// `orc lane calls <lane>` / `--all` — the catalogue, rendered.
//
// `--json is not a summary`: the human branch prints the same fields, so a
// panel can never be less detailed than the terminal.
function laneCallsCmd(lane, claudeDir) {
  const all = flag("--all") === true;
  if (!lane && !all) {
    console.error("Usage: orc lane calls <lane> [--json]   |   orc lane calls --all [--json]");
    return 2;
  }
  let entries = Object.entries(LANE_CALLS);
  if (!all) {
    if (!LANES.some((l) => l.lane === lane)) {
      console.error(`Unknown lane: ${lane}\n(orc lane list)`);
      return 2;
    }
    entries = entries.filter(([, c]) => c.lanes.includes(lane));
  }
  const rows = entries.map(([id, c]) => ({
    id,
    cmd: c.cmd,
    what: c.what,
    exits: c.exits,
    states: c.states || null,
    cost: c.cost,
    when: c.when,
    on_absent: c.on_absent,
    never: c.never,
    canonical: c.canonical || null,
    lanes: c.lanes,
  }));
  if (wantsJson()) {
    emitJson({ ok: true, lane: all ? null : lane, all, count: rows.length, calls: rows });
    return 0;
  }
  console.log(`\nORC calls  ${all ? ui.color.bold("(the whole catalogue)") : ui.color.bold(lane)}\n`);
  if (!rows.length) {
    // An empty answer is an ANSWER (v0.43.0). This lane makes no CATALOGUED
    // call, which is not the same as making none: a call only this lane makes
    // belongs to that lane and is deliberately not in the catalogue.
    console.log(
      ui.color.gray(
        "  No catalogued call. A call only this lane makes belongs to this lane\n" +
          "  and is not catalogued; the catalogue holds what two or more lanes share.\n"
      )
    );
    return 0;
  }
  for (const r of rows) {
    console.log("  " + ui.color.cyan(r.cmd));
    console.log("    " + ui.color.gray(r.what));
    console.log(
      "    exit  " +
        Object.entries(r.exits)
          .map(([code, meaning]) => `${code} = ${meaning}`)
          .join("  ·  ")
    );
    if (r.states) console.log("    states  " + r.states.join(" · "));
    console.log(`    cost  ${r.cost}    when  ${r.when}`);
    console.log("    empty answer  " + ui.color.gray(r.on_absent));
    console.log("    " + ui.color.yellow("never  ") + ui.color.gray(r.never));
    if (r.canonical) console.log("    canonical  " + ui.color.gray(r.canonical));
    console.log("");
  }
  console.log(
    ui.color.gray(
      `  ${rows.length} call${rows.length === 1 ? "" : "s"}. The CLI's state words are the only state words —\n` +
        "  never invent a spelling, re-word an exit code, or re-derive a state.\n"
    )
  );
  return 0;
}

// ── The phase library manifest (v1.0.0 W11 · design-02) ────────────────────
//
// The shared phase material already existed and was already shared — it just
// lived in ONE lane's private folder, and 26 other lanes reached across into
// \`orc/references/\` to read it. \`templates/skills/_shared/phases/\` is now its
// home, and THIS TABLE is the pipeline: the CLI owns the phase list and its
// order, exactly like \`DIY_STEPS\`. A skill never derives either from the
// filenames — a second idea of the pipeline is the drift this exists to make
// impossible (the Flow-stepper rule).
//
// Per phase: \`file\` + \`layers\` (never a line number — /orc-doc rule 2, a
// stored line number is a wrong line number one edit later), \`when\` and
// \`read\` (the partial-read declarations registered in \`_shared/read-ladder.md\`
// at W10), \`optional_when\` (a config KEY, resolved through the priority ladder
// by \`orc lane config\`, never read raw), and \`calls\` — catalogue ids from
// \`LANE_CALLS\`, DERIVED rather than restated, so a lane can ask for one
// phase's calls instead of its whole catalogue.
//
// SCOPE, stated so the shape is not mistaken for a claim: W11 moved the three
// MECHANICAL phases. A lane's own pipeline (orc's Phases 0–8, /orc-doc's
// D0–D9, /orc-challenge's C0–C8) is still declared in that lane's spine, and
// \`own_phases\` says so with \`in-spine\` rather than pretending an empty array
// is the answer. W12 moves the build spine; W14 the rest.
