const DOC_TYPES = DOC_TEMPLATES.map((t) => t.type);
const docTemplate = (type) => DOC_TEMPLATES.find((t) => t.type === String(type || "").toLowerCase());

function docPaths(claudeDir, slug) {
  const root = repoRootOf(claudeDir);
  let rel = DOC_DIR_DEFAULT;
  try {
    rel = resolvedConfig(claudeDir).doc_dir || DOC_DIR_DEFAULT;
  } catch (_) {}
  const dir = path.isAbsolute(rel) ? rel : path.join(root, ...String(rel).split(/[\\/]/).filter(Boolean));
  const folder = slug ? path.join(dir, slug) : null;
  return {
    root,
    rel: String(rel).replace(/\\/g, "/"),
    dir,
    folder,
    state: folder ? path.join(folder, DOC_STATE_FILE) : null,
    document: folder ? path.join(folder, DOC_FILE) : null,
    outline: folder ? path.join(folder, DOC_OUTLINE_FILE) : null,
    work: folder ? path.join(folder, DOC_WORK) : null,
    // v0.49.0 — the real, visible, diffable source of truth.
    sections: folder ? path.join(folder, DOC_SECTIONS) : null,
    front: folder ? path.join(folder, DOC_SECTIONS, DOC_FRONT_FILE) : null,
    gaps: folder ? path.join(folder, DOC_GAPS_FILE) : null,
  };
}

// Where RESUME.md actually lives (v0.49.0). The registered v0.42.0 home, and
// the ONLY place `listRuns()` looks — which is why a document paused by a usage
// limit never appeared in `orc run list` and `orc resume` could not find it.
function docRunDir(claudeDir, slug) {
  try {
    return path.join(resolveRunDir(claudeDir), slug);
  } catch (_) {
    return null;
  }
}

const docRelFolder = (p, abs) => path.relative(p.folder, abs).split(path.sep).join("/");

function docRead(claudeDir, slug) {
  const p = docPaths(claudeDir, slug);
  if (!p.state || !fs.existsSync(p.state)) return null;
  try {
    const d = JSON.parse(fs.readFileSync(p.state, "utf8"));
    d.outline = Array.isArray(d.outline) ? d.outline : [];
    d.sections = d.sections || {};
    d.extracts = d.extracts || {};
    d.cycles = Array.isArray(d.cycles) ? d.cycles : [];
    // BOTH versions are accepted. A v1 document in flight must open, migrate and
    // continue without the user knowing anything happened.
    d.version = Number(d.version) || 1;
    d.migrations = Array.isArray(d.migrations) ? d.migrations : [];
    // v0.49.2. A document created before house rules existed has none, and that
    // is an ANSWER, not a gap: it was written against no house rules, which is
    // exactly what an empty frozen set means.
    // v0.49.5 — a v0.49.2 document froze an ARRAY of rows; this one freezes
    // the three text BLOCKS. Both open, and the older shape migrates on read.
    d.doc_rules = docRulesBlocksOf(d.doc_rules);
    d.doc_rule_syncs = Array.isArray(d.doc_rule_syncs) ? d.doc_rule_syncs : [];
    return d;
  } catch (_) {
    return null;
  }
}

// doc.json HAS EXACTLY ONE WRITER — this function, reached only from an
// `orc doc` subcommand. A model never edits it, and never invents a line number.
function docWrite(claudeDir, slug, d) {
  const p = docPaths(claudeDir, slug);
  fs.mkdirSync(p.folder, { recursive: true });
  d.version = Number(d.version) || 1;
  d.updated_at = fmtStamp(new Date());
  fs.writeFileSync(p.state, JSON.stringify(d, null, 2) + "\n");
  // v0.49.5 - RESUME.md IS REWRITTEN HERE, on every state change, by the CLI.
  // It used to be prose the orchestrator was told to write at every stop, and
  // "the orchestrator remembers to do X at every stop" is exactly the bet this
  // repo has already lost twice (the v0.32.0 narration lesson). doc.json has one
  // writer, so hooking the hand-back to it makes "there is always a RESUME.md,
  // and it is always current" structurally true instead of remembered.
  //
  // It is still written by ORC ITSELF and never by a dispatched agent - an `orc
  // doc` call is the lane's own hand, not a subagent's - so rule 13 holds.
  docResumeRefresh(claudeDir, slug);
  return p.state;
}

// The re-entrancy guard: docMapView(persist) and docResumeBuild both reach
// docWrite, and a hand-back that rewrote itself forever would be a hang.
let docResumeBusy = false;
function docResumeRefresh(claudeDir, slug) {
  if (docResumeBusy) return null;
  docResumeBusy = true;
  try {
    const dir = docRunDir(claudeDir, slug);
    if (!dir) return null;
    // A CLOSED run is a human saying they are finished with it (v0.49.2). Never
    // re-open it behind their back by putting the pointer back.
    if (fs.existsSync(path.join(dir, RUN_CLOSED_FILE))) return null;
    const built = docResumeBuild(claudeDir, slug);
    if (!built) return null;
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, RESUME_FILE);
    fs.writeFileSync(file, built.text);
    return file;
  } catch (_) {
    // Best effort, always. A hand-back that cannot be written must never take
    // the command that triggered it down with it.
    return null;
  } finally {
    docResumeBusy = false;
  }
}

function docList(claudeDir) {
  const p = docPaths(claudeDir);
  if (!fs.existsSync(p.dir)) return [];
  return fs
    .readdirSync(p.dir, { withFileTypes: true })
    .filter((e) => e.isDirectory() && fs.existsSync(path.join(p.dir, e.name, DOC_STATE_FILE)))
    .map((e) => e.name)
    .sort();
}

const docLines = (text) => String(text).replace(/\r\n/g, "\n").split("\n");
const docHash = (s) => sha256(String(s).replace(/\r\n/g, "\n").replace(/\s+$/, ""));

// The heading id: ordinal + the slugified heading. Stable across every rewrite
// of the BODY, which is what a re-check needs; an INSERTED section renumbers its
// followers, which is what the rename repair below is for.
const docSectionId = (n, heading) => `${two(n)}-${docSlugify(heading).slice(0, 40) || "section"}`;

// ── the section FILES — one file per thing, and ONE resolver (v0.49.0) ───────
// `docSectionSource` is the single answer to "what is this section's source?".
// Compile, `parts`, the staleness check, `extract` and the check-dispatch ALL
// call it. A second idea of what a section's source is would be exactly the
// drift this lane exists to prevent.

const docSectionFile = (p, id) => path.join(p.sections, id + ".md");
const docSectionDir = (p, id) => path.join(p.sections, id);

// Strip the template's purpose comments (instructions for the writer, never
// content), drop leading blanks, drop trailing whitespace. Blank-line
// normalisation happens ONCE, at the very end of a compile, so a nested join is
// never normalised twice.
function docTrimPart(text) {
  return docLines(text)
    .filter((l) => !/^\s*<!--\s*purpose:/i.test(l))
    .join("\n")
    .replace(/^\s*\n+/, "")
    .replace(/\s*$/, "");
}

const docFirstLine = (text) => (docLines(text).find((l) => /\S/.test(l)) || "").trim();

function docSectionSource(p, o) {
  const out = { id: o.id, files: [], parts: [], text: null, nested: false, problems: [] };
  if (!p.sections) return out;
  const flat = docSectionFile(p, o.id);
  if (fs.existsSync(flat) && fs.statSync(flat).isFile()) {
    const raw = fs.readFileSync(flat, "utf8");
    const rel = docRelFolder(p, flat);
    out.files.push(rel);
    out.parts.push({ sub: null, file: rel, hash: docHash(raw), lines: docLines(raw).length, text: raw });
    out.text = docTrimPart(raw);
    return out;
  }
  const dir = docSectionDir(p, o.id);
  if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) return out;
  out.nested = true;
  // ORDER IS `outline[i].subsections[]` — never `readdir`, never the filename
  // number. Decision 4, one level down.
  const seq = [];
  const head = path.join(dir, DOC_HEAD_FILE);
  if (fs.existsSync(head)) seq.push({ sub: DOC_HEAD_FILE.replace(/\.md$/, ""), file: head, head: true });
  for (const s of o.subsections || []) {
    const f = path.join(dir, s.id + ".md");
    if (fs.existsSync(f)) seq.push({ sub: s.id, file: f, head: false, heading: s.heading });
  }
  if (!seq.length) return out;
  const chunks = [];
  for (const it of seq) {
    const raw = fs.readFileSync(it.file, "utf8");
    const body = docTrimPart(raw);
    const rel = docRelFolder(p, it.file);
    const first = docFirstLine(body);
    // Every rule here is a REFUSE-AND-NAME, never a silent fix. Demoting a `##`
    // to `###` would restructure the deliverable; promoting it would split one
    // section into two. Neither is ours to choose.
    if (!it.head) {
      if (/^##\s/.test(first))
        out.problems.push({ rule: "subpart-h2", file: rel, what: `${rel} starts with a \`## \` heading. A sub-part is part of ONE section — demoting it would restructure the document and promoting it would split the section in two. Neither is this lane's to choose.` });
      else if (!/^#{3,6}\s/.test(first))
        out.problems.push({ rule: "subpart-bad-level", file: rel, what: `${rel} does not start at \`### \` or deeper. A sub-part carries its own sub-heading; without one the compile cannot tell where it begins.` });
    }
    out.files.push(rel);
    out.parts.push({ sub: it.sub, file: rel, hash: docHash(raw), lines: docLines(raw).length, text: raw });
    chunks.push(body);
  }
  out.text = chunks.join("\n\n");
  return out;
}

// Exactly one `## ` per section: `00-head.md` carries it, and when that file is
// absent the compile emits the outline's own heading. Never twice, never none.
function docSectionBody(o, src) {
  let body = src.text || "";
  if (!/^##\s/.test(docFirstLine(body))) body = `## ${o.heading}\n\n` + body;
  return body.replace(/\s*$/, "");
}

// `state` is COMPUTED from the disk every time, never stored as a claim.
//   planned      no source file at all
//   unconfirmed  a file exists but no VALIDATED RETURN ever recorded its hash —
//                exactly what a writer killed by a usage limit leaves behind
//   user-edited  the recorded hash no longer matches the file
//   checked      a check cycle confirmed it and it has not moved since
//   written      confirmed, not yet checked
function docPartState(rec, exists, hash) {
  if (!exists) return "planned";
  if (!rec || !rec.source_hash) return "unconfirmed";
  if (rec.source_hash !== hash) return "user-edited";
  return rec.state === "checked" ? "checked" : "written";
}

// The `sections/` view — and it works BEFORE a single compile has ever run,
// which is the whole reason a resumed session no longer needs `document.md`.
function docPartsView(claudeDir, slug) {
  const d = docRead(claudeDir, slug);
  if (!d) return null;
  const p = docPaths(claudeDir, slug);
  const rows = (d.outline || []).map((o, i) => {
    const src = docSectionSource(p, o);
    const rec = d.sections[o.id] || {};
    const exists = !!src.text;
    const hash = exists ? docHash(src.text) : null;
    return {
      id: o.id,
      heading: o.heading,
      required: o.required !== false,
      purpose: o.purpose || null,
      files: src.files,
      nested: src.nested,
      exists,
      lines: exists ? docLines(src.text).length : 0,
      hash,
      state: docPartState(rec, exists, hash),
      findings: rec.findings || 0,
      cycle: rec.cycle || null,
      subsections: (o.subsections || []).map((s) => {
        const part = src.parts.find((x) => x.sub === s.id);
        const known = (rec.parts || {})[s.id];
        return {
          id: s.id,
          heading: s.heading,
          file: part ? part.file : null,
          exists: !!part,
          lines: part ? part.lines : 0,
          hash: part ? part.hash : null,
          changed: !!(part && known && known !== part.hash),
        };
      }),
      // The NUMBER is a mirror of the outline index, kept in sync by the CLI.
      // Order is always the outline — the number is never what decides it.
      ordinal_ok: o.id === docSectionId(i + 1, o.heading),
      problems: src.problems,
    };
  });
  const front = p.front && fs.existsSync(p.front) ? docRelFolder(p, p.front) : null;
  return { d, paths: p, rows, front };
}

// `K of N` is DERIVED by counting waves whose sections are ALL hash-confirmed —
// never a number a model claims. Same discipline as every other state here.
function docWaveState(d, rows) {
  const waves = ((d.plan || {}).waves || []).filter(Array.isArray);
  if (!waves.length) return null;
  const done = new Set(rows.filter((r) => r.state === "written" || r.state === "checked").map((r) => r.id));
  let k = 0;
  for (const w of waves) {
    if (!w.length || !w.every((id) => done.has(id))) break;
    k++;
  }
  return { done: k, total: waves.length, role: (d.plan || {}).role || "write" };
}

// `document.md` is stale ⇔ some section's assembled source hashes differently
// today than `compiled.source_hashes` recorded. Pure disk comparison, no stored
// status word, and COVERAGE-RELATIVE — the `computeWikiFreshness` /
// `shipped-drifted` rule applied to a build artifact.
function docDocStale(view) {
  const d = view.d;
  const c = d.compiled;
  if (!c || !c.source_hashes) return null;
  const then = c.source_hashes;
  const out = [];
  for (const r of view.rows) {
    if (!r.exists) {
      if (then[r.id]) out.push({ id: r.id, heading: r.heading, reason: "gone" });
      continue;
    }
    if (!then[r.id]) out.push({ id: r.id, heading: r.heading, reason: "added" });
    else if (then[r.id] !== r.hash) out.push({ id: r.id, heading: r.heading, reason: "changed" });
  }
  return out;
}

// ORC's own markers, found in a body that is supposed to carry content only.
// REPORTED, never silently stripped: rule 4 outranks tidiness, because we cannot
// tell whose line it is.
function docAnnotations(text) {
  const out = [];
  docLines(text).forEach((l, i) => {
    if (DOC_ANNOTATION_RE.test(l)) out.push({ line: i + 1, quote: l.trim().slice(0, 160) });
  });
  return out;
}

// ── the section map — DERIVED, NEVER STORED (§5.2) ──────────────────────────
// Because it is re-derived after every single write, no line number in this
// system is ever stale. That is the entire reason range-based reading is safe.
function docScan(text) {
  const lines = docLines(text);
  const heads = [];
  let fence = false;
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*(```|~~~)/.test(lines[i])) {
      fence = !fence;
      continue;
    }
    if (fence) continue;
    const m = lines[i].match(/^(#{1,6})\s+(.+?)\s*$/);
    if (m) heads.push({ line: i + 1, level: m[1].length, heading: m[2].replace(/[*_`]/g, "").trim() });
  }
  const h2 = heads.filter((h) => h.level === 2);
  const sections = h2.map((h, i) => {
    const start = h.line;
    const end = i + 1 < h2.length ? h2[i + 1].line - 1 : lines.length;
    const body = lines.slice(start - 1, end).join("\n");
    return {
      id: docSectionId(i + 1, h.heading),
      ordinal: i + 1,
      heading: h.heading,
      level: 2,
      start,
      end,
      lines: end - start + 1,
      hash: docHash(body),
      text: body,
    };
  });
  return {
    total_lines: lines.length,
    preamble_end: h2.length ? h2[0].line - 1 : lines.length,
    headings: heads,
    sections,
  };
}

// A heading whose TEXT changed but whose position and neighbours match is the
// SAME section with a new id — repaired, never lost. A heading that appears with
// no such match is new. Without this, one typo in a heading throws away that
// section's whole history.
// A SECTION'S IDENTITY COMES FROM THE OUTLINE, NEVER FROM ITS POSITION IN THE
// FILE. `docScan` can only number what it sees, and a skipped optional section
// shifts every ordinal after it — so a purely positional id would rename half
// the document the first time somebody dropped a section nobody asked for.
//
// Two passes, in this order:
//   1. exact heading match, consumed in document order — the normal case;
//   2. RENAME REPAIR for what is left: an unmatched section sitting between two
//      matched neighbours takes the one unconsumed outline entry between them.
//      A heading whose text changed but whose position and neighbours match is
//      the SAME section with a new name. Anything still unmatched is genuinely
//      new and keeps its positional id.
function docReconcile(d, scan) {
  const outline = d.outline || [];
  const bySlug = new Map();
  outline.forEach((o, i) => {
    const k = docSlugify(o.heading);
    if (!bySlug.has(k)) bySlug.set(k, []);
    bySlug.get(k).push(i);
  });
  const used = new Set();
  const sections = scan.sections.map((s) => ({ ...s, outline_index: null }));

  for (const s of sections) {
    const cands = bySlug.get(docSlugify(s.heading)) || [];
    const hit = cands.find((i) => !used.has(i));
    if (hit === undefined) continue;
    used.add(hit);
    s.outline_index = hit;
    s.id = outline[hit].id;
  }

  const repairs = [];
  const nextMatched = (from) => {
    for (let j = from; j < sections.length; j++) if (sections[j].outline_index !== null) return sections[j].outline_index;
    return outline.length;
  };
  for (let k = 0; k < sections.length; k++) {
    const s = sections[k];
    if (s.outline_index !== null) continue;
    const prev = k > 0 && sections[k - 1].outline_index !== null ? sections[k - 1].outline_index : -1;
    const next = nextMatched(k + 1);
    const gap = [];
    for (let i = prev + 1; i < next; i++) if (!used.has(i)) gap.push(i);
    // Exactly one candidate, or it is ambiguous and nothing is repaired: a
    // guessed identity is worse than a lost one, because it silently attaches a
    // section's whole history to the wrong text.
    if (gap.length !== 1) continue;
    const i = gap[0];
    used.add(i);
    s.outline_index = i;
    const from = outline[i].id;
    // The new id is built from the OUTLINE slot, so ids stay in outline order
    // even when the file's own ordinals do not.
    s.id = docSectionId(i + 1, s.heading);
    repairs.push({ from, to: s.id, heading: s.heading, index: i });
  }
  return { sections, repairs };
}

function docApplyRepairs(d, repairs) {
  for (const r of repairs) {
    const rec = d.sections[r.from];
    if (rec) {
      d.sections[r.to] = { ...rec, renamed_from: r.from };
      delete d.sections[r.from];
    }
    const o = (d.outline || [])[r.index] || (d.outline || []).find((x) => x.id === r.from);
    if (o) {
      o.id = r.to;
      o.heading = r.heading;
    }
    if (d.extracts && d.extracts[r.from]) {
      d.extracts[r.to] = d.extracts[r.from];
      delete d.extracts[r.from];
    }
  }
  return repairs.length;
}

// `state` is COMPUTED by comparing the live hash to the one doc.json recorded at
// the end of the last cycle — never stored as a claim. A stored status is a
// status that lies the moment somebody saves a file.
function docStateOfSection(rec, live, version) {
  if (!live) return "planned";
  // v1 ONLY. In v2 the deliverable carries content only, so nothing ever writes
  // a `> **Open:**` stub into the body and there is nothing to sniff for. A text
  // match was always strictly less reliable than the hash it sat beside.
  if ((Number(version) || 1) < 2 && /^\s*>\s*\*\*Open:/m.test(live.text) && live.lines <= 6) return "open";
  if (!rec || !rec.hash) return "written";
  if (rec.hash !== live.hash) return "user-edited";
  return DOC_STATES.includes(rec.state) && rec.state !== "planned" ? rec.state : "written";
}

function docMapView(claudeDir, slug, { persist = false } = {}) {
  const d = docRead(claudeDir, slug);
  if (!d) return null;
  const p = docPaths(claudeDir, slug);
  // `parts_only` lets a caller tell "not compiled yet" from "empty document" —
  // in v2 those are completely different situations and both are normal.
  if (!fs.existsSync(p.document))
    return { d, paths: p, document: null, sections: [], total_lines: 0, repairs: [], parts_only: true };
  const text = fs.readFileSync(p.document, "utf8");
  const scan = docScan(text);
  const { sections: resolved, repairs } = docReconcile(d, scan);
  // The repair is the ONE thing map writes, and it is a repair, not a claim:
  // without it the identity of a section a human renamed is lost forever, and
  // nothing else in this system ever runs after a hand edit.
  if (persist && repairs.length) {
    docApplyRepairs(d, repairs);
    docWrite(claudeDir, slug, d);
  }
  // The scan is re-keyed to the outline's ids, so `scan.sections` and the view
  // agree — `extract` reads the text off one and the hash off the other.
  scan.sections = resolved;
  const outline = d.outline || [];
  const sections = resolved.map((s) => {
    const rec = d.sections[s.id];
    const o = s.outline_index === null ? null : outline[s.outline_index];
    return {
      id: s.id,
      heading: s.heading,
      level: s.level,
      start: s.start,
      end: s.end,
      lines: s.lines,
      hash: s.hash,
      state: docStateOfSection(rec, s, d.version),
      required: o ? !!o.required : true,
      purpose: o ? o.purpose || null : null,
      findings: rec && rec.findings ? rec.findings : 0,
      cycle: rec && rec.cycle ? rec.cycle : null,
      renamed_from: (rec && rec.renamed_from) || null,
    };
  });
  return {
    d,
    paths: p,
    document: p.document,
    total_lines: scan.total_lines,
    preamble_end: scan.preamble_end,
    sections,
    scan,
    repairs,
  };
}

// The one status line every listing parses, so a listing never has to open
// doc.json. Same shape as the run trio's `Where it stands:` line.
function docWhereLine(d, view, extra) {
  const e = extra || {};
  // In v2 the SECTION FILES are the progress, so `written` is counted from them
  // when the caller has them — the count no longer waits for a compile.
  const written = Array.isArray(e.rows)
    ? e.rows.filter((r) => r.state === "written" || r.state === "checked").length
    : view
      ? view.sections.filter((s) => s.state !== "planned" && s.state !== "open").length
      : 0;
  const total = (d.outline || []).length || (view ? view.sections.length : 0);
  // The PREFIX is byte-stable — `orc doc list` parses it, which is how a listing
  // never has to open doc.json. v0.48.1 appends a SUFFIX and never touches the
  // rest; v0.49.0 appends one more, so `orc run list` finally shows phase AND
  // wave. `parseStands` splits on `·` and matches positionally-free.
  const base = `Where it stands:  /orc-doc · ${String(d.type || "").toUpperCase()} · cycle ${d.cycle || 0} · ${written} of ${total} sections written`;
  let line = base;
  if (d && d.shipped) {
    const drift = view ? docShipDrift(d, view) : null;
    line +=
      ` · shipped ${d.shipped.at.split(" ")[0]} → ${d.shipped.where}` +
      (drift && drift.length ? ` (drifted: ${plural(drift.length, "section")})` : "");
  }
  if (e.phase) line += ` · phase ${e.phase}`;
  if (e.wave) line += ` · wave ${e.wave.done} of ${e.wave.total}`;
  return line;
}

// ── the free check (§4.4 + §7) ──────────────────────────────────────────────
// Two honesty rules, printed by the command itself:
//   1. A readability signal is a SIGNAL, not a verdict. It never blocks.
//   2. It is English-specific and heuristic — passive detection is a pattern
//      match and a syllable count is an estimate. Say so, once, on the output.
// Its real payoff: the findings ride in the checker's slice, so a model never
// spends a token counting sentences.
const DOC_SENTENCE_MAX = 35;
const DOC_SENTENCE_AVG_MAX = 20;
const DOC_HARDWRAP_MIN = 60;


// ── §B — THE PRE-DETERMINED GENERATION RULES (v0.49.2) ──────────────────────
// ORC's own, read AFTER the house rules, shipped enabled, applied to every
// document. All four are FREE and deterministic — rule 6 (the free check runs
// before the paid one) is what makes them worth having at all: no model is ever
// paid to notice a `TODO`.
//
// Every one is NARROW on purpose. A broad rule that argues with the author gets
// switched off; a narrow rule that is always right gets used. That is the same
// reasoning that keeps `DOC_ANNOTATION_RE` to an exact set.

// B.1 — no questions, confirmations, or non-document explanation in the body.
// It matches ORC-shaped or APPROVAL-shaped markers, never "is this a question
// mark": a document may legitimately ask its reader a rhetorical question.
const DOC_CONFIRM_MARKERS = [
  "to be confirmed", "to be decided", "please confirm", "needs confirmation",
  "we need to decide", "pending confirmation",
];
// Short markers need a WORD BOUNDARY. A three-letter substring match would flag
// a word that happens to contain it, and a rule that is wrong once is a rule
// people switch off. `(?)` is punctuation, so it is matched literally.
const DOC_CONFIRM_TOKENS = [
  [/\bTBA\b/, "TBA"],
  [/\bTBD\b/, "TBD"],
  [/\bTODO\b/, "TODO"],
  [/\bFIXME\b/, "FIXME"],
  [/\bXXX\b/, "XXX"],
  [/\?{3}/, "???"],
  [/\(\?\)/, "(?)"],
];
// A line that is ONLY a question put to the reader as an APPROVER.
const DOC_APPROVAL_RE = /^\s*(?:Should|Do|Can|Would|Could)\s+we\b.*\?\s*$/;
// A heading that DECLARES a questions section. A template that says it has open
// questions is allowed to have open questions.
const DOC_QUESTION_SECTION_RE = /open questions|questions|risks|assumptions/i;

// B.4 — no local-only references. The document is for a reader who has no
// repository, no checkout and no shell.
const DOC_LOCAL_REF_RULES = [
  [/(?:^|[\s(\[])[\w./-]+\.[A-Za-z]{1,4}:\d+\b/, "a file:line anchor — the reader has no repository to open it in"],
  [/(?:^|[\s(\["'])[A-Za-z]:[\\/][^\s)"']+/, "an absolute Windows path — it exists only on one machine"],
  [/(?:^|[\s(\["'])\/(?:Users|home|mnt|var|opt|etc)\/[^\s)"']+/, "an absolute path — it exists only on one machine"],
  [/(?:^|[\s(\["'])\.\.?\/[^\s)"']+/, "a relative path — it means nothing without the folder it is relative to"],
  [/\b(?:localhost|127\.0\.0\.1|0\.0\.0\.0)\b/, "a localhost address — nobody reading this can reach it"],
  [/\bfile:\/\/\S+/, "a file:// URL — it resolves only on the machine that wrote it"],
  [/(?:^|[\s(\["'])(?:src|bin|lib|app|test|tests|pkg|internal)\/[\w./-]+\.[A-Za-z]{1,4}\b/, "a repository path — the reader has no checkout"],
  [/\[[^\]]+\]\((?!https?:|mailto:|#)[^)]+\.(?:md|txt)\)/, "a link to a local file — it breaks the moment the document is imported"],
];

// Which OUTLINE section a line falls in, so a rule can be exempted per section
// without the lint ever being told the outline. Derived from the file's own
// headings, which is all `docScan` already gives us.
function docSectionAt(scan, line) {
  let cur = null;
  for (const h of scan.sections) {
    if (h.start <= line) cur = h;
    else break;
  }
  return cur;
}

// ONE place builds the lint's options, so `lint`, `compile`, `status`, `ship`,
// `audit` and `next` can never disagree about which rules were in force.
// The budgets come from the OUTLINE, which is the only thing that knows what a
// section was planned to be — the lint itself is never told the outline.
// The template cage, read in ONE place. `locked` is only ever true for a USER
// template — a shipped base template is a floor, not a cage.
function docLock(d) {
  const t = (d && d.template) || {};
  return {
    locked: !!t.locked,
    path: t.path || null,
    hash: t.hash || null,
    source: t.source || "shipped",
    // The headings the template declared. A document whose outline was later
    // edited on purpose keeps the ORIGINAL list — the cage is the template, not
    // whatever the outline drifted into.
    headings: Array.isArray(t.headings) ? t.headings : [],
  };
}

function docLintOpts(claudeDir, d) {
  let localRefs = "error";
  try {
    localRefs = resolvedConfig(claudeDir).doc_local_refs || "error";
  } catch (_) {}
  const budgets = {};
  for (const o of (d && d.outline) || []) if (o.budget_lines) budgets[o.id] = o.budget_lines;
  const lock = docLock(d);
  // A subsection the outline DECLARES is allowed too — sub-parts split
  // underneath a section and are invisible to the reader, so they were never
  // headings the template had to know about.
  const subs = [];
  for (const o of (d && d.outline) || []) for (const s of o.subsections || []) subs.push(s.heading);
  return {
    local_refs: localRefs,
    budgets,
    template_locked: lock.locked,
    allowed_headings: lock.locked ? lock.headings.concat(subs) : null,
  };
}

function docLintRun(text, targetId, opts) {
  const tgt = docTarget(targetId);
  const o = opts || {};
  // `off | warn | error` (config `doc_local_refs`). A rule with no switch gets
  // fought instead of used, and a genuinely internal runbook legitimately names
  // local paths.
  const localRefs = ["off", "warn", "error"].includes(o.local_refs) ? o.local_refs : "error";
  // The outline's own headings, when the caller has them, so `open questions`
  // can be exempted by NAME rather than by the file's ordinal.
  const lines = docLines(text);
  const findings = [];
  let seq = 0;
  const add = (severity, rule, line, what, quote) =>
    findings.push({
      id: "D-" + String(++seq).padStart(3, "0"),
      severity, // "error" blocks the handoff; "warn" is advisory
      rule,
      line,
      what,
      quote: quote ? String(quote).slice(0, 160) : null,
    });

  // front matter, first — every rule below counts lines from the same file
  const hasFront = /^---\s*$/.test(lines[0] || "");
  let frontEnd = 0;
  if (hasFront) {
    for (let i = 1; i < lines.length; i++)
      if (/^---\s*$/.test(lines[i])) {
        frontEnd = i + 1;
        break;
      }
  }
  // v0.49.2 — a PART is not a document. Front matter and the single H1 belong to
  // the whole file; a section file has neither by design, and reporting them on
  // every part would bury the findings a revision round can act on.
  const wholeDoc = !o.part;
  if (wholeDoc && tgt.front_matter === "require" && !hasFront)
    add("error", "front-matter-required", 1, `--target ${tgt.id} requires YAML front matter, and will not render the page without it`);
  if (wholeDoc && tgt.front_matter === "ban" && hasFront)
    add("error", "front-matter-banned", 1, `--target ${tgt.id} renders YAML front matter as visible junk at the top of the page`);

  const scan = docScan(text);
  const h1 = scan.headings.filter((h) => h.level === 1);
  if (wholeDoc && h1.length === 0) add("error", "no-h1", 1, "no H1 — every importer's outline builder starts from one");
  if (h1.length > 1)
    for (const h of h1.slice(1)) add("error", "many-h1", h.line, `a second H1: "${h.heading}". Exactly one is the title`);
  if (!wholeDoc && h1.length)
    for (const h of h1) add("error", "many-h1", h.line, `an H1 inside a section file: "${h.heading}". The H1 is the document's title and lives in the front matter file`);
  let prev = 0;
  for (const h of scan.headings) {
    if (prev && h.level > prev + 1)
      add("error", "skipped-level", h.line, `heading jumps from H${prev} to H${h.level} — the outline builder loses the branch`);
    prev = h.level;
    if (h.level > tgt.max_heading)
      add("error", "heading-too-deep", h.line, `H${h.level} is deeper than ${tgt.label} supports (max H${tgt.max_heading}) — it degrades to bold text`, h.heading);
    if (/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u.test(h.heading))
      add("warn", "emoji-heading", h.line, "an emoji in a heading — some importers slug headings and mangle the anchor", h.heading);
    // v0.49.2 — TEMPLATE LOCK. Only under a lock, only H2 and deeper (the H1 is
    // the title), and only against the headings the template itself declared.
    if (o.template_locked && h.level >= 2 && !(o.allowed_headings || []).includes(h.heading))
      add(
        "error",
        "heading-outside-template",
        h.line,
        `"${h.heading}" is not a heading this document's template has. A supplied template is a cage: what does not fit is a gap, not a new section`,
        h.heading
      );
  }

  // Setext headings survive nothing, and an underline that looks like a rule is
  // a heading the outline builder never sees.
  for (let i = 1; i < lines.length; i++)
    if (/^(=+|-{3,})\s*$/.test(lines[i]) && /\S/.test(lines[i - 1]) && !/^\s*[|>#-]/.test(lines[i - 1]) && i > frontEnd)
      add("error", "setext-heading", i + 1, "a setext (underlined) heading — use ATX (`##`) so every importer sees it", lines[i - 1]);

  let fence = false;
  let fenceLang = true;
  let tableCols = 0;
  let prevProse = null;
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1;
    const l = lines[i];
    if (n <= frontEnd) continue;

    const fm = l.match(/^\s*(```|~~~)(\s*[A-Za-z0-9_+-]*)/);
    if (fm) {
      if (!fence) {
        fence = true;
        fenceLang = !!(fm[2] || "").trim();
        if (fm[1] === "~~~") add("error", "tilde-fence", n, "a `~~~` fence — only ``` fences convert reliably");
        else if (!fenceLang) add("warn", "fence-no-language", n, "a code fence with no language tag");
      } else fence = false;
      prevProse = null;
      continue;
    }
    if (fence) continue;

    if (/^\s{4,}\S/.test(l) && !/^\s*[-*+\d]/.test(l) && !/^\s*\|/.test(l))
      add("warn", "indented-code", n, "an indented code block — it converts unreliably; use a ``` fence");

    if (/<!--/.test(l)) add("error", "html-comment", n, "an HTML comment — some importers render it as literal text", l.trim());
    if (/<(table|div|span|br|img|p|b|i|u|font|sup|sub)\b[^>]*>/i.test(l))
      add("error", "raw-html", n, "raw HTML — it survives almost no import path", l.trim());

    if (/\[\[[^\]]+\]\]/.test(l)) add("error", "wikilink", n, "a [[wikilink]] — Obsidian-only syntax", l.trim());
    if (/\[\^[^\]]+\]/.test(l)) add("error", "footnote", n, "a footnote — Pandoc-only syntax", l.trim());
    if (/^:\s+\S/.test(l) && /\S/.test(lines[i - 1] || "")) add("warn", "definition-list", n, "a definition list — Pandoc-only syntax", l.trim());

    for (const m of l.matchAll(/!\[([^\]]*)\]\(([^)]+)\)/g)) {
      if (!m[1].trim()) add("error", "image-no-alt", n, "an image with no alt text — the alt text is what survives an import", m[0]);
      const near = (lines[i + 1] || "") + (lines[i - 1] || "");
      if (!/\S/.test(near))
        add("warn", "image-no-description", n, "an image with no one-line text description beside it — images do not travel through most imports", m[0]);
    }

    if (/^\s*\|/.test(l)) {
      const cells = l.trim().replace(/^\||\|$/g, "").split("|").length;
      if (/^\s*\|[\s:|-]+\|?\s*$/.test(l)) {
        // the delimiter row — it defines the column count
      } else if (!tableCols) tableCols = cells;
      else if (cells !== tableCols)
        add("warn", "ragged-table", n, `a table row with ${cells} cells where the header has ${tableCols} — complex tables flatten on import`, l.trim());
      prevProse = null;
      continue;
    }
    tableCols = 0;

    // THE HARD-WRAP RULE — the single most common import-mangling bug. A wrap at
    // 80 columns becomes a line break INSIDE a Notion or Docs paragraph.
    const isProse = /\S/.test(l) && !/^\s*[-*+>#|]/.test(l) && !/^\s*\d+[.)]\s/.test(l);
    if (
      isProse &&
      prevProse &&
      !prevProse.reported &&
      prevProse.text.length >= DOC_HARDWRAP_MIN &&
      !/[.:;!?]\s*$/.test(prevProse.text)
    )
      add("error", "hard-wrap", prevProse.n, "a hard-wrapped paragraph — one paragraph must be one line, or the wrap becomes a line break on import", prevProse.text);
    // ONE finding per paragraph. A five-line wrapped paragraph is one mistake,
    // and reporting it four times buries the other rules.
    prevProse = isProse ? { n, text: l.trim(), reported: !!(prevProse && (prevProse.reported || prevProse.text.length >= DOC_HARDWRAP_MIN)) } : null;

    for (const marker of LINT_MARKERS)
      if (l.includes(marker)) {
        add("warn", "placeholder", n, `leftover placeholder text: ${marker}`, l.trim());
        break;
      }

    // ── B.1 — no questions, confirmations or approval-seeking in the body ──
    // Exempt: a section whose OWN heading declares it (open questions, risks,
    // assumptions). Fenced code was already skipped by the `continue` above.
    const sec = docSectionAt(scan, n);
    const inQuestions = !!(sec && DOC_QUESTION_SECTION_RE.test(sec.heading));
    if (!inQuestions) {
      const low = l.toLowerCase();
      const phrase = DOC_CONFIRM_MARKERS.find((m) => low.includes(m));
      const token = phrase ? null : (DOC_CONFIRM_TOKENS.find(([re]) => re.test(l)) || [null, null])[1];
      if (phrase || token)
        add("error", "question-in-body", n, `"${phrase || token}" — the deliverable answers, it does not ask. Raise it as a gap instead: orc doc log --kind gap`, l.trim());
      else if (DOC_APPROVAL_RE.test(l))
        add("error", "question-in-body", n, "a question put to the reader as an approver — the deliverable answers, it does not ask. Raise it as a gap instead", l.trim());
    }

    // ── B.4 — no local-only references ────────────────────────────────────
    if (localRefs !== "off") {
      for (const [re, why] of DOC_LOCAL_REF_RULES)
        if (re.test(l)) {
          add(localRefs, "local-reference", n, why, l.trim());
          break; // one finding per line: a path and its link are one mistake
        }
    }
  }

  // ── the clean-deliverable rule (v0.49.0) ──────────────────────────────────
  // The deliverable carries CONTENT ONLY. ORC's own bookkeeping — an Open, an
  // Assumption, a note callout, an `orc-doc:` fence — belongs in `gaps.md` and
  // in the journal, not in the document the reader came for.
  //
  // It uses the SAME helper the compile reports with, so the free check and the
  // build can never disagree about what one of ORC's markers is. And the set is
  // narrow on purpose: a user's own line beginning "Note:" is content.
  for (const a of docAnnotations(text))
    add("error", "annotation-in-body", a.line, "ORC bookkeeping in the deliverable — it belongs in gaps.md, not in the document", a.quote);

  // ── B.2 — `N/A` plus one short line, never filler (v0.49.2) ───────────────
  // What you do not have is `N/A` and at most one short sentence saying what is
  // missing. Never write around a hole. A WARN, never an error: the author may
  // have a reason, and a hard rule here would be ORC arguing about content it
  // has not read.
  //
  // ── B.3 — the bloat SIGNAL, per section ───────────────────────────────────
  // Not a prose rule the model has to feel — a measurement. Under the budget is
  // correct; well over it is a finding.
  const sectionRows = [];
  for (const s of scan.sections) {
    const body = docLines(s.text).slice(1); // drop the heading itself
    const nonBlank = body.filter((x) => /\S/.test(x));
    const budget = ((o.budgets || {})[s.id] || (o.budgets || {})[s.heading] || 0) || null;
    const overPct = budget ? Math.round(((s.lines - budget) / budget) * 100) : null;
    sectionRows.push({
      id: s.id,
      heading: s.heading,
      start: s.start,
      lines: s.lines,
      words: (s.text.match(/\S+/g) || []).length,
      budget_lines: budget,
      over_budget_pct: overPct,
    });
    if (/^\s*N\/A\b/i.test(nonBlank[0] || "") && nonBlank.length > 4)
      add(
        "warn",
        "na-padded",
        s.start,
        `"${s.heading}" opens with N/A and then runs ${nonBlank.length} more lines — what you do not have is N/A plus one short line, never filler`,
        (nonBlank[0] || "").trim()
      );
    // 1.5x is the bar: a section a little over budget is a judgement call, and a
    // section half again as long as it was planned to be is a fact.
    if (budget && s.lines > budget * 1.5)
      add(
        "warn",
        "over-budget-section",
        s.start,
        `"${s.heading}" is ${s.lines} lines against a budget of ${budget} (${overPct}% over) — short and straight beats complete and unread`
      );
  }

  // ── readability signals (§7) ──────────────────────────────────────────────
  const prose = proseLines(text).filter((p) => /\S/.test(p.text) && !/^\s*#/.test(p.text));
  const sentences = [];
  for (const p of prose)
    for (const raw of p.text.split(/(?<=[.!?])\s+/)) {
      const words = raw.trim().split(/\s+/).filter(Boolean);
      if (words.length) sentences.push({ line: p.n, words: words.length, text: raw.trim() });
    }
  const totalWords = sentences.reduce((a, s) => a + s.words, 0);
  const avg = sentences.length ? Math.round((totalWords / sentences.length) * 10) / 10 : 0;
  const longest = sentences.reduce((a, s) => (!a || s.words > a.words ? s : a), null);
  for (const s of sentences)
    if (s.words > DOC_SENTENCE_MAX)
      add("warn", "long-sentence", s.line, `a ${s.words}-word sentence — one idea per sentence, and the bar is ${DOC_SENTENCE_MAX}`, s.text);

  const longWords = sentences.reduce(
    (a, s) => a + s.text.split(/\s+/).filter((w) => syllables(w) >= 4).length,
    0
  );
  let passive = 0;
  for (const p of prose) passive += (p.text.match(PASSIVE_RE) || []).length;

  const seenAcr = new Set();
  const undefinedAcr = [];
  for (const p of prose)
    for (const m of p.text.matchAll(/\b([A-Z]{2,6})\b/g)) {
      const a = m[1];
      if (LINT_COMMON_ACRONYMS.has(a) || seenAcr.has(a)) continue;
      seenAcr.add(a);
      // "expanded on first use" looks like `Something Something (ABC)` or
      // `ABC (something something)`.
      const expanded = new RegExp(`\\(${a}\\)|${a}\\s*\\(`).test(p.text);
      if (!expanded) {
        undefinedAcr.push({ acronym: a, line: p.n });
        add("warn", "undefined-acronym", p.n, `"${a}" is used without being expanded on first use`, p.text.trim().slice(0, 120));
      }
    }

  const errors = findings.filter((f) => f.severity === "error").length;
  const warnings = findings.length - errors;
  return {
    target: tgt.id,
    target_label: tgt.label,
    max_heading: tgt.max_heading,
    front_matter: tgt.front_matter,
    lines: lines.length,
    findings,
    errors,
    warnings,
    // v0.49.2 — the measurement half of B.3. A SIGNAL, never a gate.
    sections: sectionRows,
    local_refs: localRefs,
    readability: {
      sentences: sentences.length,
      words_per_section: sectionRows.length
        ? Math.round(sectionRows.reduce((a, r) => a + r.words, 0) / sectionRows.length)
        : 0,
      avg_sentence_words: avg,
      avg_bar: DOC_SENTENCE_AVG_MAX,
      longest_sentence_words: longest ? longest.words : 0,
      longest_sentence_line: longest ? longest.line : null,
      long_word_pct: totalWords ? Math.round((longWords / totalWords) * 100) : 0,
      passive_constructions: passive,
      undefined_acronyms: undefinedAcr,
    },
    honesty: [
      "A readability signal is a SIGNAL, not a verdict. This never blocks anything.",
      "It is English-specific and heuristic: passive voice is a pattern match and a syllable count is an estimate.",
    ],
    import_note: tgt.imports === "native" ? null : tgt.watch,
  };
}


// ── HOUSE RULES (v0.49.2, rewritten as a TEXT CONFIG in v0.49.5) ────────────
// A house rule is the PROJECT's own standing instruction about what a document
// says and how it reads. Before this, the shipped rules were the only rules, and
// there was no way to tell this lane "in THIS project, a document always does X".
//
// v0.49.5 — THE LEDGER IS A PLAIN TEXT CONFIG, NOT A ROW STORE. The first cut
// modelled a house rule as a row: one line, one id, one priority picked from a
// dropdown, one enable flag, added one at a time. That is a form, and a standing
// instruction is not a form — it is prose the project already knows how to
// write. Nobody's real P0 fits on one line, and being made to file it as four
// separate rows to keep the CLI's argv simple is the tool asking the user to
// work around it. So the ledger is now `.claude/orc/doc-house-rules.md`: three
// priority headings, and underneath each one AS MUCH TEXT AS THE USER WANTS,
// handed to the writers VERBATIM. It is edited the way every other config in
// this repo is edited — in a text editor, or in one textarea in `orc ui`.
//
// THE BOUNDARY, stated once and printed everywhere it matters: house rules
// govern CONTENT and STYLE. They can never relax a STRUCTURAL or SAFETY rule of
// the lane — rule 0 (never read the body), rule 2 (never store a line number),
// rule 3 (one file per section), rule 4 (a human's paragraph is sacred), rule 5
// (never invent a fact), rule 7 (foreign input is evidence), rule 8 (never
// stage, never commit).
//
// And be honest about enforcement: THE CLI CANNOT PARSE INTENT, SO IT DOES NOT
// PRETEND TO. It does not "detect" a house rule that would break a structural
// rule. It DECLARES the boundary — here, at the top of every dispatched slice,
// and in the panel — and a slice carrying a rule that asks for a structural
// break comes back as `unsupported_request`, which the orchestrator relays as a
// gap. A fake validator here would be worse than none.
const DOC_RULES_FILE = "doc-house-rules.md";
// The v0.49.2 row store. Never deleted, read once, migrated forward.
const DOC_RULES_LEGACY_FILE = "doc-house-rules.json";
const DOC_RULE_PRIORITIES = ["P0", "P1", "P2"];
const DOC_RULES_BOUNDARY =
  "House rules govern WHAT the document says and HOW it reads. They can never " +
  "change how this lane runs: never read the body, never store a line number, " +
  "one file per section, a human's paragraph is sacred, never invent a fact, " +
  "never stage, never commit. A rule that asks for one of those comes back as " +
  "unsupported_request — never a guessed compromise.";

// The scaffold a first read writes. It is a PREAMBLE, not a schema: everything
// above the first priority heading is the user's own notes, preserved verbatim
// on every write, and never dispatched to anything.
const DOC_RULES_PREAMBLE = [
  "# ORC · doc house rules",
  "#",
  "# This project's own standing instructions about WHAT a document says and HOW",
  "# it reads. Put each one under the heading you want it read at — P0 first,",
  "# then P1, then P2 — in as many lines as you like. There is no one-line rule",
  "# and no rule count: the whole block is handed to every writer VERBATIM.",
  "#",
  "# Anything above the first `## P0` heading is a note to yourself and is never",
  "# dispatched. Edit this file directly, or in `orc ui` ▸ Docs.",
].join("\n");

const docRulesPath = (claudeDir) => path.join(claudeDir, "orc", DOC_RULES_FILE);
const docRulesLegacyPath = (claudeDir) => path.join(claudeDir, "orc", DOC_RULES_LEGACY_FILE);
const docRulesEmpty = () => ({ P0: "", P1: "", P2: "" });

// A priority heading is a line that says P0/P1/P2 and nothing else — with or
// without `#`s, with or without a colon — because a config a human types by
// hand must not fail on a plausible spelling of the only structure it has.
const DOC_RULES_HEAD_RE = /^[ \t]*#{0,6}[ \t]*(P[012])[ \t]*[:.)-]?[ \t]*$/;

function docRulesParse(text) {
  const acc = { P0: [], P1: [], P2: [] };
  const pre = [];
  let cur = null;
  for (const raw of String(text == null ? "" : text).replace(/\r\n/g, "\n").split("\n")) {
    const m = DOC_RULES_HEAD_RE.exec(raw);
    if (m) {
      cur = m[1];
      continue;
    }
    if (cur) acc[cur].push(raw);
    else pre.push(raw);
  }
  // VERBATIM inside a block: only the blank lines the headings themselves
  // introduce are trimmed. A user's indentation, bullets and blank lines are
  // theirs — the `context.md` rule, applied to a config file.
  const body = (rows) => rows.join("\n").replace(/^(?:[ \t]*\n)+/, "").replace(/\s+$/, "");
  return {
    preamble: pre.join("\n").replace(/\s+$/, ""),
    blocks: { P0: body(acc.P0), P1: body(acc.P1), P2: body(acc.P2) },
  };
}

// ONE canonical shape on disk: the preamble, then P0, P1, P2 in that order,
// every heading always present so the file is a template even when it is empty.
function docRulesRender(preamble, blocks) {
  const L = [String(preamble || "").replace(/\s+$/, "") || DOC_RULES_PREAMBLE, ""];
  for (const pr of DOC_RULE_PRIORITIES) {
    L.push("## " + pr, "");
    const body = String((blocks || {})[pr] || "").replace(/\s+$/, "");
    if (body) L.push(body, "");
  }
  return L.join("\n");
}

// LAZY, FREE, NON-DESTRUCTIVE (the v0.49.0 migration rule). The old JSON is
// never deleted, and a rule the user had DISABLED is never resurrected — it is
// left behind and counted, because silently switching someone's rule back on is
// the one migration outcome nobody can audit.
function docRulesMigrateLegacy(claudeDir) {
  let j = null;
  try {
    j = JSON.parse(fs.readFileSync(docRulesLegacyPath(claudeDir), "utf8"));
  } catch (_) {
    return null;
  }
  const rows = Array.isArray(j && j.rules) ? j.rules : [];
  if (!rows.length) return null;
  const prOf = (r) => (DOC_RULE_PRIORITIES.includes(r && r.priority) ? r.priority : "P2");
  const dropped = rows.filter((r) => r && r.enabled === false).length;
  const blocks = docRulesEmpty();
  for (const pr of DOC_RULE_PRIORITIES)
    blocks[pr] = rows
      .filter((r) => r && r.enabled !== false && prOf(r) === pr)
      .map((r) => String(r.text || "").trim())
      .filter(Boolean)
      .join("\n");
  const text = docRulesRender(DOC_RULES_PREAMBLE, blocks);
  try {
    const p = docRulesPath(claudeDir);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, text);
  } catch (_) {
    return null;
  }
  return { from: docRulesLegacyPath(claudeDir), text, blocks, dropped_disabled: dropped };
}

function docRulesRead(claudeDir) {
  let text = null;
  let migrated = null;
  try {
    text = fs.readFileSync(docRulesPath(claudeDir), "utf8");
  } catch (_) {}
  if (text === null) {
    migrated = docRulesMigrateLegacy(claudeDir);
    if (migrated) text = migrated.text;
  }
  const parsed = docRulesParse(text === null ? DOC_RULES_PREAMBLE : text);
  const preamble = parsed.preamble || DOC_RULES_PREAMBLE;
  return {
    path: docRulesPath(claudeDir),
    exists: text !== null,
    preamble,
    blocks: parsed.blocks,
    text: docRulesRender(preamble, parsed.blocks),
    empty: DOC_RULE_PRIORITIES.every((k) => !parsed.blocks[k]),
    migrated,
  };
}

// ONE WRITER, and it is this function, reached only from `orc doc rules`.
function docRulesWrite(claudeDir, preamble, blocks) {
  const p = docRulesPath(claudeDir);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  const text = docRulesRender(preamble, blocks);
  fs.writeFileSync(p, text);
  return { path: p, text };
}

// A frozen set may be a v0.49.2 ARRAY of rows or a v0.49.5 block object. Both
// open, and a document in flight migrates without the user knowing.
function docRulesBlocksOf(v) {
  const blocks = docRulesEmpty();
  if (Array.isArray(v)) {
    const prOf = (r) => (DOC_RULE_PRIORITIES.includes(r && r.priority) ? r.priority : "P2");
    for (const pr of DOC_RULE_PRIORITIES)
      blocks[pr] = v
        .filter((r) => r && r.enabled !== false && prOf(r) === pr)
        .map((r) => String(r.text || "").trim())
        .filter(Boolean)
        .join("\n");
    return blocks;
  }
  if (v && typeof v === "object") for (const pr of DOC_RULE_PRIORITIES) blocks[pr] = String(v[pr] || "");
  return blocks;
}

const docRulesCount = (block) => String(block || "").split("\n").filter((l) => l.trim()).length;

const docRulesCounts = (blocks) => {
  const c = {};
  for (const pr of DOC_RULE_PRIORITIES) c[pr] = docRulesCount((blocks || {})[pr]);
  return c;
};

// The one line the preflight prints. A rule set is NEVER silent. It counts
// LINES, because a line is the only unit this file has now — and it says so.
function docRulesLine(blocks) {
  const c = docRulesCounts(blocks);
  const total = DOC_RULE_PRIORITIES.reduce((a, k) => a + c[k], 0);
  if (!total) return "house rules: none";
  const parts = DOC_RULE_PRIORITIES.filter((k) => c[k]).map((k) => `${k} ${c[k]}`);
  return `house rules: ${plural(total, "line")} (${parts.join(" · ")})`;
}

// What actually rides at the top of a slice: the priority word, then the block,
// VERBATIM. An empty priority is omitted — an empty heading in a slice is noise
// a writer has to decide about.
function docRulesSlice(blocks) {
  const L = [];
  for (const pr of DOC_RULE_PRIORITIES) {
    const body = String((blocks || {})[pr] || "").replace(/\s+$/, "");
    if (body) L.push(pr, body, "");
  }
  return L.join("\n").replace(/\s+$/, "");
}

// FROZEN vs PROJECT — per priority, and it NAMES the block that moved with both
// texts. A "rules changed" boolean would tell the user a fact they cannot act
// on: the `computeWikiFreshness` lesson, applied to a config file.
function docRulesDrift(frozen, project) {
  const fz = docRulesBlocksOf(frozen);
  const pj = docRulesBlocksOf(project);
  const changed = [];
  for (const pr of DOC_RULE_PRIORITIES)
    if (fz[pr] !== pj[pr]) changed.push({ priority: pr, from: fz[pr], to: pj[pr] });
  return { changed, drifted: changed.length > 0 };
}

// house-rules.md is DERIVED — never hand-edited, rewritten whenever the frozen
// set changes. It exists so the rules a document was written against are
// readable beside the document, not only inside doc.json.
function docWriteHouseRules(claudeDir, slug, d) {
  const p = docPaths(claudeDir, slug);
  const blocks = docRulesBlocksOf(d.doc_rules);
  const L = [
    "<!-- orc-doc:derived — written by the `orc doc` CLI from doc.json.",
    "     Change the project ledger in `.claude/orc/" + DOC_RULES_FILE + "` (or with",
    "     `orc doc rules set`); re-freeze this document with",
    "     `orc doc rules " + slug + " --sync`. A hand edit here is overwritten the",
    "     next time anything writes. -->",
    "",
    `# House rules — ${d.title}`,
    "",
    "These are the rules this document was FROZEN against at `orc doc init`. A",
    "document is written against the rules that were true when it started.",
    "",
  ];
  if (DOC_RULE_PRIORITIES.every((pr) => !blocks[pr]))
    L.push("No house rules were set when this document started.", "");
  for (const pr of DOC_RULE_PRIORITIES) {
    if (!blocks[pr]) continue;
    L.push(`## ${pr}`, "", blocks[pr], "");
  }
  L.push("---", "", DOC_RULES_BOUNDARY, "");
  fs.writeFileSync(path.join(p.folder, "house-rules.md"), L.join("\n"));
  return path.join(p.folder, "house-rules.md");
}

// `orc doc rules …` — the project ledger, the frozen set, and the drift between.
// The skill's side of this is hard rule 15: `house rules are read first` — the
// whole enabled text rides at the TOP of every dispatched slice, above ORC's own
// generation rules. This function is where that text comes from.
function docRulesCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const led = docRulesRead(claudeDir);
  const pos = docPositionals(); // ["doc","rules",<sub|slug?>]
  const sub = String(pos[2] || "");
  const fail = (reason, hint, code = 2) => {
    if (asJson) emitJson({ ok: false, reason, hint, boundary: DOC_RULES_BOUNDARY }, code);
    console.error("❌ " + hint);
    process.exit(code);
  };
  const save = (msg, blocks, extra) => {
    const w = docRulesWrite(claudeDir, led.preamble, blocks);
    const fresh = docRulesParse(w.text).blocks;
    if (asJson)
      emitJson(
        {
          ok: true,
          ...extra,
          file: w.path,
          blocks: fresh,
          text: w.text,
          counts: docRulesCounts(fresh),
          line: docRulesLine(fresh),
          priorities: DOC_RULE_PRIORITIES,
          boundary: DOC_RULES_BOUNDARY,
        },
        0
      );
    console.log("✓ " + msg);
    console.log(ui.color.gray("  " + docRulesLine(fresh)));
    console.log(ui.color.gray("  " + w.path));
    process.exit(0);
  };
  const priorityOf = () => {
    const pr = String(docOpt("--priority") || "").toUpperCase();
    return DOC_RULE_PRIORITIES.includes(pr) ? pr : null;
  };
  const wholeFile = (text, msg, extra) => {
    const parsed = docRulesParse(text);
    // A whole-file write brings its own preamble with it, so the notes a user
    // typed above `## P0` survive a round trip through the panel.
    led.preamble = parsed.preamble || led.preamble;
    return save(msg, parsed.blocks, extra);
  };

  // ── the writes ───────────────────────────────────────────────────────────
  // The v0.49.2 row commands. They are REFUSED BY NAME rather than quietly
  // dropped: a command that used to work and now does nothing is worse than one
  // that says what replaced it.
  if (sub === "remove" || sub === "enable" || sub === "disable" || sub === "move")
    return fail(
      "retired",
      `\`orc doc rules ${sub}\` is gone — house rules are plain text now, not numbered rows. ` +
        `Edit the block: orc doc rules set --priority P0 --text "…", or open ${docRulesPath(claudeDir)} in your editor.`
    );

  if (sub === "set" || sub === "add") {
    const pr = priorityOf();
    if (!pr) return fail("bad-priority", `--priority must be one of: ${DOC_RULE_PRIORITIES.join(", ")}`);
    const text = docOpt("--text");
    if (!text || !String(text).trim())
      return fail("no-text", `orc doc rules ${sub} needs --text "<your rules, in your own words>". As many lines as you like.`);
    const body = String(text).replace(/\r\n/g, "\n").replace(/\s+$/, "");
    const blocks = { ...led.blocks };
    blocks[pr] = sub === "add" && blocks[pr] ? blocks[pr] + "\n" + body : body;
    return save(`${pr} ${sub === "add" ? "extended" : "set"} — ${plural(docRulesCount(blocks[pr]), "line")}`, blocks, { priority: pr });
  }
  if (sub === "clear") {
    const pr = priorityOf();
    if (!pr) return fail("bad-priority", `--priority must be one of: ${DOC_RULE_PRIORITIES.join(", ")}`);
    const blocks = { ...led.blocks };
    blocks[pr] = "";
    return save(`${pr} cleared`, blocks, { priority: pr, cleared: true });
  }
  // The PANEL's write, and the one a script pipes in: the whole file at once.
  if (sub === "set-all") {
    const text = docOpt("--text");
    if (text === undefined) return fail("no-text", `orc doc rules set-all needs --text "<the whole file>".`);
    return wholeFile(text, "house rules replaced");
  }
  const setFile = docOpt("--set-file");
  if (setFile) {
    const abs = path.isAbsolute(setFile) ? setFile : path.join(repoRootOf(claudeDir), setFile);
    if (!fs.existsSync(abs)) return fail("no-such-file", `no such file: ${setFile}`);
    return wholeFile(fs.readFileSync(abs, "utf8"), `house rules replaced from ${setFile}`, { from: setFile });
  }
  if (flag("--reset") === true) {
    led.preamble = DOC_RULES_PREAMBLE;
    return save("house rules reset to the empty template", docRulesEmpty(), { reset: true });
  }

  // ── the reads ────────────────────────────────────────────────────────────
  // `orc doc rules <slug>` — the FROZEN set of one document, and its drift.
  const slug = sub && sub !== "list" ? docResolveSlug(claudeDir, sub) : slugArg ? docResolveSlug(claudeDir, slugArg) : null;
  if ((sub && sub !== "list") || slugArg) {
    if (!slug) return docNoSuch(asJson, sub || slugArg);
    const d = docRead(claudeDir, slug);
    if (!d) return docNoSuch(asJson, sub || slugArg);
    const frozen = docRulesBlocksOf(d.doc_rules);
    const drift = docRulesDrift(frozen, led.blocks);
    if (flag("--sync") === true) {
      // A DELIBERATE re-freeze. It NAMES the already-written sections that
      // predate the new set and never re-writes one: auto-rewriting would be ORC
      // spending money applying a rule change nobody asked it to apply
      // retroactively.
      const predate = d.outline
        .filter((o) => {
          const st = (d.sections || {})[o.id];
          return st && st.state && st.state !== "planned";
        })
        .map((o) => o.id);
      d.doc_rules = { ...led.blocks };
      d.doc_rule_syncs = Array.isArray(d.doc_rule_syncs) ? d.doc_rule_syncs : [];
      d.doc_rule_syncs.push({ at: fmtStamp(new Date()), counts: docRulesCounts(led.blocks), predate });
      docWrite(claudeDir, slug, d);
      docWriteHouseRules(claudeDir, slug, d);
      const synced = DOC_RULE_PRIORITIES.reduce((a, k) => a + docRulesCount(led.blocks[k]), 0);
      if (asJson)
        emitJson(
          {
            ok: true,
            slug,
            synced,
            predate,
            blocks: led.blocks,
            text: docRulesSlice(led.blocks),
            counts: docRulesCounts(led.blocks),
            boundary: DOC_RULES_BOUNDARY,
          },
          0
        );
      console.log(`✓ ${slug} re-frozen against ${plural(synced, "line")} of house rules.`);
      if (predate.length) {
        console.log(`\n  These sections were written BEFORE the change and are NOT re-written:`);
        for (const id of predate) console.log(`    ${id}`);
        console.log(`\n  Whether any of them needs redoing is your call, not ORC's.`);
      }
      process.exit(0);
    }
    const code = drift.drifted ? 1 : 0;
    if (asJson)
      emitJson(
        {
          ok: true,
          slug,
          frozen,
          project: led.blocks,
          drift,
          counts: docRulesCounts(frozen),
          line: docRulesLine(frozen),
          priorities: DOC_RULE_PRIORITIES,
          text: docRulesSlice(frozen),
          boundary: DOC_RULES_BOUNDARY,
        },
        code
      );
    console.log(ui.header(`ORC · doc rules — ${slug}`));
    console.log(`\n  ${docRulesLine(frozen)}   ${ui.color.gray("(frozen at init)")}`);
    for (const pr of DOC_RULE_PRIORITIES) {
      if (!frozen[pr]) continue;
      console.log(`\n  ${pr}`);
      for (const l of frozen[pr].split("\n")) console.log(`    ${l}`);
    }
    if (!drift.drifted) console.log(`\n  The project ledger has not moved since.`);
    else {
      console.log(`\n  The project ledger HAS moved since this document was frozen:`);
      for (const ch of drift.changed) {
        console.log(`    ~ ${ch.priority}  ${plural(docRulesCount(ch.from), "line")} → ${plural(docRulesCount(ch.to), "line")}`);
        for (const l of (ch.to || "(empty)").split("\n")) console.log(`        ${l}`);
      }
      console.log(`\n  Re-freeze deliberately:  orc doc rules ${slug} --sync`);
    }
    console.log("\n" + ui.color.gray("  " + DOC_RULES_BOUNDARY));
    process.exit(code);
  }

  // `orc doc rules` — the project ledger. NO rules is an ANSWER, so the object
  // is still returned; only the exit code says "there is nothing here yet".
  const code = led.empty ? 1 : 0;
  if (asJson)
    emitJson(
      {
        ok: true,
        file: led.path,
        exists: led.exists,
        preamble: led.preamble,
        blocks: led.blocks,
        text: led.text,
        slice: docRulesSlice(led.blocks),
        counts: docRulesCounts(led.blocks),
        line: docRulesLine(led.blocks),
        priorities: DOC_RULE_PRIORITIES,
        empty: led.empty,
        migrated: led.migrated ? { from: led.migrated.from, dropped_disabled: led.migrated.dropped_disabled } : null,
        template: docRulesRender(DOC_RULES_PREAMBLE, docRulesEmpty()),
        boundary: DOC_RULES_BOUNDARY,
      },
      code
    );
  console.log(ui.header("ORC · doc house rules"));
  console.log(`\n  ${led.path}`);
  if (led.migrated)
    console.log(
      ui.color.yellow(`\n  Migrated from ${DOC_RULES_LEGACY_FILE} — it was left on disk, nothing was deleted.`) +
        (led.migrated.dropped_disabled
          ? `\n  ${plural(led.migrated.dropped_disabled, "disabled rule")} was NOT carried over. Add it back if you want it.`
          : "")
    );
  if (led.empty) {
    console.log(`\n  No house rules yet.`);
    console.log(`\n  Write them:  orc doc rules set --priority P0 --text "every document opens with a one-paragraph summary"`);
    console.log(`  Or open the file above in your editor — P0, P1 and P2 are already there.`);
  } else {
    for (const pr of DOC_RULE_PRIORITIES) {
      if (!led.blocks[pr]) continue;
      console.log(`\n  ${pr}`);
      for (const l of led.blocks[pr].split("\n")) console.log(`    ${l}`);
    }
    console.log(`\n  ${docRulesLine(led.blocks)}`);
  }
  console.log("\n" + ui.color.gray("  " + DOC_RULES_BOUNDARY));
  process.exit(code);
}

// ── the commands ────────────────────────────────────────────────────────────

function docInit(claudeDir) {
  const asJson = wantsJson();
  const pos = docPositionals(); // ["doc","init",<slug?>]
  const fail = (reason, hint, code = 2) => {
    if (asJson) emitJson({ ok: false, reason, hint }, code);
    console.error("❌ " + hint);
    process.exit(code);
  };
  const type = String(docOpt("--type") || "").toLowerCase();
  const tpl = docTemplate(type);
  const custom = docOpt("--template");
  if (!type) fail("no-type", `orc doc init needs --type <${DOC_TYPES.join("|")}>.`);
  if (!tpl) fail("bad-type", `--type must be one of: ${DOC_TYPES.join(", ")}`);
  const explicit = docSlugify(pos[2] || "");
  if (!explicit) fail("no-slug", "orc doc init needs a slug (it becomes the folder name).");
  // The folder is `<slug>-<DDMMYY>`, so the same subject on two days is two
  // documents and neither silently overwrites the other.
  const folderSlug = /-\d{6}$/.test(explicit) ? explicit : explicit + "-" + docStamp();
  const paths = docPaths(claudeDir, folderSlug);
  if (fs.existsSync(paths.state)) fail("exists", `a document named ${folderSlug} already exists at ${paths.folder}`, 1);

  let sections = tpl.sections.map((s) => ({ ...s }));
  let templateSource = "shipped:" + tpl.type;
  // v0.49.2 — TEMPLATE LOCK. A SUPPLIED template is a P0 cage, not a suggestion:
  // `--template` set the outline and then nothing stopped a writer adding a
  // heading the template never had. A SHIPPED base template stays unlocked — it
  // is a floor, not a cage, which is what `orc doc templates` has always said.
  let templateLock = { path: null, hash: null, locked: false, headings: [], source: "shipped" };
  if (custom) {
    const abs = path.isAbsolute(custom) ? custom : path.join(paths.root, custom);
    if (!fs.existsSync(abs)) fail("no-such-template", `template not found: ${custom}`);
    // A user template REPLACES the shipped one entirely. Its headings become the
    // outline; its body text is instructions for the writer, never content to
    // copy through. The two are never merged silently.
    const heads = docScan(fs.readFileSync(abs, "utf8")).sections;
    if (!heads.length)
      fail(
        "no-headings",
        `no \`## \` headings found in ${custom}. A structure is never guessed out of prose — ` +
          `show the user the shipped ${tpl.type} outline and ask which to use.`
      );
    sections = heads.map((h) => ({ heading: h.heading, required: true, budget: 120, affinity: null, purpose: null }));
    templateSource = custom;
    templateLock = {
      path: String(custom).replace(/\\/g, "/"),
      hash: shaOfFile(abs),
      // Locked BY DEFAULT whenever a user template is supplied. `--template-soft`
      // opts out, and the init output says which one is in force.
      locked: flag("--template-soft") !== true,
      headings: heads.map((h) => h.heading),
      source: "user",
    };
  }

  const outline = sections.map((s, i) => ({
    id: docSectionId(i + 1, s.heading),
    heading: s.heading,
    level: 2,
    required: s.required !== false,
    purpose: s.purpose || null,
    affinity: s.affinity || null,
    budget_lines: s.budget || 120,
  }));

  const target = String(docOpt("--target") || "generic").toLowerCase();
  if (!DOC_TARGETS.some((t) => t.id === target))
    fail("bad-target", `--target must be one of: ${DOC_TARGETS.map((t) => t.id).join(", ")}`);
  const length = String(docOpt("--length") || "standard").toLowerCase();
  if (!DOC_LENGTHS.includes(length)) fail("bad-length", `--length must be one of: ${DOC_LENGTHS.join(", ")}`);

  const cfg = resolvedConfig(claudeDir);
  // FROZEN at init, for the same reason `context.md` is frozen: if a P0 changes
  // at wave 3, half the document silently no longer complies and nothing on disk
  // says so. `orc doc rules <slug>` reports the drift; `--sync` re-freezes
  // deliberately and NAMES the sections that predate the change.
  const houseRules = docRulesRead(claudeDir).blocks;
  const d = {
    version: DOC_STATE_VERSION,
    slug: folderSlug,
    type: tpl.type,
    title: docOpt("--title") || folderSlug.replace(/-\d{6}$/, "").replace(/-/g, " "),
    language: docOpt("--language") || cfg.doc_language || "en",
    target,
    length,
    template: { source: templateSource, label: tpl.label, ...templateLock },
    created_at: fmtStamp(new Date()),
    cycle: 0,
    outline,
    write_mode: cfg.doc_write_mode && cfg.doc_write_mode !== "ask" ? cfg.doc_write_mode : null,
    sections: {},
    extracts: {},
    cycles: [],
    migrations: [],
    doc_rules: { ...houseRules },
    doc_rule_syncs: [],
  };
  // `sections/` is a REAL, VISIBLE folder — a hidden dot-folder is not something
  // a human opens, edits, or reviews in a PR, and half the point is that you can
  // read one section without opening the document.
  fs.mkdirSync(paths.sections, { recursive: true });
  docWrite(claudeDir, folderSlug, d);
  docWriteOutline(claudeDir, folderSlug, d);
  docWriteHouseRules(claudeDir, folderSlug, d);

  const oversized = outline.filter((o) => o.budget_lines > Number(cfg.doc_max_lines_per_agent || 400));
  if (asJson)
    emitJson(
      {
        ok: true,
        slug: folderSlug,
        dir: paths.folder,
        type: tpl.type,
        target,
        language: d.language,
        outline,
        oversized: oversized.map((o) => o.id),
        sections_dir: path.relative(paths.root, paths.sections).split(path.sep).join("/"),
        write_mode: d.write_mode,
        doc_rules: houseRules,
        doc_rules_text: docRulesSlice(houseRules),
        doc_rules_line: docRulesLine(houseRules),
        template_locked: templateLock.locked,
        allowed_headings: templateLock.locked ? templateLock.headings : null,
        next: `orc doc plan ${folderSlug} --role write`,
      },
      0
    );
  console.log(ui.header(`ORC · doc — ${folderSlug} created`));
  console.log(`\n  type:      ${tpl.label}`);
  console.log(`  template:  ${templateSource}`);
  console.log(`  target:    ${docTarget(target).label}`);
  console.log(`  sections:  ${outline.length}   (${outline.filter((o) => o.required).length} required)`);
  console.log(`  ${docRulesLine(houseRules)}`);
  if (templateLock.source === "user")
    console.log(
      templateLock.locked
        ? `  template:  LOCKED — a heading this template never had is a lint error and \`parts --confirm\` refuses it`
        : `  template:  soft (--template-soft) — the outline came from it, but nothing enforces it`
    );
  console.log(`  folder:    ${paths.folder}`);
  console.log(`\n  Next:  orc doc plan ${folderSlug} --role write`);
  process.exit(0);
}

// outline.md is DERIVED from doc.json and rewritten whenever the outline
// changes. It is the writer/orchestrator contract in a form a human can read —
// and having one writer is what stops the two disagreeing about section order.
function docWriteOutline(claudeDir, slug, d) {
  const p = docPaths(claudeDir, slug);
  const L = [
    "<!-- orc-doc:derived — written by the `orc doc` CLI from doc.json.",
    "     Change the outline with `orc doc outline <slug> --set <file>`; a hand",
    "     edit here is overwritten the next time anything writes. -->",
    "",
    `# Outline — ${d.title}`,
    "",
    `Type: ${d.type} · Language: ${d.language} · Target: ${d.target} · Length: ${d.length}`,
    "",
    "| # | Section | Required | Budget | Purpose |",
    "|---|---|---|---|---|",
    ...d.outline.map(
      (o, i) =>
        `| ${i + 1} | ${o.heading} | ${o.required ? "yes" : "no"} | ${o.budget_lines} | ${o.purpose || "—"} |` +
        ((o.subsections || []).length ? `\n| | ${o.subsections.map((s) => "· " + s.heading).join("<br>")} | | | stored as parts |` : "")
    ),
    "",
    "A required section with no material is NOT written. It is returned as a gap,",
    "recorded in gaps.md, and raised with you — the deliverable carries content only.",
    "",
    "One file per section under `sections/`. `document.md` is a build artifact:",
    "rebuild it any time, for free, with `orc doc compile`.",
    "",
  ];
  fs.writeFileSync(p.outline, L.join("\n"));
  return p.outline;
}

function docOutlineCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const set = docOpt("--set");
  if (set) {
    const p = docPaths(claudeDir, slug);
    const abs = path.isAbsolute(set) ? set : path.join(p.root, set);
    if (!fs.existsSync(abs)) {
      if (asJson) emitJson({ ok: false, reason: "no-such-file", path: set }, 2);
      console.error(`❌ not found: ${set}`);
      process.exit(2);
    }
    const heads = docScan(fs.readFileSync(abs, "utf8")).sections;
    if (!heads.length) {
      if (asJson) emitJson({ ok: false, reason: "no-headings", path: set }, 2);
      console.error(`❌ no \`## \` headings in ${set} — a structure is never guessed out of prose.`);
      process.exit(2);
    }
    const old = new Map(d.outline.map((o) => [docSlugify(o.heading), o]));
    const renames = [];
    d.outline = heads.map((h, i) => {
      const prev = old.get(docSlugify(h.heading));
      const id = docSectionId(i + 1, h.heading);
      if (prev && prev.id !== id) renames.push({ from: prev.id, to: id });
      return {
        id,
        heading: h.heading,
        level: 2,
        required: prev ? prev.required : true,
        purpose: prev ? prev.purpose : null,
        affinity: prev ? prev.affinity : null,
        budget_lines: prev ? prev.budget_lines : 120,
        subsections: prev ? prev.subsections || [] : [],
      };
    });
    // The filename NUMBER is a mirror of the outline index, and the CLI is what
    // keeps it in sync. A renumber renames the files on disk in the SAME step —
    // otherwise `audit` would report `part-misnumbered` on a document nobody
    // touched, and the section's whole history would sit under a dead name.
    const p2 = docPaths(claudeDir, slug);
    for (const r of renames) {
      for (const [from, to] of [[docSectionFile(p2, r.from), docSectionFile(p2, r.to)], [docSectionDir(p2, r.from), docSectionDir(p2, r.to)]])
        if (fs.existsSync(from) && !fs.existsSync(to)) {
          try { fs.renameSync(from, to); } catch (_) {}
        }
      if (d.sections[r.from]) {
        d.sections[r.to] = { ...d.sections[r.from], renamed_from: r.from };
        delete d.sections[r.from];
      }
    }
    docWrite(claudeDir, slug, d);
    docWriteOutline(claudeDir, slug, d);
    if (renames.length && !asJson)
      for (const r of renames) console.log(`  renamed: ${r.from} → ${r.to}`);
  }
  if (asJson) emitJson({ ok: true, slug, outline: d.outline, file: docPaths(claudeDir, slug).outline }, 0);
  console.log(ui.header(`ORC · doc outline — ${slug}`));
  d.outline.forEach((o, i) =>
    console.log(`  ${String(i + 1).padStart(3)}  ${o.required ? " " : "·"} ${o.heading.padEnd(44)} ${String(o.budget_lines).padStart(4)} L`)
  );
  process.exit(0);
}

// A prefix is enough, because the folder carries a date suffix nobody memorises.
function docResolveSlug(claudeDir, raw) {
  const want = String(raw || "");
  if (!want) return null;
  const all = docList(claudeDir);
  if (all.includes(want)) return want;
  const hits = all.filter((s) => s.startsWith(want));
  return hits.length === 1 ? hits[0] : null;
}

function docNoSuch(asJson, slugArg) {
  const hint = `no document "${slugArg || ""}" — \`orc doc list\` shows the ones that exist (a prefix is enough).`;
  if (asJson) emitJson({ ok: false, reason: "no-such-doc", slug: slugArg || null, hint }, 2);
  console.log(hint);
  process.exit(2);
}

function docListCmd(claudeDir) {
  const asJson = wantsJson();
  const slugs = docList(claudeDir);
  // A listing must NOT mutate, so `list` is the one command that never triggers
  // the lazy migration.
  const rows = slugs.map((s) => {
    const view = docMapView(claudeDir, s);
    const d = view.d;
    const v2 = d.version >= DOC_STATE_VERSION;
    const pv = docPartsView(claudeDir, s);
    const written = v2
      ? pv.rows.filter((x) => x.state === "written" || x.state === "checked").length
      : view.sections.filter((x) => x.state !== "planned" && x.state !== "open").length;
    return {
      slug: s,
      version: d.version,
      title: d.title,
      type: d.type,
      target: d.target,
      language: d.language,
      cycle: d.cycle || 0,
      // It may only claim what the disk proves: a missing document.md means
      // NOT STARTED, never "failed".
      document: view.document && fs.existsSync(view.document) ? "present" : "not started",
      lines: view.total_lines,
      sections_total: (d.outline || []).length,
      sections_written: written,
      user_edited: (v2 ? pv.rows : view.sections).filter((x) => x.state === "user-edited").map((x) => x.id),
      where: docWhereLine(d, view, { rows: v2 ? pv.rows : null, wave: docWaveState(d, pv.rows) }),
      dir: view.paths.folder,
      next: `/orc-doc resume ${s}`,
    };
  });
  if (asJson) emitJson({ ok: true, dir: docPaths(claudeDir).rel, documents: rows, total: rows.length }, 0);
  if (!rows.length) {
    console.log("no documents yet — run `/orc-doc` to start one (it asks what you want written first, and never invents it).");
    process.exit(0);
  }
  console.log(ui.header(`ORC · doc — ${plural(rows.length, "document")}`));
  console.log("");
  for (const r of rows) {
    console.log(`  ${r.type.toUpperCase().padEnd(14)} ${r.slug}`);
    console.log(`  ${"".padEnd(14)} ${ui.color.gray(r.where)}`);
    if (r.user_edited.length)
      console.log(`  ${"".padEnd(14)} ${ui.color.gray("you edited: " + r.user_edited.join(", "))}`);
  }
  process.exit(0);
}

function docShowCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const view = slug ? docMapView(claudeDir, slug) : null;
  if (!view) return docNoSuch(asJson, slugArg);
  const d = view.d;

  // ONE section's text, on an explicit request. This is the only command that
  // returns any of the document's prose, and it is deliberately one section at a
  // time: the rule is that nothing HOLDS the document, not that the text is
  // secret. A caller that asked for a named section has already decided to spend
  // the context on it.
  const want = docOpt("--section");
  if (want) {
    const s = (view.sections || []).find((x) => x.id === want || x.id.startsWith(want));
    if (!s || !view.scan) {
      const hint = `no section "${want}" in ${slug} — \`orc doc map ${slug}\` lists them.`;
      if (asJson) emitJson({ ok: false, reason: "no-such-section", slug, section: want, hint }, 2);
      console.error("❌ " + hint);
      process.exit(2);
    }
    const scanned = view.scan.sections.find((x) => x.id === s.id);
    if (asJson)
      emitJson(
        { ok: true, slug, section: s.id, heading: s.heading, start: s.start, end: s.end, lines: s.lines, state: s.state, hash: s.hash, text: scanned.text },
        0
      );
    console.log(scanned.text);
    process.exit(0);
  }

  // v0.48.1 — the memory fields. `created_at` was already in doc.json and was
  // never emitted: the CLI knew when a document started and never said so. That
  // is a bug fix, not a feature.
  const jr = docJournalRows(claudeDir, slug);
  const ctx = docContextSources(docContextPaths(view.paths), view.paths.root);
  const payload = {
    ok: true,
    slug,
    title: d.title,
    type: d.type,
    language: d.language,
    target: d.target,
    length: d.length,
    template: d.template,
    cycle: d.cycle || 0,
    created_at: d.created_at || null,
    last_touched_at: d.updated_at || null,
    sessions: docSessionCount(claudeDir, slug),
    dir: view.paths.folder,
    document: view.document && fs.existsSync(view.document) ? view.document : null,
    total_lines: view.total_lines,
    outline: d.outline,
    sections: view.sections,
    extracts: d.extracts,
    // Per cycle: the role, the sections it touched, the findings it raised, and
    // the agent + model that ran it. It was all in doc.json and effectively
    // invisible.
    cycles: (d.cycles || []).map((c, i) => ({
      n: c.n || i + 1,
      at: c.at || null,
      role: c.role || null,
      sections: c.sections || [],
      findings: c.findings || 0,
      agents: c.agents || null,
      model: c.model || null,
      effort: c.effort || null,
    })),
    journal: jr ? jr.rows : [],
    context: ctx,
    shipped: d.shipped || null,
    ship_history: d.ship_history || [],
    lock: d.lock || null,
    where: docWhereLine(d, view),
  };
  if (asJson) emitJson(payload, 0);
  console.log(ui.header(`ORC · doc ${slug} — ${d.title}`));
  console.log(`\n  ${docWhereLine(d, view)}\n`);
  for (const s of view.sections)
    console.log(
      `  ${s.state.padEnd(12)} ${String(s.start).padStart(5)}..${String(s.end).padEnd(5)} ` +
        `${String(s.lines).padStart(4)}L  ${s.heading}` +
        (s.findings ? `  ${ui.color.gray(plural(s.findings, "finding"))}` : "")
    );
  process.exit(0);
}

function docMapCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const view = slug ? docMapView(claudeDir, slug, { persist: true }) : null;
  if (!view) return docNoSuch(asJson, slugArg);
  if (!view.document || !fs.existsSync(view.document)) {
    const hint = `no ${DOC_FILE} yet for ${slug} — nothing has been assembled.`;
    if (asJson) emitJson({ ok: false, reason: "no-document", slug, hint }, 2);
    console.log(hint);
    process.exit(2);
  }
  const payload = {
    ok: true,
    slug,
    file: path.relative(view.paths.root, view.document).split(path.sep).join("/"),
    lines: view.total_lines,
    preamble_end: view.preamble_end,
    sections: view.sections.map(({ id, heading, level, start, end, lines, hash, state, required, findings, renamed_from }) => ({
      id, heading, level, start, end, lines, hash, state, required, findings, renamed_from,
    })),
    repaired: view.repairs,
    note: "line numbers are DERIVED on every read and never stored — a stored line number is a wrong line number one edit later",
  };
  if (asJson) emitJson(payload, 0);
  console.log(ui.header(`ORC · doc map — ${slug}  (${view.total_lines} lines)`));
  console.log("");
  for (const s of view.sections)
    console.log(
      `  ${s.id.padEnd(30)} ${String(s.start).padStart(5)}..${String(s.end).padEnd(5)} ` +
        `${String(s.lines).padStart(4)}L  ${s.state.padEnd(12)} ${s.hash.slice(0, 8)}`
    );
  if (view.repairs.length)
    for (const r of view.repairs) console.log(`\n  repaired: ${r.from} → ${r.to} (heading renamed; history kept)`);
  process.exit(0);
}

// ── the batching — the model NEVER decides how to split (§5.4) ──────────────
// v0.49.2 — the batcher is a FUNCTION, and `orc doc plan`, `orc doc forecast`
// and `orc doc next` all call it. A forecast computed by a second idea of the
// wave shape would describe a run the run will not follow, which is the same
// drift the Flow stepper rule exists to prevent.
//
// It RETURNS the shape and prints nothing. `role` overrides `--role` so a
// forecast can ask for the check pass without the flag.
function docPlanShape(claudeDir, slugArg, roleOverride) {
  const slug = docResolveSlug(claudeDir, slugArg);
  if (slug) docMigrateV2(claudeDir, slug);
  if (slug) docMigrateV2(claudeDir, slug);
  const view = slug ? docMapView(claudeDir, slug) : null;
  if (!view) return null;
  const d = view.d;
  const cfg = resolvedConfig(claudeDir);
  const v2 = d.version >= DOC_STATE_VERSION;
  const pv = v2 ? docPartsView(claudeDir, slug) : null;
  const only = String(docOpt("--only") || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const writeMode = d.write_mode || (cfg.doc_write_mode === "ask" ? null : cfg.doc_write_mode);
  const role = String(roleOverride || docOpt("--role") || "write").toLowerCase();
  if (!DOC_ROLES.includes(role)) return { bad_role: true, role, slug, d, view };
  const budget = Math.max(40, Number(docOpt("--budget") || cfg.doc_max_lines_per_agent || 400));
  const wanted = Math.max(1, Number(cfg.doc_max_parallel || DOC_MAX_PARALLEL_CAP));
  const parallel = Math.min(DOC_MAX_PARALLEL_CAP, wanted);
  const clamped = wanted > DOC_MAX_PARALLEL_CAP ? { from: wanted, to: parallel } : null;

  const live = new Map(view.sections.map((s) => [s.id, s]));
  const byPart = pv ? new Map(pv.rows.map((r) => [r.id, r])) : null;
  // ONE FILE PER SECTION, never per slice. Before v0.49.0 a slice covering two
  // sections wrote ONE file named after the first, while compile looked up a
  // file per outline id — so the second section's file never existed. That was a
  // live bug; one file per section fixes it by construction.
  const partFile = (o) => {
    if (!v2) return `${DOC_WORK}/${o.id}.md`;
    const row = byPart ? byPart.get(o.id) : null;
    if (row && row.nested) return `${DOC_SECTIONS}/${o.id}/`;
    return `${DOC_SECTIONS}/${o.id}.md`;
  };
  let items = [];
  if (role === "write") {
    // Only what has no body yet, plus anything a wave left `unconfirmed`. A
    // `user-edited` section is NEVER re-written without an instruction naming
    // it — overwriting a human's paragraph is unrecoverable from this side.
    items = d.outline
      .filter((o) => {
        if (v2) {
          const r = byPart.get(o.id);
          return !r || r.state === "planned" || r.state === "unconfirmed";
        }
        const s = live.get(o.id);
        return !s || s.state === "planned" || s.state === "open";
      })
      .map((o) => ({
        id: o.id,
        heading: o.heading,
        required: !!o.required,
        purpose: o.purpose,
        affinity: o.affinity,
        budget_lines: o.budget_lines,
        part: partFile(o),
        subsections: (o.subsections || []).map((s) => ({ id: s.id, heading: s.heading, file: `${DOC_SECTIONS}/${o.id}/${s.id}.md` })),
      }));
  } else if (role === "check") {
    // The hash is what turns a re-check from a full pass into a diff: a section
    // whose hash has not moved since it was checked does not need re-reading.
    // In v2 a checker gets one bounded PART FILE, so there is no line arithmetic
    // anywhere in the loop.
    items = v2
      ? pv.rows
          .filter((r) => r.exists && r.state !== "checked")
          .map((r) => {
            const o = d.outline.find((x) => x.id === r.id) || {};
            return {
              id: r.id,
              heading: r.heading,
              required: r.required,
              purpose: r.purpose,
              affinity: o.affinity || null,
              budget_lines: r.lines,
              part: partFile(o),
              files: r.files,
              // Only the sub-parts that MOVED are re-read. A single changed
              // sub-part in a 900-line section costs one ~150-line read.
              changed_subparts: r.subsections.filter((s) => s.changed).map((s) => s.file),
            };
          })
      : view.sections
          .filter((s) => s.state !== "planned" && s.state !== "checked")
          .map((s) => ({
            id: s.id,
            heading: s.heading,
            required: s.required,
            purpose: s.purpose,
            affinity: (d.outline.find((o) => o.id === s.id) || {}).affinity || null,
            budget_lines: s.lines,
            start: s.start,
            end: s.end,
          }));
  } else {
    const lintOpts = docLintOpts(claudeDir, d);
    items = (v2 ? pv.rows : view.sections)
      .filter((s) => s.findings > 0)
      .map((s) => {
        const o = d.outline.find((x) => x.id === s.id) || { id: s.id };
        // v0.49.2 — EVERY finding carries the FILE and the PART-LOCAL line. An
        // edit round that names a rule but not a place cannot be followed in
        // `sections/`, which is where the user is actually reading. The compiled
        // `document.md` line number is deliberately NOT carried: it is stale the
        // moment anything is written, which is what rule 2 exists for.
        let anchors = [];
        if (v2) {
          const src = docSectionSource(view.paths, o);
          for (const pt of (src && src.parts) || []) {
            const res = docLintRun(pt.text, d.target, { ...lintOpts, part: true });
            for (const f of res.findings)
              anchors.push({
                rule: f.rule,
                severity: f.severity,
                file: pt.file,
                line: f.line,
                sub_file: pt.sub ? pt.file : null,
                what: f.what,
                quote: f.quote,
              });
          }
        }
        return {
          id: s.id,
          heading: s.heading,
          required: s.required,
          purpose: s.purpose,
          affinity: null,
          budget_lines: s.lines,
          start: s.start,
          end: s.end,
          part: partFile(o),
          files: v2 ? s.files : undefined,
          findings: anchors,
        };
      });
  }
  if (only.length) items = items.filter((it) => only.some((k) => it.id === k || it.id.startsWith(k)));

  const agentName = role === "check" ? "orc-doc-checker-opus-5-low" : "orc-doc-writer-opus-5-med";

  if (!items.length) {
    // An empty result is an ANSWER, so the SAME shape comes back with an empty
    // wave list — a caller must never have to special-case "nothing to do" by
    // parsing prose or by finding half the keys missing.
    const hint =
      role === "write"
        ? "every section already has a body — nothing to write."
        : role === "check"
          ? "every section has been checked since it last changed — nothing to re-read."
          : "no section carries an open finding — nothing to edit.";
    return {
      slug, role, d, view, agent: agentName, budget, parallel, clamped, writeMode,
      only, items: 0, waves: [], slices: [], hint,
    };
  }

  // Pack in outline order, and NEVER split a section — a writer given half a
  // section writes half an idea. Sections that reference each other (Goals ↔
  // Non-goals, Alternatives ↔ Detailed design) share an `affinity` and are kept
  // in the SAME agent wherever the budget allows: cross-agent consistency is
  // expensive to check and free to prevent.
  const groups = [];
  for (const it of items) {
    const last = groups[groups.length - 1];
    if (last && it.affinity && last.affinity === it.affinity) last.items.push(it);
    else groups.push({ affinity: it.affinity, items: [it] });
  }
  const slices = [];
  let cur = null;
  const push = (sections, oversized) => {
    cur = { sections: [...sections], budget_lines: sections.reduce((a, x) => a + x.budget_lines, 0), oversized: !!oversized };
    slices.push(cur);
  };
  for (const g of groups) {
    const total = g.items.reduce((a, x) => a + x.budget_lines, 0);
    if (total <= budget) {
      if (cur && !cur.oversized && cur.budget_lines + total <= budget) {
        cur.sections.push(...g.items);
        cur.budget_lines += total;
      } else push(g.items, false);
      continue;
    }
    // The group does not fit whole: split it, still never splitting a section.
    for (const it of g.items) {
      if (it.budget_lines > budget) {
        // A single section over the cap is a PLANNING SMELL, not something to
        // dispatch anyway: the lane offers to split it into sub-sections at the
        // outline gate rather than handing a writer an over-budget slice.
        push([it], true);
        cur = null;
        continue;
      }
      if (cur && !cur.oversized && cur.budget_lines + it.budget_lines <= budget) {
        cur.sections.push(it);
        cur.budget_lines += it.budget_lines;
      } else push([it], false);
    }
  }

  const agent = agentName;
  const allWaves = [];
  for (let i = 0; i < slices.length; i += parallel) {
    const group = slices.slice(i, i + parallel);
    allWaves.push({
      n: allWaves.length + 1,
      agents: group.map((s) => {
        const out = {
          agent,
          sections: s.sections.map((x) => x.id),
          headings: s.sections.map((x) => x.heading),
          budget_lines: s.budget_lines,
          oversized: !!s.oversized,
        };
        // ONE ENTRY PER SECTION — and per SUB-PART for a nested section. The
        // singular `part` is kept as parts[0].file for one release, because
        // `next` output gets copied into notes and scripts.
        const anchorsFor = (x, file) => (x.findings || []).filter((f) => f.file === file);
        if (role !== "check" || v2)
          out.parts = s.sections.flatMap((x) =>
            (x.subsections || []).length
              ? x.subsections.map((sub) => ({
                  id: x.id, subsection: sub.id, file: sub.file, heading: sub.heading,
                  purpose: x.purpose, budget_lines: x.budget_lines,
                  findings: anchorsFor(x, sub.file),
                }))
              : [{
                  id: x.id, subsection: null, file: x.part, heading: x.heading,
                  purpose: x.purpose, budget_lines: x.budget_lines,
                  findings: anchorsFor(x, x.part),
                }]
          );
        if (out.parts && out.parts.length) out.part = out.parts[0].file;
        if (!v2 && (role === "check" || role === "edit")) {
          // v1 documents keep the RANGE form on the alias path:
          // Read(file_path, offset=start, limit=end-start+1).
          out.range = [s.sections[0].start, s.sections[s.sections.length - 1].end];
          out.read_limit = out.range[1] - out.range[0] + 1;
        }
        if (v2 && role === "check") {
          out.files = s.sections.flatMap((x) => x.files || []);
          out.changed_subparts = s.sections.flatMap((x) => x.changed_subparts || []);
        }
        return out;
      }),
    });
  }

  return {
    slug, role, d, view, agent, budget, parallel, clamped, writeMode, only,
    items: items.length,
    // ALL waves. The `partial` truncation is the COMMAND's, never the shape's:
    // a forecast is telling the user what the whole document costs.
    waves: allWaves,
    slices,
    hint: null,
  };
}

function docPlanCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const shape = docPlanShape(claudeDir, slugArg);
  if (!shape) return docNoSuch(asJson, slugArg);
  if (shape.bad_role) {
    if (asJson) emitJson({ ok: false, reason: "bad-role", hint: `--role must be one of: ${DOC_ROLES.join(", ")}` }, 2);
    console.error(`❌ --role must be one of: ${DOC_ROLES.join(", ")}`);
    process.exit(2);
  }
  const { slug, role, d, agent, budget, parallel, clamped, writeMode, only, allWaves = shape.waves } = shape;

  if (!shape.items) {
    if (asJson)
      emitJson(
        {
          ok: true, slug, role, agent, budget_lines: budget, parallel, clamped,
          write_mode: writeMode, waves: [], agents: 0, more_waves: 0, only: only.length ? only : null,
          oversized: [], hint: shape.hint,
          doc_rules: docRulesBlocksOf(d.doc_rules),
          doc_rules_text: docRulesSlice(docRulesBlocksOf(d.doc_rules)),
          doc_rules_boundary: DOC_RULES_BOUNDARY,
          template_locked: docLock(d).locked,
          allowed_headings: docLock(d).locked ? docLock(d).headings : null,
          note: "no section is ever split across two agents, and no two agents ever share a file",
        },
        1
      );
    console.log(shape.hint);
    process.exit(1);
  }

  // PARTIAL is a first-class mode, and it returns WAVE 1 ONLY — the rest cannot
  // be bought by accident. This is the single biggest saving in the lane: you
  // read what wave 1 wrote and redirect before waves 2..N are paid for.
  const partial = role === "write" && writeMode === "partial" && !only.length;
  const waves = partial ? allWaves.slice(0, 1) : allWaves;
  const agents = waves.reduce((a, w) => a + w.agents.length, 0);

  // The wave list is PERSISTED so `K of N` can be DERIVED later by counting
  // waves whose sections are all hash-confirmed — never claimed by a model.
  if (role === "write" && !only.length) {
    d.plan = { role, at: fmtStamp(new Date()), waves: allWaves.map((w) => w.agents.flatMap((a) => a.sections)) };
    docWrite(claudeDir, slug, d);
  }

  const payload = {
    ok: true,
    slug,
    role,
    agent,
    budget_lines: budget,
    parallel,
    clamped,
    write_mode: writeMode,
    waves,
    agents,
    more_waves: partial ? allWaves.length - 1 : 0,
    only: only.length ? only : null,
    oversized: shape.slices.filter((s) => s.oversized).map((s) => s.sections[0].id),
    hint: null,
    // HOUSE RULES ARE READ FIRST. They ride on the plan, not on each agent,
    // because they are identical for every dispatch in the run — and the SKILL
    // puts them at the very top of every slice, above ORC's own generation
    // rules. That order is the contract.
    doc_rules: docRulesBlocksOf(d.doc_rules),
    doc_rules_text: docRulesSlice(docRulesBlocksOf(d.doc_rules)),
    doc_rules_boundary: DOC_RULES_BOUNDARY,
    // THE CAGE, on every write item. A writer may not add, rename, merge or drop
    // a heading; what does not fit is a gap.
    template_locked: docLock(d).locked,
    allowed_headings: docLock(d).locked ? docLock(d).headings : null,
    note: "no section is ever split across two agents, and no two agents ever share a file",
  };
  if (asJson) emitJson(payload, 0);
  console.log(ui.header(`ORC · doc plan — ${slug} · ${role}`));
  if (clamped)
    console.log(
      `\n  ⚠ doc_max_parallel ${clamped.from} clamped to the hard cap ${clamped.to} — ` +
        "more parallel writers is more chances for the outline to drift."
    );
  for (const w of waves) {
    console.log(`\n  wave ${w.n}`);
    for (const a of w.agents)
      console.log(
        `    ${a.agent}  ${String(a.budget_lines).padStart(4)}L  ${a.sections.join(" + ")}` +
          (a.range ? `   lines ${a.range[0]}..${a.range[1]}` : "") +
          (a.oversized ? "   ⚠ over budget — split it, or store it in parts" : "")
      );
  }
  console.log(`\n  ${plural(agents, "agent")} across ${plural(waves.length, "wave")}.`);
  console.log(`  ${docRulesLine(payload.doc_rules)}   ${ui.color.gray("— read first in every slice")}`);
  if (payload.template_locked)
    console.log(
      `  template:  LOCKED to ${payload.allowed_headings.length} headings   ` +
        ui.color.gray("— a writer may not add, rename, merge or drop one; what does not fit is a gap")
    );
  if (partial)
    console.log(
      ui.color.gray(
        `  partial mode: ${plural(payload.more_waves, "later wave")} not returned. Read wave 1's files, then ask for the next.`
      )
    );
  process.exit(0);
}

// ── extract → edit the part → splice back (§5.6) ────────────────────────────
// v0.49.0: both survive as THIN ALIASES for one release. `orc doc next` output
// gets copied into notes and scripts, and a v1 document mid-flight still emits
// them. In v2 the section file IS the extract, so `extract` makes no copy.
function docExtractCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  // NO lazy migration here: a v1 document must reach the v1 extract, so its
  // recorded hash still guards the splice that follows.
  const d0 = slug ? docRead(claudeDir, slug) : null;
  if (d0 && d0.version >= DOC_STATE_VERSION) {
    const p = docPaths(claudeDir, slug);
    const want = String(docOpt("--section") || "");
    const entry = (d0.outline || []).find((x) => x.id === want || x.id.startsWith(want));
    const src = entry ? docSectionSource(p, entry) : null;
    if (!entry || !src || !src.text) {
      const hint = `no written section "${want}" in ${slug} — \`orc doc parts ${slug}\` lists them.`;
      if (asJson) emitJson({ ok: false, reason: "no-such-section", slug, section: want || null, hint }, 2);
      console.error("❌ " + hint);
      process.exit(2);
    }
    const hash = docHash(src.text);
    const prev = d0.sections[entry.id] || {};
    d0.sections[entry.id] = { ...prev, source_hash: prev.source_hash || hash };
    docWrite(claudeDir, slug, d0);
    if (asJson) emitJson({ ok: true, slug, section: entry.id, files: src.files, file: src.files[0], lines: docLines(src.text).length, hash, alias: "extract" }, 0);
    console.log(`✓ ${entry.id} already lives at ${src.files[0]} — the section file IS the source, so nothing was copied.`);
    console.log(`  Edit it, then: orc doc compile ${slug}`);
    process.exit(0);
  }
  const view = slug ? docMapView(claudeDir, slug) : null;
  if (!view) return docNoSuch(asJson, slugArg);
  if (!view.document || !fs.existsSync(view.document)) {
    if (asJson) emitJson({ ok: false, reason: "no-document", slug }, 2);
    console.error(`❌ no ${DOC_FILE} yet for ${slug}.`);
    process.exit(2);
  }
  const want = String(docOpt("--section") || "");
  const s = view.sections.find((x) => x.id === want) || view.sections.find((x) => x.id.startsWith(want));
  if (!s) {
    const hint = `no section "${want}" in ${slug} — \`orc doc map ${slug}\` lists them.`;
    if (asJson) emitJson({ ok: false, reason: "no-such-section", section: want || null, hint }, 2);
    console.error("❌ " + hint);
    process.exit(2);
  }
  const scanned = view.scan.sections.find((x) => x.id === s.id);
  const p = view.paths;
  fs.mkdirSync(p.work, { recursive: true });
  const rel = `${DOC_WORK}/${s.id}.md`;
  fs.writeFileSync(path.join(p.folder, rel), scanned.text.replace(/\s*$/, "") + "\n");
  const d = view.d;
  d.extracts[s.id] = { file: rel, hash: s.hash, start: s.start, end: s.end, at: fmtStamp(new Date()) };
  docWrite(claudeDir, slug, d);
  if (asJson) emitJson({ ok: true, slug, section: s.id, file: rel, start: s.start, end: s.end, lines: s.lines, hash: s.hash }, 0);
  console.log(`✓ ${s.id} extracted to ${rel}  (lines ${s.start}..${s.end}, ${s.lines} L)`);
  console.log(`  Edit ONLY that file. Then: orc doc splice ${slug}`);
  process.exit(0);
}

function docSpliceCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d0 = slug ? docRead(claudeDir, slug) : null;
  if (!d0) return docNoSuch(asJson, slugArg);
  // A v1-era recorded `.work/` part is drained into sections/ first, hash-guarded
  // exactly as before — the refuse-by-name block below is preserved verbatim on
  // the v1 path, because two sessions on one slug is still a real risk.
  if (d0.version >= DOC_STATE_VERSION || !Object.keys(d0.extracts || {}).length) {
    docMigrateV2(claudeDir, slug);
    return docCompileCmd(claudeDir, slugArg, { alias: "splice" });
  }
  const view = slug ? docMapView(claudeDir, slug) : null;
  if (!view) return docNoSuch(asJson, slugArg);
  const d = view.d;
  const p = view.paths;
  const ids = Object.keys(d.extracts || {});
  if (!ids.length) {
    if (asJson) emitJson({ ok: true, slug, spliced: [], hint: "nothing is extracted" }, 1);
    console.log("nothing is extracted — `orc doc extract <slug> --section <id>` first.");
    process.exit(1);
  }
  const live = new Map(view.sections.map((s) => [s.id, s]));
  // REFUSE on a conflict, by section NAME. The user edited that section while we
  // were working, and overwriting a human's paragraph is unrecoverable from this
  // lane's side — the part file is gone and their wording with it.
  const conflicts = [];
  const missing = [];
  for (const id of ids) {
    const rec = d.extracts[id];
    const s = live.get(id);
    if (!s) {
      missing.push(id);
      continue;
    }
    if (s.hash !== rec.hash) conflicts.push({ id, heading: s.heading, was: rec.hash.slice(0, 8), now: s.hash.slice(0, 8) });
    if (!fs.existsSync(path.join(p.folder, rec.file))) missing.push(id);
  }
  if (conflicts.length || missing.length) {
    const payload = {
      ok: false,
      reason: conflicts.length ? "hash-conflict" : "missing-part",
      slug,
      conflicts,
      missing,
      hint: conflicts.length
        ? `these sections changed on disk after they were extracted: ${conflicts.map((c) => c.heading).join(", ")}. ` +
          "Nothing was written. Ask before overwriting — a human's wording is not recoverable from here."
        : `these part files are missing: ${missing.join(", ")}`,
    };
    if (asJson) emitJson(payload, 1);
    console.error("❌ " + payload.hint);
    process.exit(1);
  }

  // BOTTOM-UP (highest start first), so an edit that changes a section's length
  // never shifts a range that has not been spliced yet. This is why the model
  // never does line arithmetic.
  const order = ids
    .map((id) => ({ id, ...d.extracts[id], live: live.get(id) }))
    .sort((a, b) => b.live.start - a.live.start);
  let lines = docLines(fs.readFileSync(p.document, "utf8"));
  const spliced = [];
  for (const e of order) {
    const body = docLines(fs.readFileSync(path.join(p.folder, e.file), "utf8"));
    while (body.length && !/\S/.test(body[body.length - 1])) body.pop();
    const before = e.live.end - e.live.start + 1;
    lines.splice(e.live.start - 1, before, ...body);
    spliced.push({ id: e.id, heading: e.live.heading, was_lines: before, now_lines: body.length, delta: body.length - before });
  }
  fs.writeFileSync(p.document, lines.join("\n").replace(/\n{3,}/g, "\n\n").replace(/\s*$/, "") + "\n");

  d.extracts = {};
  d.cycle = (d.cycle || 0) + 1;
  const body = fs.readFileSync(p.document, "utf8");
  const after = docScan(body);
  const rec = docReconcile(d, after);
  docApplyRepairs(d, rec.repairs);
  after.sections = rec.sections;
  for (const s of after.sections) {
    const prev = d.sections[s.id] || {};
    const touched = spliced.some((x) => x.id === s.id);
    d.sections[s.id] = {
      ...prev,
      hash: s.hash,
      state: touched ? "written" : prev.state || "written",
      cycle: touched ? d.cycle : prev.cycle || d.cycle,
      findings: touched ? 0 : prev.findings || 0,
    };
  }
  d.cycles.push({ n: d.cycle, at: fmtStamp(new Date()), kind: "edit", agents: spliced.length, sections: spliced.map((s) => s.id) });
  docWrite(claudeDir, slug, d);

  const lint = docLintRun(body, d.target, docLintOpts(claudeDir, d));
  const payload = {
    ok: true,
    slug,
    spliced,
    lines: after.total_lines,
    lint: { errors: lint.errors, warnings: lint.warnings },
    note: "the map and the lint were re-derived after the write — no line number in this system is ever stale",
  };
  if (asJson) emitJson(payload, 0);
  console.log(`✓ ${plural(spliced.length, "section")} spliced back, bottom-up.`);
  for (const s of spliced) console.log(`    ${s.id.padEnd(30)} ${s.was_lines} → ${s.now_lines} L  (${s.delta >= 0 ? "+" : ""}${s.delta})`);
  console.log(`\n  ${DOC_FILE} is now ${after.total_lines} lines · lint ${lint.errors} errors, ${lint.warnings} warnings`);
  console.log(ui.color.gray("  Bottom-up: the highest section is replaced first, so no range shifts before it is used."));
  process.exit(0);
}

// ── compile — `document.md` is a BUILD ARTIFACT (v0.49.0) ───────────────────
// ZERO model tokens, zero subprocess, zero shell script. It is Node code in this
// same process, which is better than a shell step: no quoting, identical on
// Windows, and it can re-derive doc.json in the same pass. Measured cost is I/O
// only — outline.length reads, one write, one docScan.
//
// Anyone who claims v0.49.0 made compiling cheaper is selling something: it was
// already free. The saving is early review, a resumable wave, no round trip and
// bounded reads.
function docCompileCmd(claudeDir, slugArg, opts) {
  const o = opts || {};
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const pv = slug ? docPartsView(claudeDir, slug) : null;
  if (!pv) return docNoSuch(asJson, slugArg);
  docMigrateV2(claudeDir, slug);
  const view = docPartsView(claudeDir, slug);
  const d = view.d;
  const p = view.paths;
  const partial = o.partial || flag("--partial");
  const strip = flag("--strip-annotations");
  const alias = o.alias || null;

  const present = [];
  const missing = [];
  const skippedOptional = [];
  const problems = [];
  for (const row of view.rows) {
    const entry = d.outline.find((x) => x.id === row.id);
    const src = docSectionSource(p, entry);
    if (src.problems.length) problems.push(...src.problems);
    if (src.text) present.push({ o: entry, src, row });
    else if (row.required) missing.push({ id: row.id, heading: row.heading });
    else skippedOptional.push(row.id);
  }

  // A nested section that would restructure the deliverable is a REFUSAL, named
  // by file. Never a silent demote, never a silent promote.
  if (problems.length) {
    const hint = "cannot compile — " + problems.map((x) => x.what).join("  ·  ");
    if (asJson) emitJson({ ok: false, reason: "subpart-shape", slug, problems, hint }, 1);
    console.error("❌ " + hint);
    process.exit(1);
  }

  if (missing.length && !partial) {
    const hint =
      `cannot compile — ${plural(missing.length, "required section")} ${missing.length === 1 ? "has" : "have"} no source file: ` +
      missing.map((m) => m.id).join(", ") +
      ". Write them, or see what exists so far with --partial.";
    if (asJson) emitJson({ ok: false, reason: "missing-part", slug, missing: missing.map((m) => m.id), hint }, 1);
    console.error("❌ " + hint);
    process.exit(1);
  }

  // Partial: a missing section is simply ABSENT. It is NOT stubbed with a note —
  // the deliverable carries content only. The omission is reported loudly
  // OUTSIDE the document: here, in `status`, in `next` and in `audit`.
  // `00-front.md` is reserved for anything above the first `## ` — front matter
  // for a Docusaurus target, an exec summary a human typed, the H1 itself. It
  // survives a round trip instead of being regenerated, which is what makes
  // `split` → `compile` byte-for-byte.
  const out = [];
  let front = null;
  if (p.front && fs.existsSync(p.front)) front = docTrimPart(fs.readFileSync(p.front, "utf8"));
  if (front) out.push(front, "");
  if (!front || !/^#\s/m.test(front)) out.push(`# ${d.title}`, "");
  for (const x of present) out.push(docSectionBody(x.o, x.src), "");

  let body = out.join("\n");
  const annotations = docAnnotations(body);
  let stripped = [];
  if (strip && annotations.length) {
    stripped = annotations.map((a) => a.quote);
    body = docLines(body).filter((l) => !DOC_ANNOTATION_RE.test(l)).join("\n");
  }
  // ONCE, at the very end — so a nested join is never normalised twice.
  body = body.replace(/\n{3,}/g, "\n\n").replace(/\s*$/, "") + "\n";

  fs.mkdirSync(p.folder, { recursive: true });
  fs.writeFileSync(p.document, body);

  d.cycle = (d.cycle || 0) + 1;
  const scan = docScan(body);
  // Re-key to the outline before recording a hash: a skipped optional section
  // shifts every ordinal after it, and a hash filed under a positional id would
  // make the next `map` read the whole document as renamed.
  scan.sections = docReconcile(d, scan).sections;
  for (const s of scan.sections) {
    const prev = d.sections[s.id] || {};
    const row = view.rows.find((r) => r.id === s.id);
    d.sections[s.id] = {
      ...prev,
      hash: s.hash,
      state: row && row.state === "unconfirmed" ? "unconfirmed" : prev.state === "checked" ? "checked" : "written",
      cycle: d.cycle,
      findings: prev.findings || 0,
    };
  }
  // `source_hashes` IS the staleness mechanism, and it is why nothing has to be
  // remembered: `document.md` is stale ⇔ some section's source hashes
  // differently today than this recorded. Pure disk comparison.
  const sourceHashes = {};
  for (const x of present) sourceHashes[x.o.id] = x.row.hash;
  d.compiled = {
    at: fmtStamp(new Date()),
    cycle: d.cycle,
    partial: !!missing.length,
    sections: present.map((x) => x.o.id),
    missing: missing.map((m) => m.id),
    source_hashes: sourceHashes,
  };
  d.cycles.push({
    n: d.cycle,
    at: fmtStamp(new Date()),
    kind: "compile",
    role: "compile",
    agents: 0,
    sections: present.map((x) => x.o.id),
  });
  docWrite(claudeDir, slug, d);
  docWriteOutline(claudeDir, slug, d);

  const lint = docLintRun(body, d.target, docLintOpts(claudeDir, d));
  const mv = docMapView(claudeDir, slug);
  const after = docPartsView(claudeDir, slug);
  const payload = {
    ok: true,
    slug,
    file: path.relative(p.root, p.document).split(path.sep).join("/"),
    sections: scan.sections.length,
    lines: scan.total_lines,
    partial: !!missing.length,
    missing: missing.map((m) => ({ id: m.id, heading: m.heading })),
    skipped_optional: skippedOptional,
    annotations,
    stripped,
    lint: { errors: lint.errors, warnings: lint.warnings },
    where: docWhereLine(d, mv, { rows: after.rows, wave: docWaveState(d, after.rows) }),
    note: "document.md is a BUILD ARTIFACT — the files under sections/ are the source of truth",
  };
  if (asJson) emitJson(payload, 0);
  if (alias) console.log(ui.color.gray(`  \`orc doc ${alias}\` is now \`orc doc compile\` — same result, and the section files are the source.`));
  console.log(`✓ compiled ${plural(scan.sections.length, "section")} → ${p.document}  (${scan.total_lines} lines)`);
  if (missing.length)
    console.log(
      ui.color.yellow(`  PARTIAL — ${plural(missing.length, "required section")} not written yet: `) +
        missing.map((m) => m.heading).join(", ") +
        "\n  " +
        ui.color.gray("Absent, not stubbed. The document carries content only.")
    );
  if (annotations.length && !strip)
    console.log(
      ui.color.yellow(`  ${plural(annotations.length, "ORC annotation")} still in the body`) +
        ` (first at line ${annotations[0].line}). Reported, never silently removed — we cannot tell whose line it is.` +
        `\n  Remove them with:  orc doc compile ${slug} --strip-annotations`
    );
  if (stripped.length) console.log(ui.color.gray(`  stripped ${plural(stripped.length, "annotation")} on your explicit request.`));
  console.log(`  lint: ${lint.errors} errors, ${lint.warnings} warnings  ·  run \`orc doc lint ${slug}\` for the detail`);
  process.exit(0);
}

// ── parts — the wave-boundary command, and it works before any compile ──────
// `--confirm <ids>` is how a VALIDATED RETURN becomes a recorded hash. Until
// then a part file on disk is `unconfirmed`: a writer killed by a usage limit
// leaves a truncated file, and detection is already paid for.
function docPartsCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  if (!slug || !docRead(claudeDir, slug)) return docNoSuch(asJson, slugArg);
  docMigrateV2(claudeDir, slug);

  const confirm = String(docOpt("--confirm") || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  if (confirm.length) {
    const view = docPartsView(claudeDir, slug);
    const d = view.d;
    const unknown = [];
    const empty = [];
    const drifted = [];
    const confirmed = [];
    for (const want of confirm) {
      const row = view.rows.find((r) => r.id === want || r.id.startsWith(want));
      if (!row) {
        unknown.push(want);
        continue;
      }
      if (!row.exists) {
        empty.push(row.id);
        continue;
      }
      const entry = d.outline.find((x) => x.id === row.id);
      const src = docSectionSource(view.paths, entry);
      // v0.49.2 — under a TEMPLATE LOCK, a part whose headings drifted is
      // REFUSED and NOTHING is written: the `splice` hash-conflict refusal
      // shape. Confirming it would record a hash for a section that is no longer
      // the section the template declared.
      const lock = docLock(d);
      if (lock.locked) {
        const allowed = new Set(lock.headings.concat((entry.subsections || []).map((x) => x.heading)));
        const stray = docScan(src.text || "").headings.filter((h) => h.level >= 2 && !allowed.has(h.heading));
        if (stray.length) {
          drifted.push({ id: row.id, headings: stray.map((h) => h.heading) });
          continue;
        }
      }
      const prev = d.sections[row.id] || {};
      const parts = {};
      for (const pt of src.parts) if (pt.sub) parts[pt.sub] = pt.hash;
      d.sections[row.id] = { ...prev, source_hash: row.hash, state: "written", cycle: d.cycle || 0, findings: prev.findings || 0, parts };
      confirmed.push(row.id);
    }
    if (unknown.length || empty.length || drifted.length) {
      const hint =
        (unknown.length ? `no such section: ${unknown.join(", ")}. ` : "") +
        (empty.length ? `nothing on disk for: ${empty.join(", ")} — a return cannot confirm a file that was never written. ` : "") +
        (drifted.length
          ? `outside the locked template: ` +
            drifted.map((x) => `${x.id} adds "${x.headings.join('", "')}"`).join("; ") +
            `. Nothing was written. Remove the heading, or unlock the template deliberately. `
          : "");
      const reason = unknown.length ? "no-such-section" : drifted.length ? "template-drift" : "no-source";
      if (asJson) emitJson({ ok: false, reason, slug, unknown, empty, drifted, confirmed: [], hint }, 1);
      console.error("❌ " + hint);
      process.exit(1);
    }
    docWrite(claudeDir, slug, d);
  }

  const view = docPartsView(claudeDir, slug);
  const d = view.d;
  const wave = docWaveState(d, view.rows);
  const problems = view.rows.flatMap((r) => r.problems.map((x) => ({ id: r.id, ...x })));
  const missing = view.rows.filter((r) => r.required && !r.exists).map((r) => r.id);
  const unconfirmed = view.rows.filter((r) => r.state === "unconfirmed").map((r) => r.id);
  const misnumbered = view.rows.filter((r) => !r.ordinal_ok).map((r) => r.id);
  const payload = {
    ok: true,
    slug,
    dir: path.relative(view.paths.root, view.paths.sections).split(path.sep).join("/"),
    front: view.front,
    confirmed: confirm.length ? confirm : [],
    parts: view.rows.map(({ id, heading, required, files, nested, exists, lines, hash, state, subsections, ordinal_ok, findings }) => ({
      id, heading, required, files, nested, exists, lines, hash, state, subsections, ordinal_ok, findings,
    })),
    total: view.rows.length,
    written: view.rows.filter((r) => r.state === "written" || r.state === "checked").length,
    missing,
    unconfirmed,
    misnumbered,
    problems,
    wave,
    note: "the section files ARE the progress — there is no checkpoint file to invent and none to drift",
  };
  const code = missing.length || unconfirmed.length ? 1 : 0;
  if (asJson) emitJson(payload, code);
  console.log(ui.header(`ORC · doc parts — ${slug}`));
  if (wave) console.log(`\n  wave ${wave.done} of ${wave.total} confirmed`);
  console.log("");
  for (const r of view.rows) {
    console.log(
      `  ${r.state.padEnd(12)} ${String(r.lines).padStart(4)}L  ${r.id.padEnd(32)} ${r.files[0] || ui.color.gray("(not written)")}` +
        (r.ordinal_ok ? "" : ui.color.yellow("   ⚠ number does not mirror the outline"))
    );
    for (const s of r.subsections)
      console.log(`  ${"".padEnd(12)} ${String(s.lines).padStart(4)}L    ${s.id.padEnd(30)} ${s.file || ui.color.gray("(not written)")}`);
  }
  if (unconfirmed.length)
    console.log(
      ui.color.yellow(`\n  ${plural(unconfirmed.length, "part")} on disk with no validated return: `) +
        unconfirmed.join(", ") +
        "\n  " +
        ui.color.gray("A wave killed mid-flight leaves exactly this. It is re-written, never shipped.")
    );
  process.exit(code);
}

// ── split — the reverse direction, also free ────────────────────────────────
// `docScan` already returns every `##` section with its exact text and
// `docReconcile` already re-keys those to outline ids. So decomposing a monolith
// costs nothing, and it is what the migration uses — and what recovers a
// document a human reshaped by hand in an editor.
function docSplitSections(claudeDir, slug, d, p) {
  if (!fs.existsSync(p.document)) return { written: [], front: null, reason: "no-document" };
  const text = fs.readFileSync(p.document, "utf8");
  const scan = docScan(text);
  if (!scan.sections.length) return { written: [], front: null, reason: "no-headings" };
  const rec = docReconcile(d, scan);
  docApplyRepairs(d, rec.repairs);
  fs.mkdirSync(p.sections, { recursive: true });
  const written = [];
  for (const s of rec.sections) {
    // A section body that is nothing but a `> **Open:**` stub does NOT survive
    // into v2. It becomes `planned`, so the pipeline offers to write it.
    const bodyOnly = docLines(s.text).slice(1).filter((l) => /\S/.test(l));
    if (bodyOnly.length && bodyOnly.every((l) => DOC_ANNOTATION_RE.test(l))) continue;
    const file = docSectionFile(p, s.id);
    fs.writeFileSync(file, s.text.replace(/\s*$/, "") + "\n");
    written.push({ id: s.id, file: docRelFolder(p, file), lines: s.lines });
  }
  let front = null;
  if (scan.preamble_end > 0) {
    const pre = docLines(text).slice(0, scan.preamble_end).join("\n").replace(/\s*$/, "");
    if (/\S/.test(pre)) {
      fs.writeFileSync(p.front, pre + "\n");
      front = docRelFolder(p, p.front);
    }
  }
  return { written, front, repairs: rec.repairs, reason: null };
}

// Cut ONE existing flat section on its own `###` headings, so a big section
// stores as sub-parts without the reader ever knowing. The deliverable's
// structure is never changed to solve ORC's storage problem.
function docSplitByHeading(p, d, id) {
  const entry = (d.outline || []).find((x) => x.id === id || x.id.startsWith(id));
  if (!entry) return { ok: false, reason: "no-such-section" };
  const flat = docSectionFile(p, entry.id);
  if (!fs.existsSync(flat)) return { ok: false, reason: "no-source" };
  const text = fs.readFileSync(flat, "utf8");
  const lines = docLines(text);
  const scan = docScan(text);
  const h3 = scan.headings.filter((h) => h.level === 3);
  if (!h3.length) return { ok: false, reason: "no-subheadings" };
  const slugs = h3.map((h) => docSlugify(h.heading));
  if (new Set(slugs).size !== slugs.length) return { ok: false, reason: "ambiguous-subheadings" };

  const dir = docSectionDir(p, entry.id);
  fs.mkdirSync(dir, { recursive: true });
  const outFiles = [];
  const head = lines.slice(0, h3[0].line - 1).join("\n").replace(/\s*$/, "");
  fs.writeFileSync(path.join(dir, DOC_HEAD_FILE), head + "\n");
  outFiles.push(docRelFolder(p, path.join(dir, DOC_HEAD_FILE)));
  const subs = [];
  h3.forEach((h, i) => {
    const end = i + 1 < h3.length ? h3[i + 1].line - 1 : lines.length;
    const sid = docSectionId(i + 1, h.heading);
    const f = path.join(dir, sid + ".md");
    fs.writeFileSync(f, lines.slice(h.line - 1, end).join("\n").replace(/\s*$/, "") + "\n");
    subs.push({ id: sid, heading: h.heading, level: 3 });
    outFiles.push(docRelFolder(p, f));
  });
  fs.unlinkSync(flat);
  entry.subsections = subs;
  return { ok: true, id: entry.id, files: outFiles, subsections: subs };
}

function docSplitCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const p = docPaths(claudeDir, slug);
  const one = docOpt("--section");

  if (one || flag("--by-heading")) {
    const res = docSplitByHeading(p, d, one || "");
    if (!res.ok) {
      const hints = {
        "no-such-section": `no section "${one}" in ${slug} — \`orc doc parts ${slug}\` lists them.`,
        "no-source": `${one} has no source file yet — there is nothing to split.`,
        "no-subheadings": `${one} has no \`### \` headings, so there is nothing to cut on. Add sub-headings first, or make them real \`## \` sections at the outline gate.`,
        "ambiguous-subheadings": `${one} has two identical \`### \` headings. Ambiguous is a refusal, never a guess — rename one.`,
      };
      const code = res.reason === "no-such-section" ? 2 : 1;
      if (asJson) emitJson({ ok: false, reason: res.reason, slug, section: one || null, hint: hints[res.reason] }, code);
      console.error("❌ " + hints[res.reason]);
      process.exit(code);
    }
    docWrite(claudeDir, slug, d);
    docWriteOutline(claudeDir, slug, d);
    if (asJson) emitJson({ ok: true, slug, section: res.id, files: res.files, subsections: res.subsections }, 0);
    console.log(`✓ ${res.id} stored as ${plural(res.files.length, "part")} under sections/${res.id}/`);
    for (const f of res.files) console.log(`    ${f}`);
    console.log(ui.color.gray("\n  Invisible to the reader: the compiled document still has exactly one `## ` for this section."));
    process.exit(0);
  }

  const res = docSplitSections(claudeDir, slug, d, p);
  if (res.reason) {
    const hint =
      res.reason === "no-document"
        ? `no ${DOC_FILE} for ${slug} — there is nothing to split. The section files are already the source.`
        : `${DOC_FILE} has no \`## \` headings at all. A structure is never guessed out of prose, so nothing was written.`;
    const code = res.reason === "no-document" ? 1 : 2;
    if (asJson) emitJson({ ok: false, reason: res.reason, slug, hint }, code);
    console.error("❌ " + hint);
    process.exit(code);
  }
  for (const w of res.written) {
    const prev = d.sections[w.id] || {};
    const entry = d.outline.find((x) => x.id === w.id);
    const src = entry ? docSectionSource(p, entry) : null;
    d.sections[w.id] = { ...prev, source_hash: src && src.text ? docHash(src.text) : null, state: prev.state === "checked" ? "checked" : "written" };
  }
  docWrite(claudeDir, slug, d);
  if (asJson) emitJson({ ok: true, slug, written: res.written, front: res.front, repaired: res.repairs || [] }, 0);
  console.log(`✓ ${plural(res.written.length, "section")} written to sections/`);
  for (const w of res.written) console.log(`    ${w.file.padEnd(46)} ${w.lines} L`);
  if (res.front) console.log(`    ${res.front.padEnd(46)} (everything above the first heading)`);
  process.exit(0);
}

// ── migration v1 → v2 — lazy, free, idempotent, non-destructive ─────────────
// A v1 document in flight must open, migrate and continue without the user
// knowing anything happened, and without losing a byte. Runs on the first
// `orc doc <anything> <slug>` where version < 2 — never on `list`, because a
// listing must not mutate.
function docMigrateV2(claudeDir, slug, opts) {
  const o = opts || {};
  const d = docRead(claudeDir, slug);
  if (!d || d.version >= DOC_STATE_VERSION) return null;
  const p = docPaths(claudeDir, slug);
  const notes = [];

  // Refuse rather than guess. A guessed structure is worse than none — the
  // `docInit` no-headings precedent.
  if (fs.existsSync(p.document)) {
    const scan = docScan(fs.readFileSync(p.document, "utf8"));
    if (!scan.sections.length)
      return {
        refused: true,
        slug,
        reason: "unparseable-document",
        hint:
          `${DOC_FILE} has no \`## \` headings, so its sections cannot be recovered. Nothing was written and the document stays on v1 — ` +
          "a guessed structure is worse than none.",
      };
  }

  fs.mkdirSync(p.sections, { recursive: true });
  let sections = [];

  if (fs.existsSync(p.document)) {
    const res = docSplitSections(claudeDir, slug, d, p);
    sections = res.written.map((w) => w.id);
    notes.push(`${plural(sections.length, "section")} recovered from ${DOC_FILE}; the file itself was NOT deleted — it is the build artifact now.`);
    if (res.front) notes.push("everything above the first heading kept in sections/00-front.md");
  }

  // A recorded extract is the NEWER edit, so it wins for that id.
  const extracts = Object.keys(d.extracts || {});
  for (const id of extracts) {
    const rec = d.extracts[id];
    const src = rec && rec.file ? path.join(p.folder, rec.file) : null;
    if (!src || !fs.existsSync(src)) continue;
    fs.writeFileSync(docSectionFile(p, id), fs.readFileSync(src, "utf8"));
    if (!sections.includes(id)) sections.push(id);
    notes.push(`${rec.file} was a pending extract — the newer edit, so it won for ${id}.`);
  }
  d.extracts = {};

  // Mid-write: part files exist and nothing was ever assembled. MOVE them.
  if (!fs.existsSync(p.document) && p.work && fs.existsSync(p.work)) {
    for (const f of fs.readdirSync(p.work).filter((x) => x.endsWith(".md"))) {
      const id = f.replace(/\.md$/, "");
      const dst = docSectionFile(p, id);
      if (fs.existsSync(dst)) continue;
      fs.writeFileSync(dst, fs.readFileSync(path.join(p.work, f), "utf8"));
      try { fs.unlinkSync(path.join(p.work, f)); } catch (_) {}
      if (!sections.includes(id)) sections.push(id);
    }
    if (sections.length) notes.push(`${plural(sections.length, "part file")} moved out of ${DOC_WORK}/ — nothing had been assembled yet.`);
  }

  // The v0.42.0 home is the only place `listRuns()` looks, which is why a
  // document paused by a usage limit never showed up in `orc run list`.
  const legacyResume = p.folder ? path.join(p.folder, RESUME_FILE) : null;
  if (legacyResume && fs.existsSync(legacyResume)) {
    const runDir = docRunDir(claudeDir, slug);
    if (runDir) {
      fs.mkdirSync(runDir, { recursive: true });
      // The `## ` prefix made `parseStands` — which is line-anchored — unable to
      // match the ONE line the whole listing contract depends on.
      const body = fs.readFileSync(legacyResume, "utf8").replace(/^#{1,6}\s+(Where it stands:)/m, "$1");
      fs.writeFileSync(path.join(runDir, RESUME_FILE), body);
      try { fs.unlinkSync(legacyResume); } catch (_) {}
      notes.push(`RESUME.md moved to ${path.relative(p.root, path.join(runDir, RESUME_FILE)).split(path.sep).join("/")} and its heading prefix stripped, so \`orc resume\` can finally see it.`);
    }
  }

  // Record the hashes now, so `document.md` starts life FRESH rather than stale.
  const sourceHashes = {};
  for (const entry of d.outline || []) {
    const src = docSectionSource(p, entry);
    if (!src.text) continue;
    const h = docHash(src.text);
    sourceHashes[entry.id] = h;
    const prev = d.sections[entry.id] || {};
    d.sections[entry.id] = { ...prev, source_hash: h, state: prev.state === "checked" ? "checked" : "written" };
  }
  if (fs.existsSync(p.document))
    d.compiled = { at: fmtStamp(new Date()), cycle: d.cycle || 0, partial: false, sections: Object.keys(sourceHashes), missing: [], source_hashes: sourceHashes };

  if (o.clean && p.work && fs.existsSync(p.work)) {
    try { fs.rmSync(p.work, { recursive: true, force: true }); notes.push(`${DOC_WORK}/ removed on your explicit request.`); } catch (_) {}
  }

  d.version = DOC_STATE_VERSION;
  d.migrations = Array.isArray(d.migrations) ? d.migrations : [];
  // NOT in the journal: `orc doc log` records what the USER said, and a
  // migration is a machine fact (hard rule 12).
  d.migrations.push({ from: 1, to: DOC_STATE_VERSION, at: fmtStamp(new Date()), sections, notes });
  docWrite(claudeDir, slug, d);
  return { refused: false, slug, from: 1, to: DOC_STATE_VERSION, sections, notes };
}

function docMigrateCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const already = d.version >= DOC_STATE_VERSION;
  const res = docMigrateV2(claudeDir, slug, { clean: flag("--clean") });
  if (res && res.refused) {
    if (asJson) emitJson({ ok: false, reason: res.reason, slug, hint: res.hint }, 1);
    console.error("❌ " + res.hint);
    process.exit(1);
  }
  if (already || !res) {
    if (asJson) emitJson({ ok: true, slug, migrated: false, version: DOC_STATE_VERSION, hint: "already on v2 — nothing to do" }, 0);
    console.log(`${slug} is already on v${DOC_STATE_VERSION}. Nothing to do.`);
    process.exit(0);
  }
  if (asJson) emitJson({ ok: true, slug, migrated: true, ...res }, 0);
  console.log(ui.header(`ORC · doc migrate — ${slug}  v1 → v${DOC_STATE_VERSION}`));
  console.log(`\n  ${plural(res.sections.length, "section")} now live under sections/, which is the source of truth.`);
  for (const n of res.notes) console.log(`    · ${n}`);
  console.log(ui.color.gray(`\n  ${DOC_FILE} was NOT deleted. It is the build artifact — rebuild it any time with \`orc doc compile ${slug}\`.`));
  process.exit(0);
}

// ── write mode — asked once per run, stored, enforced by `orc doc next` ─────
// Never decided per wave by the skill: that is remembered-not-dispatched
// protocol, the failure this repo has already paid for twice.
function docModeCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const set = docOpt("--set");
  if (set) {
    if (!DOC_WRITE_MODES.includes(set) || set === "ask") {
      const hint = `--set must be one of: ${DOC_WRITE_MODES.filter((m) => m !== "ask").join(", ")}`;
      if (asJson) emitJson({ ok: false, reason: "bad-mode", slug, hint }, 2);
      console.error("❌ " + hint);
      process.exit(2);
    }
    d.write_mode = set;
    docWrite(claudeDir, slug, d);
  }
  const cfg = resolvedConfig(claudeDir);
  const resolved = d.write_mode || (cfg.doc_write_mode === "ask" ? null : cfg.doc_write_mode);
  const payload = {
    ok: true,
    slug,
    write_mode: resolved,
    stored: d.write_mode || null,
    config_default: cfg.doc_write_mode,
    hint: resolved
      ? null
      : "unset — this is a decision, and it is asked once and stored. `partial` writes ONE wave so you can read it before the rest is paid for.",
  };
  if (asJson) emitJson(payload, 0);
  console.log(`write mode for ${slug}: ${resolved || "unset (ask)"}`);
  if (!resolved) console.log(ui.color.gray("  " + payload.hint));
  process.exit(0);
}

// ── orc doc extra <slug> — THE PER-DOCUMENT SWITCH (v0.52.0, D9) ──────────
//
// The mechanism already existed: `EXTRA_ROLES_ALL` carries `doc-writer` and
// `doc-checker`, and orc-doc's SKILL already states the stance. It was GLOBAL,
// and that is the defect: turning it on for a throwaway runbook turns it on for
// the PRD you ship to a customer, and a document's VOICE is the deliverable.
//
// Stored in `doc.json`, which already has exactly one writer (`docWrite`) and
// already stores `doc_write_mode` the same way. No new file, no new writer, and
// `RESUME.md` regenerates for free.
const DOC_EXTRA_MODES = ["off", "writer", "checker", "both"];
const DOC_EXTRA_ROLE_OF = { writer: "doc-writer", checker: "doc-checker" };

// Resolution, highest wins, and it is PRINTED:
//
//   doc.json.extra (this document) > the slot row exists > off
//
// v0.55.0 — `config.extra_roles` IS NO LONGER CONSULTED. It was a project-wide
// list that armed both roles at once, and its two doc members moved to the slot
// ledger (`orc extra role`) where a POSITION is chosen with a profile and a
// model. The per-document switch stays exactly as it was, because a runbook and
// a customer-facing PRD are different documents.
//
// A document set to `both` when only ONE position is held resolves to that one
// and SAYS SO — a shadowed setting must never be silent, the same rule
// `orc config set` follows when it names every key it makes inert.
//
// AND EACH ROLE RESOLVES ITS OWN TARGET. Before this release the hardcoded
// `edges:` field resolved `orc-doc-writer-opus-5-med` whatever `resolved` said,
// so a document set to `checker` reported the WRITER's band — a band it was not
// routing — while the checker actually runs at a different rung entirely.
function docExtraResolve(claudeDir, d) {
  const cfg = resolvedConfig(claudeDir);
  const roles = INLINE_LIST(cfg.extra_roles).filter(Boolean);
  const stored = DOC_EXTRA_MODES.includes(d.extra) ? d.extra : null;
  // The slot rows are the project-level floor now. A position with no row is
  // Claude, which is a correct answer rather than a gap.
  const held = {};
  for (const w of ["writer", "checker"])
    held[w] = extraResolveSlot(claudeDir, DOC_EXTRA_ROLE_OF[w], {});
  const heldNames = ["writer", "checker"].filter((w) => held[w].resolved === "extra");
  const slotMode = heldNames.length === 2 ? "both" : heldNames.length === 1 ? heldNames[0] : "off";
  const wanted = stored || slotMode;
  const want = wanted === "both" ? ["writer", "checker"] : wanted === "off" ? [] : [wanted];
  const granted = want.filter((w) => held[w].resolved === "extra");
  const resolved = granted.length === 2 ? "both" : granted.length === 1 ? granted[0] : "off";
  const shadowed = want.filter((w) => granted.indexOf(w) === -1);
  // A config still naming one of the retired roles warns ONCE, by name, and
  // arms nothing — the deprecation is visible where the decision is read.
  const legacyRoles = roles.filter((r) => LEGACY_EXTRA_ROLES.includes(r));
  return {
    resolved,
    stored,
    source: stored ? "doc.json" : heldNames.length ? "slot rows" : "off",
    config_roles: roles,
    order: ["doc.json (this document)", "the slot row exists (orc extra role)", "off"],
    // Never silent. The shadow is named, in both directions — and it now names
    // the missing SLOT ROW rather than a config key that no longer decides.
    shadowed_by_slots: shadowed,
    legacy_config_roles: legacyRoles,
    legacy_warning: legacyRoles.length
      ? `extra_roles still names ${legacyRoles.join(" and ")}. That moved to \`orc extra role\` in v0.55.0 and arms nothing here.`
      : null,
    why:
      resolved === "off"
        ? shadowed.length
          ? `this document asks for ${shadowed.join(" and ")}, and no slot row holds ${shadowed.map((w) => DOC_EXTRA_ROLE_OF[w]).join(" or ")} — so it resolves to OFF.`
          : "nothing in this document goes off Claude."
        : `${granted.join(" and ")} go off Claude for this document; every other role stays on Claude.` +
          (shadowed.length
            ? ` ${shadowed.join(" and ")} was asked for and no slot row holds ${shadowed.map((w) => DOC_EXTRA_ROLE_OF[w]).join(" or ")}, so it stays on Claude.`
            : ""),
    // ONE TARGET PER ROLE, each from its OWN slot. `null` where that role is not
    // going foreign — an em dash on any surface that renders it, never a
    // borrowed answer from the other role.
    targets: {
      writer: granted.includes("writer") ? held.writer : null,
      checker: granted.includes("checker") ? held.checker : null,
    },
  };
}

function docExtraCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const set = docOpt("--set");
  if (set) {
    if (!DOC_EXTRA_MODES.includes(set)) {
      const hint = `--set must be one of: ${DOC_EXTRA_MODES.join(", ")}`;
      if (asJson) emitJson({ ok: false, reason: "bad-mode", slug, hint }, 2);
      console.error("❌ " + hint);
      process.exit(2);
    }
    d.extra = set;
    docWrite(claudeDir, slug, d);
  }
  const r = docExtraResolve(claudeDir, d);
  const payload = {
    ok: true,
    slug,
    extra: r.resolved,
    stored: r.stored,
    source: r.source,
    options: DOC_EXTRA_MODES,
    resolve_order: r.order,
    config_roles: r.config_roles,
    shadowed_by_slots: r.shadowed_by_slots,
    legacy_config_roles: r.legacy_config_roles,
    legacy_warning: r.legacy_warning,
    why: r.why,
    // One per role, each from its own POSITION. A `null` here is an answer.
    targets: r.targets,
    // DEFAULT OFF, AND IT STAYS OFF. A document is the one artifact where the
    // model choice is visible in the output.
    default: "off",
  };
  if (asJson) emitJson(payload, 0);
  console.log(`extra for ${slug}: ${r.resolved}`);
  console.log(ui.color.gray("  " + r.why));
  for (const role of ["writer", "checker"]) {
    const t = r.targets[role];
    console.log(
      "  " +
        role.padEnd(8) +
        (t ? ui.color.cyan(`${t.provider}/${t.model}`) + ui.color.gray(`  via ${t.profile} — displaces ${t.claude.agent}`) : ui.color.gray("claude"))
    );
  }
  if (r.legacy_warning) console.log("  " + ui.mark.warn(r.legacy_warning));
  process.exit(0);
}

// ── gaps.md — DERIVED, CLI-written, never compiled in ───────────────────────
// This is where an Open question and an Assumption go now. The deliverable
// carries content only; ORC's uncertainty about it is real and is written down,
// just not inside the document the reader came for.
function docWriteGaps(claudeDir, slug, d) {
  const p = docPaths(claudeDir, slug);
  const rows = (d.journal || []).filter((e) => e.kind === "gap");
  if (!rows.length) {
    try { if (fs.existsSync(p.gaps)) fs.unlinkSync(p.gaps); } catch (_) {}
    return null;
  }
  const L = [
    "<!-- orc-doc:derived — written by the `orc doc` CLI from doc.json.",
    "     Record one with `orc doc log <slug> --kind gap --sections <id> --text \"…\"`. -->",
    "",
    `# Gaps — ${d.title}`,
    "",
    "Everything ORC could not anchor to the frozen context. It is NOT in the",
    "document: the deliverable carries content only.",
    "",
    "| # | Section | Kind | What is missing |",
    "|---|---|---|---|",
    ...rows.map((e, i) => `| ${i + 1} | ${(e.sections || []).join(", ") || "—"} | ${e.source === "assumption" ? "assumption" : "open"} | ${String(e.text).replace(/\|/g, "\\|").split("\n")[0]} |`),
    "",
  ];
  fs.writeFileSync(p.gaps, L.join("\n"));
  return p.gaps;
}

function docLintCmd(claudeDir, arg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, arg);
  let file = null;
  let target = docOpt("--target");
  let section = null;
  let subFiles = null;
  if (slug) {
    const p = docPaths(claudeDir, slug);
    const d = docRead(claudeDir, slug);
    file = p.document;
    if (!target) target = d.target;
    // v0.49.2 — lint ONE SECTION FILE and report PART-LOCAL line numbers. The
    // part file is what the writer opens, so those are the only line numbers a
    // revision round can act on. Re-derived on every call, never stored (rule 2).
    const want = String(docOpt("--section") || "");
    if (want) {
      const entry = (d.outline || []).find((x) => x.id === want || x.id.startsWith(want));
      const src = entry ? docSectionSource(p, entry) : null;
      if (!entry || !src || !src.files.length) {
        const hint = `no written section "${want}" in ${slug} — \`orc doc parts ${slug}\` lists them.`;
        if (asJson) emitJson({ ok: false, reason: "no-such-section", slug, section: want, hint }, 2);
        console.error("❌ " + hint);
        process.exit(2);
      }
      section = entry.id;
      subFiles = src.files;
      file = path.join(p.folder, src.files[0]);
    }
  } else if (arg) {
    file = path.isAbsolute(arg) ? arg : path.join(repoRootOf(claudeDir), arg);
  }
  if (!file || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
    const hint = `cannot read: ${arg || "(no slug or path given)"}`;
    if (asJson) emitJson({ ok: false, reason: "no-document", path: arg || null, hint }, 2);
    console.error("❌ " + hint);
    process.exit(2);
  }
  const res = docLintRun(fs.readFileSync(file, "utf8"), target, {
    ...docLintOpts(claudeDir, slug ? docRead(claudeDir, slug) : null),
    part: !!section,
  });
  const payload = {
    ok: true,
    slug: slug || null,
    // The path RELATIVE to the document folder when this is a section file —
    // `sections/03-goals.md` is what the user sees in their editor.
    file: (section ? subFiles[0] : file.split(path.sep).join("/")),
    section,
    files: subFiles,
    part_local: !!section,
    ...res,
  };
  const code = res.findings.length ? 1 : 0;
  if (asJson) emitJson(payload, code);
  console.log(ui.header(`orc doc lint — ${path.basename(file)}  →  ${res.target_label}`));
  console.log(
    `\n  ${res.errors} errors · ${res.warnings} warnings · ${res.lines} lines\n` +
      `  readability: avg ${res.readability.avg_sentence_words} words/sentence (bar ${res.readability.avg_bar}) · ` +
      `longest ${res.readability.longest_sentence_words} → L${res.readability.longest_sentence_line} · ` +
      `${res.readability.passive_constructions} passive · ${res.readability.undefined_acronyms.length} undefined acronyms\n`
  );
  for (const f of res.findings.slice(0, 60))
    console.log(`  ${f.id}  ${f.severity.padEnd(5)} ${String(f.line).padStart(5)}  ${f.what}`);
  if (res.findings.length > 60) console.log(`  … and ${res.findings.length - 60} more (use --json for all of them)`);
  if (res.import_note) console.log(ui.color.gray(`\n  ${res.target_label}: ${res.import_note}`));
  console.log(ui.color.gray("\n  " + res.honesty[0] + "\n  " + res.honesty[1]));
  process.exit(code);
}

// ── THE HAND-BACK: RESUME.md (v0.49.5) ──────────────────────────────────────
// One generator, and it is this one. `orc doc status` already computes the
// `Where it stands:` line; this builds the whole page around it, in the same
// plain words the lane speaks to a reader who does not write code.
//
// Why the CLI and not the skill: a hand-back the orchestrator is TOLD to write
// at every stop is a hand-back that goes missing on the one run that mattered —
// the one a usage limit killed. It is written on every doc.json write instead,
// so it exists from `orc doc init` onward and is never behind.
function docResumeBuild(claudeDir, slug) {
  const view = docMapView(claudeDir, slug);
  if (!view) return null;
  const d = view.d;
  const p = view.paths;
  const v2 = d.version >= DOC_STATE_VERSION;
  const pv = docPartsView(claudeDir, slug);
  const rows = v2 ? pv.rows : view.sections;
  const byId = new Map(rows.map((s) => [s.id, s]));
  const next = docNextAction(claudeDir, slug);
  const wave = docWaveState(d, pv.rows);
  const where = docWhereLine(d, view, { rows: v2 ? pv.rows : null, phase: next ? next.phase : null, wave });
  const open = d.outline.filter((o) => {
    const s = byId.get(o.id);
    return !s || s.state === "planned" || s.state === "open" || s.state === "unconfirmed";
  });
  const edited = rows.filter((s) => s.state === "user-edited");
  const rel = (abs) => (abs ? path.relative(p.root, abs).split(path.sep).join("/") : null);
  const hasDoc = !!view.document && fs.existsSync(view.document);

  const L = [
    "# Resume this document",
    "",
    "You do not need to remember anything. Open a new Claude Code session in this",
    "project and paste the line below. It reads what is already on disk.",
    "",
    "    /orc-doc resume " + slug,
    "",
    // COLUMN 0, always. `parseStands` is line-anchored, so a heading prefix here
    // means `orc resume`, `orc run list` and `orc doc list` all stop seeing it.
    where,
    "",
    "## What this document is",
    "",
    "- Title:      " + (d.title || slug),
    "- Kind:       " + String(d.type || "").toUpperCase(),
    "- Started:    " + (d.created_at || "unknown"),
    "- " + docRulesLine(docRulesBlocksOf(d.doc_rules)),
    "",
    "## Where the files are",
    "",
    "- Sections:   " + rel(p.sections) + "/   <- the source of truth, one file per section",
    "- Document:   " + (hasDoc ? rel(view.document) : rel(path.join(p.folder, DOC_FILE)) + "  (not built yet)"),
    "              This is a BUILD ARTIFACT. `orc doc compile " + slug + "` rebuilds it, free.",
    "- Context:    " + rel(p.folder) + "/context.md   <- the new session reads this, so you never",
    "              have to explain the same thing twice.",
    "",
  ];

  if (open.length) {
    L.push("## Not written yet", "");
    for (const o of open.slice(0, 40)) L.push("- " + o.heading);
    if (open.length > 40) L.push("- ... and " + (open.length - 40) + " more");
    L.push("");
  }
  if (edited.length) {
    L.push("## You edited these yourself", "");
    for (const s of edited) L.push("- " + s.heading);
    L.push("", "ORC will not touch them again unless you name them.", "");
  }

  L.push("## What happens next", "");
  if (next && next.command) {
    L.push("The next step is:", "", "    " + next.command, "");
    L.push(next.paid ? "That one costs model tokens." : "That one is free - it costs no model tokens.", "");
  } else if (next && next.blocked_by) {
    L.push("Nothing runs until you decide something:", "", "    " + next.blocked_by, "");
  }
  L.push(
    "The new session will:",
    "",
    "1. Read the context and the plan from disk. It will NOT ask you again what you",
    "   already answered.",
    "2. Carry on from where it stopped, and re-read nothing it already wrote.",
    "3. Ask you what should change - and it will not touch the document until you say.",
    "",
    "---",
    "",
    "Nothing here is staged or committed. If your team should see it:",
    "",
    "    git add " + rel(p.folder) + "/",
    ""
  );
  return { text: L.join("\n"), where, next, wave, open, edited, dir: docRunDir(claudeDir, slug) };
}

// `orc doc resume-file <slug>` — write the hand-back on demand, and print the
// two things a reader actually needs: where the file is, and the line to paste.
// The lane calls it before every question it asks, so "see RESUME.md" is never
// a promise about a file that is not there.
function docResumeFileCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  if (!slug) return docNoSuch(asJson, slugArg);
  const built = docResumeBuild(claudeDir, slug);
  if (!built) return docNoSuch(asJson, slugArg);
  const dir = docRunDir(claudeDir, slug);
  if (!dir) {
    if (asJson) emitJson({ ok: false, reason: "no-run-dir", slug, hint: "the run directory could not be resolved" }, 2);
    console.error("❌ the run directory could not be resolved");
    process.exit(2);
  }
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, RESUME_FILE);
  fs.writeFileSync(file, built.text);
  const payload = {
    ok: true,
    slug,
    file,
    where: built.where,
    paste: `/orc-doc resume ${slug}`,
    next: built.next ? { phase: built.next.phase, action: built.next.action, command: built.next.command, paid: built.next.paid, blocked_by: built.next.blocked_by } : null,
    wave: built.wave,
    open: built.open.map((o) => ({ id: o.id, heading: o.heading })),
    user_edited: built.edited.map((s) => ({ id: s.id, heading: s.heading })),
    lines: built.text.split("\n").length,
  };
  if (asJson) emitJson(payload, 0);
  console.log(ui.header(`ORC · doc resume-file — ${slug}`));
  console.log(`\n  ${built.where}`);
  console.log(`\n  Written:  ${file}`);
  console.log(`  Paste:    ${payload.paste}`);
  process.exit(0);
}

function docStatusCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  if (slug) docMigrateV2(claudeDir, slug);
  const view = slug ? docMapView(claudeDir, slug) : null;
  if (!view) return docNoSuch(asJson, slugArg);
  const d = view.d;
  const p = view.paths;
  const v2 = d.version >= DOC_STATE_VERSION;
  const pv = docPartsView(claudeDir, slug);
  const hasDoc = !!view.document && fs.existsSync(view.document);
  const lint = hasDoc ? docLintRun(fs.readFileSync(view.document, "utf8"), d.target, docLintOpts(claudeDir, d)) : null;
  const byId = new Map((v2 ? pv.rows : view.sections).map((s) => [s.id, s]));
  const open = d.outline.filter((o) => {
    const s = byId.get(o.id);
    return o.required && (!s || s.state === "planned" || s.state === "open" || s.state === "unconfirmed");
  });
  const userEdited = (v2 ? pv.rows : view.sections).filter((s) => s.state === "user-edited");
  const staleDoc = v2 && hasDoc ? docDocStale(pv) : null;
  const state = docComputedState(d, view, { hasDoc, open, lint, pv: v2 ? pv : null, staleDoc });
  const drift = docShipDrift(d, view);
  const next = docNextAction(claudeDir, slug);
  const wave = docWaveState(d, pv.rows);
  const payload = {
    ok: true,
    slug,
    title: d.title,
    type: d.type,
    target: d.target,
    language: d.language,
    version: d.version,
    cycle: d.cycle || 0,
    state,
    write_mode: d.write_mode || null,
    // v0.52.0 (D9) - the RESOLVED per-document Extra answer, so the row chip and
    // the header strip print the same word the CLI would.
    extra: docExtraResolve(claudeDir, d).resolved,
    wave,
    shipped: d.shipped || null,
    drifted_sections: state === "shipped-drifted" ? drift : [],
    next: next ? { phase: next.phase, action: next.action, command: next.command, paid: next.paid, blocked_by: next.blocked_by } : null,
    document: hasDoc ? path.relative(p.root, view.document).split(path.sep).join("/") : null,
    document_stale: staleDoc && staleDoc.length ? staleDoc : [],
    sections_dir: path.relative(p.root, p.sections).split(path.sep).join("/"),
    lines: view.total_lines,
    sections_total: d.outline.length,
    sections_written: (v2 ? pv.rows : view.sections).filter((s) => (v2 ? s.state === "written" || s.state === "checked" : s.state !== "planned" && s.state !== "open")).length,
    open_sections: open.map((o) => ({ id: o.id, heading: o.heading })),
    user_edited: userEdited.map((s) => ({ id: s.id, heading: s.heading })),
    lint: lint ? { errors: lint.errors, warnings: lint.warnings, target: lint.target } : null,
    dir: p.folder,
    // ONE GENERATOR, NOT TWO. The skill copies this line VERBATIM into
    // RESUME.md, so the CLI computes and the skill renders — and the two can no
    // longer disagree about what the run's own status line says.
    where: docWhereLine(d, view, { rows: v2 ? pv.rows : null, phase: next ? next.phase : null, wave }),
    resume: `/orc-doc resume ${slug}`,
  };
  // 1 = THERE IS SOMETHING TO DO. `shipped-drifted` is a 1 for that reason: the
  // document moved after it was delivered, so either re-ship it or say why not.
  const code = DOC_STATE_EXIT[state];
  if (asJson) emitJson(payload, code);
  console.log(ui.header(`ORC · doc status — ${slug}`));
  console.log(`\n  ${state}`);
  console.log(`  ${payload.where}`);
  if (staleDoc && staleDoc.length)
    console.log(
      `  ${DOC_FILE} is behind sections/: ${staleDoc.map((s) => s.heading).join(", ")}  ${ui.color.gray("(free to rebuild — orc doc compile)")}`
    );
  if (lint) console.log(`  lint: ${lint.errors} errors, ${lint.warnings} warnings against ${lint.target_label}`);
  if (userEdited.length)
    console.log(`\n  You edited since last time: ${userEdited.map((s) => s.heading).join(", ")}\n  ${ui.color.gray("These are never rewritten unless you name them.")}`);
  if (open.length) console.log(`  Still open: ${open.map((o) => o.heading).join(" · ")}`);
  if (state === "shipped-drifted")
    console.log(
      `\n  Changed since it shipped: ${drift.map((s) => s.heading).join(", ")}\n  ` +
        ui.color.gray("Coverage-relative on purpose — a whole-file \"something changed\" cannot tell you what to re-read.")
    );
  if (next) console.log(`\n  Next:  ${next.command || ui.color.yellow("waiting on you — " + next.blocked_by)}`);
  console.log(`\n  Carry on, even in a brand-new chat:  ${payload.resume}`);
  process.exit(code);
}

// ── ship: RECORDED as a decision, COMPUTED as a state (v0.48.1) ─────────────
// Two rules this repo already uses for exactly this shape:
//   1. /orc-pact — "retirement is a user decision with a recorded reason", so
//      shipping is RECORDED and never inferred from "it looks finished".
//   2. /orc-challenge — "PASS is computed, never declared", so the resulting
//      STATE is derived from the record every time it is read, never stored.
//
// Before this, `docStatusCmd` computed `complete` and stopped there. Nothing
// recorded that a document was DELIVERED, so a listing could not tell a PRD
// that went to a backend team in March from one that has been sitting finished
// and forgotten ever since.

const docWholeHash = (view) => (view && view.document && fs.existsSync(view.document) ? docHash(fs.readFileSync(view.document, "utf8")) : null);

function docSectionHashes(view) {
  const out = {};
  for (const s of (view && view.sections) || []) out[s.id] = s.hash;
  return out;
}

// Which sections moved SINCE THE SHIP — coverage-relative, the
// `computeWikiFreshness` lesson applied to a document. A whole-file "something
// changed" would be useless: it cannot tell you what to re-read.
function docShipDrift(d, view) {
  const rec = d && d.shipped;
  if (!rec) return null;
  const then = rec.section_hashes || {};
  const now = docSectionHashes(view);
  const out = [];
  for (const s of (view && view.sections) || [])
    if (then[s.id] && then[s.id] !== now[s.id]) out.push({ id: s.id, heading: s.heading, reason: "changed" });
  for (const id of Object.keys(then)) if (!(id in now)) out.push({ id, heading: id, reason: "gone" });
  for (const s of (view && view.sections) || []) if (!(s.id in then)) out.push({ id: s.id, heading: s.heading, reason: "added" });
  return out;
}

// not-started | in-progress | complete | shipped | shipped-drifted.
// `shipped-drifted` KEEPS ITS SLOT and is an answer, not a gap.
function docComputedState(d, view, { hasDoc, open, lint, pv, staleDoc }) {
  // v2: the SECTION FILES are the progress, so a document with sections written
  // and no compile yet is `in-progress`, never `not-started`. A build artifact
  // that has not been built yet says nothing about whether work happened.
  if (pv) {
    const anyWritten = pv.rows.some((r) => r.exists);
    if (!hasDoc && !anyWritten) return "not-started";
  } else if (!hasDoc) return "not-started";
  const finished = hasDoc && !open.length && lint && lint.errors === 0 && !(staleDoc && staleDoc.length);
  if (d.shipped) {
    const drift = docShipDrift(d, view);
    return drift && drift.length ? "shipped-drifted" : "shipped";
  }
  return finished ? "complete" : "in-progress";
}

// `1` means THERE IS SOMETHING TO DO, and that is now said out loud in the help
// text. `shipped-drifted` is a 1 for that reason: the document moved after it
// was delivered, so either re-ship it or say why not — either way, work.
const DOC_STATE_EXIT = { "not-started": 1, "in-progress": 1, complete: 0, shipped: 0, "shipped-drifted": 1 };

function docShipCmd(claudeDir, slugArg, undo) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const view = slug ? docMapView(claudeDir, slug) : null;
  if (!view) return docNoSuch(asJson, slugArg);
  const d = view.d;
  const fail = (reason, hint, extra, code = 2) => {
    if (asJson) emitJson({ ok: false, reason, slug, hint, ...(extra || {}) }, code);
    console.error("❌ " + hint);
    process.exit(code);
  };

  if (undo) {
    // Unship needs a reason for the same rule ship needs a destination: an
    // undone decision with no recorded why is a decision nobody can review.
    const reason = docOpt("--reason");
    if (!reason) fail("no-reason", "orc doc unship needs --reason <text> — an un-shipped document with no reason is a state nobody can explain.");
    if (!d.shipped) fail("not-shipped", `${slug} was never shipped, so there is nothing to undo.`, null, 1);
    d.ship_history = Array.isArray(d.ship_history) ? d.ship_history : [];
    d.ship_history.push({ ...d.shipped, unshipped_at: fmtStamp(new Date()), unship_reason: reason });
    d.shipped = null;
    docWrite(claudeDir, slug, d);
    if (asJson) emitJson({ ok: true, slug, state: "in-progress", ship_history: d.ship_history.length, reason }, 0);
    console.log(ui.header(`ORC · doc unship — ${slug}`));
    console.log(`\n  Un-shipped. The previous record is kept in ship_history (${d.ship_history.length} now) — nothing is ever silently erased.`);
    console.log(`  Reason: ${reason}`);
    process.exit(0);
  }

  // `--where` has NO DEFAULT, the `orc challenge init --goal` rule: "shipped"
  // with no destination is not a fact, it is a feeling.
  const where = docOpt("--where");
  if (!where)
    fail(
      "no-where",
      "orc doc ship needs --where <destination> — a Notion URL, a Slack thread, " +
        '"handed to the platform team in the 12 Aug review". Shipped with no destination is not a fact.'
    );

  const hasDoc = !!view.document && fs.existsSync(view.document);
  const lint = hasDoc ? docLintRun(fs.readFileSync(view.document, "utf8"), d.target, docLintOpts(claudeDir, d)) : null;
  const v2 = d.version >= DOC_STATE_VERSION;
  const pv = v2 ? docPartsView(claudeDir, slug) : null;
  const byId = new Map((v2 ? pv.rows : view.sections).map((s) => [s.id, s]));
  const open = d.outline.filter((o) => {
    const s = byId.get(o.id);
    return o.required && (!s || s.state === "planned" || s.state === "open" || s.state === "unconfirmed");
  });
  // A document.md behind its own sections/ is not the document that would be
  // delivered. Same wording family as `shipped-drifted`, one step earlier.
  const staleDoc = v2 && hasDoc ? docDocStale(pv) : null;
  if (staleDoc && staleDoc.length)
    fail(
      "document-stale",
      `${DOC_FILE} is behind sections/: ${staleDoc.map((s) => s.heading).join(", ")} changed since the last compile. ` +
        `Rebuild it first (free): orc doc compile ${slug}`,
      { stale_sections: staleDoc },
      1
    );
  const complete = hasDoc && !open.length && lint && lint.errors === 0;
  const forced = flag("--force");
  const forceReason = docOpt("--reason");

  if (!complete && !forced)
    fail(
      "not-complete",
      `${slug} is not complete: ` +
        (open.length ? `${plural(open.length, "required section")} still open (${open.map((o) => o.heading).join(", ")})` : "") +
        (open.length && lint && lint.errors ? "; " : "") +
        (lint && lint.errors ? `${plural(lint.errors, "lint error")}` : "") +
        ". Ship it anyway with --force --reason <text>.",
      { open_sections: open.map((o) => ({ id: o.id, heading: o.heading })), lint_errors: lint ? lint.errors : null },
      1
    );
  // The escape valve is never automatic and never silent.
  if (!complete && forced && !forceReason)
    fail("no-force-reason", "--force needs --reason <text>: shipping an incomplete document is a decision, and it is recorded verbatim.");

  d.shipped = {
    at: fmtStamp(new Date()),
    where,
    note: docOpt("--note") || null,
    cycle: d.cycle || 0,
    lines: view.total_lines,
    document_hash: docWholeHash(view),
    section_hashes: docSectionHashes(view),
    source_commit: gitIn(view.paths.root, ["rev-parse", "--short", "HEAD"]) || null,
    forced: !complete,
    force_reason: !complete ? forceReason : null,
  };
  docWrite(claudeDir, slug, d);

  if (asJson) emitJson({ ok: true, slug, state: "shipped", shipped: d.shipped, where: docWhereLine(d, view) }, 0);
  console.log(ui.header(`ORC · doc ship — ${slug}`));
  console.log(`\n  Shipped ${d.shipped.at} → ${where}`);
  if (d.shipped.note) console.log(`  Note: ${d.shipped.note}`);
  if (d.shipped.forced) console.log(ui.color.yellow(`  FORCED (incomplete): ${forceReason}`));
  console.log(ui.color.gray(`\n  ${view.sections.length} section hashes recorded. If any of them changes, this reads shipped-drifted —`));
  console.log(ui.color.gray("  which names the sections that moved, so you know exactly what a re-send would change."));
  process.exit(0);
}

// ── the audit — every drift class, from disk (v0.48.1) ──────────────────────
// Each finding carries a `fix` command and a `panel` (the FINDING_ROUTE rule: a
// caution routes to the panel that can CLEAR it; `panel: null` when there is
// genuinely no button).
//
// `user-edited` sections are REPORTED and never counted as a finding. Rule 4
// says a human's wording is not recoverable from this lane's side, and flagging
// their edits as drift would teach people to stop editing their own document.
function docAuditFindings(claudeDir, slug) {
  const view = docMapView(claudeDir, slug);
  if (!view) return null;
  const d = view.d;
  const p = view.paths;
  const out = [];
  const add = (id, summary, fix, panel, level = "error") => out.push({ id, level, summary, fix, panel });
  const hasDoc = !!view.document && fs.existsSync(view.document);
  const v2 = d.version >= DOC_STATE_VERSION;

  // ── v0.49.0 — the folder's own drift classes ──────────────────────────────
  if (v2) {
    const pv = docPartsView(claudeDir, slug);
    for (const r of pv.rows) {
      if (r.required && !r.exists)
        add("part-missing", `"${r.heading}" is required and has no source file under sections/.`, `orc doc plan ${slug} --role write --only ${r.id} --json`, "docs");
      if (r.state === "unconfirmed")
        add(
          "part-unconfirmed",
          `${r.files[0]} exists but no validated return ever recorded its hash — a wave killed mid-flight leaves exactly this.`,
          `orc doc plan ${slug} --role write --only ${r.id} --json`,
          "docs"
        );
      if (!r.ordinal_ok)
        add("part-misnumbered", `${r.id} no longer mirrors its outline position.`, `orc doc outline ${slug} --set ${DOC_OUTLINE_FILE}`, "docs", "warn");
      for (const pb of r.problems) add("subpart-bad-level", pb.what, `orc doc parts ${slug} --json`, "docs");
    }
    // A file under sections/ that no outline entry claims.
    if (pv.paths.sections && fs.existsSync(pv.paths.sections)) {
      const claimed = new Set(pv.rows.map((r) => r.id));
      for (const e of fs.readdirSync(pv.paths.sections, { withFileTypes: true })) {
        const id = e.name.replace(/\.md$/, "");
        if (id === DOC_FRONT_FILE.replace(/\.md$/, "") || claimed.has(id)) continue;
        add("part-orphan", `sections/${e.name} is not in the outline — nothing will ever compile it.`, `orc doc outline ${slug} --json`, "docs", "warn");
      }
    }
    const staleDoc = hasDoc ? docDocStale(pv) : null;
    if (staleDoc && staleDoc.length)
      add(
        "document-stale",
        `${DOC_FILE} is behind sections/: ${staleDoc.map((s) => s.heading).join(", ")}.`,
        `orc doc compile ${slug}`,
        "docs",
        "warn"
      );
    if (p.work && fs.existsSync(p.work) && fs.readdirSync(p.work).length)
      add("legacy-work", `${DOC_WORK}/ still holds files from before this document became a folder. Nothing reads them.`, `orc doc migrate ${slug} --clean`, "docs", "warn");
    if (p.folder && fs.existsSync(path.join(p.folder, RESUME_FILE)))
      add(
        "resume-misplaced",
        `RESUME.md is in the document folder, where \`orc resume\` and \`orc run list\` never look.`,
        `orc doc migrate ${slug}`,
        "docs"
      );
  } else {
    add("doc-v1", `${slug} is still v1: one file, and every change routed through it.`, `orc doc migrate ${slug}`, "docs", "warn");
  }

  // v0.49.2 — the TEMPLATE LOCK, from disk, in both directions.
  const lock = docLock(d);
  if (lock.locked) {
    const allowed = new Set(lock.headings);
    for (const o of d.outline || []) for (const s of o.subsections || []) allowed.add(s.heading);
    const stray = [];
    for (const o of d.outline || []) {
      const src = docSectionSource(p, o);
      if (!src || !src.text) continue;
      for (const h of docScan(src.text).headings)
        if (h.level >= 2 && !allowed.has(h.heading)) stray.push({ id: o.id, heading: h.heading });
    }
    if (stray.length)
      add(
        "template-drift",
        `${plural(stray.length, "heading")} the template never had: ` +
          stray.map((x) => `"${x.heading}" in ${x.id}`).join(", ") +
          `. A supplied template is a cage — what does not fit is a gap.`,
        `orc doc lint ${slug} --json`,
        "docs"
      );
    // The template FILE moved. REPORTED, never auto-synced: re-freezing an
    // outline against a template somebody edited is a decision, not a repair.
    if (lock.path) {
      const abs = path.isAbsolute(lock.path) ? lock.path : path.join(p.root, lock.path);
      const now = shaOfFile(abs);
      if (now === null)
        add("template-moved", `the template ${lock.path} is gone — the lock still holds the headings it declared.`, `orc doc rules ${slug}`, "docs", "warn");
      else if (lock.hash && now !== lock.hash)
        add(
          "template-moved",
          `${lock.path} has changed since this document was created. The lock still holds the ORIGINAL headings — nothing is re-synced on its own.`,
          `orc doc outline ${slug}`,
          "docs",
          "warn"
        );
    }
  }

  // v0.49.2 — the frozen house rules and the project ledger have parted. It is a
  // WARN, never an error: the drift is a fact about the document, and whether
  // any already-written section needs redoing is the user's call, not ORC's.
  const hrDrift = docRulesDrift(d.doc_rules, docRulesRead(claudeDir).blocks);
  if (hrDrift.drifted) {
    add(
      "house-rules-drifted",
      `the project's house rules moved since this document was frozen ` +
        `(${hrDrift.changed.map((c) => c.priority).join(", ")}). Nothing is re-written on its own.`,
      `orc doc rules ${slug} --sync`,
      "docs",
      "warn"
    );
  }

  if (hasDoc) {
    const ann = docAnnotations(fs.readFileSync(view.document, "utf8"));
    if (ann.length)
      add(
        "annotation-in-body",
        `${plural(ann.length, "line")} of ORC bookkeeping in the deliverable (first at line ${ann[0].line}). The document carries content only.`,
        `orc doc compile ${slug} --strip-annotations`,
        "docs"
      );
  }

  // Extracts that never came back, and extracts whose section moved under them.
  const now = docSectionHashes(view);
  for (const [id, rec] of Object.entries(d.extracts || {})) {
    const part = p.work ? path.join(p.work, id + ".md") : null;
    if (!part || !fs.existsSync(part)) continue;
    let age = "";
    try {
      age = " (" + relAgeShort(Date.now() - fs.statSync(part).mtimeMs) + " old)";
    } catch (_) {}
    if (rec && rec.hash && now[id] && rec.hash !== now[id])
      add(
        "extract-stale",
        `.work/${id}.md was extracted from a version of "${id}" that no longer matches the document — splice WILL refuse.`,
        `orc doc extract ${slug} --section ${id}`,
        "docs"
      );
    else add("orphan-extract", `.work/${id}.md was extracted${age} and never spliced back.`, `orc doc splice ${slug}`, "docs", "warn");
  }

  // The outline and the document disagreeing is always a hand edit, and always
  // worth naming: every later batch is computed from the outline.
  if (hasDoc) {
    const live = new Set(view.sections.map((s) => s.id));
    // A section that was never WRITTEN did not vanish — it is `part-missing`,
    // reported above. Claiming both would be the audit saying something the disk
    // does not prove, and under `compile --partial` it would say it eight times.
    const written = v2 ? new Set(docPartsView(claudeDir, slug).rows.filter((r) => r.exists).map((r) => r.id)) : null;
    for (const o of d.outline || [])
      if (!live.has(o.id) && (!written || written.has(o.id)))
        add("section-vanished", `outline lists "${o.heading}" but the document has no such heading.`, `orc doc compile ${slug}`, "docs");
    const planned = new Set((d.outline || []).map((o) => o.id));
    for (const s of view.sections)
      if (!planned.has(s.id))
        add("section-unlisted", `the document has "${s.heading}" but the outline does not.`, `orc doc outline ${slug}`, "docs", "warn");

    // The target decides the portability rules the lint enforces, so a target
    // that disagrees with the file is a lint measuring the wrong thing.
    const tgt = docTarget(d.target);
    const text = fs.readFileSync(view.document, "utf8");
    const hasFront = /^---\r?\n/.test(text);
    if (tgt && tgt.front_matter === "required" && !hasFront)
      add("target-mismatch", `target ${tgt.label} requires front matter and the document has none.`, `orc doc lint ${slug}`, "docs");
    if (tgt && tgt.front_matter === "banned" && hasFront)
      add("target-mismatch", `target ${tgt.label} does not support front matter, and the document starts with some.`, `orc doc lint ${slug}`, "docs");
    const tooDeep = view.sections.filter((s) => s.level > Number(tgt && tgt.max_heading ? tgt.max_heading : 6));
    if (tooDeep.length)
      add(
        "target-mismatch",
        `${plural(tooDeep.length, "heading")} deeper than H${tgt.max_heading}, which ${tgt.label} flattens.`,
        `orc doc lint ${slug}`,
        "docs"
      );
  }

  const drift = docShipDrift(d, view);
  if (drift && drift.length)
    add(
      "ship-drifted",
      `shipped ${d.shipped.at} to ${d.shipped.where}, and ${plural(drift.length, "section")} changed since: ` +
        drift.map((s) => s.heading).join(", ") + ".",
      `orc doc ship ${slug} --where "<where it went this time>"`,
      "docs",
      "warn"
    );

  // Hard rule 10: nothing is created before D1 is answered — so a doc.json with
  // no context.md is a document that was started without a frozen brief.
  const ctx = docContextPaths(p);
  if (!fs.existsSync(ctx.context))
    add("context-missing", "doc.json exists but context.md does not — this document has no frozen brief.", `/orc-doc resume ${slug}`, null);
  else {
    // docContextSources, not docContextRead: only the former resolves each
    // reference file against disk and sets its state.
    const src = docContextSources(ctx, p.root);
    // A WARNING, never an error. A frozen context is SUPPOSED to be old; what
    // is not acceptable is nobody knowing a source moved under it.
    const moved = (src.sources || []).filter((s) => s.state === "MISSING" || s.state === "SOURCE-DRIFTED");
    if (moved.length)
      add(
        "source-drifted",
        `${plural(moved.length, "reference file")} moved since the brief was frozen: ` + moved.map((s) => `${s.path} (${s.state})`).join(", "),
        `orc doc context ${slug}`,
        "docs",
        "warn"
      );
    const behind = docContextCommitsBehind(p.root, src.source_commit);
    if (behind !== null && behind > 200)
      add(
        "context-behind",
        `the brief was frozen ${plural(behind, "commit")} ago. That is not wrong — a frozen context is meant to be old — but it is worth a look.`,
        `orc doc context ${slug}`,
        "docs",
        "warn"
      );
  }

  if ((d.cycle || 0) !== (d.cycles || []).length)
    add(
      "cycle-mismatch",
      `doc.json says cycle ${d.cycle || 0} but records ${plural((d.cycles || []).length, "cycle")}.`,
      `orc doc show ${slug} --json`,
      null,
      "warn"
    );

  return { view, findings: out, user_edited: view.sections.filter((s) => s.state === "user-edited").map((s) => ({ id: s.id, heading: s.heading })) };
}

function docAuditCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const res = slug ? docAuditFindings(claudeDir, slug) : null;
  if (!res) return docNoSuch(asJson, slugArg);
  const code = res.findings.length ? 1 : 0;
  if (asJson) emitJson({ ok: true, slug, clean: !res.findings.length, findings: res.findings, user_edited: res.user_edited }, code);
  console.log(ui.header(`ORC · doc audit — ${slug}`));
  if (!res.findings.length) console.log("\n  Nothing drifted.");
  for (const f of res.findings) {
    console.log(`\n  ${(f.level === "error" ? ui.color.red("✗") : ui.color.yellow("~"))} ${f.id}`);
    console.log(`    ${f.summary}`);
    console.log(`    fix: ${f.fix}`);
  }
  if (res.user_edited.length)
    console.log(
      ui.color.gray(`\n  You edited: ${res.user_edited.map((s) => s.heading).join(", ")}\n` + "  Reported, never a finding — your wording is not recoverable from this side.")
    );
  process.exit(code);
}

// ── the memory surface (v0.48.1) ────────────────────────────────────────────
// A DATA gap, not a rendering one. Measured on disk before this release:
// `created_at` existed and `orc doc show --json` never emitted it; `context.md`
// and `context-sources.md` were files the CLI never opened; and what the user
// ASKED FOR, in order, across every session, lived nowhere at all.
//
// No conflict with hard rule 0. Rule 0 forbids the orchestrator reading
// `document.md`. `context.md` and `outline.md` are exactly what a resumed
// session is INSTRUCTED to read.

// How many separate sessions have touched this document — counted from the
// trace files the hook already writes, never from a counter a model maintains.
function docSessionCount(claudeDir, slug) {
  try {
    const dir = resolveLogDir(claudeDir);
    if (!fs.existsSync(dir)) return 0;
    const base = String(slug).replace(/-\d{6}$/, "");
    return fs.readdirSync(dir).filter((f) => f.startsWith("run-doc-") && f.includes(base) && f.endsWith(".txt")).length;
  } catch (_) {
    return 0;
  }
}

const DOC_CONTEXT_FILE = "context.md";
const DOC_SOURCES_FILE = "context-sources.md";
const DOC_CHANGELOG_FILE = "changelog.md";
// `gap` (v0.49.0) is where an Open question or an Assumption goes now that the
// deliverable carries content only. It is NOT a second ledger: it rides the
// journal, which already has exactly one writer, and gaps.md is derived from it.
const DOC_JOURNAL_KINDS = ["request", "decision", "gate", "note", "gap"];

function docContextPaths(p) {
  return {
    context: p.folder ? path.join(p.folder, DOC_CONTEXT_FILE) : null,
    sources: p.folder ? path.join(p.folder, DOC_SOURCES_FILE) : null,
    changelog: p.folder ? path.join(p.folder, DOC_CHANGELOG_FILE) : null,
  };
}

function docContextCommitsBehind(root, commit) {
  if (!commit) return null;
  const out = gitIn(root, ["rev-list", "--count", `${commit}..HEAD`]);
  return out === null ? null : Number(out) || 0;
}

// Parse the frozen brief. The VERBATIM REQUEST comes first because that is the
// memory-regain payload — everything else is supporting detail.
function docContextRead(ctx, root) {
  if (!ctx.context || !fs.existsSync(ctx.context)) return { exists: false, sources: [] };
  const text = fs.readFileSync(ctx.context, "utf8");
  const frozen = (text.match(/<!--\s*frozen\s+([^·\n]+?)\s*(?:·|-->)/) || [])[1] || null;
  // NO `m` FLAG on the terminator. Under `m`, `$` matches end of LINE, so a
  // lazy body stops at the first newline and every multi-line block came back
  // as its first line only — which read as "the brief has one bullet" rather
  // than as a parser bug.
  const block = (title) => {
    const re = new RegExp("(?:^|\\n)##\\s+" + title + "[^\\n]*\\n([\\s\\S]*?)(?=\\n##\\s|$(?![\\s\\S]))");
    const m = re.exec(text);
    return m ? m[1].trim() : null;
  };
  const request = block("The request \\(verbatim\\)") || block("The request");
  const sources = [];
  const table = block("Supporting documents[^\\n]*") || "";
  for (const line of table.split("\n")) {
    const cells = line.split("|").map((c) => c.trim());
    if (cells.length < 4 || /^-+$/.test(cells[1]) || /^path$/i.test(cells[1])) continue;
    const rel = cells[1];
    if (!rel || /^\*?none\*?$/i.test(rel)) continue;
    sources.push({ path: rel, read: /^y/i.test(cells[2] || ""), digest: cells[3] || null });
  }
  return {
    exists: true,
    path: ctx.context,
    frozen_at: frozen,
    request: request ? request.replace(/^>\s?/gm, "").trim() : null,
    purpose: block("Purpose[^\\n]*"),
    template: block("Template[^\\n]*"),
    decisions: block("Decisions[^\\n]*"),
    sources,
    source_commit: (text.match(/source_commit:\s*([0-9a-f]{7,40})/) || [])[1] || null,
  };
}

// Does each D2 reference file still exist, and has it changed since the freeze?
// Coverage-relative, the `computeWikiFreshness` shape applied to a brief: a
// supporting document is stale only when THAT FILE moved, never because the
// repository did.
function docContextSources(ctx, root) {
  const parsed = docContextRead(ctx, root);
  if (!parsed.exists) return parsed;
  const recorded = {};
  if (ctx.sources && fs.existsSync(ctx.sources)) {
    const s = fs.readFileSync(ctx.sources, "utf8");
    for (const m of s.matchAll(/^<!--\s*source:\s*(\S+)\s+sha:\s*([0-9a-f]+)\s*-->/gm)) recorded[m[1]] = m[2];
  }
  parsed.sources = parsed.sources.map((row) => {
    const abs = path.isAbsolute(row.path) ? row.path : path.join(root, ...row.path.split(/[\\/]/));
    if (!fs.existsSync(abs)) return { ...row, state: "MISSING", note: "the file the brief was built on is gone" };
    const known = recorded[row.path];
    if (!known) return { ...row, state: "ok", note: "no hash was recorded at freeze time — existence is all that can be checked" };
    const live = docHash(fs.readFileSync(abs, "utf8"));
    return live === known
      ? { ...row, state: "ok" }
      : { ...row, state: "SOURCE-DRIFTED", note: "changed since the brief was frozen — the brief is not wrong, but it is older than this file" };
  });
  parsed.sources_path = ctx.sources && fs.existsSync(ctx.sources) ? ctx.sources : null;
  return parsed;
}

function docContextCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const p = docPaths(claudeDir, slug);
  const ctx = docContextSources(docContextPaths(p), p.root);
  const drifted = (ctx.sources || []).filter((s) => s.state !== "ok");
  const code = drifted.length ? 1 : 0;
  if (asJson) emitJson({ ok: true, slug, context: ctx, drifted: drifted.map((s) => s.path) }, code);

  console.log(ui.header(`ORC · doc context — ${slug}`));
  if (!ctx.exists) {
    console.log("\n  No context.md. This document was started without a frozen brief.");
    process.exit(code);
  }
  console.log(ui.color.gray(`\n  Frozen ${ctx.frozen_at || "(date not recorded)"} — read forever, never re-asked.`));
  if (ctx.request) console.log(`\n  YOU ASKED FOR:\n${ctx.request.split("\n").map((l) => "    " + l).join("\n")}`);
  if (ctx.purpose) console.log(`\n  Purpose\n${ctx.purpose.split("\n").map((l) => "    " + l).join("\n")}`);
  if (!ctx.sources.length) console.log(ui.color.gray("\n  Reference files: none — you were asked and said none."));
  else {
    console.log("\n  Reference files");
    for (const s of ctx.sources) console.log(`    ${s.state.padEnd(16)} ${s.path}${s.note ? "  " + ui.color.gray(s.note) : ""}`);
  }
  process.exit(code);
}

// ── the journal — one writer, and it NEVER invents an entry ─────────────────
function docLogCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const fail = (reason, hint) => {
    if (asJson) emitJson({ ok: false, reason, slug, hint }, 2);
    console.error("❌ " + hint);
    process.exit(2);
  };
  const kind = String(docOpt("--kind") || "").toLowerCase();
  if (!DOC_JOURNAL_KINDS.includes(kind)) fail("bad-kind", `--kind must be one of: ${DOC_JOURNAL_KINDS.join(", ")}`);
  const text = docOpt("--text");
  if (!text) fail("no-text", "orc doc log needs --text — and at D1 it is the user's words VERBATIM, never a paraphrase.");

  d.journal = Array.isArray(d.journal) ? d.journal : [];
  const entry = {
    n: d.journal.length + 1,
    at: fmtStamp(new Date()),
    kind,
    text,
    cycle: d.cycle || 0,
    sections: String(docOpt("--sections") || "")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean),
    source: docOpt("--source") || "user",
  };
  d.journal.push(entry);
  // Through docWrite, so doc.json still has EXACTLY ONE WRITER.
  docWrite(claudeDir, slug, d);
  const gaps = docWriteGaps(claudeDir, slug, d);
  if (asJson) emitJson({ ok: true, slug, entry, entries: d.journal.length, gaps: gaps ? path.basename(gaps) : null }, 0);
  console.log(`recorded #${entry.n} (${kind}) — ${d.journal.length} entries in the journal for ${slug}`);
  process.exit(0);
}

// Merge four sources into ONE chronological array. Every row carries its
// PROVENANCE so the panel can be honest about which is which:
//   recorded  the user's own words, verbatim (journal[])
//   derived   a machine fact (a cycle, a ship record)
//   observed  a machine fact with no text (a section that turned user-edited)
//
// AND IT NEVER INVENTS AN ENTRY. A cycle that ran with nothing logged renders
// as an explicit gap — never a plausible reconstruction from file mtimes. Same
// honesty rule as /orc-pact's UNCHECKABLE: not knowing is an answer, and faking
// it teaches people to distrust the rows that are real.
function docJournalRows(claudeDir, slug) {
  const view = docMapView(claudeDir, slug);
  if (!view) return null;
  const d = view.d;
  const rows = [];
  for (const e of d.journal || [])
    rows.push({ at: e.at, origin: "recorded", kind: e.kind, text: e.text, cycle: e.cycle || 0, sections: e.sections || [], source: e.source || "user" });

  const logged = new Set((d.journal || []).map((e) => e.cycle));
  (d.cycles || []).forEach((c, i) => {
    const n = c.n || i + 1;
    rows.push({
      at: c.at || null,
      origin: "derived",
      kind: c.role ? c.role + " cycle" : "cycle",
      text: null,
      cycle: n,
      sections: c.sections || [],
      agents: c.agents || null,
      gap: !logged.has(n),
    });
  });

  if (d.shipped) rows.push({ at: d.shipped.at, origin: "derived", kind: "shipped", text: d.shipped.where, cycle: d.shipped.cycle || 0, sections: [] });
  for (const h of d.ship_history || [])
    rows.push({ at: h.unshipped_at, origin: "derived", kind: "unshipped", text: h.unship_reason || null, cycle: h.cycle || 0, sections: [] });

  for (const s of view.sections)
    if (s.state === "user-edited") rows.push({ at: null, origin: "observed", kind: "you edited", text: null, cycle: s.cycle || 0, sections: [s.id] });

  // Oldest first: reading order IS the story.
  rows.sort((a, b) => (a.cycle || 0) - (b.cycle || 0) || String(a.at || "").localeCompare(String(b.at || "")));
  return { view, rows };
}

function docJournalCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const res = slug ? docJournalRows(claudeDir, slug) : null;
  if (!res) return docNoSuch(asJson, slugArg);
  const recorded = res.rows.filter((r) => r.origin === "recorded").length;
  const gaps = res.rows.filter((r) => r.gap).length;
  if (asJson) emitJson({ ok: true, slug, entries: res.rows.length, recorded, gaps, journal: res.rows }, 0);
  console.log(ui.header(`ORC · doc journal — ${slug}`));
  console.log(ui.color.gray(`\n  ${plural(res.rows.length, "entry", "entries")}, ${recorded} in your own words. Oldest first.\n`));
  for (const r of res.rows) {
    const mark = r.origin === "recorded" ? "•" : r.origin === "observed" ? "~" : "·";
    const head = `  ${mark} ${(r.at || "—").padEnd(20)} ${r.kind}`;
    if (r.gap) console.log(head + ui.color.gray("  · no request was recorded for it"));
    else console.log(head + (r.text ? "  " + r.text.split("\n")[0].slice(0, 96) : ""));
  }
  if (gaps)
    console.log(
      ui.color.gray(`\n  ${plural(gaps, "cycle")} ran with nothing recorded. Shown as a gap on purpose — a reconstruction would read like a fact.`)
    );
  process.exit(0);
}

// ── the reader — for the HUMAN, never for the orchestrator ──────────────────
// This does NOT weaken hard rule 0. `SKILL.md`'s rule table carries the line
// "the orchestrator never runs `orc doc read`", registered as a contract token
// so it cannot quietly disappear. It is a command for the person, the same way
// `orc challenge report` is.
function docReadCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const view = slug ? docMapView(claudeDir, slug) : null;
  if (!view) return docNoSuch(asJson, slugArg);
  const want0 = docOpt("--section");
  // v2: a named section is read straight from its own file, so `read` works
  // BEFORE a single compile has ever run.
  if (want0 && view.d.version >= DOC_STATE_VERSION && !flag("--toc")) {
    const entry = (view.d.outline || []).find((x) => x.id === want0 || x.id.startsWith(want0));
    const src = entry ? docSectionSource(view.paths, entry) : null;
    if (entry && src && src.text) {
      const text = docSectionBody(entry, src);
      if (asJson) emitJson({ ok: true, slug, section: entry.id, heading: entry.heading, files: src.files, lines: docLines(text).length, text }, 0);
      console.log(text);
      process.exit(0);
    }
  }
  if (!view.document || !fs.existsSync(view.document)) {
    const hint = `no ${DOC_FILE} yet for ${slug} — nothing has been compiled. The sections themselves: orc doc parts ${slug}`;
    if (asJson) emitJson({ ok: false, reason: "no-document", slug, hint }, 1);
    console.error("❌ " + hint);
    process.exit(1);
  }
  const want = want0;
  if (!want || flag("--toc")) {
    const toc = view.sections.map((s) => ({ id: s.id, heading: s.heading, level: s.level, start: s.start, end: s.end, lines: s.lines, state: s.state }));
    if (asJson) emitJson({ ok: true, slug, document: view.document, total_lines: view.total_lines, toc }, 0);
    console.log(ui.header(`ORC · doc read — ${slug}  (${plural(view.total_lines, "line")})`));
    console.log("");
    for (const s of toc)
      console.log(`  ${String(s.start).padStart(5)}..${String(s.end).padEnd(5)} ${"  ".repeat(Math.max(0, s.level - 2))}${s.heading}`);
    console.log(ui.color.gray(`\n  One section at a time:  orc doc read ${slug} --section <id>`));
    process.exit(0);
  }
  const s = view.sections.find((x) => x.id === want || x.id.startsWith(want));
  if (!s) {
    const hint = `no section "${want}" in ${slug} — \`orc doc read ${slug} --toc\` lists them.`;
    if (asJson) emitJson({ ok: false, reason: "no-such-section", slug, section: want, hint }, 2);
    console.error("❌ " + hint);
    process.exit(2);
  }
  const scanned = view.scan.sections.find((x) => x.id === s.id);
  if (asJson) emitJson({ ok: true, slug, section: s.id, heading: s.heading, start: s.start, end: s.end, lines: s.lines, state: s.state, text: scanned.text }, 0);
  console.log(scanned.text);
  process.exit(0);
}

// ── `orc doc next` — the orchestrator's score (v0.48.1) ─────────────────────
// The CLI computes the next legal action; the skill RENDERS it and does exactly
// that. Same shape as the Flow stepper, and for the same reason: D6–D9 used to
// be prose the orchestrator had to hold in its head across a session that might
// be resumed months later in a fresh context. That is precisely the
// remembered-not-dispatched protocol that has failed twice in this repo (the
// v0.32.0 narration lesson).
//
// Exit codes, the `pattern status` / `diy status` convention:
//   0  an action is available
//   1  waiting on a HUMAN decision — `blocked_by` names it in one sentence
//   2  unknown slug
function docNextAction(claudeDir, slug) {
  const view = docMapView(claudeDir, slug);
  if (!view) return null;
  const d = view.d;
  const p = view.paths;
  const v2 = d.version >= DOC_STATE_VERSION;
  const hasDoc = !!view.document && fs.existsSync(view.document);
  const allParts = p.work && fs.existsSync(p.work) ? fs.readdirSync(p.work).filter((f) => f.endsWith(".md")) : [];
  // Only a RECORDED extract is waiting to be spliced. A write-wave part file is
  // consumed by `assemble` and then just lingers in .work/ — treating those as
  // pending splices told every finished document to splice forever.
  const parts = allParts.filter((f) => (d.extracts || {})[f.replace(/\.md$/, "")]);
  const byId = new Map(view.sections.map((s) => [s.id, s]));
  const open = (d.outline || []).filter((o) => {
    const s = byId.get(o.id);
    return o.required && (!s || s.state === "planned" || s.state === "open");
  });
  const lint = hasDoc ? docLintRun(fs.readFileSync(view.document, "utf8"), d.target, docLintOpts(claudeDir, d)) : null;
  const A = (phase, action, command, why, paid, alternatives) => ({
    ok: true,
    slug,
    phase,
    action,
    command,
    why,
    paid: !!paid,
    blocked_by: null,
    alternatives: alternatives || [],
  });
  const BLOCK = (phase, blocked_by, alternatives) => ({
    ok: true,
    slug,
    phase,
    action: "ask",
    command: null,
    why: blocked_by,
    paid: false,
    blocked_by,
    alternatives: alternatives || [],
  });

  const ctx = docContextPaths(p);
  if (!fs.existsSync(ctx.context))
    return BLOCK("D1", "no context.md — the brief was never frozen. Ask the D1 question and write it before anything else runs.");

  if (!(d.outline || []).length) return A("D5", "outline", `orc doc outline ${slug} --json`, "there is no agreed outline yet", false);

  // ── v0.49.0 — the folder ladder. Free repairs first, always. ──────────────
  if (!v2)
    return A("D6", "migrate", `orc doc migrate ${slug} --json`, "this document is still v1: one file, and every change routed through it", false, [
      `orc doc audit ${slug} --json`,
    ]);

  const pv = docPartsView(claudeDir, slug);
  const cfg = resolvedConfig(claudeDir);
  const writeMode = d.write_mode || (cfg.doc_write_mode === "ask" ? null : cfg.doc_write_mode);
  const shape = pv.rows.flatMap((r) => r.problems);
  if (shape.length)
    return BLOCK("D6", `${shape[0].what} Nothing was compiled — a nested sub-part that would restructure the deliverable is a refusal, never a silent fix.`, [
      `orc doc parts ${slug} --json`,
    ]);

  if (!writeMode)
    return BLOCK(
      "D6",
      "partial or all — your call. `partial` writes ONE wave and stops so you can read those files and redirect before the rest is paid for; `all` writes every wave.",
      [`orc doc mode ${slug} --set partial`, `orc doc mode ${slug} --set all`]
    );

  // v0.49.2 — THE RUN MAP, ONCE. Before the first paid wave the user is told
  // how many waves there are, how many stops, and what the whole document costs.
  // It is named EXACTLY ONCE: a resumed session in a fresh context does not
  // re-show it, because the record is on disk rather than in a model's memory.
  // A forecast for a DIFFERENT shape is not a forecast, so a changed outline or
  // a changed write mode invalidates it.
  const fc = d.forecast || null;
  const fcStale =
    fc && (fc.outline_hash !== docOutlineHash(d) || (fc.write_mode || null) !== (writeMode || null));
  const anyWritten = pv.rows.some((r) => r.exists);
  if ((!fc || fcStale) && !anyWritten)
    return A(
      "D5.5",
      "forecast",
      `orc doc forecast ${slug} --json`,
      fcStale
        ? "the outline or the write mode changed since the last forecast — a forecast for a different shape is not a forecast"
        : "you are about to buy the first wave and have not been told what the whole document costs",
      false,
      [`orc doc forecast ${slug} --naive --json`]
    );

  const unconfirmed = pv.rows.filter((r) => r.state === "unconfirmed");
  if (unconfirmed.length)
    return A(
      "D6",
      "plan-write",
      `orc doc plan ${slug} --role write --only ${unconfirmed.map((r) => r.id).join(",")} --json`,
      `${plural(unconfirmed.length, "part file")} on disk with no validated return — a wave was killed mid-flight. Re-write, never ship.`,
      true,
      [`orc doc parts ${slug} --json`]
    );

  const notWritten = pv.rows.filter((r) => r.required && !r.exists);
  const wave = docWaveState(d, pv.rows);
  if (notWritten.length) {
    if (writeMode === "all")
      return A("D6", "plan-write", `orc doc plan ${slug} --role write --json`, `${plural(notWritten.length, "required section")} ${notWritten.length === 1 ? "has" : "have"} no source file yet`, true);
    // Partial: after every wave the lane STOPS. The wave-review gate is just
    // another `blocked_by`, which is why the skill needs no new prose for it.
    if (wave && wave.done > 0 && wave.done < wave.total)
      return BLOCK(
        "D6",
        `wave ${wave.done} of ${wave.total} is written. Read those section files and say whether to carry on — nothing later is bought yet.`,
        [`orc doc compile ${slug} --partial`, `orc doc parts ${slug} --json`]
      );
    return A(
      "D6",
      "plan-write",
      `orc doc plan ${slug} --role write --json`,
      `${plural(notWritten.length, "required section")} ${notWritten.length === 1 ? "has" : "have"} no source file yet — partial mode returns wave 1 only`,
      true
    );
  }

  const staleDoc = hasDoc ? docDocStale(pv) : null;
  if (!hasDoc)
    return A("D7", "compile", `orc doc compile ${slug} --json`, "every required section is written and nothing has been compiled yet", false);
  if (staleDoc && staleDoc.length)
    return A(
      "D7",
      "compile",
      `orc doc compile ${slug} --json`,
      `${plural(staleDoc.length, "section")} changed since the last compile (${staleDoc.map((s) => s.heading).join(", ")})`,
      false
    );

  // A section a human edited is never rewritten without an instruction naming
  // it: their wording is not recoverable from this side.
  const edited = pv.rows.filter((s) => s.state === "user-edited");
  if (edited.length && !parts.length)
    return BLOCK(
      "D8",
      `you edited ${edited.map((s) => s.heading).join(", ")} by hand. Nothing rewrites those without you naming them — ask what should change.`,
      [`orc doc read ${slug} --section ${edited[0].id}`]
    );

  // Extract → edit → splice. The half-finished round comes before anything new.
  const stale = parts.map((f) => f.replace(/\.md$/, "")).filter((id) => {
    const rec = (d.extracts || {})[id];
    const live = byId.get(id);
    return rec && live && rec.hash && rec.hash !== live.hash;
  });
  if (stale.length)
    return BLOCK(
      "D8",
      `.work/${stale[0]}.md was extracted from a version that no longer matches the document — splice will refuse. Re-extract, or decide which wording wins.`,
      [`orc doc extract ${slug} --section ${stale[0]}`, `orc doc audit ${slug} --json`]
    );
  if (parts.length && hasDoc)
    return A("D8", "splice", `orc doc splice ${slug}`, `${plural(parts.length, "part file")} waiting in .work/ — bottom-up, so no line number moves under another`, false);
  if (allParts.length && !hasDoc)
    return A("D7", "assemble", `orc doc assemble ${slug}`, `${plural(allParts.length, "part file")} written and nothing assembled yet`, false);

  if (!hasDoc) return A("D6", "plan-write", `orc doc plan ${slug} --role write --json`, "the outline is agreed and nothing has been written", true);

  // THE FREE CHECK ALWAYS RUNS BEFORE THE PAID ONE. `orc doc lint` costs zero
  // tokens and its findings ride in the checker's slice, so no model is ever
  // paid to count sentences.
  const writtenSince = (v2 ? pv.rows : view.sections).filter((s) => s.state === "written").length;
  if (lint && lint.errors)
    return A("D7", "lint", `orc doc lint ${slug} --json`, `${plural(lint.errors, "lint error")} — the free check runs before the paid one`, false, [
      `orc doc map ${slug} --json`,
    ]);
  if (writtenSince)
    return A(
      "D7",
      "plan-check",
      `orc doc plan ${slug} --role check --json`,
      `${plural(writtenSince, "section")} written since the last check`,
      true,
      [`orc doc lint ${slug} --json`, `orc doc map ${slug} --json`]
    );

  if (!v2 && open.length)
    return A("D6", "plan-write", `orc doc plan ${slug} --role write --json`, `${plural(open.length, "required section")} still open`, true);

  const audit = docAuditFindings(claudeDir, slug);
  const blockingAudit = (audit.findings || []).filter((f) => f.level === "error");
  if (blockingAudit.length)
    return A("D9", "audit", `orc doc audit ${slug} --json`, blockingAudit[0].summary, false);

  if (!d.shipped)
    return BLOCK("D9", "the document is complete. Shipping is YOUR decision and it needs a destination — nothing here can infer one.", [
      `orc doc ship ${slug} --where "<where it went>"`,
      `/orc-challenge ${path.relative(p.root, view.document).split(path.sep).join("/")}`,
    ]);

  const drift = docShipDrift(d, view);
  if (drift && drift.length)
    return BLOCK(
      "D9",
      `shipped to ${d.shipped.where}, then ${plural(drift.length, "section")} changed (${drift.map((s) => s.heading).join(", ")}). Re-send it, or say why not.`,
      [`orc doc ship ${slug} --where "<where it went this time>"`, `orc doc audit ${slug} --json`]
    );

  return BLOCK("D9", `shipped ${d.shipped.at} to ${d.shipped.where}, and nothing has changed since. There is nothing to do.`);
}

function docNextCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const next = slug ? docNextAction(claudeDir, slug) : null;
  if (!next) return docNoSuch(asJson, slugArg);
  // v0.52.0 (D9) — BEFORE the wave, not after. A document's VOICE is the
  // deliverable, so which sections are about to be written by something other
  // than Claude is a thing the user has to be able to see and then find.
  next.extra = docExtraNext(claudeDir, slug);
  const code = next.blocked_by ? 1 : 0;
  if (asJson) emitJson(next, code);
  console.log(ui.header(`ORC · doc next — ${slug}`));
  console.log(`\n  ${next.phase}   ${next.action}`);
  console.log(`  ${ui.color.gray(next.why)}`);
  if (next.command) console.log(`\n  ${next.paid ? "PAID  " : "free  "}${next.command}`);
  else console.log(`\n  ${ui.color.yellow("waiting on you: " + next.blocked_by)}`);
  if (next.alternatives.length) console.log(ui.color.gray("\n  also possible: " + next.alternatives.join("  ·  ")));
  if (next.extra && next.extra.sentence) console.log("\n  " + next.extra.sentence);
  process.exit(code);
}

// Which sections of the NEXT write wave go off Claude, named. `off` is still an
// answer and still gets a sentence — silence would make "nothing leaves Claude"
// and "nobody checked" identical.
function docExtraNext(claudeDir, slug) {
  const d = docRead(claudeDir, slug);
  if (!d) return null;
  const r = docExtraResolve(claudeDir, d);
  let sections = [];
  if (r.resolved === "writer" || r.resolved === "both") {
    try {
      const shape = docPlanShape(claudeDir, slug, "write");
      if (shape && shape.slices) sections = shape.slices.flatMap((x) => x.sections || []).map((x) => (x && x.id) || x);
    } catch (_) {}
  }
  // v0.55.0 — WHICH MODEL PER ROLE, not just "extra is on". "the writer went
  // foreign" and "the checker went foreign" are different facts about a
  // document, because a document's VOICE is the deliverable and only one of
  // those two writes it.
  const per = ["writer", "checker"]
    .map((role) => {
      const t = r.targets[role];
      return t ? `${role} → ${t.provider}/${t.model} (via ${t.profile}, displaces ${t.claude.agent})` : null;
    })
    .filter(Boolean);
  return {
    resolved: r.resolved,
    stored: r.stored,
    source: r.source,
    why: r.why,
    shadowed_by_slots: r.shadowed_by_slots,
    legacy_warning: r.legacy_warning,
    targets: r.targets,
    sections,
    sentence:
      r.resolved === "off"
        ? "extra: off — every section of this document is written and checked on Claude."
        : `extra: ${r.resolved} — ${sections.length ? "sections " + sections.join(", ") : "the next wave"} will be written off Claude. ` +
          per.join("; ") +
          ". A document's voice is the deliverable, so this is said before the wave, not after it.",
  };
}



// The outline's identity: ids, headings and budgets, in order. It is what
// decides whether a stored forecast still describes THIS document — the same
// question `compiled.source_hashes` answers for the build artifact.
const docOutlineHash = (d) =>
  docHash(((d && d.outline) || []).map((o) => `${o.id}|${o.heading}|${o.budget_lines}`).join("\n"));

// ── §D — THE WAVE FORECAST, ONCE, BEFORE THE FIRST WAVE (v0.49.2) ───────────
// The user is asked `partial` or `all` with no idea what either costs or how
// many stops there will be. This answers both, from `orc doc plan --role write`
// over ALL waves (never the `partial` truncation — they are being told what the
// WHOLE document costs) × the same rate model `orc budget` uses.
//
// Every honesty rule of /orc-budget is INHERITED, not re-invented: four token
// kinds never blended, a range with a sample count, no dollars without a dated
// price table, no quota without a known plan, `unattributed` always reported,
// and NO HISTORY MEANS NO FORECAST — it refuses rather than inventing numbers.
function docForecastCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const cfg = resolvedConfig(claudeDir);
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  const naive = flag("--naive") === true;
  const asView = typeof flag("--as") === "string" ? String(flag("--as")) : "all";
  const table = readPricing(claudeDir);
  readPricingCache = table;

  const rates = naive ? null : budgetRates(claudeDir);
  const minSamples = Number(cfg.budget_min_samples) || 5;
  if (!naive && !(rates && rates.dispatches_joined)) {
    const msg =
      "BUDGET · no forecast\n" +
      `  0 joinable dispatches in ${resolveLogDir(claudeDir)}.\n` +
      "  I will not invent numbers. Write one wave, then ask again.\n" +
      "  A floor from the public price table only:  orc doc forecast " + slug + " --naive";
    d.forecast = {
      shown_at: fmtStamp(new Date()),
      waves: null,
      tokens: null,
      write_mode: d.write_mode || null,
      outline_hash: docOutlineHash(d),
      available: false,
      reason: "no-history",
    };
    docWrite(claudeDir, slug, d);
    if (asJson) emitJson({ ok: false, reason: "no-history", slug, hint: msg, shown_at: d.forecast.shown_at }, 3);
    console.log(msg);
    process.exit(3);
  }

  // The wave shape comes from the SAME batcher the dispatch uses, so a forecast
  // can never describe a run-map the run will not follow.
  const shape = docPlanShape(claudeDir, slug, "write");
  const checks = docPlanShape(claudeDir, slug, "check");
  const writeRole = "orc-doc-writer-opus-5-med";
  const checkRole = "orc-doc-checker-opus-5-low";
  const roleRate = (name) => (rates && rates.roles && rates.roles[name]) || null;

  const vecFor = (name, n, p) => {
    const src = roleRate(name);
    if (src) return mulVec(src[p], n);
    // The --naive floor: one agent's worth of the SMALLEST thing the price table
    // can price. Labelled a floor everywhere it is printed.
    return mulVec({ input: 12000, cache_write: 40000, cache_read: 90000, output: 6000 }, n);
  };
  const lowConfidence = [writeRole, checkRole].filter((r) => {
    const src = roleRate(r);
    return !src || src.samples < minSamples;
  });

  const waves = shape.waves.map((w) => ({
    n: w.n,
    agents: w.agents.length,
    sections: w.agents.flatMap((a) => a.sections),
    headings: w.agents.flatMap((a) => a.headings),
    budget_lines: w.agents.reduce((a, x) => a + x.budget_lines, 0),
    p50: vecFor(writeRole, w.agents.length, "p50"),
    p90: vecFor(writeRole, w.agents.length, "p90"),
  }));
  const writeAgents = waves.reduce((a, w) => a + w.agents, 0);
  const checkAgents = checks.waves.reduce((a, w) => a + w.agents.length, 0);
  const p50 = sumVec(vecFor(writeRole, writeAgents, "p50"), vecFor(checkRole, checkAgents, "p50"));
  const p90 = sumVec(vecFor(writeRole, writeAgents, "p90"), vecFor(checkRole, checkAgents, "p90"));

  // ── THE POSITIONS (v0.55.0) ────────────────────────────────────────────
  // Slots are not scored, so `bandFor`'s ask-the-resolver-first comment cannot
  // help here — this lane has to ask `extraResolveSlot` itself. Without it a
  // document whose writer runs on DeepSeek is forecast at Opus rates, which is
  // exactly the lie the honest-numbers lane exists to prevent.
  //
  // AND A FOREIGN ROLE IS PRICED FROM ITS OWN PROVIDER, or not at all: a cost
  // figure ORC did not price itself is never printed, so `usd` reads as an em
  // dash rather than as an Opus number for work Opus will not do.
  const docExtra = docExtraResolve(claudeDir, d);
  const roleParts = [
    { role: "writer", agent: writeRole, n: writeAgents, target: docExtra.targets.writer },
    { role: "checker", agent: checkRole, n: checkAgents, target: docExtra.targets.checker },
  ];
  let priceable = true;
  const usdAt = (pct) => {
    let total = 0;
    for (const part of roleParts) {
      const vec = vecFor(part.agent, part.n, pct);
      if (!part.target) {
        const m = priceVector(claudeDir, vec, "claude-opus-5");
        if (m.usd === null) priceable = false;
        else total += m.usd;
        continue;
      }
      const rate = foreignRate(table, part.target.provider, part.target.model);
      if (!rate) {
        // `bin/pricing.json`'s provider maps ship EMPTY on purpose. This is the
        // honest answer, not a gap ORC forgot to fill: `orc extra rates` prints
        // the JSON to paste.
        priceable = false;
        continue;
      }
      total +=
        (vec.input * rate.input +
          vec.cache_write * rate.cache_write +
          vec.cache_read * rate.cache_read +
          vec.output * rate.output) /
        1e6;
    }
    return priceable ? total : null;
  };
  const usd50 = usdAt("p50");
  const usd90 = usdAt("p90");
  const money50 = priceVector(claudeDir, p50, "claude-opus-5");
  const money90 = priceVector(claudeDir, p90, "claude-opus-5");
  const extraView = {
    resolved: docExtra.resolved,
    why: docExtra.why,
    roles: roleParts.map((part) => ({
      role: part.role,
      agents: part.n,
      via: part.target ? `extra:${part.target.profile}` : "claude",
      provider: part.target ? part.target.provider : null,
      model: part.target ? part.target.model : part.agent,
      displaces: part.target ? part.target.claude.agent : null,
      priced: part.target ? !!foreignRate(table, part.target.provider, part.target.model) : true,
    })),
    // The QUOTA half. A foreign dispatch does not touch the Anthropic session
    // window at all, so counting it there would overstate the limit that
    // actually bites.
    quota_note: roleParts.some((x) => x.target)
      ? "a role that runs off Claude does NOT consume the Claude session window — the quota figure below covers the Claude half only."
      : null,
  };
  const quota = quotaView(table, cfg, money50.weighted);
  const writeMode = d.write_mode || (cfg.doc_write_mode === "ask" ? null : cfg.doc_write_mode);
  // A STOP is a hand-back. In `partial` every wave is one; in `all` the whole
  // write is one.
  const stops = writeMode === "partial" ? waves.length : 1;

  const payload = {
    ok: true,
    slug,
    write_mode: writeMode,
    stops,
    waves,
    checks: {
      agents: checkAgents,
      p50: vecFor(checkRole, checkAgents, "p50"),
      p90: vecFor(checkRole, checkAgents, "p90"),
      note: "the check pass is forecast separately — it is a second decision, not part of the write",
    },
    tokens: { p50, p90 },
    raw: { p50: rawTokens(p50), p90: rawTokens(p90) },
    weighted: { p50: money50.weighted, p90: money90.weighted },
    // NULL when any part of the run cannot be priced from a DATED table, never
    // an Opus figure standing in for a provider ORC has no rates for.
    usd: { p50: usd50, p90: usd90 },
    usd_claude_only: { p50: money50.usd, p90: money90.usd },
    extra: extraView,
    price_table: table ? { as_of: table.as_of, age_days: table._age_days, stale: table._stale } : null,
    quota,
    min_samples: minSamples,
    samples: { write: (roleRate(writeRole) || {}).samples || 0, check: (roleRate(checkRole) || {}).samples || 0 },
    low_confidence_roles: lowConfidence,
    naive,
    unattributed: rates ? rates.unattributed : { blocks: 0, tokens: ZERO_VEC },
    free_steps: ["orc doc compile", "orc doc lint", "orc doc parts", "orc doc audit"],
    shown_at: (d.forecast && d.forecast.shown_at) || null,
    view: asView,
  };

  // Recorded so `orc doc next` names it EXACTLY ONCE. A resumed session in a
  // fresh context does not re-show it, because the record is on disk rather than
  // in a model's memory. Running it BY HAND always recomputes and always prints —
  // the once-rule governs `next`, never the user.
  d.forecast = {
    shown_at: (d.forecast && d.forecast.shown_at) || fmtStamp(new Date()),
    waves: waves.length,
    tokens: p50,
    write_mode: writeMode,
    outline_hash: docOutlineHash(d),
    available: true,
    naive,
  };
  docWrite(claudeDir, slug, d);

  const code = lowConfidence.length ? 1 : 0;
  if (asJson) emitJson(payload, code);

  console.log(ui.header(`ORC · doc forecast — ${slug}`));
  console.log(
    `\n  This document is ${plural(shape.items, "section")} in ${plural(waves.length, "wave")}, ` +
      `${shape.parallel} ${shape.parallel === 1 ? "agent" : "agents"} per wave.`
  );
  console.log("");
  for (const w of waves)
    console.log(
      `  wave ${String(w.n).padEnd(2)} ${w.sections.join(" + ").padEnd(34)} ~${String(w.budget_lines).padStart(4)} lines   ` +
        `p50 ${kTok(weightedTokens(w.p50)).padStart(7)}   p90 ${kTok(weightedTokens(w.p90)).padStart(7)}`
    );
  console.log(`  then    compile (free) → lint (free) → ${plural(checkAgents, "checker read")}`);
  console.log(
    `\n  TOKENS  p50 in ${kTok(p50.input)} · cache-w ${kTok(p50.cache_write)} · cache-r ${kTok(p50.cache_read)} · out ${kTok(p50.output)}`
  );
  console.log(`          p90 in ${kTok(p90.input)} · cache-w ${kTok(p90.cache_write)} · cache-r ${kTok(p90.cache_read)} · out ${kTok(p90.output)}`);
  console.log(
    `  USD     ` +
      (usd50 === null
        ? "—  (no dated rate for at least one of the models this run will use)"
        : `$${usd50.toFixed(2)} → $${usd90.toFixed(2)}`)
  );
  console.log(`  QUOTA   ` + (quota.available ? `${quota.window_pct.toFixed(1)}% of a 5-hour window on ${quota.label}` : quota.reason));
  // v0.55.0 — WHO RUNS WHICH HALF. Printed on BOTH surfaces: a field one
  // surface prints and the other omits is drift no lint can see.
  for (const r of extraView.roles)
    console.log(
      `  ${r.role.toUpperCase().padEnd(8)}` +
        (r.via === "claude"
          ? ui.color.gray(`claude · ${r.model} · ${plural(r.agents, "agent")}`)
          : ui.color.cyan(`${r.provider}/${r.model}`) +
            ui.color.gray(`  via ${r.via.slice(6)} · ${plural(r.agents, "agent")} · displaces ${r.displaces}`) +
            (r.priced ? "" : ui.color.yellow("  · no dated rate for this model")))
    );
  if (extraView.quota_note) console.log("  " + ui.color.gray(extraView.quota_note));
  console.log(
    `\n  Every wave is a stop. ` +
      (writeMode === "partial"
        ? `In partial you pay for wave 1 and then decide — ${plural(stops, "stop")} in all.`
        : writeMode === "all"
          ? `In all mode the whole write runs, then hands back once.`
          : `The mode is not chosen yet — it is asked once and stored.`)
  );
  if (naive) console.log(ui.color.yellow(`\n  --naive: this is a FLOOR from the price table, not a forecast from your history.`));
  if (lowConfidence.length)
    console.log(
      ui.color.yellow(
        `\n  LOW CONFIDENCE: ${lowConfidence.join(", ")} ${lowConfidence.length === 1 ? "has" : "have"} fewer than ${minSamples} samples. ` +
          `The total is a FLOOR, not a range.`
      )
    );
  if (rates && rates.unattributed)
    console.log(
      ui.color.gray(`  ${kTok(rawTokens(rates.unattributed.tokens))} in ${plural(rates.unattributed.blocks, "block")} are unattributed in the corpus.`)
    );
  process.exit(code);
}

// ── §E — WHAT THIS DOCUMENT COST (v0.49.2) ──────────────────────────────────
// `orc budget actual` works per RUN. A document spans several runs — that is the
// whole design of this lane — so nobody could answer "what did this document
// cost". This joins EVERY trace whose slug matches, using the same
// `listTraces` → `readTraceMeta` → `readCorpus` → `joinRun` → `priceVector`
// pipeline `/orc-budget` already owns. It re-implements nothing.
//
// Per-section attribution is only honest because the doc lane's DISPATCH tail
// names the sections it was for:
//   DISPATCH orc-doc-writer-opus-5-med :: doc write sections=03-goals,04-scope …
// A dispatch whose sections cannot be read reports `joined: false` and
// `tokens: null` — NEVER zero. An unknown reported as a number is worse than an
// unknown reported as unknown (the /orc-pact UNCHECKABLE rule).
const DOC_TRACE_TAIL_RE = /\bsections=([\w,-]+)/;
const DOC_TRACE_ROLE_RE = /\bdoc\s+(write|check|digest|edit)\b/;

function docCostCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const slug = docResolveSlug(claudeDir, slugArg);
  const d = slug ? docRead(claudeDir, slug) : null;
  if (!d) return docNoSuch(asJson, slugArg);
  readPricingCache = readPricing(claudeDir);

  const { runs } = listTraces(claudeDir);
  // EVERY trace for this slug. Several sessions per document is CORRECT, and the
  // counts have to add up across them.
  const mine = runs.filter((r) => r.slug && (r.slug === slug || r.slug.startsWith(slug) || slug.startsWith(r.slug)));
  if (!mine.length) {
    const hint =
      `no trace for "${slug}" in ${resolveLogDir(claudeDir)}. ` +
      `A cost report is joined from traces and local transcripts — it is never estimated.`;
    if (asJson) emitJson({ ok: false, reason: "no-trace", slug, hint, known: runs.slice(0, 10).map((r) => r.slug) }, 3);
    console.log(hint);
    process.exit(3);
  }

  const corpus = readCorpus(repoRootOf(claudeDir));
  const byRole = {};
  const bySection = {};
  for (const o of d.outline || []) bySection[o.id] = { id: o.id, heading: o.heading, dispatches: 0, joined: 0, vec: { ...ZERO_VEC } };
  let total = { ...ZERO_VEC };
  let unattVec = { ...ZERO_VEC };
  let unattBlocks = 0;
  let dispatches = 0;
  let joined = 0;
  const runRows = [];

  for (const r of mine) {
    const trace = readTraceMeta(r.path);
    if (!trace) continue;
    const j = joinRun(trace, corpus.groups);
    let runVec = { ...ZERO_VEC };
    for (const row of j.rows) {
      dispatches++;
      const roleM = DOC_TRACE_ROLE_RE.exec(row.task || "");
      const role = roleM ? roleM[1] : "other";
      const ids = (DOC_TRACE_TAIL_RE.exec(row.task || "") || [null, ""])[1].split(",").filter(Boolean);
      for (const id of ids) if (bySection[id]) bySection[id].dispatches++;
      if (!row.group) continue;
      joined++;
      const vec = row.group.vec;
      total = sumVec(total, vec);
      runVec = sumVec(runVec, vec);
      const rr = (byRole[role] = byRole[role] || { dispatches: 0, vec: { ...ZERO_VEC } });
      rr.dispatches++;
      rr.vec = sumVec(rr.vec, vec);
      // A slice covering two sections SPLITS its cost evenly across them. It is
      // an even split, said out loud in `honesty[]` — never a weighting invented
      // from line counts nobody measured.
      if (ids.length) {
        const share = divVec(vec, ids.length);
        for (const id of ids)
          if (bySection[id]) {
            bySection[id].joined++;
            bySection[id].vec = sumVec(bySection[id].vec, share);
          }
      }
    }
    for (const g of j.unattributed) {
      unattBlocks++;
      unattVec = sumVec(unattVec, g.vec);
    }
    runRows.push({ trace: r.name, lane: r.lane, date: r.date, tokens: runVec, weighted: weightedTokens(runVec) });
  }

  const money = priceVector(claudeDir, total, "claude-opus-5");
  const sections = Object.values(bySection).map((s) => ({
    id: s.id,
    heading: s.heading,
    dispatches: s.dispatches,
    // NEVER zero for an unknown. A section with no joinable dispatch reads `—`.
    joined: s.joined > 0,
    tokens: s.joined ? s.vec : null,
    weighted: s.joined ? weightedTokens(s.vec) : null,
    usd: s.joined ? priceVector(claudeDir, s.vec, "claude-opus-5").usd : null,
  }));
  const unjoined = sections.filter((s) => !s.joined).length;
  const code = joined === 0 ? 3 : unjoined ? 1 : 0;

  const payload = {
    ok: joined > 0,
    slug,
    runs: runRows,
    total: { tokens: total, raw: rawTokens(total), weighted: money.weighted, usd: money.usd },
    by_role: Object.fromEntries(
      Object.entries(byRole).map(([k, v]) => [k, { dispatches: v.dispatches, tokens: v.vec, weighted: weightedTokens(v.vec) }])
    ),
    by_section: sections,
    dispatches,
    joined,
    // ALWAYS present, including when zero.
    unattributed: { blocks: unattBlocks, tokens: unattVec },
    price_table: readPricingCache ? { as_of: readPricingCache.as_of, age_days: readPricingCache._age_days, stale: readPricingCache._stale } : null,
    honesty: [
      "The join is nearest-in-time between an ORC trace and a local usage transcript. A dispatch the transcript cannot confirm is reported, never estimated.",
      "A slice that covered two sections splits its cost evenly between them — an even split, not a measurement.",
      "A section with no joinable dispatch reads —, never 0. An unknown reported as a number is worse than an unknown reported as unknown.",
    ],
  };
  if (asJson) emitJson(payload, code);

  console.log(ui.header(`ORC · doc cost — ${slug}`));
  console.log(`\n  ${plural(mine.length, "trace")} · ${joined} of ${plural(dispatches, "dispatch")} joined`);
  console.log("\n  section                            disp        weighted        usd");
  console.log("  " + "─".repeat(66));
  for (const s of sections)
    console.log(
      `  ${s.id.padEnd(32)} ${String(s.dispatches).padStart(4)}   ${(s.joined ? kTok(s.weighted) : "—").padStart(13)}   ${(s.usd === null ? "—" : "$" + s.usd.toFixed(2)).padStart(8)}`
    );
  console.log("  " + "─".repeat(66));
  for (const [role, v] of Object.entries(payload.by_role))
    console.log(`  ${("by role: " + role).padEnd(32)} ${String(v.dispatches).padStart(4)}   ${kTok(v.weighted).padStart(13)}`);
  console.log(
    `\n  TOTAL   ${kTok(money.weighted)} weighted / ${kTok(money.raw)} raw` + (money.usd === null ? "" : ` / $${money.usd.toFixed(2)}`)
  );
  console.log(
    `  unattributed  ${unattBlocks ? `${kTok(rawTokens(unattVec))} in ${plural(unattBlocks, "block")} could not be joined` : "0"}`
  );
  console.log(ui.color.gray("\n  " + payload.honesty.join("\n  ")));
  process.exit(code);
}

function docTemplatesCmd() {
  const asJson = wantsJson();
  const rows = DOC_TEMPLATES.map((t) => ({
    type: t.type,
    label: t.label,
    about: t.about,
    sections: t.sections.map((s) => ({ heading: s.heading, required: s.required !== false, budget_lines: s.budget, purpose: s.purpose })),
  }));
  if (asJson) emitJson({ ok: true, templates: rows }, 0);
  console.log(ui.header(`ORC · doc templates — ${plural(rows.length, "base template")}`));
  for (const t of rows) {
    console.log(`\n  ${t.type.padEnd(14)} ${t.label}`);
    console.log(`  ${"".padEnd(14)} ${ui.color.gray(t.about)}`);
    t.sections.forEach((s, i) => console.log(`  ${"".padEnd(14)} ${String(i + 1).padStart(3)}. ${s.heading}${s.required ? "" : "  (optional)"}`));
  }
  console.log(ui.color.gray("\n  A template is a floor, not a cage — bring your own with --template <path> and its headings become the outline."));
  process.exit(0);
}

function docTargetsCmd() {
  const asJson = wantsJson();
  if (asJson) emitJson({ ok: true, targets: DOC_TARGETS }, 0);
  console.log(ui.header(`ORC · doc targets — where a Markdown file can actually go`));
  console.log("");
  for (const t of DOC_TARGETS) {
    console.log(`  ${t.id.padEnd(12)} ${t.label.padEnd(28)} imports: ${t.imports}   max H${t.max_heading}   front matter: ${t.front_matter}`);
    console.log(`  ${"".padEnd(12)} ${ui.color.gray(t.watch)}`);
  }
  console.log(ui.color.gray("\n  A lint rule that came from a real product limit is worth ten invented ones."));
  process.exit(0);
}

function doc() {
  if (flag("--global")) {
    console.error("❌ orc doc is project-scoped — the document is this project's. Run it from the project (or with --dir <path>).");
    process.exit(1);
  }
  const claudeDir = resolveClaudeDir();
  const pos = docPositionals(); // ["doc", <sub?>, <slug|path?>]
  // The migration is LAZY, free, idempotent and non-destructive: it runs on the
  // first `orc doc <anything> <slug>` where version < 2. Never on `list` — a
  // listing must not mutate — and never on `init`/`migrate`, which own it.
  // `splice` and `extract` are excluded on purpose: a v1 document with a PENDING
  // extract has to reach its own hash-conflict refusal, preserved verbatim,
  // before anything moves. Two sessions on one slug is still a real risk.
  if (pos[1] && !["list", "init", "migrate", "splice", "extract", "templates", "targets", "rules"].includes(pos[1])) {
    const s = docResolveSlug(claudeDir, pos[2]);
    if (s) docMigrateV2(claudeDir, s);
  }
  switch (pos[1]) {
    case undefined:
    case "list":
      docListCmd(claudeDir);
      break;
    case "init":
      docInit(claudeDir);
      break;
    case "show":
      docShowCmd(claudeDir, pos[2]);
      break;
    case "map":
      docMapCmd(claudeDir, pos[2]);
      break;
    case "plan":
      docPlanCmd(claudeDir, pos[2]);
      break;
    case "outline":
      docOutlineCmd(claudeDir, pos[2]);
      break;
    case "extract":
      docExtractCmd(claudeDir, pos[2]);
      break;
    case "splice":
      docSpliceCmd(claudeDir, pos[2]);
      break;
    case "assemble":
      // Alias for one release, naming the new command. Exit codes preserved.
      docCompileCmd(claudeDir, pos[2], { alias: "assemble" });
      break;
    // v0.49.0 — sections/ is the source of truth, document.md is a build artifact
    case "compile":
      docCompileCmd(claudeDir, pos[2]);
      break;
    case "parts":
      docPartsCmd(claudeDir, pos[2]);
      break;
    case "split":
      docSplitCmd(claudeDir, pos[2]);
      break;
    case "migrate":
      docMigrateCmd(claudeDir, pos[2]);
      break;
    case "mode":
      docModeCmd(claudeDir, pos[2]);
      break;
    // v0.52.0 (D9) — PER DOCUMENT, because a global switch turns Extra on for
    // the PRD you ship as well as for the throwaway runbook.
    case "extra":
      docExtraCmd(claudeDir, pos[2]);
      break;
    // v0.49.2 — the project's OWN standing instructions about what a document
    // says and how it reads, plus the per-document frozen set and its drift.
    case "rules":
      docRulesCmd(claudeDir, undefined);
      break;
    case "cost":
      docCostCmd(claudeDir, pos[2]);
      break;
    case "forecast":
      docForecastCmd(claudeDir, pos[2]);
      break;
    case "lint":
      docLintCmd(claudeDir, pos[2]);
      break;
    case "status":
      docStatusCmd(claudeDir, pos[2]);
      break;
    // v0.48.1 — the score, the finish line, the drift report and the memory.
    case "next":
      docNextCmd(claudeDir, pos[2]);
      break;
    // v0.49.5 - the hand-back, on demand. docWrite() already refreshes it on
    // every state change; this is the lane's explicit "write it now" before it
    // asks the user anything.
    case "resume-file":
      docResumeFileCmd(claudeDir, pos[2]);
      break;
    case "ship":
      docShipCmd(claudeDir, pos[2], false);
      break;
    case "unship":
      docShipCmd(claudeDir, pos[2], true);
      break;
    case "audit":
      docAuditCmd(claudeDir, pos[2]);
      break;
    case "log":
      docLogCmd(claudeDir, pos[2]);
      break;
    case "journal":
      docJournalCmd(claudeDir, pos[2]);
      break;
    case "context":
      docContextCmd(claudeDir, pos[2]);
      break;
    case "read":
      docReadCmd(claudeDir, pos[2]);
      break;
    case "templates":
      docTemplatesCmd();
      break;
    case "targets":
      docTargetsCmd();
      break;
    default:
      console.error(
        `Unknown: orc doc ${pos[1]}\n` +
          "Usage: orc doc list [--json]                        every document + its `Where it stands:` line\n" +
          "       orc doc next <slug> [--json]                 THE NEXT LEGAL ACTION. 0 = do it / 1 = a human decides / 2 = unknown\n" +
          "       orc doc status <slug> [--json]               0 nothing to do / 1 something to do / 2 unknown slug\n" +
          "       orc doc show <slug> [--json]                 full state: sections, cycles, extracts\n" +
          "       orc doc map <slug> [--json]                  the DERIVED section map (fresh line numbers)\n" +
          "       orc doc parts <slug> [--confirm <ids>]       the SECTION FILES (works before any compile)\n" +
          "       orc doc compile <slug> [--partial]           sections/ -> document.md. FREE, on demand\n" +
          "       orc doc split <slug> [--section <id> --by-heading]  document -> sections/, or a section -> parts\n" +
          "       orc doc migrate <slug> [--clean]             v1 -> v2, lazy and non-destructive\n" +
          "       orc doc mode <slug> [--set partial|all]      how much is bought at once\n" +
          "       orc doc plan <slug> --role write|check|edit  the batching (never splits a section, <=2)\n" +
          "       orc doc outline <slug> [--set <path>]        the agreed section list\n" +
          "       orc doc extract <slug> --section <id>        alias — in v2 the section file IS the extract\n" +
          "       orc doc splice <slug>                        alias -> compile (v1 parts are drained first)\n" +
          "       orc doc assemble <slug>                      alias -> compile\n" +
          "       orc doc lint <slug|path> [--target <t>]      the free check (0 clean / 1 findings / 2 none)\n" +
          "       orc doc audit <slug> [--json]                every drift class, from disk (0 clean / 1 findings)\n" +
          "       orc doc ship <slug> --where <destination>    record the delivery. --where has NO DEFAULT\n" +
          "       orc doc unship <slug> --reason <text>        undo it; the old record is kept in ship_history\n" +
          "       orc doc log <slug> --kind request|decision|gate|note|gap --text <t>\n" +
          "       orc doc journal <slug> [--json]              the ordered story, gaps shown AS gaps\n" +
          "       orc doc context <slug> [--json]              the frozen brief + whether its sources still hold\n" +
          "       orc doc read <slug> [--section <id>|--toc]   FOR THE HUMAN — the orchestrator never runs this\n" +
          "       orc doc templates | targets [--json]\n" +
          "       orc doc init <slug> --type <" + DOC_TYPES.join("|") + "> [--template <p>] [--target <t>]"
      );
      process.exit(1);
  }
}

function where() {
  const claudeDir = resolveClaudeDir();
  if (wantsJson())
    return emitJson({
      claude_dir: claudeDir,
      project_root: repoRootOf(claudeDir),
      package_root: PKG_ROOT,
      package_version: currentVersion(),
      installed_version: installedPayloadVersion(claudeDir),
      skills: path.join(claudeDir, "skills"),
      commands: path.join(claudeDir, "commands"),
      agents: path.join(claudeDir, "agents"),
      hooks: path.join(claudeDir, "hooks"),
      settings: path.join(claudeDir, "settings.json"),
      config: overridePath(claudeDir),
      run_dir: resolveRunDir(claudeDir),
      log_dir: resolveLogDir(claudeDir),
    });
  console.log("skills   →", path.join(claudeDir, "skills"));
  console.log("commands →", path.join(claudeDir, "commands"));
  console.log("agents   →", path.join(claudeDir, "agents"));
  console.log("hooks    →", path.join(claudeDir, "hooks"));
  console.log("settings →", path.join(claudeDir, "settings.json"), "(merged)");
  console.log(
    "config   →",
    path.join(claudeDir, "orc.config.yaml"),
    "(user overrides via `orc config`; update-safe)"
  );
}

// ═══════════════════════════════════════════════════════════════════════════
// orc extra (v0.50.0) — dispatch ORC's WORKERS to non-Claude agents
//
// The orchestrator stays Claude. What changes is who executes a slice: a score
// band the user owns can point at DeepSeek, GLM, Kimi, a local Ollama, or any
// OpenAI-/Anthropic-compatible endpoint they can name. Everything ORC already
// does around a dispatch — the wave scheduler, the smoke gate, the TDD gate,
// the worktree-delta check, the trace, the budget — is engine-blind, which is
// the property that makes this safe rather than clever.
//
// THE HARD RULES THIS HALF ENFORCES (the skill half carries the rest):
//   P2  a key is never stored where it can be committed, and never printed.
//       The DEFAULT credential source is an environment variable NAME; ORC
//       stores the name. `orc extra list --json` returns
//       { source, key_name, present } and nothing more — a test greps every
//       --json shape for a key-shaped string.
//   P4  ORC ships a PROVIDER catalog, never a MODEL catalog. Model ids come
//       from the wire at ping time (`models_seen`). bin/providers.json is
//       DATED like bin/pricing.json and warns past 90 days.
//   P5  there is ONE resolver (`orc extra resolve`).
//
// `.claude/orc/extra.json` is the ledger and `orc extra` is its ONLY writer,
// the same discipline as doc.json, challenge.json and the pact ledger.
// ═══════════════════════════════════════════════════════════════════════════

const EXTRA_LEDGER = "extra.json";
const EXTRA_CATALOG = path.join(__dirname, "providers.json");
const EXTRA_CATALOG_STALE_DAYS = 90;
const EXTRA_ENGINES = ["api", "claude-shim", "cli"];
// Anything else is a header ORC would have to guess at. Claude Code picks the
// header FROM the variable name, so this list IS the auth shape.
const EXTRA_AUTH_ENVS = ["ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_API_KEY"];

function extraPaths(claudeDir) {
  return {
    root: repoRootOf(claudeDir),
    dir: path.join(claudeDir, "orc"),
    ledger: path.join(claudeDir, "orc", EXTRA_LEDGER),
    vault: path.join(claudeDir, "orc", "extra-vault.json"),
    // v0.52.0 — the passphrase cache. IN THE PROJECT, gitignored beside the
    // vault, and encrypted under the pepper that lives in $HOME. That split is
    // what makes "a copied project folder opens nothing" a property rather than
    // a hope, and it is why the project is the RIGHT place for it. The name is
    // STABLE and non-obvious, never random: a name that changes per write is a
    // file nobody can find to delete, and "delete it whenever you like" is the
    // whole point.
    session: path.join(claudeDir, "orc", ".orc-ec-session"),
  };
}

// The shipped catalog, with its age computed on READ — never stored. Same
// shape as readPricing(): `_age_days` / `_stale` ride on the object so every
// caller renders the same staleness sentence.
function readCatalog() {
  try {
    const t = JSON.parse(fs.readFileSync(EXTRA_CATALOG, "utf8"));
    t.providers = Array.isArray(t.providers) ? t.providers : [];
    const asOf = Date.parse(String(t.as_of || "") + "T00:00:00Z");
    t._age_days = isNaN(asOf) ? null : Math.floor((Date.now() - asOf) / 86400000);
    t._stale = t._age_days === null || t._age_days > EXTRA_CATALOG_STALE_DAYS;
    t._path = EXTRA_CATALOG;
    return t;
  } catch (_) {
    return null;
  }
}
const catalogRow = (cat, id) => (cat ? cat.providers.find((p) => p.id === id) || null : null);

// A provider row + a region id → the two base URLs actually in play. Kept in
// ONE place because a region is not cosmetic: a MiniMax key issued for the
// international host does not authenticate against the China host, and the
// failure is a 401 with nothing on screen explaining why.
function providerBases(row, region) {
  if (!row) return { api_base: null, anthropic_base: null, region: "default" };
  const r = region && region !== "default" ? (row.regions || []).find((x) => x.id === region) : null;
  return {
    api_base: (r && r.api_base) || row.api_base || null,
    anthropic_base: (r && r.anthropic_base) || row.anthropic_base || null,
    region: r ? r.id : "default",
  };
}

function readExtra(claudeDir) {
  const p = extraPaths(claudeDir);
  if (!fs.existsSync(p.ledger)) return null;
  try {
    const l = JSON.parse(fs.readFileSync(p.ledger, "utf8"));
    l.profiles = Array.isArray(l.profiles) ? l.profiles : [];
    l.routes = Array.isArray(l.routes) ? l.routes : [];
    // v0.55.0 — SLOT ROWS. A v1 ledger reads `slots: []` and is NEVER rewritten
    // on read: lazy, free, idempotent, non-destructive (the /orc-doc migration
    // rule). A reader of the old shape finds nothing missing, because the
    // addition is additive — the `challenge.json` v2 precedent.
    l.slots = Array.isArray(l.slots) ? l.slots : [];
    l.history = Array.isArray(l.history) ? l.history : [];
    return l;
  } catch (_) {
    return null;
  }
}
const emptyExtra = () => ({ version: 2, profiles: [], routes: [], slots: [], history: [] });

function writeExtra(claudeDir, ledger) {
  const p = extraPaths(claudeDir);
  fs.mkdirSync(p.dir, { recursive: true });
  ledger.slots = Array.isArray(ledger.slots) ? ledger.slots : [];
  ledger.version = 2;
  ledger.updated_at = new Date().toISOString();
  fs.writeFileSync(p.ledger, JSON.stringify(ledger, null, 2) + "\n");
  return p.ledger;
}

function extraHistory(ledger, action, detail) {
  ledger.history = Array.isArray(ledger.history) ? ledger.history : [];
  ledger.history.push(Object.assign({ at: new Date().toISOString(), action }, detail || {}));
  return ledger;
}

const extraProfile = (ledger, name) =>
  (ledger && ledger.profiles.find((x) => x.name === name)) || null;

// ── P2: the ONE redaction. Every `--json` route goes through this ───────────
// There is no secret in the ledger by construction — `credential` holds an
// env-var NAME or a vault pointer, never a value — but "by construction" is a
// property that survives exactly as long as nobody adds a field. So the shape
// is built by ALLOW-LIST here: a future key carrying a secret would have to be
// added to this function on purpose, in a diff a reviewer reads.
function redactProfile(prof, claudeDir) {
  const cred = prof.credential || { source: "env", key_name: null };
  return {
    name: prof.name,
    provider: prof.provider,
    engine: prof.engine,
    region: prof.region || "default",
    cli: prof.cli || null,
    base_url: prof.base_url || null,
    anthropic_base_url: prof.anthropic_base_url || null,
    completions_path: prof.completions_path || null,
    auth_env: prof.auth_env || null,
    credential: {
      source: cred.source || "env",
      key_name: cred.key_name || null,
      present: credentialPresent(cred, claudeDir),
      vault: credentialVaultState(cred, claudeDir),
    },
    verified_at: prof.verified_at || null,
    // v0.52.0 — the passphrase DEADLINE rides on the profile row, computed on
    // read. A read's --json is the WHOLE computed object, and the panel draws a
    // countdown chip beside the vault chip from exactly this.
    session: (prof.credential || {}).source === "vault" ? extraSessionStateSwept(claudeDir, prof.name) : null,
    expired_at: prof.expired_at || null,
    verify_method: prof.verify_method || null,
    verify_base_url: prof.verify_base_url || null,
    // v0.53.3 — WHICH CREDENTIAL EARNED THE BADGE. A probe and a dispatch used
    // to resolve the credential differently, so "verified" could be true of a
    // path no wave ever runs. They resolve identically now; this field is how a
    // reader can tell without taking that on trust.
    verify_credential_source: prof.verify_credential_source || null,
    latency_ms: prof.latency_ms === undefined ? null : prof.latency_ms,
    models_seen: Array.isArray(prof.models_seen) ? prof.models_seen : [],
    model_map: prof.model_map || null,
    tool_fidelity: prof.tool_fidelity || null,
    privacy: prof.privacy || null,
    notes: prof.notes || null,
  };
}

// `present` is the ONE bit of a credential ORC will say out loud: is there
// something to send. For an env source that is whether the variable is set in
// THIS process; for a vault source it is whether a record exists on disk.
// Neither reads a value into a place it could be printed.
function credentialPresent(cred, claudeDir) {
  const src = (cred && cred.source) || "env";
  // The tool holds its own. ORC has nothing to send and nothing is missing, so
  // neither `found` nor `not found` is the truth — null is.
  if (src === "tool") return null;
  if (src === "env") return !!(cred.key_name && process.env[cred.key_name]);
  if (src === "vault") {
    try {
      const v = JSON.parse(fs.readFileSync(extraPaths(claudeDir).vault, "utf8"));
      const rec = v && v.records && v.records[cred.key_name];
      // A WIPED record is a tombstone with no ciphertext. `present: false` is
      // the right answer for it, and `vault_state` below is what keeps "wiped"
      // and "never had a key" from collapsing into the same chip.
      return !!(rec && rec.ciphertext && !rec.wiped_at);
    } catch (_) {
      return false;
    }
  }
  return false;
}

// The vault record's own state, kept separate from `present` because a panel
// that showed only presence could not tell a user their key was DELETED.
function credentialVaultState(cred, claudeDir) {
  if ((cred && cred.source) !== "vault") return null;
  try {
    const v = JSON.parse(fs.readFileSync(extraPaths(claudeDir).vault, "utf8"));
    const rec = v && v.records && v.records[cred.key_name];
    if (!rec) return { state: "none", attempts_used: 0, wiped_at: null };
    if (rec.wiped_at) return { state: "wiped", attempts_used: Number(rec.attempts) || 0, wiped_at: rec.wiped_at };
    return { state: "stored", attempts_used: Number(rec.attempts) || 0, wiped_at: null };
  } catch (_) {
    return { state: "none", attempts_used: 0, wiped_at: null };
  }
}

// A secret that reaches disk reaches a commit. `orc extra add` appends the
// vault path to .gitignore ONCE, idempotently, and never rewrites a line it
// did not add.
const EXTRA_GITIGNORE_LINES = [
  ".claude/orc/extra-vault.json",
  // The cached PASSPHRASE, which opens the file above it. Same rule, same
  // mechanism — this list is idempotent, so the line arrives on the next
  // `orc extra` write with no migration of its own.
  ".claude/orc/.orc-ec-session",
  // Engine `cli` writes the task text and reads the tool's final message
  // here, INSIDE the repo, because a workspace-write sandbox cannot write
  // outside the workspace. It is removed in a `finally`; this line is what
  // makes a CRASHED run leave an ignored file rather than a staged one.
  ".orc-extra/",
];
function ensureExtraGitignore(root) {
  const p = path.join(root, ".gitignore");
  let text = "";
  try {
    text = fs.readFileSync(p, "utf8");
  } catch (_) {}
  const have = new Set(text.split(/\r?\n/).map((l) => l.trim()));
  const missing = EXTRA_GITIGNORE_LINES.filter((l) => !have.has(l));
  if (!missing.length) return null;
  const sep = text && !text.endsWith("\n") ? "\n" : "";
  try {
    fs.writeFileSync(
      p,
      text + sep + "# orc extra — the credential vault NEVER belongs in a commit\n" + missing.join("\n") + "\n"
    );
  } catch (_) {
    return null;
  }
  return missing;
}

// ── orc extra providers ────────────────────────────────────────────────────
function extraProvidersCmd() {
  const cat = readCatalog();
  const asJson = wantsJson();
  if (!cat) {
    const hint = `provider catalog missing or unreadable at ${EXTRA_CATALOG} — this is a packaging bug; reinstall orc.`;
    if (asJson) emitJson({ ok: false, reason: "no-catalog", path: EXTRA_CATALOG, hint }, 1);
    console.error("❌ " + hint);
    process.exit(1);
  }
  const rows = cat.providers.map((p) => ({
    id: p.id,
    label: p.label,
    engines: p.engines || [],
    api_base: p.api_base,
    anthropic_base: p.anthropic_base,
    auth_env: p.auth_env,
    env_key_default: p.env_key_default,
    models_path: p.models_path,
    context_tokens: p.context_tokens === undefined ? null : p.context_tokens,
    regions: (p.regions || []).map((r) => ({ id: r.id, label: r.label })),
    docs_url: p.docs_url || null,
    terms_url: p.terms_url || null,
    notes: p.notes || null,
    // v0.51.0 — the three keys a renderer needs to tell a LOCAL TOOL from an
    // endpoint. `cli_bin` names the binary a row's only surface is, `install`
    // carries the dated command (filtered to this platform by the CLI, so the
    // panel never picks), and `models_public` is why a 200 on /models is not
    // always a credential proof.
    cli_bin: p.cli_bin || null,
    min_version: p.min_version || null,
    models_public: p.models_public === true,
    no_install_alternative: p.no_install_alternative === undefined ? null : p.no_install_alternative,
    install: p.install ? extraInstallView(p) : null,
    credential: p.credential || null,
  }));
  if (asJson)
    emitJson(
      {
        ok: true,
        path: cat._path,
        as_of: cat.as_of,
        age_days: cat._age_days,
        stale: cat._stale,
        stale_after_days: EXTRA_CATALOG_STALE_DAYS,
        // P4, said out loud in the payload so a renderer cannot invent a model
        // dropdown out of this.
        models: "never shipped — `orc extra ping` reads them from the provider",
        providers: rows,
      },
      0
    );
  console.log(ui.header(`ORC · extra — ${plural(rows.length, "provider")} (catalog dated ${cat.as_of})`));
  console.log("");
  console.log(
    ui.kv(
      rows.map((r) => [
        r.id,
        r.label + (r.regions.length ? ui.color.gray(`  [${r.regions.map((x) => x.id).join(", ")}]`) : ""),
        r.engines.join(" · "),
      ])
    )
  );
  console.log(
    "\n" +
      ui.color.gray(
        "  Model ids are NOT shipped — they rot within a quarter. `orc extra ping <profile>`\n" +
          "  reads them from the provider and caches them on the profile.\n" +
          "  `orc extra providers --json` carries the base URLs, the auth variable and the terms link."
      )
  );
  if (cat._stale)
    console.log(
      "\n  " +
        ui.mark.warn(
          `this catalog is ${cat._age_days === null ? "undated" : cat._age_days + " days old"} (> ${EXTRA_CATALOG_STALE_DAYS}) — ` +
            "a base URL may have moved. Check the provider's own docs before you trust a failure."
        )
    );
  console.log("");
}


// ═══════════════════════════════════════════════════════════════════════════
// W0 — `orc extra tools`: THE INSTALL GATE (v0.51.0)
//
// Two of this catalog's providers are LOCAL TOOLS, and a local tool can simply
// not be there. Today that surfaces as an `extra-engine-unavailable` doctor
// finding — a report AFTER the fact, when the user has already added a profile
// that cannot work. This is the refusal BEFORE it, and the read the panel makes
// before it offers anything else.
//
// Every field is computed FRESH on every read and NOTHING is stored. There is
// deliberately no "installing" state: the user may close the terminal window,
// and a stored flag would be a lie from that moment on (the computeWikiFreshness
// rule, applied to a binary).
//
// exit 0 when at least one tool is `ready`, 1 otherwise — the same exit-code-as-
// data convention as `pattern status` and `diy status`.
// ═══════════════════════════════════════════════════════════════════════════

// The closed set, and it is the CLI's answer rather than the panel's. Each one
// has exactly ONE next action, which is what lets a renderer switch on it and
// derive nothing.
const EXTRA_TOOL_STATES = ["absent", "outdated", "unauthenticated", "ready"];

// A FREE tool probe is local and answers in milliseconds, so it is bounded
// tightly: a hung `models` call must never hold a panel read open.
const EXTRA_TOOL_TIMEOUT_MS = 15000;
// THE PAID RUNG IS A DIFFERENT ANIMAL and must not inherit that bound. A local
// agentic tool loads its own system prompt and tool schemas, then does a real
// model round trip — the first live probe written against a real tool was killed
// at 15s MID-ANSWER and reported as a flag problem, which is the exact
// mis-blame this release exists to end. Measured: ~2.4s on a fast model, well
// past 15s on a slow one.
const EXTRA_LIVE_TIMEOUT_MS = 180000;

const stripAnsi = (s) => String(s || "").replace(/\x1b\[[0-9;?]*[ -\/]*[@-~]/g, "");

// LENIENT ON PURPOSE (R8): version output differs per tool and per install
// method — an npm shim, a native binary and a winget package all print it
// differently. The first `N.N.N` wins; unparseable is `null`, which reads as
// "the version is unknown" and never as "too old".
function parseVersion(text) {
  const m = /(\d+)\.(\d+)\.(\d+)/.exec(stripAnsi(text));
  return m ? m[0] : null;
}
function cmpVersion(a, b) {
  const pa = String(a).split(".").map(Number);
  const pb = String(b).split(".").map(Number);
  for (let i = 0; i < 3; i++) {
    const x = pa[i] || 0;
    const y = pb[i] || 0;
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

// Run a local tool's own free command. Returns the SAME shape whatever happens,
// because "it exited 1" and "it was not there" are different answers a caller
// has to be able to tell apart.
function runToolCmd(binPath, argv, env, timeoutMs) {
  try {
    const r = spawnCmdSafe(binPath, argv, {
      encoding: "utf8",
      timeout: timeoutMs || EXTRA_TOOL_TIMEOUT_MS,
      windowsHide: true,
      maxBuffer: 8 * 1024 * 1024,
      env: Object.assign({}, process.env, env || {}),
    });
    return {
      ran: true,
      code: r.status === null ? null : r.status,
      stdout: stripAnsi(r.stdout || ""),
      stderr: stripAnsi(r.stderr || ""),
      timed_out: !!((r.error && r.error.code === "ETIMEDOUT") || r.signal === "SIGTERM" || r.signal === "SIGKILL"),
    };
  } catch (e) {
    return { ran: false, code: null, stdout: "", stderr: String((e && e.message) || e), timed_out: false };
  }
}

// The install block, filtered to THIS platform by the CLI so no renderer ever
// picks a command. An empty `cmds` after filtering is an honest answer: no
// shipped package manager covers this platform, and the docs link is the route.
function extraInstallView(row) {
  const inst = row.install || {};
  const cmds = (inst.cmds || []).filter((c) => (c.platforms || []).includes(process.platform));
  return {
    docs_url: inst.docs_url || row.docs_url || null,
    bin_name: inst.bin_name || row.cli_bin || null,
    platform: process.platform,
    cmds: cmds.map((c) => ({ manager: c.manager, platforms: c.platforms || [], cmd: c.cmd })),
    // Every command the catalog knows, so a machine whose platform matches none
    // of them can still be told what exists elsewhere.
    all_cmds: (inst.cmds || []).map((c) => ({ manager: c.manager, platforms: c.platforms || [], cmd: c.cmd })),
  };
}

// One tool row, computed. The order of the checks IS the state ladder: absent
// beats outdated beats unauthenticated beats ready, because each one makes the
// next unanswerable.
function extraToolRow(row, ledger) {
  const bin = row.cli_bin;
  const inst = extraInstallView(row);
  // v0.52.0 — WHETHER A CONNECTION TO THIS TOOL EXISTS IS A FACT ABOUT THE
  // LEDGER, and it is joined HERE. The panel used to render an unconditional
  // Connect button on every `ready` card, because it never consulted
  // `list.profiles` — so a tool you had already connected, tested and routed
  // work to still offered to connect it. The panel may not do this join itself:
  // a second idea of "connected" is exactly the drift this panel exists to
  // prevent.
  const mine = ((ledger && ledger.profiles) || []).filter((x) => x.provider === row.id);
  const out = {
    provider: row.id,
    label: row.label,
    bin,
    connected_profiles: mine.map((x) => ({
      name: x.name,
      verified_at: x.verified_at || null,
      credential_source: (x.credential && x.credential.source) || null,
    })),
    connected: mine.length > 0,
    // "Has ever answered" — the same evidence the setup gate reads. A profile
    // that was configured and never tested is CONNECTED and NOT VERIFIED, and
    // those are two different cards.
    verified: mine.some((x) => !!x.verified_at),
    state: "absent",
    installed: false,
    bin_path: null,
    version: null,
    version_raw: null,
    min_version: row.min_version || null,
    outdated: false,
    authed: null,
    auth_detail: null,
    models_count: null,
    models: [],
    probe_error: null,
    no_install_alternative: row.no_install_alternative === undefined ? null : row.no_install_alternative,
    docs_url: row.docs_url || null,
    install: inst,
  };
  const found = whichBin(bin);
  if (!found) return out;
  out.installed = true;
  out.bin_path = found;

  if (row.version_cmd) {
    const v = runToolCmd(found, row.version_cmd);
    out.version_raw = (v.stdout.trim() || v.stderr.trim() || "").split(/\r?\n/)[0] || null;
    out.version = parseVersion(v.stdout + "\n" + v.stderr);
  }
  // A version we could not parse is NOT a version below the floor. Blocking on
  // a guess would make an unusual install method look like a broken one.
  if (out.version && row.min_version && cmpVersion(out.version, row.min_version) < 0) {
    out.state = "outdated";
    out.outdated = true;
    return out;
  }

  if (row.auth_cmd) {
    const a = runToolCmd(found, row.auth_cmd);
    const text = (a.stdout + "\n" + a.stderr).trim();
    out.authed = a.code === 0 && !/not logged in|no credentials|logged out|not authenticated/i.test(text);
    out.auth_detail = text.split(/\r?\n/).filter(Boolean).slice(0, 4).join(" · ") || null;
  }
  if (row.models_cmd) {
    const m = runToolCmd(found, row.models_cmd);
    if (m.code === 0) {
      const list = extraParseModelList(m.stdout);
      out.models = list;
      out.models_count = list.length;
    } else if (m.timed_out) {
      out.probe_error = "the model list did not answer in time";
    }
  }
  // `authed` is only decidable where the tool has a command for it. A non-empty
  // model list is the second piece of evidence there is a credential at all —
  // and where there is neither, `authed` stays null and the state is `ready`
  // rather than a verdict this read cannot support.
  if (out.authed === false && !out.models_count) {
    out.state = "unauthenticated";
    return out;
  }
  out.state = "ready";
  return out;
}

// The model list a local tool prints. One `provider/model` per line is the shape
// on one of them; JSON is the shape on the other. Both are read defensively, and
// a shape this does not recognise returns an EMPTY list rather than an invented
// one — one of the two is documented, not verified (R1), so it must tolerate a
// shape it has never seen.
function extraParseModelList(text) {
  const t = String(text || "").trim();
  if (!t) return [];
  if (t[0] === "{" || t[0] === "[") {
    try {
      const v = JSON.parse(t);
      const arr = Array.isArray(v) ? v : Array.isArray(v.data) ? v.data : Array.isArray(v.models) ? v.models : [];
      // `slug` is in this list because one shipped tool uses it and neither
      // `id` nor `name` — verified against its real output, not assumed.
      return arr.map((m) => (typeof m === "string" ? m : m && (m.id || m.slug || m.name))).filter(Boolean);
    } catch (_) {
      return [];
    }
  }
  return t
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter((l) => l && !/\s/.test(l) && !/^[-=*#]/.test(l));
}

function extraTools(claudeDir) {
  const asJson = wantsJson();
  const cat = readCatalog();
  if (!cat) {
    const hint = `provider catalog missing or unreadable at ${EXTRA_CATALOG} — this is a packaging bug; reinstall orc.`;
    if (asJson) emitJson({ ok: false, reason: "no-catalog", path: EXTRA_CATALOG, hint }, 1);
    console.error("❌ " + hint);
    process.exit(1);
  }
  const only = typeof flag("--provider") === "string" ? flag("--provider") : null;
  const toolLedger = readExtra(claudeDir);
  const rows = cat.providers.filter((p) => p.cli_bin && (!only || p.id === only)).map((p) => extraToolRow(p, toolLedger));
  const anyReady = rows.some((r) => r.state === "ready");
  const code = anyReady ? 0 : 1;
  if (asJson)
    emitJson(
      {
        ok: true,
        as_of: cat.as_of,
        age_days: cat._age_days,
        stale: cat._stale,
        platform: process.platform,
        states: EXTRA_TOOL_STATES,
        ready: anyReady,
        tools: rows,
      },
      code
    );

  console.log(ui.header(`ORC · extra — local tools (catalog dated ${cat.as_of})`));
  console.log("");
  for (const r of rows) {
    const badge =
      r.state === "ready" ? ui.mark.ok(r.state) : r.state === "absent" ? ui.mark.bad(r.state) : ui.mark.warn(r.state);
    console.log(`  ${ui.color.cyan(r.provider)}  ${badge}`);
    if (r.installed)
      console.log(
        ui.kv([
          ["binary", r.bin_path],
          ["version", r.version || ui.color.gray("unknown — the output did not parse; not treated as too old")],
          ["floor", r.min_version || "—"],
          ["signed in", r.authed === null ? "—" : r.authed ? "yes" : "no"],
          ["models", r.models_count === null ? "—" : String(r.models_count)],
          [
            "connected",
            !r.connected
              ? ui.color.gray("no connection uses this tool yet")
              : r.connected_profiles.map((x) => x.name + (x.verified_at ? "" : " (never tested)")).join(", "),
          ],
        ])
      );
    else {
      const cmds = r.install.cmds.length ? r.install.cmds : r.install.all_cmds;
      console.log("    " + ui.color.gray(`\`${r.bin}\` is not on PATH. Install it with:`));
      for (const c of cmds) console.log("      " + ui.color.bold(c.cmd) + ui.color.gray(`   (${c.manager})`));
      console.log("    " + ui.color.gray(`or run: orc extra install ${r.provider}   — opens a terminal and runs it there`));
      if (r.no_install_alternative)
        console.log(
          "    " +
            ui.color.gray(
              `no install needed if you use \`${r.no_install_alternative}\` instead — same models, an ordinary endpoint and a key.`
            )
        );
      else
        console.log(
          "    " + ui.color.gray("there is no install-free alternative for this one — the install is the only route.")
        );
    }
    if (r.probe_error) console.log("    " + ui.mark.warn(r.probe_error));
    console.log("");
  }
  if (!rows.length) console.log(ui.color.gray("  no provider in the catalog is a local tool.\n"));
  process.exit(code);
}

// ═══════════════════════════════════════════════════════════════════════════
// W0.5 — `orc extra install <provider>`: THE TERMINAL LAUNCHER
//
// A global install can ask for elevation, hit an npm EACCES, pull 80 MB or take
// forty seconds, and inside a hidden subprocess all four look identical:
// NOTHING HAPPENED. So this is neither a silent background job nor a string to
// copy — it is a REAL TERMINAL WINDOW, in the foreground, with the command on
// screen before it runs, which the user can read, scroll and Ctrl-C.
//
// Three properties, all three load-bearing: it is VISIBLE (the failures are the
// user's to see), it is THEIRS (their shell, their profile, their privileges —
// ORC NEVER ELEVATES: no sudo, no runas), and it is FALLBACK-FIRST (the command
// renders whether or not the launch worked, the `openBrowser` rule).
//
// The SCRIPT FILE is the design. ORC does not try to thread a command string
// through a terminal host into a shell into a package manager; that nesting is
// where cross-platform launchers break and the quoting is unreadable. It writes
// a small script and opens a terminal ON THE FILE.
// ═══════════════════════════════════════════════════════════════════════════

const EXTRA_TMP_DIR = "tmp";

function extraInstallScript(dir, provider, cmd, verifyCmd) {
  fs.mkdirSync(dir, { recursive: true });
  // Sweep scripts older than a week. Not on a shorter window and never on the
  // one just written: the user may still have that terminal open, and deleting
  // a script out from under a running install would be the one failure this
  // whole command exists to make visible.
  try {
    for (const f of fs.readdirSync(dir)) {
      const full = path.join(dir, f);
      if (!/^install-.*.(ps1|sh)$/.test(f)) continue;
      if (Date.now() - fs.statSync(full).mtimeMs > 7 * 86400000) fs.rmSync(full, { force: true });
    }
  } catch (_) {}
  const ts = new Date().toISOString().replace(/[-:T]/g, "").slice(0, 14);
  const win = process.platform === "win32";
  const file = path.join(dir, `install-${provider}-${ts}.${win ? "ps1" : "sh"}`);
  // Four things and nothing else: echo the command, run it, verify, STAY OPEN.
  // A window that vanishes on failure is worse than no window. It carries NO
  // CREDENTIAL, ever — this is an install, and ORC never writes another tool's
  // credential store anyway.
  const body = win
    ? [
        "$ErrorActionPreference = 'Continue'",
        "Write-Host ''",
        "Write-Host 'ORC is about to run this command. It is yours to read, scroll and Ctrl-C.'",
        "Write-Host ''",
        `Write-Host '  ${cmd.replace(/'/g, "''")}'`,
        "Write-Host ''",
        cmd,
        "Write-Host ''",
        "Write-Host 'Checking it landed:'",
        verifyCmd,
        "Write-Host ''",
        "Write-Host 'Done. Go back to ORC and press Re-check.'",
        "Write-Host ''",
      ].join("\r\n") + "\r\n"
    : [
        "#!/bin/sh",
        "echo",
        "echo 'ORC is about to run this command. It is yours to read, scroll and Ctrl-C.'",
        "echo",
        `echo '  ${cmd.replace(/'/g, "'\\''")}'`,
        "echo",
        cmd,
        "echo",
        "echo 'Checking it landed:'",
        verifyCmd,
        "echo",
        "echo 'Done. Go back to ORC and press Re-check.'",
        // STAY OPEN. A terminal profile that closes the window on exit would
        // have taught the user nothing about a failure.
        "printf 'Press Enter to close this window. '",
        "read _dummy",
        "",
      ].join("\n");
  fs.writeFileSync(file, body, { mode: win ? 0o600 : 0o700 });
  try {
    fs.chmodSync(file, win ? 0o600 : 0o700);
  } catch (_) {}
  return file;
}

// Each rung is BEST EFFORT and falls through on a throw or a failed spawn.
// A machine with no terminal to open — SSH, a locked-down policy, a headless
// session — degrades to the copy-able command, never to a dead button.
function extraLaunchTerminal(script) {
  const attempts = [];
  const { spawn } = require("child_process");
  const tryOne = (name, cmd, argv) => {
    try {
      const child = spawn(cmd, argv, { detached: true, stdio: "ignore", windowsHide: false });
      let failed = false;
      child.on("error", () => {
        failed = true;
      });
      child.unref();
      attempts.push({ launcher: name, ok: !failed });
      return !failed;
    } catch (e) {
      attempts.push({ launcher: name, ok: false, error: String((e && e.message) || e) });
      return false;
    }
  };
  const ladder =
    process.platform === "win32"
      ? [
          ["wt", "wt.exe", ["-w", "0", "nt", "powershell", "-NoExit", "-File", script]],
          ["powershell", "cmd.exe", ["/c", "start", "", "powershell", "-NoExit", "-File", script]],
        ]
      : process.platform === "darwin"
        ? [
            ["Terminal", "open", ["-a", "Terminal", script]],
            ["osascript", "osascript", ["-e", `tell application "Terminal" to do script ${JSON.stringify(script)}`]],
          ]
        : [
            ["x-terminal-emulator", "x-terminal-emulator", ["-e", "sh", script]],
            ["gnome-terminal", "gnome-terminal", ["--", "sh", script]],
            ["konsole", "konsole", ["-e", "sh", script]],
            ["xterm", "xterm", ["-e", "sh", script]],
          ];
  for (const [name, cmd, argv] of ladder) {
    // On win32 the two hosts are looked up by the shell, not by PATH walking.
    if (process.platform !== "win32" && !whichBin(cmd)) {
      attempts.push({ launcher: name, ok: false, error: "not on PATH" });
      continue;
    }
    if (tryOne(name, cmd, argv)) return { launched: true, launcher: name, attempts };
  }
  return { launched: false, launcher: null, attempts };
}

function extraInstallCmd(claudeDir, providerId) {
  const asJson = wantsJson();
  const cat = readCatalog();
  const row = catalogRow(cat, providerId);
  const fail = (reason, msg, extra) => {
    if (asJson) emitJson(Object.assign({ ok: false, reason, error: msg }, extra || {}), 1);
    console.error("❌ " + msg);
    process.exit(1);
  };
  if (!row || !row.cli_bin)
    fail(
      "not-a-tool",
      `"${providerId || ""}" is not a local tool in the catalog. \`orc extra tools\` lists the ones that are.`,
      { provider: providerId || null }
    );
  const view = extraInstallView(row);
  const chosen =
    (typeof flag("--manager") === "string" && view.cmds.find((c) => c.manager === flag("--manager"))) || view.cmds[0];
  if (!chosen)
    fail(
      "no-command",
      `the catalog has no install command for ${row.id} on ${process.platform}. Its documentation is at ${view.docs_url || "(none listed)"}.`,
      { provider: row.id, install: view }
    );
  const verifyCmd = `${row.cli_bin} --version`;
  const dir = path.join(claudeDir, "orc", EXTRA_TMP_DIR);
  let script = null;
  try {
    script = extraInstallScript(dir, row.id, chosen.cmd, verifyCmd);
  } catch (e) {
    fail("script-failed", `could not write the install script under ${dir}: ${(e && e.message) || e}`, {
      provider: row.id,
      cmd: chosen.cmd,
    });
  }
  const dry = flag("--dry-run") === true;
  const launch = dry ? { launched: false, launcher: null, attempts: [] } : extraLaunchTerminal(script);
  // A FAILED LAUNCH IS EXIT 0. It is an answer, not an error: the same object
  // comes back carrying the command to paste.
  const payload = {
    ok: true,
    provider: row.id,
    launched: launch.launched,
    launcher: launch.launcher,
    attempts: launch.attempts,
    dry_run: dry,
    script,
    cmd: chosen.cmd,
    manager: chosen.manager,
    verify_cmd: verifyCmd,
    fallback_cmd: chosen.cmd,
    docs_url: view.docs_url,
    elevation: "never — ORC does not elevate. A package-manager permission problem is yours to see and fix.",
    note: launch.launched
      ? "a terminal window opened — come back and press Re-check when it finishes"
      : "no terminal could be opened here. Run the command yourself; nothing about this is different if you do.",
  };
  if (asJson) emitJson(payload, 0);
  console.log("");
  console.log(
    ui.box(["ORC will run this in YOUR terminal:", "", "  " + chosen.cmd, "", `then check it with: ${verifyCmd}`])
  );
  console.log("");
  if (dry) console.log("  " + ui.color.gray(`--dry-run: the script was written to ${script} and nothing was opened.`));
  else if (launch.launched) console.log("  " + ui.mark.ok(payload.note) + ui.color.gray(`  (${launch.launcher})`));
  else console.log("  " + ui.mark.warn(payload.note));
  console.log("");
  process.exit(0);
}

// ═══════════════════════════════════════════════════════════════════════════
// W0.6 — `orc extra keyhelp <profile>`: WHICH OF THREE ROUTES APPLIES
//
// The two shipped tools are OPPOSITES about credentials, so this command's whole
// job is to say which route this profile is on and to make that one route one
// click:
//
//   env                 the tool reads a per-provider variable → NOTHING to set
//                       up. ORC injects the key at rungs 2-4 and at dispatch.
//   stdin-login         the tool accepts a key on STDIN → the command is printed
//                       and can be opened in a terminal. ORC NEVER PIPES THE KEY
//                       ITSELF.
//   interactive-login   the tool always prompts → open a terminal on its own
//                       command and say plainly that it cannot be automated.
//
// ORC NEVER WRITES ANOTHER TOOL'S CREDENTIAL STORE. The key lives in ORC's vault
// or in the user's own environment variable and is injected into the child
// process — so nothing global is mutated, revoking in ORC actually revokes, and
// a user who already ran the tool's own login is untouched.
// ═══════════════════════════════════════════════════════════════════════════

const EXTRA_KEY_ROUTES = ["env", "stdin-login", "interactive-login", "none"];

// v0.52.0 (D3 Part 2) — HOW TO SET IT, per OS, computed HERE.
//
// `orc extra list` printed `no key (env DEEPSEEK_API_KEY)` and nothing anywhere
// said how to set that variable on Windows or on macOS. The instruction is the
// CLI's to compose, because the panel must name no command of its own.
//
// PLACEHOLDERS ONLY. The CLI never renders a real key into an instruction
// string, so nothing here can leak into a screenshot, a copy button, a shell
// history or argv. And ORC still does NOT run `setx` or append to `~/.zshrc`
// itself: `setx NAME <value>` puts the key IN ARGV, which this subsystem
// refuses by name, and appending an `export` line writes the key in plaintext to
// a file the vault exists to avoid.
function extraEnvSetHelp(varName, opts) {
  const o = opts || {};
  const name = varName || "<VARIABLE>";
  const value = o.value || "<your key>";
  if (process.platform === "win32")
    return {
      platform: "win32",
      session: `$env:${name} = "${value}"`,
      persist: `[Environment]::SetEnvironmentVariable('${name}', '${value}', 'User')`,
      persist_note: "a new terminal picks it up; the one you are in does not.",
      shell_file: null,
      // Said out loud wherever the persistent form appears.
      warning: o.warning || null,
    };
  const shell = String(process.env.SHELL || "");
  const file = /zsh/.test(shell) ? "~/.zshrc" : /bash/.test(shell) ? "~/.bashrc" : "~/.profile";
  return {
    platform: process.platform,
    session: `export ${name}="${value}"`,
    persist: `echo 'export ${name}="${value}"' >> ${file}`,
    persist_note: `a new shell picks it up; the one you are in does not. This writes the value in PLAINTEXT to ${file}.`,
    shell_file: file,
    warning: o.warning || null,
  };
}

function extraKeyhelp(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  if (!prof) {
    const known = ledger ? ledger.profiles.map((x) => x.name) : [];
    if (asJson) emitJson({ ok: false, reason: "unknown-profile", profile: name || null, known }, 2);
    console.error(`❌ unknown profile "${name || ""}".`);
    process.exit(2);
  }
  const cat = readCatalog();
  const row = catalogRow(cat, prof.provider);
  const credRow = (row && row.credential) || null;
  const src = (prof.credential || {}).source || "env";
  const keyName = (prof.credential || {}).key_name || null;

  let route, envVar, cmd, why;
  if (credRow && credRow.env_route && (src === "env" || src === "vault")) {
    route = "env";
    envVar = credRow.env_var || keyName || null;
    cmd = null;
    why =
      "nothing to set up. ORC puts the key in this tool's environment for every probe and every dispatch, so the tool's own credential store is never touched and revoking it in ORC actually revokes it.";
  } else if (credRow && credRow.stdin_login) {
    route = "stdin-login";
    envVar = null;
    cmd = credRow.stdin_login;
    why =
      "this tool can take a key on stdin. ORC prints the command and can open a terminal on it — it never pipes your key itself, because a key ORC pipes is a key ORC has to hold.";
  } else if (credRow && credRow.interactive_login) {
    route = "interactive-login";
    envVar = null;
    cmd = credRow.interactive_login;
    why =
      "this tool's login always prompts and cannot be driven non-interactively. ORC opens a terminal on its own command and says so, rather than pretending to automate it.";
  } else {
    route = "none";
    envVar = null;
    cmd = null;
    why = "this provider is not a local tool — its credential is the key on the profile and nothing else is needed.";
  }
  const payload = {
    ok: true,
    profile: prof.name,
    provider: prof.provider,
    engine: prof.engine,
    routes: EXTRA_KEY_ROUTES,
    route,
    env_var: route === "env" ? envVar : null,
    needs_terminal: route === "stdin-login" || route === "interactive-login",
    cmd,
    why,
    note: (credRow && credRow.note) || null,
    never: "ORC never writes another tool's credential store, and never puts a key in argv.",
    // The instruction, per OS. `env_set` is present exactly where there is a
    // VARIABLE to set.
    env_set: route === "env" && src === "env" ? extraEnvSetHelp(envVar) : null,
    // v0.53.3 — THIS BLOCK USED TO NAME `ORC_EXTRA_KEY` AS THE PASSPHRASE, and
    // `extraCredentialValue` reads that variable as THE KEY. One variable, two
    // meanings, and the instruction was the wrong one: a user who followed it
    // exported their vault passphrase into the variable dispatch sends in an
    // Authorization header — i.e. handed the secret that opens the vault to a
    // third-party provider. Nothing reads a passphrase from the environment, so
    // there is no env route for one and this field is now always null.
    passphrase_env: null,
    // The KEY variable, described as the key. It is the unattended-wave escape
    // hatch and it now LOSES to a vault that can be opened, so it is offered
    // second, after the route that has a deadline on it.
    key_env:
      src === "vault"
        ? extraEnvSetHelp("ORC_EXTRA_KEY", {
            value: "<your key>",
            warning:
              "This is the KEY, not the passphrase — never put a passphrase here: dispatch sends this variable's value to the provider in an Authorization header. It applies only when the vault cannot be opened (an unattended wave with nothing cached); a vault ORC can open always wins.",
          })
        : null,
    // The route WITH A DEADLINE ON IT, which is the one to reach for first.
    vault_unlock:
      src === "vault"
        ? {
            cmd: `orc extra session ${prof.name} --save --ttl 30`,
            why:
              "the passphrase is a DEADLINE, not a second factor. Saving it with a TTL is what lets an unattended wave open the vault without a key sitting in your environment forever.",
          }
        : null,
  };
  if (asJson) emitJson(payload, 0);
  console.log("\n" + ui.header(`ORC · extra — ${prof.name} · credential route`));
  console.log(
    ui.kv([
      ["route", route],
      ["variable", payload.env_var || "—"],
      ["command", cmd || "—"],
    ])
  );
  console.log("\n  " + why);
  if (payload.note) console.log("  " + ui.color.gray(payload.note));
  if (payload.vault_unlock) {
    console.log("\n  " + ui.color.bold("unlock:  ") + payload.vault_unlock.cmd);
    console.log("  " + ui.color.gray(payload.vault_unlock.why));
  }
  for (const block of [payload.env_set, payload.key_env]) {
    if (!block) continue;
    console.log("");
    console.log("  " + ui.color.bold("this session:  ") + block.session);
    console.log("  " + ui.color.bold("to persist:    ") + block.persist);
    console.log("  " + ui.color.gray("  " + block.persist_note));
    if (block.warning) console.log("  " + ui.color.yellow("  " + block.warning));
  }
  console.log("");
}

// ── orc extra add ──────────────────────────────────────────────────────────
function extraAdd(claudeDir, name) {
  const cat = readCatalog();
  const asJson = wantsJson();
  const fail = (reason, msg, extra) => {
    if (asJson) emitJson(Object.assign({ ok: false, reason, error: msg }, extra || {}), 1);
    console.error("❌ " + msg);
    process.exit(1);
  };
  if (!name || !/^[a-z0-9][a-z0-9_-]*$/i.test(name))
    fail(
      "bad-name",
      "usage: orc extra add <profile> --provider <id> --engine <api|claude-shim|cli>\n" +
        "   <profile> is your own slug — letters, digits, - and _ — and it is what a route row names."
    );
  const providerId = flag("--provider");
  if (typeof providerId !== "string")
    fail("no-provider", "--provider <id> is required. `orc extra providers` lists them (use `custom` for anything else).");
  const row = catalogRow(cat, providerId);
  if (!row)
    fail(
      "unknown-provider",
      `unknown provider "${providerId}". Known: ${(cat ? cat.providers.map((p) => p.id) : []).join(", ")}`
    );
  const engine = flag("--engine");
  if (typeof engine !== "string" || !EXTRA_ENGINES.includes(engine))
    fail("bad-engine", `--engine must be one of: ${EXTRA_ENGINES.join(" | ")}`);
  if (!(row.engines || []).includes(engine))
    fail(
      "engine-unsupported",
      `provider "${providerId}" does not ship a ${engine} surface (it has: ${(row.engines || []).join(", ")}).`
    );

  const region = typeof flag("--region") === "string" ? flag("--region") : "default";
  if (region !== "default" && !(row.regions || []).some((r) => r.id === region))
    fail(
      "unknown-region",
      `unknown region "${region}" for ${providerId} (has: default${(row.regions || []).map((r) => ", " + r.id).join("")}).`
    );

  const bases = providerBases(row, region);
  const baseUrl = typeof flag("--base-url") === "string" ? flag("--base-url") : null;
  const anthropicBase =
    typeof flag("--anthropic-base-url") === "string" ? flag("--anthropic-base-url") : null;
  if (engine === "api" && !baseUrl && !bases.api_base)
    fail("no-base-url", `provider "${providerId}" has no OpenAI-compatible base URL in the catalog — pass --base-url.`);
  if (engine === "claude-shim" && !anthropicBase && !bases.anthropic_base)
    fail("no-base-url", `provider "${providerId}" has no /anthropic base URL in the catalog — pass --anthropic-base-url.`);

  // v0.51.0 — A PROVIDER WHOSE ONLY SURFACE IS A LOCAL TOOL CANNOT BE ADDED
  // WHILE THAT TOOL IS ABSENT. Today's `extra-engine-unavailable` doctor finding
  // is a report AFTER the fact, when the user already has a profile that cannot
  // work; this is the refusal before it, and it NAMES the install command rather
  // than only saying no.
  if (row.cli_bin && !whichBin(row.cli_bin)) {
    const inst = extraInstallView(row);
    const cmds = inst.cmds.length ? inst.cmds : inst.all_cmds;
    fail(
      "not-installed",
      `"${providerId}" is a program that runs on this machine, and \`${row.cli_bin}\` is not on PATH.\n` +
        (cmds.length ? `   Install it:  ${cmds[0].cmd}\n   or run:      orc extra install ${providerId}   (opens a terminal and runs it there)\n` : "") +
        (row.no_install_alternative
          ? `   Or use \`${row.no_install_alternative}\` instead — same models, an ordinary endpoint and a key, nothing to install.`
          : "   There is no install-free alternative for this one; the install is the only route."),
      { provider: providerId, bin: row.cli_bin, install: inst, no_install_alternative: row.no_install_alternative || null }
    );
  }

  let cli = null;
  if (engine === "cli") {
    // The catalog's own binary is the default, so a native row needs no --cli.
    const bin = typeof flag("--cli") === "string" ? flag("--cli") : row.cli_bin;
    if (typeof bin !== "string")
      fail("no-cli", "--cli <bin> is required for --engine cli on a provider that does not name one (`orc extra tools` lists the ones that do).");
    if (!EXTRA_CLI_ADAPTERS[bin])
      fail(
        "no-adapter",
        `no adapter for "${bin}". This release ships: ${Object.keys(EXTRA_CLI_ADAPTERS).join(", ")}.\n` +
          "   An adapter is a table row — argv, env, output parser, what the tool documents about its exit codes — so adding one is small, but ORC will not pretend to drive a tool it has never been told how to call."
      );
    const attach = flag("--cli-attach");
    if (attach !== undefined && !EXTRA_CLI_ADAPTERS[bin].supports.attach)
      fail("no-attach", `--cli-attach is an \`${bin}\` feature it does not have. Only ${Object.keys(EXTRA_CLI_ADAPTERS).filter((k) => EXTRA_CLI_ADAPTERS[k].supports.attach).join(", ")} joins a running server.`);
    if (typeof attach === "string" && !/^https?:\/\//.test(attach))
      fail("bad-attach", `--cli-attach takes the URL of a running server (got "${attach}").`);
    // extra_args are the USER's own words on a profile they authored, appended
    // verbatim. That is why they are allowed at all: a task SLICE is not
    // ORC's text and never reaches argv, but a profile is configuration.
    const cliArgs = typeof flag("--cli-args") === "string" ? flag("--cli-args").split(/\s+/).filter(Boolean) : [];
    cli = {
      bin,
      agent: typeof flag("--cli-agent") === "string" ? flag("--cli-agent") : null,
      attach: typeof attach === "string" ? attach : null,
      extra_args: cliArgs,
    };
  }

  // P2 / D3 — the credential. An env-var NAME is the default and the
  // recommended source: an environment variable your OS already protects beats
  // a passphrase you will forget. `--key-stdin` is the second option and is
  // the encrypted vault; there is deliberately no `--key <value>`, which would
  // land the secret in shell history and in a world-readable process list.
  if (args.includes("--key"))
    fail(
      "key-in-argv",
      "`--key <value>` does not exist on purpose: argv is world-readable in a process list and lands in shell history.\n" +
        "   Use --env-key <NAME> (recommended) or --key-stdin."
    );
  const envKey = flag("--env-key");
  const keyStdin = args.includes("--key-stdin");
  // v0.51.0 — the THIRD source, and it exists because ORC never writes another
  // tool's credential store (nothing global is mutated, revoking in ORC actually
  // revokes, and a user who already ran the tool's own login is untouched). A
  // local tool that holds its own credential needs no key from ORC at all, and
  // `--tool-auth` is how that is said out loud instead of being faked with an
  // environment variable nobody set.
  const toolAuth = args.includes("--tool-auth");
  let credential;
  if (toolAuth) {
    if (engine !== "cli")
      fail("tool-auth-not-cli", "--tool-auth means \"the tool signs itself in\", which only exists for --engine cli.");
    credential = { source: "tool", key_name: null };
  } else if (keyStdin) {
    credential = { source: "vault", key_name: name };
  } else {
    const kn = typeof envKey === "string" ? envKey : row.env_key_default;
    if (!kn)
      fail(
        "no-credential",
        "no credential source. Pass --env-key <NAME> (recommended), --key-stdin (stored in the encrypted vault), or --tool-auth if this tool is already signed in and holds its own."
      );
    credential = { source: "env", key_name: kn };
  }

  const authEnv = typeof flag("--auth-env") === "string" ? flag("--auth-env") : row.auth_env;
  if (!EXTRA_AUTH_ENVS.includes(authEnv))
    fail(
      "bad-auth-env",
      `--auth-env must be one of: ${EXTRA_AUTH_ENVS.join(" | ")}\n` +
        "   The variable NAME decides the header: ANTHROPIC_AUTH_TOKEN → Authorization: Bearer, ANTHROPIC_API_KEY → x-api-key."
    );

  const ledger = readExtra(claudeDir) || emptyExtra();
  if (extraProfile(ledger, name))
    fail("exists", `profile "${name}" already exists. Remove it first: orc extra remove ${name} --reason "<why>"`);

  const prof = {
    name,
    provider: providerId,
    engine,
    region: bases.region,
    cli,
    base_url: baseUrl || bases.api_base || null,
    anthropic_base_url: anthropicBase || bases.anthropic_base || null,
    // Engine `api` derives `/v1/chat/completions` vs `/chat/completions` from
    // whether the base already carries a version segment. This is the override
    // for a gateway that does neither, and it is null in every normal case.
    completions_path: typeof flag("--completions-path") === "string" ? flag("--completions-path") : null,
    auth_env: authEnv,
    credential,
    // Everything below is written by `orc extra ping` and by dispatch. Never
    // guessed here — an unverified profile must read unverified.
    verified_at: null,
    verify_method: null,
    verify_base_url: null,
    latency_ms: null,
    models_seen: [],
    // Engine A resolves FOUR model ids, not one — Claude Code makes background
    // calls on the `haiku` alias, so a single ANTHROPIC_MODEL 404s mid-wave.
    // Filled at route time from models_seen; null until then.
    model_map: { opus: null, sonnet: null, haiku: null, subagent: null },
    // A record, never a boolean. "DeepSeek works" and "DeepSeek works if you
    // set two env vars, and here they are" are different facts.
    tool_fidelity: null,
    privacy: null,
    notes: null,
  };

  ledger.profiles.push(prof);
  extraHistory(ledger, "add", { profile: name, provider: providerId, engine });
  const file = writeExtra(claudeDir, ledger);
  const ignored = ensureExtraGitignore(extraPaths(claudeDir).root);

  if (asJson)
    emitJson(
      {
        ok: true,
        profile: redactProfile(prof, claudeDir),
        ledger: file,
        gitignore_added: ignored,
        next: keyStdin
          ? `orc extra ping ${name} --key-stdin`
          : `orc extra ping ${name}`,
      },
      0
    );

  console.log(`\nAdded profile ${ui.color.cyan(name)}  →  ${file}`);
  console.log(
    ui.kv([
      ["provider", providerId + (prof.region !== "default" ? `  (${prof.region})` : "")],
      ["engine", engine],
      ["base url", engine === "claude-shim" ? prof.anthropic_base_url || "—" : prof.base_url || "—"],
      ["credential", credential.source === "env" ? `env ${credential.key_name}` : "vault (not stored yet)"],
      ["verified", ui.color.yellow("no — nothing routes to an unverified profile")],
    ])
  );
  if (ignored) console.log(ui.color.gray(`\n  .gitignore  + ${ignored.join(", ")}`));
  if (credential.source === "env" && !process.env[credential.key_name])
    console.log("\n  " + ui.mark.warn(`${credential.key_name} is not set in this shell — the ping will fail until it is.`));
  console.log(
    "\n" +
      ui.box([
        "Next:  " + (keyStdin ? `orc extra ping ${name} --key-stdin` : `orc extra ping ${name}`),
        "",
        "A profile does nothing until a route points at it. Nothing has changed",
        "about how this repo builds yet.",
      ]) +
      "\n"
  );
}

// ── orc extra list / show ──────────────────────────────────────────────────
function extraList(claudeDir) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const cat = readCatalog();
  const p = extraPaths(claudeDir);
  const rows = (ledger ? ledger.profiles : []).map((x) => redactProfile(x, claudeDir));
  if (asJson)
    emitJson(
      {
        ok: true,
        ledger: p.ledger,
        exists: !!ledger,
        catalog_as_of: cat ? cat.as_of : null,
        catalog_stale: cat ? cat._stale : null,
        profiles: rows,
        routes: ledger ? ledger.routes : [],
        counts: {
          profiles: rows.length,
          verified: rows.filter((r) => r.verified_at).length,
          credential_present: rows.filter((r) => r.credential.present).length,
        },
        // W8 (v0.51.0) — THE SETUP GATE, computed here and nowhere else. It
        // carries WHICH FLOOR you are on, because the instruction differs: no
        // connection at all means install-or-add, and a connection that has
        // never answered means test it.
        gate: extraConnectedState(claudeDir),
        extra_enabled: isTrue(resolvedConfig(claudeDir).extra_enabled),
      },
      0
    );
  if (!rows.length) {
    console.log(
      "\nNo extra profiles yet." +
        ui.color.gray(
          "\n\n  orc extra providers                  what ORC knows how to reach\n" +
            "  orc extra add <name> --provider <id> --engine api --env-key <VAR>\n" +
            "  orc extra ping <name>                the connection gate\n"
        )
    );
    return;
  }
  console.log(ui.header(`ORC · extra — ${plural(rows.length, "profile")}`));
  console.log("");
  console.log(
    ui.kv(
      rows.map((r) => [
        r.name,
        `${r.provider}/${r.engine}`,
        (r.verified_at ? ui.color.green("verified " + r.verified_at.slice(0, 10)) : ui.color.yellow("unverified")) +
          "  " +
          (r.credential.source === "tool"
          ? ui.color.gray("the tool holds its own key")
          : r.credential.present
            ? ui.color.gray(`key ${r.credential.source}`)
            : ui.color.red(`no key (${r.credential.source} ${r.credential.key_name || "—"})`)),
      ])
    )
  );
  console.log(ui.color.gray("\n  No key value is ever stored or printed here — only the variable NAME.\n"));
}

function extraShow(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  if (!prof) {
    const known = ledger ? ledger.profiles.map((x) => x.name) : [];
    const hint = `unknown profile "${name || ""}"${known.length ? ` — known: ${known.join(", ")}` : " — none configured yet"}`;
    if (asJson) emitJson({ ok: false, reason: "unknown-profile", profile: name || null, known, hint }, 2);
    console.error("❌ " + hint);
    process.exit(2);
  }
  const cat = readCatalog();
  const row = catalogRow(cat, prof.provider);
  const view = redactProfile(prof, claudeDir);
  if (asJson)
    emitJson(
      {
        ok: true,
        profile: view,
        catalog: row
          ? { id: row.id, label: row.label, docs_url: row.docs_url, terms_url: row.terms_url, notes: row.notes }
          : null,
        history: (ledger.history || []).filter((h) => h.profile === name),
      },
      0
    );
  console.log(ui.header(`ORC · extra — ${name}`));
  console.log("");
  console.log(
    ui.kv([
      [
        "provider",
        `${view.provider}${view.region !== "default" ? " (" + view.region + ")" : ""}${row ? "  " + row.label : ""}`,
      ],
      ["engine", view.engine],
      ["api base", view.base_url || "—"],
      ["/anthropic base", view.anthropic_base_url || "—"],
      ["auth variable", view.auth_env || "—"],
      [
        "credential",
        `${view.credential.source} ${view.credential.key_name || "—"} · ${view.credential.present ? "present" : "MISSING"}`,
      ],
      ["verified", view.verified_at ? `${view.verified_at} via ${view.verify_method}` : "no"],
      ["models seen", view.models_seen.length ? view.models_seen.join(", ") : "— (run `orc extra ping`)"],
      ["tool fidelity", view.tool_fidelity ? "measured" : "— (measured on first dispatch)"],
      ["terms", (row && row.terms_url) || "—"],
    ])
  );
  console.log("");
}

// ── orc extra remove ───────────────────────────────────────────────────────
// A reason is REQUIRED — the /orc-pact retirement rule. Removing a profile
// un-routes every band pointing at it, which is a change to how this repo
// builds; a change like that with no recorded why is a change nobody can
// explain in three weeks.
function extraRemove(claudeDir, name) {
  const asJson = wantsJson();
  const reason = flag("--reason");
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  const fail = (r, msg, code) => {
    if (asJson) emitJson({ ok: false, reason: r, error: msg }, code);
    console.error("❌ " + msg);
    process.exit(code);
  };
  if (!prof) fail("unknown-profile", `unknown profile "${name || ""}".`, 2);
  if (typeof reason !== "string" || !reason.trim())
    fail(
      "no-reason",
      `a reason is required: orc extra remove ${name} --reason "<why>"\n` +
        "   Removing a profile un-routes every band pointing at it. That is worth one sentence.",
      1
    );

  const orphaned = ledger.routes.filter((r) => r.profile === name);
  ledger.routes = ledger.routes.filter((r) => r.profile !== name);
  ledger.profiles = ledger.profiles.filter((x) => x.name !== name);
  extraHistory(ledger, "remove", { profile: name, reason: reason.trim(), routes_dropped: orphaned.length });
  const file = writeExtra(claudeDir, ledger);
  // The vault record goes with it: a key nothing can reach is a key nothing
  // should keep. The profile's history stays — it is not a secret.
  const vaultWiped = extraVaultForget(claudeDir, name);

  if (asJson)
    emitJson(
      { ok: true, removed: name, reason: reason.trim(), routes_dropped: orphaned, vault_record_removed: vaultWiped, ledger: file },
      0
    );
  console.log(`\nRemoved profile ${ui.color.cyan(name)}  —  ${reason.trim()}`);
  if (orphaned.length)
    console.log(
      "  " +
        ui.mark.warn(
          `${plural(orphaned.length, "route row")} dropped with it: ` +
            orphaned.map((r) => `[${r.from},${r.to})`).join(", ") +
            " — those scores are back on the Claude ladder."
        )
    );
  console.log("");
}

// Drop a profile's vault record. Called on `remove`, and by the vault's own
// self-destruct. Best effort: a vault that does not exist yet is not an error,
// and a removal must never fail because a file it does not need is missing.
function extraVaultForget(claudeDir, name) {
  const p = extraPaths(claudeDir).vault;
  try {
    const v = JSON.parse(fs.readFileSync(p, "utf8"));
    if (v && v.records && v.records[name]) {
      delete v.records[name];
      fs.writeFileSync(p, JSON.stringify(v, null, 2) + "\n", { mode: 0o600 });
      return true;
    }
  } catch (_) {}
  return false;
}

// ── The wire (zero-dep) ────────────────────────────────────────────────────
// One tiny request helper for every probe. Two properties are load-bearing and
// neither is a performance choice:
//
//   REDIRECTS ARE A FAILURE. Claude Code's own gateway model discovery refuses
//   them deliberately, so a credential cannot be handed to a redirect target
//   the user never named. We copy that verbatim.
//
//   The TIMEOUT is short and explicit. A probe that hangs is a connect modal
//   that hangs, and a profile is either reachable now or it is not.
// THE PROBE SEAM (v1.0.0 W15), and it is deliberately the ONLY one for the
// PROBES, exactly as `ORC_TEST_BUDGET_FLOOR_MS` is the only one for a dispatch.
//
// Every budget below is a WALL CLOCK, and a wall clock is a fact about the box
// rather than about the decision these probes make. That distinction is what
// the suite kept tripping over: on a loaded box a LOCAL fake provider misses
// rung 1's 3 s, the ping falls THROUGH to rung 2, and a test asserting
// `verify_method: "models"` fails with `'completion' !== 'models'` at ~23 s.
// It looks exactly like a regression, it lands on a different file every run,
// and every affected file passes on its own. `test/_helpers.js` recorded three
// debugging rounds of it, `test/cli/extra-slots.test.js` and
// `test/cli/extra-demotion.test.js` each recorded the diagnosis, and the whole
// v1.0.0 build gated on a suite that flaked this way in W6, W7, W8 and W14.
//
// The budgets themselves are PRODUCT RULES and they do not move: a probe that
// hangs is a connect modal that hangs. What moves is that a test can now say
// "give this loopback answer the headroom a real network call would have", so
// the assertion is about the RUNG THAT ANSWERED and never about the scheduler.
// Unset, this returns its argument and the shipped behaviour is byte-identical.
// Nothing in ORC ever sets it; only a test does.
function extraProbeMs(ms) {
  const v = Number(process.env.ORC_TEST_PROBE_MS);
  return Number.isFinite(v) && v > 0 ? v : ms;
}

function extraHttp(opts) {
  return new Promise((resolve) => {
    let url;
    try {
      url = new URL(opts.url);
    } catch (_) {
      return resolve({ ok: false, reason: "bad-url", error: `not a URL: ${opts.url}` });
    }
    if (url.protocol !== "https:" && url.protocol !== "http:")
      return resolve({ ok: false, reason: "bad-url", error: `unsupported protocol ${url.protocol}` });
    const lib = url.protocol === "https:" ? require("https") : require("http");
    const body = opts.body === undefined ? null : Buffer.from(JSON.stringify(opts.body), "utf8");
    const headers = Object.assign({ accept: "application/json" }, opts.headers || {});
    if (body) {
      headers["content-type"] = "application/json";
      headers["content-length"] = String(body.length);
    }
    const started = Date.now();
    const req = lib.request(
      { protocol: url.protocol, hostname: url.hostname, port: url.port || undefined, path: url.pathname + url.search, method: opts.method || "GET", headers },
      (res) => {
        // A 3xx is refused BEFORE a single byte of the body is read: following
        // it would send the Authorization header to a host the user did not
        // configure. This is a credential-safety rule, not a strictness one.
        if (res.statusCode >= 300 && res.statusCode < 400) {
          res.destroy();
          return resolve({
            ok: false,
            reason: "redirect-refused",
            status: res.statusCode,
            error: `endpoint redirected to ${res.headers.location || "an unnamed host"} — ORC refuses to follow a redirect with your credential attached. Configure the final URL directly.`,
            ms: Date.now() - started,
          });
        }
        // The ceiling is the CALLER's: 2 MB is right for a models list and
        // wrong for a long completion, and a silently truncated body parses as
        // a malformed answer, which is a different and much more confusing
        // fact than "it was too big". So `truncated` is REPORTED.
        const cap = Number(opts.maxBytes) || 2 * 1024 * 1024;
        const chunks = [];
        let size = 0;
        let truncated = false;
        res.on("data", (c) => {
          size += c.length;
          if (size <= cap) chunks.push(c);
          else truncated = true;
        });
        res.on("end", () => {
          const text = Buffer.concat(chunks).toString("utf8");
          let json = null;
          try {
            json = JSON.parse(text);
          } catch (_) {}
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            status: res.statusCode,
            json,
            text: json ? null : text.slice(0, 400),
            truncated,
            bytes: size,
            ms: Date.now() - started,
          });
        });
      }
    );
    req.setTimeout(opts.timeoutMs || extraProbeMs(3000), () => {
      req.destroy();
      resolve({ ok: false, reason: "timeout", error: `no answer in ${opts.timeoutMs || extraProbeMs(3000)}ms`, ms: Date.now() - started });
    });
    req.on("error", (e) =>
      resolve({ ok: false, reason: "unreachable", error: e.message, code: e.code, ms: Date.now() - started })
    );
    if (body) req.write(body);
    req.end();
  });
}

// The provider's own words, never ORC's paraphrase. A gateway that wraps its
// upstream's error in a house envelope is a real fidelity problem, and dropping
// the text here would hide it.
function extraErrText(res) {
  if (!res) return "no response";
  if (res.error) return res.error;
  const j = res.json;
  if (j) {
    const e = j.error || j;
    const m = e.message || e.msg || e.detail || e.type;
    if (m) return String(m).slice(0, 300);
  }
  if (res.text) return String(res.text).replace(/\s+/g, " ").slice(0, 300);
  return `HTTP ${res.status}`;
}

// Is this rejection ABOUT THE MODEL NAME? The unknown-model escape treats a
// 400/404/422 as proof that the endpoint authenticated and then declined the id
// ORC invented — which is only true if the endpoint is the one it was aiming at.
// A gateway answering "Unknown request URL" with a 404 proves the opposite.
//
// The test is deliberately narrow: the body must NAME the model ORC asked for,
// or say something about a model/engine/deployment. Anything else — a routing
// error, an HTML error page, an empty body — is NOT evidence and does not get
// to stand in for one.
function extraErrAboutModel(res, model) {
  const text = extraErrText(res);
  if (!text) return false;
  if (model && text.includes(model)) return true;
  return /\b(model|engine|deployment)\b/i.test(text) && !/\b(url|path|endpoint|route)\b/i.test(text);
}

// ── The credential vault (P10) ─────────────────────────────────────────────
//
// `a key ORC can read without you` has broken this contract. The vault is
// decryptable only with a passphrase ORC never stores, never logs, never puts
// in argv, and never shows a model.
//
// AES-256-GCM under scrypt(pepper + " " + passphrase). NO separate verifier
// hash is stored: GCM's auth tag IS the verifier, and a stored hash would hand
// an offline attacker a cheaper oracle than the cipher itself.
//
// N = 2^17 costs ~128 MB and a beat of wall clock. THAT BEAT IS THE ENTIRE
// DEFENCE against an offline attack on a copied file, so it is a feature and
// must never be tuned down for responsiveness. Node's default maxmem is 32 MB
// and scryptSync THROWS at this N without being told otherwise.
const EXTRA_KDF = { algo: "scrypt", N: 131072, r: 8, p: 1, len: 32 };
const EXTRA_KDF_MAXMEM = 256 * 1024 * 1024;
const EXTRA_VAULT_MAX_ATTEMPTS_DEFAULT = 10;
// The `shipped` pepper. It travels to every user inside the npm package, so it
// is OBFUSCATION and nothing more — a secret published on npm is not a secret.
// It exists only for someone who explicitly wants a vault portable between
// machines with the passphrase alone, and every surface that offers it prints
// that weakness beside it. `install` is the default.
const EXTRA_SHIPPED_PEPPER = "orc-extra/v1/shipped-pepper/not-a-secret";

function extraPepperPath() {
  return path.join(os.homedir(), ".claude", "orc", "extra-pepper");
}

// 32 random bytes at ~/.claude/orc/extra-pepper, mode 0600, generated ONCE.
// A real second factor: the vault travels with the repo, the pepper does not —
// which also means LOSING THE PEPPER LOSES THE KEY, and every surface that
// writes one says so.
function extraPepper(mode, { create } = {}) {
  if (mode === "shipped") return { ok: true, value: EXTRA_SHIPPED_PEPPER, mode: "shipped" };
  const p = extraPepperPath();
  try {
    return { ok: true, value: fs.readFileSync(p, "utf8").trim(), mode: "install", path: p };
  } catch (_) {}
  if (!create)
    return {
      ok: false,
      reason: "pepper-missing",
      path: p,
      error: `the install pepper at ${p} is gone. It is one of the two halves of the key and ORC cannot regenerate it — the stored keys cannot be opened again. Paste a new key from your provider.`,
    };
  try {
    fs.mkdirSync(path.dirname(p), { recursive: true });
    const val = crypto.randomBytes(32).toString("base64");
    fs.writeFileSync(p, val + "\n", { mode: 0o600 });
    return { ok: true, value: val, mode: "install", path: p, created: true };
  } catch (e) {
    return { ok: false, reason: "pepper-unwritable", path: p, error: e.message };
  }
}

function extraDerive(pepper, passphrase, salt) {
  return crypto.scryptSync(pepper + " " + passphrase, salt, EXTRA_KDF.len, {
    N: EXTRA_KDF.N,
    r: EXTRA_KDF.r,
    p: EXTRA_KDF.p,
    maxmem: EXTRA_KDF_MAXMEM,
  });
}

function readVault(claudeDir) {
  try {
    const v = JSON.parse(fs.readFileSync(extraPaths(claudeDir).vault, "utf8"));
    v.records = v.records && typeof v.records === "object" ? v.records : {};
    return v;
  } catch (_) {
    return { version: 1, kdf: EXTRA_KDF, records: {} };
  }
}

function writeVault(claudeDir, v) {
  const p = extraPaths(claudeDir);
  fs.mkdirSync(p.dir, { recursive: true });
  v.version = 1;
  v.kdf = EXTRA_KDF; // pinned IN the file so a future reader sees the cost was chosen
  fs.writeFileSync(p.vault, JSON.stringify(v, null, 2) + "\n", { mode: 0o600 });
  try {
    fs.chmodSync(p.vault, 0o600);
  } catch (_) {}
  return p.vault;
}

function extraVaultPut(claudeDir, name, plaintext, passphrase, pepperMode) {
  const pep = extraPepper(pepperMode, { create: true });
  if (!pep.ok) return pep;
  const salt = crypto.randomBytes(16);
  const iv = crypto.randomBytes(12);
  const key = extraDerive(pep.value, passphrase, salt);
  const c = crypto.createCipheriv("aes-256-gcm", key, iv);
  const ct = Buffer.concat([c.update(Buffer.from(plaintext, "utf8")), c.final()]);
  const tag = c.getAuthTag();
  key.fill(0);
  const v = readVault(claudeDir);
  v.records[name] = {
    salt: salt.toString("base64"),
    iv: iv.toString("base64"),
    ciphertext: ct.toString("base64"),
    tag: tag.toString("base64"),
    pepper: pep.mode,
    created_at: new Date().toISOString(),
    attempts: 0,
    wiped_at: null,
  };
  const file = writeVault(claudeDir, v);
  return { ok: true, vault: file, pepper: pep.mode, pepper_path: pep.path || null, pepper_created: !!pep.created };
}

// Reading it back, and the self-destruct.
//
// `attempts` is incremented AND FLUSHED TO DISK BEFORE the decrypt is
// attempted. A counter written after the attempt is a counter you defeat with
// Ctrl-C.
function extraVaultGet(claudeDir, name, passphrase, maxAttempts) {
  const max = Math.max(3, Number(maxAttempts) || EXTRA_VAULT_MAX_ATTEMPTS_DEFAULT);
  const v = readVault(claudeDir);
  const rec = v.records[name];
  if (!rec) return { ok: false, reason: "no-record", error: `no stored key for "${name}".` };
  if (rec.wiped_at)
    return {
      ok: false,
      reason: "wiped",
      wiped_at: rec.wiped_at,
      error: `the stored key for "${name}" was deleted after ${max} wrong attempts. Paste a new key from your provider.`,
    };
  const pep = extraPepper(rec.pepper);
  if (!pep.ok) return pep;

  rec.attempts = (Number(rec.attempts) || 0) + 1;
  writeVault(claudeDir, v);

  try {
    const d = crypto.createDecipheriv(
      "aes-256-gcm",
      extraDerive(pep.value, passphrase, Buffer.from(rec.salt, "base64")),
      Buffer.from(rec.iv, "base64")
    );
    d.setAuthTag(Buffer.from(rec.tag, "base64"));
    const out = Buffer.concat([d.update(Buffer.from(rec.ciphertext, "base64")), d.final()]).toString("utf8");
    rec.attempts = 0;
    writeVault(claudeDir, v);
    return { ok: true, value: out, attempts_used: 0, max };
  } catch (_) {
    const used = rec.attempts;
    if (used >= max) {
      // Overwrite the ciphertext with random bytes of the same length before
      // dropping the record, so the bytes are not merely unlinked. A TOMBSTONE
      // stays: `wiped` and `never had a key` are different facts and a panel
      // that collapsed them would be lying about what happened here.
      const len = Buffer.from(rec.ciphertext, "base64").length;
      rec.ciphertext = crypto.randomBytes(len).toString("base64");
      writeVault(claudeDir, v);
      v.records[name] = { wiped_at: new Date().toISOString(), attempts: used, pepper: rec.pepper };
      writeVault(claudeDir, v);
      return {
        ok: false,
        reason: "wiped",
        attempts_used: used,
        max,
        error: `wrong passphrase — attempt ${used} of ${max}. The stored key has been deleted, on purpose. Paste a new key from your provider.`,
      };
    }
    return {
      ok: false,
      reason: "bad-passphrase",
      attempts_used: used,
      max,
      // A countdown toward a destructive action that is not SHOWN is
      // indistinguishable from no countdown at all.
      error: `wrong passphrase — attempt ${used} of ${max}. At ${max} the stored key is deleted.`,
    };
  }
}

// The honesty this needs, in one place so every surface repeats the same
// sentence: the counter defends against a person at your keyboard. It does NOT
// defend against someone who copies the file and brute-forces it offline. The
// defence there is scrypt's cost parameters, and nothing else.
const EXTRA_VAULT_HONESTY =
  "The attempt counter stops someone at your keyboard. It does NOT stop someone who copies " +
  "the vault file and tries offline — scrypt's cost is the only defence there.";
const EXTRA_VAULT_WARNING = [
  "Write your passphrase down somewhere safe now.",
  "ORC does not store it and cannot recover it. If you lose it, the stored key is gone",
  "and you paste a new one from your provider. After ten wrong attempts ORC deletes the",
  "stored key on purpose.",
];

// -- v0.52.0 - THE PASSPHRASE CACHE, and its deadline ----------------------
//
// One honest sentence first, because the whole design follows from it: a
// passphrase stored on the same machine as the vault it opens is NOT A SECOND
// FACTOR ANY MORE. It becomes a DEADLINE - the shape of ssh-agent and
// gpg-agent, which is a real and respectable thing to build, but it is a
// different promise from the one the vault makes. Everywhere this is described,
// it is described as what it is.
//
// There is exactly one way to keep real value in it, and this uses it:
//
//   the vault      .claude/orc/extra-vault.json   the project, gitignored
//   the pepper     ~/.claude/orc/extra-pepper     $HOME, 0600, never travels
//   the cache      .claude/orc/.orc-ec-session    the project, gitignored, 0600
//
// The cache is encrypted UNDER THE PEPPER, so A COPY OF THE PROJECT DIRECTORY
// OPENS NOTHING. That is a genuine property, it is worth saying out loud in
// every surface that shows the countdown, and it is why the project is the
// right place for the file rather than a compromise.
const EXTRA_SESSION_HONESTY =
  "While this passphrase is saved, anything that can run as you on this computer can open " +
  "the connection. The deadline is what limits that. Copying the project folder to another " +
  "computer does not open it.";
// COMPUTED, never stored - a stored status word is a wrong status word the next
// day (the computeWikiFreshness rule, and the /orc-pact rule). EXPIRING is the
// larger of "3 days left" and "the last 20% of the TTL", so a 1-day deadline is
// not permanently EXPIRING and a 360-day one warns with more than a weekend.
const EXTRA_SESSION_STATES = ["ACTIVE", "EXPIRING", "EXPIRED", "ABSENT"];

function readSession(claudeDir) {
  try {
    const v = JSON.parse(fs.readFileSync(extraPaths(claudeDir).session, "utf8"));
    v.records = v.records && typeof v.records === "object" ? v.records : {};
    return v;
  } catch (_) {
    return { version: 1, kdf: EXTRA_KDF, records: {} };
  }
}

function writeSession(claudeDir, v) {
  const p = extraPaths(claudeDir);
  fs.mkdirSync(p.dir, { recursive: true });
  v.version = 1;
  v.kdf = EXTRA_KDF;
  fs.writeFileSync(p.session, JSON.stringify(v, null, 2) + "\n", { mode: 0o600 });
  try {
    fs.chmodSync(p.session, 0o600);
  } catch (_) {}
  return p.session;
}

// The key is derived from the PEPPER and the profile name - there is no second
// passphrase to open the passphrase. `N = 2^17` is not tuned down here either:
// that cost IS the defence, and a cache that opens instantly on a copied disk
// would have thrown away the one property this file has.
function extraSessionDerive(pepper, profile, salt) {
  return crypto.scryptSync(pepper + " ec " + profile, salt, EXTRA_KDF.len, {
    N: EXTRA_KDF.N,
    r: EXTRA_KDF.r,
    p: EXTRA_KDF.p,
    maxmem: EXTRA_KDF_MAXMEM,
  });
}

function extraSessionTtl(cfg) {
  const n = Number((cfg && cfg.extra_passphrase_ttl_days) || 30);
  return EXTRA_TTL_DAYS.indexOf(n) === -1 ? 30 : n;
}

function extraSessionPut(claudeDir, profile, passphrase, ttlDays) {
  const days = EXTRA_TTL_DAYS.indexOf(Number(ttlDays)) === -1 ? 30 : Number(ttlDays);
  const pep = extraPepper("install", { create: true });
  if (!pep.ok) return pep;
  const salt = crypto.randomBytes(16);
  const iv = crypto.randomBytes(12);
  const key = extraSessionDerive(pep.value, profile, salt);
  const c = crypto.createCipheriv("aes-256-gcm", key, iv);
  const ct = Buffer.concat([c.update(Buffer.from(passphrase, "utf8")), c.final()]);
  const tag = c.getAuthTag();
  key.fill(0);
  const now = new Date();
  const v = readSession(claudeDir);
  v.records[profile] = {
    salt: salt.toString("base64"),
    iv: iv.toString("base64"),
    ciphertext: ct.toString("base64"),
    tag: tag.toString("base64"),
    pepper: "install",
    created_at: now.toISOString(),
    expires_at: new Date(now.getTime() + days * 86400000).toISOString(),
    ttl_days: days,
    last_used_at: null,
  };
  const file = writeSession(claudeDir, v);
  return { ok: true, file, ttl_days: days, expires_at: v.records[profile].expires_at };
}

// The state, computed on read from `expires_at` and NOTHING ELSE. A record whose
// deadline has passed reads EXPIRED without the file being rewritten - the
// sweep is what removes it, and the sweep runs on an `orc extra` command.
function extraSessionState(claudeDir, profile) {
  const rec = readSession(claudeDir).records[profile];
  if (!rec || !rec.expires_at) return { state: "ABSENT", days_left: null, expires_at: null, ttl_days: null };
  const t = Date.parse(rec.expires_at);
  if (isNaN(t)) return { state: "ABSENT", days_left: null, expires_at: null, ttl_days: null };
  const msLeft = t - Date.now();
  const daysLeft = Math.floor(msLeft / 86400000);
  const ttl = Number(rec.ttl_days) || 30;
  const warnAt = Math.max(3, Math.ceil(ttl * 0.2));
  const state = msLeft <= 0 ? "EXPIRED" : daysLeft <= warnAt ? "EXPIRING" : "ACTIVE";
  return {
    state,
    days_left: Math.max(0, daysLeft),
    expires_at: rec.expires_at,
    ttl_days: ttl,
    created_at: rec.created_at || null,
    last_used_at: rec.last_used_at || null,
  };
}

function extraSessionGet(claudeDir, profile) {
  const st = extraSessionState(claudeDir, profile);
  if (st.state === "ABSENT") return { ok: false, reason: "absent" };
  if (st.state === "EXPIRED") return { ok: false, reason: "expired", expires_at: st.expires_at };
  const v = readSession(claudeDir);
  const rec = v.records[profile];
  const pep = extraPepper(rec.pepper);
  if (!pep.ok) return { ok: false, reason: "pepper-missing", error: pep.error };
  try {
    const d = crypto.createDecipheriv(
      "aes-256-gcm",
      extraSessionDerive(pep.value, profile, Buffer.from(rec.salt, "base64")),
      Buffer.from(rec.iv, "base64")
    );
    d.setAuthTag(Buffer.from(rec.tag, "base64"));
    const out = Buffer.concat([d.update(Buffer.from(rec.ciphertext, "base64")), d.final()]).toString("utf8");
    // NO AUTO-EXTEND. A deadline that renews itself every time you use it is not
    // a deadline. `last_used_at` is recorded for the report and changes nothing.
    rec.last_used_at = new Date().toISOString();
    writeSession(claudeDir, v);
    return { ok: true, value: out, state: st.state, days_left: st.days_left, expires_at: st.expires_at };
  } catch (_) {
    // The pepper is there and the record will not open: it was written under a
    // different pepper. Unreadable is a REASON, never a silent absence.
    return { ok: false, reason: "unreadable" };
  }
}

function extraSessionForget(claudeDir, profile) {
  const v = readSession(claudeDir);
  const rec = v.records[profile];
  if (!rec) return { ok: true, removed: false };
  // Overwrite before unlinking, the vault's own rule.
  try {
    const len = Buffer.from(rec.ciphertext || "", "base64").length;
    if (len) {
      rec.ciphertext = crypto.randomBytes(len).toString("base64");
      writeSession(claudeDir, v);
    }
  } catch (_) {}
  delete v.records[profile];
  writeSession(claudeDir, v);
  return { ok: true, removed: true };
}

// Called at the top of EVERY `orc extra` command and at the P0 gate. There is
// deliberately NO timer: a background process that deletes credentials is a
// background process nobody can audit.
//
// MEMOISED FOR THE LIFE OF THE PROCESS, and that is load-bearing rather than an
// optimisation: the sweep DESTROYS the evidence the gate needs. Swept and never
// saved both read ABSENT off the disk, and those are different facts — one is a
// deadline you set and missed, the other is a passphrase you never saved. So the
// list of what this call dropped IS the record that it expired, and every later
// reader in the same command gets the same answer.
let extraSweptThisRun = null;
function extraSessionSweep(claudeDir) {
  if (extraSweptThisRun) return extraSweptThisRun;
  const v = readSession(claudeDir);
  const dropped = [];
  for (const name of Object.keys(v.records)) {
    if (extraSessionState(claudeDir, name).state === "EXPIRED") dropped.push(name);
  }
  for (const name of dropped) extraSessionForget(claudeDir, name);
  extraSweptThisRun = dropped;
  return dropped;
}
// What a reader should call. It answers EXPIRED for a record this command just
// swept, rather than the ABSENT the disk now shows.
function extraSessionStateSwept(claudeDir, profile) {
  const st = extraSessionState(claudeDir, profile);
  if (st.state !== "ABSENT") return st;
  let swept = [];
  try {
    swept = extraSessionSweep(claudeDir);
  } catch (_) {}
  return swept.indexOf(profile) === -1 ? st : Object.assign({}, st, { state: "EXPIRED" });
}

// ── Reading a secret without it reaching argv, a log, or the screen ────────
// Piped stdin: line 1 is the key, an OPTIONAL line 2 is the passphrase (the
// only way an unattended shell can complete the save). A TTY gets a real
// no-echo prompt instead.
function readStdinLines() {
  try {
    return fs.readFileSync(0, "utf8").split(/\r?\n/);
  } catch (_) {
    return [];
  }
}

function promptSecret(label) {
  if (!process.stdin.isTTY) return null;
  process.stderr.write(label);
  let out = "";
  const fd = process.stdin.fd;
  try {
    process.stdin.setRawMode(true);
  } catch (_) {
    return null;
  }
  const buf = Buffer.alloc(1);
  for (;;) {
    let n = 0;
    try {
      n = fs.readSync(fd, buf, 0, 1, null);
    } catch (e) {
      if (e.code === "EAGAIN") continue;
      break;
    }
    if (!n) break;
    const ch = buf[0];
    if (ch === 3) {
      // Ctrl-C. The attempts counter is already flushed by the time a decrypt
      // runs, so there is nothing to gain here — but exit cleanly anyway.
      try {
        process.stdin.setRawMode(false);
      } catch (_) {}
      process.stderr.write("\n");
      process.exit(130);
    }
    if (ch === 13 || ch === 10) break;
    if (ch === 127 || ch === 8) {
      out = out.slice(0, -1);
      continue;
    }
    out += String.fromCharCode(ch);
  }
  try {
    process.stdin.setRawMode(false);
  } catch (_) {}
  process.stderr.write("\n");
  return out;
}

// ── Verification freshness — COMPUTED on read, never stored ────────────────
// The computeWikiFreshness rule. A stored status word is a status word that
// lies the moment the clock moves. And a STALE verification is not a FAILED
// one: it still routes (the /orc-pact UNCHECKABLE rule), it just re-pings
// before wave 1.
// W8 — ONE definition of CONNECTED, and every consumer reads it: the config
// gate, `orc extra doctor`, and the panel through `orc extra list --json`. A
// second idea of "has anything ever answered" is exactly the drift this
// subsystem's own rules forbid.
//
// It has TWO FLOORS and it says which one you are on, because the instruction
// differs: with no tool installed and no key the answer is an INSTALL, and with
// a profile that has never verified the answer is a TEST. Showing a Connect box
// to someone who has neither is showing them a button that cannot succeed.
function extraConnectedState(claudeDir) {
  const ledger = readExtra(claudeDir);
  const profiles = (ledger && ledger.profiles) || [];
  const verified = profiles.filter((x) => x.verified_at);
  if (verified.length)
    return {
      connected: true,
      floor: null,
      profiles: profiles.length,
      verified: verified.length,
      why: null,
      next: null,
    };
  if (!profiles.length)
    return {
      connected: false,
      floor: "no-connection",
      profiles: 0,
      verified: 0,
      why: "no connection has been configured at all.",
      next: "Add one with `orc extra add <name> --provider <id> --engine <api|claude-shim|cli>`, then test it with `orc extra ping <name>`.",
    };
  return {
    connected: false,
    floor: "never-tested",
    profiles: profiles.length,
    verified: 0,
    why: `${plural(profiles.length, "connection")} configured and not one of them has ever answered.`,
    next: `Test one: \`orc extra ping ${profiles[0].name}\``,
  };
}

function extraVerifyState(prof, cfg) {
  const maxDays = Number((cfg && cfg.extra_verify_max_days) || EXTRA_VERIFY_MAX_DAYS_DEFAULT);
  if (!prof.verified_at) return { state: "UNVERIFIED", age_days: null, max_days: maxDays };
  const t = Date.parse(prof.verified_at);
  if (isNaN(t)) return { state: "UNVERIFIED", age_days: null, max_days: maxDays };
  const age = Math.floor((Date.now() - t) / 86400000);
  return { state: age > maxDays ? "STALE" : "VERIFIED", age_days: age, max_days: maxDays };
}
const EXTRA_VERIFY_MAX_DAYS_DEFAULT = 7;

// The two base URLs, per engine. There are TWO and therefore two probes: the
// OpenAI-compatible one that engine `api` speaks, and the `/anthropic` shim
// that engine `claude-shim` drives. `/v1/models` does not necessarily live
// under the second one, so the profile records WHICH URL it probed.
function extraProbeBase(prof, cat) {
  const row = catalogRow(cat, prof.provider);
  if (prof.engine === "claude-shim")
    return { base: prof.anthropic_base_url, kind: "anthropic", models_path: (row && row.models_path) || "/v1/models" };
  return { base: prof.base_url, kind: "openai", models_path: (row && row.models_path) || "/v1/models" };
}

// v0.53.3 — ONE completions URL, and the PROBES now speak it too. `ping` rung 2
// and `models --test` hardcoded `{base}/chat/completions` while dispatch derived
// `{base}/v1/chat/completions` and honoured `completions_path`; neither probe
// honoured it at all. DeepSeek accepts both spellings, so this was not the 401 —
// but on a provider that accepts only one it produces a profile that verifies
// GREEN and dispatches into a 404, which is the same lie wearing a different
// status code. A green badge is earned by the URL a wave will actually call, or
// it is not earned.
function extraProbeCompletionsUrl(prof, probe) {
  if (probe.kind === "anthropic") return joinUrl(probe.base, "/v1/messages");
  return apiCompletionsUrl(prof);
}

// The auth HEADER is decided by the variable NAME, exactly as Claude Code does
// it. Ollama's Anthropic endpoint REJECTS x-api-key, which is why a catalog row
// naming a header instead of a variable would have failed at 401 with nothing
// on screen explaining why.
function extraAuthHeaders(prof, key) {
  if (prof.engine === "claude-shim" && prof.auth_env === "ANTHROPIC_API_KEY")
    return { "x-api-key": key, "anthropic-version": "2023-06-01" };
  const h = { authorization: "Bearer " + key };
  if (prof.engine === "claude-shim") h["anthropic-version"] = "2023-06-01";
  return h;
}

const joinUrl = (base, p) => String(base).replace(/\/+$/, "") + (p.startsWith("/") ? p : "/" + p);

// Resolve a profile's credential VALUE. Never returns it to a printer — every
// caller hands it straight to a request header or a child process's env.
// The two in-memory options are DIFFERENT FACTS and were one option, which is
// the whole of the v0.53.3 bug:
//
//   opts.inMemory    an EXPLICIT key supplied for THIS invocation (`--key-stdin`).
//                    It is the key being tested and then stored, so it WINS.
//   opts.ambientKey  a key found lying in the environment (`ORC_EXTRA_KEY`).
//                    It is the UNATTENDED-WAVE fallback and nothing more, so it
//                    only applies to a vault that cannot be opened here.
//
// Collapsing the second into the first meant `ORC_EXTRA_KEY` short-circuited the
// vault branch on its first line. Only `dispatch` and `conform` passed it, so
// `ping`, `models --test` and `preflight` opened the vault and went green while
// every wave authenticated with whatever that variable happened to hold — and
// died at 401 naming the vaulted key it never sent.
function extraCredentialValue(claudeDir, prof, opts) {
  const cred = prof.credential || {};
  if (cred.source === "env") {
    const v = cred.key_name ? process.env[cred.key_name] : null;
    if (!v)
      return {
        ok: false,
        reason: "missing-key",
        error: `${cred.key_name || "the credential variable"} is not set in this environment.`,
      };
    return { ok: true, value: v, source: "env", key_name: cred.key_name || null };
  }
  if (cred.source === "tool") return { ok: true, value: null, source: "tool", key_name: null };
  if (cred.source === "vault") {
    // An explicit key for this invocation is the one being proved. It outranks
    // the record it is about to replace, which is what makes
    // `orc extra ping <name> --key-stdin` a re-key rather than a no-op.
    if (opts && opts.inMemory) return { ok: true, value: opts.inMemory, source: "memory", key_name: null };
    let pass = opts && opts.passphrase;
    // v0.52.0 — THE SAVED PASSPHRASE, and this is the only place it is read.
    // Every caller — dispatch, ping, conform — gets it by asking for the
    // credential, so there is no second idea of where a passphrase comes from.
    // An EXPIRED record never reaches here: `extraSessionGet` refuses it and the
    // sweep removes it, which is what makes `orc extra preflight` the gate
    // rather than one of two competing ones.
    if (!pass && !(opts && opts.noSession)) {
      const cached = extraSessionGet(claudeDir, prof.name);
      if (cached.ok) pass = cached.value;
    }
    const ambient = (opts && opts.ambientKey) || null;
    if (!pass) {
      // The vault cannot be opened HERE. This is the case `ORC_EXTRA_KEY` was
      // written for — `extra_unlock: per-dispatch`, where nothing is cached on
      // purpose — and it is the only case it applies to.
      if (ambient) return { ok: true, value: ambient, source: "ambient", key_name: "ORC_EXTRA_KEY" };
      return { ok: false, reason: "locked", error: `"${prof.name}" is stored in the vault — a passphrase is required. Save one with a deadline: orc extra session ${prof.name} --save --ttl 30` };
    }
    const got = extraVaultGet(claudeDir, cred.key_name || prof.name, pass, opts && opts.maxAttempts);
    // A passphrase was in hand and the vault refused it. That is a real answer
    // ABOUT THE DECLARED SOURCE, not a reason to reach for a leftover variable:
    // falling through would burn a vault attempt and then send the wrong secret
    // anyway, which is the failure this ordering exists to end.
    if (!got.ok) return got;
    return { ok: true, value: got.value, source: "vault", key_name: cred.key_name || prof.name };
  }
  return { ok: false, reason: "no-credential", error: "this profile has no credential source." };
}

// WHICH SOURCE produced the secret that was just rejected. "your api key
// ****w5f7 is invalid" is the provider describing what it saw; the user reads it
// as the key they verified four minutes ago. Naming the source is what turns a
// multi-step diagnosis into a sentence.
function extraCredSourceLabel(cred) {
  const src = cred && cred.source;
  if (src === "ambient")
    return "the ORC_EXTRA_KEY environment variable — NOT this profile's vault record";
  if (src === "memory") return "the key supplied on stdin for this command";
  if (src === "vault") return `the vault record "${(cred && cred.key_name) || "?"}"`;
  if (src === "env") return `the ${(cred && cred.key_name) || "credential"} environment variable`;
  if (src === "tool") return "the tool's own sign-in — ORC sent no key";
  return "an unrecorded source";
}

// ── orc extra ping — THE CONNECTION GATE ───────────────────────────────────
//
// Cheapest rung first, and the profile records WHICH RUNG ANSWERED, because
// "verified by a models list" and "verified by a real completion" are different
// guarantees and collapsing them into one green tick would be a lie.
//
//   1  GET {base}{models_path}       free, zero tokens, and it fills models_seen
//   2  a max_tokens:1 completion     a fraction of a cent  (--deep forces it)
//   3  manual                        --model <id>, recorded as `manual`
//
// Rung 2 has one property worth the code: AN ERROR NAMING AN UNKNOWN MODEL
// STILL PROVES THE URL AND THE CREDENTIAL, because the endpoint authenticated
// before it rejected the name. That is the escape from the chicken-and-egg an
// endpoint with no models list would otherwise leave you in.
//
// exit 0 verified · 1 unreachable · 2 unknown profile
async function extraPing(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  if (!prof) {
    const known = ledger ? ledger.profiles.map((x) => x.name) : [];
    const hint = `unknown profile "${name || ""}"${known.length ? ` — known: ${known.join(", ")}` : " — none configured yet"}`;
    if (asJson) emitJson({ ok: false, reason: "unknown-profile", profile: name || null, known, hint }, 2);
    console.error("❌ " + hint);
    process.exit(2);
  }
  const cfg = resolvedConfig(claudeDir);
  const cat = readCatalog();
  const deep = flag("--deep") === true;
  // W5 (v0.51.0) — the PAID rung, forced, on every engine. It is opt-in
  // everywhere because a CLI ping is NOT a cheap ping: a one-line prompt through
  // a local agentic tool loads that tool's own system prompt and tool schemas
  // first, which is fifteen thousand input tokens against an api-engine probe's
  // ten. The panel quotes the two separately, before the button.
  const live = flag("--live") === true;
  const modelArg = typeof flag("--model") === "string" ? flag("--model") : null;
  const keyStdin = args.includes("--key-stdin");
  // v0.50.0 — RE-PROBING A STORED KEY. Without this a vaulted profile could
  // never be re-verified: the probe needs the key itself, `extraCredentialValue`
  // answers `locked` without one, and `orc extra unlock` proves a passphrase
  // while deliberately never yielding what it unlocked. So `extra-stale-verify`
  // promised a re-ping before wave 1 that was unreachable for exactly the
  // profiles the vault exists for.
  //
  // The passphrase decrypts the stored key INTO MEMORY for the probe and
  // nothing else: it is never re-written, and a wrong one spends an attempt on
  // the same counter every other unlock spends, because a second door with its
  // own counter is not a lock.
  const passStdin = args.includes("--passphrase-stdin");
  if (keyStdin && passStdin) {
    const msg =
      "--key-stdin and --passphrase-stdin cannot be combined: stdin's first line would be a key on one reading and a passphrase on the other.\n" +
      "   Pasting a NEW key: --key-stdin (line 1 the key, an optional line 2 the passphrase that stores it).\n" +
      "   Re-testing a STORED key: --passphrase-stdin (line 1 the passphrase).";
    if (asJson) emitJson({ ok: false, reason: "stdin-ambiguous", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }

  // The lifecycle: TEST FIRST, THEN STORE. A pasted key is held in memory for
  // the probe and NEVER written before the test is green; a failed test leaves
  // nothing behind — no half-profile, no orphan record — which also means a
  // typo'd key can never rot in a vault nobody can open.
  let pending = null;
  let pendingPass = null;
  let vaultPass = null;
  if (passStdin) {
    if ((prof.credential || {}).source !== "vault") {
      const msg = `"${name}" reads its key from the environment variable ${(prof.credential || {}).key_name || "(none)"} — there is no stored key to unlock, so --passphrase-stdin has nothing to do.`;
      if (asJson) emitJson({ ok: false, reason: "not-vaulted", profile: name, error: msg }, 1);
      console.error("❌ " + msg);
      process.exit(1);
    }
    vaultPass = process.stdin.isTTY
      ? promptSecret(`Passphrase for "${name}" (not shown): `)
      : (readStdinLines()[0] || "").trim();
    if (!vaultPass) {
      const msg = "no passphrase on stdin. Pipe it, or run this at a terminal.";
      if (asJson) emitJson({ ok: false, reason: "no-passphrase", profile: name, error: msg }, 1);
      console.error("❌ " + msg);
      process.exit(1);
    }
  }
  if (keyStdin) {
    if (process.stdin.isTTY) {
      pending = promptSecret(`Paste the API key for "${name}" (not shown): `);
    } else {
      const lines = readStdinLines();
      pending = (lines[0] || "").trim();
      pendingPass = (lines[1] || "").trim() || null;
    }
    if (!pending) {
      const msg = "no key on stdin. Pipe it (`printf '%s' \"$KEY\" | orc extra ping <profile> --key-stdin`) or run this at a terminal.";
      if (asJson) emitJson({ ok: false, reason: "no-key", error: msg }, 1);
      console.error("❌ " + msg);
      process.exit(1);
    }
  }

  // ONE exit, so the reset cannot be forgotten on a path somebody adds later.
  // A pasted key that failed its test leaves NOTHING behind: the key is never
  // written, and a profile that has never verified is removed — so a typo'd
  // key can never rot in a vault nobody can open. A profile that verified
  // BEFORE is kept: this ping failing does not un-know what an earlier one
  // proved (the /orc-pact rule — a failed check is not an erased history).
  const finish = (result, code) => {
    if (code !== 0 && pending && !prof.verified_at) {
      ledger.profiles = ledger.profiles.filter((x) => x.name !== name);
      extraHistory(ledger, "add-reverted", { profile: name, reason: result.error || result.reason || "connection test failed" });
      writeExtra(claudeDir, ledger);
      result.profile_reverted = true;
    }
    if (asJson) emitJson(result, code);
    extraPingRender(result);
    process.exit(code);
  };

  // Engine `cli` has no endpoint to probe — the thing that can be absent is the
  // binary, and after that a credential, and after that a model, and only after
  // ALL THREE a working call. So it gets its own FOUR-RUNG LADDER plus a rung-0
  // refusal, each rung its own `verify_method`, because `cli-bin` is not
  // `cli-auth` is not `cli-models` is not `cli-live` and nothing may read
  // stronger than it is.
  if (prof.engine === "cli") {
    const credCli = extraCredentialValue(claudeDir, prof, {
      inMemory: pending,
      passphrase: vaultPass,
      maxAttempts: cfg.extra_vault_max_attempts,
    });
    return extraPingCli({
      claudeDir,
      ledger,
      prof,
      cat,
      cfg,
      name,
      live,
      modelArg,
      finish,
      // A missing credential is NOT fatal here: the tool may hold its own, which
      // is exactly the case ORC refuses to break (it never writes another tool's
      // credential store, so a user who already logged in is untouched).
      key: credCli.ok ? credCli.value : null,
      key_error: credCli.ok ? null : credCli.error || credCli.reason,
      credSource: credCli.ok ? credCli.source : null,
      pending,
      pendingPass,
      asJson,
    });
  }

  const probe = extraProbeBase(prof, cat);
  if (!probe.base) {
    const msg = `profile "${name}" has no ${probe.kind === "anthropic" ? "/anthropic" : "API"} base URL.`;
    if (asJson) emitJson({ ok: false, reason: "no-base-url", profile: name, error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const cred = extraCredentialValue(claudeDir, prof, {
    inMemory: pending,
    passphrase: vaultPass,
    maxAttempts: cfg.extra_vault_max_attempts,
  });
  if (!cred.ok)
    return finish(
      Object.assign({ ok: false, profile: name, engine: prof.engine, base_url: probe.base, rung: null }, cred),
      1
    );
  const headers = extraAuthHeaders(prof, cred.value);
  const catRow = catalogRow(cat, prof.provider);
  const attempts = [];

  // ── rung 1: the free one ────────────────────────────────────────────────
  let models = [];
  if (!modelArg) {
    const url = joinUrl(probe.base, probe.models_path) + "?limit=1000";
    const r = await extraHttp({ url, headers, timeoutMs: extraProbeMs(3000) });
    attempts.push({ rung: "models", url, status: r.status || null, ok: !!r.ok, ms: r.ms || null, error: r.ok ? null : extraErrText(r) });
    if (r.ok && r.json) {
      // DELIBERATELY NOT Claude Code's filter. Its discovery keeps only ids
      // containing `claude` or `anthropic`; copying that here would discard
      // every DeepSeek, GLM and Kimi id — i.e. all of them. Do not "fix" this.
      const data = Array.isArray(r.json.data) ? r.json.data : Array.isArray(r.json.models) ? r.json.models : [];
      models = data.map((m) => (typeof m === "string" ? m : m.id || m.name)).filter(Boolean);
    }
    // W3 (v0.51.0) — SOME PROVIDERS SERVE THEIR MODELS LIST WITHOUT A CREDENTIAL.
    // Rung 1 treats a 200 on /models as verification, so on such a provider it
    // would mark a profile VERIFIED WITH A GARBAGE KEY. A row that says its list
    // is public fills models_seen and then falls THROUGH to the paid rung; the
    // free answer is recorded on attempts[] as `models-public` and is never the
    // profile's verification.
    const modelsPublic = !!(catRow && catRow.models_public);
    if (r.ok && models.length && modelsPublic)
      attempts.push({
        rung: "models-public",
        url,
        status: r.status || null,
        ok: true,
        ms: r.ms || null,
        error: null,
        note: "this provider serves its model list without a credential, so a 200 here proves the URL and nothing about the key.",
      });
    if (r.ok && models.length && !deep && !live && !modelsPublic) {
      prof.verified_at = new Date().toISOString();
      prof.verify_method = "models";
      prof.verify_base_url = probe.base;
      prof.verify_credential_source = cred.source;
      prof.latency_ms = r.ms;
      prof.models_seen = models;
      extraHistory(ledger, "ping", { profile: name, method: "models", models: models.length });
      writeExtra(claudeDir, ledger);
      const saved = maybeStorePendingKey(claudeDir, ledger, prof, pending, pendingPass, asJson);
      return finish(
        { ok: true, profile: name, engine: prof.engine, base_url: probe.base, rung: "models", verify_method: "models", latency_ms: r.ms, models_seen: models, attempts, vault: saved },
        0
      );
    }
    // A 401/403 on the models list is already the answer — no reason to spend a
    // completion to be told the same thing.
    if (r.status === 401 || r.status === 403)
      return finish(
        { ok: false, profile: name, engine: prof.engine, base_url: probe.base, reason: "auth-failed", rung: "models", status: r.status, error: extraErrText(r), attempts },
        1
      );
  }

  // ── rung 2: a max_tokens:1 completion ───────────────────────────────────
  const model = modelArg || models[0] || EXTRA_PROBE_UNKNOWN_MODEL;
  const isProbeName = model === EXTRA_PROBE_UNKNOWN_MODEL;
  const url = extraProbeCompletionsUrl(prof, probe);
  // `--live` sends a REAL message and reads the reply back; the ordinary rung
  // still spends one token. The prompt is a FIXED CONSTANT in both cases — never
  // task text, never anything a slice supplied.
  const body = {
    model,
    max_tokens: live ? 32 : 1,
    messages: [{ role: "user", content: live ? EXTRA_LIVE_PROMPT : "hi" }],
  };
  const r2 = await extraHttp({ url, method: "POST", headers, body, timeoutMs: extraProbeMs(live ? 60000 : 20000) });
  attempts.push({ rung: "completion", url, status: r2.status || null, ok: !!r2.ok, ms: r2.ms || null, error: r2.ok ? null : extraErrText(r2) });

  if (r2.ok) {
    const reported = (r2.json && r2.json.model) || null;
    prof.verified_at = new Date().toISOString();
    prof.verify_method = modelArg ? "manual" : "completion";
    prof.verify_base_url = probe.base;
    prof.verify_credential_source = cred.source;
    prof.latency_ms = r2.ms;
    if (models.length) prof.models_seen = models;
    else if (reported && !prof.models_seen.includes(reported)) prof.models_seen = prof.models_seen.concat(reported);
    else if (modelArg && !prof.models_seen.includes(modelArg)) prof.models_seen = prof.models_seen.concat(modelArg);
    if (live) prof.verify_method = "live";
    extraHistory(ledger, "ping", { profile: name, method: prof.verify_method });
    writeExtra(claudeDir, ledger);
    const saved = maybeStorePendingKey(claudeDir, ledger, prof, pending, pendingPass, asJson);
    const excerpt = live ? extraReplyText(r2.json) : null;
    return finish(
      Object.assign(
        {
          ok: true,
          profile: name,
          engine: prof.engine,
          base_url: probe.base,
          rung: live ? "live" : "completion",
          verify_method: prof.verify_method,
          latency_ms: r2.ms,
          model_requested: model,
          model_reported: reported,
          // An `api` endpoint DOES report which model answered, and that
          // difference from the local tools is worth carrying explicitly rather
          // than leaving a reader to infer it from a null.
          reports_model: true,
          models_seen: prof.models_seen,
          attempts,
          vault: saved,
        },
        live
          ? {
              reply_excerpt: excerpt ? excerpt.slice(0, EXTRA_LIVE_EXCERPT_MAX) : null,
              reply_truncated: !!(excerpt && excerpt.length > EXTRA_LIVE_EXCERPT_MAX),
              foreign_input: EXTRA_FOREIGN_REPLY_NOTE,
              // Four kinds, never blended (/orc-budget) — and NULL when the
              // endpoint reported nothing, never four zeros.
              tokens: r2.json && r2.json.usage ? extraApiUsageVector(r2.json.usage) : null,
              cost_note: EXTRA_LIVE_COST_API,
            }
          : {}
      ),
      0
    );
  }

  // THE ESCAPE FROM THE CHICKEN-AND-EGG: a 400/404 that rejects the MODEL NAME
  // still proves the URL and the credential, because the endpoint had to
  // authenticate before it could reject anything. Recorded as its own method —
  // it is weaker evidence than a real completion and must never read the same.
  //
  // v0.53.3 — AND IT HAS TO BE ABOUT THE MODEL. A 404 from a wrong URL and a 404
  // from an unknown model id are the same status code and nothing else about
  // them is the same: the first authenticated nothing, because there was no
  // endpoint there to authenticate. Reading one as the other is how a profile
  // earns a green badge against a path that does not exist, which is the whole
  // family of failure this release is closing. `extraErrAboutModel` is the
  // guard, and when it says no the ping FAILS — honestly — instead of verifying.
  if (isProbeName && (r2.status === 400 || r2.status === 404 || r2.status === 422) && extraErrAboutModel(r2, model)) {
    prof.verified_at = new Date().toISOString();
    prof.verify_method = "completion-unknown-model";
    prof.verify_base_url = probe.base;
    prof.verify_credential_source = cred.source;
    prof.latency_ms = r2.ms;
    extraHistory(ledger, "ping", { profile: name, method: "completion-unknown-model" });
    writeExtra(claudeDir, ledger);
    const saved = maybeStorePendingKey(claudeDir, ledger, prof, pending, pendingPass, asJson);
    return finish(
      {
        ok: true,
        profile: name,
        engine: prof.engine,
        base_url: probe.base,
        rung: "completion",
        verify_method: "completion-unknown-model",
        latency_ms: r2.ms,
        models_seen: prof.models_seen,
        attempts,
        vault: saved,
        note: "the endpoint authenticated and then rejected a model name ORC made up — the URL and the credential work, but NO model id is confirmed. Give one with --model, or route only after `orc extra models` has something in it.",
      },
      0
    );
  }

  // Failed. `finish` performs the reset — see the comment there.
  return finish(
    {
      ok: false,
      profile: name,
      engine: prof.engine,
      base_url: probe.base,
      reason: r2.status === 401 || r2.status === 403 ? "auth-failed" : r2.reason || "unreachable",
      rung: "completion",
      status: r2.status || null,
      error: extraErrText(r2),
      model_requested: model,
      attempts,
    },
    1
  );
}


// ═══════════════════════════════════════════════════════════════════════════
// W2 (v0.51.0) — THE ENGINE-`cli` LADDER
//
// The old engine-`cli` probe returned after ONE check — is the binary on PATH —
// and said so honestly: "the binary exists; nothing about a model or a
// credential has been proven." Honest, and useless: `models_seen` stayed empty
// forever, so the routing model box had nothing to offer and the user hand-typed
// a `provider/model` string they had to go and find somewhere else.
//
//   rung 0  refusal   not on PATH → the install command, and the install-free
//                     alternative when one exists (null MEANS there is none)
//   rung 1  cli-bin   on PATH, and `--version` above the floor
//   rung 2  cli-auth  the tool's own credential command answered
//   rung 3  cli-models the tool's own model list → models_seen
//   rung 4  cli-live  a real message to a real model            COSTS MONEY
//
// Rungs 1-3 are FREE and always run. Rung 4 is `--live` only.
//
// EVERY RUNG RUNS WITH ORC'S KEY IN THE CHILD'S ENVIRONMENT. Without that,
// rung 3 lists whatever the user happened to log into the tool with rather than
// what ORC's key can actually reach — and the account-scoped dropdown is the
// entire point of reading a live list.
//
// A rung that fails does NOT erase the rungs below it: `verify_method` is the
// strongest rung that answered, and the return says plainly what the ones above
// it did not prove.
// ═══════════════════════════════════════════════════════════════════════════

function extraPingCli(ctx) {
  const { claudeDir, ledger, prof, cat, cfg, name, live, modelArg, finish, key, key_error, credSource, pending, pendingPass, asJson } =
    ctx;
  const row = catalogRow(cat, prof.provider) || {};
  const bin = (prof.cli && prof.cli.bin) || row.cli_bin || null;
  const adapter = (bin && EXTRA_CLI_ADAPTERS[bin]) || null;
  const attempts = [];
  const found = bin ? whichBin(bin) : null;

  // ── rung 0: the refusal ─────────────────────────────────────────────────
  // Not a failure to connect — a failure to have anything to connect TO. It
  // names the install command and, where one exists, the route that needs no
  // install at all.
  if (!found) {
    const inst = row.cli_bin ? extraInstallView(row) : null;
    const cmds = inst ? (inst.cmds.length ? inst.cmds : inst.all_cmds) : [];
    attempts.push({ rung: "cli-bin", ok: false, error: `\`${bin || "(none)"}\` is not on PATH` });
    return finish(
      {
        ok: false,
        profile: name,
        engine: "cli",
        reason: "not-installed",
        rung: "cli-bin",
        bin,
        error: `"${bin || "(no binary configured)"}" is not on PATH — engine \`cli\` dispatches by running it, so there is nothing here to authenticate and nothing to list.`,
        install: inst,
        install_cmd: cmds.length ? cmds[0].cmd : null,
        install_cmds: cmds,
        // `null` MEANS THERE IS NONE, never that ORC forgot to look.
        no_install_alternative: row.no_install_alternative === undefined ? null : row.no_install_alternative,
        attempts,
      },
      1
    );
  }

  // The credential goes into the CHILD'S ENVIRONMENT and nowhere else — never
  // into argv, and never into the tool's own credential store (D8). A profile
  // whose key lives with the tool passes `key: null` and every rung below still
  // runs; the tool authenticates itself.
  const credRow = row.credential || {};
  const env = {};
  if (key) {
    if (credRow.env_var) env[credRow.env_var] = key;
    const kn = (prof.credential || {}).key_name;
    if (kn) env[kn] = key;
  }

  // ── rung 1: cli-bin ─────────────────────────────────────────────────────
  let version = null;
  let versionRaw = null;
  if (row.version_cmd) {
    const v = runToolCmd(found, row.version_cmd, env);
    versionRaw = (v.stdout.trim() || v.stderr.trim() || "").split(/\r?\n/)[0] || null;
    version = parseVersion(v.stdout + "\n" + v.stderr);
    attempts.push({ rung: "cli-bin", ok: true, cmd: row.version_cmd.join(" "), version, raw: versionRaw });
  } else {
    attempts.push({ rung: "cli-bin", ok: true, path: found });
  }
  // R2 — the flag rename that broke every opencode dispatch happened once
  // already, so the floor is a VERSION rather than a hard-coded flag. An
  // unparseable version is not a version below the floor.
  if (version && row.min_version && cmpVersion(version, row.min_version) < 0)
    return finish(
      {
        ok: false,
        profile: name,
        engine: "cli",
        reason: "too-old",
        rung: "cli-bin",
        bin: found,
        cli_version: version,
        min_version: row.min_version,
        error: `\`${bin}\` reports ${version} and ORC needs at least ${row.min_version} — an older build takes different flags, and the failure would look like a model problem instead of a version one.`,
        install: extraInstallView(row),
        attempts,
      },
      1
    );

  // The version is stored on the profile, because it is what picks the
  // permission flag at dispatch time (W7).
  prof.cli = Object.assign({}, prof.cli, { version, version_raw: versionRaw });

  let method = "cli-bin";
  let authed = null;
  let authDetail = null;
  let models = [];

  // ── rung 2: cli-auth ────────────────────────────────────────────────────
  if (row.auth_cmd) {
    const a = runToolCmd(found, row.auth_cmd, env);
    const text = (a.stdout + "\n" + a.stderr).trim();
    authed = a.code === 0 && !/not logged in|no credentials|logged out|not authenticated/i.test(text);
    authDetail = text.split(/\r?\n/).filter(Boolean).slice(0, 4).join(" · ") || null;
    attempts.push({
      rung: "cli-auth",
      ok: !!authed,
      cmd: row.auth_cmd.join(" "),
      detail: authDetail,
      error: authed ? null : "the tool reports no usable credential",
    });
    if (authed) method = "cli-auth";
  }

  // ── rung 3: cli-models ──────────────────────────────────────────────────
  if (row.models_cmd) {
    const m = runToolCmd(found, row.models_cmd, env);
    models = m.code === 0 ? extraParseModelList(m.stdout) : [];
    attempts.push({
      rung: "cli-models",
      ok: models.length > 0,
      cmd: row.models_cmd.join(" "),
      count: models.length,
      error: models.length
        ? null
        : m.timed_out
          ? "the model list did not answer in time"
          : extraCliClassify(m.stderr, m.stdout) === "unknown"
            ? "the tool listed no model ORC could read"
            : extraCliClassify(m.stderr, m.stdout),
    });
    if (models.length) {
      method = "cli-models";
      prof.models_seen = models;
    }
  }

  // ── rung 4: cli-live — REAL MONEY ───────────────────────────────────────
  let liveResult = null;
  if (live) {
    const wanted = modelArg || models[0] || null;
    if (!wanted)
      return finish(
        {
          ok: false,
          profile: name,
          engine: "cli",
          reason: "no-model",
          rung: "cli-live",
          bin: found,
          cli_version: version,
          models_seen: models,
          error:
            "a live test needs a model id and none is known: the model list came back empty, and no --model was given. Pass one, or fix the credential first.",
          attempts,
        },
        1
      );
    liveResult = extraCliLiveProbe({ adapter, bin: found, prof, row, model: wanted, env, version, cfg, claudeDir });
    attempts.push({
      rung: "cli-live",
      ok: !!liveResult.ok,
      cmd: liveResult.cmd,
      ms: liveResult.latency_ms,
      error: liveResult.ok ? null : liveResult.error,
    });
    if (liveResult.ok) {
      method = "cli-live";
      if (!models.includes(wanted)) {
        models = models.concat(wanted);
        prof.models_seen = models;
      }
    }
  }

  const ok = !live || !!(liveResult && liveResult.ok);
  if (ok) {
    prof.verified_at = new Date().toISOString();
    prof.verify_method = method;
    prof.verify_base_url = found;
    prof.verify_credential_source = credSource || null;
    prof.latency_ms = liveResult ? liveResult.latency_ms : null;
    extraHistory(ledger, "ping", { profile: name, method, models: models.length });
    writeExtra(claudeDir, ledger);
  }
  const saved = ok ? maybeStorePendingKey(claudeDir, ledger, prof, pending, pendingPass, asJson) : null;

  // What each rung did NOT prove, said out loud. A ladder whose top rung was
  // never climbed must never read like one that was.
  const notes = [];
  if (method === "cli-bin")
    notes.push(
      "the binary exists and nothing else has been proven: no credential, no model list, no working call."
    );
  if (authed === false)
    notes.push("the tool reports no credential of its own — ORC will inject the key it holds, but nothing has confirmed that key yet.");
  if (key_error && !key) notes.push(key_error);
  if (row.models_cmd && !models.length)
    notes.push("no model list came back, so there is nothing to pick from yet and a route here still needs a hand-typed id.");
  if (!live && models.length)
    notes.push(
      "a model being LISTED is not a model that WORKS — a listed id can be dead upstream. `orc extra models " +
        name +
        " --test <id>` is the only thing that tells those two apart."
    );

  return finish(
    Object.assign(
      {
        ok,
        profile: name,
        engine: "cli",
        rung: method,
        verify_method: method,
        bin: found,
        cli_version: version,
        cli_version_raw: versionRaw,
        min_version: row.min_version || null,
        authed,
        auth_detail: authDetail,
        models_seen: models,
        // F6/F14c — NEITHER shipped tool reports which model answered, so a
        // substitution is invisible on this engine. `reports_model: false` is
        // the record of that, and every renderer prints the sentence rather
        // than leaving a blank field.
        reports_model: !!(adapter && adapter.supports && adapter.supports.reports_model),
        attempts,
        vault: saved,
        note: notes.length ? notes.join(" ") : null,
      },
      liveResult
        ? {
            latency_ms: liveResult.latency_ms,
            model_requested: liveResult.model_requested,
            model_reported: liveResult.model_reported,
            reply_excerpt: liveResult.reply_excerpt,
            reply_truncated: liveResult.reply_truncated,
            foreign_input: EXTRA_FOREIGN_REPLY_NOTE,
            tokens: liveResult.tokens,
            usage_kinds: (adapter && adapter.supports && adapter.supports.usage_kinds) || null,
            cost_note: EXTRA_LIVE_COST_CLI,
            error: liveResult.ok ? null : liveResult.error,
            reason: liveResult.ok ? undefined : liveResult.reason,
          }
        : {}
    ),
    ok ? 0 : 1
  );
}

// ONE real call to ONE real model, in a SCRATCH DIRECTORY with the most
// restrictive sandbox the tool offers, carrying a fixed constant prompt. It is
// the only thing that tells a LISTED model from a WORKING one.
function extraCliLiveProbe(a) {
  const { adapter, bin, model, env, version } = a;
  if (!adapter || !adapter.probeArgv)
    return { ok: false, reason: "no-adapter", error: `ORC has no live-probe recipe for \`${bin}\`.`, cmd: null, latency_ms: null };
  let scratch = null;
  try {
    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "orc-extra-probe-"));
  } catch (e) {
    return { ok: false, reason: "scratch-failed", error: String((e && e.message) || e), cmd: null, latency_ms: null };
  }
  const argv = adapter.probeArgv({ model, dir: scratch, prompt: EXTRA_LIVE_PROMPT, version });
  const started = Date.now();
  const r = runToolCmd(bin, argv, env, EXTRA_LIVE_TIMEOUT_MS);
  const ms = Date.now() - started;
  let parsed = null;
  try {
    parsed = adapter.parse({ stdout: r.stdout, stderr: r.stderr, lastMessage: null });
  } catch (_) {}
  try {
    fs.rmSync(scratch, { recursive: true, force: true });
  } catch (_) {}

  // F3, MADE LEGIBLE. An exit whose output is the tool's own help text is a FLAG
  // problem, not a model problem — that exact failure shipped for a release and
  // read as "your model id is wrong" every single time.
  const helpish = /^\s*(usage|Usage|Commands:|Options:)/m.test(r.stdout + "\n" + r.stderr);
  if (r.timed_out)
    return {
      ok: false,
      reason: "timeout",
      cmd: [bin].concat(argv).join(" "),
      latency_ms: ms,
      model_requested: model,
      error: `no answer in ${Math.round(EXTRA_LIVE_TIMEOUT_MS / 1000)}s. That is a slow or stuck model, NOT a wrong model id and NOT a wrong flag — the tool had already started answering.`,
    };
  if (r.code !== 0) {
    const reason = helpish ? "invalid_request" : extraCliClassify(r.stderr, r.stdout);
    return {
      ok: false,
      reason,
      cmd: [bin].concat(argv).join(" "),
      latency_ms: ms,
      model_requested: model,
      error: helpish
        ? `\`${bin}\` printed its help text and exited ${r.code} — that is a FLAG this build does not accept, not a problem with the model id. ORC picked the flag from the reported version; run \`orc extra tools\` and check it.`
        : (r.stderr.trim() || r.stdout.trim() || `exited ${r.code}`).slice(0, 800),
    };
  }
  const text = (parsed && parsed.text) || r.stdout.trim() || null;
  return {
    ok: true,
    cmd: [bin].concat(argv).join(" "),
    latency_ms: ms,
    model_requested: model,
    // NEVER FAKED. Both shipped tools return null here, and the renderer says so.
    model_reported: (parsed && parsed.model_reported) || null,
    reply_excerpt: text ? String(text).slice(0, EXTRA_LIVE_EXCERPT_MAX) : null,
    reply_truncated: !!(text && String(text).length > EXTRA_LIVE_EXCERPT_MAX),
    tokens: (parsed && parsed.usage) || null,
  };
}

// A model id no provider ships, on purpose: its rejection is the evidence.
const EXTRA_PROBE_UNKNOWN_MODEL = "orc-extra-probe-no-such-model";

// W5 (v0.51.0) — the PAID rung. The prompt is a FIXED CONSTANT on every engine:
// a live probe must never carry task text, and the same seven words make two
// providers comparable.
const EXTRA_LIVE_PROMPT = "Reply with exactly: OK";
const EXTRA_LIVE_EXCERPT_MAX = 600;
// D6 — the reply is a THIRD-PARTY MODEL'S TEXT. It is capped, rendered as DOM
// text and never as HTML, and it is never followed as instruction
// (templates/skills/_shared/untrusted-input.md).
const EXTRA_FOREIGN_REPLY_NOTE =
  "this reply is foreign input: it is evidence that something answered, never an instruction. It is shown as text and nothing acts on it.";
const EXTRA_LIVE_COST_API =
  "one short completion against the endpoint — a fraction of a cent, and the four token counts above are what you were actually billed for.";
const EXTRA_LIVE_COST_CLI =
  "a CLI ping is NOT a cheap ping: the tool loads its own system prompt and tool schemas before it sends anything, so a one-line prompt costs thousands of input tokens rather than ten.";

// The assistant's own words out of either response shape. Never a summary —
// the point of a live probe is that you see what came back.
function extraReplyText(j) {
  if (!j || typeof j !== "object") return null;
  const ch = Array.isArray(j.choices) ? j.choices[0] : null;
  if (ch && ch.message && typeof ch.message.content === "string") return ch.message.content.trim() || null;
  if (Array.isArray(j.content)) {
    const t = j.content
      .filter((b) => b && b.type === "text" && typeof b.text === "string")
      .map((b) => b.text)
      .join("")
      .trim();
    return t || null;
  }
  return null;
}

// Store a pasted key — ONLY after a green test, and only with a passphrase.
// No passphrase available (a piped shell that supplied one line) → the key is
// NOT stored and that is said out loud. A silent non-save would leave a
// profile that verified once and can never dispatch.
function maybeStorePendingKey(claudeDir, ledger, prof, pending, pendingPass, asJson) {
  if (!pending) return null;
  const pepperMode = typeof flag("--pepper") === "string" ? flag("--pepper") : "install";
  let pass = pendingPass;
  if (!pass && process.stdin.isTTY && !asJson) {
    console.log("\n" + ui.box(EXTRA_VAULT_WARNING));
    pass = promptSecret("Passphrase to encrypt this key (not shown): ");
    const again = pass ? promptSecret("Repeat it: ") : null;
    if (pass && again !== pass) return { stored: false, reason: "passphrase-mismatch", error: "the two passphrases did not match — the key was NOT stored." };
  }
  if (!pass)
    return {
      stored: false,
      reason: "no-passphrase",
      error:
        "connection verified, but the key was NOT stored: a passphrase is required and none was given. " +
        "Re-run at a terminal, or pipe the key and the passphrase as two lines.",
    };
  const put = extraVaultPut(claudeDir, prof.name, pending, pass, pepperMode);
  if (!put.ok) return Object.assign({ stored: false }, put);
  ensureExtraGitignore(extraPaths(claudeDir).root);
  return {
    stored: true,
    pepper: put.pepper,
    pepper_path: put.pepper_path,
    pepper_created: put.pepper_created,
    honesty: EXTRA_VAULT_HONESTY,
  };
}

// ── orc extra health — DOES THIS MODEL STALL? (v0.56.1) ────────────────────
//
// `orc extra ping --live` answers "did something come back". It cannot answer
// the question a stall raises, which is "what was it DOING for those fifteen
// minutes" — because a synchronous probe has no view of the child while it
// runs, exactly the blindness runCliChild was built to remove.
//
// So health is the live probe run through THE SAME WATCHDOG A DISPATCH USES.
// That matters: it is not a second idea of the path (the v0.53.3 rule — a green
// badge must be earned by the path a wave actually runs), it is the dispatch's
// own observer pointed at a one-line prompt. What it reports is a TIMELINE:
// when the first byte arrived, the longest silence, and whether it ended by
// answering, by stalling, or by running out of wall clock.
//
// Exit codes: 0 answered · 1 stalled or failed · 2 unknown profile.
async function extraHealth(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir) || emptyExtra();
  const cfg = resolvedConfig(claudeDir);
  const prof = extraProfile(ledger, name);
  const fail = (reason, error, code) => {
    if (asJson)
      console.log(JSON.stringify({ ok: false, command: "extra health", profile: name || null, reason, error }, null, 2));
    else console.error(`❌ ${error}`);
    process.exit(code);
  };
  if (!prof)
    return fail(
      "unknown-profile",
      name ? `no profile called "${name}". \`orc extra list\` has the names.` : "usage: orc extra health <profile> [--model <id>]",
      2
    );
  if (prof.engine !== "cli")
    return fail(
      "engine-unsupported",
      "`orc extra health` measures the STALL clock, and that clock only exists on engine `cli` — engine `" +
        prof.engine +
        "` has a per-request inactivity timeout on its own socket, which `orc extra ping " +
        prof.name +
        " --live` already exercises.",
      1
    );

  const cat = readCatalog();
  const row = catalogRow(cat, prof.provider) || {};
  const bin = (prof.cli && prof.cli.bin) || row.cli_bin || null;
  const adapter = (bin && EXTRA_CLI_ADAPTERS[bin]) || null;
  const found = bin ? whichBin(bin) : null;
  if (!adapter || !found)
    return fail(
      "engine-unavailable",
      "`" + (bin || "(no binary configured)") + "` is not on PATH, or ORC ships no adapter for it.",
      1
    );

  const modelArg = flag("--model");
  const model = typeof modelArg === "string" ? modelArg : prof.default_model || (prof.models_seen || [])[0] || null;
  if (!model)
    return fail(
      "no-model",
      `no model to probe. Name one: \`orc extra health ${prof.name} --model <id>\` (\`orc extra models ${prof.name}\` lists what the provider offers).`,
      1
    );

  // The credential goes into the CHILD'S ENVIRONMENT and nowhere else, exactly
  // as a dispatch does it. A tool that holds its own key gets nothing and still
  // authenticates.
  const cred = extraCredentialValue(claudeDir, prof, { ambientKey: process.env.ORC_EXTRA_KEY || null });
  const env = {};
  if (cred.ok && cred.value) {
    const credRow = row.credential || {};
    if (credRow.env_var) env[credRow.env_var] = cred.value;
    const kn = (prof.credential || {}).key_name;
    if (kn) env[kn] = cred.value;
  }

  const timeouts = extraTimeouts(cfg);
  let scratch = null;
  try {
    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "orc-extra-health-"));
  } catch (e) {
    return fail("scratch-failed", String((e && e.message) || e), 1);
  }
  let version = null;
  if (row.version_cmd) {
    const v = runToolCmd(found, row.version_cmd, env);
    version = parseVersion(v.stdout + "\n" + v.stderr);
  }
  const argv = adapter.probeArgv({ model, dir: scratch, prompt: EXTRA_LIVE_PROMPT, version });
  const started = Date.now();
  const r = await runCliChild(
    found,
    argv,
    { cwd: scratch, env: Object.assign({}, process.env, env), windowsHide: true, stdio: ["ignore", "pipe", "pipe"] },
    { started, wall_ms: timeouts.wall_ms, stall_ms: timeouts.stall_ms, progressFile: null, root: scratch, declared: [] }
  );
  const total = Date.now() - started;
  let parsed = null;
  try {
    parsed = adapter.parse({ stdout: r.stdout || "", stderr: r.stderr || "", lastMessage: null });
  } catch (_) {}
  try {
    fs.rmSync(scratch, { recursive: true, force: true });
  } catch (_) {}

  const verdict =
    r.stopped_by === "stall"
      ? "stalled"
      : r.stopped_by === "wall"
        ? "timeout"
        : r.error
          ? "spawn-failed"
          : r.status === 0
            ? "answered"
            : "failed";
  const text = (parsed && parsed.text) || String(r.stdout || "").trim() || null;
  const out = {
    ok: verdict === "answered",
    command: "extra health",
    profile: prof.name,
    provider: prof.provider,
    engine: "cli",
    adapter: bin,
    model,
    verdict,
    exit_code: r.status,
    credential: { source: cred.source || null, ok: !!cred.ok },
    timeline: {
      total_ms: total,
      first_byte_ms: r.first_byte_ms,
      last_progress_ms: r.last_progress_ms,
      longest_gap_ms: r.longest_gap_ms,
      quiet_for_ms: r.stall_ms,
      stall_budget_ms: timeouts.stall_ms,
      wall_budget_ms: timeouts.wall_ms,
      stall_budget_clamped: !!timeouts.stall_clamped,
    },
    // WHAT IT WAS DOING — the bytes, capped, never interpreted. On engine `cli`
    // ORC did not compose the request and does not parse the tool's turns, so
    // this is the log and nothing more (`journal_fidelity: streamed-opaque`).
    log_excerpt: text ? String(text).slice(0, EXTRA_LIVE_EXCERPT_MAX) : null,
    log_truncated: !!(text && String(text).length > EXTRA_LIVE_EXCERPT_MAX),
    stderr_excerpt: String(r.stderr || "").trim().slice(0, EXTRA_LIVE_EXCERPT_MAX) || null,
    events: (parsed && parsed.events) || 0,
    tokens: (parsed && parsed.usage) || null,
    foreign_reply_note: EXTRA_FOREIGN_REPLY_NOTE,
    cost_note: EXTRA_LIVE_COST_CLI,
  };
  if (asJson) {
    console.log(JSON.stringify(out, null, 2));
    process.exit(out.ok ? 0 : 1);
  }
  const sec = (ms) => (ms === null || ms === undefined ? "—" : `${(ms / 1000).toFixed(1)}s`);
  console.log("");
  console.log(ui.color.bold(`ORC · extra — health · ${prof.name} · ${model}`));
  console.log("─".repeat(40));
  console.log("");
  const mark = out.ok ? ui.color.green("✔") : ui.color.red("✖");
  console.log(`  ${mark} ${verdict}${out.exit_code === null ? "" : ui.color.gray(`  exit ${out.exit_code}`)}`);
  console.log("");
  console.log(`  first byte        ${sec(out.timeline.first_byte_ms)}`);
  console.log(`  last progress     ${sec(out.timeline.last_progress_ms)}`);
  console.log(`  longest quiet gap ${sec(out.timeline.longest_gap_ms)}`);
  console.log(`  total             ${sec(out.timeline.total_ms)}`);
  console.log(
    `  stall budget      ${
      out.timeline.stall_budget_ms ? sec(out.timeline.stall_budget_ms) : ui.color.gray("off (extra_stall_s = 0)")
    }` + (out.timeline.stall_budget_clamped ? ui.color.yellow("  ← clamped under the wall clock") : "")
  );
  if (verdict === "stalled") {
    console.log("");
    console.log(
      ui.color.yellow(
        `  This model went quiet for ${sec(out.timeline.quiet_for_ms)} and was still running. In a wave\n` +
          "  that is a `stalled` dispatch: retryable, so `extra_resume` continues it from what\n" +
          "  is on disk rather than starting over."
      )
    );
  }
  if (out.log_excerpt) {
    console.log("");
    console.log(ui.color.gray("  what it said"));
    for (const line of out.log_excerpt.split(/\r?\n/).slice(0, 12)) console.log("    " + line);
    if (out.log_truncated) console.log(ui.color.gray("    …"));
    console.log("");
    console.log(ui.color.gray("  " + EXTRA_FOREIGN_REPLY_NOTE));
  } else if (out.stderr_excerpt) {
    console.log("");
    console.log(ui.color.gray("  stderr"));
    for (const line of out.stderr_excerpt.split(/\r?\n/).slice(0, 8)) console.log("    " + line);
  }
  console.log("");
  console.log(ui.color.gray("  " + EXTRA_LIVE_COST_CLI));
  process.exit(out.ok ? 0 : 1);
}

function extraPingRender(res) {
  if (res.ok) {
    console.log(
      "\n" +
        ui.mark.ok(
          `${ui.color.cyan(res.profile)} verified via ${res.verify_method}` +
            (res.latency_ms ? ui.color.gray(`  ${res.latency_ms}ms`) : "")
        )
    );
    if (res.base_url) console.log(ui.color.gray(`  ${res.base_url}`));
    if (res.models_seen && res.models_seen.length)
      console.log(
        `\n  ${plural(res.models_seen.length, "model")}: ` +
          res.models_seen.slice(0, 8).join(", ") +
          (res.models_seen.length > 8 ? ", …" : "")
      );
    if (res.note) console.log("\n  " + ui.mark.warn(res.note));
    if (res.vault && res.vault.stored) {
      console.log("\n  " + ui.mark.ok(`key stored, encrypted (pepper: ${res.vault.pepper}).`));
      if (res.vault.pepper === "shipped")
        console.log(
          "  " +
            ui.mark.warn(
              "the `shipped` pepper is a constant inside the npm package — it is obfuscation, not a secret. Only your passphrase protects this key."
            )
        );
      if (res.vault.pepper_created)
        console.log(ui.color.gray(`  pepper written to ${res.vault.pepper_path} — losing that file loses the key.`));
      console.log(ui.color.gray("  " + EXTRA_VAULT_HONESTY));
    } else if (res.vault && res.vault.error) {
      console.log("\n  " + ui.mark.warn(res.vault.error));
    }
    console.log("");
    return;
  }
  console.log("\n" + ui.mark.bad(`${ui.color.cyan(res.profile)} — ${res.reason}`));
  if (res.error) console.log("  " + res.error);
  if (res.base_url) console.log(ui.color.gray(`  ${res.base_url}`));
  if (res.profile_reverted)
    console.log(
      "\n  " + ui.color.gray("the pasted key was discarded and the profile removed — nothing was written.")
    );
  console.log("");
}

// ── orc extra models — the cache, a live refresh, and a per-model live test ──
//
// The `pattern show` / `headered: false` precedent: with nothing cached this
// says so and returns an empty list. It never falls back to a shipped guess,
// because a guessed model id is a 404 in the middle of a wave.
//
// W4 (v0.51.0) adds the two things that make a DROPDOWN possible and honest:
//
//   --refresh        re-runs the free model-list rung and rewrites models_seen
//   --test <id>      the PAID rung, scoped to ONE id
//
// The second one exists because F5 is the whole argument: a model that is
// LISTED can still be DEAD. A dropdown is a list of what is OFFERED, never a
// list of what WORKS, and only a live call tells those two apart.
//
// `entry` is the CLI's answer to "dropdown or text box", and the panel renders
// it and derives nothing — the Flow-stepper rule (`steps[]`), applied to models.
async function extraModels(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  if (!prof) {
    const known = ledger ? ledger.profiles.map((x) => x.name) : [];
    if (asJson) emitJson({ ok: false, reason: "unknown-profile", profile: name || null, known }, 2);
    console.error(`❌ unknown profile "${name || ""}".`);
    process.exit(2);
  }
  const cfg = resolvedConfig(claudeDir);
  const cat = readCatalog();
  const row = catalogRow(cat, prof.provider) || {};
  const refresh = flag("--refresh") === true;
  const testId = typeof flag("--test") === "string" ? flag("--test") : null;
  const passStdin = args.includes("--passphrase-stdin");
  const adapter = ((prof.cli && prof.cli.bin) || row.cli_bin) ? EXTRA_CLI_ADAPTERS[(prof.cli && prof.cli.bin) || row.cli_bin] : null;

  // A vaulted profile needs its key for either of the live paths, and it is
  // unlocked into MEMORY for that and nothing else — the same counter, the same
  // rule as `orc extra ping --passphrase-stdin`.
  let key = null;
  let keyError = null;
  if (refresh || testId) {
    const pass = passStdin ? (process.stdin.isTTY ? promptSecret(`Passphrase for "${name}" (not shown): `) : (readStdinLines()[0] || "").trim()) : null;
    const cred = extraCredentialValue(claudeDir, prof, { passphrase: pass, maxAttempts: cfg.extra_vault_max_attempts });
    if (cred.ok) key = cred.value;
    else keyError = cred.error || cred.reason;
  }

  let refreshed = null;
  let tested = null;
  if (refresh) {
    refreshed = await extraRefreshModels({ claudeDir, prof, row, key, cat });
    if (refreshed.ok) {
      prof.models_seen = refreshed.models;
      prof.models_refreshed_at = new Date().toISOString();
      extraHistory(ledger, "models-refresh", { profile: name, count: refreshed.models.length });
      writeExtra(claudeDir, ledger);
    }
  }
  if (testId) {
    tested = await extraTestModel({ claudeDir, prof, row, adapter, key, cat, model: testId, cfg });
  }

  const models = Array.isArray(prof.models_seen) ? prof.models_seen : [];
  const v = extraVerifyState(prof, cfg);
  const rows = models.map((id) => extraModelView(id, prof));
  // `custom` is the escape hatch that keeps the catalog from being a gate, and a
  // list that came back empty is not a list. Both are FREE TEXT — the panel must
  // never offer a dropdown that cannot contain the answer.
  const entry = prof.provider === "custom" || !models.length ? "free-text" : "list";
  const refreshedAt = prof.models_refreshed_at || prof.verified_at || null;
  const staleDays = refreshedAt && !isNaN(Date.parse(refreshedAt)) ? Math.floor((Date.now() - Date.parse(refreshedAt)) / 86400000) : null;

  const payload = {
    ok: true,
    profile: name,
    provider: prof.provider,
    engine: prof.engine,
    entry,
    source: refreshed && refreshed.ok ? refreshed.source : models.length ? "cached from the last ping" : null,
    refreshed_at: refreshedAt,
    stale_days: staleDays,
    models: rows,
    // The plain id list, kept for every caller that already reads it.
    model_ids: models,
    // F6/F14c — neither local tool reports which model answered, so a
    // substitution is invisible on that engine. Carried here so a renderer that
    // is about to draw a dropdown can say so beside it.
    reports_model: prof.engine === "cli" ? !!(adapter && adapter.supports && adapter.supports.reports_model) : true,
    verified_at: prof.verified_at,
    verify_method: prof.verify_method,
    verify_state: v.state,
    verify_age_days: v.age_days,
    key_error: keyError,
    refresh: refreshed,
    test: tested,
    // F5, said out loud beside every list: OFFERED is not WORKING.
    caveat:
      "this is what the provider OFFERS. A listed id can still be dead upstream — `orc extra models " +
      name +
      " --test <id>` is the only thing that tells those two apart.",
    hint: models.length ? null : "no model has been read from this provider yet — run `orc extra ping " + name + "` or `orc extra models " + name + " --refresh`.",
  };
  if (asJson) emitJson(payload, 0);

  if (refreshed && !refreshed.ok) console.log("\n  " + ui.mark.warn(refreshed.error));
  if (!rows.length) {
    console.log(`\nNo models cached for ${name}. ORC never ships a model list — run \`orc extra ping ${name}\`.\n`);
  } else {
    console.log(ui.header(`ORC · extra — ${name} · ${plural(rows.length, "model")}`));
    console.log("\n" + rows.map((m) => `  ${m.label}${m.group ? ui.color.gray(`  (${m.group})`) : ""}`).join("\n"));
    console.log(
      ui.color.gray(
        `\n  ${payload.source || "cached"}${refreshedAt ? ` at ${refreshedAt}` : ""}` +
          (v.state === "STALE" ? `  (${v.age_days}d old — STALE, still routes)` : "")
      )
    );
    console.log("  " + ui.color.gray(payload.caveat));
  }
  if (tested) {
    console.log("");
    if (tested.ok) {
      console.log("  " + ui.mark.ok(`${testId} answered in ${tested.latency_ms}ms`));
      if (tested.reply_excerpt) console.log(ui.color.gray("  reply: " + tested.reply_excerpt.split(/\r?\n/)[0]));
      if (!tested.reports_model)
        console.log("  " + ui.color.gray("this tool does not report which model answered, so a substitution here would be invisible."));
    } else {
      console.log("  " + ui.mark.bad(`${testId} — ${tested.reason}`));
      if (tested.error) console.log("  " + tested.error);
    }
  }
  console.log("");
}

// One model id, viewed. `group` is the CLI's answer so a renderer can compose
// `glm-5 (opencode-go)` from data it was HANDED rather than by splitting a
// string it does not own.
function extraModelView(id, prof) {
  const s = String(id);
  const i = s.indexOf("/");
  return {
    id: s,
    label: i === -1 ? s : s.slice(i + 1),
    group: i === -1 ? prof.provider : s.slice(0, i),
    // A NAME HINT, never a price. ORC prices nothing it did not price itself
    // (/orc-budget), and several catalogues put the word in the id — so this
    // says what the NAME says and makes no claim about what you will be billed.
    name_says_free: /(^|[-_/.])free($|[-_/.])/i.test(s),
  };
}

// Re-run the FREE model-list rung for one profile. Engine `cli` asks the tool;
// everything else asks the endpoint. Either way ORC'S OWN KEY is in play, which
// is the whole point: a list read without it is whatever the user happened to
// log in with, not what this profile can actually reach.
async function extraRefreshModels(a) {
  const { claudeDir, prof, row, key, cat } = a;
  if (prof.engine === "cli") {
    const bin = (prof.cli && prof.cli.bin) || row.cli_bin || null;
    const found = bin ? whichBin(bin) : null;
    if (!found) return { ok: false, reason: "not-installed", error: `\`${bin || "(none)"}\` is not on PATH.`, models: [] };
    if (!row.models_cmd)
      return { ok: false, reason: "no-list-command", error: `ORC has no model-list command for \`${bin}\` in the catalog.`, models: [] };
    const env = {};
    if (key) {
      const credRow = row.credential || {};
      if (credRow.env_var) env[credRow.env_var] = key;
      const kn = (prof.credential || {}).key_name;
      if (kn) env[kn] = key;
    }
    const m = runToolCmd(found, row.models_cmd, env);
    const models = m.code === 0 ? extraParseModelList(m.stdout) : [];
    if (!models.length)
      return {
        ok: false,
        reason: m.timed_out ? "timeout" : "empty",
        error: m.timed_out ? "the model list did not answer in time." : (m.stderr.trim() || "the tool listed no model ORC could read.").slice(0, 400),
        models: [],
        source: bin + " " + row.models_cmd.join(" "),
      };
    return { ok: true, models, source: bin + " " + row.models_cmd.join(" ") };
  }
  if (!key) return { ok: false, reason: "no-credential", error: "no key is available for this profile.", models: [] };
  const probe = extraProbeBase(prof, cat);
  if (!probe.base) return { ok: false, reason: "no-base-url", error: "this profile has no base URL to ask.", models: [] };
  const url = joinUrl(probe.base, probe.models_path) + "?limit=1000";
  const r = await extraHttp({ url, headers: extraAuthHeaders(prof, key), timeoutMs: extraProbeMs(8000) });
  if (!r.ok || !r.json) return { ok: false, reason: "unreachable", error: extraErrText(r), models: [], source: url };
  const data = Array.isArray(r.json.data) ? r.json.data : Array.isArray(r.json.models) ? r.json.models : [];
  const models = data.map((m) => (typeof m === "string" ? m : m.id || m.name)).filter(Boolean);
  return { ok: !!models.length, models, source: url, error: models.length ? null : "the endpoint answered with no model ids." };
}

// F5's answer, scoped to ONE id: the paid rung for a single model, so a dead
// entry in a live list can be found before a wave finds it.
async function extraTestModel(a) {
  const { claudeDir, prof, row, adapter, key, cat, model, cfg } = a;
  if (prof.engine === "cli") {
    const bin = (prof.cli && prof.cli.bin) || row.cli_bin || null;
    const found = bin ? whichBin(bin) : null;
    if (!found) return { ok: false, reason: "not-installed", error: `\`${bin || "(none)"}\` is not on PATH.` };
    const env = {};
    if (key) {
      const credRow = row.credential || {};
      if (credRow.env_var) env[credRow.env_var] = key;
      const kn = (prof.credential || {}).key_name;
      if (kn) env[kn] = key;
    }
    const out = extraCliLiveProbe({
      adapter,
      bin: found,
      prof,
      row,
      model,
      env,
      version: (prof.cli && prof.cli.version) || null,
      cfg,
      claudeDir,
    });
    return Object.assign(
      {
        reports_model: !!(adapter && adapter.supports && adapter.supports.reports_model),
        foreign_input: EXTRA_FOREIGN_REPLY_NOTE,
        cost_note: EXTRA_LIVE_COST_CLI,
      },
      out
    );
  }
  if (!key) return { ok: false, reason: "no-credential", error: "no key is available for this profile." };
  const probe = extraProbeBase(prof, cat);
  if (!probe.base) return { ok: false, reason: "no-base-url", error: "this profile has no base URL to ask." };
  const url = extraProbeCompletionsUrl(prof, probe);
  const r = await extraHttp({
    url,
    method: "POST",
    headers: extraAuthHeaders(prof, key),
    body: { model, max_tokens: 32, messages: [{ role: "user", content: EXTRA_LIVE_PROMPT }] },
    timeoutMs: extraProbeMs(60000),
  });
  if (!r.ok)
    return {
      ok: false,
      reason: r.status === 401 || r.status === 403 ? "auth-failed" : r.reason || "model-unavailable",
      status: r.status || null,
      error: extraErrText(r),
      model_requested: model,
      latency_ms: r.ms || null,
    };
  const text = extraReplyText(r.json);
  return {
    ok: true,
    latency_ms: r.ms || null,
    model_requested: model,
    model_reported: (r.json && r.json.model) || null,
    reports_model: true,
    reply_excerpt: text ? text.slice(0, EXTRA_LIVE_EXCERPT_MAX) : null,
    reply_truncated: !!(text && text.length > EXTRA_LIVE_EXCERPT_MAX),
    foreign_input: EXTRA_FOREIGN_REPLY_NOTE,
    tokens: r.json && r.json.usage ? extraApiUsageVector(r.json.usage) : null,
    cost_note: EXTRA_LIVE_COST_API,
  };
}

// ── orc extra unlock — prove the passphrase, and NEVER print the key ───────
// This is the counter's home. It answers one question — does this passphrase
// open this record — and returns nothing that could be pasted anywhere.
function extraUnlock(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  if (!prof) {
    if (asJson) emitJson({ ok: false, reason: "unknown-profile", profile: name || null }, 2);
    console.error(`❌ unknown profile "${name || ""}".`);
    process.exit(2);
  }
  if ((prof.credential || {}).source !== "vault") {
    const msg = `"${name}" reads its key from the environment variable ${prof.credential.key_name} — there is nothing to unlock.`;
    if (asJson) emitJson({ ok: false, reason: "not-vaulted", profile: name, error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const cfg = resolvedConfig(claudeDir);
  const max = Number(cfg.extra_vault_max_attempts || EXTRA_VAULT_MAX_ATTEMPTS_DEFAULT);
  const pass = process.stdin.isTTY
    ? promptSecret(`Passphrase for "${name}" (not shown): `)
    : (readStdinLines()[0] || "").trim();
  if (!pass) {
    const msg = "no passphrase given.";
    if (asJson) emitJson({ ok: false, reason: "no-passphrase", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const got = extraVaultGet(claudeDir, prof.credential.key_name || name, pass, max);
  if (got.ok) {
    // The plaintext exists in this process for exactly as long as it takes to
    // decide it was correct. It is never returned, never printed, never logged.
    const out = { ok: true, profile: name, unlocked: true, attempts_used: 0, max, note: "the key is not printed and was not written anywhere." };
    if (asJson) emitJson(out, 0);
    console.log("\n" + ui.mark.ok(`"${name}" unlocked — the passphrase is correct.`));
    console.log(ui.color.gray("  The key was not printed and was not written anywhere.\n"));
    return;
  }
  if (asJson) emitJson(Object.assign({ ok: false, profile: name, honesty: EXTRA_VAULT_HONESTY }, got), 1);
  console.error("\n" + ui.mark.bad(got.error));
  console.error(ui.color.gray("  " + EXTRA_VAULT_HONESTY + "\n"));
  process.exit(1);
}

// ── orc extra rekey — an EXPLICIT passphrase change ────────────────────────
// No silent re-encryption and no passphrase change without the old one: both
// would be a second door into the vault.
function extraRekey(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  if (!prof || (prof.credential || {}).source !== "vault") {
    const msg = `"${name || ""}" has no vault record to rekey.`;
    if (asJson) emitJson({ ok: false, reason: "not-vaulted", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const cfg = resolvedConfig(claudeDir);
  const max = Number(cfg.extra_vault_max_attempts || EXTRA_VAULT_MAX_ATTEMPTS_DEFAULT);
  let oldPass, newPass;
  if (process.stdin.isTTY) {
    oldPass = promptSecret("Current passphrase (not shown): ");
    newPass = promptSecret("New passphrase (not shown): ");
    const again = promptSecret("Repeat the new one: ");
    if (newPass !== again) {
      console.error("❌ the two new passphrases did not match — nothing changed.");
      process.exit(1);
    }
  } else {
    const lines = readStdinLines();
    oldPass = (lines[0] || "").trim();
    newPass = (lines[1] || "").trim();
  }
  if (!oldPass || !newPass) {
    const msg = "rekey needs the current passphrase and a new one (two lines on stdin, or a terminal).";
    if (asJson) emitJson({ ok: false, reason: "no-passphrase", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const got = extraVaultGet(claudeDir, prof.credential.key_name || name, oldPass, max);
  if (!got.ok) {
    if (asJson) emitJson(Object.assign({ ok: false, profile: name }, got), 1);
    console.error("❌ " + got.error);
    process.exit(1);
  }
  const rec = readVault(claudeDir).records[prof.credential.key_name || name] || {};
  const put = extraVaultPut(claudeDir, prof.credential.key_name || name, got.value, newPass, rec.pepper || "install");
  if (!put.ok) {
    if (asJson) emitJson(Object.assign({ ok: false, profile: name }, put), 1);
    console.error("❌ " + put.error);
    process.exit(1);
  }
  if (asJson) emitJson({ ok: true, profile: name, rekeyed: true, pepper: put.pepper }, 0);
  console.log("\n" + ui.mark.ok(`"${name}" re-encrypted under the new passphrase.`));
  console.log(ui.color.gray("  " + EXTRA_VAULT_HONESTY + "\n"));
}

// Resolve a bare command name to an absolute path, without a shell. `spawn` on
// Windows cannot execute a .cmd/.bat without `shell: true`, and `shell: true`
// puts arbitrary task text through cmd.exe quoting — so the engines resolve the
// real file and run THAT.
function whichBin(bin) {
  const exts = process.platform === "win32" ? (process.env.PATHEXT || ".COM;.EXE;.BAT;.CMD").split(";") : [""];
  for (const dir of String(process.env.PATH || "").split(path.delimiter)) {
    if (!dir) continue;
    for (const ext of exts) {
      const p = path.join(dir, bin + ext.toLowerCase());
      const q = path.join(dir, bin + ext);
      for (const cand of [p, q]) {
        try {
          if (fs.statSync(cand).isFile()) return cand;
        } catch (_) {}
      }
    }
  }
  return null;
}

// ── The routing table ──────────────────────────────────────────────────────
//
// THE TABLE IS FLAT, AND A GAP MEANS CLAUDE. This is the one place the storage
// shape differs from how a human describes it ("DeepSeek: 0-30, 31-70"), and
// the reason is worth the paragraph:
//
//   A per-PROVIDER table forces every provider to tile 0-100. That makes two
//   providers impossible to express (adding GLM would silently un-route
//   DeepSeek) and makes "leave the top band on Claude" inexpressible at all.
//   One flat table of non-overlapping rows expresses both, and it turns the
//   resolver into a LOOKUP instead of a precedence puzzle.
//
// The panel still renders it per provider, because that is how a person thinks
// about it. The storage is flat because that is what keeps the answer honest.
//
// Bands are half-open `[from, to)` with the top row inclusive of 100, exactly
// like DIY_SCORE_TABLE's `101` convention — so the two tables can be compared
// without a translation step that could drift.

const EXTRA_BAND_RE = /^(\d{1,3})\s*-\s*(\d{1,3})$/;

function parseBand(spec) {
  const m = EXTRA_BAND_RE.exec(String(spec || "").trim());
  if (!m) return { err: `band must look like 0-30 or 70-100 (got "${spec}")` };
  const from = Number(m[1]);
  const to = Number(m[2]);
  if (from < 0 || to > 100) return { err: "a band lives inside 0-100" };
  if (to <= from) return { err: `"${spec}" is empty or backwards — the second number must be larger` };
  return { from, to };
}

const bandLabel = (r) => `[${r.from},${r.to >= 100 ? "100]" : r.to + ")"}`;
const bandCovers = (r, score) => score >= r.from && (r.to >= 100 ? score <= 100 : score < r.to);
const bandsOverlap = (a, b) => a.from < b.to && b.from < a.to;

// R17 — WHAT A BAND MEANS, IN WORDS, AND IT IS THE CLI'S ANSWER.
//
// `[0,30)` is developer notation and the half-open bracket is load-bearing, so
// it stays exactly as it is. But it is not a thing a first-time reader knows,
// and a routing table nobody can read is a routing table nobody sets. So every
// row carries a PLAIN reading of its own range and a sentence about what a score
// in it describes.
//
// IT IS COMPUTED HERE AND NOWHERE ELSE. Writing "simple work" beside `[0,30)`
// in the panel would be the panel deciding what a score means — the
// Flow-stepper rule, the computeWikiFreshness rule and the docPlanShape rule
// applied a fifth time. And it goes in BOTH surfaces: a field the human path
// prints and the JSON omits is drift no lint can see.
//
// Every phrase describes the SCORE FORMULA and never a model:
// `score = breadth + novelty + logic + test_surface + fan + uncertainty`
// (`effort-and-mode.md`), clamped 0..100, with a cited risk flooring it at 70.
// That is why the 70+ anchor names the risk floor — it is the one thing about a
// high band a reader cannot infer from the number.
const EXTRA_BAND_MEANINGS = [
  [0, 30, "mechanical work in one or two files, with no new logic"],
  [30, 55, "a few files, following a pattern this repo already has"],
  [55, 70, "several files, or a new surface, or logic that carries state"],
  [70, 85, "wide reach or genuinely new work (a cited risk floors a task to 70, so it lands here or above)"],
  [85, 101, "the hardest work: a novel algorithm, or wide reach with deep logic"],
];
// The half-open range, read out. Scores are integers (the formula sums integers
// and clamps), so `[0,30)` is exactly 0 to 29 — this is a translation of the
// notation, not an approximation of it.
function bandPlain(from, to) {
  const hi = to >= 100 ? 100 : to - 1;
  return from === hi ? `score ${from}` : `scores ${from} to ${hi}`;
}
function bandMeaning(from, to) {
  const top = to >= 100 ? 101 : to;
  const hit = EXTRA_BAND_MEANINGS.filter((m) => from < m[1] && m[0] < top);
  if (!hit.length) return null;
  if (hit.length === 1) return hit[0][2];
  // A user-set band can span several anchors. Naming the two ends is honest;
  // concatenating every phrase in between reads as a list of unrelated claims.
  return `${hit[0][2]} — ranging up to ${hit[hit.length - 1][2]}`;
}

// The Claude fall-through, expressed as rows. `orc extra route` ALWAYS prints
// these: a table that showed only the foreign bands would not be the routing
// table, it would be a list of exceptions to a table you cannot see.
function claudeGaps(routes, map) {
  const table = isTrue(map.opus5_only) ? OPUS5_SCORE_TABLE : DIY_SCORE_TABLE;
  const sorted = [...routes].sort((a, b) => a.from - b.from);
  const gaps = [];
  let at = 0;
  for (const r of sorted) {
    if (r.from > at) gaps.push({ from: at, to: r.from });
    at = Math.max(at, r.to);
  }
  if (at < 100) gaps.push({ from: at, to: 100 });
  // Split each gap at the Claude table's own edges, so a gap reads as the
  // agents it actually resolves to rather than as one undifferentiated slab.
  const out = [];
  for (const g of gaps) {
    for (const [lo, hi, agent] of table) {
      const from = Math.max(g.from, lo);
      const to = Math.min(g.to, hi === 101 ? 100 : hi);
      if (to > from || (to === from && to === 100))
        out.push({ from, to: hi === 101 ? 100 : to, via: "claude", agent });
    }
  }
  return out;
}

function extraRouteRows(claudeDir) {
  const ledger = readExtra(claudeDir) || emptyExtra();
  const { map } = readOverride(claudeDir);
  const cfg = resolvedConfig(claudeDir);
  const foreign = [...ledger.routes]
    .sort((a, b) => a.from - b.from)
    .map((r) => {
      const prof = extraProfile(ledger, r.profile);
      const v = prof ? extraVerifyState(prof, cfg) : { state: "MISSING", age_days: null };
      return {
        from: r.from,
        to: r.to,
        band: bandLabel(r),
        via: "extra",
        profile: r.profile,
        model: r.model,
        small_model: r.small_model || null,
        max_turns: r.max_turns === undefined ? null : r.max_turns,
        engine: prof ? prof.engine : null,
        provider: prof ? prof.provider : null,
        verify_state: v.state,
        // A routed model that is no longer in `models_seen` is an `orc extra
        // doctor` finding, not a mid-wave 404 nobody saw coming.
        model_known: prof ? (prof.models_seen || []).includes(r.model) : false,
      };
    });
  const gaps = claudeGaps(ledger.routes, map).map((g) =>
    Object.assign({ band: `[${g.from},${g.to >= 100 ? "100]" : g.to + ")"}` }, g)
  );
  // R17 — on EVERY row, foreign and Claude alike. A plain reading of the range
  // and what a score in it describes; see EXTRA_BAND_MEANINGS.
  const describe = (r) => Object.assign(r, { range: bandPlain(r.from, r.to), meaning: bandMeaning(r.from, r.to) });
  foreign.forEach(describe);
  gaps.forEach(describe);
  return { ledger, cfg, map, foreign, gaps, rows: [...foreign, ...gaps].sort((a, b) => a.from - b.from) };
}

function extraRouteList(claudeDir) {
  const asJson = wantsJson();
  const t = extraRouteRows(claudeDir);
  const enabled = isTrue(t.cfg.extra_enabled);
  if (asJson)
    emitJson(
      {
        ok: true,
        extra_enabled: enabled,
        claude_table: isTrue(t.map.opus5_only) ? "opus5_only" : t.map.rubric_bands_override ? "rubric_bands_override" : "default",
        rows: t.rows,
        foreign: t.foreign,
        claude_fallthrough: t.gaps,
        counts: { foreign: t.foreign.length, claude: t.gaps.length },
        // R17 — the anchors the per-row `meaning` is built from, so a reader can
        // see the whole ladder rather than only the rows they happen to have.
        band_meanings: EXTRA_BAND_MEANINGS.map(([from, to, meaning]) => ({ from, to: to >= 100 ? 100 : to, meaning })),
        note: enabled
          ? null
          : "extra_enabled is false — every row below is inert and every score resolves on the Claude ladder.",
      },
      0
    );
  console.log(ui.header("ORC · extra — the routing table"));
  if (!enabled)
    console.log(
      "\n  " +
        ui.mark.warn("extra_enabled is false — these rows are INERT. `orc config set extra_enabled true` arms them.")
    );
  console.log("");
  console.log(
    ui.kv(
      t.rows.map((r) =>
        r.via === "extra"
          ? [
              r.band,
              ui.color.cyan(`${r.profile}/${r.model}`),
              // R17 — the bracket read out, on the same line. It is in `--json`
              // too: a field one surface prints and the other omits is drift no
              // lint can see. `ui.kv` carries three columns, so it rides in the
              // third rather than becoming a fourth that is silently dropped.
              `${r.engine || "?"} · ${r.verify_state} · ${r.range}` + (r.model_known ? "" : ui.color.yellow("  · model not in models_seen")),
            ]
          : [r.band, ui.color.gray(r.agent), ui.color.gray("claude · " + r.range)]
      )
    )
  );
  // R17 — and what a score in each range describes. Printed once as a ladder
  // rather than repeated per row: the anchors do not change with your routes.
  console.log("\n  " + ui.color.bold("what a score in each range describes"));
  for (const [from, to, meaning] of EXTRA_BAND_MEANINGS)
    console.log("    " + ui.color.gray(bandPlain(from, to).padEnd(18)) + ui.color.gray(meaning));
  console.log(
    ui.color.gray(
      "\n  A gap is not a hole — it is Claude, and it is printed so \"I left the top band\n" +
        "  on Opus on purpose\" and \"there is no top band\" can never look the same.\n"
    )
  );

// v0.52.0 (D6) — the SAME table `orc extra lanes` prints, under the bands, so
// the terminal and the panel say the identical thing. A band with no lane
// attached is not a routing decision, and this is the shortest place to see
// which lane each row above actually governs.
  extraLanesBrief(claudeDir);
}

// The lane verdicts, in one line each. Used by `orc extra route list`; the full
// answer with both edges is `orc extra lanes`.
function extraLanesBrief(claudeDir) {
  const cfg = resolvedConfig(claudeDir);
  if (!isTrue(cfg.extra_enabled)) return;
  const roles = INLINE_LIST(cfg.extra_roles).filter(Boolean);
  console.log(ui.color.bold("  which lane routes foreign, and how"));
  for (const row of EXTRA_LANE_SHAPES) {
    let verdict = "claude";
    let extra = "";
    if (row.shape === "never" || row.shape === "inert") verdict = "never";
    else if (row.shape === "scored") verdict = roles.includes("executor") ? "per-task" : "claude";
    else if (row.shape === "slot" || row.shape === "gated-choice") {
      const on = (row.slots || []).filter((slot) => extraResolveSlot(claudeDir, slot, {}).resolved === "extra");
      verdict = on.length ? (row.shape === "gated-choice" ? "offered" : "roles") : "claude";
      if (on.length) extra = ui.color.gray("  " + on.join(", "));
    } else {
      // fixed-executor, and `/orc-mini` is the only lane on it.
      const e = extraResolveEdges(claudeDir, row.agent, "executor");
      verdict = e.agree ? "foreign" : "claude";
      if (e.band) extra = ui.color.gray(`  ${e.band} edges ${(e.edges || []).join(",")} agreeing=${e.agree}`);
    }
    console.log(`    ${ui.color.cyan(row.lane.padEnd(16))} ${verdict}${extra}`);
  }
  console.log(ui.color.gray("    A lane not listed here does not route foreign.\n"));
}

// `orc extra route set <from>-<to> <profile>/<model> [--max-turns N]`
//
// Overlap is REFUSED BY NAME. Tiling is NOT required — the gaps are the point.
function extraRouteSet(claudeDir, bandSpec, target) {
  const asJson = wantsJson();
  const fail = (reason, msg, extra) => {
    if (asJson) emitJson(Object.assign({ ok: false, reason, error: msg }, extra || {}), 1);
    console.error("❌ " + msg);
    process.exit(1);
  };
  const band = parseBand(bandSpec);
  if (band.err) fail("bad-band", band.err);
  const m = /^([^/]+)\/(.+)$/.exec(String(target || ""));
  if (!m) fail("bad-target", `target must be <profile>/<model> (got "${target || ""}")`);
  const [, profileName, model] = m;

  const ledger = readExtra(claudeDir) || emptyExtra();
  const prof = extraProfile(ledger, profileName);
  if (!prof)
    fail("unknown-profile", `unknown profile "${profileName}". \`orc extra list\` shows what exists.`, {
      known: ledger.profiles.map((x) => x.name),
    });
  // R10, at the CLI as well as in the panel: nothing routes to a profile whose
  // connection was never proven. A route to an unverified endpoint is a wave
  // that dies at dispatch instead of at configuration time.
  if (!prof.verified_at)
    fail(
      "unverified",
      `"${profileName}" has never verified. Run \`orc extra ping ${profileName}\` first — nothing routes to an unproven endpoint.`
    );

  const clash = ledger.routes.find((r) => bandsOverlap(r, band));
  if (clash)
    fail(
      "overlap",
      `${bandLabel(band)} overlaps the existing row ${bandLabel(clash)} → ${clash.profile}/${clash.model}.\n` +
        `   Remove it first: orc extra route rm ${clash.from}-${clash.to}`,
      { conflicts_with: { from: clash.from, to: clash.to, profile: clash.profile, model: clash.model } }
    );

  // A model outside `models_seen` WARNS and does not refuse: a provider may add
  // a model between pings, and refusing would make ORC's cache the authority on
  // someone else's catalogue.
  const known = (prof.models_seen || []).includes(model);
  const maxTurns = flag("--max-turns");
  // The CHEAP companion. Claude Code makes background calls on the `haiku`
  // alias, so without one those land on the PRIMARY model — and "we sent your
  // background calls to the expensive model" is exactly the cost surprise this
  // subsystem exists to remove. Per-route rather than per-profile because the
  // right companion for a 15-score rename and a 95-score migration are not
  // necessarily the same id.
  const smallModel = flag("--small-model");
  const row = {
    from: band.from,
    to: band.to,
    profile: profileName,
    model,
    small_model: typeof smallModel === "string" ? smallModel : null,
    max_turns: typeof maxTurns === "string" && /^\d+$/.test(maxTurns) ? Number(maxTurns) : null,
  };

  // What this row TAKES. The shadowing rule runs both ways, and a band silently
  // lifted off the Claude ladder is exactly the kind of quiet change this
  // codebase announces everywhere else.
  const { map } = readOverride(claudeDir);
  const displaced = claudeGaps([row], map).filter((g) => g.from >= band.from && g.to <= band.to);

  ledger.routes.push(row);
  ledger.routes.sort((a, b) => a.from - b.from);
  extraHistory(ledger, "route-set", { band: bandLabel(band), profile: profileName, model });
  const file = writeExtra(claudeDir, ledger);
  const cfg = resolvedConfig(claudeDir);

  if (asJson)
    emitJson(
      {
        ok: true,
        row: Object.assign({ band: bandLabel(band) }, row),
        model_known: known,
        displaces: displaced,
        extra_enabled: isTrue(cfg.extra_enabled),
        ledger: file,
      },
      0
    );
  console.log(`\nRouted ${ui.color.cyan(bandLabel(band))} → ${profileName}/${model}`);
  if (displaced.length)
    console.log(
      "  " +
        ui.color.gray(
          "takes this band off: " + displaced.map((d) => `${d.agent} ${bandLabel(d)}`).join(", ")
        )
    );
  if (!known)
    console.log(
      "  " +
        ui.mark.warn(
          `"${model}" is not in this profile's models_seen — ORC's cache is not the authority on someone else's catalogue, so this is allowed. Re-ping to refresh it.`
        )
    );
  if (!row.small_model)
    console.log(
      "  " +
        ui.color.gray(
          "no --small-model: background calls (title generation, small utility turns) will use " +
            `"${model}". Name a cheap id to stop paying primary rates for them.`
        )
    );
  if (!isTrue(cfg.extra_enabled))
    console.log("  " + ui.mark.warn("extra_enabled is false — this row is inert until you set it."));
  console.log("");
}

function extraRouteRm(claudeDir, bandSpec) {
  const asJson = wantsJson();
  const band = parseBand(bandSpec);
  if (band.err) {
    if (asJson) emitJson({ ok: false, reason: "bad-band", error: band.err }, 1);
    console.error("❌ " + band.err);
    process.exit(1);
  }
  const ledger = readExtra(claudeDir) || emptyExtra();
  const before = ledger.routes.length;
  const gone = ledger.routes.filter((r) => r.from === band.from && r.to === band.to);
  ledger.routes = ledger.routes.filter((r) => !(r.from === band.from && r.to === band.to));
  if (ledger.routes.length === before) {
    const msg = `no route row is exactly ${bandLabel(band)}. \`orc extra route\` lists them.`;
    if (asJson) emitJson({ ok: false, reason: "no-such-row", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  extraHistory(ledger, "route-rm", { band: bandLabel(band) });
  writeExtra(claudeDir, ledger);
  if (asJson) emitJson({ ok: true, removed: gone.map((g) => Object.assign({ band: bandLabel(g) }, g)) }, 0);
  console.log(`\nRemoved ${bandLabel(band)} — those scores are back on the Claude ladder.\n`);
}

// ═══════════════════════════════════════════════════════════════════════════
// P5 — THERE IS ONE RESOLVER, AND THE SKILL IS NOT IT
//
// `orc extra resolve <score>` is the ONLY thing that decides whether a task
// goes foreign and to what. The /orc skill CALLS it and RENDERS the answer; it
// never re-derives the band from the config. This is the computeWikiFreshness
// rule, the Flow-stepper rule and the docPlanShape rule applied a fourth time:
// a second idea of the routing would describe a dispatch that will not happen.
//
// It always explains itself. `why` is not decoration — a routing decision the
// user cannot account for is a routing decision they will turn off.
//
// exit 0 = extra · 1 = claude
// ═══════════════════════════════════════════════════════════════════════════
function extraResolveFor(claudeDir, score, opts) {
  const o = opts || {};
  const t = extraRouteRows(claudeDir);
  const cfg = t.cfg;
  const claudeTable = isTrue(t.map.opus5_only) ? "opus5_only" : t.map.rubric_bands_override ? "rubric_bands_override" : "default";
  const claudeBand = bandFor(score, cfg);
  const claude = {
    via: "claude",
    band: claudeBand.band,
    agent: claudeBand.agent,
    table: claudeTable,
  };
  const answer = (why, extra) =>
    Object.assign({ ok: true, score, role: o.role || null, claude, resolved: "claude", why }, extra || {});

  if (!isTrue(cfg.extra_enabled))
    return answer("extra_enabled is false — the master gate. Nothing routes foreign until it is true.", { held_back: null });

  const roles = INLINE_LIST(cfg.extra_roles).filter(Boolean);
  const role = o.role || "executor";
  if (!roles.includes(role))
    return answer(
      `extra_roles does not include "${role}" (it has: ${roles.join(", ") || "nothing"}). A role ORC has not been told to hand over stays on Claude.`,
      { held_back: "role" }
    );

  const row = t.ledger.routes.find((r) => bandCovers(r, score));
  if (!row)
    return answer(
      `no route row covers ${score} — Extra is an OVERLAY, so an uncovered score falls straight through to the Claude ladder.`,
      { held_back: null }
    );

  // P1 — a cited-risk task never leaves Claude by default. This mirrors the
  // existing risk floor: ORC already refuses to send a refund-endpoint change
  // to a cheap model, and Extra must not become the hole in that rule.
  // NOTE the comparison: `extra_risk_tasks` is an off/on ENUM, not a boolean.
  // `isTrue()` here would compare "on" against "true", never match, and hold
  // every risk task back forever — a gate the user cannot open is worse than
  // no gate, because it looks like one.
  const risk = Number(o.risk || 0);
  if (risk > 0 && String(cfg.extra_risk_tasks) !== "on")
    return answer(
      `this task carries ${plural(risk, "cited risk")} and extra_risk_tasks is off — it is HELD BACK to ${claude.agent}.`,
      { held_back: "risk", would_have_been: { profile: row.profile, model: row.model } }
    );

  const prof = extraProfile(t.ledger, row.profile);
  if (!prof)
    return answer(
      `route row ${bandLabel(row)} names profile "${row.profile}", which no longer exists — falling through to Claude.`,
      { held_back: "missing-profile" }
    );
  if (!prof.verified_at)
    return answer(
      `"${row.profile}" has never verified — nothing dispatches to an unproven endpoint.`,
      { held_back: "unverified" }
    );

  // v1.0.0 W5 — THE DEMOTION, and it is a HOLD-BACK like every other one: the
  // score does not move, `declared_files` is not widened, `acceptance[]` is not
  // touched. The task runs at the SAME Claude agent it would have had, which is
  // why this returns the ordinary `claude` answer rather than a new shape.
  const dem = extraProfileDemoted(claudeDir, prof.name, cfg);
  if (dem)
    return answer(
      `"${prof.name}" is DEMOTED for the rest of run ${dem.state.run} — ${dem.profile.why} It stays at the bottom of the ladder until you promote it back: orc extra promote ${dem.state.run} --reason "<why>"`,
      {
        held_back: "demoted",
        demotion: {
          run: dem.state.run,
          profile: prof.name,
          reason: dem.profile.reason,
          why: dem.profile.why,
          announce: dem.state.announce,
          trace_line: dem.state.trace_line,
        },
        would_have_been: { profile: row.profile, model: row.model },
      }
    );

  // A STALE verification still ROUTES. A stale check is not a failed one (the
  // /orc-pact UNCHECKABLE rule); the lane re-pings before wave 1 and says so.
  const v = extraVerifyState(prof, cfg);
  const cred = prof.credential || {};
  return {
    ok: true,
    score,
    role,
    resolved: "extra",
    via: `extra:${prof.name}`,
    profile: prof.name,
    provider: prof.provider,
    engine: prof.engine,
    model: row.model,
    small_model: row.small_model || null,
    model_known: (prof.models_seen || []).includes(row.model),
    max_turns: row.max_turns === undefined ? null : row.max_turns,
    band: bandLabel(row),
    verify_state: v.state,
    verify_age_days: v.age_days,
    needs_reping: v.state === "STALE",
    credential: { source: cred.source || "env", key_name: cred.key_name || null, present: credentialPresent(cred, claudeDir) },
    claude,
    held_back: null,
    why:
      `route row ${bandLabel(row)} covers ${score} and outranks the ${claudeTable} Claude table` +
      (v.state === "STALE" ? `; verification is ${v.age_days}d old (STALE — still routes, re-pinged before wave 1)` : "") +
      ".",
    // P0's sentence, composed HERE so no lane writes a second wording for it.
    announce: `task at score ${score} → ${prof.provider}/${row.model} via ${prof.engine} (profile ${prof.name}) — this sends the slice to a third party.`,
  };
}

// ─ orc extra lanes (v0.52.0, D6) ───────────────────
//
// A BAND WITH NO LANE ATTACHED IS NOT A ROUTING DECISION. The routing table
// says `[40,55) → opencode/big-pickle`, which is true for `/orc` — and is not
// how `/orc-fast` works at all. That lane pins ONE executor, and the rule that
// governs it (resolve BOTH EDGES of the pinned agent's band and require them to
// agree) was implemented, documented, and rendered NOWHERE.
//
// This is the machine-readable copy of the "Which lanes route foreign" table in
// `templates/skills/_shared/extra-dispatch.md`, registered in
// `bin/verify-contracts.js` against that file so the two cannot drift, with a
// golden test comparing them in BOTH directions — the DIY_STEPS ↔- stitch-order
// precedent. A lane in the markdown and not here fails; the reverse fails too.
//
// `agent` is the pinned executor whose BAND is resolved at both edges. A lane
// with no pinned agent has no band, and that is an answer rather than a gap.
// ═══════════════════════════════════════════════════════════════════════════
// v0.55.0 — ROLE SLOTS: THE NON-SCORED HALF OF ROUTING
//
// A SCORE IS WHAT A BAND NEEDS, AND FOUR LANES DO NOT HAVE ONE. `/orc`,
// `/orc-ultra`, `/orc-mini` and `/orc-diy` score every task, so a band is a
// routing decision the user made. `/orc-quick`, `/orc-fast`, `/orc-doc` and
// `/orc-wiki` do not: they pin an agent to a POSITION. Resolving that agent's
// band at both edges was arithmetic on a number nobody chose — and it was
// wrong in two places and dead in a third (a doc CHECKER resolved against the
// WRITER's band; `/orc-wiki` asked for a role spelling `extra_roles` refuses).
//
// So a slot is an explicit, named POSITION with one chosen `profile/model`.
// A row's PRESENCE is the arming; there is no second master gate and no
// per-lane key. ZERO CONFIG KEYS WERE ADDED.
//
// This is the machine-readable copy of the `## The slot table` section in
// `templates/skills/_shared/extra-dispatch.md`, registered in
// `bin/verify-contracts.js` against that file, with a golden test comparing
// the two IN BOTH DIRECTIONS — the EXTRA_LANE_SHAPES / DIY_STEPS precedent. A
// row in the markdown and not here fails, and the reverse fails too.
//
// `claude` is an ARRAY because `quick-executor` has two: a menu is what that
// lane is. `claude_opus5` is the variant `opus5_only` would have used, derived
// from the shipped ladders — NULL where the agent is already Opus 5, so two
// wiki slots collapsing onto one Opus 5 scanner is not a contradiction: the
// slot names the POSITION, not the model. NO AGENT IS ADDED by this release
// and no pair is needed (the floor stays 51).
const EXTRA_SLOTS = [
  {
    slot: "quick-executor",
    lane: "/orc-quick",
    claude: ["orc-executor-sonnet-4-6-med", "orc-executor-opus-5-low"],
    claude_opus5: ["orc-executor-opus-5-low"],
    asks: true,
    announce: "the dispatch gate — offered as a third option, never a default",
    why: "the user picks the agent for every entry anyway, so a foreign worker is one more option on a menu they already read.",
  },
  {
    slot: "fast-executor",
    lane: "/orc-fast",
    claude: ["orc-executor-sonnet-4-6-high"],
    claude_opus5: ["orc-executor-opus-5-med"],
    asks: false,
    announce: "the F0 preflight `extra:` line, before wave 1",
    why: "one executor, one slice, a build+test smoke gate behind it — the checks that catch a bad implementation here are engine-blind.",
  },
  {
    slot: "doc-writer",
    lane: "/orc-doc",
    claude: ["orc-doc-writer-opus-5-med"],
    claude_opus5: null,
    asks: false,
    announce: "before the wave, naming the sections going off Claude",
    why: "a writer owns ONE part file and invents no fact; its output is read by a checker and by you before it ships.",
  },
  {
    slot: "doc-checker",
    lane: "/orc-doc",
    claude: ["orc-doc-checker-opus-5-low"],
    claude_opus5: null,
    asks: false,
    announce: "before the wave",
    why: "the checker reads one bounded part and reports; it rewrites nothing, so a finding it makes is a finding you read.",
  },
  {
    slot: "wiki-scanner-deep",
    lane: "/orc-wiki",
    claude: ["orc-wiki-scanner-opus-4-8-high"],
    claude_opus5: ["orc-wiki-scanner-opus-5-med"],
    asks: false,
    announce: "per scan-batch, beside the resolved tier",
    why: "a scanner returns an evidence-anchored doc body the orchestrator writes; every claim in it is anchored to a file you can open.",
  },
  {
    slot: "wiki-scanner-light",
    lane: "/orc-wiki",
    claude: ["orc-wiki-scanner-sonnet-5-high"],
    claude_opus5: ["orc-wiki-scanner-opus-5-med"],
    asks: false,
    announce: "per scan-batch, beside the resolved tier",
    why: "the LIGHT tier is already a small no-new-surface delta on an existing doc — the cheapest work the wiki does.",
  },
];
const EXTRA_SLOT_IDS = EXTRA_SLOTS.map((s) => s.slot);
const extraSlotRow = (slot) => EXTRA_SLOTS.find((s) => s.slot === slot) || null;

// The Claude agents a slot displaces, AFTER `opus5_only`. Deterministic: a
// pinned NAME, never an interval — which is why the displaced answer a slot
// resolve carries is strictly more honest than what the scored half can offer.
function extraSlotClaude(row, opus5) {
  const agents = (opus5 && row.claude_opus5 ? row.claude_opus5 : row.claude).slice();
  return {
    via: "claude",
    agent: agents[0],
    agents,
    // NOT "inert" — NOT CONSULTED. With one slot routed and another not,
    // `opus5_only` is fully live for the one with no row, and that distinction
    // must be printed rather than flattened.
    table: opus5 ? "opus5_only" : "shipped",
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// `extraResolveSlot` — THE SECOND RESOLVER, AND IT NEVER TOUCHES A BAND
//
// The sibling of `extraResolveFor`, with the SAME answer shape (`ok`,
// `resolved`, `why`, `held_back`, `announce`, `claude`) so every consumer
// renders one thing. It never calls `extraAgentBand`, never calls
// `extraResolveEdges`, and never reads a score.
//
// PRECEDENCE, one sentence: extra decides whether a Claude agent runs at all;
// `opus5_only` and the score tables only decide WHICH Claude agent runs where
// extra did not take it. For a slot that is: the slot row > `opus5_only`'s
// variant of that slot's agent > the shipped agent.
//
// exit 0 = extra · 1 = claude · 2 = unknown slot
// ═══════════════════════════════════════════════════════════════════════════
function extraResolveSlot(claudeDir, slot, opts) {
  const o = opts || {};
  const row = extraSlotRow(slot);
  // 1 — an unknown slot is REFUSED and the six are LISTED (the `orc pattern
  // status` exit-2 precedent). A typo is not a routing decision.
  if (!row)
    return {
      ok: false,
      shape: "slot",
      reason: "unknown-slot",
      slot: slot === undefined || slot === null ? "" : String(slot),
      known: EXTRA_SLOT_IDS,
      error: `unknown slot "${slot === undefined || slot === null ? "" : slot}" (known: ${EXTRA_SLOT_IDS.join(", ")}).`,
    };

  const ledger = readExtra(claudeDir) || emptyExtra();
  const cfg = resolvedConfig(claudeDir);
  const { map } = readOverride(claudeDir);
  const claude = extraSlotClaude(row, isTrue(map.opus5_only));
  const base = {
    ok: true,
    shape: "slot",
    slot: row.slot,
    lane: row.lane,
    asks: !!row.asks,
    announce_point: row.announce,
    claude,
  };
  const answer = (why, extra) =>
    Object.assign({}, base, { resolved: "claude", why, held_back: null }, extra || {});

  // 2 — the master gate.
  if (!isTrue(cfg.extra_enabled))
    return answer("extra_enabled is false — the master gate. Nothing routes foreign until it is true.");

  // 3 — Extra is an OVERLAY. An unrouted slot falls straight through, exactly
  // like an uncovered score. ABSENCE IS NOT A HOLE.
  const sr = ledger.slots.find((x) => x.slot === row.slot);
  if (!sr)
    return answer(
      `no slot row holds ${row.slot} — Extra is an OVERLAY, so an unrouted position falls straight through to ${claude.agent}.`
    );

  // 6 — a cited risk, IN THE SLICE. NEVER INVENT A RISK FACET: a wiki scan and
  // a doc section do not have one, and a slot dispatch with no `risk` field is
  // not a risk-free task — it is a task with no risk statement. Only
  // /orc-quick and /orc-fast can legitimately carry one.
  const risk = Number(o.risk || 0);
  if (risk > 0 && String(cfg.extra_risk_tasks) !== "on")
    return answer(
      `this task carries ${plural(risk, "cited risk")} and extra_risk_tasks is off — it is HELD BACK to ${claude.agent}.`,
      { held_back: "risk", would_have_been: { profile: sr.profile, model: sr.model } }
    );

  // 7 — a boundary REFUSE holds, and holds in `warn` too. `boundary_gate`
  // decides whether ORC should attempt the task at all; neither mode ever
  // asked whether the work should leave the machine.
  if (o.boundary === "REFUSE")
    return answer(
      "the boundary card for this area says REFUSE — that holds in `warn` too, because boundary_gate never asked whether the work should leave the machine.",
      { held_back: "boundary", would_have_been: { profile: sr.profile, model: sr.model } }
    );

  // 4 / 5 — the profile must exist and must have proven itself.
  const prof = extraProfile(ledger, sr.profile);
  if (!prof)
    return answer(
      `slot row ${row.slot} names profile "${sr.profile}", which no longer exists — falling through to ${claude.agent}.`,
      { held_back: "missing-profile" }
    );
  if (!prof.verified_at)
    return answer(
      `"${sr.profile}" has never verified — nothing dispatches to an unproven endpoint.`,
      { held_back: "unverified" }
    );

  // 10 — v1.0.0 W5, THE DEMOTION. The tenth hold-back, and the only one that is
  // about the RUN rather than about the row: a profile that stalled twice is at
  // the bottom of the ladder until a human promotes it back. The position falls
  // through to the SAME pinned Claude agent it always had — a demotion changes
  // WHERE the work runs and nothing else.
  const demSlot = extraProfileDemoted(claudeDir, prof.name, cfg);
  if (demSlot)
    return answer(
      `"${prof.name}" is DEMOTED for the rest of run ${demSlot.state.run} — ${demSlot.profile.why} ${row.slot} falls through to ${claude.agent} until you promote it back: orc extra promote ${demSlot.state.run} --reason "<why>"`,
      {
        held_back: "demoted",
        demotion: {
          run: demSlot.state.run,
          profile: prof.name,
          reason: demSlot.profile.reason,
          why: demSlot.profile.why,
          announce: demSlot.state.announce,
          trace_line: demSlot.state.trace_line,
        },
        would_have_been: { profile: sr.profile, model: sr.model },
      }
    );

  // 8 — a STALE verification STILL ROUTES. A stale check is not a failed one
  // (the /orc-pact UNCHECKABLE rule); it is re-pinged before the wave and said
  // out loud. (9 — an EXPIRED/ABSENT vault passphrase is `orc extra
  // preflight`'s stop, not this resolver's: the row is not the credential's
  // problem, and a routing answer is not the place to report a deadline.)
  const v = extraVerifyState(prof, cfg);
  const cred = prof.credential || {};
  return Object.assign({}, base, {
    resolved: "extra",
    via: `extra:${prof.name}`,
    profile: prof.name,
    provider: prof.provider,
    engine: prof.engine,
    model: sr.model,
    small_model: sr.small_model || null,
    model_known: (prof.models_seen || []).includes(sr.model),
    max_turns: sr.max_turns === undefined ? null : sr.max_turns,
    band: `slot:${row.slot}`,
    verify_state: v.state,
    verify_age_days: v.age_days,
    needs_reping: v.state === "STALE",
    credential: { source: cred.source || "env", key_name: cred.key_name || null, present: credentialPresent(cred, claudeDir) },
    held_back: null,
    why:
      `slot row ${row.slot} holds this position and outranks ${claude.agent}` +
      (v.state === "STALE" ? `; verification is ${v.age_days}d old (STALE — still routes, re-pinged before the wave)` : "") +
      ".",
    // The sentence, composed HERE so no lane writes a second wording for it.
    announce: `${row.slot} (${row.lane}) → ${prof.provider}/${sr.model} via ${prof.engine} (profile ${prof.name}) — displaces ${claude.agent}; this sends the slice to a third party.`,
  });
}

const EXTRA_LANE_SHAPES = [
  { lane: "/orc", shape: "scored", agent: null },
  // v0.55.0 - ADDED. `/orc-ultra` runs the `orc` skill and writes its own
  // `run-ultra-<slug>` trace, so its absence from this table was a gap: a lane
  // the protocol declares must be a lane something OPENS, and a lane something
  // opens must be a lane this table can answer for.
  { lane: "/orc-ultra", shape: "scored", agent: null },
  { lane: "/orc-mini", shape: "fixed-executor", agent: "orc-executor-sonnet-5-high" },
  // v0.55.0 - `/orc-fast` LOSES its band and gains a POSITION. `/orc-mini`
  // KEEPS the band, and the asymmetry is deliberate: mini scores its tasks and
  // then pins one executor over them, so both edges of that agent's band is a
  // question about numbers the run actually produced. Fast produces none.
  { lane: "/orc-fast", shape: "slot", agent: null, slots: ["fast-executor"] },
  // Compile-owned: the flow decides WHETHER, the resolver still decides WHERE.
  // Its shape depends on the compiled config, so it is computed per read.
  { lane: "/orc-diy", shape: "scored", agent: null, compile_owned: true },
  // v0.55.0 - NOT INERT ANY MORE, and not silently armed either. The slot adds
  // a THIRD OPTION to a menu the user already reads; it never becomes a
  // default and never sticks.
  { lane: "/orc-quick", shape: "gated-choice", agent: null, slots: ["quick-executor"] },
  { lane: "/orc-doc", shape: "slot", agent: null, slots: ["doc-writer", "doc-checker"] },
  { lane: "/orc-challenge", shape: "never", agent: null },
  // v0.55.0 - the row was DEAD: it asked for a role spelling `extra_roles`
  // refuses by name, so this lane could never route however it was configured.
  { lane: "/orc-wiki", shape: "slot", agent: null, slots: ["wiki-scanner-deep", "wiki-scanner-light"] },
  { lane: "/orc-retro", shape: "never", agent: null },
  { lane: "/orc-budget", shape: "never", agent: null },
  { lane: "/orc-aftermath", shape: "never", agent: null },
  { lane: "/orc-boundary", shape: "never", agent: null },
  { lane: "/orc-pact", shape: "never", agent: null },
];
// `offered` is `gated-choice`'s verdict and only ever that: the lane's premise
// is that it asks, so "this lane routes foreign" would be a claim about a
// decision only the user gets to make, per entry.
const EXTRA_LANE_ROUTES = ["per-task", "foreign", "claude", "roles", "offered", "never"];

// THE BAND OF A PINNED AGENT, from the SAME shipped ladders every other reader
// uses. A lane with a fixed agent has no score, so there is nothing to resolve
// with except the band its agent's MODEL AND EFFORT already encode.
//
// Matching is by the model+effort TAIL of the agent name, and that is not a
// convenience: an agent's model change is ALWAYS a rename in this repo, so the
// tail is the authoritative statement of what it runs on. `/orc-doc`'s writer is
// `orc-doc-writer-opus-5-med`, which is opus-5 at medium — the same rung the
// opus5_only ladder calls `orc-executor-opus-5-med`. Nothing is invented: a tail
// no shipped row carries returns NULL, and a lane whose band cannot be resolved
// stays on Claude and says so. A number ORC made up to satisfy an interface is
// not a routing decision the user made.
// v0.55.0 - ONE CALLER LEFT. `/orc-fast` and `/orc-doc` used to resolve a band
// here and both were REPOINTED at `extraResolveSlot`, not repaired: a slot is a
// position the user chose, and both edges of a pinned agent's band was
// arithmetic on a number nobody chose. `/orc-mini` keeps it, because mini
// SCORES its tasks and then pins one executor over them - so its edges are a
// question about numbers the run actually produced. Do not assume this pair is
// load-bearing anywhere else.
function extraAgentBand(agent) {
  const name = String(agent || "");
  const tail = name.replace(/^orc-[a-z]+(-[a-z]+)*?-(?=(haiku|sonnet|opus|fable)-)/, "");
  for (const table of [DIY_SCORE_TABLE, OPUS5_SCORE_TABLE]) {
    const row = table.find((r) => r[2] === name) || table.find((r) => tail && r[2].endsWith("-" + tail));
    if (row) return { from: row[0], to: row[1] === 101 ? 100 : row[1], inclusive_to: row[1] === 101 };
  }
  return null;
}

// Resolve BOTH EDGES, and they must AGREE. The alternative was a midpoint, and it is
// wrong for a reason worth restating here: a row covering [55,58) would capture
// an entire mini run on the strength of three scores out of ten. A number ORC
// invented to satisfy an interface is not a routing decision the user made.
function extraResolveEdges(claudeDir, agent, role) {
  const band = extraAgentBand(agent);
  if (!band) return { band: null, edges: null, agree: null, resolved: null, partial: null };
  const lo = band.from;
  const hi = band.inclusive_to ? 100 : band.to - 1;
  const a = extraResolveFor(claudeDir, lo, { role: role || "executor" });
  const b = extraResolveFor(claudeDir, hi, { role: role || "executor" });
  const same =
    a.resolved === "extra" &&
    b.resolved === "extra" &&
    a.profile === b.profile &&
    a.model === b.model;
  return {
    band: `[${lo},${band.inclusive_to ? "100]" : band.to + ")"}`,
    edges: [lo, hi],
    agree: same,
    resolved: same ? { profile: a.profile, model: a.model, engine: a.engine, provider: a.provider } : null,
    // The disclosure `extra-dispatch.md` already demands: WHICH row partially
    // covered the band, when one edge went foreign and the other did not.
    partial: same ? null : [a, b].filter((x) => x.resolved === "extra").map((x) => x.band)[0] || null,
    why_a: a.why,
    why_b: b.why,
  };
}

function extraLanes(claudeDir) {
  const asJson = wantsJson();
  const cfg = resolvedConfig(claudeDir);
  const enabled = isTrue(cfg.extra_enabled);
  const roles = INLINE_LIST(cfg.extra_roles).filter(Boolean);

  const lanes = EXTRA_LANE_SHAPES.map((row) => {
    const out = { lane: row.lane, shape: row.shape, agent: row.agent || null };
    if (row.shape === "never") {
      out.routes = "never";
      out.detail = "this lane measures rather than produces, so nothing it dispatches may be swapped for a different model.";
      return out;
    }
    if (row.shape === "inert") {
      out.routes = "never";
      out.detail = "this lane asks which agent before every dispatch, so a config that answered it silently would break its premise. It is announced at the gate.";
      return out;
    }
    if (!enabled) {
      // A slot lane says the same thing, in its own words: what falls through
      // is a NAMED agent per position, not a table.
      if (row.shape === "slot" || row.shape === "gated-choice") {
        out.slots = (row.slots || []).map((slot) => {
          const r = extraResolveSlot(claudeDir, slot, {});
          return { slot, routes: false, claude: r.claude.agent, why: r.why };
        });
      }
      out.routes = "claude";
      out.detail = "extra_enabled is false — the master gate. Nothing routes foreign until it is true.";
      return out;
    }
    if (row.shape === "scored") {
      out.routes = roles.includes("executor") ? "per-task" : "claude";
      out.detail = roles.includes("executor")
        ? "every task is scored, so the routing table below applies score by score."
        : "extra_roles does not include `executor`, so no task in this lane leaves Claude.";
      if (row.compile_owned)
        out.detail += " The flow key decides WHETHER; the resolver still decides WHERE, so route rows are never baked into flow.lock.json.";
      return out;
    }
    // v0.55.0 - THE POSITIONS. No band is resolved here at all: `slots[]` is
    // the answer, one row per position, each carrying the agent it displaces.
    if (row.shape === "slot" || row.shape === "gated-choice") {
      const res = (row.slots || []).map((slot) => {
        const r = extraResolveSlot(claudeDir, slot, {});
        return {
          slot,
          routes: r.resolved === "extra",
          profile: r.profile || null,
          model: r.model || null,
          claude: r.claude.agent,
          held_back: r.held_back || null,
          why: r.why,
        };
      });
      out.slots = res;
      const on = res.filter((x) => x.routes);
      if (row.shape === "gated-choice") {
        out.routes = on.length ? "offered" : "claude";
        out.detail = on.length
          ? `${on.map((x) => x.slot).join(" and ")} is OFFERED as one more option at the dispatch gate. It never becomes a default and never sticks — this lane asks before every dispatch.`
          : "nothing holds this lane's position, so the gate offers its Claude agents only.";
        return out;
      }
      out.routes = on.length ? "roles" : "claude";
      out.detail = on.length
        ? `${on.map((x) => x.slot).join(" and ")} ${on.length === 1 ? "is" : "are"} held by a non-Claude worker; every position with no row stays on its pinned Claude agent.`
        : "no position in this lane is held, so every one of them stays on its pinned Claude agent.";
      return out;
    }
    // v0.55.0 - the `fixed-role` shape is GONE. It served `/orc-doc` and
    // `/orc-wiki`, and both are POSITIONS now: a role that pins an agent has no
    // score, so resolving that agent's band at both edges was arithmetic on a
    // number nobody chose. A shape no row carries is a shape that does not
    // exist, so it is deleted rather than left standing as a dead branch.
    // fixed-executor
    const e = extraResolveEdges(claudeDir, row.agent, "executor");
    out.band = e.band;
    out.edges = e.edges;
    out.agree = e.agree;
    out.routes = e.agree ? "foreign" : "claude";
    out.resolved = e.resolved;
    out.detail = e.agree
      ? "this lane pins one executor. Both edges of its band resolve to the same profile, so the whole lane goes foreign."
      : e.partial
        ? `one edge routes foreign and the other does not, so the lane stays on Claude. Row ${e.partial} covers only part of this band.`
        : "no route row covers this lane's band, so it stays on the Claude ladder.";
    return out;
  });

  if (asJson)
    emitJson(
      {
        ok: true,
        extra_enabled: enabled,
        roles,
        shapes: ["scored", "fixed-executor", "slot", "gated-choice", "inert", "never"],
        slots: EXTRA_SLOTS.map((r) => ({ slot: r.slot, lane: r.lane, asks: !!r.asks })),
        routes: EXTRA_LANE_ROUTES,
        // A lane whose shape is unknown is NOT listed as `claude`. Absence is a
        // `no`, never an omission to be interpreted — the markdown's own rule.
        note: "A lane not in this list does not route foreign.",
        lanes,
      },
      0
    );

  console.log(ui.header("ORC " + "·" + " extra " + "—" + " which lane routes foreign, and how"));
  console.log("");
  for (const l of lanes) {
    const mark =
      l.routes === "foreign" || l.routes === "roles" || l.routes === "per-task"
        ? ui.mark.ok(l.routes)
        : l.routes === "never"
          ? ui.color.gray(l.routes)
          : ui.mark.warn(l.routes);
    console.log(`  ${ui.color.cyan(l.lane.padEnd(16))} ${l.shape.padEnd(15)} ${mark}`);
    if (l.band) console.log(`      band ${l.band}  edges ${(l.edges || []).join(",")}  agreeing=${l.agree}`);
    for (const sl of l.slots || [])
      console.log(
        `      ${sl.slot.padEnd(20)} ${sl.routes ? ui.color.cyan(sl.profile + "/" + sl.model) : ui.color.gray("claude · " + sl.claude)}`
      );
    console.log("      " + ui.color.gray(l.detail));
  }
  console.log(ui.color.gray("\n  A lane not listed here does not route foreign.\n"));
}

// ═══════════════════════════════════════════════════════════════════════════
// `orc extra role` — THE SLOT LEDGER'S CLI (v0.55.0)
//
//   orc extra role [list] [--json]
//   orc extra role set <slot> <profile>/<model> [--small-model <id>] [--max-turns N]
//   orc extra role rm  <slot>
//   orc extra role show <slot> [--json]
//
// Exit codes, the `orc pattern status` convention: 0 done / at least one slot
// routes · 1 nothing routes (a read) or the write was REFUSED · 2 unknown slot,
// NAMED, with the six listed.
//
// NO OVERLAP CONCEPT EXISTS. A slot is a point, not an interval, so the band
// table's overlap refusal has no analogue here and none is invented; `set` on
// an occupied slot REPLACES and says what it replaced.
// ═══════════════════════════════════════════════════════════════════════════

// One row's whole computed answer. `--json is not a summary`: every field the
// TTY branch prints is here, including the displaced Claude agent, the verify
// state and its age, `model_known` and the next action where one exists.
function extraRoleRow(claudeDir, row, ledger, cfg) {
  const res = extraResolveSlot(claudeDir, row.slot, {});
  const sr = ledger.slots.find((x) => x.slot === row.slot) || null;
  const prof = sr ? extraProfile(ledger, sr.profile) : null;
  const v = prof ? extraVerifyState(prof, cfg) : null;
  return {
    slot: row.slot,
    lane: row.lane,
    routed: !!sr,
    profile: sr ? sr.profile : null,
    model: sr ? sr.model : null,
    small_model: sr ? sr.small_model || null : null,
    max_turns: sr ? (sr.max_turns === undefined ? null : sr.max_turns) : null,
    added_at: sr ? sr.added_at || null : null,
    provider: prof ? prof.provider : null,
    engine: prof ? prof.engine : null,
    verify_state: v ? v.state : null,
    verify_age_days: v ? v.age_days : null,
    model_known: prof && sr ? (prof.models_seen || []).includes(sr.model) : null,
    // The POSITION, in plain words, composed by the CLI — the panel must never
    // write its own meaning for one (the Flow-stepper rule).
    meaning: row.why,
    asks: !!row.asks,
    announce_point: row.announce,
    // The Claude answer this slot displaces, or would fall through to. A pinned
    // NAME, never an interval.
    claude: res.claude,
    resolved: res.resolved,
    why: res.why,
    held_back: res.held_back || null,
    announce: res.resolved === "extra" ? res.announce : null,
    next:
      res.resolved === "extra"
        ? null
        : sr
          ? res.held_back === "unverified"
            ? `orc extra ping ${sr.profile}`
            : res.held_back === "missing-profile"
              ? `orc extra role rm ${row.slot}`
              : null
          : `orc extra role set ${row.slot} <profile>/<model>`,
  };
}

function extraRoleList(claudeDir) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir) || emptyExtra();
  const cfg = resolvedConfig(claudeDir);
  const enabled = isTrue(cfg.extra_enabled);
  // ALL SIX, ALWAYS. An unrouted slot KEEPS ITS SLOT and reads as Claude with
  // its pinned agent — the OFF-phase rule. Filtering it out makes "I left the
  // checker on Claude on purpose" and "there is no checker" identical.
  const rows = EXTRA_SLOTS.map((r) => extraRoleRow(claudeDir, r, ledger, cfg));
  const routing = rows.filter((r) => r.resolved === "extra");
  // The honest report of `00-problem.md` P3: six values `extra_roles` accepts
  // that no resolution path can ever reach, because every one of them needs a
  // score and none of those roles has one. Reported, not fixed — a reviewer you
  // cannot trust is worse than no reviewer, so that one needs its own decision.
  const unreachable = EXTRA_ROLES_ALL.filter(
    (r) => r !== "executor" && !LEGACY_EXTRA_ROLES.includes(r)
  ).map((role) => ({ role, state: "declared · no slot · nothing resolves this" }));
  const code = routing.length ? 0 : 1;
  if (asJson)
    emitJson(
      {
        ok: true,
        extra_enabled: enabled,
        slots: rows,
        counts: { total: rows.length, routed: rows.filter((r) => r.routed).length, resolving: routing.length },
        unreachable_roles: unreachable,
        note: "a slot with no row KEEPS ITS SLOT and falls through to its pinned Claude agent. Absence is not a hole.",
      },
      code
    );
  console.log(ui.header("ORC · extra — the positions"));
  if (!enabled)
    console.log(
      "\n  " +
        ui.mark.warn("extra_enabled is false — every row below is INERT. `orc config set extra_enabled true` arms them.")
    );
  console.log("");
  console.log(
    ui.kv(
      rows.map((r) =>
        r.resolved === "extra"
          ? [r.slot, ui.color.cyan(`${r.profile}/${r.model}`), `${r.lane} · ${r.engine || "?"} · ${r.verify_state}` + (r.model_known ? "" : ui.color.yellow(" · model not in models_seen"))]
          : [r.slot, ui.color.gray("claude · " + r.claude.agent), ui.color.gray(r.lane + (r.routed ? " · " + (r.held_back || "held back") : ""))]
      )
    )
  );
  console.log("\n  " + ui.color.bold("what each position is"));
  for (const r of rows) console.log("    " + ui.color.gray(r.slot.padEnd(20)) + ui.color.gray(r.asks ? "asked at the gate" : "announced: " + r.announce_point));
  if (unreachable.length) {
    console.log("\n  " + ui.color.bold("extra_roles values with no slot"));
    for (const u of unreachable) console.log("    " + ui.color.gray(u.role.padEnd(20)) + ui.color.gray(u.state));
  }
  console.log(
    ui.color.gray(
      "\n  A slot with no row is not a hole — it is Claude, and it is printed so \"I left\n" +
        "  the checker on Claude on purpose\" and \"there is no checker\" never look the same.\n"
    )
  );
  process.exit(code);
}

function extraRoleShow(claudeDir, slotArg) {
  const asJson = wantsJson();
  const row = extraSlotRow(slotArg);
  if (!row) {
    const msg = `unknown slot "${slotArg === undefined ? "" : slotArg}" (known: ${EXTRA_SLOT_IDS.join(", ")}).`;
    if (asJson) emitJson({ ok: false, reason: "unknown-slot", slot: slotArg || "", known: EXTRA_SLOT_IDS, error: msg }, 2);
    console.error("❌ " + msg);
    process.exit(2);
  }
  const ledger = readExtra(claudeDir) || emptyExtra();
  const cfg = resolvedConfig(claudeDir);
  const r = extraRoleRow(claudeDir, row, ledger, cfg);
  const code = r.resolved === "extra" ? 0 : 1;
  if (asJson) emitJson(Object.assign({ ok: true, extra_enabled: isTrue(cfg.extra_enabled) }, r), code);
  console.log(`\n  ${ui.color.cyan(r.slot)}  ${ui.color.gray(r.lane)}`);
  console.log("  " + ui.color.gray(r.meaning));
  console.log(
    r.resolved === "extra"
      ? `  → ${ui.color.cyan(r.profile + "/" + r.model)}  (${r.engine}) · ${r.verify_state}`
      : `  → claude  ${r.claude.agent}`
  );
  console.log("  " + ui.color.gray(r.why));
  console.log("  " + ui.color.gray(r.asks ? "asked at the dispatch gate" : "announced at: " + r.announce_point));
  if (r.announce) console.log("  " + ui.mark.warn(r.announce));
  if (r.next) console.log("  " + ui.color.gray("next: " + r.next));
  console.log("");
  process.exit(code);
}

function extraRoleSet(claudeDir, slotArg, target) {
  const asJson = wantsJson();
  const fail = (reason, msg, extra, code) => {
    if (asJson) emitJson(Object.assign({ ok: false, reason, error: msg }, extra || {}), code || 1);
    console.error("❌ " + msg);
    process.exit(code || 1);
  };
  const row = extraSlotRow(slotArg);
  if (!row)
    fail(
      "unknown-slot",
      `unknown slot "${slotArg === undefined ? "" : slotArg}" (known: ${EXTRA_SLOT_IDS.join(", ")}).`,
      { slot: slotArg || "", known: EXTRA_SLOT_IDS },
      2
    );
  const m = /^([^/]+)\/(.+)$/.exec(String(target || ""));
  if (!m) fail("bad-target", `target must be <profile>/<model> (got "${target || ""}")`);
  const [, profileName, model] = m;

  const ledger = readExtra(claudeDir) || emptyExtra();
  const prof = extraProfile(ledger, profileName);
  if (!prof)
    fail("unknown-profile", `unknown profile "${profileName}". \`orc extra list\` shows what exists.`, {
      known: ledger.profiles.map((x) => x.name),
    });
  // ONLY VERIFIED PROFILES MAY HOLD A POSITION. `orc extra add` already refuses
  // while a tool is absent; this is the same discipline one step later. A slot
  // pointing at an unproven endpoint is a wave that dies at dispatch instead of
  // at configuration time.
  if (!prof.verified_at)
    fail(
      "unverified",
      `"${profileName}" has never verified. Run \`orc extra ping ${profileName}\` first — only a verified profile may hold a position.`
    );

  // A model outside `models_seen` WARNS AND STORES — the route-row rule. It
  // becomes an `orc extra doctor` finding rather than a mid-wave 404 nobody saw
  // coming: a listed model can be dead and an unlisted one can work, and only
  // `orc extra models --test <id>` tells them apart.
  const known = (prof.models_seen || []).includes(model);
  const maxTurns = flag("--max-turns");
  const smallModel = flag("--small-model");
  const replaced = ledger.slots.find((x) => x.slot === row.slot) || null;
  const entry = {
    slot: row.slot,
    profile: profileName,
    model,
    small_model: typeof smallModel === "string" ? smallModel : null,
    max_turns: typeof maxTurns === "string" && /^\d+$/.test(maxTurns) ? Number(maxTurns) : null,
    added_at: new Date().toISOString(),
  };
  ledger.slots = ledger.slots.filter((x) => x.slot !== row.slot).concat([entry]);
  ledger.slots.sort((a, b) => EXTRA_SLOT_IDS.indexOf(a.slot) - EXTRA_SLOT_IDS.indexOf(b.slot));
  extraHistory(ledger, "role-set", {
    slot: row.slot,
    profile: profileName,
    model,
    replaced: replaced ? `${replaced.profile}/${replaced.model}` : null,
  });
  const file = writeExtra(claudeDir, ledger);
  const cfg = resolvedConfig(claudeDir);
  const claude = extraSlotClaude(row, isTrue(readOverride(claudeDir).map.opus5_only));
  // A CREDENTIAL THE VAULT CANNOT OPEN HERE still stores the row and says the
  // run will stop at preflight. The row is not the credential's problem.
  const sess = extraSessionRow(claudeDir, prof);
  const stopsAtPreflight = sess.credential_source === "vault" && (sess.state === "EXPIRED" || sess.state === "ABSENT");

  if (asJson)
    emitJson(
      {
        ok: true,
        slot: row.slot,
        lane: row.lane,
        row: entry,
        replaced: replaced || null,
        model_known: known,
        displaces: claude.agents,
        extra_enabled: isTrue(cfg.extra_enabled),
        stops_at_preflight: stopsAtPreflight,
        ledger: file,
      },
      0
    );
  console.log(`\n${row.slot} → ${ui.color.cyan(profileName + "/" + model)}   ${ui.color.gray(row.lane)}`);
  if (replaced)
    console.log("  " + ui.mark.warn(`replaced ${replaced.profile}/${replaced.model} — that connection no longer holds this position.`));
  console.log("  " + ui.color.gray("takes this position off: " + claude.agents.join(", ")));
  if (!known)
    console.log(
      "  " +
        ui.mark.warn(
          `"${model}" is not in this profile's models_seen — ORC's cache is not the authority on someone else's catalogue, so this is allowed. Re-ping to refresh it.`
        )
    );
  if (stopsAtPreflight)
    console.log(
      "  " + ui.mark.warn("this profile's vault passphrase has reached its deadline — the run will STOP at `orc extra preflight` until you connect again.")
    );
  if (!isTrue(cfg.extra_enabled))
    console.log("  " + ui.mark.warn("extra_enabled is false — this row is inert until you set it."));
  console.log("");
}

function extraRoleRm(claudeDir, slotArg) {
  const asJson = wantsJson();
  const row = extraSlotRow(slotArg);
  if (!row) {
    const msg = `unknown slot "${slotArg === undefined ? "" : slotArg}" (known: ${EXTRA_SLOT_IDS.join(", ")}).`;
    if (asJson) emitJson({ ok: false, reason: "unknown-slot", slot: slotArg || "", known: EXTRA_SLOT_IDS, error: msg }, 2);
    console.error("❌ " + msg);
    process.exit(2);
  }
  const ledger = readExtra(claudeDir) || emptyExtra();
  const gone = ledger.slots.find((x) => x.slot === row.slot) || null;
  if (!gone) {
    const msg = `${row.slot} has no row — it is already on ${extraSlotClaude(row, isTrue(readOverride(claudeDir).map.opus5_only)).agent}.`;
    if (asJson) emitJson({ ok: false, reason: "no-such-row", slot: row.slot, error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  ledger.slots = ledger.slots.filter((x) => x.slot !== row.slot);
  extraHistory(ledger, "role-rm", { slot: row.slot, profile: gone.profile, model: gone.model });
  writeExtra(claudeDir, ledger);
  const claude = extraSlotClaude(row, isTrue(readOverride(claudeDir).map.opus5_only));
  if (asJson) emitJson({ ok: true, slot: row.slot, removed: gone, back_to: claude }, 0);
  console.log(`\nRemoved ${row.slot} — that position is back on ${claude.agent}.\n`);
}

function extraResolveCmd(claudeDir, scoreArg) {
  const asJson = wantsJson();
  // v0.55.0 — ONE COMMAND, TWO SHAPES. A score resolves a BAND; `--slot`
  // resolves a POSITION. Both together is refused BY NAME: one invocation, one
  // shape, because an answer that silently picked which of the two you meant is
  // a routing decision the user did not make.
  const slotFlag = flag("--slot");
  if (typeof slotFlag === "string" || slotFlag === true) {
    if (scoreArg !== undefined) {
      const msg = "`orc extra resolve <score>` and `--slot <slot>` are two shapes of one question — pass one, not both.";
      if (asJson) emitJson({ ok: false, reason: "two-shapes", error: msg }, 2);
      console.error("❌ " + msg);
      process.exit(2);
    }
    const riskF = flag("--risk");
    const res = extraResolveSlot(claudeDir, slotFlag === true ? "" : slotFlag, {
      risk: typeof riskF === "string" ? Number(riskF) : riskF === true ? 1 : 0,
      boundary: typeof flag("--boundary") === "string" ? flag("--boundary") : null,
    });
    if (!res.ok) {
      if (asJson) emitJson(res, 2);
      console.error("❌ " + res.error);
      console.error("   known slots: " + res.known.join(", "));
      process.exit(2);
    }
    const code = res.resolved === "extra" ? 0 : 1;
    if (asJson) emitJson(res, code);
    if (res.resolved === "extra") {
      console.log(`\n  ${ui.color.cyan(res.slot)}  →  ${ui.color.cyan(res.via)}  ${res.provider}/${res.model}  (${res.engine})`);
      console.log(ui.color.gray(`  ${res.why}`));
      console.log("  " + ui.mark.warn(res.announce));
    } else {
      console.log(`\n  ${ui.color.cyan(res.slot)}  →  claude  ${res.claude.agent}  ${ui.color.gray(res.claude.table)}`);
      console.log(ui.color.gray(`  ${res.why}`));
    }
    console.log("");
    process.exit(code);
  }
  const score = Number(scoreArg);
  if (!Number.isFinite(score) || score < 0 || score > 100) {
    const msg = `usage: orc extra resolve <score 0-100> [--role <r>] [--risk N] [--json]  |  orc extra resolve --slot <${EXTRA_SLOT_IDS.join("|")}>  (got "${scoreArg === undefined ? "" : scoreArg}")`;
    if (asJson) emitJson({ ok: false, reason: "bad-score", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const role = typeof flag("--role") === "string" ? flag("--role") : null;
  if (role && !EXTRA_ROLES_ALL.includes(role)) {
    const msg = `unknown role "${role}" (known: ${EXTRA_ROLES_ALL.join(", ")}).`;
    if (asJson) emitJson({ ok: false, reason: "bad-role", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const riskFlag = flag("--risk");
  const risk = typeof riskFlag === "string" ? Number(riskFlag) : riskFlag === true ? 1 : 0;
  const res = extraResolveFor(claudeDir, score, { role, risk });
  const code = res.resolved === "extra" ? 0 : 1;
  if (asJson) emitJson(res, code);
  if (res.resolved === "extra") {
    console.log(`\n  ${ui.color.cyan(String(score))}  →  ${ui.color.cyan(res.via)}  ${res.provider}/${res.model}  (${res.engine})`);
    console.log(ui.color.gray(`  ${res.why}`));
    console.log("  " + ui.mark.warn(res.announce));
  } else {
    console.log(`\n  ${ui.color.cyan(String(score))}  →  claude  ${res.claude.agent}  ${ui.color.gray(res.claude.band)}`);
    console.log(ui.color.gray(`  ${res.why}`));
  }
  console.log("");
  process.exit(code);
}

// ── orc extra doctor ───────────────────────────────────────────────────────
// Read-only, exit 0 clean / 1 findings. Every finding id gets a FINDING_ROUTE
// row in the panel (the v0.43.6 rule — a caution routes to the panel that can
// CLEAR it), and `orc doctor` surfaces the count and links across.
function extraDoctorFindings(claudeDir) {
  const out = [];
  const ledger = readExtra(claudeDir);
  const cfg = resolvedConfig(claudeDir);
  const cat = readCatalog();
  if (!ledger) return out;
  const add = (id, message, extra) => out.push(Object.assign({ id, severity: "warn", message }, extra || {}));

  if (cat && cat._stale)
    add(
      "extra-catalog-stale",
      `the shipped provider catalog is dated ${cat.as_of} (${cat._age_days === null ? "undated" : cat._age_days + " days"}) — a base URL may have moved.`,
      { as_of: cat.as_of, age_days: cat._age_days }
    );

  // W8 — the switch is ON and nothing has ever answered, so every dispatch
  // falls back to Claude and the setting reads ON while meaning OFF. This is the
  // report of a state `orc config set` now refuses to create, which still
  // happens when a config file is hand-edited or copied between machines.
  const gate = extraConnectedState(claudeDir);
  if (isTrue(cfg.extra_enabled) && !gate.connected)
    add("extra-enabled-unverified", `extra_enabled is true and ${gate.why} ${gate.next}`, {
      floor: gate.floor,
      profiles: gate.profiles,
    });

  for (const prof of ledger.profiles) {
    const v = extraVerifyState(prof, cfg);
    if (v.state === "UNVERIFIED")
      add("extra-unverified", `"${prof.name}" has never verified — nothing will route to it.`, { profile: prof.name });
    else if (v.state === "STALE")
      add(
        "extra-stale-verify",
        `"${prof.name}" last verified ${v.age_days}d ago (> extra_verify_max_days ${v.max_days}) — it still routes, and re-pings before wave 1.`,
        { profile: prof.name, age_days: v.age_days }
      );
    if ((prof.credential || {}).source !== "tool" && !credentialPresent(prof.credential, claudeDir)) {
      const c = prof.credential || {};
      const vault = credentialVaultState(c, claudeDir);
      if (vault && vault.state === "wiped")
        add(
          "extra-vault-wiped",
          `"${prof.name}" had its stored key deleted after ${vault.attempts_used} wrong passphrase attempts. Paste a new key from your provider.`,
          { profile: prof.name, wiped_at: vault.wiped_at }
        );
      else
        add(
          "extra-missing-key",
          c.source === "env"
            ? `"${prof.name}" reads ${c.key_name}, which is not set in this environment.`
            : `"${prof.name}" has no stored key yet.`,
          { profile: prof.name, source: c.source }
        );
    } else if ((prof.credential || {}).source === "vault") {
      // v0.52.0 — THE DEADLINE. Two findings and no more, and the restraint is
      // the design: there is deliberately NO finding for "you have not saved a
      // passphrase". An `env` or `tool` credential never needs one, and a doctor
      // that warns about a normal state is a doctor people learn to ignore (the
      // `wiki-debt` rule).
      const sess = extraSessionStateSwept(claudeDir, prof.name);
      if (sess.state === "EXPIRING")
        add(
          "extra-passphrase-expiring",
          `"${prof.name}" has its saved passphrase until ${String(sess.expires_at).slice(0, 10)} — ${sess.days_left} day(s) left. After that a run STOPS rather than falling back.`,
          { profile: prof.name, days_left: sess.days_left, expires_at: sess.expires_at }
        );
      else if (sess.state === "EXPIRED")
        out.push({
          id: "extra-passphrase-expired",
          severity: "bad",
          message: `"${prof.name}" has a vaulted key and its saved passphrase reached its deadline. This is the one \`orc extra preflight\` STOPS on.`,
          profile: prof.name,
          expires_at: sess.expires_at,
        });
      const vault = credentialVaultState(prof.credential, claudeDir);
      if (vault && vault.attempts_used > 0)
        add(
          "extra-vault-attempts",
          `"${prof.name}" has ${vault.attempts_used} failed passphrase attempts recorded — a correct unlock resets the count.`,
          { profile: prof.name, attempts_used: vault.attempts_used }
        );
    }
    if (prof.engine === "claude-shim" && !whichBin("claude"))
      add("extra-engine-unavailable", `"${prof.name}" uses engine claude-shim, but \`claude\` is not on PATH.`, {
        profile: prof.name,
        engine: "claude-shim",
      });
    // There is NO mitigation for this one, which is exactly why it is detected
    // once here rather than discovered in the middle of a wave. Managed
    // settings that pin a login method cannot coexist with a third-party
    // credential; engine `api` talks to the provider directly and is the way
    // out, so say that instead of offering a fix that cannot work.
    if (prof.engine === "claude-shim") {
      const m = managedLoginConflict();
      if (m.conflict)
        add(
          "extra-managed-login-conflict",
          `this machine's managed settings set ${m.keys.join(" and ")} (${m.path}), which cannot coexist with a third-party credential — engine claude-shim is unavailable here. Switch "${prof.name}" to engine \`api\`.`,
          { profile: prof.name, managed_settings: m.path, keys: m.keys, fixable: false }
        );
    }
    if (prof.engine === "cli" && !(prof.cli && whichBin(prof.cli.bin)))
      add(
        "extra-engine-unavailable",
        `"${prof.name}" uses engine cli, but "${(prof.cli && prof.cli.bin) || "(none)"}" is not on PATH.`,
        { profile: prof.name, engine: "cli" }
      );
    // The install pepper is one of the two halves of the key and cannot be
    // regenerated. Say that instead of offering a fix that cannot work.
    if ((prof.credential || {}).source === "vault") {
      const rec = readVault(claudeDir).records[prof.credential.key_name || prof.name];
      if (rec && rec.ciphertext && rec.pepper === "install" && !extraPepper("install").ok)
        add(
          "extra-pepper-missing",
          `"${prof.name}" is encrypted against the install pepper at ${extraPepperPath()}, which is gone. The stored key CANNOT be recovered — paste a new one.`,
          { profile: prof.name, fixable: false }
        );
    }
  }

  // v0.54.0 — TWO recovery findings, and the restraint is the design.
  //
  // A dispatch that never reported back is money spent and work half-done that
  // nothing will ever look at again unless somebody is told. It is reported
  // here and at preflight, and it is NEVER resumed automatically.
  for (const r of extraJournalListRows(claudeDir).rows) {
    if (!r.orphan) continue;
    add(
      "extra-orphan-dispatch",
      `"${r.task_id}" was dispatched to "${r.profile}" on ${String(r.started_at || "?").slice(0, 16).replace("T", " ")} and never reported back. Its lease has expired, so nothing is still running it: orc extra reconcile ${r.task_id}`,
      { task_id: r.task_id, profile: r.profile, attempt: r.attempt, started_at: r.started_at }
    );
  }
  {
    // NEVER BELOW THE SAMPLE FLOOR. A rate computed from three dispatches is
    // noise with a percent sign on it, and a doctor that warns about noise is a
    // doctor people learn to ignore (the `wiki-debt` STALE-only restraint).
    const rel = extraReliability(claudeDir, extraStatsScan(claudeDir));
    for (const g of rel.profiles) {
      if (g.sample_too_small || g.failure_rate === null || g.failure_rate <= EXTRA_UNRELIABLE_RATE) continue;
      add(
        "extra-profile-unreliable",
        `"${g.profile}" failed or never reported back on ${g.failed + g.orphaned} of ${g.dispatches_total} dispatches (${Math.round(
          g.failure_rate * 100
        )}%). Attribution: provider ${g.attribution.provider} · network ${g.attribution.network} · local ${g.attribution.local} · worker ${g.attribution.worker} · orc ${g.attribution.orc}.`,
        {
          profile: g.profile,
          dispatches: g.dispatches_total,
          failed: g.failed,
          orphaned: g.orphaned,
          failure_rate: g.failure_rate,
          attribution: g.attribution,
        }
      );
    }
  }

  // v1.0.0 W5 — THE DEMOTED RUN. One finding, and it is deliberately not two:
  // a demotion is a state a human clears, so there is nothing to say about it
  // beyond which run, which profile, and the command that clears it. It routes
  // to the Extra panel's Recovery tab — the panel that can CLEAR it.
  {
    const dem = extraDemotionCached(claudeDir, cfg);
    if (dem && dem.demoted)
      add(
        "extra-demoted-run",
        `run ${dem.run} has DEMOTED ${dem.demoted_profiles.join(", ")} — ${dem.reasons
          .map((r) => r.why)
          .join(" ")} Foreign work in that run is staying on Claude until you promote it back: orc extra promote ${dem.run} --reason "<why>"`,
        { run: dem.run, profiles: dem.demoted_profiles, reasons: dem.reasons, fix_command: `orc extra promote ${dem.run} --reason "<why>"` }
      );
  }

  for (let i = 0; i < ledger.routes.length; i++)
    for (let j = i + 1; j < ledger.routes.length; j++)
      if (bandsOverlap(ledger.routes[i], ledger.routes[j]))
        add(
          "extra-route-overlap",
          `route rows ${bandLabel(ledger.routes[i])} and ${bandLabel(ledger.routes[j])} overlap — the resolver takes the first match, which is not a decision anybody made.`,
          { rows: [bandLabel(ledger.routes[i]), bandLabel(ledger.routes[j])] }
        );

  for (const r of ledger.routes) {
    const prof = extraProfile(ledger, r.profile);
    if (prof && prof.models_seen.length && !prof.models_seen.includes(r.model))
      add(
        "extra-model-gone",
        `${bandLabel(r)} routes to "${r.model}", which the last ping of "${r.profile}" did not list. A vanished model is a 404 in the middle of a wave.`,
        { band: bandLabel(r), profile: r.profile, model: r.model }
      );
  }

  // v0.55.0 - THE POSITIONS. Exactly two findings, and the restraint is the
  // design: there is deliberately NO `extra-slot-missing`. Nagging a user to
  // route a slot they chose not to route is a doctor people learn to ignore -
  // an unrouted slot is Claude, and Claude is a correct answer.
  for (const sr of ledger.slots || []) {
    const prof = extraProfile(ledger, sr.profile);
    if (!prof || !prof.verified_at)
      add(
        "extra-slot-unverified-profile",
        `the ${sr.slot} position names "${sr.profile}", which ${prof ? "has lost its verification" : "no longer exists"} - that position has fallen back to Claude without you asking it to.`,
        { slot: sr.slot, profile: sr.profile, model: sr.model }
      );
    else if (prof.models_seen.length && !prof.models_seen.includes(sr.model))
      add(
        "extra-slot-model-unknown",
        `the ${sr.slot} position uses "${sr.model}", which the last ping of "${sr.profile}" did not list. A vanished model is a 404 in the middle of a wave.`,
        { slot: sr.slot, profile: sr.profile, model: sr.model }
      );
  }
  return out;
}

function extraDoctor(claudeDir) {
  const asJson = wantsJson();
  const findings = extraDoctorFindings(claudeDir);
  const code = findings.length ? 1 : 0;
  if (asJson) emitJson({ ok: !findings.length, findings, count: findings.length }, code);
  console.log(ui.header("ORC · extra doctor"));
  console.log("");
  if (!findings.length) {
    console.log("  " + ui.mark.ok("nothing to report."));
    console.log("");
    process.exit(0);
  }
  for (const f of findings) console.log("  " + ui.mark.warn(f.message) + ui.color.gray(`  [${f.id}]`));
  console.log("");
  process.exit(1);
}

// ═══════════════════════════════════════════════════════════════════════════
// ENGINE A — `claude-shim`: spawn a nested `claude` against a foreign base URL
//
// The cheapest possible bridge is not a new agent loop. It is a second `claude`
// process with a handful of environment variables overridden: the foreign model
// then drives Claude Code's own tool harness — Read / Write / Edit / Bash, the
// permission system, the whole thing — and ORC's slice, its return shape and
// its worktree-delta check all keep working unchanged.
//
// Four rules make it safe rather than merely clever:
//
//   P8  `a nested claude that inherits ORC's own hooks` has broken this
//       contract. Engine A ALWAYS passes --bare. Without it the child runs
//       .claude/settings.json's PreToolUse effort guard, runs orc-trace.js —
//       which appends SPAWN/RETURN lines into the PARENT RUN'S LIVE TRACE —
//       and loads CLAUDE.md plus every ORC skill into a foreign model's
//       context at foreign-model prices, for a slice that already carries what
//       it needs. A `-p` session shows no workspace-trust dialog either, so
//       project hooks would run in a folder nobody trusted. Standing rules
//       reach the child through --append-system-prompt-file, never through
//       discovery: what the worker knows is COMPOSED, never inherited.
//
//   P9  `a cost figure ORC did not price itself` has broken this contract.
//       The result object carries `total_cost_usd`, computed client-side
//       against ANTHROPIC's price table. On a foreign endpoint that number is
//       fiction and it looks authoritative. This engine reads the TOKEN
//       COUNTS and nothing else. Do not wire up the field sitting right there.
//
//   F3  Exit code 0 is not success. Claude Code prints an in-run failure
//       (a 401, say) as the RESULT on stdout, so `is_error` is the signal and
//       the exit code is one input among several. Hitting --max-turns exits
//       with an error too, and that is `partial`, never `failed`.
//
//   R3  Windows. `claude` is a .cmd, which spawn cannot execute without
//       shell:true — and shell:true puts arbitrary task text through cmd.exe
//       quoting, which is a correctness AND an injection hazard. CreateProcess
//       also caps a command line at 32,767 characters, which a real slice plus
//       the standing rules exceeds. Both are solved the same way and the flags
//       exist for it: the standing rules go in a FILE, the prompt goes on
//       STDIN, and we resolve the real executable instead of shelling. That
//       also makes "no secret in argv" trivially true.
// ═══════════════════════════════════════════════════════════════════════════

// spawnSync's default maxBuffer is 1 MB and this repo has already been bitten
// twice (v0.49.3 `git ls-files`, v0.49.4 the --json pipe). A stream-json
// transcript of a real task WILL exceed it, so engine A does not use a pipe at
// all: the child writes to a FILE and we read the file. This constant is the
// belt to that braces — it bounds what we are willing to read back.
const EXTRA_MAX_OUTPUT_BYTES = 256 * 1024 * 1024;

// Valid --permission-mode values, so a typo is caught here rather than by a
// child that exits 1 with a usage message nobody sees.
const CLAUDE_PERMISSION_MODES = [
  "default",
  "acceptEdits",
  "plan",
  "auto",
  "dontAsk",
  "bypassPermissions",
  "manual",
];

// The tools a foreign executor needs. The same six ORC's own executors carry —
// a slice that could not read or run a build would not be a slice.
const EXTRA_DEFAULT_TOOLS = ["Read", "Write", "Edit", "Bash", "Glob", "Grep"];
// A CLOSED set, and the closure is load-bearing rather than tidy. It is the
// last piece of argv a task slice can influence, and closing it is what makes
// the Windows shell path below safe (see spawnCmdSafe): with the prompt on
// stdin, the standing rules in a file and this list closed, every byte of the
// command line is ORC's own.
const EXTRA_TOOLS_ALLOWED = new Set([
  "Read", "Write", "Edit", "MultiEdit", "NotebookEdit",
  "Bash", "BashOutput", "KillShell",
  "Glob", "Grep", "WebFetch", "WebSearch", "TodoWrite", "Task",
]);

// ── Running the binary on Windows, without handing cmd.exe anything ────────
// `claude` on Windows is an npm shim — a .cmd. Node REFUSES to spawn a .cmd or
// .bat without `shell: true` (the CVE-2024-27980 fix), and `shell: true` puts
// the command line through cmd.exe's quoting rules, which is a correctness and
// an injection hazard for anything a task slice supplied.
//
// So we removed the hazard instead of living with it: the prompt goes on
// STDIN, the standing rules go in a FILE, `--permission-mode` is checked
// against a closed list and `--allowedTools` against EXTRA_TOOLS_ALLOWED. What
// is left in argv is short, ORC-authored flags plus two paths we created. We
// still quote every element ourselves rather than trusting the default
// joining, because a temp path on Windows routinely contains a space.
//
// Engine B needs exactly the same protection (`codex` is an npm shim too), which
// is why this is named for what it does rather than for its first caller.
// ── The stall watchdog (v0.56.1) ───────────────────────────────────────────
//
// `spawnSync` cannot have one. It blocks the event loop for the whole dispatch,
// so nothing in this process can observe the child while it runs — which is why
// a stalled worker could only ever be discovered by the wall clock, fifteen
// minutes later, wearing the wrong name (`timeout`).
//
// So engine `cli` spawns ASYNCHRONOUSLY and something watches. What it watches
// is deliberately not "is the process alive" — a stalled opencode is extremely
// alive. It watches for OBSERVABLE PROGRESS, in the three places progress can
// show up:
//
//   1. the child's stdout, which is redirected onto the journal's progress file
//      (so the measurement is a `stat`, not a buffer this process holds),
//   2. the child's stderr, which stays a pipe and is counted as it arrives,
//   3. the DECLARED FILES on disk — a worker can think for four minutes and
//      write nothing, but a worker that just wrote a file is working, whatever
//      its stream is doing.
//
// Any one of the three resets the clock. All three quiet for the whole stall
// budget is the finding.
function spawnCmdParts(bin, argv) {
  const needsShell = process.platform === "win32" && /\.(cmd|bat)$/i.test(bin);
  if (!needsShell) return { cmd: bin, args: argv, shell: false };
  const q = (s) => `"${String(s).replace(/"/g, '""')}"`;
  return { cmd: q(bin) + " " + argv.map(q).join(" "), args: [], shell: true };
}

// A .cmd shim on Windows is `cmd.exe` with the real tool as a GRANDCHILD, and
// killing cmd.exe leaves the tool running against the same repository the next
// attempt is about to resume into. `taskkill /T` is the only thing that takes
// the tree. On POSIX the child is spawned into its own process group and the
// group is signalled.
function killProcessTree(child) {
  if (!child || child.pid === undefined || child.exitCode !== null) return;
  if (process.platform === "win32") {
    try {
      spawnSync("taskkill", ["/pid", String(child.pid), "/T", "/F"], { windowsHide: true });
      return;
    } catch (_) {}
  }
  try {
    process.kill(-child.pid, "SIGTERM");
  } catch (_) {
    try {
      child.kill("SIGTERM");
    } catch (_) {}
  }
}

// The size of every declared file, plus its mtime. Cheap enough to run every
// few seconds, and it is the ONE progress signal that does not depend on the
// worker choosing to say anything.
function declaredFilesFingerprint(root, declared) {
  let acc = "";
  for (const rel of declared || []) {
    try {
      const st = fs.statSync(path.resolve(root, rel));
      acc += `${rel}:${st.size}:${st.mtimeMs};`;
    } catch (_) {
      acc += `${rel}:-;`;
    }
  }
  return acc;
}

const EXTRA_STALL_POLL_MS = 5000;

function runCliChild(bin, argv, opts, watch) {
  return new Promise((resolve) => {
    const parts = spawnCmdParts(bin, argv);
    const spawnOpts = Object.assign({}, opts, { shell: parts.shell });
    if (!parts.shell && process.platform !== "win32") spawnOpts.detached = true;
    let child;
    try {
      child = require("child_process").spawn(parts.cmd, parts.args, spawnOpts);
    } catch (e) {
      return resolve({ error: e, status: null, stderr: "", stopped_by: null, stall_ms: null, last_progress_ms: null });
    }

    let stderr = "";
    let stderrBytes = 0;
    if (child.stderr)
      child.stderr.on("data", (c) => {
        stderrBytes += c.length;
        if (stderr.length < 512 * 1024) stderr += c.toString("utf8");
      });

    // When there is no journal to redirect stdout onto, the bytes are collected
    // HERE instead — never dropped. A journal is best effort by construction
    // (it can be null), and a dispatch that silently produced no readable output
    // because ORC could not write a log file would be a far worse failure than
    // the missing log.
    let stdout = "";
    let stdoutBytes = 0;
    if (child.stdout)
      child.stdout.on("data", (c) => {
        stdoutBytes += c.length;
        if (stdout.length < EXTRA_MAX_OUTPUT_BYTES) stdout += c.toString("utf8");
      });

    let stoppedBy = null;
    let lastProgress = Date.now();
    let longestGap = 0;
    let firstByteAt = null;
    let seen = { out: -1, err: -1, files: null };

    // `true` on the very first call: the baseline is what everything after it is
    // compared AGAINST, so counting it as movement would report a first byte at
    // 0ms on every dispatch — a timeline that always says the worker started
    // instantly is a timeline nobody can read a stall out of.
    const sample = (baseline) => {
      let outSize = stdoutBytes;
      if (watch.progressFile) {
        try {
          outSize = fs.statSync(watch.progressFile).size;
        } catch (_) {}
      }
      const files = declaredFilesFingerprint(watch.root, watch.declared);
      const moved =
        outSize !== seen.out || stderrBytes !== seen.err || (seen.files !== null && files !== seen.files);
      seen = { out: outSize, err: stderrBytes, files };
      if (moved && !baseline) {
        const now = Date.now();
        longestGap = Math.max(longestGap, now - lastProgress);
        if (firstByteAt === null) firstByteAt = now;
        lastProgress = now;
      }
      return moved;
    };
    sample(true); // establish the baseline WITHOUT counting it as movement

    const wall = setTimeout(() => {
      stoppedBy = "wall";
      killProcessTree(child);
    }, watch.wall_ms);

    let poll = null;
    if (watch.stall_ms > 0) {
      poll = setInterval(() => {
        sample();
        if (Date.now() - lastProgress >= watch.stall_ms) {
          stoppedBy = "stall";
          clearInterval(poll);
          poll = null;
          killProcessTree(child);
        }
      }, Math.min(EXTRA_STALL_POLL_MS, Math.max(1000, Math.floor(watch.stall_ms / 4))));
    }

    const done = (status, err) => {
      clearTimeout(wall);
      if (poll) clearInterval(poll);
      sample();
      resolve({
        error: err || null,
        status,
        stdout,
        stderr,
        stopped_by: stoppedBy,
        // The timeline, for `orc extra health` and for the failure report. A
        // stall report that cannot say how long the worker was quiet is a
        // report nobody can tune a budget from.
        stall_ms: Date.now() - lastProgress,
        longest_gap_ms: longestGap,
        first_byte_ms: firstByteAt === null ? null : firstByteAt - watch.started,
        last_progress_ms: lastProgress - watch.started,
      });
    };
    child.on("error", (e) => done(null, e));
    child.on("close", (code) => done(code === null ? null : code, null));
  });
}

function spawnCmdSafe(bin, argv, opts) {
  const needsShell = process.platform === "win32" && /\.(cmd|bat)$/i.test(bin);
  if (!needsShell) return spawnSync(bin, argv, opts);
  const q = (s) => `"${String(s).replace(/"/g, '""')}"`;
  return spawnSync(q(bin) + " " + argv.map(q).join(" "), Object.assign({}, opts, { shell: true }));
}

// ── The three timeouts, DERIVED from one key ───────────────────────────────
// Claude Code's own API_TIMEOUT_MS defaults to 600s and its byte-level stream
// watchdog to 300s. ORC's extra_timeout_s defaults to 900. Left independent,
// ORC's timeout never fires first and every stall is reported by whichever
// child timer happened to win — so the user tunes a number that does nothing.
// Ordered here, once: idle < api < wall.
function extraTimeouts(cfg) {
  // THE TEST SEAM, and it is deliberately the ONLY one (v1.0.0 W0).
  //
  // Two 30-second floors live in this function: the shortest wall clock a
  // dispatch may have, and the shortest stall budget that may fire. They are
  // product rules and they stay — but they also mean the two watchdog tests
  // have to SLEEP for 37 s and 32 s to prove a classification, which was 77 s
  // of the suite's 328 s wall clock and not one millisecond of it computing
  // anything. What those tests assert is the DECISION, not the duration.
  //
  // So the floor — and the gap the stall clock must keep under the wall clock,
  // which is derived from it — is injectable. Unset, this is byte-identical to
  // the shipped behaviour: 30 000 and 15 000. Nothing in ORC ever sets it; only
  // a test does, and it says so in its own words when it does.
  const FLOOR_MS = Math.max(1, Number(process.env.ORC_TEST_BUDGET_FLOOR_MS) || 30000);
  const GAP_MS = Math.floor(FLOOR_MS / 2);
  const wall = Math.max(FLOOR_MS / 1000, Number(cfg.extra_timeout_s) || 900) * 1000;
  const api = Math.min(wall, Math.max(60000, wall - 60000));
  const idle = Math.max(10000, Math.min(300000, api - 30000, 1800000));
  // v0.56.1 — THE FOURTH TIMEOUT, and the only one that measures the WORKER
  // rather than a socket. A wall clock cannot tell a worker that is thinking
  // hard from one that stopped: both look like 900 seconds of nothing. The
  // stall clock is reset by OBSERVABLE PROGRESS — new bytes on the worker's own
  // stream, new bytes on its stderr, or a declared file that changed on disk —
  // so it fires only when nothing at all is happening.
  //
  // Ordered with the rest, once: stall < idle < api < wall. A stall budget at
  // or past the wall clock can never fire, so it is CLAMPED rather than
  // honoured, and the clamp is reported by `orc extra health`.
  const raw = cfg.extra_stall_s === undefined ? 180 : Number(cfg.extra_stall_s);
  const asked = !Number.isFinite(raw) || raw <= 0 ? 0 : raw * 1000;
  // STRICTLY under the wall clock, and never below the 30s floor. Those two
  // rules can disagree — a 30-second wall clock leaves no room for either — and
  // when they do the stall clock is simply OFF. Two timers that fire at the same
  // instant would report whichever won the race, which is exactly the "three
  // timeouts disagreeing about which one fires first" bug this function exists
  // to prevent; the wall clock is the one that must win a tie, because it is
  // the budget the user set.
  const fitted = Math.min(asked, wall - GAP_MS);
  const stall = asked === 0 || fitted < FLOOR_MS ? 0 : fitted;
  return {
    wall_ms: wall,
    api_ms: api,
    idle_ms: idle,
    stall_ms: stall,
    stall_clamped: asked > 0 && stall !== asked,
    // WHY it is off, when it is off and the user asked for one. A budget that
    // silently does nothing is the failure mode; a budget that says "your wall
    // clock is too short for me" is a thing somebody can act on.
    stall_off_reason:
      asked > 0 && stall === 0
        ? `extra_stall_s (${Math.round(asked / 1000)}s) cannot fit under extra_timeout_s (${Math.round(
            wall / 1000
          )}s) with the ${Math.round(FLOOR_MS / 1000)}s floor, so the wall clock is the only stop.`
        : null,
  };
}

// ── Managed settings (F4, last row) ────────────────────────────────────────
// A machine whose managed settings pin `forceLoginMethod` / `forceLoginOrgUUID`
// CANNOT also use ANTHROPIC_API_KEY, ANTHROPIC_AUTH_TOKEN or an apiKeyHelper —
// the two are mutually exclusive by policy, so engine A is simply unavailable
// here. There is no mitigation, which is exactly why this is detected once and
// reported as a finding rather than discovered mid-wave.
function managedSettingsPath() {
  if (process.platform === "win32") return "C:\\ProgramData\\ClaudeCode\\managed-settings.json";
  if (process.platform === "darwin") return "/Library/Application Support/ClaudeCode/managed-settings.json";
  return "/etc/claude-code/managed-settings.json";
}
function managedLoginConflict() {
  const p = managedSettingsPath();
  try {
    const s = JSON.parse(fs.readFileSync(p, "utf8"));
    const keys = ["forceLoginMethod", "forceLoginOrgUUID"].filter((k) => s[k] !== undefined && s[k] !== null);
    if (keys.length) return { conflict: true, path: p, keys };
  } catch (_) {}
  return { conflict: false, path: p, keys: [] };
}

// ── The env matrix ─────────────────────────────────────────────────────────
// Every variable here earns its line, and several of them are the difference
// between "works" and "404s in the middle of a wave".
function extraShimEnv(prof, route, key, cfg, timeouts) {
  const models = extraModelMap(prof, route);
  const env = {
    // The endpoint. EVERY request the child makes — its own sub-loops and its
    // background calls included — goes here.
    ANTHROPIC_BASE_URL: prof.anthropic_base_url,

    // The credential, through `env` ONLY — never argv, which is world-readable
    // in a process list. The VARIABLE NAME decides the header: AUTH_TOKEN ->
    // `Authorization: Bearer`, API_KEY -> `x-api-key`. Ollama's /v1/messages
    // rejects x-api-key, which is why this is data on the profile and not a
    // constant here. Prefer AUTH_TOKEN where a provider accepts both: a key
    // that was once declined in an interactive session is ignored afterwards
    // WITHOUT ASKING AGAIN, and that failure is invisible.
    [prof.auth_env || "ANTHROPIC_AUTH_TOKEN"]: key,

    // SIX model variables, not one. Claude Code resolves ALIASES independently
    // of the session model and makes background calls on the `haiku` alias
    // (title generation, small utility turns). Setting only ANTHROPIC_MODEL
    // leaves those pointing at a model the foreign provider has never heard
    // of, and the failure lands mid-wave rather than at dispatch.
    ANTHROPIC_MODEL: models.primary,
    ANTHROPIC_DEFAULT_OPUS_MODEL: models.primary,
    ANTHROPIC_DEFAULT_SONNET_MODEL: models.primary,
    ANTHROPIC_DEFAULT_FABLE_MODEL: models.primary,
    ANTHROPIC_DEFAULT_HAIKU_MODEL: models.small,
    // D10 — SET it rather than leaving it `inherit`. It overrides both the
    // per-invocation model parameter and a subagent's own frontmatter, which
    // is how a foreign worker's own sub-dispatches stay foreign and
    // predictable instead of silently trying to reach Anthropic.
    CLAUDE_CODE_SUBAGENT_MODEL: models.small,

    // F4's mitigations, set up front because every one of them is a 400 that
    // reads like a mystery when you meet it live.
    //
    // Claude Code sends `thinking: {"type":"adaptive"}` and treats an
    // UNRECOGNISED model id — i.e. every foreign one — as a current model that
    // receives the field. The shim's upstream rejects it: `Input tag
    // 'adaptive' found`.
    CLAUDE_CODE_DISABLE_ADAPTIVE_THINKING: "1",
    // Pre-release beta body fields (`context_management`, `output_config`,
    // unknown tool-schema fields) that a third-party upstream answers with
    // `Extra inputs are not permitted`.
    CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS: "1",
    // D11 — every gateway request otherwise carries a system-prompt
    // attribution block (client version + a conversation fingerprint) that a
    // non-Anthropic upstream receives AS PART OF THE PROMPT. Turning it off
    // improves foreign cache reuse and keeps a client fingerprint out of a
    // third party's context. It is a COMPATIBILITY flag with a privacy side
    // effect and Anthropic's own docs say so — never sell it as a privacy
    // control.
    CLAUDE_CODE_ATTRIBUTION_HEADER: "0",
    // Claude Code assumes a context window for an unrecognised id, so it
    // compacts too early or too late. A known window is better; where the
    // catalog has none, stop it enforcing a guess.
    ...(models.context_tokens
      ? { CLAUDE_CODE_MAX_CONTEXT_TOKENS: String(models.context_tokens) }
      : { CLAUDE_CODE_DISABLE_UNKNOWN_MODEL_WINDOW_ENFORCEMENT: "1" }),

    // The three timeouts, ordered so ORC's own wall clock is the LAST to fire
    // and every earlier stall arrives as a classifiable child error.
    API_TIMEOUT_MS: String(timeouts.api_ms),
    CLAUDE_BYTE_STREAM_IDLE_TIMEOUT_MS: String(timeouts.idle_ms),

    // Never let a foreign dispatch inherit the parent run's trace pointer or
    // its update check. --bare already skips hook discovery; this is the
    // belt to that braces.
    ORC_NO_UPDATE_CHECK: "1",
    CI: "true",
  };
  return { env, models };
}

// The model map (F2). `routes[].model` is the primary; the CHEAP companion is
// what background calls land on. Where the user has not named one we fall back
// to the primary and SAY SO — "we sent your background calls to the expensive
// model" is a cost surprise, and removing cost surprises is what this whole
// subsystem is for.
function extraModelMap(prof, route) {
  const primary = route.model;
  const small = (route && route.small_model) || (prof.model_map && prof.model_map.haiku) || null;
  const cat = readCatalog();
  const row = catalogRow(cat, prof.provider);
  return {
    primary,
    small: small || primary,
    small_source: small ? "route" : "primary",
    small_note: small
      ? null
      : "no cheap companion model is configured, so background calls (title generation, small utility turns) go to the PRIMARY model. `orc extra route set <band> <profile>/<model> --small-model <cheap-id>` fixes the cost.",
    context_tokens: (row && row.context_tokens) || prof.context_tokens || null,
  };
}

// ── Failure classification (P6) ────────────────────────────────────────────
// `system/api_retry` events under --output-format stream-json carry a closed
// set of `error` values plus attempt / max_retries / retry_delay_ms. That is a
// READY-MADE classifier and it is the reason this engine prefers stream-json
// over json: without it, every failure is "the child exited non-zero" and ORC
// has to guess whether retrying could possibly help.
//
// `retry` = retrying THIS profile could work. `fallback` = go to the Claude
// band this task would have had. A failure is never a dead run either way
// (P6); this only decides whether we spend another call finding that out.
const EXTRA_FAILURES = {
  rate_limit: { retry: true, label: "the provider rate-limited this key" },
  overloaded: { retry: true, label: "the provider is overloaded" },
  server_error: { retry: true, label: "the provider returned a server error" },
  timeout: { retry: true, label: "no answer inside the dispatch timeout" },
  authentication_failed: { retry: false, label: "the credential was rejected" },
  model_not_found: { retry: false, label: "the provider does not serve this model id" },
  billing_error: { retry: false, label: "the provider reports a billing problem" },
  invalid_request: { retry: false, label: "the provider rejected the request shape" },
  oauth_org_not_allowed: { retry: false, label: "this organisation may not use this endpoint" },
  max_output_tokens: { retry: false, label: "the reply hit the output-token ceiling" },
  "managed-login-conflict": { retry: false, label: "this machine's managed settings forbid a third-party credential" },
  "engine-unavailable": { retry: false, label: "the engine's binary is not on PATH" },
  "spawn-failed": { retry: false, label: "the worker process could not be started" },
  "malformed-return": { retry: true, label: "the worker's return did not parse" },
  // Engine C reaches the network itself, so it produces two answers engine A
  // never sees. They live in the SAME taxonomy so `retry` means the same thing
  // whichever engine said it, and /orc-retro can aggregate across both.
  unreachable: { retry: true, label: "the endpoint could not be reached" },
  // v0.54.0 — THE TWO ROWS THAT MAKE A RECOVERY CHOOSABLE.
  //
  // `unreachable` says the connection NEVER OPENED, which means nothing was
  // written and a fresh dispatch is correct. A connection that opened, served
  // three tool calls and then died leaves a half-changed repository, and those
  // two want OPPOSITE recoveries. A taxonomy that returns the same word for both
  // cannot pick either, which is why until now there was only one.
  "stream-interrupted": { retry: true, label: "the connection was established and then died mid-response" },
  // The same shape, with the unauthenticated network probe ALSO failing. This is
  // the row that must never quietly fall back to Claude: a fallback that cannot
  // succeed is a second failure and a second cost for nothing.
  "connection-lost-local": { retry: true, label: "the connection dropped and this machine could not reach the network either" },
  "redirect-refused": { retry: false, label: "the endpoint redirected, and a credential must never follow one" },
  "response-truncated": { retry: true, label: "the reply exceeded the response ceiling" },
  // v0.56.1 — THE ROW FOR A WORKER THAT IS STILL ALIVE AND DOING NOTHING.
  //
  // `timeout` says the whole dispatch budget ran out, which is a statement
  // about ORC's patience. `stalled` says the worker went quiet: no new bytes on
  // its stream, no new bytes on stderr, and no declared file changed, for the
  // whole stall budget. The process was up the entire time — an opencode
  // session that stops mid-task and waits for a human to type "continue" looks
  // exactly like this, and reporting it as `timeout` hid that it was a
  // RESUMABLE position rather than a budget somebody should raise.
  //
  // Retryable, and that is the point: `extra_resume` turns it into a
  // continuation slice carrying what is already on disk, which is ORC's own
  // spelling of typing "continue".
  stalled: { retry: true, label: "the worker went quiet and stopped changing anything" },
  unknown: { retry: false, label: "the worker failed and said nothing ORC can classify" },
};
const classifyFailure = (k) => EXTRA_FAILURES[k] || EXTRA_FAILURES.unknown;

// stream-json is newline-delimited events. We want three things out of it and
// nothing else: the final `result`, every `system`/`api_retry` (the classifier),
// and whether a tool round trip ever completed (the fidelity measurement).
function parseStreamJson(text) {
  // `tool_names` is additive and exists for ONE consumer: the journal, which
  // has to be able to say WHICH tool the worker last ran. It is collected in the
  // walk that is already happening rather than in a second pass, because two
  // walks over the same bytes is two ideas of what an event is.
  const out = { result: null, retries: [], tool_uses: 0, tool_results: 0, events: 0, init: null, tool_names: [] };
  for (const line of String(text).split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t[0] !== "{") continue;
    let e;
    try {
      e = JSON.parse(t);
    } catch (_) {
      continue;
    }
    out.events++;
    if (e.type === "result") out.result = e;
    if (e.type === "system" && e.subtype === "init") out.init = e;
    if (e.type === "system" && (e.subtype === "api_retry" || e.error))
      out.retries.push({
        error: e.error || null,
        attempt: e.attempt === undefined ? null : e.attempt,
        max_retries: e.max_retries === undefined ? null : e.max_retries,
        retry_delay_ms: e.retry_delay_ms === undefined ? null : e.retry_delay_ms,
      });
    // Tool fidelity is measured, never assumed: a shim that mangles tool_use /
    // tool_result blocks is the known weak spot of this whole transport.
    const content = (e.message && e.message.content) || e.content;
    if (Array.isArray(content))
      for (const b of content) {
        if (b && b.type === "tool_use") {
          out.tool_uses++;
          out.tool_names.push({
            name: b.name || null,
            path: (b.input && (b.input.file_path || b.input.path || b.input.notebook_path)) || null,
          });
        }
        if (b && b.type === "tool_result") out.tool_results++;
      }
  }
  return out;
}

// The four token kinds, NEVER blended (the /orc-budget rule). A shim that
// ignores cache_control reports cache_read 0, and THAT IS A REAL MEASUREMENT,
// not missing data — /orc-retro must not read a fidelity problem as a gap.
function extraUsageVector(usage) {
  const u = usage || {};
  return {
    input: Number(u.input_tokens || 0),
    cache_write: Number(u.cache_creation_input_tokens || 0),
    cache_read: Number(u.cache_read_input_tokens || 0),
    output: Number(u.output_tokens || 0),
  };
}

// ══ THE JOURNAL (v0.54.0) ══════════════════════════════════════════════════
//
// A failed foreign dispatch is a POSITION, not a blank page. `a lane that
// re-does work the worktree already contains` has broken this contract — and
// the only way any lane can know what the worktree already contains is if
// somebody wrote down what it looked like BEFORE a third party touched it.
//
// WRITTEN BY `orc extra dispatch`, INCREMENTALLY, AND BY NOTHING ELSE. That is
// the v0.53.2 spend-log rule applied a second time and for the same reason: a
// fact that reaches disk by being relayed through a model's memory is a fact
// this repo has already lost three times (v0.32.0 narration, v0.53.2 spend).
// No lane writes the journal, no lane can forget it, no lane can reshape it.
//
// BEST EFFORT BY CONSTRUCTION. A journal that cannot be written never takes the
// dispatch down with it — the same clause that already guards appendExtraSpend.
// Every function here swallows its own errors and answers null/false.
//
// It lives in `.claude/orc/`, NOT under {run_dir}: the bridge does not know the
// run slug, and a crashed session is exactly the moment nobody remembers it.
// One directory, one reader, findable by task id alone. `isPrunable` can never
// match it (the ui.lock rule) — this is run state ORC wrote, not payload the
// installer owns.
const EXTRA_JOURNAL_DIR = "extra-journal";
const EXTRA_JOURNAL_TTL_DAYS = 30;

// DECLARED PER ENGINE, AND NEVER RENDERED STRONGER THAN IT IS (the
// `reports_model: false` restraint). Engine `cli` hands its own tools to its own
// harness, so ORC can capture the bytes and cannot interpret them until the
// adapter parses them. A gap that is not reported reads as a capability, so the
// fidelity rides in the HEADER and every consumer prints it.
const EXTRA_JOURNAL_FIDELITY = {
  api: "per-turn",
  "claude-shim": "per-turn",
  cli: "streamed-opaque",
};
const EXTRA_JOURNAL_FIDELITY_NOTE = {
  "per-turn": "every turn and every tool call was recorded as it happened.",
  "streamed-opaque":
    "the child's own output was captured verbatim; ORC did not interpret it, so there is NO per-turn tool attribution here — only bytes.",
};

const extraJournalRoot = (claudeDir) => path.join(claudeDir, "orc", EXTRA_JOURNAL_DIR);

// A task id arrives on a slice FILE, so it is untrusted input about to become a
// path segment. It is sanitised, never trusted — and an id that sanitises to
// nothing gets NO journal rather than a directory called "".
function extraJournalSlug(taskId) {
  const safe = String(taskId == null ? "" : taskId)
    .trim()
    .replace(/[^A-Za-z0-9._-]+/g, "-")
    .replace(/^[-.]+/, "")
    .replace(/[-.]+$/, "")
    .slice(0, 80);
  return safe || null;
}

function extraJournalPathsIn(dir, attempt) {
  const n = Math.max(1, Number(attempt) || 1);
  const nn = String(n).padStart(2, "0");
  return {
    slug: path.basename(dir),
    dir,
    attempt: n,
    header: path.join(dir, `attempt-${nn}.json`),
    progress: path.join(dir, `attempt-${nn}.progress.jsonl`),
    result: path.join(dir, `attempt-${nn}.result.json`),
  };
}

function extraJournalPaths(claudeDir, taskId, attempt) {
  const slug = extraJournalSlug(taskId);
  if (!slug) return null;
  return extraJournalPathsIn(path.join(extraJournalRoot(claudeDir), slug), attempt);
}

// A RESUME IS A NEW ATTEMPT, NEVER AN OVERWRITE. The previous attempt holds the
// only record of what the repository looked like before anyone touched it, so
// nothing may ever write over it.
function extraJournalNextAttempt(claudeDir, taskId) {
  const slug = extraJournalSlug(taskId);
  if (!slug) return 1;
  let max = 0;
  try {
    for (const name of fs.readdirSync(path.join(extraJournalRoot(claudeDir), slug))) {
      const m = /^attempt-(\d+)\.json$/.exec(name);
      if (m) max = Math.max(max, Number(m[1]));
    }
  } catch (_) {}
  return max + 1;
}

// Line counts are the ones a human counts: a trailing newline TERMINATES the
// last line, it does not begin an empty one.
const extraCountLines = (s) => (s.length ? s.split("\n").length - (s.endsWith("\n") ? 1 : 0) : 0);

function extraFileFacts(abs) {
  try {
    const buf = fs.readFileSync(abs);
    return {
      exists: true,
      sha256: crypto.createHash("sha256").update(buf).digest("hex"),
      lines: extraCountLines(buf.toString("utf8")),
      bytes: buf.length,
    };
  } catch (_) {
    return { exists: false, sha256: null, lines: 0, bytes: 0 };
  }
}

// `gitIn` returns null for an EMPTY stdout, which is exactly what a clean
// `git status --short` produces — so "clean tree" and "not a git repository"
// would be the same answer, and a baseline cannot afford to confuse them.
function extraGitLines(root, argv) {
  const r = spawnSync("git", argv, { cwd: root, encoding: "utf8", maxBuffer: GIT_MAX_BUFFER });
  if (r.error || r.status !== 0) return { ok: false, lines: [] };
  return {
    ok: true,
    lines: String(r.stdout || "")
      .split(/\r?\n/)
      .filter((l) => l.trim().length),
  };
}

// THE BASELINE — the file that makes a reconciliation possible at all.
//
// `files` covers `declared_files` ONLY. Hashing the whole worktree is unbounded
// work for a question nobody asks; a change OUTSIDE the fence is §6's job, and
// §6 reads `git status --short`, which is here in full.
function extraBaseline(root, declaredFiles) {
  const files = {};
  for (const rel of Array.isArray(declaredFiles) ? declaredFiles : []) {
    const p = String(rel);
    files[p] = extraFileFacts(path.resolve(root, p));
  }
  // `--untracked-files=all`, NOT the default. `git status --short` COLLAPSES an
  // untracked directory into a single `?? src/routes/` row, so a declared file
  // created inside a new directory is never named — and the fence check then
  // reports the directory as an undeclared change, which is a false breach on
  // the single most ordinary thing a worker does. The baseline and the later
  // comparison must use the SAME command, or the set difference between them is
  // comparing two different questions.
  const g = extraGitLines(root, ["status", "--short", "--untracked-files=all"]);
  return {
    head: gitIn(root, ["rev-parse", "HEAD"]) || null,
    git: g.ok,
    git_status: g.ok ? g.lines : null,
    git_status_note: g.ok
      ? null
      : "not a git repository (or git is not on PATH), so a write OUTSIDE declared_files cannot be detected from here.",
    files,
  };
}

// Written AFTER the credential and the slot resolve and BEFORE the first byte
// leaves the machine. Returns the paths, or null when the journal could not be
// opened — in which case the dispatch proceeds exactly as it did in 0.53.4.
function extraJournalHeader(claudeDir, hdr) {
  const paths = extraJournalPaths(claudeDir, hdr && hdr.task_id, hdr && hdr.attempt);
  if (!paths) return null;
  try {
    fs.mkdirSync(paths.dir, { recursive: true });
    fs.writeFileSync(paths.header, JSON.stringify(hdr, null, 2) + "\n", "utf8");
    // The progress file EXISTS from the header onward, empty. "the log is
    // empty" and "the dispatch never got that far" are different facts and must
    // never look the same on disk.
    fs.appendFileSync(paths.progress, "", "utf8");
    return paths;
  } catch (_) {
    return null;
  }
}

function extraJournalAppend(paths, obj) {
  if (!paths) return false;
  try {
    fs.appendFileSync(
      paths.progress,
      JSON.stringify(Object.assign({ t: new Date().toISOString() }, obj)) + "\n",
      "utf8"
    );
    return true;
  } catch (_) {
    return false;
  }
}

function extraJournalResult(paths, payload) {
  if (!paths) return false;
  try {
    fs.writeFileSync(paths.result, JSON.stringify(payload, null, 2) + "\n", "utf8");
    return true;
  } catch (_) {
    return false;
  }
}

// ── Retention ──────────────────────────────────────────────────────────────
// Swept on the next `orc extra dispatch`, memoised per process. FIXED at 30
// days after a `done` close, no config key — the spend-log reasoning verbatim:
// a record you can switch off is off on the run you needed it for, and 30 days
// of a few kB per task is not a problem anyone has.
//
// A directory is a candidate ONLY when EVERY attempt in it closed `done`. An
// attempt with a header and no result is an ORPHAN, which is the one thing this
// whole subsystem exists to find, so it is never swept however old it is.
function extraJournalAttemptList(dir) {
  const out = [];
  let names = [];
  try {
    names = fs.readdirSync(dir);
  } catch (_) {
    return out;
  }
  for (const name of names) {
    const m = /^attempt-(\d+)\.json$/.exec(name);
    if (m) out.push(extraJournalPathsIn(dir, Number(m[1])));
  }
  return out.sort((a, b) => a.attempt - b.attempt);
}

function extraJournalNewestMs(dir) {
  let newest = 0;
  try {
    for (const name of fs.readdirSync(dir)) {
      try {
        newest = Math.max(newest, fs.statSync(path.join(dir, name)).mtimeMs);
      } catch (_) {}
    }
  } catch (_) {}
  return newest;
}

function extraJournalPrunable(dir, cutoffMs) {
  const attempts = extraJournalAttemptList(dir);
  const newest = extraJournalNewestMs(dir);
  if (!attempts.length)
    return { prunable: false, why: "no attempt header — this is not a journal directory", attempts: 0, newest_ms: newest };
  for (const a of attempts) {
    let r = null;
    try {
      r = JSON.parse(fs.readFileSync(a.result, "utf8"));
    } catch (_) {}
    if (!r)
      return {
        prunable: false,
        why: `attempt ${a.attempt} never reported back — an orphan is never swept`,
        attempts: attempts.length,
        newest_ms: newest,
      };
    if (r.outcome !== "done")
      return {
        prunable: false,
        why: `attempt ${a.attempt} closed \`${r.outcome}\`, not \`done\``,
        attempts: attempts.length,
        newest_ms: newest,
      };
  }
  if (newest >= cutoffMs)
    return {
      prunable: false,
      why: `every attempt closed \`done\`, but the newest file here is ${Math.floor(
        (Date.now() - newest) / 86400000
      )} days old and the floor is ${EXTRA_JOURNAL_TTL_DAYS}`,
      attempts: attempts.length,
      newest_ms: newest,
    };
  return {
    prunable: true,
    why: `every attempt closed \`done\` and nothing here has changed in ${EXTRA_JOURNAL_TTL_DAYS}+ days`,
    attempts: attempts.length,
    newest_ms: newest,
  };
}

let EXTRA_JOURNAL_SWEPT = false;
function extraJournalSweep(claudeDir) {
  if (EXTRA_JOURNAL_SWEPT) return null;
  EXTRA_JOURNAL_SWEPT = true;
  const root = extraJournalRoot(claudeDir);
  const cutoff = Date.now() - EXTRA_JOURNAL_TTL_DAYS * 86400000;
  const removed = [];
  let names = [];
  try {
    names = fs.readdirSync(root);
  } catch (_) {
    return { root, scanned: 0, removed };
  }
  for (const name of names) {
    const dir = path.join(root, name);
    try {
      if (!fs.statSync(dir).isDirectory()) continue;
    } catch (_) {
      continue;
    }
    if (!extraJournalPrunable(dir, cutoff).prunable) continue;
    try {
      fs.rmSync(dir, { recursive: true, force: true });
      removed.push(name);
    } catch (_) {}
  }
  return { root, scanned: names.length, removed };
}

// ══ RECONCILE + ATTRIBUTION (v0.54.0) ══════════════════════════════════════
//
// ZERO TOKENS. DETERMINISTIC. The free check runs before the paid one — the
// /orc-doc lint rule, applied here.
//
// WHAT THIS DELIBERATELY DOES NOT COMPUTE: whether a file is syntactically
// complete. No brace counter, no "the last line looks unfinished" heuristic, no
// language sniffing. /orc-doc's house-rule boundary applies verbatim — the CLI
// cannot parse intent, so it does not pretend to — and A FAKE VALIDATOR WOULD BE
// WORSE THAN NONE: a truncation detector that is right 80% of the time teaches
// people to trust it the other 20%. The checks for "is this file finished"
// already exist and are already engine-blind: the smoke gate, the TDD gate and
// the reviewer. Reconciliation's job is to point them at the right thing.

// The five verdicts, and each one carries a DIFFERENT correct recovery. That is
// the whole reason the set is closed: a verdict nobody can act on differently is
// decoration.
//
// `orc` is deliberately in the set. This subsystem asks the user to trust a
// report about a third party, and a report with no way to blame its own author
// is not a report anybody should trust — v0.53.3 was exactly an ORC bug that
// presented as a bad key.
const EXTRA_ATTRIBUTION = ["provider", "network", "local", "worker", "orc"];

// WHOSE FAULT IT WAS, mapped from the failure taxonomy that already exists plus
// the one new fact the probe supplies. Every row that could plausibly be two
// things is decided by the probe, never by a guess.
const EXTRA_ATTRIBUTION_OF = {
  // The endpoint answered, and what it answered with was a refusal. A Claude
  // fallback is unaffected by any of these.
  server_error: "provider",
  overloaded: "provider",
  rate_limit: "provider",
  authentication_failed: "provider",
  billing_error: "provider",
  model_not_found: "provider",
  oauth_org_not_allowed: "provider",
  "redirect-refused": "provider",
  "response-truncated": "provider",
  // The machine. Neither route works until somebody fixes it here.
  "spawn-failed": "local",
  "engine-unavailable": "local",
  "managed-login-conflict": "local",
  // ORC composed the thing that was refused.
  invalid_request: "orc",
  // The conversation was clean and the model under-performed. The band or the
  // turn cap is wrong, which is a calibration fact and not a failure of anybody's
  // infrastructure.
  "max-turns": "worker",
  "wall-clock": "worker",
  max_output_tokens: "worker",
  "empty-diff": "worker",
  "malformed-return": "worker",
  "worker-reported-partial": "worker",
  unknown: "worker",
};

// THE THREE REASONS THAT CANNOT BE TOLD APART WITHOUT ASKING THE NETWORK.
// "your wifi is down" and "deepseek is down" produce the same socket error and
// have OPPOSITE correct responses, which is the entire justification for
// spending one unauthenticated request on the answer.
const EXTRA_PROBE_REASONS = new Set(["unreachable", "timeout", "stream-interrupted", "connection-lost-local"]);

// ONE cheap UNAUTHENTICATED request, 3 seconds, and it asks exactly one
// question: CAN THIS MACHINE REACH THAT HOST AT ALL. It is not a credential
// check and must never be read as one — ANY HTTP answer, 401 and 404 included,
// proves the network got there, which is the only thing being measured.
//
// No credential is attached, so this is the one `orc extra` request that cannot
// leak one.
async function extraNetworkProbe(prof, cat) {
  const row = catalogRow(cat, prof && prof.provider);
  const base =
    (prof && prof.engine === "claude-shim" ? prof.anthropic_base_url : prof && prof.base_url) ||
    (row && (row.api_base || row.anthropic_base)) ||
    null;
  if (!base)
    return {
      ran: false,
      reachable: null,
      url: null,
      // ABSENT IS NOT FALSE. A profile with no endpoint to probe (engine `cli`
      // on a tool that owns its own provider config) tells us NOTHING about the
      // network, and reporting that as "unreachable" would attribute a failure
      // to a user's internet on no evidence at all.
      note: "this profile names no endpoint ORC can reach, so the network was NOT measured. Absent is not the same as unreachable.",
    };
  const url = joinUrl(base, (row && row.models_path) || "/v1/models");
  const res = await extraHttp({ url, method: "GET", timeoutMs: extraProbeMs(3000), maxBytes: 64 * 1024 });
  // A REDIRECT IS A RESPONSE. extraHttp refuses to follow one, which is a
  // credential rule — but the host answered, and reachability is what is being
  // measured here.
  const answered = typeof res.status === "number" || res.reason === "redirect-refused";
  return {
    ran: true,
    reachable: answered,
    url,
    status: typeof res.status === "number" ? res.status : null,
    ms: res.ms === undefined ? null : res.ms,
    error: answered ? null : res.error || res.reason || "no answer",
    note: answered
      ? `the host answered (HTTP ${res.status || "3xx"}) without a credential, so this machine's network reached it. That says NOTHING about whether the key is good — only that the wire is up.`
      : `no answer in 3000ms without a credential (${res.error || res.reason || "no answer"}).`,
  };
}

// The verdict, the sentence, and the evidence that produced it. Never a verdict
// with no evidence: a report that cannot show its work is folklore.
function extraAttribution(header, result, probe) {
  const reason = (result && result.reason) || null;
  const outcome = (result && result.outcome) || null;
  const evidence = [];
  let verdict = null;
  let why = null;

  if (result && result.http_status) evidence.push(`the endpoint answered HTTP ${result.http_status}`);
  if (result && Array.isArray(result.api_retries) && result.api_retries.length)
    evidence.push(
      `${result.api_retries.length} in-turn retry attempt(s), last: ${result.api_retries[result.api_retries.length - 1].error}`
    );
  if (result && typeof result.turns === "number") evidence.push(`${result.turns} turn(s) completed`);
  if (result && Array.isArray(result.files_written) && result.files_written.length)
    evidence.push(`${result.files_written.length} file(s) were written before it stopped`);

  if (outcome === "done") {
    return {
      verdict: null,
      why: "this attempt finished. There is nothing to attribute.",
      evidence: [],
      fallback_would_also_fail: false,
      probe: probe || null,
    };
  }

  if (EXTRA_PROBE_REASONS.has(reason)) {
    // THE ROW THE WHOLE RELEASE IS SHAPED AROUND. The probe decides it, because
    // nothing else can.
    if (probe && probe.ran && probe.reachable === false) {
      verdict = "network";
      why = `the connection to ${header.provider || header.profile} failed, and an UNAUTHENTICATED probe of ${probe.url} also failed inside 3s. That points at this machine's network, not at the provider.`;
      evidence.push(`network probe: ${probe.error} after ${probe.ms === null ? "3000" : probe.ms}ms`);
    } else if (probe && probe.ran && probe.reachable === true) {
      verdict = "provider";
      why = `the dispatch could not complete, but an unauthenticated probe of ${probe.url} answered inside 3s — the wire is up, so this is the endpoint and not the network.`;
      evidence.push(`network probe: HTTP ${probe.status} in ${probe.ms}ms`);
    } else {
      // NOT MEASURED. The honest answer is the ambiguity itself, because
      // choosing one of the two on no evidence is how a report earns distrust.
      verdict = "provider";
      why = `the connection failed and the network was NOT measured (${(probe && probe.note) || "no probe was run"}), so this cannot be separated from a local network problem. It is reported as \`provider\` because that is the recovery that is safe to attempt — check your connection before reading it as the provider's fault.`;
      evidence.push("network probe: not run");
    }
  } else if (reason && EXTRA_ATTRIBUTION_OF[reason]) {
    verdict = EXTRA_ATTRIBUTION_OF[reason];
    const label = classifyFailure(reason).label;
    why =
      verdict === "provider"
        ? `${label} — the endpoint answered, and what it answered was a refusal.`
        : verdict === "local"
        ? `${label} — this is this machine, so neither a retry nor a Claude fallback fixes it until it is fixed here.`
        : verdict === "orc"
        ? `${label} — ORC composed the request that was refused, so this is an ORC defect and is reported as one.`
        : `${label} — the HTTP conversation was clean and the worker under-performed inside it.`;
  } else if (outcome === "partial") {
    verdict = "worker";
    why = `the dispatch was capped rather than broken (${reason || "no reason given"}): the conversation worked and the work did not finish inside it.`;
  } else {
    verdict = "worker";
    why = `the worker failed with \`${reason || "no reason"}\` and nothing in the record points at the network, the endpoint or ORC.`;
  }

  // The credential SOURCE is evidence, never a verdict. v0.53.3 was a 401 caused
  // by ORC sending a credential the profile never declared, so on a rejection the
  // one field that could name that shape is put in front of the reader — and it
  // is left to the reader, because ORC cannot tell its own bug from a bad key.
  if (reason === "authentication_failed" && result && result.credential)
    evidence.push(
      `the rejected credential came from \`${result.credential.source}\`` +
        (result.credential_override ? " — which is NOT the source this profile declares" : "")
    );

  return {
    verdict,
    why,
    evidence,
    // THE FIELD THAT CHANGES THE RECOVERY. A Claude fallback that cannot
    // succeed is a second cost for nothing.
    fallback_would_also_fail: verdict === "network" || verdict === "local",
    probe: probe || null,
  };
}

// ── The worktree, now, against the baseline ────────────────────────────────

// The HEAD blob's hash, for the ONE comparison that needs it: `reverted`.
function extraHeadBlobSha(root, rel) {
  const r = spawnSync("git", ["show", `HEAD:${rel}`], { cwd: root, maxBuffer: GIT_MAX_BUFFER });
  if (r.error || r.status !== 0 || !r.stdout) return null;
  return crypto.createHash("sha256").update(r.stdout).digest("hex");
}

// added / removed, EXACT or absent — never estimated.
//
// `created` and `deleted` are exact from the baseline's own line count. A
// `modified` file is exact only when the baseline WAS the HEAD blob, because
// that is the only case where `git diff HEAD` describes the change this dispatch
// made rather than that change plus somebody else's uncommitted edits. Anything
// else answers null and says why: unknown is not zero.
function extraNumstat(root, rel, before, now, headSha) {
  if (!before.exists && now.exists)
    return { added: now.lines, removed: 0, source: "the file did not exist at baseline, so every line in it is new" };
  if (before.exists && !now.exists)
    return { added: 0, removed: before.lines, source: "the file existed at baseline and is gone now" };
  if (before.sha256 === now.sha256) return { added: 0, removed: 0, source: "the file is byte-identical to the baseline" };
  if (headSha && before.sha256 === headSha) {
    const r = spawnSync("git", ["diff", "--numstat", "HEAD", "--", rel], { cwd: root, encoding: "utf8", maxBuffer: GIT_MAX_BUFFER });
    if (!r.error && r.status === 0) {
      const m = /^(\d+|-)\t(\d+|-)\t/.exec(String(r.stdout || "").trim());
      if (m && m[1] !== "-")
        return {
          added: Number(m[1]),
          removed: Number(m[2]),
          source: "the baseline WAS the committed blob, so `git diff --numstat HEAD` describes exactly this dispatch's change",
        };
    }
  }
  return {
    added: null,
    removed: null,
    source:
      "the file already differed from HEAD before this dispatch started, so a line count here would mix this dispatch's change with somebody else's uncommitted one. UNKNOWN, and unknown is not zero.",
  };
}

// The header's own two liveness facts. A "disconnected" dispatch is NOT provably
// dead: a client-side socket timeout does not stop a provider streaming, and a
// SIGTERM'd child may still be mid-write(). So this asks for BOTH — the pid gone,
// or the lease expired.
//
// PID REUSE IS REAL AND IS SAID OUT LOUD. Past the lease a live pid is treated
// as somebody else's process. That is an honest bound, not a proof.
function extraAttemptLive(header) {
  const leaseMs = Date.parse((header && header.lease_expires_at) || "");
  const leaseExpired = !isNaN(leaseMs) && Date.now() > leaseMs;
  let pidAlive = false;
  if (header && typeof header.pid === "number" && header.pid > 0 && header.pid !== process.pid) {
    try {
      process.kill(header.pid, 0);
      pidAlive = true;
    } catch (e) {
      // EPERM means the pid EXISTS and belongs to somebody else — alive, and not
      // ours to signal. ESRCH means it is gone.
      pidAlive = e && e.code === "EPERM";
    }
  }
  return {
    live: pidAlive && !leaseExpired,
    pid: (header && header.pid) || null,
    pid_alive: pidAlive,
    lease_expires_at: (header && header.lease_expires_at) || null,
    lease_expired: leaseExpired,
    note: leaseExpired
      ? "the lease has expired, so a live pid here is treated as SOMEBODY ELSE'S process. Pid reuse is real; this is an honest bound, not a proof."
      : null,
  };
}

// The last thing anybody saw the worker do, rendered as a sentence rather than
// as a record. `last_action` is what makes a resume preamble mean something.
function extraLastAction(lines, fidelity) {
  if (!lines.length)
    return fidelity === "streamed-opaque"
      ? "nothing was captured — this engine records BYTES, and none arrived."
      : "no tool call was ever recorded.";
  for (let i = lines.length - 1; i >= 0; i--) {
    const l = lines[i];
    if (!l || !l.tool) continue;
    const turn = l.turn ? `turn ${l.turn}${l.max_turns ? ` of ${l.max_turns}` : ""} · ` : "";
    return `${turn}${l.tool}${l.path ? " " + l.path : ""}${l.ok === true ? " · ok" : l.ok === false ? " · REFUSED" : ""}`;
  }
  const last = lines[lines.length - 1];
  if (last && last.event) return `the last recorded event was \`${last.event}\`; no tool call was ever recorded.`;
  if (last && last.model) return `turn ${last.turn || "?"} answered, and no tool call was ever recorded.`;
  return "no tool call was ever recorded.";
}

// Every parsable line, and the torn ones COUNTED. This is an append-only log a
// killed process may have cut mid-write, so one torn line must never cost the
// report every line before it.
function extraReadProgress(file) {
  let text = "";
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (_) {
    return { lines: [], unreadable: 0, exists: false };
  }
  const lines = [];
  let unreadable = 0;
  for (const raw of text.split(/\r?\n/)) {
    if (!raw.trim()) continue;
    try {
      lines.push(JSON.parse(raw));
    } catch (_) {
      unreadable++;
    }
  }
  return { lines, unreadable, exists: true };
}

// THE READ. Returns the whole computed object and an exit code — one function,
// so the human renderer and `--json` can never describe two different states.
function extraReconcileCompute(claudeDir, taskId, attemptWanted) {
  const root = repoRootOf(claudeDir);
  const slug = extraJournalSlug(taskId);
  const empty = (state, error) => ({
    ok: false,
    state,
    task_id: taskId || null,
    attempt: null,
    attempts_total: 0,
    error,
    blocked_by: null,
    _code: 2,
  });
  if (!slug) return empty("no-journal", "a task id is required: orc extra reconcile <task_id>");
  const dir = path.join(extraJournalRoot(claudeDir), slug);
  const all = extraJournalAttemptList(dir);
  if (!all.length)
    return empty(
      "no-journal",
      `no journal for task \`${taskId}\`. Either the id is wrong, or this dispatch predates the journal (orc 0.54.0) — in which case there is no baseline and today's fallback procedure is the whole of the answer.`
    );

  const paths = attemptWanted ? all.find((a) => a.attempt === Number(attemptWanted)) : all[all.length - 1];
  if (!paths) return empty("no-journal", `task \`${taskId}\` has no attempt ${attemptWanted}. It has: ${all.map((a) => a.attempt).join(", ")}.`);

  let header = null;
  try {
    header = JSON.parse(fs.readFileSync(paths.header, "utf8"));
  } catch (e) {
    return empty("no-journal", `the attempt header at ${paths.header} could not be read: ${e.message}`);
  }
  let result = null;
  try {
    result = JSON.parse(fs.readFileSync(paths.result, "utf8"));
  } catch (_) {}

  const prog = extraReadProgress(paths.progress);
  const live = extraAttemptLive(header);
  const fidelity = header.journal_fidelity || "none";

  // The per-file table. This is the position.
  const baseline = header.baseline || { files: {}, git_status: null };
  const files = [];
  const reverted = [];
  for (const rel of Object.keys(baseline.files || {})) {
    const before = baseline.files[rel];
    const now = extraFileFacts(path.resolve(root, rel));
    const headSha = baseline.git ? extraHeadBlobSha(root, rel) : null;
    let state;
    if (!before.exists && !now.exists) state = "untouched";
    else if (!before.exists && now.exists) state = "created";
    else if (before.exists && !now.exists) state = "deleted";
    else if (before.sha256 === now.sha256) state = "untouched";
    else if (headSha && now.sha256 === headSha && before.sha256 !== headSha) state = "reverted";
    else state = "modified";
    if (state === "reverted") reverted.push(rel);
    files.push({
      path: rel,
      state,
      baseline: { exists: before.exists, sha256: before.sha256, lines: before.lines },
      now: { exists: now.exists, sha256: now.sha256, lines: now.lines },
      numstat: extraNumstat(root, rel, before, now, headSha),
    });
  }

  // A FENCE BREACH, surfaced here as well as at §6 — because a crashed dispatch
  // is exactly the case where §6 never ran.
  const declared = new Set(header.declared_files || []);
  const beforeStatus = new Set(Array.isArray(baseline.git_status) ? baseline.git_status : []);
  // THE SAME COMMAND the baseline used, flags included. Two different `git
  // status` invocations answer two different questions, and a set difference
  // across them is arithmetic on incomparable rows.
  const nowStatus = baseline.git ? extraGitLines(root, ["status", "--short", "--untracked-files=all"]) : { ok: false, lines: [] };
  const touchedUndeclared = [];
  if (baseline.git && nowStatus.ok)
    for (const line of nowStatus.lines) {
      if (beforeStatus.has(line)) continue;
      const rel = line.slice(3).trim().replace(/^"|"$/g, "").split(" -> ").pop();
      if (declared.has(rel)) continue;
      // ORC'S OWN BOOKKEEPING IS NOT THE WORKER'S STRAY WRITE. The journal, the
      // spend log and engine `cli`'s work dir are all written BY THIS DISPATCH,
      // between the baseline and this read, so every dispatch would otherwise
      // report itself as a fence breach — and a fence warning that always fires
      // is a fence warning nobody reads. The exclusion is by NAME and is narrow:
      // it covers ORC's own two directories and nothing a worker could reach.
      if (/^\.claude\//.test(rel) || rel === ".claude" || rel.split("/")[0] === EXTRA_CLI_WORK) continue;
      touchedUndeclared.push({ path: rel, status_line: line });
    }

  const turnLines = prog.lines.filter((l) => typeof l.turn === "number");
  const turnsUsed = turnLines.length ? Math.max(...turnLines.map((l) => l.turn)) : 0;
  const maxTurns = (result && result.max_turns) || (turnLines.find((l) => l.max_turns) || {}).max_turns || null;

  // THE FLOOR. Read from the journal's running vector, which is the only record
  // a dispatch that never reached appendExtraSpend left behind.
  let partialUsage = null;
  for (let i = prog.lines.length - 1; i >= 0; i--)
    if (prog.lines[i] && prog.lines[i].usage) {
      partialUsage = prog.lines[i].usage;
      break;
    }

  const moved = files.some((f) => f.state !== "untouched");
  let state;
  let code;
  let blockedBy = null;
  if (live.live) {
    state = "in-flight";
    code = 4;
    blockedBy = `pid ${live.pid} is still alive and its lease does not expire until ${live.lease_expires_at}. A human decides whether that process is really working: two writers on one file is worse than a lost dispatch.`;
  } else if (result && result.outcome === "done") {
    state = "complete";
    code = 3;
  } else if (moved) {
    state = "resumable";
    code = 0;
  } else {
    state = "nothing-to-resume";
    code = 1;
  }
  if (state === "resumable" && reverted.length)
    blockedBy = `${reverted.join(", ")} came back CLOSER TO HEAD than the baseline — the §6 revert signature. A human decides whether to restore first: resuming on top of a possible destructive action is the one case where continuing is worse than starting over.`;

  return {
    ok: true,
    state,
    task_id: header.task_id || taskId || null,
    attempt: paths.attempt,
    attempts_total: all.length,
    profile: header.profile || null,
    provider: header.provider || null,
    engine: header.engine || null,
    model_requested: header.model_requested || null,
    band: header.band || null,
    score: typeof header.score === "number" ? header.score : null,
    journal: paths.header,
    journal_fidelity: fidelity,
    journal_fidelity_note: header.journal_fidelity_note || null,
    resumed_from: header.resumed_from || null,
    slice_path: header.slice_path || null,
    slice_sha256: header.slice_sha256 || null,
    started_at: header.started_at || null,
    ended_at: (result && result.ended_at) || null,
    duration_ms: (result && result.duration_ms) || null,

    outcome: (result && result.outcome) || null,
    reason: (result && result.reason) || null,
    retryable: result ? !!result.retry : null,
    // A HEADER WITH NO RESULT IS THE ORPHAN. It is the one shape this whole
    // subsystem exists to find, so it is named rather than inferred.
    reported_back: !!result,
    orphan: !result && !live.live,

    liveness: live,
    attribution: (result && result.attribution) || null,

    files,
    touched_undeclared: touchedUndeclared,
    reverted,
    git: !!baseline.git,
    git_note: baseline.git_status_note || null,

    last_action: extraLastAction(prog.lines, fidelity),
    progress_lines: prog.lines.length,
    // NAMED, ALWAYS. A report quietly short by three rows is exactly the failure
    // the spend log's `unreadable_spend_lines` exists to prevent.
    unreadable_progress_lines: prog.unreadable,
    turns_used: turnsUsed,
    max_turns: maxTurns,

    partial_usage: partialUsage,
    partial_usage_note: partialUsage
      ? "read from the journal's per-turn vector. It is a FLOOR — the true total may be higher, because the dispatch died before it could report."
      : "the journal recorded no usage vector, so there is NO figure here — not a zero one.",

    acceptance: Array.isArray(header.acceptance) ? header.acceptance : [],
    acceptance_note:
      "carried forward unevaluated — whether these are met is not a question this command can answer.",

    blocked_by: blockedBy,
    _code: code,
  };
}

const EXTRA_RECONCILE_MEANING = {
  resumable: "the worktree moved off the baseline — there is a position",
  "nothing-to-resume": "the worktree is exactly the baseline — nothing was written",
  "no-journal": "unknown task id, or a dispatch that predates the journal",
  complete: "the journal holds a `done` result",
  "in-flight": "the attempt is still alive — REFUSED",
};

function extraReconcileCmd(claudeDir, taskId) {
  const attempt = flag("--attempt");
  const v = extraReconcileCompute(claudeDir, taskId, typeof attempt === "string" ? attempt : null);
  const code = v._code;
  delete v._code;

  if (v.ok) {
    const cfg = resolvedConfig(claudeDir);
    let result = null;
    try {
      result = JSON.parse(fs.readFileSync(v.journal.replace(/\.json$/, ".result.json"), "utf8"));
    } catch (_) {}
    // WHO CONTINUES IT. Derived from the failure classification that already
    // exists plus the attribution — never a config key.
    v.resume_target = v.state === "resumable" ? extraResumeTarget(v, result, cfg) : null;
    v.next =
      v.state === "resumable" && v.resume_target && (v.resume_target.kind === "extra" || v.resume_target.kind === "claude") && !v.reverted.length
        ? `orc extra resume-slice ${v.task_id} --out <file>`
        : v.state === "nothing-to-resume"
        ? "nothing was written — re-dispatch the ORIGINAL slice (the existing fallback procedure)."
        : null;
    // The spend a killed dispatch never got to record. Written ONCE, marked, and
    // labelled a FLOOR wherever it is read.
    v.spend_recovered = extraRecoverSpend(claudeDir, v);
  }

  // An empty result is an ANSWER, so it still returns its object.
  if (wantsJson()) emitJson(v, code);

  if (!v.ok) {
    console.log("\n  " + ui.mark.warn(`${v.state} — ${EXTRA_RECONCILE_MEANING[v.state]}`));
    console.log("  " + v.error + "\n");
    process.exit(code);
  }

  const mark = v.state === "resumable" ? ui.mark.ok : v.state === "complete" ? ui.mark.ok : ui.mark.warn;
  console.log(
    "\n" +
      mark(`${v.task_id} · attempt ${v.attempt} of ${v.attempts_total} — ${v.state.toUpperCase()}`) +
      `\n  ${EXTRA_RECONCILE_MEANING[v.state]}`
  );
  console.log(`  ${v.profile}/${v.model_requested || "?"} · engine ${v.engine} · band ${v.band || "?"}`);
  if (v.outcome) console.log(`  ended: ${v.outcome}${v.reason ? " · " + v.reason : ""}${v.retryable ? " (retryable)" : ""}`);
  else console.log("  " + ui.mark.warn("this attempt NEVER REPORTED BACK — the process died before it could."));

  if (v.attribution && v.attribution.verdict) {
    console.log(`\n  attributed: ${v.attribution.verdict.toUpperCase()}`);
    console.log("  " + v.attribution.why);
    for (const e of v.attribution.evidence || []) console.log("    · " + e);
    if (v.attribution.fallback_would_also_fail)
      console.log(
        "  " + ui.mark.warn("a Claude fallback would fail too — falling back here burns a second failure and a second cost for nothing.")
      );
  }

  console.log("\n  the position:");
  for (const f of v.files) {
    const n = f.numstat.added === null ? "±?" : `+${f.numstat.added} −${f.numstat.removed}`;
    console.log(`    ${f.path} — ${f.state}${f.state === "untouched" ? "" : ` (${n})`}`);
  }
  if (!v.git) console.log("    " + ui.mark.warn(v.git_note));
  for (const t of v.touched_undeclared)
    console.log("    " + ui.mark.warn(`${t.path} — CHANGED AND NEVER DECLARED (${t.status_line})`));
  console.log(`  last action: ${v.last_action}`);
  console.log(`  fidelity: ${v.journal_fidelity} — ${v.journal_fidelity_note || ""}`);
  if (v.unreadable_progress_lines)
    console.log("  " + ui.mark.warn(`${v.unreadable_progress_lines} progress line(s) were torn and could not be read.`));
  if (v.partial_usage)
    console.log(
      `  tokens so far: ${extraTokStr(v.partial_usage)} — ${v.partial_usage_note}`
    );
  if (v.acceptance.length) {
    console.log("\n  acceptance (carried forward, UNEVALUATED):");
    for (const a of v.acceptance) console.log("    · " + a);
  }
  if (v.spend_recovered && !v.spend_recovered.already)
    console.log(
      "  " +
        ui.mark.warn(
          "this dispatch never reached the spend log, so its journal vector was recovered into it — recorded as a FLOOR (`recovered: true, complete: false`), never as a total."
        )
    );
  if (v.resume_target) {
    console.log(`\n  resume target: ${v.resume_target.kind}${v.resume_target.profile ? " " + v.resume_target.profile : v.resume_target.agent ? " " + v.resume_target.agent : ""}`);
    console.log("  " + v.resume_target.why);
  }
  if (v.blocked_by) console.log("\n  " + ui.mark.bad("BLOCKED: " + v.blocked_by));
  if (v.next) console.log("\n  " + ui.color.bold(v.next));
  console.log("");
  process.exit(code);
}

// ── orc extra journal ──────────────────────────────────────────────────────
function extraJournalListRows(claudeDir) {
  const root = extraJournalRoot(claudeDir);
  const rows = [];
  let names = [];
  try {
    names = fs.readdirSync(root);
  } catch (_) {
    return { root, rows };
  }
  const cutoff = Date.now() - EXTRA_JOURNAL_TTL_DAYS * 86400000;
  for (const name of names.sort()) {
    const dir = path.join(root, name);
    try {
      if (!fs.statSync(dir).isDirectory()) continue;
    } catch (_) {
      continue;
    }
    const attempts = extraJournalAttemptList(dir);
    if (!attempts.length) continue;
    const last = attempts[attempts.length - 1];
    let header = null;
    let result = null;
    try {
      header = JSON.parse(fs.readFileSync(last.header, "utf8"));
    } catch (_) {}
    try {
      result = JSON.parse(fs.readFileSync(last.result, "utf8"));
    } catch (_) {}
    const live = extraAttemptLive(header || {});
    const prune = extraJournalPrunable(dir, cutoff);
    rows.push({
      task_id: (header && header.task_id) || name,
      dir,
      attempts: attempts.length,
      attempt: last.attempt,
      // v1.0.0 W5 — WHICH RUN. `null` on every journal written before W5 and on
      // every dispatch made with no run open; the demotion counts those as
      // skipped rather than folding them into whichever run asks.
      run: (header && header.run) || null,
      lane: (header && header.lane) || null,
      profile: (header && header.profile) || null,
      provider: (header && header.provider) || null,
      engine: (header && header.engine) || null,
      model_requested: (header && header.model_requested) || null,
      started_at: (header && header.started_at) || null,
      journal_fidelity: (header && header.journal_fidelity) || null,
      declared_files: (header && header.declared_files) || [],
      outcome: (result && result.outcome) || null,
      reason: (result && result.reason) || null,
      reported_back: !!result,
      live: live.live,
      // The one state this listing exists to make visible.
      orphan: !result && !live.live,
      prunable: prune.prunable,
      prunable_why: prune.why,
    });
  }
  return { root, rows };
}

function extraJournalCmd(claudeDir, sub, arg) {
  const asJson = wantsJson();
  if (sub === undefined || sub === "list") {
    const { root, rows } = extraJournalListRows(claudeDir);
    const obj = {
      ok: true,
      root,
      entries: rows.length,
      orphans: rows.filter((r) => r.orphan).length,
      in_flight: rows.filter((r) => r.live).length,
      prunable: rows.filter((r) => r.prunable).length,
      retention_days: EXTRA_JOURNAL_TTL_DAYS,
      journals: rows,
    };
    if (asJson) emitJson(obj, 0);
    if (!rows.length) {
      console.log(`\n  no foreign dispatch has been journalled yet.\n  ${root}\n`);
      process.exit(0);
    }
    console.log(`\n  ${rows.length} journalled task(s) — ${root}\n`);
    for (const r of rows) {
      const state = r.live ? "IN FLIGHT" : r.orphan ? "NEVER REPORTED BACK" : (r.outcome || "?").toUpperCase();
      console.log(
        `    ${r.task_id} · ${r.profile}/${r.model_requested || "?"} · ${r.engine} · attempt ${r.attempt} of ${r.attempts} — ${state}`
      );
      console.log(`      started ${r.started_at || "?"} · ${r.declared_files.length} declared file(s) · fidelity ${r.journal_fidelity}`);
      if (r.orphan) console.log("      " + ui.mark.warn(`orc extra reconcile ${r.task_id}`));
    }
    console.log("");
    process.exit(0);
  }

  if (sub === "show") {
    const slug = extraJournalSlug(arg);
    const dir = slug ? path.join(extraJournalRoot(claudeDir), slug) : null;
    const attempts = dir ? extraJournalAttemptList(dir) : [];
    if (!attempts.length) {
      const obj = { ok: false, reason: "no-journal", task_id: arg || null, error: `no journal for task \`${arg}\`.` };
      if (asJson) emitJson(obj, 2);
      console.error("❌ " + obj.error);
      process.exit(2);
    }
    const want = flag("--attempt");
    const paths = typeof want === "string" ? attempts.find((a) => a.attempt === Number(want)) || attempts[attempts.length - 1] : attempts[attempts.length - 1];
    let header = null;
    let result = null;
    try {
      header = JSON.parse(fs.readFileSync(paths.header, "utf8"));
    } catch (_) {}
    try {
      result = JSON.parse(fs.readFileSync(paths.result, "utf8"));
    } catch (_) {}
    const prog = extraReadProgress(paths.progress);
    // `--body` is OPT-IN, one artifact at a time — the `orc wiki show` rule.
    const body = flag("--body") === true;
    let raw = null;
    if (body) {
      try {
        raw = fs.readFileSync(paths.progress, "utf8");
      } catch (_) {}
    }
    const obj = {
      ok: true,
      task_id: (header && header.task_id) || arg,
      attempt: paths.attempt,
      attempts_total: attempts.length,
      header,
      result: result
        ? {
            outcome: result.outcome,
            reason: result.reason,
            retry: result.retry,
            duration_ms: result.duration_ms,
            usage: result.usage || null,
            attribution: result.attribution || null,
          }
        : null,
      reported_back: !!result,
      progress_lines: prog.lines.length,
      unreadable_progress_lines: prog.unreadable,
      last_action: extraLastAction(prog.lines, (header && header.journal_fidelity) || "none"),
      progress: prog.lines,
      body: raw,
      body_note: body ? null : "the raw progress log is opt-in: add --body.",
    };
    if (asJson) emitJson(obj, 0);
    console.log(`\n  ${obj.task_id} · attempt ${paths.attempt} of ${attempts.length}`);
    if (header)
      console.log(
        `  ${header.profile}/${header.model_requested || "?"} · ${header.engine} · started ${header.started_at} · fidelity ${header.journal_fidelity}`
      );
    console.log(`  ${obj.reported_back ? `ended ${result.outcome}${result.reason ? " · " + result.reason : ""}` : "NEVER REPORTED BACK"}`);
    console.log(`\n  ${prog.lines.length} progress line(s)${prog.unreadable ? `, ${prog.unreadable} torn` : ""}:`);
    for (const l of prog.lines.slice(-40))
      console.log(
        `    ${l.t || "?"} · ${l.tool ? `${l.tool}${l.path ? " " + l.path : ""}` : l.event || (l.model !== undefined ? `turn ${l.turn}` : "?")}`
      );
    if (raw !== null) console.log("\n" + raw);
    console.log("");
    process.exit(0);
  }

  if (sub === "prune") {
    const { root, rows } = extraJournalListRows(claudeDir);
    const candidates = rows.filter((r) => r.prunable);
    const dry = flag("--dry-run") === true;
    const removed = [];
    if (!dry)
      for (const c of candidates) {
        try {
          fs.rmSync(c.dir, { recursive: true, force: true });
          removed.push(c.task_id);
        } catch (_) {}
      }
    const obj = {
      ok: true,
      root,
      dry_run: dry,
      retention_days: EXTRA_JOURNAL_TTL_DAYS,
      // NAMED, EVERY ONE. A count is not consent.
      candidates: candidates.map((c) => ({ task_id: c.task_id, dir: c.dir, attempts: c.attempts, why: c.prunable_why })),
      kept: rows.filter((r) => !r.prunable).map((r) => ({ task_id: r.task_id, why: r.prunable_why })),
      removed,
    };
    if (asJson) emitJson(obj, 0);
    if (!candidates.length) {
      console.log(`\n  nothing to prune. Only a journal whose EVERY attempt closed \`done\` and whose newest file is ${EXTRA_JOURNAL_TTL_DAYS}+ days old is ever a candidate.\n`);
      process.exit(0);
    }
    console.log(`\n  ${dry ? "would delete" : "deleted"} ${candidates.length} journal(s):\n`);
    for (const c of candidates) console.log(`    ${c.task_id} — ${c.dir}\n      ${c.why}`);
    if (dry) console.log("\n  run without --dry-run to delete them.");
    console.log("");
    process.exit(0);
  }

  console.error(`Unknown: orc extra journal ${sub}\n` + extraUsage());
  process.exit(1);
}

// ══ THE STALL DEMOTION (v1.0.0 W5) ═════════════════════════════════════════
//
// THE PRIORITY LADDER MOVES AT RUNTIME, AND NOTHING ELSE ABOUT IT MOVES.
//
// Two consecutive `stalled` dispatches on one profile inside one run — or one
// LIVE attempt that has shown no observable progress for `extra_demote_stale_min`
// minutes — drop that profile to the BOTTOM of its families for the remainder of
// the run. `opus5_only` (or the shipped score table) becomes the effective P0,
// and the work stays on Claude.
//
// THIS WAVE WRITES NO NEW MEASUREMENT. Every fact the trigger reads already
// ships and is already CLI-owned: `EXTRA_FAILURES.stalled` (v0.56.1), the
// `timeline` block on every engine-`cli` return (v0.56.1), and the extra journal
// written by `orc extra dispatch` itself before the first byte leaves the
// machine (v0.54.0). The demotion READS the journal and decides.
//
// It is COMPUTED FROM DISK ON EVERY READ AND NEVER REMEMBERED. That is the
// lesson this repo has now lost to four times — v0.32.0 narration, v0.49.5 the
// hand-back, v0.53.2 the spend log, v0.54.0 the journal: a fact relayed through
// a model's memory is a fact this repo has already lost. The only thing on disk
// is the HUMAN half — a `promote` or a manual `demote`, with its reason — and
// that is a decision, not a verdict.
//
// FOUR THINGS IT MUST NEVER DO, each with the rule that stops it:
//
//   1. NEVER writes `.claude/orc.config.yaml`. Run-scoped, like `/orc-ultra`'s
//      `ultra_mode`. A run that had a bad afternoon must not silently turn off a
//      subsystem the user paid to set up.
//   2. NEVER auto-promotes inside the run. Two stalls is evidence.
//      `orc extra promote <run> --reason "<why>"` is a human action and the
//      reason is stored verbatim (the /orc-pact retirement rule).
//   3. NEVER changes WHAT. The score does not move, `declared_files` is not
//      widened, `acceptance[]` is not touched — `extra_fallback_agent`'s rule
//      (v0.56.1) inherited verbatim. A demotion changes WHERE work runs.
//   4. NEVER abandons the position. A demoted run still goes
//      `orc extra reconcile` → `orc extra resume-slice` → an ORDINARY Claude
//      dispatch. `a lane that re-does work the worktree already contains`
//      (v0.54.0) applies here exactly as it applies to the fallback, and it is
//      the same code path.
//
// And it is ANNOUNCED. The mirror of `a lane that sends work off Claude without
// saying so` is a lane that quietly STOPS: a user who connected a provider
// deserves to be told the run left it.
const EXTRA_DEMOTE_FILE = "extra-demotion.json";
const EXTRA_DEMOTE_AFTER_DEFAULT = 2;
const EXTRA_DEMOTE_STALE_MIN_DEFAULT = 20;
// The closed set. `manual` is its own word because "a human demoted this" and
// "two dispatches stalled" are different facts with different fixes.
const EXTRA_DEMOTE_REASONS = ["consecutive-stall", "stale-live-attempt", "manual"];

const extraDemotePath = (claudeDir, slug) => path.join(resolveRunDir(claudeDir), slug, EXTRA_DEMOTE_FILE);

// The run this is about. A slug the caller named wins; otherwise the trace
// pointer answers, exactly as it does for the spend log. No third source — a
// second spelling of "which run" is the drift this subsystem lints for.
function extraDemoteRun(claudeDir, slugArg) {
  if (slugArg) return { slug: String(slugArg), from: "argument", lane: null };
  const cur = extraCurrentRun(claudeDir);
  if (cur && cur.slug) return { slug: cur.slug, from: "trace pointer", lane: cur.lane };
  return { slug: null, from: null, lane: null };
}

function extraDemoteOverride(claudeDir, slug) {
  if (!slug) return null;
  try {
    const j = JSON.parse(fs.readFileSync(extraDemotePath(claudeDir, slug), "utf8"));
    return j && (j.state === "demoted" || j.state === "promoted") ? j : null;
  } catch (_) {
    return null;
  }
}

// Best effort, and it says so. A run folder that does not exist yet is created —
// this is run state beside `RESUME.md` and the checkpoint, and it is deleted
// with the run.
function extraDemoteWrite(claudeDir, slug, obj) {
  try {
    const p = extraDemotePath(claudeDir, slug);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, JSON.stringify(obj, null, 2) + "\n", "utf8");
    return p;
  } catch (_) {
    return null;
  }
}

// Every CLOSED attempt this run made, oldest first, across every task. The
// journal is keyed by task and a run spans many, so the sequence has to be
// rebuilt chronologically or "consecutive" means nothing.
function extraDemoteAttempts(claudeDir, slug) {
  const root = extraJournalRoot(claudeDir);
  const closed = [];
  const live = [];
  let skipped_unattributed = 0;
  let names = [];
  try {
    names = fs.readdirSync(root);
  } catch (_) {
    return { closed, live, skipped_unattributed };
  }
  for (const name of names) {
    const dir = path.join(root, name);
    try {
      if (!fs.statSync(dir).isDirectory()) continue;
    } catch (_) {
      continue;
    }
    for (const a of extraJournalAttemptList(dir)) {
      let header = null;
      try {
        header = JSON.parse(fs.readFileSync(a.header, "utf8"));
      } catch (_) {
        continue;
      }
      // An attempt with no `run` is NOT folded into whichever run happens to be
      // asking. It is counted and named — the v0.53.2 rule that both ABSENT
      // counts are printed, because a report quietly short by three rows is the
      // exact failure that rule exists to prevent.
      if (!header.run) {
        skipped_unattributed++;
        continue;
      }
      if (header.run !== slug) continue;
      let result = null;
      try {
        result = JSON.parse(fs.readFileSync(a.result, "utf8"));
      } catch (_) {}
      const row = {
        task_id: header.task_id || name,
        attempt: a.attempt,
        profile: header.profile || null,
        provider: header.provider || null,
        engine: header.engine || null,
        model_requested: header.model_requested || null,
        started_at: header.started_at || null,
        started_ms: Date.parse(header.started_at || "") || 0,
        // A RESUME IS THE SAME STALL. It is carried so the counter can skip it
        // without pretending it did not happen.
        resumed_from: header.resumed_from || null,
        outcome: result ? result.outcome || null : null,
        reason: result ? result.reason || null : null,
      };
      if (result) closed.push(row);
      else {
        const l = extraAttemptLive(header);
        row.live = l.live;
        row.lease_expired = l.lease_expired;
        // LAST OBSERVABLE PROGRESS, off the disk: the progress file is appended
        // as the worker talks (engine `api` writes a line per turn; engine `cli`
        // streams the child's own bytes into it), so its mtime is when anything
        // last happened. `started_at` is the floor — a worker that has said
        // nothing at all has been quiet since it started, not since never.
        let mtime = 0;
        try {
          mtime = fs.statSync(a.progress).mtimeMs;
        } catch (_) {}
        row.last_progress_ms = Math.max(mtime, row.started_ms);
        row.quiet_ms = row.last_progress_ms ? Math.max(0, Date.now() - row.last_progress_ms) : null;
        live.push(row);
      }
    }
  }
  closed.sort((a, b) => a.started_ms - b.started_ms || a.attempt - b.attempt);
  live.sort((a, b) => a.started_ms - b.started_ms);
  return { closed, live, skipped_unattributed };
}

// THE TRIGGER, and the two clocks stay two clocks.
//
//   demote(profile, run) ⇔
//         consecutive_stalls(profile, run) >= extra_demote_after
//      OR a LIVE attempt quiet for >= extra_demote_stale_min
//
// The consecutive clock is about attempts that ENDED. The stale clock is about
// an attempt that has NOT ended — `extra_stall_s` already stops one DISPATCH
// after 180 seconds of silence; this is about the RUN. Different question,
// different budget, and neither is a simplification of the other.
//
// ONLY `stalled` COUNTS. Not `timeout` (the budget was the operator's choice),
// not `rate_limit`, not `authentication_failed` — each has its own answer, and a
// demotion triggered by a 401 would hide a credential problem behind a routing
// change where the user would never see the real fault.
function extraDemotionState(claudeDir, slugArg, opts) {
  const o = opts || {};
  const cfg = o.cfg || resolvedConfig(claudeDir);
  const run = extraDemoteRun(claudeDir, slugArg);
  const after = Math.max(0, Number(cfg.extra_demote_after === undefined ? EXTRA_DEMOTE_AFTER_DEFAULT : cfg.extra_demote_after) || 0);
  const staleMin = Math.max(
    0,
    Number(cfg.extra_demote_stale_min === undefined ? EXTRA_DEMOTE_STALE_MIN_DEFAULT : cfg.extra_demote_stale_min) || 0
  );
  const stallOff = Number(cfg.extra_stall_s === undefined ? 180 : cfg.extra_stall_s) === 0;
  const clocks = {
    consecutive: {
      key: "extra_demote_after",
      threshold: after,
      on: after > 0,
      // Both halves say this, because a user who turned the per-dispatch stall
      // budget off has silently turned this clock off too: no `stalled`
      // classification is ever produced, so the counter can never move.
      note:
        after === 0
          ? "off — extra_demote_after is 0."
          : stallOff
          ? "extra_stall_s is 0, so no dispatch is ever classified `stalled` and this counter can never fire. Only the stale clock remains."
          : null,
    },
    stale: {
      key: "extra_demote_stale_min",
      threshold_min: staleMin,
      on: staleMin > 0,
      note: staleMin === 0 ? "off — extra_demote_stale_min is 0." : null,
    },
  };

  const base = {
    ok: true,
    run: run.slug,
    run_from: run.from,
    run_dir: run.slug ? path.join(resolveRunDir(claudeDir), run.slug) : null,
    clocks,
    profiles: [],
    demoted: false,
    demoted_profiles: [],
    reasons: [],
    override: null,
    skipped_unattributed: 0,
    announce: null,
    trace_line: null,
  };
  if (!run.slug)
    return Object.assign(base, {
      known_run: false,
      ladder: null,
      why: "no run slug was given and the trace pointer names none, so there is no run to scope a demotion to.",
    });
  base.known_run = true;

  const { closed, live, skipped_unattributed } = extraDemoteAttempts(claudeDir, run.slug);
  base.skipped_unattributed = skipped_unattributed;
  const override = extraDemoteOverride(claudeDir, run.slug);
  base.override = override;
  // A PROMOTE IS A WATERMARK, NOT A MUTE. Everything the promote had already
  // seen is forgiven; a stall AFTER it is new evidence and may demote again.
  // The alternative — a promote that suppresses the clock for the rest of the
  // run — is an auto-off switch wearing a human's name.
  const since = override && override.state === "promoted" ? Date.parse(override.at || "") || 0 : 0;

  const byProfile = new Map();
  const of = (name) => {
    if (!byProfile.has(name))
      byProfile.set(name, {
        profile: name,
        consecutive_stalls: 0,
        stalls: [],
        resumes_of_the_same_stall: 0,
        reset_by: null,
        stale: null,
        demoted: false,
        reason: null,
        why: null,
      });
    return byProfile.get(name);
  };

  for (const a of closed) {
    if (!a.profile) continue;
    if (since && a.started_ms && a.started_ms <= since) continue;
    const g = of(a.profile);
    // A RESUME OF THE SAME STALLED ATTEMPT IS THE SAME STALL — it neither
    // increments nor resets. A stall is a stall whether its continuation
    // succeeded or not: a profile that needs a continuation twice in a row is
    // costing more than it saves, and letting a successful resume erase the
    // stall would make the counter unable to reach two by construction.
    if (a.resumed_from) {
      g.resumes_of_the_same_stall++;
      continue;
    }
    if (a.reason === "stalled") {
      g.consecutive_stalls++;
      g.stalls.push({ task_id: a.task_id, attempt: a.attempt, started_at: a.started_at, model: a.model_requested });
      g.reset_by = null;
    } else {
      // A COMPLETED DISPATCH THAT WAS NOT A STALL RESETS IT — including a 401.
      // Only `stalled` counts, and it counts in both directions.
      g.consecutive_stalls = 0;
      g.stalls = [];
      g.reset_by = { task_id: a.task_id, outcome: a.outcome, reason: a.reason };
    }
  }
  for (const a of live) {
    if (!a.profile || !a.live) continue;
    const g = of(a.profile);
    const quietMin = a.quiet_ms === null ? null : a.quiet_ms / 60000;
    if (!g.stale || (g.stale.quiet_ms || 0) < (a.quiet_ms || 0))
      g.stale = {
        task_id: a.task_id,
        attempt: a.attempt,
        started_at: a.started_at,
        quiet_ms: a.quiet_ms,
        quiet_min: quietMin === null ? null : Math.floor(quietMin),
        over_threshold: clocks.stale.on && quietMin !== null && quietMin >= staleMin,
      };
  }

  for (const g of byProfile.values()) {
    if (clocks.consecutive.on && g.consecutive_stalls >= after) {
      g.demoted = true;
      g.reason = "consecutive-stall";
      g.why =
        `${g.consecutive_stalls} consecutive stalled ${g.consecutive_stalls === 1 ? "dispatch" : "dispatches"} on "${g.profile}"` +
        ` in this run (extra_demote_after is ${after}) — ${g.stalls.map((s) => s.task_id).join(", ")}.`;
    } else if (g.stale && g.stale.over_threshold) {
      g.demoted = true;
      g.reason = "stale-live-attempt";
      g.why = `"${g.profile}" has a live attempt (${g.stale.task_id}) that has shown no observable progress for ${g.stale.quiet_min}m (extra_demote_stale_min is ${staleMin}).`;
    }
  }

  // THE MANUAL HALF. A user who knows the provider is down should not have to
  // wait for two stalls, and a user who knows it is back should not have to
  // finish the run on Claude. Both are recorded WITH THEIR REASON.
  if (override && override.state === "demoted") {
    let ledger = null;
    try {
      ledger = readExtra(claudeDir);
    } catch (_) {}
    for (const p of (ledger && ledger.profiles) || []) of(p.name);
    for (const g of byProfile.values())
      if (!g.demoted) {
        g.demoted = true;
        g.reason = "manual";
        g.why = `demoted by hand on ${String(override.at || "").slice(0, 16).replace("T", " ")} — "${override.reason}".`;
      }
  }
  if (override && override.state === "promoted")
    for (const g of byProfile.values())
      if (g.demoted)
        // The watermark above already excluded everything the promote saw, so
        // anything still demoted here is NEW evidence. Say that out loud rather
        // than letting it look like the promote was ignored.
        g.why = (g.why || "") + " This is evidence from AFTER the promote — a promote forgives what it saw, it does not mute the clock.";

  const profiles = [...byProfile.values()].sort((a, b) => a.profile.localeCompare(b.profile));
  base.profiles = profiles;
  base.demoted_profiles = profiles.filter((p) => p.demoted).map((p) => p.profile);
  base.demoted = base.demoted_profiles.length > 0;
  base.reasons = profiles.filter((p) => p.demoted).map((p) => ({ profile: p.profile, reason: p.reason, why: p.why }));

  // THE LADDER, BEFORE AND AFTER. `--json is not a summary`: the whole point of
  // a demotion is which rank answers now, so the report carries both.
  const hand = readOverride(claudeDir).map || {};
  const table = isTrue(cfg.opus5_only) ? "opus5_only" : hand.rubric_bands_override ? "rubric_bands_override" : "default";
  const effective = table === "default" ? "the shipped score→model table" : table;
  base.ladder = {
    before: ["extra_enabled (P0)", "opus5_only (P1)", "rubric_bands_override (P2)", "the shipped score→model table (P3)"],
    after: base.demoted
      ? ["opus5_only (P1)", "rubric_bands_override (P2)", "the shipped score→model table (P3)", `extra_enabled — DEMOTED for run ${run.slug}`]
      : null,
    effective_now: base.demoted ? effective : "extra_enabled (P0)",
  };

  if (base.demoted) {
    base.announce =
      `extra: DEMOTED for the rest of this run — ${base.demoted_profiles.join(", ")} ${
        base.demoted_profiles.length === 1 ? "is" : "are"
      } at the bottom of the ladder, so ${effective} answers instead. ` +
      base.reasons.map((r) => r.why).join(" ") +
      ` Nothing was written to your config, and it is not promoted back on its own: orc extra promote ${run.slug} --reason "<why>"`;
    // CLI-COMPOSED, because a demotion that leaves no line cannot be counted
    // (the v0.53.2 rule, restated). The lane copies it VERBATIM.
    base.trace_line = extraDemoteTraceLine(base);
  }
  return base;
}

// One line, one wording, one owner. `n=` is the consecutive counter for a
// `consecutive-stall`, and the quiet MINUTES for a stale live attempt — the two
// clocks measure different things and the `reason=` field is what tells a reader
// which number it is looking at.
function extraDemoteTraceLine(st) {
  const bits = st.reasons.map((r) => {
    const g = st.profiles.find((p) => p.profile === r.profile);
    const n = r.reason === "stale-live-attempt" ? (g && g.stale ? g.stale.quiet_min : "?") : g ? g.consecutive_stalls : "?";
    return `profile=${r.profile} reason=${r.reason} n=${n}`;
  });
  return `EXTRA demote run=${st.run} :: ${bits.join(" · ")} → ${st.ladder.effective_now}`;
}

// PER PROFILE, ACROSS EVERY RUN THE JOURNAL STILL HOLDS. A provider that
// demotes every run is a pattern; a provider that demoted once is an afternoon.
// The difference is only visible if somebody counts, and this is the counter
// `orc extra stats` and `/orc-retro` read.
//
// It re-runs the ONE engine per distinct run rather than re-deriving the rule,
// which costs a journal walk per run and buys the guarantee that the history
// and the live verdict can never disagree. The journal is swept at 30 days, so
// the walk is bounded by construction.
//
// `runs_seen` counts runs that actually dispatched to that profile — not runs
// that existed — so a rate here means "of the runs that used it", which is the
// only question anybody asks.
const EXTRA_DEMOTE_RATE_FLOOR = 3;
function extraDemotionHistory(claudeDir, cfg) {
  const runs = new Set();
  let unattributed = 0;
  const root = extraJournalRoot(claudeDir);
  let names = [];
  try {
    names = fs.readdirSync(root);
  } catch (_) {
    // The SAME SHAPE in the empty case. A key that vanishes when there is
    // nothing to report is a key every consumer has to guard, and an empty
    // result is an ANSWER (`--json is not a summary`).
    return { runs: 0, runs_unattributed: 0, rate_floor: EXTRA_DEMOTE_RATE_FLOOR, profiles: [] };
  }
  for (const name of names) {
    const dir = path.join(root, name);
    try {
      if (!fs.statSync(dir).isDirectory()) continue;
    } catch (_) {
      continue;
    }
    for (const a of extraJournalAttemptList(dir)) {
      let h = null;
      try {
        h = JSON.parse(fs.readFileSync(a.header, "utf8"));
      } catch (_) {
        continue;
      }
      if (h.run) runs.add(h.run);
      else unattributed++;
    }
  }
  const byProfile = new Map();
  const of = (n) => {
    if (!byProfile.has(n))
      byProfile.set(n, {
        profile: n,
        runs_seen: 0,
        runs_demoted: 0,
        demote_rate: null,
        reasons: { "consecutive-stall": 0, "stale-live-attempt": 0, manual: 0 },
        runs: [],
      });
    return byProfile.get(n);
  };
  for (const slug of runs) {
    const st = extraDemotionState(claudeDir, slug, { cfg });
    for (const g of st.profiles) {
      const row = of(g.profile);
      row.runs_seen++;
      if (!g.demoted) continue;
      row.runs_demoted++;
      if (row.reasons[g.reason] !== undefined) row.reasons[g.reason]++;
      row.runs.push({ run: slug, reason: g.reason, why: g.why });
    }
  }
  const profiles = [...byProfile.values()].sort((a, b) => b.runs_demoted - a.runs_demoted || a.profile.localeCompare(b.profile));
  // NO RATE BELOW THE FLOOR, the `extra-profile-unreliable` restraint verbatim:
  // one demotion out of one run is not a 100% demotion rate, it is one bad
  // afternoon with a percent sign bolted on.
  for (const g of profiles) g.demote_rate = g.runs_seen >= EXTRA_DEMOTE_RATE_FLOOR ? g.runs_demoted / g.runs_seen : null;
  return {
    runs: runs.size,
    // Named, always. Both ABSENT counts are printed (v0.53.2) — an attempt with
    // no run belongs to no run's history and saying nothing about it is how a
    // report goes quietly short.
    runs_unattributed: unattributed,
    rate_floor: EXTRA_DEMOTE_RATE_FLOOR,
    profiles,
  };
}

// Is this profile held back RIGHT NOW? One reader, so the resolver, the
// preflight, the doctor and `orc lane config` can never disagree about it.
// Memoised per process: `extraResolveFor` is called once per task in a wave and
// this walks the journal, and a wave of forty tasks must not walk it forty
// times.
let EXTRA_DEMOTE_MEMO = null;
function extraDemotionCached(claudeDir, cfg) {
  if (!EXTRA_DEMOTE_MEMO) EXTRA_DEMOTE_MEMO = extraDemotionState(claudeDir, null, { cfg });
  return EXTRA_DEMOTE_MEMO;
}
function extraProfileDemoted(claudeDir, profile, cfg) {
  const st = extraDemotionCached(claudeDir, cfg);
  if (!st.demoted) return null;
  const g = st.profiles.find((p) => p.profile === profile && p.demoted);
  return g ? { state: st, profile: g } : null;
}

// ── The three commands ─────────────────────────────────────────────────────
//
//   orc extra demotion [<run>] [--json]   0 armed (not demoted) · 1 demoted · 2 unknown run
//   orc extra promote  <run> --reason ""  0 promoted · 1 not demoted · 2 unknown run
//   orc extra demote   <run> --reason ""  0 demoted  ·               · 2 unknown run
//
// `demotion` is a READ and its exit code is the ANSWER, the same convention as
// `orc pattern status` and `orc diy status`. The reason on the two writes is
// REQUIRED — a state change nobody wrote a reason for is a state nobody can
// audit later (the /orc-pact retirement rule).
function extraDemotionCmd(claudeDir, slugArg) {
  const asJson = wantsJson();
  const st = extraDemotionState(claudeDir, slugArg);
  if (!st.known_run) {
    const obj = { ok: false, reason: "unknown-run", run: null, why: st.why, hint: "orc run list names the runs that exist." };
    if (asJson) emitJson(obj, 2);
    console.error(st.why);
    process.exit(2);
  }
  const code = st.demoted ? 1 : 0;
  if (asJson) emitJson(st, code);

  console.log(ui.header(`ORC · extra demotion — ${st.run}`));
  console.log("");
  if (!st.demoted) {
    console.log("  " + ui.mark.ok(`armed — nothing is demoted in this run.`));
  } else {
    console.log("  " + ui.mark.warn(st.announce));
  }
  console.log("");
  console.log(
    ui.kv([
      ["consecutive clock", st.clocks.consecutive.on ? `${st.clocks.consecutive.threshold} stalled dispatches` : "off"],
      ["stale clock", st.clocks.stale.on ? `${st.clocks.stale.threshold_min} minutes with no progress` : "off"],
      ["ladder now", st.ladder.effective_now],
    ])
  );
  for (const note of [st.clocks.consecutive.note, st.clocks.stale.note]) if (note) console.log(ui.color.gray("  " + note));
  console.log("");
  if (!st.profiles.length) console.log(ui.color.gray("  no foreign dispatch in this run has reached the journal yet.\n"));
  for (const p of st.profiles) {
    const mark = p.demoted ? ui.mark.bad("DEMOTED") : ui.mark.ok("routing");
    console.log(`  ${mark}  ${p.profile}  ${ui.color.gray(`stalls ${p.consecutive_stalls}/${st.clocks.consecutive.threshold || "off"}`)}`);
    if (p.why) console.log("      " + p.why);
    if (p.stale && !p.demoted) console.log(ui.color.gray(`      live attempt ${p.stale.task_id} quiet for ${p.stale.quiet_min}m`));
    if (p.reset_by) console.log(ui.color.gray(`      counter reset by ${p.reset_by.task_id} (${p.reset_by.outcome})`));
    if (p.resumes_of_the_same_stall)
      console.log(ui.color.gray(`      ${p.resumes_of_the_same_stall} resume(s) of the same stall — not counted twice`));
  }
  // Both ABSENT counts are named. A report quietly short by three rows is the
  // exact failure this rule exists to prevent (v0.53.2).
  if (st.skipped_unattributed)
    console.log(
      ui.color.gray(
        `\n  ${st.skipped_unattributed} journal attempt(s) carry no run and are counted by NO run's clock (dispatched with no run open, or written before v1.0.0).`
      )
    );
  if (st.override)
    console.log(
      ui.color.gray(
        `\n  ${st.override.state} by hand on ${String(st.override.at || "").slice(0, 16).replace("T", " ")} — "${st.override.reason}"`
      )
    );
  console.log("");
  process.exit(code);
}

function extraDemoteCmd(claudeDir, slugArg, want) {
  const asJson = wantsJson();
  const reason = flag("--reason");
  const run = extraDemoteRun(claudeDir, slugArg);
  const fail = (r, why, code) => {
    if (asJson) emitJson({ ok: false, reason: r, run: run.slug, why }, code);
    console.error(why);
    process.exit(code);
  };
  if (!run.slug)
    fail("unknown-run", "Name the run: orc extra " + want + ' <run-slug> --reason "<why>". `orc run list` shows the ones that exist.', 2);
  if (!reason || !String(reason).trim())
    fail(
      "reason-required",
      `A reason is REQUIRED: orc extra ${want} ${run.slug} --reason "<why>". A state change nobody wrote a reason for is a state nobody can audit later.`,
      2
    );

  const before = extraDemotionState(claudeDir, run.slug);
  if (!before.known_run) fail("unknown-run", before.why, 2);
  if (want === "promote" && !before.demoted)
    fail("not-demoted", `Nothing is demoted in run ${run.slug} — there is nothing to promote back.`, 1);

  const rec = {
    v: 1,
    state: want === "promote" ? "promoted" : "demoted",
    at: new Date().toISOString(),
    reason: String(reason).trim(),
    // WHAT THE DECISION SAW. A promote is a watermark, so the evidence it
    // forgave is on the record beside it — otherwise a later demotion looks
    // like the promote was ignored.
    saw: {
      demoted_profiles: before.demoted_profiles,
      reasons: before.reasons,
    },
  };
  const written = extraDemoteWrite(claudeDir, run.slug, rec);
  const after = extraDemotionState(claudeDir, run.slug);
  const obj = {
    ok: true,
    run: run.slug,
    action: want,
    reason: rec.reason,
    file: written,
    was_demoted: before.demoted,
    now_demoted: after.demoted,
    demoted_profiles: after.demoted_profiles,
    ladder: after.ladder,
    announce: after.announce,
    trace_line: after.trace_line,
    note:
      want === "promote"
        ? "A promote FORGIVES the evidence it saw; it does not mute the clock. Two more stalls in this run demote again."
        : "Run-scoped. Nothing was written to your config, and it is never promoted back on its own.",
  };
  if (asJson) emitJson(obj, 0);
  console.log("");
  console.log(
    "  " +
      (want === "promote"
        ? ui.mark.ok(`promoted — run ${run.slug} routes foreign again.`)
        : ui.mark.warn(`demoted — run ${run.slug} keeps its work on Claude.`))
  );
  console.log(ui.color.gray(`  reason: ${rec.reason}`));
  console.log(ui.color.gray("  " + obj.note));
  console.log("");
  process.exit(0);
}

// ══ THE RESUME SLICE (v0.54.0) ═════════════════════════════════════════════
//
// `a lane that re-does work the worktree already contains` has broken this
// contract.
//
// A resume is A NEW DISPATCH OF A DERIVED SLICE — not a new engine, not a new
// dispatch path, not a new agent. The lane's flow is:
//
//   orc extra reconcile   <task_id> --json          exit 0 → resumable
//   orc extra resume-slice <task_id> --out <file>
//   orc extra dispatch --task <file> --json         the ORDINARY bridge
//
// Every existing gate — the fence, the concurrency cap, the credential rules,
// the spend log, §6 — comes along for free, because none of them ever asked
// whether a slice was a first attempt.
//
// THE CLI COMPOSES THE PREAMBLE. Same rule as `trace_line` and `announce`: a
// lane that wrote its own resume wording would produce a second wording for the
// same facts, and the two would drift.

// WHERE A RESUME GOES — DERIVED, never a config key.
//
// The user asked for "the same agent, in a new session". That is the default and
// it is right, and it is wrong for a non-retryable failure — so the target comes
// from the classification that already exists (`EXTRA_FAILURES[…].retry`) plus
// the attribution. A key here would let somebody configure "always resume on the
// same profile" and then wait out `extra_resume_max` × a 401.
const EXTRA_RESUME_TARGETS = ["extra", "claude", "hold", "off"];

// ONE reader of "which Claude agent takes this over". A resume that goes to
// Claude and a fallback that goes to Claude must never disagree about the
// answer, and before v0.56.1 there was only one place it could come from. Now
// `extra_fallback_agent` can pin one or defer to the user, so the resolved
// choice wins where it made one and `fallback_to` is still the floor. `null`
// under `ask` is CORRECT and not a gap: nothing has been chosen yet.
function extraFallbackAgentOf(result) {
  const f = result && result.fallback;
  // `ask` deliberately resolves to NULL — nothing has been chosen yet, and a
  // resume report that named an agent would answer the question the setting
  // exists to ask. The renderer prints the menu instead.
  if (f && f.mode === "ask") return null;
  // ONLY a PINNED setting overrides. Under `band` the two fields agree by
  // construction (both are `res.claude`), and `fallback_to` keeps its name, its
  // position and its meaning as the promise at the payload says — so it stays
  // the authority for the default, and this function is the exception, not a
  // replacement.
  if (f && f.mode === "pinned" && f.agent) return f.agent;
  return (result && result.fallback_to && result.fallback_to.agent) || (f && f.agent) || null;
}

// ONE idea of what "on" means. Two readers of the same key that disagree about
// its default is the drift this repo lints for everywhere else.
const extraResumeOn = (cfg) => String((cfg && cfg.extra_resume) === undefined ? "on" : cfg.extra_resume) !== "off";

function extraResumeTarget(v, result, cfg) {
  const resumesSoFar = Math.max(0, (v.attempts_total || 1) - 1);
  const max = Math.max(0, Number(cfg.extra_resume_max) || 0);

  if (!extraResumeOn(cfg))
    return {
      kind: "off",
      profile: null,
      agent: null,
      why: "`extra_resume` is off, so this behaves exactly as it did before v0.54.0: the fallback procedure re-dispatches the ORIGINAL slice. Nothing here reads the position.",
      resumes_so_far: resumesSoFar,
      resume_max: max,
    };

  const verdict = v.attribution && v.attribution.verdict;
  if (verdict === "network" || verdict === "local")
    return {
      kind: "hold",
      profile: null,
      agent: null,
      // THE POINT OF THE WHOLE RELEASE. Fallback and resume are orthogonal, and
      // ORC has been conflating them: today a failure means "start over, on
      // Claude". A fallback that cannot succeed is a second cost for nothing.
      why:
        verdict === "network"
          ? "attributed to this machine's NETWORK. A Claude fallback would fail too, so hold the wave and say why — do not spend a second failure finding that out."
          : "attributed to this MACHINE (a missing binary, a managed-settings conflict, a disk error). Neither route works until it is fixed here.",
      resumes_so_far: resumesSoFar,
      resume_max: max,
    };

  if (resumesSoFar >= max)
    return {
      kind: "claude",
      profile: null,
      agent: extraFallbackAgentOf(result),
      why: `\`extra_resume_max\` is ${max} and this task has already been resumed ${resumesSoFar} time(s). The cap STOPS with an honest report rather than looping a third time — bounded like \`tdd_loop_max\`.`,
      capped: true,
      resumes_so_far: resumesSoFar,
      resume_max: max,
    };

  const retryable = result ? !!result.retry : true;
  if (retryable)
    return {
      kind: "extra",
      profile: v.profile,
      agent: null,
      why: `\`${v.reason || "the failure"}\` is retryable, so the same profile gets it again in a NEW session — carrying the position it left behind.`,
      resumes_so_far: resumesSoFar,
      resume_max: max,
    };

  return {
    kind: "claude",
    profile: null,
    agent: extraFallbackAgentOf(result),
    // THE CASE THAT FIXES GAP 1. A Claude executor receiving a resume slice gets
    // the same preamble, the same `preexisting[]` table and the same instruction
    // not to rewrite finished work. The Claude fallback stops being a
    // from-scratch dispatch, which it should never have been.
    why: `\`${v.reason || "the failure"}\` will not succeed on a retry, so this goes to the Claude band — STILL AS A RESUME SLICE. A from-scratch re-dispatch onto a half-written file is the failure this exists to remove.`,
    resumes_so_far: resumesSoFar,
    resume_max: max,
  };
}

// ── WHICH Claude agent picks up a failed foreign task (v0.56.1) ────────────
//
// `fallback_to` has always carried the band's (or the slot's) own Claude agent,
// which is the right default and the only one ORC can compute: a fallback that
// changes tier is a re-plan nobody asked for.
//
// What it could not do is let a human choose. A stall costs real minutes before
// anybody hears about it, and by the time the wave stops the user often knows
// something ORC does not — that this slice wants more thinking than its band
// bought, or less. So `extra_fallback_agent` adds two words to the default:
// `ask` STOPS with the menu, and a bare agent name pins one.
//
// The menu is COMPUTED, never a second idea of the ladder: the band's own agent
// always leads it (it is what happens if the user just presses enter), and the
// three named alternates are the ones a person actually reaches for. "Any other
// installed agent" is the honest last row — the roster is generated, and a
// closed list here would go stale the next time a band moves.
const EXTRA_FALLBACK_ALTERNATES = [
  { agent: "orc-executor-opus-5-med", why: "more thinking than most bands buy, without the top-tier cost." },
  { agent: "orc-executor-opus-5-low", why: "the same model on the cheapest rung — right when the slice turned out to be mechanical." },
  { agent: "orc-executor-sonnet-4-6-high", why: "a different model entirely, for a slice where Opus is not the constraint." },
];

function extraFallbackChoice(cfg, claude) {
  const bandAgent = (claude && claude.agent) || null;
  const setting = String((cfg && cfg.extra_fallback_agent) || "band").trim() || "band";
  const options = [];
  if (bandAgent)
    options.push({
      agent: bandAgent,
      label: "the agent this task would have had",
      why: "a fallback changes WHO runs the task and nothing else — the score, the declared files and the acceptance criteria are untouched.",
      is_band: true,
    });
  for (const alt of EXTRA_FALLBACK_ALTERNATES)
    if (alt.agent !== bandAgent) options.push({ agent: alt.agent, label: alt.agent, why: alt.why, is_band: false });

  if (setting === "ask")
    return {
      mode: "ask",
      agent: null,
      band_agent: bandAgent,
      options,
      free_text: "any installed ORC agent name is also accepted",
      // The lane STOPS here. It is a config the user set on purpose, so a lane
      // that quietly picked the default for them would be answering the one
      // question the setting exists to ask.
      note: "`extra_fallback_agent` is `ask` — put these to the user and dispatch what they pick. Do not choose one for them.",
    };
  if (setting === "band")
    return {
      mode: "band",
      agent: bandAgent,
      band_agent: bandAgent,
      options,
      free_text: null,
      note: bandAgent
        ? `dispatch \`${bandAgent}\` — the agent this band or slot already resolves to.`
        : "no Claude agent could be resolved for this task, so there is nothing to fall back to. Report that rather than guessing one.",
    };
  return {
    mode: "pinned",
    agent: setting,
    band_agent: bandAgent,
    options,
    free_text: null,
    note:
      `\`extra_fallback_agent\` pins every fallback to \`${setting}\`` +
      (bandAgent && bandAgent !== setting ? `, overriding this task's own \`${bandAgent}\`.` : "."),
  };
}

// ONE WORDING, composed here. Renderers print it; nobody writes a second one.
function extraResumePreamble(v, target) {
  const line = (f) => {
    if (f.state === "untouched") return `\`${f.path}\` — **untouched**.`;
    const n = f.numstat.added === null ? "line counts unknown" : `+${f.numstat.added} / −${f.numstat.removed} lines`;
    return `\`${f.path}\` — **${f.state}** by the previous attempt (${n}).`;
  };
  const out = [
    "This task was already started by a worker that was cut off before it finished.",
    "**The repository already contains its partial work.** Do not start over and do",
    "not rewrite a file that is already correct. Read each file listed below before",
    "changing it. Finish the task; change nothing that is already done.",
    "",
  ];
  for (const f of v.files) out.push(line(f));
  out.push("");
  out.push(`Last recorded action: ${v.last_action}`);
  if (v.journal_fidelity === "streamed-opaque")
    out.push(
      "That record is BYTES the previous worker printed, not a per-turn tool log — ORC did not interpret it, so treat it as a hint and the files above as the fact."
    );
  out.push(
    `The previous attempt ended: \`${v.reason || "it never reported back"}\`${
      v.attribution && v.attribution.verdict ? ` (attributed: ${v.attribution.verdict})` : ""
    }.`
  );
  if (v.touched_undeclared.length)
    out.push(
      `NOTE — ${v.touched_undeclared.length} file(s) outside this task's declared list changed while it ran: ${v.touched_undeclared
        .map((t) => "`" + t.path + "`")
        .join(", ")}. You may not change them. Say so if one blocks you.`
    );
  out.push("");
  out.push(
    "When you report back, say `resume_state`: `continued` if you built on what was there, `restarted` if you rewrote it, `no-op` if it was already finished — and list in `preexisting_read[]` which of the files above you actually opened."
  );
  return out.join("\n");
}

// SIX refusals, each NAMED — because a refusal the lane renders as a generic
// error is a refusal the user cannot act on.
//
// Five are about the POSITION. The sixth (`resume-disabled`) is about the
// SWITCH, and it is deliberately its own word rather than being folded into
// `not-resumable`: "you turned this off" and "there is nothing to resume" are
// different facts with different fixes, and a command that silently ignores a
// config somebody set is worse than one that refuses by name.
const EXTRA_RESUME_REFUSALS = [
  "not-resumable",
  "in-flight",
  "reverted-file",
  "slice-drifted",
  "resume-cap",
  "resume-disabled",
];

function extraResumeSlice(claudeDir, taskId) {
  const asJson = wantsJson();
  const outArg = flag("--out");
  const cfg = resolvedConfig(claudeDir);
  const attemptFlag = flag("--attempt");
  const v = extraReconcileCompute(claudeDir, taskId, typeof attemptFlag === "string" ? attemptFlag : null);

  const refuse = (reason, error, blockedBy, extra) => {
    const obj = Object.assign(
      {
        ok: false,
        reason,
        task_id: taskId || null,
        attempt: v.attempt || null,
        state: v.state,
        error,
        blocked_by: blockedBy || null,
        // WRITES NOTHING. The `orc doc splice` refusal shape: refuse, name it,
        // write nothing.
        slice_path: null,
      },
      extra || {}
    );
    if (asJson) emitJson(obj, reason === "no-journal" ? 2 : 1);
    console.error("❌ " + error);
    if (blockedBy) console.error("   " + blockedBy);
    process.exit(reason === "no-journal" ? 2 : 1);
  };

  if (!v.ok) refuse("no-journal", v.error, null);

  // The switch, first: nothing below is worth computing if the user turned this
  // off.
  if (!extraResumeOn(cfg))
    refuse(
      "resume-disabled",
      "`extra_resume` is off, so ORC does not compose resume slices. The fallback procedure re-dispatches the ORIGINAL slice, exactly as it did before v0.54.0.",
      "a human decides: `orc config set extra_resume on`, or accept the from-scratch re-dispatch."
    );

  if (v.state === "in-flight") refuse("in-flight", "that attempt is still alive. Two writers on one file is worse than a lost dispatch.", v.blocked_by);
  if (v.state !== "resumable")
    refuse(
      "not-resumable",
      `the reconciliation says \`${v.state}\` — ${EXTRA_RECONCILE_MEANING[v.state]}. There is no position to continue from.`,
      v.state === "nothing-to-resume"
        ? "nothing was written, so re-dispatching the ORIGINAL slice is the correct move — that is the existing fallback procedure and it is right here."
        : v.state === "complete"
        ? "this attempt finished. Resuming it would duplicate work; run the ordinary gates instead."
        : null
    );

  // A `reverted` declared file STOPS the resume. Resuming on top of a possible
  // destructive action is the one case where continuing is worse than starting
  // over, and ORC does not get to make that call.
  if (v.reverted.length)
    refuse(
      "reverted-file",
      `${v.reverted.join(", ")} came back CLOSER TO HEAD than the baseline — the §6 revert signature, which is how a destructive git command inside a slice disguises itself.`,
      v.blocked_by,
      { reverted: v.reverted }
    );

  // THE SLICE IS IMMUTABLE ACROSS ATTEMPTS. If the plan moved between attempts,
  // continuing quietly is how a resume produces work nobody asked for.
  let sliceRaw = null;
  try {
    sliceRaw = fs.readFileSync(v.slice_path, "utf8");
  } catch (e) {
    refuse(
      "slice-drifted",
      `the original slice at ${v.slice_path} could not be read (${e.code || e.message}), so ORC cannot prove the task is still the task it was.`,
      "a human decides whether the plan still stands. Re-plan, or dispatch a fresh slice."
    );
  }
  const nowHash = sha256(sliceRaw);
  if (nowHash !== v.slice_sha256)
    refuse(
      "slice-drifted",
      `the plan changed between attempts: the slice at ${v.slice_path} now hashes ${nowHash.slice(0, 12)}…, and this attempt ran ${String(v.slice_sha256).slice(0, 12)}….`,
      "a human decides. Continuing a stale task quietly is how a resume produces work nobody asked for.",
      { slice_sha256_then: v.slice_sha256, slice_sha256_now: nowHash }
    );

  let original;
  try {
    original = JSON.parse(sliceRaw);
  } catch (e) {
    refuse("slice-drifted", `the original slice at ${v.slice_path} is not valid JSON (${e.message}).`, null);
  }

  let result = null;
  try {
    result = JSON.parse(fs.readFileSync(path.join(path.dirname(v.journal), path.basename(v.journal).replace(/\.json$/, ".result.json")), "utf8"));
  } catch (_) {}

  const target = extraResumeTarget(v, result, cfg);
  if (target.kind === "hold")
    refuse("not-resumable", `this failure is attributed to ${v.attribution.verdict} — ${target.why}`, v.attribution.why, {
      resume_target: target,
      attribution: v.attribution,
    });
  if (target.capped) {
    // The cap is a STOP WITH AN HONEST REPORT, never a silent third loop. It
    // still names the Claude agent, because the fallback procedure is what
    // happens next and the lane should not have to look it up.
    refuse("resume-cap", target.why, `a human decides: raise \`extra_resume_max\`, or let the fallback procedure hand this to ${target.agent || "the Claude band"}.`, {
      resume_target: target,
    });
  }

  if (typeof outArg !== "string")
    refuse("not-resumable", "usage: orc extra resume-slice <task_id> --out <file.json>", "the derived slice needs somewhere to go.");

  const preamble = extraResumePreamble(v, target);
  const preexisting = v.files.map((f) => ({
    path: f.path,
    state: f.state,
    lines: f.now.lines,
    added: f.numstat.added,
    removed: f.numstat.removed,
  }));

  // THE DERIVED SLICE differs from the original in exactly four ways, and every
  // one of the things it does NOT change is a rule:
  //
  //   declared_files is NEVER widened — a resume that could add a path is a
  //     fence expansion nobody approved, arriving through the one door where
  //     nobody is watching. A genuine need is a `needs_context` return.
  //   acceptance[] NEVER moves — the definition of done was set before any of
  //     this happened; a resume that could relax it would let a failure rewrite
  //     its own grade.
  //   the score NEVER moves, so the resume resolves through the SAME
  //     `extraResolveFor` call and lands on the same band. A resume is not a
  //     discount.
  const derived = Object.assign({}, original, {
    prompt: preamble + "\n\n---\n\n" + original.prompt,
    resumed_from: {
      attempt: v.attempt,
      reason: v.reason,
      attribution: (v.attribution && v.attribution.verdict) || null,
      at: v.started_at,
      journal: v.journal,
    },
    preexisting,
    // So a `Read` of them is obviously the first move.
    resume_readonly_hint: v.files.filter((f) => f.state !== "untouched").map((f) => f.path),
  });
  derived.declared_files = original.declared_files || [];
  derived.acceptance = original.acceptance || [];
  derived.score = original.score;

  const outPath = path.resolve(outArg);
  try {
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, JSON.stringify(derived, null, 2) + "\n", "utf8");
  } catch (e) {
    refuse("not-resumable", `cannot write the resume slice to ${outPath}: ${e.code || e.message}`, null);
  }

  const announce =
    target.kind === "extra"
      ? `resuming ${v.task_id} on ${v.profile}/${v.model_requested || "?"} in a NEW session — ${preexisting.filter((p) => p.state !== "untouched").length} file(s) already changed on disk are carried into the slice, not re-done.`
      : `resuming ${v.task_id} on ${target.agent || "the Claude band"} — still as a RESUME slice, so the executor is told what is already on disk instead of landing on it blind.`;

  const obj = {
    ok: true,
    task_id: v.task_id,
    attempt: v.attempt,
    next_attempt: v.attempt + 1,
    slice_path: outPath,
    resume_target: target,
    attribution: v.attribution,
    preexisting,
    resume_readonly_hint: derived.resume_readonly_hint,
    preamble,
    announce,
    declared_files: derived.declared_files,
    acceptance: derived.acceptance,
    score: derived.score,
    slice_sha256: v.slice_sha256,
    next: `orc extra dispatch --task ${outPath} --json`,
    blocked_by: null,
  };
  if (asJson) emitJson(obj, 0);
  console.log("\n" + ui.mark.ok(announce));
  console.log(`\n  target: ${target.kind}${target.profile ? " " + target.profile : target.agent ? " " + target.agent : ""}`);
  console.log("  " + target.why);
  console.log("\n  carried into the slice:");
  for (const p of preexisting)
    console.log(`    ${p.path} — ${p.state}${p.state === "untouched" ? "" : p.added === null ? " (±?)" : ` (+${p.added} −${p.removed})`}`);
  console.log(`\n  ${outPath}`);
  console.log("  " + ui.color.bold(obj.next) + "\n");
  process.exit(0);
}

// ── The spend a killed dispatch never got to record ────────────────────────
//
// `appendExtraSpend` runs AFTER the engine returns, so a dispatch whose parent
// was killed cost real money and is invisible to every cost report there is —
// the exact hole v0.53.2 was released to close, re-opening through a different
// door.
//
// The journal's running vector is the only record it left, so reconcile writes
// it — ONCE, idempotently, marked. `/orc-budget`'s discipline holds: MEASURED IS
// NOT UNKNOWN and UNKNOWN IS NOT ZERO. A recovered vector is a FLOOR and it says
// so, in a field a renderer cannot miss.
function extraRecoverSpend(claudeDir, v) {
  if (v.reported_back || !v.partial_usage) return null;
  const marker = v.journal.replace(/\.json$/, ".recovered");
  try {
    if (fs.existsSync(marker)) return { already: true, marker };
  } catch (_) {}
  const rec = appendExtraSpend(claudeDir, {
    profile: v.profile,
    provider: v.provider,
    model_requested: v.model_requested,
    engine: v.engine,
    task_id: v.task_id,
    band: v.band,
    score: v.score,
    usage: v.partial_usage,
    // NOT `failed`. Nothing observed this dispatch end, and calling it failed
    // would be a claim the disk cannot support.
    outcome: "orphaned",
    duration_ms: 0,
    reason: "never-reported-back",
    recovered: true,
  });
  if (!rec) return null;
  try {
    fs.writeFileSync(marker, new Date().toISOString() + "\n", "utf8");
  } catch (_) {}
  return { already: false, marker, record: rec };
}

// ── Reliability — a MEASURED property of a profile ─────────────────────────
//
// A provider that drops one dispatch in three is a fact that should be visible
// WHEN THE USER IS CHOOSING A PROFILE, not folklore. It joins the spend/trace
// rows (the cost side) to the journals (the position side), and — as
// `extraStatsScan` already does — IT NAMES WHAT IT COULD NOT READ.
function extraReliability(claudeDir, scan) {
  const per = new Map();
  const get = (name) => {
    if (!per.has(name))
      per.set(name, {
        profile: name,
        dispatches: 0,
        failed: 0,
        partial: 0,
        resumed: 0,
        orphaned: 0,
        attribution: { provider: 0, network: 0, local: 0, worker: 0, orc: 0 },
        // ALWAYS PRINTED, INCLUDING WHEN ZERO (the /orc-budget rule).
        unattributed: 0,
        failure_durations: [],
        mean_time_to_failure_ms: null,
        // BELOW THE FLOOR THERE IS NO RATE. A percentage computed from three
        // dispatches is noise with a percent sign on it.
        sample_floor: EXTRA_RELIABILITY_FLOOR,
        sample_too_small: true,
        failure_rate: null,
      });
    return per.get(name);
  };

  for (const r of scan.rows) {
    if (!r.profile) continue;
    const g = get(r.profile);
    g.dispatches++;
    if (r.outcome === "failed") {
      g.failed++;
      if (r.duration_ms) g.failure_durations.push(r.duration_ms);
    } else if (r.outcome === "partial") g.partial++;
    else if (r.outcome === "orphaned") g.orphaned++;
  }

  let unreadable = 0;
  let withoutResult = 0;
  const root = extraJournalRoot(claudeDir);
  let names = [];
  try {
    names = fs.readdirSync(root);
  } catch (_) {}
  for (const name of names) {
    const dir = path.join(root, name);
    try {
      if (!fs.statSync(dir).isDirectory()) continue;
    } catch (_) {
      continue;
    }
    for (const a of extraJournalAttemptList(dir)) {
      let header = null;
      try {
        header = JSON.parse(fs.readFileSync(a.header, "utf8"));
      } catch (_) {
        unreadable++;
        continue;
      }
      const g = get(header.profile || "?");
      if (header.resumed_from) g.resumed++;
      let result = null;
      try {
        result = JSON.parse(fs.readFileSync(a.result, "utf8"));
      } catch (_) {}
      if (!result) {
        withoutResult++;
        // An ORPHAN is one that also cannot still be running.
        if (!extraAttemptLive(header).live) g.orphaned++;
        continue;
      }
      const verdict = result.attribution && result.attribution.verdict;
      if (result.outcome === "done") continue;
      if (verdict && g.attribution[verdict] !== undefined) g.attribution[verdict]++;
      else g.unattributed++;
    }
  }

  for (const g of per.values()) {
    const denom = g.dispatches + g.orphaned;
    g.dispatches_total = denom;
    if (g.failure_durations.length)
      g.mean_time_to_failure_ms = Math.round(g.failure_durations.reduce((a, b) => a + b, 0) / g.failure_durations.length);
    delete g.failure_durations;
    g.sample_too_small = denom < EXTRA_RELIABILITY_FLOOR;
    g.failure_rate = g.sample_too_small ? null : Math.round(((g.failed + g.orphaned) / denom) * 100) / 100;
  }

  return {
    profiles: [...per.values()].sort((a, b) => b.dispatches_total - a.dispatches_total),
    sample_floor: EXTRA_RELIABILITY_FLOOR,
    // THE TWO ABSENT COUNTS, named — a report quietly short by three rows is the
    // exact failure v0.53.2 was released to fix.
    unreadable_journals: unreadable,
    journals_without_result: withoutResult,
  };
}

// Below this a rate is not reported at all — the `wiki-debt` STALE-only
// restraint. A doctor that warns about noise is a doctor people learn to ignore.
const EXTRA_RELIABILITY_FLOOR = 10;
const EXTRA_UNRELIABLE_RATE = 0.3;

// ── The engine ─────────────────────────────────────────────────────────────
function runClaudeShim(ctx) {
  const { prof, route, key, cfg, slice, cwd, workDir } = ctx;
  const started = Date.now();
  const fail = (reason, error, extra) =>
    Object.assign(
      { ok: false, outcome: "failed", reason, error, retry: classifyFailure(reason).retry, duration_ms: Date.now() - started },
      extra || {}
    );

  const managed = managedLoginConflict();
  if (managed.conflict)
    return fail(
      "managed-login-conflict",
      `this machine's managed settings set ${managed.keys.join(" and ")} (${managed.path}), which cannot coexist with a third-party credential. Engine claude-shim is unavailable here — use engine \`api\`, which talks to the provider directly.`
    );

  const bin = whichBin("claude");
  if (!bin)
    return fail("engine-unavailable", "`claude` is not on PATH — engine claude-shim dispatches by running it.");

  const timeouts = extraTimeouts(cfg);
  const { env, models } = extraShimEnv(prof, route, key, cfg, timeouts);
  // The ONLY caller is the conformance run, which deliberately un-sets a
  // mitigation to find out whether this endpoint needs it. A dispatch never
  // passes this.
  if (ctx.envOverride) Object.assign(env, ctx.envOverride);

  // The standing rules go in a FILE and the prompt goes on STDIN (R3). Between
  // them that leaves argv holding nothing but short flags — under Windows'
  // 32,767-character command-line cap, and with no secret in it by
  // construction rather than by care.
  const rulesFile = path.join(workDir, "system-prompt.md");
  const outFile = path.join(workDir, "output.jsonl");
  fs.writeFileSync(rulesFile, slice.standing_rules || "", "utf8");

  const tools = Array.isArray(slice.allowed_tools) && slice.allowed_tools.length ? slice.allowed_tools : EXTRA_DEFAULT_TOOLS;
  const badTools = tools.filter((t) => !EXTRA_TOOLS_ALLOWED.has(t));
  if (badTools.length)
    return fail(
      "invalid_request",
      `the slice asks for tool(s) ORC does not recognise: ${badTools.join(", ")}. The set is closed on purpose — it is the last part of the command line a slice can influence.`
    );
  const mode = slice.permission_mode || "acceptEdits";
  if (!CLAUDE_PERMISSION_MODES.includes(mode))
    return fail("invalid_request", `permission_mode "${mode}" is not one of: ${CLAUDE_PERMISSION_MODES.join(", ")}`);

  // stream-json is PREFERRED because its system/api_retry events are the
  // classifier P6's fallback needs. It is not depended on: an endpoint or a
  // client build that will not produce it degrades to `json`, and the
  // degradation is RECORDED as tool_fidelity.streams rather than hidden.
  const attempts = [];
  for (const format of ["stream-json", "json"]) {
    const argv = [
      // P8. Always. Skips hooks, skills, commands, subagents, plugins, MCP
      // servers, auto memory and CLAUDE.md — and never reads OAuth credentials
      // or the system keychain, which is the clean answer to the auth-conflict
      // warning a third-party base URL otherwise produces.
      "--bare",
      "-p",
      "--output-format",
      format,
      "--permission-mode",
      mode,
      "--allowedTools",
      tools.join(","),
      "--append-system-prompt-file",
      rulesFile,
    ];
    if (format === "stream-json") argv.push("--verbose"); // headless stream-json requires it
    const maxTurns = route.max_turns || slice.max_turns || null;
    if (maxTurns) argv.push("--max-turns", String(maxTurns));

    const r = spawnCmdSafe(bin, argv, {
      cwd,
      env: Object.assign({}, process.env, env),
      input: slice.prompt || "",
      encoding: "utf8",
      timeout: timeouts.wall_ms,
      killSignal: "SIGTERM",
      maxBuffer: EXTRA_MAX_OUTPUT_BYTES,
      windowsHide: true,
    });

    if (r.error && r.error.code === "ETIMEDOUT")
      return fail("timeout", `no answer in ${Math.round(timeouts.wall_ms / 1000)}s (the dispatch wall clock).`, { format });
    if (r.error)
      return fail("spawn-failed", r.error.message, { format });

    const text = r.stdout || "";
    try {
      fs.writeFileSync(outFile, text, "utf8");
    } catch (_) {}
    attempts.push({ format, exit_code: r.status, bytes: text.length });

    // A client that does not understand this format at all: try the next one.
    // Anything else is a real answer and must not be retried in another shape.
    if (!text.trim() && r.status !== 0 && format === "stream-json") continue;

    return interpretShimRun({ text, format, exit: r, started, models, timeouts, attempts, outFile, stderr: r.stderr || "", journal: ctx.journal });
  }
  return fail("spawn-failed", "the worker produced no output in either output format.", { attempts });
}

// F3 lives here: exit code 0 is NOT success, and `is_error` is the signal.
function interpretShimRun(a) {
  const { text, format, exit, started, models, attempts, outFile, stderr } = a;
  const duration_ms = Date.now() - started;
  // The `json` shape must be the SAME shape parseStreamJson returns, field for
  // field. A literal that is missing one of them is a crash in whichever
  // consumer reaches for it — which is exactly how `tool_names` broke the
  // degrade path the first time it was added.
  const parsed =
    format === "stream-json"
      ? parseStreamJson(text)
      : { result: null, retries: [], tool_uses: 0, tool_results: 0, events: 0, init: null, tool_names: [] };
  let result = parsed.result;
  if (!result && format === "json") {
    try {
      result = JSON.parse(text);
    } catch (_) {}
  }

  const retries = parsed.retries;
  const lastRetry = retries.length ? retries[retries.length - 1] : null;

  // ── The journal, for engine A ────────────────────────────────────────────
  // HONEST LIMIT, said here rather than discovered later: this engine hands the
  // conversation to a `claude` child through a BUFFERED spawnSync, so these
  // lines are appended once the child has returned. The fidelity is per-turn —
  // every turn and every tool round trip is here — but the durability is not:
  // a parent killed mid-dispatch leaves a header, an empty progress log, and no
  // result, which reads as the orphan it is.
  if (a.journal) {
    for (const r of retries) extraJournalAppend(a.journal, Object.assign({ event: "api_retry" }, r));
    let n = 0;
    for (const t of parsed.tool_names) extraJournalAppend(a.journal, { turn: ++n, tool: t.name, path: t.path, ok: null });
    extraJournalAppend(a.journal, {
      event: "result",
      format,
      exit_code: exit.status,
      events: parsed.events,
      tool_uses: parsed.tool_uses,
      tool_results: parsed.tool_results,
      is_error: !!(result && result.is_error),
      subtype: (result && result.subtype) || null,
      model: (result && result.model) || null,
      usage: result ? extraUsageVector(result.usage) : null,
    });
  }

  const base = {
    engine: "claude-shim",
    format,
    exit_code: exit.status,
    duration_ms,
    attempts,
    output_file: outFile,
    api_retries: retries,
    // SIGTERM is exit 143 — worth naming, because "143" reads like a crash and
    // is in fact us killing the child at the wall clock.
    signalled: exit.status === 143 || exit.signal === "SIGTERM",
  };

  if (!result) {
    // Claude Code prints an in-run failure as the RESULT on stdout, so a run
    // with no parseable result at all is a different fact from a run that
    // failed: the transport itself did not work.
    const cls = lastRetry && lastRetry.error ? lastRetry.error : "malformed-return";
    return Object.assign(base, {
      ok: false,
      outcome: "failed",
      reason: cls,
      retry: classifyFailure(cls).retry,
      error:
        (lastRetry && lastRetry.error ? classifyFailure(cls).label + " — " : "") +
        (String(stderr).trim().split("\n").slice(-3).join(" ").slice(0, 300) || "the worker produced no parseable result object."),
    });
  }

  const usage = extraUsageVector(result.usage);
  const isError = result.is_error === true;
  const subtype = result.subtype || null;
  // Hitting --max-turns exits with an error and IS NOT A FAILURE. It is a
  // capped run with real work in the tree, and reporting it as `failed` would
  // throw that work away and pay for it twice.
  const hitCap = subtype === "error_max_turns" || /max.?turns/i.test(String(result.result || ""));

  const out = Object.assign(base, {
    // model_reported is the ONLY defence against silent substitution by an
    // aggregator, and it is real quotable evidence rather than an assumption.
    // `unknown` is an honest value and is reported as `unknown`, never as a
    // match. (The comparison itself is the return-validation wave's job.)
    model_requested: models.primary,
    model_reported: result.model || (parsed.init && parsed.init.model) || "unknown",
    model_map: models,
    usage,
    // P9: `total_cost_usd` is deliberately NOT read. On a foreign endpoint it
    // is Anthropic's price table applied to somebody else's bill.
    cost_usd: null,
    cost_note: "priced by /orc-budget from the dated provider table — the worker's own total_cost_usd is Anthropic's rates and is fiction here",
    session_id: result.session_id || null,
    text: typeof result.result === "string" ? result.result : null,
    tool_uses: parsed.tool_uses,
    tool_results: parsed.tool_results,
  });

  if (hitCap)
    return Object.assign(out, {
      ok: true,
      outcome: "partial",
      reason: "max-turns",
      error: "the worker hit its turn cap. Whatever it finished is in the worktree; the rest is not done.",
    });
  if (isError) {
    const cls = lastRetry && lastRetry.error ? lastRetry.error : "unknown";
    return Object.assign(out, {
      ok: false,
      outcome: "failed",
      reason: cls,
      retry: classifyFailure(cls).retry,
      error: classifyFailure(cls).label + (result.result ? " — " + String(result.result).slice(0, 300) : ""),
    });
  }
  return Object.assign(out, { ok: true, outcome: "done", reason: null, error: null });
}

// ══ ENGINE C: `api` — ORC's OWN TOOL LOOP ══════════════════════════════════
//
// Why a second engine exists at all, now that `claude-shim` demonstrably works:
// THIS IS THE ONLY ENGINE THAT COMPOSES THE REQUEST BODY. Engine A hands the
// conversation to a `claude` child and can add HEADERS but not body FIELDS —
// ANTHROPIC_CUSTOM_HEADERS is headers, and that is the whole of its reach. So
// two things are possible here and nowhere else:
//
//   · a routing POLICY that is enforced rather than hoped for (F6) — "never
//     serve this from a provider that retains data", "refuse a provider that
//     cannot do tool calls", expressed as body fields the aggregator obeys;
//   · SEEING who actually served the request (U4) — an aggregator's
//     provider-level fallback is on by DEFAULT and it PRESERVES the model id,
//     so `model_reported == model_requested` reads clean while the code went to
//     a different company. The response's own `provider` echo is the only way
//     that becomes visible, and only a body-composing engine ever sees it.
//
// That is why this engine survives the plan's cut list even though A is
// simpler: A is the cheaper transport, C is the only honest one.
//
// It is also the engine with NO dependencies whatsoever — no `claude` on PATH,
// no third-party CLI, no npm package. Node's built-in http/https through
// extraHttp(), and nothing else.

// A default only. A route row's --max-turns and the slice both outrank it.
const EXTRA_API_MAX_TURNS = 30;
// One Read's ceiling, and one tool RESULT's ceiling. A tool result travels back
// up the wire as prompt tokens on EVERY subsequent turn, so an unbounded one is
// not a memory problem, it is a bill.
const EXTRA_API_READ_BYTES = 256 * 1024;
const EXTRA_API_TOOL_OUT = 32 * 1024;
const EXTRA_API_GLOB_MAX = 400;
const EXTRA_API_GREP_MAX = 200;
// The response ceiling for ONE completion. extraHttp's default is 2 MB, which
// is right for a models list and wrong for a long completion.
const EXTRA_API_RESP_BYTES = 16 * 1024 * 1024;
const EXTRA_API_SKIP_DIRS = new Set([
  "node_modules", ".git", ".claude", ".hg", ".svn",
  "dist", "build", "out", "coverage", ".next", ".nuxt", ".turbo",
  ".venv", "venv", "__pycache__", "target", "vendor",
]);

// ── The completions URL, DERIVED from the base ─────────────────────────────
// If the base already carries a version segment (`/v1`, `/api/v1`,
// `/api/paas/v4`, `/compatible-mode/v1`) the path is `/chat/completions`; a
// base with no version segment wants `/v1/chat/completions`. This is derivable
// from the one thing the catalog IS authoritative about — the base URL — so it
// does not add an eleventh field that could disagree with it.
// `--completions-path` on the profile overrides it for a gateway that does
// neither.
function apiCompletionsUrl(prof) {
  const base = String(prof.base_url || "").replace(/\/+$/, "");
  if (prof.completions_path) return joinUrl(base, prof.completions_path);
  return joinUrl(base, (/\/v\d+(?:[a-z]*\d*)?$/i.test(base) ? "" : "/v1") + "/chat/completions");
}

// ── F6 — the guarantee engine A cannot make ────────────────────────────────
// The DEFAULT IS NO BLOCK, deliberately. Sending routing directives nobody
// asked for would change where a request goes without saying so, which is the
// exact failure this whole subsystem is shaped around. `orc extra privacy`
// sets it, and every dispatch PRINTS which policy is in force — including when
// the answer is "none", because "no policy" and "a policy that did not apply"
// must not look the same.
function apiProviderPolicy(prof) {
  const p = prof && prof.privacy;
  const none = {
    block: null,
    summary:
      "none - this endpoint's own default routing applies. On an aggregator that means allow_fallbacks is ON, and a provider-level reroute KEEPS the model id.",
  };
  if (!p || typeof p !== "object") return none;
  const block = {};
  if (p.zdr === true) block.zdr = true;
  if (p.data_collection) block.data_collection = p.data_collection;
  if (p.require_parameters === true) block.require_parameters = true;
  if (Array.isArray(p.only) && p.only.length) block.only = p.only.slice();
  if (p.allow_fallbacks === false) block.allow_fallbacks = false;
  const keys = Object.keys(block);
  if (!keys.length) return none;
  return {
    block,
    summary: keys
      .map((k) => k + "=" + (Array.isArray(block[k]) ? block[k].join("|") : block[k]))
      .join(" · "),
  };
}

// ── The fence ──────────────────────────────────────────────────────────────
// A foreign worker is running tools against the user's real checkout. Two
// separate rules, and the difference between them matters:
//
//   CONTAINMENT — every path any tool receives is resolved and refused if it
//   leaves the repository root. Absolute, `..`, a symlink target outside: all
//   refused. This applies to READS as well as writes, because reading
//   ~/.ssh/id_rsa into a prompt is the leak, not the write.
//
//   DECLARATION — a WRITE is refused unless the slice declared that file.
//   declared_files is what makes a parallel wave conflict-free; a worker that
//   writes outside it has invalidated the conflict graph the whole wave was
//   scheduled against, and the wave, not the file, is the casualty.
//
// Paths resolve against the slice's cwd (the repo root unless the slice
// narrowed it) and containment is checked against the ROOT. The declared-files
// comparison uses the path RELATIVE TO THE ROOT, because that is what
// declared_files is in every other ORC artifact.
function apiResolvePath(root, cwd, p) {
  if (typeof p !== "string" || !p.trim())
    return { ok: false, error: "`path` is required and must be a non-empty string." };
  const abs = path.resolve(cwd, p);
  const rel = path.relative(root, abs);
  // The root ITSELF is inside the root — `Glob` with path "." is a legitimate
  // call and refusing it would look like the fence misfiring. A WRITE to "."
  // still cannot pass, because "." matches no declared file.
  if (rel === "") return { ok: true, abs, rel: "." };
  if (rel.startsWith("..") || path.isAbsolute(rel))
    return {
      ok: false,
      escaped: true,
      error: `REFUSED: "${p}" resolves to ${abs}, which is outside the repository root (${root}). Every path a foreign worker names is resolved against the root and refused if it escapes - reads included.`,
    };
  // A symlink pointing out is the same escape by a longer road.
  try {
    const r2 = path.relative(fs.realpathSync(root), fs.realpathSync(abs));
    if (r2.startsWith("..") || path.isAbsolute(r2))
      return { ok: false, escaped: true, error: `REFUSED: "${p}" is a link that resolves outside the repository root.` };
  } catch (_) {
    // Does not exist yet - normal for a Write. The lexical check above stands.
  }
  return { ok: true, abs, rel: rel.split(path.sep).join("/") };
}

// Enough glob for a declared-files list: `**` crosses `/`, `*` does not, `?` is
// one non-`/` character. It is NOT a glob library and does not pretend to be —
// a declared_files entry is written by ORC's own planner, not improvised.
function apiGlobToRe(pat) {
  let re = "";
  for (let i = 0; i < pat.length; i++) {
    const c = pat[i];
    if (c === "*") {
      if (pat[i + 1] === "*") {
        i++;
        if (pat[i + 1] === "/") i++;
        re += "(?:.*/)?";
      } else re += "[^/]*";
    } else if (c === "?") re += "[^/]";
    else re += c.replace(/[.+^${}()|[\]\\]/g, "\\$&");
  }
  return new RegExp("^" + re + "$");
}

function apiDeclaredMatch(declared, rel) {
  for (const raw of declared || []) {
    const t = String(raw || "").replace(/\\/g, "/").replace(/^\.\//, "");
    if (!t) continue;
    if (t === rel) return t;
    if (t.endsWith("/") && rel.startsWith(t)) return t;
    if (/[*?]/.test(t) && apiGlobToRe(t).test(rel)) return t;
  }
  return null;
}

function apiWriteGate(slice, rel) {
  const declared = slice.declared_files || [];
  if (!declared.length)
    return {
      ok: false,
      error:
        "REFUSED: this task slice declared no files, so nothing may be written. A slice that means to write names its files - that list is what makes a parallel wave conflict-free.",
    };
  const hit = apiDeclaredMatch(declared, rel);
  if (!hit)
    return {
      ok: false,
      error: `REFUSED: "${rel}" is not in this task's declared_files (${declared.join(", ")}). Writing outside the declaration invalidates the conflict graph the whole wave was scheduled against, so the write is refused rather than the wave silently corrupted.`,
    };
  return { ok: true, matched: hit };
}

// ── Bash, and exactly what is NOT promised about it ────────────────────────
// The fence above is a PATH fence, and a shell command is not path-shaped. ORC
// says so rather than shipping a validator that looks like a sandbox and is
// not: a shell command can reach anything the user can, and no amount of
// string inspection changes that. A fake sandbox would be worse than none,
// because it is the one people would rely on.
//
// What IS promised, precisely:
//   · the tool exists only if the slice's allowed_tools asked for it
//   · the cwd is pinned inside the repository
//   · wall clock and output are bounded
//   · every command is RECORDED VERBATIM in the return, so a run is auditable
//     after the fact even where it cannot be constrained before it
//
// The check that actually catches a stray write is the one that already exists
// and is engine-blind: the worktree delta, the smoke gate, the reviewer.
//
// The tripwire below refuses the two forms that are never an accident. It is a
// TRIPWIRE, not a sandbox, and it says so in the refusal itself so nobody
// reads a pass as a guarantee.
function apiBashTripwire(root, cwd, command) {
  const cmd = String(command || "");
  if (!cmd.trim()) return { ok: false, error: "REFUSED: `command` is required." };
  if (/(^|[\s;&|(])sudo\s/.test(cmd))
    return {
      ok: false,
      error: "REFUSED (tripwire, not a sandbox): `sudo` in a foreign worker's command. ORC does not escalate on someone else's behalf.",
    };
  const tokens = cmd.match(/(?:[A-Za-z]:[\\/]|\/|\.\.[\\/])[^\s"';|&)]*/g) || [];
  for (const t of tokens) {
    const r = apiResolvePath(root, cwd, t);
    if (!r.ok && r.escaped)
      return {
        ok: false,
        error: `REFUSED (tripwire, not a sandbox): the command names "${t}", which is outside the repository root. This check catches an obvious escape; it cannot and does not make an arbitrary shell command safe.`,
      };
  }
  return { ok: true };
}

// ── The tools, in the OpenAI function-calling shape ────────────────────────
// The same six ORC's own executors carry. Their DESCRIPTIONS carry the fence,
// because a worker told the rule up front spends its turns working instead of
// discovering a refusal — and a refusal it can read is one it can recover from.
const EXTRA_API_TOOLS = {
  Read: {
    description: "Read a file from the repository. Paths are relative to the repository root.",
    parameters: {
      type: "object",
      properties: {
        path: { type: "string", description: "Path relative to the repository root." },
        offset: { type: "integer", description: "First line to return (1-based). Optional." },
        limit: { type: "integer", description: "How many lines to return. Optional." },
      },
      required: ["path"],
    },
  },
  Write: {
    description:
      "Write a file, replacing it entirely. REFUSED unless the path is in this task's declared files - that list is in your instructions.",
    parameters: {
      type: "object",
      properties: { path: { type: "string" }, content: { type: "string" } },
      required: ["path", "content"],
    },
  },
  Edit: {
    description:
      "Replace an exact string in a file. old_string must appear exactly once unless replace_all is true. REFUSED unless the path is in this task's declared files.",
    parameters: {
      type: "object",
      properties: {
        path: { type: "string" },
        old_string: { type: "string" },
        new_string: { type: "string" },
        replace_all: { type: "boolean" },
      },
      required: ["path", "old_string", "new_string"],
    },
  },
  Glob: {
    description: "List files matching a glob pattern (** crosses directories, * does not).",
    parameters: {
      type: "object",
      properties: {
        pattern: { type: "string" },
        path: { type: "string", description: "Directory to search under. Optional." },
      },
      required: ["pattern"],
    },
  },
  Grep: {
    description: "Search file contents with a regular expression. Returns file:line matches.",
    parameters: {
      type: "object",
      properties: {
        pattern: { type: "string" },
        path: { type: "string", description: "File or directory to search. Optional." },
        glob: { type: "string", description: "Only search files matching this glob. Optional." },
      },
      required: ["pattern"],
    },
  },
  Bash: {
    description:
      "Run a shell command with the repository as the working directory. Use it for builds and tests. Every command is recorded in this dispatch's report.",
    parameters: {
      type: "object",
      properties: { command: { type: "string" }, timeout_ms: { type: "integer" } },
      required: ["command"],
    },
  },
};

function apiToolSpecs(names) {
  return names
    .filter((n) => EXTRA_API_TOOLS[n])
    .map((n) => ({ type: "function", function: Object.assign({ name: n }, EXTRA_API_TOOLS[n]) }));
}

// ── Running one tool call ──────────────────────────────────────────────────
// Returns { ok, text, error, wrote }. `text` is what goes back up the wire as
// the tool result, and A REFUSAL IS A LEGITIMATE TOOL RESULT: the worker needs
// to read it and try something else, not have the run torn down under it.
// WHICH FILE, for the journal line only. Arguments arrive as a model-composed
// string, so this parses defensively and answers null rather than guessing —
// `Bash` has no path at all, and inventing one would be worse than an em dash.
function apiToolPath(argsJson) {
  try {
    const a = typeof argsJson === "string" ? JSON.parse(argsJson || "{}") : argsJson || {};
    const v = a.path || a.file_path || a.file || null;
    return typeof v === "string" && v.trim() ? v.trim().slice(0, 300) : null;
  } catch (_) {
    return null;
  }
}

function apiRunTool(ctx, name, argsJson, state) {
  const { root, cwd, slice, timeouts } = ctx;
  const clip = (s) => {
    const t = String(s === undefined || s === null ? "" : s);
    return t.length > EXTRA_API_TOOL_OUT
      ? t.slice(0, EXTRA_API_TOOL_OUT) +
          `\n… [truncated at ${EXTRA_API_TOOL_OUT} bytes - a tool result is re-sent as prompt tokens on every later turn]`
      : t;
  };
  let a;
  try {
    a = typeof argsJson === "string" ? JSON.parse(argsJson || "{}") : argsJson || {};
  } catch (e) {
    return {
      ok: false,
      text: `REFUSED: your arguments for ${name} were not valid JSON (${e.message}). Send them again as a JSON object.`,
      error: "bad-arguments",
    };
  }
  const fenced = (p) => apiResolvePath(root, cwd, p);

  if (name === "Read") {
    const r = fenced(a.path);
    if (!r.ok) return { ok: false, text: r.error, error: "fence" };
    let buf;
    try {
      buf = fs.readFileSync(r.abs);
    } catch (e) {
      return { ok: false, text: `cannot read ${r.rel}: ${e.code || e.message}`, error: "read-failed" };
    }
    let text = buf.slice(0, EXTRA_API_READ_BYTES).toString("utf8");
    if (buf.length > EXTRA_API_READ_BYTES)
      text += `\n… [file is ${buf.length} bytes; the first ${EXTRA_API_READ_BYTES} are shown]`;
    if (a.offset || a.limit) {
      const lines = text.split(/\r?\n/);
      const from = Math.max(1, Number(a.offset) || 1);
      const n = Number(a.limit) || lines.length;
      text = lines
        .slice(from - 1, from - 1 + n)
        .map((l, i) => `${from + i}\t${l}`)
        .join("\n");
    }
    return { ok: true, text: clip(text) };
  }

  if (name === "Write" || name === "Edit") {
    const r = fenced(a.path);
    if (!r.ok) return { ok: false, text: r.error, error: "fence" };
    const gate = apiWriteGate(slice, r.rel);
    if (!gate.ok) return { ok: false, text: gate.error, error: "undeclared" };
    if (name === "Write") {
      if (typeof a.content !== "string")
        return { ok: false, text: "REFUSED: `content` must be a string.", error: "bad-arguments" };
      try {
        fs.mkdirSync(path.dirname(r.abs), { recursive: true });
        fs.writeFileSync(r.abs, a.content, "utf8");
      } catch (e) {
        return { ok: false, text: `cannot write ${r.rel}: ${e.code || e.message}`, error: "write-failed" };
      }
      return { ok: true, text: `wrote ${r.rel} (${Buffer.byteLength(a.content, "utf8")} bytes)`, wrote: r.rel };
    }
    let before;
    try {
      before = fs.readFileSync(r.abs, "utf8");
    } catch (e) {
      return { ok: false, text: `cannot read ${r.rel} to edit it: ${e.code || e.message}`, error: "read-failed" };
    }
    if (typeof a.old_string !== "string" || typeof a.new_string !== "string")
      return { ok: false, text: "REFUSED: `old_string` and `new_string` must both be strings.", error: "bad-arguments" };
    const parts = before.split(a.old_string);
    if (parts.length === 1)
      return {
        ok: false,
        text: `old_string was not found in ${r.rel}. Read the file again - it may not say what you think it says.`,
        error: "no-match",
      };
    if (parts.length > 2 && a.replace_all !== true)
      return {
        ok: false,
        text: `old_string appears ${parts.length - 1} times in ${r.rel}. Include more surrounding text, or pass replace_all.`,
        error: "ambiguous",
      };
    const after =
      a.replace_all === true ? parts.join(a.new_string) : parts[0] + a.new_string + parts.slice(1).join(a.old_string);
    try {
      fs.writeFileSync(r.abs, after, "utf8");
    } catch (e) {
      return { ok: false, text: `cannot write ${r.rel}: ${e.code || e.message}`, error: "write-failed" };
    }
    return {
      ok: true,
      text: `edited ${r.rel} (${parts.length - 1} replacement${parts.length === 2 ? "" : "s"})`,
      wrote: r.rel,
    };
  }

  if (name === "Glob" || name === "Grep") {
    const start = a.path ? fenced(a.path) : { ok: true, abs: cwd, rel: "." };
    if (!start.ok) return { ok: false, text: start.error, error: "fence" };
    const files = [];
    const walk = (dir) => {
      if (files.length >= EXTRA_API_GLOB_MAX * 8) return;
      let ents = [];
      try {
        ents = fs.readdirSync(dir, { withFileTypes: true });
      } catch (_) {
        return;
      }
      for (const e of ents) {
        if (e.name.startsWith(".") && e.name !== ".github") continue;
        if (e.isDirectory()) {
          if (EXTRA_API_SKIP_DIRS.has(e.name)) continue;
          walk(path.join(dir, e.name));
        } else if (e.isFile()) files.push(path.join(dir, e.name));
      }
    };
    let stat = null;
    try {
      stat = fs.statSync(start.abs);
    } catch (_) {}
    if (stat && stat.isFile()) files.push(start.abs);
    else walk(start.abs);
    const rels = files.map((f) => path.relative(root, f).split(path.sep).join("/"));

    if (name === "Glob") {
      const re = apiGlobToRe(String(a.pattern || "*"));
      const hits = rels.filter((x) => re.test(x) || re.test(x.split("/").pop()));
      const shown = hits.slice(0, EXTRA_API_GLOB_MAX);
      return {
        ok: true,
        text: clip(
          (shown.join("\n") || "(no match)") +
            (hits.length > shown.length ? `\n… ${hits.length - shown.length} more; narrow the pattern` : "")
        ),
      };
    }
    let re;
    try {
      re = new RegExp(String(a.pattern), "i");
    } catch (e) {
      return { ok: false, text: `that is not a valid regular expression: ${e.message}`, error: "bad-arguments" };
    }
    const only = a.glob ? apiGlobToRe(String(a.glob)) : null;
    const out = [];
    for (const rel of rels) {
      if (only && !only.test(rel) && !only.test(rel.split("/").pop())) continue;
      let body;
      try {
        const b = fs.readFileSync(path.join(root, rel));
        if (b.includes(0)) continue; // binary
        body = b.toString("utf8");
      } catch (_) {
        continue;
      }
      const lines = body.split(/\r?\n/);
      for (let i = 0; i < lines.length; i++) {
        if (re.test(lines[i])) out.push(`${rel}:${i + 1}: ${lines[i].slice(0, 300)}`);
        if (out.length >= EXTRA_API_GREP_MAX) break;
      }
      if (out.length >= EXTRA_API_GREP_MAX) break;
    }
    return {
      ok: true,
      text:
        clip(out.join("\n") || "(no match)") +
        (out.length >= EXTRA_API_GREP_MAX ? `\n… stopped at ${EXTRA_API_GREP_MAX} matches` : ""),
    };
  }

  if (name === "Bash") {
    const tw = apiBashTripwire(root, cwd, a.command);
    if (!tw.ok) return { ok: false, text: tw.error, error: "fence" };
    const ms = Math.max(1000, Math.min(Number(a.timeout_ms) || timeouts.idle_ms, timeouts.idle_ms));
    const t0 = Date.now();
    const r = spawnSync(String(a.command), {
      cwd,
      shell: true,
      encoding: "utf8",
      timeout: ms,
      maxBuffer: EXTRA_API_TOOL_OUT * 4,
      windowsHide: true,
    });
    state.bash_calls.push({
      command: String(a.command),
      exit_code: r.status === undefined ? null : r.status,
      ms: Date.now() - t0,
    });
    if (r.error && r.error.code === "ETIMEDOUT")
      return { ok: false, text: `the command was killed after ${ms}ms.`, error: "timeout" };
    if (r.error) return { ok: false, text: `could not run the command: ${r.error.message}`, error: "spawn-failed" };
    const body = [
      `exit ${r.status}`,
      (r.stdout || "").trim() && "stdout:\n" + r.stdout,
      (r.stderr || "").trim() && "stderr:\n" + r.stderr,
    ]
      .filter(Boolean)
      .join("\n");
    return { ok: r.status === 0, text: clip(body) };
  }

  return { ok: false, text: `REFUSED: there is no tool called "${name}".`, error: "unknown-tool" };
}

// ── The four kinds again, out of an OpenAI-shaped `usage` ──────────────────
// Two of them need care, and both have cost this repo a wrong number before in
// the /orc-budget lane:
//
//  · cache_read. `prompt_tokens` INCLUDES the cached tokens on every endpoint
//    that reports them at all, so FRESH input is prompt_tokens MINUS the cached
//    count. Not subtracting double-counts the largest number in the vector.
//  · cache_write. OpenAI-compatible endpoints do IMPLICIT caching and report no
//    write count, because there is no write charge to report. So this is 0, and
//    ZERO IS THE MEASUREMENT, not missing data - /orc-retro must not read it as
//    a gap. `cache_note` says so ON THE RECORD rather than in a comment no
//    downstream reader ever sees.
function extraApiUsageVector(u) {
  const x = u || {};
  const det = x.prompt_tokens_details || {};
  const cacheRead = Number(det.cached_tokens || x.prompt_cache_hit_tokens || x.cache_read_input_tokens || 0);
  const prompt = Number(x.prompt_tokens || x.input_tokens || 0);
  return {
    input: Math.max(0, prompt - cacheRead),
    cache_write: Number(x.cache_creation_input_tokens || 0),
    cache_read: cacheRead,
    output: Number(x.completion_tokens || x.output_tokens || 0),
  };
}
const extraVectorAdd = (a, b) => ({
  input: a.input + b.input,
  cache_write: a.cache_write + b.cache_write,
  cache_read: a.cache_read + b.cache_read,
  output: a.output + b.output,
});

// An HTTP answer, mapped onto the SAME closed taxonomy engine A classifies
// with. One taxonomy, so `retry` means the same thing whichever engine
// produced it and /orc-retro can aggregate across both.
function apiClassifyHttp(res) {
  if (!res) return "unknown";
  if (res.reason === "timeout") return "timeout";
  if (res.reason === "unreachable") return "unreachable";
  if (res.reason === "redirect-refused") return "redirect-refused";
  if (res.reason === "bad-url") return "invalid_request";
  const s = Number(res.status || 0);
  const t = String(extraErrText(res)).toLowerCase();
  if (s === 401 || s === 403) return "authentication_failed";
  if (s === 402 || /insufficient|balance|billing|credit|quota exceed/.test(t)) return "billing_error";
  if (s === 429) return "rate_limit";
  if (s === 503) return "overloaded";
  if (s >= 500) return "server_error";
  if (/model/.test(t) && /not (exist|found|supported|available)|unknown|invalid|unsupported|no such|unavailable|deprecated/.test(t))
    return "model_not_found";
  if (s === 404) return "model_not_found";
  if (s >= 400) return "invalid_request";
  return "unknown";
}

// ── The system preamble ────────────────────────────────────────────────────
// ORC's own words, ABOVE the slice's standing rules and clearly separated from
// them. A worker that is told the fence up front works inside it; a worker that
// discovers it by refusal burns turns finding out. Naming the declared files
// here is the single highest-value line in the whole prompt.
function apiSystemPreamble(slice, tools) {
  const declared = slice.declared_files || [];
  return [
    "You are executing ONE task inside a real repository, through a tool loop.",
    "",
    "Rules that are enforced, not advisory:",
    "· Every path you name is resolved against the repository root. A path that leaves the root is refused, reads included.",
    declared.length
      ? "· You may WRITE ONLY these files:\n" + declared.map((f) => "    " + f).join("\n")
      : "· This task declared NO files, so every write will be refused. If you believe a file must change, say which one and stop.",
    "· A refusal is information, not a crash. Read it and choose differently.",
    "",
    "Tools available: " + tools.join(", ") + ".",
    "When the task is finished, reply with a short report: what you changed, and anything you could not do.",
  ].join("\n");
}

// ── The loop ───────────────────────────────────────────────────────────────
// Returns THE SAME SHAPE runClaudeShim does. That is not tidiness: the bridge,
// the slot accounting, the render, the trace line and every downstream gate are
// engine-blind, and they stay that way only if the two engines are
// indistinguishable from outside.
//
// Three caps, and each produces a DIFFERENT honest answer:
//   max_turns   -> partial. Work is in the tree and it is not finished.
//   wall clock  -> partial if any file was written, timeout if none was.
//   output cap  -> partial (finish_reason "length"): the reply was cut off
//                  mid-sentence, so the last tool call may never have been made.
// None of them is `done`. A `done` with nothing in the tree is the single most
// expensive lie this engine could tell, because the smoke gate downstream would
// pass a wave that built nothing.
async function runApiEngine(ctx) {
  const { prof, route, key, cfg, slice, cwd, root, workDir } = ctx;
  const started = Date.now();
  const timeouts = extraTimeouts(cfg);
  // The tools read their own budget off ctx, so a caller that did not pass one
  // (the conformance run) still gets the same derived ladder rather than a
  // second, disagreeing set of numbers.
  ctx.timeouts = timeouts;
  const deadline = started + timeouts.wall_ms;
  const fail = (reason, error, extra) =>
    Object.assign(
      {
        engine: "api",
        format: "chat-completions",
        exit_code: null,
        ok: false,
        outcome: "failed",
        reason,
        error,
        retry: classifyFailure(reason).retry,
        duration_ms: Date.now() - started,
      },
      extra || {}
    );

  if (!prof.base_url)
    return fail("invalid_request", `profile "${prof.name}" has no OpenAI-compatible base URL. Engine api talks to one directly, so it cannot start without it.`);

  const url = apiCompletionsUrl(prof);
  const headers = extraAuthHeaders(prof, key);
  const policy = apiProviderPolicy(prof);

  const toolNames = (Array.isArray(slice.allowed_tools) && slice.allowed_tools.length
    ? slice.allowed_tools
    : EXTRA_DEFAULT_TOOLS
  ).filter((t) => EXTRA_API_TOOLS[t]);
  const unknown = (Array.isArray(slice.allowed_tools) ? slice.allowed_tools : []).filter((t) => !EXTRA_API_TOOLS[t]);
  if (unknown.length)
    return fail(
      "invalid_request",
      `the slice asks for tool(s) engine api does not implement: ${unknown.join(", ")}. It implements exactly six - ${Object.keys(EXTRA_API_TOOLS).join(", ")} - because it runs them itself rather than borrowing somebody else's harness.`
    );
  const tools = apiToolSpecs(toolNames);

  const models = extraModelMap(prof, route);
  // Engine C makes EXACTLY the calls ORC composes - there are no background
  // turns, no title generation and no `haiku` alias. So the cheap-companion
  // warning engine A must print does not apply here, and printing it anyway
  // would be a cost warning about a cost that cannot occur.
  models.small = models.primary;
  models.small_source = "n/a";
  models.small_note = null;

  const messages = [
    { role: "system", content: apiSystemPreamble(slice, toolNames) },
  ];
  if (slice.standing_rules && String(slice.standing_rules).trim())
    messages.push({ role: "system", content: String(slice.standing_rules) });
  messages.push({ role: "user", content: slice.prompt });

  const maxTurns = Math.max(1, Number(route.max_turns || slice.max_turns || EXTRA_API_MAX_TURNS));
  const state = { bash_calls: [], wrote: new Set(), tool_calls: [], tool_uses: 0, tool_results: 0 };
  const apiRetries = [];
  const servedBy = [];
  let usage = { input: 0, cache_write: 0, cache_read: 0, output: 0 };
  let reasoningTokens = 0;
  let modelReported = null;
  let finalText = null;
  let turns = 0;
  let cap = null; // "max-turns" | "wall-clock" | "output-cap"
  // Did this endpoint EVER answer cleanly in this dispatch? It is the whole of
  // the evidence separating `unreachable` from `stream-interrupted`.
  let answered = false;

  // THE TRANSCRIPT NOW GOES TO THE JOURNAL, NOT THE DOOMED TEMP DIR.
  //
  // This file was always good evidence and was always destroyed at the moment it
  // mattered: it lived in `workDir`, which the bridge removes in its `finally`.
  // It now lands in `.claude/orc/extra-journal/`, which survives the process
  // that wrote it — and it carries the RUNNING usage vector on every line, so a
  // dispatch that never reached appendExtraSpend still has a floor on what it
  // cost.
  const record = (obj) => extraJournalAppend(ctx.journal, Object.assign({}, obj, { usage: Object.assign({}, usage) }));

  for (turns = 1; ; turns++) {
    if (turns > maxTurns) {
      cap = "max-turns";
      break;
    }
    const left = deadline - Date.now();
    if (left <= 1000) {
      cap = "wall-clock";
      break;
    }

    const body = { model: route.model, messages, stream: false };
    if (tools.length) {
      body.tools = tools;
      body.tool_choice = "auto";
    }
    const maxOut = Number(slice.max_output_tokens || route.max_output_tokens || 0);
    if (maxOut > 0) body.max_tokens = maxOut;
    // F6 - the field engine A cannot reach.
    if (policy.block) body.provider = policy.block;

    // A retryable answer is retried HERE, on the same turn, twice, inside the
    // wall clock. Beyond that it is the caller's fallback (P6) - spending the
    // whole budget on backoff would turn a 60-second failure into a 15-minute
    // one and still fall back.
    let res = null;
    for (let attempt = 1; attempt <= 3; attempt++) {
      const remaining = deadline - Date.now();
      if (remaining <= 1000) break;
      res = await extraHttp({
        url,
        method: "POST",
        headers,
        body,
        timeoutMs: Math.min(timeouts.api_ms, remaining),
        maxBytes: EXTRA_API_RESP_BYTES,
      });
      if (res.ok) {
        answered = true;
        break;
      }
      // A 4xx/5xx is still an ANSWER: the wire reached the host. Only a socket
      // failure leaves `answered` false.
      if (typeof res.status === "number") answered = true;
      const cls = apiClassifyHttp(res);
      apiRetries.push({
        error: cls,
        attempt,
        max_retries: 3,
        status: res.status || null,
        detail: extraErrText(res).slice(0, 200),
        turn: turns,
      });
      // A STRUGGLE THAT ENDS IN A KILLED PROCESS still leaves its record.
      // `api_retries[]` only reaches anybody through a return the dispatch lived
      // long enough to compose, which is precisely the case this journal exists
      // for.
      record({ turn: turns, max_turns: maxTurns, http_attempt: attempt, error: cls, status: res.status || null, detail: extraErrText(res).slice(0, 200) });
      if (!classifyFailure(cls).retry || attempt === 3) break;
      const waitMs = Math.min(4000, 400 * Math.pow(3, attempt - 1));
      if (deadline - Date.now() <= waitMs + 1000) break;
      await new Promise((r) => setTimeout(r, waitMs));
    }

    if (!res || !res.ok) {
      // ESTABLISHED-THEN-DIED vs NEVER-OPENED. The only evidence ORC has is
      // whether this dispatch ALREADY got a clean answer out of this endpoint:
      // if it did, the host is reachable and something cut the conversation. It
      // is an inference from a real fact, and it is bounded — it cannot tell a
      // dropped socket from a host that went down between two turns, and does
      // not claim to. The network probe below decides that half.
      let cls = apiClassifyHttp(res);
      if (cls === "unreachable" && answered) cls = "stream-interrupted";
      return fail(cls, classifyFailure(cls).label + " - " + extraErrText(res), {
        turns,
        api_retries: apiRetries,
        http_status: (res && res.status) || null,
        usage,
        model_requested: route.model,
        model_reported: modelReported || "unknown",
        files_written: [...state.wrote],
        bash_calls: state.bash_calls,
        privacy: { applied: policy.block, summary: policy.summary },
        served_by: servedBy,
      });
    }
    if (res.truncated)
      return fail("response-truncated", `the reply exceeded ${EXTRA_API_RESP_BYTES} bytes and cannot be parsed. Nothing is assumed about what it said.`, {
        turns,
        api_retries: apiRetries,
        usage,
        files_written: [...state.wrote],
      });

    const j = res.json;
    const choice = j && Array.isArray(j.choices) ? j.choices[0] : null;
    if (!choice || !choice.message)
      return fail("malformed-return", `the endpoint answered 200 with no choices[0].message. First bytes: ${String(res.text || JSON.stringify(j || {})).slice(0, 200)}`, {
        turns,
        api_retries: apiRetries,
        usage,
        files_written: [...state.wrote],
      });

    if (j.usage) usage = extraVectorAdd(usage, extraApiUsageVector(j.usage));
    const cd = (j.usage && j.usage.completion_tokens_details) || {};
    reasoningTokens += Number(cd.reasoning_tokens || 0);
    if (j.model) modelReported = j.model;
    // U4 - the provider echo. The ONLY way a provider-level reroute is visible
    // at all, and only a body-composing engine ever receives it.
    if (j.provider && !servedBy.includes(j.provider)) servedBy.push(j.provider);
    record({ turn: turns, max_turns: maxTurns, model: j.model || null, provider: j.provider || null, finish_reason: choice.finish_reason || null });

    const msg = choice.message;
    messages.push({
      role: "assistant",
      content: msg.content === undefined ? null : msg.content,
      tool_calls: msg.tool_calls || undefined,
    });
    if (typeof msg.content === "string" && msg.content.trim()) finalText = msg.content;

    const calls = Array.isArray(msg.tool_calls) ? msg.tool_calls : [];
    if (!calls.length) {
      // finish_reason `length` means the reply was CUT OFF. A cut-off reply may
      // have been about to make a tool call, so it is not a finished run.
      if (choice.finish_reason === "length") cap = "output-cap";
      break;
    }

    for (const c of calls) {
      const fn = (c.function && c.function.name) || c.name || "";
      state.tool_uses++;
      const out = apiRunTool(ctx, fn, (c.function && c.function.arguments) || "{}", state);
      state.tool_results++;
      if (out.wrote) state.wrote.add(out.wrote);
      state.tool_calls.push({ turn: turns, name: fn, ok: out.ok, error: out.error || null });
      // THE PATH, in the journal line and nowhere else. `last_action` has to
      // read "Write src/routes/health.js", not "Write" — a reconciliation that
      // cannot say WHICH file the worker last touched is not a position.
      record({ turn: turns, max_turns: maxTurns, tool: fn, path: apiToolPath((c.function && c.function.arguments) || "{}"), ok: out.ok, error: out.error || null });
      messages.push({
        role: "tool",
        tool_call_id: c.id || fn,
        name: fn,
        content: out.text || "",
      });
    }
  }

  const filesWritten = [...state.wrote];
  const out = {
    engine: "api",
    format: "chat-completions",
    exit_code: null,
    duration_ms: Date.now() - started,
    turns: Math.min(turns, maxTurns),
    max_turns: maxTurns,
    api_retries: apiRetries,
    // A PATH THAT STILL EXISTS, or null. The journal outlives this process; the
    // temp dir this used to point into did not.
    output_file: (ctx.journal && ctx.journal.progress) || null,
    model_requested: route.model,
    // `unknown` is an honest value and is reported as `unknown`, never as a
    // match. The comparison itself is the return-validation wave's job.
    model_reported: modelReported || "unknown",
    model_map: models,
    usage,
    reasoning_tokens: reasoningTokens,
    cache_note:
      "cache_write is 0 because an OpenAI-compatible endpoint caches implicitly and reports no write count - that ZERO IS A MEASUREMENT, not missing data.",
    // P9 - never a cost figure ORC did not price itself.
    cost_usd: null,
    cost_note:
      "priced by /orc-budget from the dated provider table - this engine never reads a cost figure off the wire",
    session_id: null,
    text: finalText,
    tool_uses: state.tool_uses,
    tool_results: state.tool_results,
    tool_calls: state.tool_calls,
    files_written: filesWritten,
    bash_calls: state.bash_calls,
    // F6 / U4, both recorded whether or not they fired.
    privacy: { applied: policy.block, summary: policy.summary },
    served_by: servedBy,
    served_by_note: servedBy.length
      ? servedBy.length > 1
        ? "MORE THAN ONE provider served this one task."
        : null
      : "this endpoint does not name the provider that served the request, so a provider-level reroute is NOT VISIBLE here. That is a limit of the endpoint, not a clean result.",
    reroute:
      servedBy.length > 1 ||
      !!(policy.block && Array.isArray(policy.block.only) && servedBy.some((p) => !policy.block.only.includes(p))),
  };
  if (out.reroute)
    out.reroute_note =
      `the model id was honoured but the serving provider was ${servedBy.join(", ")}` +
      (policy.block && policy.block.only ? ` against a policy of only=${policy.block.only.join("|")}` : "") +
      ". A provider-level reroute PRESERVES the model id, so a model check reads clean while the code went to a different company.";

  if (cap === "max-turns")
    return Object.assign(out, {
      ok: true,
      outcome: "partial",
      reason: "max-turns",
      error: `the worker used all ${maxTurns} turns. ${filesWritten.length ? filesWritten.length + " file(s) changed and are in the worktree" : "nothing was written"}; the rest is not done.`,
    });
  if (cap === "wall-clock") {
    if (!filesWritten.length)
      return Object.assign(fail("timeout", `no answer inside the ${Math.round(timeouts.wall_ms / 1000)}s dispatch wall clock, and nothing was written.`), out, {
        ok: false,
        outcome: "failed",
        reason: "timeout",
        retry: true,
        error: `no answer inside the ${Math.round(timeouts.wall_ms / 1000)}s dispatch wall clock, and nothing was written.`,
      });
    return Object.assign(out, {
      ok: true,
      outcome: "partial",
      reason: "wall-clock",
      error: `the ${Math.round(timeouts.wall_ms / 1000)}s dispatch wall clock expired with ${filesWritten.length} file(s) already changed. Those changes are in the worktree.`,
    });
  }
  if (cap === "output-cap")
    return Object.assign(out, {
      ok: true,
      outcome: "partial",
      reason: "max_output_tokens",
      error: "the reply hit the output-token ceiling and was cut off, so a tool call it was about to make may never have happened.",
    });

  // A clean finish that changed nothing, on a slice that declared files to
  // change, is NOT done. It is the empty-diff case, and calling it done would
  // hand the smoke gate a wave that built nothing.
  if (!filesWritten.length && (slice.declared_files || []).length)
    return Object.assign(out, {
      ok: true,
      outcome: "partial",
      reason: "empty-diff",
      error: `the worker finished and reported back, but wrote none of its ${(slice.declared_files || []).length} declared file(s). "It says it is done" and "the work is done" are different facts.`,
    });

  return Object.assign(out, { ok: true, outcome: "done", reason: null, error: null });
}

// ══ ENGINE B: `cli` — DRIVE A THIRD-PARTY AGENTIC CLI ══════════════════════
//
// The third engine, and the one with the LEAST control. It is worth having
// anyway, for one reason the other two cannot match: somebody has already done
// the provider work. `opencode` fronts 75+ providers behind one interface and
// `codex` speaks OpenAI's own Responses API; neither needs a base URL, a wire
// format or a model map from ORC.
//
// WHAT THIS ENGINE CANNOT DO, said here rather than discovered later:
//
//   · IT CANNOT FENCE. The third-party CLI owns its own tools, so ORC has no
//     say over which paths get read or written. `declared_files` becomes an
//     INSTRUCTION in the task file, which is advice, not enforcement. Engine C
//     enforces it; this one asks. Every return records `fence: {...}` saying so,
//     because a capability gap that is not reported reads as a capability.
//   · IT CANNOT ENFORCE A ROUTING POLICY (F6) and cannot see a provider echo
//     (U4) — it composes no body at all. Engine C is still the only one.
//   · IT MAY NOT REPORT TOKENS. `codex --json` does (`turn.completed.usage`);
//     `opencode --format json` may not. An adapter with no vector returns
//     `usage: null`, NEVER four zeros — "not reported" and "measured zero" are
//     different facts and /orc-budget must be able to tell them apart.
//
// THE ADAPTER TABLE IS THE REGISTRY. Four functions and some data per tool:
// argv, env, parse, and what the tool documents about its own exit codes. A
// fifth tool is a table row, not a new code path.

// The task text and the tool's own output file live in ONE gitignored directory
// INSIDE the repo. Inside, because `codex --sandbox workspace-write` restricts
// writes to the workspace and a temp dir outside it is not writable; gitignored
// and removed in a `finally`, because a crashed run must leave an ignored file
// rather than a staged one.
const EXTRA_CLI_WORK = ".orc-extra";

// The shape of a structured foreign return. `codex --output-schema` enforces it
// on the final message, which is how a foreign worker returns ORC's contract
// instead of prose.
//
// F14e — THIS SHAPE IS PROVIDER-DICTATED, NOT CHOSEN. It used to be documented
// as "deliberately minimal", and that reasoning is what killed engine `cli` on
// codex for a whole release: OpenAI structured outputs require a CLOSED object
// at EVERY level (`additionalProperties: false`), and `required` must list
// EVERY key in `properties`. A permissive floor is not on offer here —
// `additionalProperties: true` is an HTTP 400 raised before the model is
// reached, and flipping only that flag is a SECOND 400, naming
// `files_changed`. An optional field is therefore expressed as a NULLABLE
// UNION, never by omission from `required`.
const EXTRA_CLI_RETURN_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["status", "summary", "files_changed", "unmet", "notes"],
  properties: {
    status: { type: "string", enum: ["done", "partial", "blocked"] },
    summary: { type: "string" },
    files_changed: { type: ["array", "null"], items: { type: "string" } },
    unmet: { type: ["array", "null"], items: { type: "string" } },
    notes: { type: ["string", "null"] },
  },
};

// A token vector out of whatever shape a third-party CLI reports. Codex uses the
// Responses API's names; opencode's are undocumented. The `input_tokens`
// family INCLUDES the cached count, exactly as engine C's does, so fresh input
// is the difference — and RETURNS NULL when there is nothing to read, which is
// the whole point of this function existing separately.
function extraCliUsageVector(u, kinds) {
  if (!u || typeof u !== "object") return null;
  const num = (...names) => {
    for (const n of names) if (u[n] !== undefined && u[n] !== null && !isNaN(Number(u[n]))) return Number(u[n]);
    return null;
  };
  // W7 (v0.51.0) — the two shipped tools report a DIFFERENT NUMBER OF KINDS, so
  // the adapter says which ones it can report and this function never invents
  // the rest. A cache field the tool has no concept of reads NULL, never 0:
  // unknown is not zero (/orc-budget).
  const canWrite = !kinds || kinds.indexOf("cache_write") !== -1;
  // opencode nests them: `tokens.cache.{write,read}` beside `tokens.{input,output}`.
  const nest = u.cache && typeof u.cache === "object" ? u.cache : null;
  const nestNum = (k) => (nest && nest[k] !== undefined && nest[k] !== null && !isNaN(Number(nest[k])) ? Number(nest[k]) : null);
  const cached = num("cached_input_tokens", "cache_read_input_tokens", "prompt_cache_hit_tokens", "cached_tokens");
  const cacheRead = cached === null ? nestNum("read") : cached;
  const written = num("cache_creation_input_tokens", "cache_write_input_tokens", "cache_write");
  const cacheWrite = written === null ? nestNum("write") : written;
  const inp = num("input_tokens", "prompt_tokens", "input");
  const outp = num("output_tokens", "completion_tokens", "output");
  if (inp === null && outp === null) return null;
  // The `input` family INCLUDES the cached count on both tools, exactly as
  // engine A's does, so fresh input is the difference. A nested vector reports
  // them separately already, so nothing is subtracted twice.
  const fresh = cached === null && nest ? inp || 0 : Math.max(0, (inp || 0) - (cacheRead || 0));
  return {
    input: fresh,
    cache_write: canWrite ? cacheWrite || 0 : null,
    cache_read: cacheRead || 0,
    output: outp || 0,
  };
}

// Tolerant, because two of these three formats are undocumented. Returns every
// JSON object it can find, in order, whether the stream was JSONL or one blob.
function extraCliJsonEvents(text) {
  const out = [];
  const t = String(text || "");
  for (const line of t.split(/\r?\n/)) {
    const s = line.trim();
    if (!s || (s[0] !== "{" && s[0] !== "[")) continue;
    try {
      const v = JSON.parse(s);
      if (Array.isArray(v)) out.push(...v.filter((x) => x && typeof x === "object"));
      else out.push(v);
    } catch (_) {}
  }
  if (out.length) return out;
  // Not JSONL. One object spanning the whole stream is the other common shape.
  try {
    const v = JSON.parse(t);
    if (Array.isArray(v)) return v.filter((x) => x && typeof x === "object");
    if (v && typeof v === "object") return [v];
  } catch (_) {}
  return [];
}

// Depth-first hunt for a nested value, used ONLY where the shape is
// undocumented. It is a fallback and it says which key it found, so a wrong
// guess is visible in the return rather than silently believed.
function extraCliDig(events, keys, pred) {
  const seen = new Set();
  const walk = (v, depth) => {
    if (!v || typeof v !== "object" || depth > 6 || seen.has(v)) return null;
    seen.add(v);
    for (const k of keys) {
      const got = v[k];
      if (got !== undefined && got !== null && (!pred || pred(got))) return { key: k, value: got };
    }
    for (const k of Object.keys(v)) {
      const r = walk(v[k], depth + 1);
      if (r) return r;
    }
    return null;
  };
  for (let i = events.length - 1; i >= 0; i--) {
    const r = walk(events[i], 0);
    if (r) return r;
  }
  return null;
}

// Classify a non-zero exit from what the tool actually SAID. Neither of these
// tools documents an exit-code table, so this is pattern matching on stderr and
// it is labelled that way — `exit_codes: null` on the row is the honest record
// that there is nothing to map against.
const EXTRA_CLI_STDERR_PATTERNS = [
  [/unauthor|invalid.{0,12}(api.?key|token|credential)|401|authentication/i, "authentication_failed"],
  [/rate.?limit|429|too many requests/i, "rate_limit"],
  [/insufficient|balance|billing|credit|payment/i, "billing_error"],
  [/model .{0,60}(not found|does not exist|unknown|unsupported|not supported)|unknown model/i, "model_not_found"],
  [/wire_api|model_providers|config\.toml/i, "invalid_request"],
  [/sandbox|permission denied|read-?only/i, "invalid_request"],
  [/timed? ?out|deadline/i, "timeout"],
  [/econnrefused|enotfound|network|unreachable|dns/i, "unreachable"],
  [/5\d\d|internal server error|overloaded/i, "server_error"],
];
function extraCliClassify(stderr, stdout) {
  const t = String(stderr || "") + "\n" + String(stdout || "");
  for (const [re, key] of EXTRA_CLI_STDERR_PATTERNS) if (re.test(t)) return key;
  return "unknown";
}

// F14f — THE PROVIDER'S OWN ERROR OBJECT BEATS A STRING MATCH ON STDERR, and
// this table is why. codex nests the upstream API's verbatim error inside its
// `error` / `turn.failed` events, and that error's own `type` and `code` are
// already the vocabulary EXTRA_FAILURES speaks. Reading stderr instead cost a
// release: the real `invalid_request_error` sat inside a JSON string in
// STDOUT while codex printed the benign `Reading additional input from
// stdin...` on STDERR, nothing matched, and a precisely-diagnosable
// non-retryable failure came back as `unknown` — `retry: false` reached by
// luck rather than by diagnosis.
const EXTRA_CLI_ERROR_TYPES = {
  invalid_request_error: "invalid_request",
  invalid_json_schema: "invalid_request",
  invalid_schema: "invalid_request",
  invalid_prompt: "invalid_request",
  authentication_error: "authentication_failed",
  invalid_api_key: "authentication_failed",
  permission_error: "authentication_failed",
  rate_limit_error: "rate_limit",
  rate_limit_exceeded: "rate_limit",
  insufficient_quota: "billing_error",
  billing_error: "billing_error",
  model_not_found: "model_not_found",
  overloaded_error: "server_error",
  api_error: "server_error",
  server_error: "server_error",
  timeout: "timeout",
};
const EXTRA_CLI_STATUS_KEYS = ["status", "status_code", "http_status"];
function extraCliStatusKey(status) {
  const n = Number(status);
  if (!n || isNaN(n)) return null;
  if (n === 401 || n === 403) return "authentication_failed";
  if (n === 402) return "billing_error";
  if (n === 404) return "model_not_found";
  if (n === 408) return "timeout";
  if (n === 429) return "rate_limit";
  if (n >= 500) return "server_error";
  if (n >= 400) return "invalid_request";
  return null;
}
// Walks the FAILED events only, so a `status` field somewhere in the happy
// path can never be read as an HTTP code. Returns an EXTRA_FAILURES key or
// null — null means "ask the stderr patterns", never "there was no failure".
function extraCliClassifyEvents(events) {
  if (!Array.isArray(events) || !events.length) return null;
  const seen = new Set();
  let hit = null;
  const consider = (o) => {
    if (hit) return;
    for (const k of ["type", "code"]) {
      const v = String(o[k] || "").toLowerCase();
      if (v && EXTRA_CLI_ERROR_TYPES[v]) {
        hit = EXTRA_CLI_ERROR_TYPES[v];
        return;
      }
    }
    for (const k of EXTRA_CLI_STATUS_KEYS) {
      const s = extraCliStatusKey(o[k]);
      if (s) {
        hit = s;
        return;
      }
    }
  };
  const walk = (v, depth) => {
    if (hit || !v || typeof v !== "object" || depth > 6 || seen.has(v)) return;
    seen.add(v);
    if (Array.isArray(v)) {
      for (const x of v) walk(x, depth + 1);
      return;
    }
    consider(v);
    for (const k of Object.keys(v)) walk(v[k], depth + 1);
  };
  walk(events, 0);
  return hit;
}
// The message a human reads, out of an event whose `error` may be a string, an
// object, or nested one level deeper again.
function extraCliEventMessage(ev) {
  if (!ev || typeof ev !== "object") return null;
  const pick = (v) => {
    if (typeof v === "string" && v.trim()) return v.trim();
    if (v && typeof v === "object") {
      for (const k of ["message", "error", "detail", "reason"]) {
        const s = pick(v[k]);
        if (s) return s;
      }
    }
    return null;
  };
  return pick(ev.message) || pick(ev.error) || null;
}

// R16 — the effort a foreign worker runs at comes from the CLAUDE AGENT this
// route displaced: that band was going to be `…-high`, so send `high`. A
// number ORC invented to satisfy an interface would not be a routing decision
// the user made.
function extraEffortFromAgent(agent) {
  const m = /-(xhigh|high|med|low)$/.exec(String(agent || ""));
  if (!m) return null;
  return m[1] === "med" ? "medium" : m[1];
}
// F14b — an unsupported level is coerced to the nearest supported one SILENTLY,
// so ORC pins one from codex's own closed set and records it as REQUESTED. It
// never claims the effort was honoured; nothing in the event stream could tell
// it either way.
function extraCodexEffort(effort) {
  const set = EXTRA_CLI_ADAPTERS.codex.efforts;
  const v = String(effort || "")
    .toLowerCase()
    .replace(/^extra[_-]high$/, "xhigh");
  return set.indexOf(v) === -1 ? "medium" : v;
}

const EXTRA_CLI_ADAPTERS = {
  // ── opencode ─────────────────────────────────────────────────────────────
  // Built first for one concrete reason: `opencode serve` + `--attach` removes
  // the cold-boot cost from EVERY dispatch, which on a wave of ten tasks is the
  // difference between this engine being usable and being a curiosity.
  opencode: {
    label: "opencode",
    docs_url: "https://opencode.ai/docs/cli/",
    // `--model provider/model` is opencode's own format, and it falls out of
    // the route target for free: `orc extra route set 0-30 oc/deepseek/x`
    // splits on the FIRST slash, so the model string arrives as
    // `deepseek/x` — already the shape opencode wants.
    model_note: "opencode wants provider/model, which is what a route target of <profile>/<provider>/<model> already produces",
    exit_codes: null,
    // F6 — opencode reports token counts and NEVER a model id: there is no
    // `model`, `modelID` or `model_id` anywhere in its event stream. So the
    // "you did not get the model you asked for" check is structurally
    // unavailable here, and that is STATED rather than rendered as a blank.
    supports: {
      attach: true,
      output_schema: false,
      usage: "undocumented",
      usage_kinds: ["input", "cache_write", "cache_read", "output"],
      reports_model: false,
      fence: false,
    },
    // F3 — A LIVE DEFECT, not a nice-to-have. `--auto` was replaced by
    // `--dangerously-skip-permissions`, and opencode's argument parser is
    // STRICT: an unknown flag prints the help text and exits 1 BEFORE any
    // network call, so every dispatch on this adapter failed — and failed
    // looking like a model problem. The flag is therefore picked from the
    // PROBED VERSION rather than hard-coded, and an unknown version takes the
    // current one (a rename happens once; a revert does not).
    permissionFlag(version) {
      return version && cmpVersion(version, "1.10.0") < 0 ? "--auto" : "--dangerously-skip-permissions";
    },
    // The paid rung: one fixed-constant prompt, in a scratch directory, against
    // one model id.
    // THE MESSAGE COMES FIRST, here and in argv(), and the two must never
    // diverge: `-f` is a yargs ARRAY flag and a yargs array is GREEDY — every
    // non-flag token after it is swallowed as another file path. A trailing
    // message therefore left `message..` EMPTY and opencode exited 1 before the
    // network. Same family as the --auto rename above: a strict parser failing
    // for free, looking exactly like a model problem. This probe has no `-f`
    // today, and it is ordered this way so it cannot acquire the bug when one
    // is added.
    probeArgv(a) {
      return [
        "run",
        a.prompt,
        "--model",
        a.model,
        "--format",
        "json",
        EXTRA_CLI_ADAPTERS.opencode.permissionFlag(a.version),
        "--dir",
        a.dir,
      ];
    },
    argv(a) {
      const v = [
        "run",
        // FIRST, and first on purpose — see probeArgv above. The greedy `-f`
        // array flag ate this message when it was last, so `message..` arrived
        // empty and the dispatch died in the parser.
        "Do the task described in the attached file. It is the whole brief; nothing else is implied.",
        "--model",
        a.model,
        "--format",
        "json",
        EXTRA_CLI_ADAPTERS.opencode.permissionFlag(a.cli && a.cli.version),
        "--dir",
        a.root,
      ];
      if (a.cli.agent) v.push("--agent", a.cli.agent);
      // R6. A running `opencode serve` is joined rather than booted.
      if (a.cli.attach) v.push("--attach", a.cli.attach);
      v.push(...(a.cli.extra_args || []));
      // LAST, and last on purpose: a greedy array flag at the END of argv has
      // nothing left to swallow. `-f` attaches a FILE to the message, which is
      // how the whole task text stays out of argv — the same reasoning as
      // engine A's stdin prompt: Windows caps a command line at 32,767
      // characters and a task slice is not ORC's own text.
      v.push("-f", a.taskFile);
      return v;
    },
    env(a) {
      const e = {};
      // For engine `cli` the credential's VARIABLE NAME is the one the
      // third-party tool reads — that is what the user configured it as. ORC
      // does not translate it into an ANTHROPIC_* name, which would be a name
      // opencode has never heard of.
      if (a.cli_key_name && a.key) e[a.cli_key_name] = a.key;
      if (process.env.OPENCODE_SERVER_PASSWORD) e.OPENCODE_SERVER_PASSWORD = process.env.OPENCODE_SERVER_PASSWORD;
      return e;
    },
    parse(out) {
      const events = extraCliJsonEvents(out.stdout);
      const usageHit = extraCliDig(events, ["usage", "tokens"], (v) => v && typeof v === "object");
      const usage = usageHit
        ? extraCliUsageVector(usageHit.value, EXTRA_CLI_ADAPTERS.opencode.supports.usage_kinds)
        : null;
      const modelHit = extraCliDig(events, ["model", "modelID", "model_id"], (v) => typeof v === "string");
      const textHit = extraCliDig(events, ["text", "content", "message", "output"], (v) => typeof v === "string" && v.trim());
      return {
        parsed: events.length ? "json-events" : "text",
        events: events.length,
        usage,
        usage_source: usageHit ? usageHit.key : null,
        model_reported: modelHit ? modelHit.value : null,
        text: (textHit && textHit.value) || String(out.stdout || "").trim().slice(0, 4000) || null,
      };
    },
  },
  // ── codex ────────────────────────────────────────────────────────────────
  // The one adapter that can be MADE to return ORC's contract rather than
  // prose: `--output-schema` validates the final message against a JSON Schema.
  // That is the same guarantee engine A only gets to hope for, and it is why
  // this adapter is worth its config awkwardness.
  codex: {
    label: "codex",
    docs_url: "https://learn.chatgpt.com/docs/non-interactive-mode.md",
    model_note: "codex takes a bare model id; WHICH PROVIDER serves it is decided by ~/.codex/config.toml, not by a flag",
    exit_codes: null,
    // F14c — A CORRECTION. An earlier reading of this adapter said codex reports
    // its model. IT DOES NOT: `exec --json` emits thread.started, turn.started,
    // item.completed, turn.completed, turn.failed and error, and NEITHER the
    // model NOR the effort appears in any of them. Both shipped adapters are
    // `reports_model: false`, and a substitution is therefore invisible on this
    // engine — which is stated wherever it is rendered, never left blank.
    //
    // F14d — A CORRECTION, and it is the mirror image of the bug it replaces.
    // This adapter used to declare THREE numbers on the grounds that "there is
    // no cache-write count", so `cache_write` read NULL. There is one:
    // `turn.completed.usage` on codex-cli 0.149.0 carries input_tokens,
    // cached_input_tokens, cache_write_input_tokens, output_tokens and
    // reasoning_output_tokens — observed on two live turns, 23-08-2026. Declaring
    // three kinds meant codex reported a real measurement and ORC threw it away
    // and then said it was never reported: MEASURED RENDERED AS UNKNOWN, which
    // is the same family of lie as unknown rendered as zero.
    //
    // `reasoning_output_tokens` is deliberately NOT read. The Responses API
    // counts reasoning tokens INSIDE `output_tokens`, so adding them would
    // double-count and /orc-budget would over-price every codex run. That is
    // very likely but unproven, and an unproven pricing change is worse than a
    // missing one.
    supports: {
      attach: false,
      output_schema: true,
      usage: "documented (turn.completed.usage)",
      usage_kinds: ["input", "cache_write", "cache_read", "output"],
      reports_model: false,
      fence: false,
    },
    // F14b — the closed set, and an unsupported level is coerced to the nearest
    // supported one SILENTLY. So ORC records what it REQUESTED and never claims
    // the effort was honoured.
    // The documented set is minimal|low|medium|high|xhigh; the live model
    // catalog on this machine also advertises `max` and `ultra` per model, so
    // both are accepted rather than silently coerced down to medium.
    efforts: ["minimal", "low", "medium", "high", "xhigh", "max", "ultra"],
    // The paid rung: one fixed-constant prompt, in a scratch directory, with the
    // most restrictive sandbox the tool offers.
    probeArgv(a) {
      return [
        "exec",
        "--json",
        "--sandbox",
        "read-only",
        "--ephemeral",
        "--skip-git-repo-check",
        "-m",
        a.model,
        "-c",
        'model_reasoning_effort="low"',
        "-C",
        a.dir,
        a.prompt,
      ];
    },
    // A refusal that costs nothing, made before the binary is spawned.
    //
    // Codex reads custom providers from `model_providers` in the USER-LEVEL
    // `~/.codex/config.toml` and IGNORES a project-local one for that key. ORC
    // does not write it: a file outside the project is not ORC's to edit, and a
    // credential-bearing config least of all. So ORC READS it and reports —
    // including the trap that costs a whole run, which is that OpenAI removed
    // the chat/completions protocol in February 2026, so a provider row with
    // `wire_api = "chat"` (or with none) fails at STARTUP.
    preflight(a) {
      const cfgPath = path.join(os.homedir(), ".codex", "config.toml");
      let toml = null;
      try {
        toml = fs.readFileSync(cfgPath, "utf8");
      } catch (_) {}
      const paste = [
        `[model_providers.${a.prof.name}]`,
        `name = "${a.prof.name}"`,
        `base_url = "${a.prof.base_url || "https://<provider>/v1"}"`,
        `env_key = "${(a.prof.credential && a.prof.credential.key_name) || "PROVIDER_API_KEY"}"`,
        `wire_api = "responses"`,
        `query_params = {}`,
      ].join("\n");
      // A DEAD row is an error, because the run cannot start with one — codex
      // refuses at startup and the failure would land mid-wave.
      if (toml && /wire_api\s*=\s*"chat"/.test(toml))
        return {
          ok: false,
          reason: "invalid_request",
          error:
            `${cfgPath} contains \`wire_api = "chat"\`. OpenAI removed the chat/completions protocol in February 2026 and codex now FAILS AT STARTUP on that row — ` +
            "so this dispatch would die before it began. `responses` is the default and the only value.",
          remedy: paste,
        };
      // No `model_providers` at all is only a problem if this profile expects a
      // custom one. It is a WARNING carried on the return, never a refusal:
      // codex's built-in providers work without it, and refusing here would
      // break the ordinary case to protect the unusual one.
      if (a.prof.base_url && !(toml && /\[model_providers\./.test(toml)))
        return { ok: true, warn: `${cfgPath} declares no \`model_providers\`, and this profile names a custom base URL. If codex does not know this provider the dispatch will fail at startup — codex reads that key from the USER-level config only, and ignores a project-local one.`, remedy: paste };
      return { ok: true };
    },
    argv(a) {
      const v = [
        "exec",
        "--json",
        // The default is READ-ONLY. Without this the worker cannot edit a file
        // and the run looks like a model that refused to work.
        "--sandbox",
        "workspace-write",
        // No session state accumulating between dispatches.
        "--ephemeral",
        // The contract, enforced by codex itself.
        "--output-schema",
        a.schemaFile,
        // Read the final answer from a FILE rather than scraping it out of an
        // event stream whose shape is not ours.
        "--output-last-message",
        a.outFile,
        "--model",
        a.model,
        // F14a — `-m` sets the MODEL. It does not set the compute budget: that
        // is `model_reasoning_effort`, an independent key that otherwise falls
        // through to the user's own config and finally to `medium`. There is no
        // dedicated flag, and `-c key=value` (parsed as TOML) is the only inline
        // route. Deliberately NOT `--profile`: a profile is a file the user owns
        // and can contain anything, so it is not a setting ORC can rely on.
        "-c",
        'model_reasoning_effort="' + extraCodexEffort(a.route && a.route.effort) + '"',
      ];
      // Only when there is no repo to check. Passing it unconditionally would
      // switch off a safety net that is doing its job everywhere else.
      if (!a.isGit) v.push("--skip-git-repo-check");
      v.push(...(a.cli.extra_args || []));
      // Short, ORC-authored, and it points at the file. The slice's own text
      // never reaches argv.
      v.push(`Read ${EXTRA_CLI_WORK}/task.md and do exactly the task it describes. It is the whole brief.`);
      return v;
    },
    env(a) {
      const e = {};
      // BOTH, and for two different code paths: CODEX_API_KEY is what codex
      // reads for a single invocation against a built-in provider, while a
      // custom `model_providers` row names its own variable via `env_key` —
      // which is the name the user configured on this profile.
      if (a.key) e.CODEX_API_KEY = a.key;
      if (a.cli_key_name && a.key) e[a.cli_key_name] = a.key;
      return e;
    },
    // F14f — the adapter's own classifier, consulted BEFORE the stderr
    // patterns. It reads the upstream error object codex relays verbatim, which
    // is a diagnosis rather than a guess — so whatever it returns is labelled
    // as coming from the provider's own error object, never as a stderr
    // pattern. A field that says where a verdict came from must not lie.
    classify(events) {
      return extraCliClassifyEvents(events);
    },
    parse(out) {
      const events = extraCliJsonEvents(out.stdout);
      // DOCUMENTED shape, so it is read by name rather than dug for. A dig
      // would silently accept the wrong field the day the shape changes.
      const completed = events.filter((e) => e && e.type === "turn.completed");
      const failed = events.filter((e) => e && (e.type === "turn.failed" || e.type === "error"));
      const last = completed[completed.length - 1] || null;
      const usage = last ? extraCliUsageVector(last.usage, EXTRA_CLI_ADAPTERS.codex.supports.usage_kinds) : null;
      // PROBED FOR, never assumed either way. The field is absent today (F14c)
      // and the issue that asked for it is closed without saying it was added,
      // so this reads it if it appears and reports null if it does not.
      const model = (last && last.model) || null;
      return {
        parsed: events.length ? "jsonl" : "text",
        events: events.length,
        // The RAW failed events, kept so `classify` can read the provider's own
        // error object. `turn_failed` below is the human sentence; this is the
        // diagnosis.
        failed_events: failed,
        usage,
        usage_source: usage ? "turn.completed.usage" : null,
        model_reported: model,
        turn_failed: failed.length ? extraCliEventMessage(failed[failed.length - 1]) || "turn failed" : null,
        // The final message came from --output-last-message; the event stream
        // is only the telemetry.
        text: (out.lastMessage && out.lastMessage.trim()) || String(out.stdout || "").trim().slice(0, 4000) || null,
      };
    },
  },
};

// ── The runner ─────────────────────────────────────────────────────────────
// Returns THE SAME SHAPE `runClaudeShim` and `runApiEngine` return. That is the
// property that kept the bridge, the slot accounting, the render and every
// downstream gate untouched across three engines, and it is worth more than any
// one adapter.
async function runCliEngine(ctx) {
  const { prof, route, key, cfg, slice, cwd, root, workDir } = ctx;
  const started = Date.now();
  const timeouts = extraTimeouts(cfg);
  const fail = (reason, error, extra) =>
    Object.assign(
      {
        engine: "cli",
        exit_code: null,
        ok: false,
        outcome: "failed",
        reason,
        error,
        retry: classifyFailure(reason).retry,
        duration_ms: Date.now() - started,
      },
      extra || {}
    );

  const cli = prof.cli || {};
  const adapter = EXTRA_CLI_ADAPTERS[cli.bin];
  if (!adapter)
    return fail(
      "engine-unavailable",
      `no adapter for "${cli.bin || "(no binary configured)"}". This release ships: ${Object.keys(EXTRA_CLI_ADAPTERS).join(", ")}. ` +
        "An adapter is a table row — argv, env, output parser, what the tool documents about its exit codes — not a new code path, so adding one is small."
    );
  const bin = whichBin(cli.bin);
  if (!bin) return fail("engine-unavailable", `\`${cli.bin}\` is not on PATH — engine cli dispatches by running it.`);

  // ONE gitignored directory inside the repo, because a workspace-write sandbox
  // cannot write outside the workspace. Removed in the finally below; the
  // .gitignore line is written idempotently so a crashed run leaves an IGNORED
  // file rather than a staged one.
  ensureExtraGitignore(root);
  const wdir = path.join(root, EXTRA_CLI_WORK);
  const taskFile = path.join(wdir, "task.md");
  const outFile = path.join(wdir, "last-message.txt");
  // A7 — written ONLY for an adapter that consumes it. The shape is
  // provider-dictated (F14e), so it belongs to the provider that dictates it;
  // opencode declares `output_schema: false` and never reads the file.
  const schemaFile = adapter.supports.output_schema ? path.join(workDir, "return.schema.json") : null;

  const declared = slice.declared_files || [];
  // The fence is an INSTRUCTION here, not a rule. Saying "you may only write
  // these files" to a tool whose file access ORC does not mediate is advice —
  // so it is written as an instruction and REPORTED as advice.
  const task = [
    "# Task",
    "",
    slice.prompt,
    "",
    declared.length
      ? "## Files you may change\n\n" +
        declared.map((f) => "- `" + f + "`" ).join("\n") +
        "\n\nDo not change anything else. This list is what lets several tasks run at once without colliding."
      : "## Files\n\nThis task declared no files to change. If you believe one must change, say which and stop.",
    "",
    "## When you finish",
    "",
    "Reply with JSON: `status` (`done` | `partial` | `blocked`), `summary`, `files_changed`, `unmet`, `notes`.",
    slice.standing_rules && String(slice.standing_rules).trim() ? "\n## Standing rules\n\n" + slice.standing_rules : "",
  ].join("\n");

  let out;
  let preflightWarn = null;
  let preflightRemedy = null;
  const argvUsed = [];
  try {
    fs.mkdirSync(wdir, { recursive: true });
    fs.writeFileSync(taskFile, task, "utf8");
    if (schemaFile) fs.writeFileSync(schemaFile, JSON.stringify(EXTRA_CLI_RETURN_SCHEMA, null, 2), "utf8");

    const a = {
      prof,
      route,
      cli,
      cfg,
      key,
      cli_key_name: (prof.credential && prof.credential.key_name) || null,
      model: route.model,
      root,
      cwd,
      taskFile,
      outFile,
      schemaFile,
      timeouts,
      isGit: fs.existsSync(path.join(root, ".git")),
    };
    // A per-adapter refusal that can be made BEFORE spending anything. Codex's
    // custom-provider requirement is the reason this hook exists.
    if (adapter.preflight) {
      const pf = adapter.preflight(a);
      if (pf && !pf.ok) return fail(pf.reason || "invalid_request", pf.error, { adapter: cli.bin, remedy: pf.remedy || null });
      // A warning is carried THROUGH, not printed and forgotten. It is the only
      // notice a user gets that a config file outside this project decides
      // whether the next wave starts at all.
      if (pf && pf.warn) {
        preflightWarn = pf.warn;
        preflightRemedy = pf.remedy || null;
      }
    }

    const argv = adapter.argv(a);
    argvUsed.push(...argv);

    // ── The child's stdout goes to a FILE DESCRIPTOR, not a buffer ─────────
    //
    // spawnSync buffers stdout in the PARENT, and the parent is what dies. With
    // the bytes redirected onto the journal's progress file, a killed parent, a
    // closed terminal or a sleeping machine leaves the child's whole output on
    // disk — and a wall-clock kill leaves whatever it had produced by then.
    //
    // stderr stays a PIPE on purpose: `classifyOut` reads it separately, and
    // blending the two streams into one file would feed stderr lines to an
    // adapter's JSON-event parser.
    //
    // The child's bytes are read back from the OFFSET the file was at before the
    // spawn. The progress file is ORC's own journal and may already hold ORC's
    // own JSON lines; handing those to `extraCliJsonEvents` would let the
    // adapter dig ORC's fields out of them and report ORC's own `usage` as the
    // worker's.
    let fd = null;
    let offset = 0;
    if (ctx.journal) {
      try {
        fd = fs.openSync(ctx.journal.progress, "a");
        offset = fs.fstatSync(fd).size;
      } catch (_) {
        fd = null;
      }
    }
    const spawnOpts = {
      cwd,
      env: Object.assign({}, process.env, adapter.env(a)),
      windowsHide: true,
    };
    // stdout to the fd when there is one; a pipe we never read otherwise, so a
    // journal-less dispatch cannot fill the OS buffer and deadlock the child.
    spawnOpts.stdio = ["ignore", fd !== null ? fd : "pipe", "pipe"];
    // v0.56.1 — ASYNCHRONOUS, so something can watch. See runCliChild.
    const r = await runCliChild(bin, argv, spawnOpts, {
      started,
      wall_ms: timeouts.wall_ms,
      stall_ms: timeouts.stall_ms,
      progressFile: (ctx.journal && ctx.journal.progress) || null,
      root,
      declared,
    });
    // READ BACK FIRST, before any early return. A timeout is exactly the case
    // where the bytes matter most, and the old code discarded them.
    let captured = null;
    if (fd !== null) {
      try {
        fs.closeSync(fd);
      } catch (_) {}
      try {
        const buf = fs.readFileSync(ctx.journal.progress);
        captured = buf.slice(offset, offset + EXTRA_MAX_OUTPUT_BYTES).toString("utf8");
      } catch (_) {
        captured = null;
      }
    }
    const childOut = captured === null ? r.stdout || "" : captured;

    // WHERE THE BYTES ARE, on either stop. The child's output up to the kill is
    // on disk, and a path to a file that exists is the difference between a bare
    // verdict and a position somebody can look at.
    const stopEvidence = {
      adapter: cli.bin,
      argv: argvUsed,
      // NAMED on a stop, not only on a completion. The trace line falls back to
      // `?` without it, and `orc extra stats` dedupes on the fields that line
      // carries — so a stalled dispatch would be unjoinable to a price, a
      // provider or another stall on a different model.
      model_requested: route.model,
      output_file: (ctx.journal && ctx.journal.progress) || null,
      captured_bytes: captured === null ? null : Buffer.byteLength(captured, "utf8"),
      timeline: {
        first_byte_ms: r.first_byte_ms,
        last_progress_ms: r.last_progress_ms,
        longest_gap_ms: r.longest_gap_ms,
        quiet_for_ms: r.stall_ms,
        stall_budget_ms: timeouts.stall_ms,
        wall_budget_ms: timeouts.wall_ms,
      },
    };
    // THE STALL, NAMED. Reported before the wall clock because it is the more
    // specific fact: a stall is a POSITION to resume from, a wall-clock timeout
    // is a budget to raise, and calling the first one the second is what sent
    // fifteen-minute stalls to a from-scratch Claude fallback.
    if (r.stopped_by === "stall")
      return fail(
        "stalled",
        `${cli.bin} produced nothing for ${Math.round(r.stall_ms / 1000)}s (the stall budget is ${Math.round(
          timeouts.stall_ms / 1000
        )}s) — no output, no stderr and no declared file changed. The process was still running; it had stopped working. ` +
          "`orc extra reconcile` has the position it left, and `extra_resume` continues from it instead of starting over.",
        stopEvidence
      );
    if (r.stopped_by === "wall")
      return fail("timeout", `no answer in ${Math.round(timeouts.wall_ms / 1000)}s (the dispatch wall clock).`, stopEvidence);
    if (r.error) return fail("spawn-failed", r.error.message, { adapter: cli.bin, argv: argvUsed });

    let lastMessage = null;
    try {
      lastMessage = fs.readFileSync(outFile, "utf8");
    } catch (_) {}
    out = { stdout: childOut, stderr: r.stderr || "", status: r.status, lastMessage, timeline: stopEvidence.timeline };
  } finally {
    try {
      fs.rmSync(wdir, { recursive: true, force: true });
    } catch (_) {}
  }

  const p = adapter.parse(out);
  // A tool that can be made to answer in a schema is asked to. Prose parsing
  // stays the FLOOR either way — the same rule engine A applies to stream-json.
  let structured = null;
  for (const src of [out.lastMessage, p.text]) {
    if (!src) continue;
    const m = /\{[\s\S]*\}/.exec(String(src));
    if (!m) continue;
    try {
      const v = JSON.parse(m[0]);
      if (v && typeof v === "object" && typeof v.status === "string") {
        structured = v;
        break;
      }
    } catch (_) {}
  }

  const base = {
    engine: "cli",
    adapter: cli.bin,
    format: p.parsed,
    exit_code: out.status,
    duration_ms: Date.now() - started,
    argv: argvUsed,
    attached: cli.attach || null,
    // v0.54.0 — NO LONGER NULL. The comment this replaced was right about paths
    // and wrong about the file: the answer was never to report a dead path, it
    // was to stop deleting the evidence. The child's stdout is redirected onto
    // the journal's progress file, which is outside the work dir and outlives
    // this process. `streamed-opaque`: these are BYTES, and ORC did not
    // interpret them.
    output_file: (ctx.journal && ctx.journal.progress) || null,
    model_requested: route.model,
    model_reported: p.model_reported || "unknown",
    model_map: { primary: route.model, small: route.model, small_source: "n/a", small_note: null, context_tokens: null },
    // NULL, not four zeros. "the tool did not report tokens" and "the tool
    // reported zero" are different facts, and /orc-budget must never price the
    // first as the second.
    usage: p.usage,
    usage_note: p.usage
      ? `token counts read from the tool's own \`${p.usage_source}\` field`
      : `${cli.bin} reported no token counts, so there is NO vector — not a zero one. /orc-budget prices this run from its sample history or says it cannot.`,
    // P9, on every engine.
    cost_usd: null,
    cost_note: "priced by /orc-budget from the dated provider table — never from a figure the worker supplied",
    session_id: null,
    text: p.text,
    structured_output: structured,
    structured_output_ok: !!structured,
    tool_uses: p.events || 0,
    tool_results: p.events || 0,
    events: p.events || 0,
    // The capability gap, ON THE RECORD. A gap that is not reported reads as a
    // capability, and this one matters: it is the difference between "ORC
    // refused that write" and "ORC asked it not to".
    fence: {
      paths: false,
      declared_files: false,
      note:
        `${cli.bin} owns its own tools, so ORC does not mediate its file access. declared_files was written into the task as an INSTRUCTION, which is advice, not enforcement. ` +
        "The checks that actually catch a stray write are the engine-blind ones: the worktree delta, the smoke gate and the reviewer. Engine `api` enforces the fence itself.",
    },
    privacy: {
      applied: null,
      summary: `none — engine cli composes no request body, so a routing policy cannot be enforced through it (engine api can). ${cli.bin} sends what ${cli.bin} decides to send.`,
    },
    preflight_warning: preflightWarn,
    preflight_remedy: preflightRemedy,
    // The same timeline the stall report carries, on EVERY outcome. A budget you
    // can only see when it fires is a budget nobody can set before it does.
    timeline: out.timeline || null,
  };

  // F14f — THE PROVIDER'S OWN ERROR OBJECT FIRST, the stderr patterns as the
  // fallback. And `classified_from` says WHICH of the two answered, because a
  // field that reports where a verdict came from must not lie about it.
  const classifyOut = (stderr, stdout) => {
    const fromEvents = adapter.classify ? adapter.classify(p.failed_events || []) : null;
    if (fromEvents)
      return {
        reason: fromEvents,
        from: `the provider's own error object — ${cli.bin} relays the upstream error verbatim in its event stream, so this is a diagnosis and not a guess`,
      };
    return {
      reason: extraCliClassify(stderr, stdout),
      from: "stderr pattern — neither adapter documents an exit-code table, so this is what the tool SAID, not what its exit code means",
    };
  };
  const failedMessage = () =>
    extraCliEventMessage(p.failed_events && p.failed_events[p.failed_events.length - 1]);

  if (out.status !== 0) {
    const cls = classifyOut(out.stderr, out.stdout);
    return Object.assign(base, {
      ok: false,
      outcome: "failed",
      reason: cls.reason,
      retry: classifyFailure(cls.reason).retry,
      classified_from: cls.from,
      error:
        classifyFailure(cls.reason).label +
        " — " +
        String(
          failedMessage() ||
            String(out.stderr).trim().split("\n").slice(-3).join(" ") ||
            `exit ${out.status} with nothing on stderr`
        ).slice(0, 300),
    });
  }

  // Exit 0 is not success — F3, and it is not specific to engine A.
  //
  // Three ways a tool that exited 0 has still told us it failed, in order of how
  // explicit they are: a `turn.failed` event, a structured `blocked`, and no
  // parseable output at all.
  if (p.turn_failed) {
    const cls = classifyOut(p.turn_failed, "");
    return Object.assign(base, {
      ok: false,
      outcome: "failed",
      reason: cls.reason,
      retry: classifyFailure(cls.reason).retry,
      classified_from: cls.from,
      error: `${cli.bin} reported a failed turn and still exited ${out.status}: ${String(p.turn_failed).slice(0, 300)}`,
    });
  }
  // A tool that reports `blocked` in its own structured answer has told us it
  // did not do the work, whatever it exited with.
  if (structured && structured.status === "blocked")
    return Object.assign(base, {
      ok: false,
      outcome: "failed",
      reason: "unknown",
      retry: false,
      error: "the worker reported `blocked`: " + String(structured.summary || "").slice(0, 300),
    });
  if (structured && structured.status === "partial")
    return Object.assign(base, {
      ok: true,
      outcome: "partial",
      reason: "worker-reported-partial",
      error: "the worker reported `partial`: " + String(structured.summary || "").slice(0, 300),
    });
  if (!p.text && !structured)
    return Object.assign(base, {
      ok: false,
      outcome: "failed",
      reason: "malformed-return",
      retry: true,
      error: `${cli.bin} exited 0 and produced nothing ORC can read. Neither its JSON stream nor its final message parsed.`,
    });
  return Object.assign(base, { ok: true, outcome: "done", reason: null, error: null });
}

// ── orc extra dispatch — THE BRIDGE ────────────────────────────────────────
//
// The orchestrator writes a task slice to a file and runs this. The slice
// content is IDENTICAL to what a Claude executor would receive — only the
// transport differs, which is the property that keeps every gate downstream
// engine-blind.
//
// Exit codes: 0 done · 1 failed · 2 unknown profile / bad slice · 3 not routed
// foreign (the caller dispatches to Claude normally) · 4 partial.
async function extraDispatch(claudeDir) {
  const asJson = wantsJson();
  const taskFile = flag("--task");
  const bail = (code, obj) => {
    if (asJson) emitJson(obj, code);
    console.error("❌ " + (obj.error || obj.reason));
    process.exit(code);
  };
  if (typeof taskFile !== "string")
    bail(2, { ok: false, reason: "no-slice", error: "usage: orc extra dispatch --task <slice.json> [--json]" });

  let slice;
  // THE RAW BYTES, kept. The slice is IMMUTABLE across attempts, and the hash of
  // what was actually read is the only thing that can later prove the plan did
  // not move underneath a resume.
  let sliceRaw = "";
  try {
    sliceRaw = fs.readFileSync(path.resolve(taskFile), "utf8");
    slice = JSON.parse(sliceRaw);
  } catch (e) {
    bail(2, { ok: false, reason: "bad-slice", error: `cannot read the task slice at ${taskFile}: ${e.message}` });
  }
  if (!slice || typeof slice.prompt !== "string" || !slice.prompt.trim())
    bail(2, { ok: false, reason: "bad-slice", error: "the task slice needs a non-empty `prompt`." });
  // v0.55.0 — TWO SHAPES, EXACTLY ONE OF THEM. A scored task carries a `score`
  // and resolves a BAND; a slot task carries a `slot` and resolves a POSITION.
  // Both present is `bad-slice`, refused BY NAME: a bridge that picked one for
  // you would be making the routing decision the whole subsystem exists to make
  // visible. Everything downstream of the resolve is UNTOUCHED — the fence, the
  // cap, the credential triangle, the journal, the spend log, the resume ladder.
  const hasSlot = typeof slice.slot === "string" && slice.slot.trim();
  const hasScore = slice.score !== undefined && slice.score !== null;
  if (hasSlot && hasScore)
    bail(2, {
      ok: false,
      reason: "bad-slice",
      error: "the task slice carries BOTH a `score` and a `slot` — those are two shapes of one question. Pass one.",
    });
  if (!hasSlot && !hasScore)
    bail(2, {
      ok: false,
      reason: "bad-slice",
      error: `the task slice needs a \`score\` between 0 and 100, or a \`slot\` (one of: ${EXTRA_SLOT_IDS.join(", ")}) — routing is what this command does.`,
    });
  // NOT DERIVED FROM ANYTHING. A slot dispatch has no score, and a number ORC
  // invented to satisfy an interface is not a routing decision the user made.
  const score = hasSlot ? null : Number(slice.score);
  if (!hasSlot && (!Number.isFinite(score) || score < 0 || score > 100))
    bail(2, { ok: false, reason: "bad-slice", error: "the task slice needs a `score` between 0 and 100 — routing is what this command does." });

  // P5 — the SAME resolver the preflight printed. The bridge never re-derives
  // a band, so what runs is always what the user was told would run.
  const riskCount = (slice.risk || []).length || slice.risk_count || 0;
  const res = hasSlot
    ? extraResolveSlot(claudeDir, slice.slot.trim(), { risk: riskCount, boundary: slice.boundary || null })
    : extraResolveFor(claudeDir, score, { role: slice.role || "executor", risk: riskCount });
  if (hasSlot && !res.ok)
    bail(2, { ok: false, reason: "bad-slice", error: res.error, known: res.known });
  if (res.resolved !== "extra") {
    const obj = Object.assign({ ok: true, dispatched: false, reason: "not-routed" }, res);
    if (asJson) emitJson(obj, 3);
    console.log(`\n  not routed foreign — ${res.why}\n`);
    process.exit(3);
  }

  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, res.profile);
  // The row that decided this dispatch. A band row for a score, a SLOT row for
  // a position — the same field names (`model`, `small_model`, `max_turns`), so
  // every engine below is untouched.
  const route = hasSlot
    ? ledger.slots.find((r) => r.slot === slice.slot.trim())
    : ledger.routes.find((r) => bandCovers(r, score));
  const cfg = resolvedConfig(claudeDir);

  // The credential. `ambientKey` is how an unattended wave works: the lane
  // unlocked the vault ONCE at the Phase-1 stop and hands the value down
  // through env, never through argv and never back to disk.
  // v0.53.3 — and it is a FALLBACK, not an override. It applies only where the
  // vault cannot be opened here, so a variable left over from another profile
  // can no longer outrank the key the user just verified.
  // v0.52.0 — `--passphrase-stdin` survives the cache as the UN-CACHED escape
  // hatch for `extra_unlock: per-dispatch`, where the whole point is that
  // nothing is kept. It mirrors `extra ping`'s flag exactly, including the
  // refusal to combine it with a key on the same stdin.
  const dispatchPassStdin = args.includes("--passphrase-stdin");
  if (dispatchPassStdin && args.includes("--key-stdin"))
    bail(2, {
      ok: false,
      reason: "stdin-conflict",
      error:
        "--key-stdin and --passphrase-stdin cannot be combined: stdin's first line would be a key on one reading and a passphrase on the other.",
    });
  if (typeof flag("--passphrase") === "string")
    bail(2, {
      ok: false,
      reason: "passphrase-in-argv",
      error:
        "`--passphrase <value>` does not exist on purpose: argv is world-readable in a process list and lands in shell history. Use --passphrase-stdin.",
    });
  const cred = extraCredentialValue(claudeDir, prof, {
    ambientKey: process.env.ORC_EXTRA_KEY || null,
    passphrase: dispatchPassStdin ? (readStdinLines()[0] || "").trim() || null : null,
    // A per-dispatch passphrase is used and DROPPED. No silent re-cache: only
    // the save modal writes the cache, because only the save modal asked how
    // long.
    noSession: dispatchPassStdin,
    maxAttempts: cfg.extra_vault_max_attempts,
  });
  if (!cred.ok)
    bail(1, {
      ok: false,
      dispatched: false,
      outcome: "failed",
      reason: cred.reason,
      error: cred.error,
      retry: false,
      profile: prof.name,
      // P6 — the caller always learns which Claude agent to fall back to,
      // without a second lookup.
      fallback_to: res.claude,
    });

  // The cap is enforced HERE, not remembered by the caller. A refusal is a
  // clean, cheap answer the orchestrator can act on — it holds the task for
  // the next wave — so it is exit 3 (`this one is not going foreign right
  // now`), the same code as an unrouted task, rather than a failure.
  const timeouts = extraTimeouts(cfg);
  const cap = Math.max(1, Number(cfg.extra_max_concurrent) || 1);
  // NOTE the name: this is the CONCURRENCY slot (`extra_max_concurrent`), not a
  // role SLOT. Two different things called "slot" in one function is how a
  // future edit picks the wrong one.
  const capSlot = takeSlot(claudeDir, cap, timeouts.wall_ms + 60000, slice.task_id);
  if (!capSlot.ok) {
    const obj = {
      ok: true,
      dispatched: false,
      reason: "concurrency-cap",
      cap,
      in_flight: capSlot.live,
      error: `extra_max_concurrent is ${cap} and ${capSlot.live} foreign ${capSlot.live === 1 ? "dispatch is" : "dispatches are"} already running. Per-provider rate limits are undocumented in aggregate, so ORC does not queue past the cap.`,
      fallback_to: res.claude,
    };
    if (asJson) emitJson(obj, 3);
    console.log("\n  " + ui.mark.warn(obj.error) + "\n");
    process.exit(3);
  }

  const root = repoRootOf(claudeDir);

  // ── THE JOURNAL HEADER ───────────────────────────────────────────────────
  // Written HERE: after the credential and the slot resolve, and BEFORE the
  // first byte leaves the machine. This is the only moment at which the
  // repository is provably untouched by this dispatch, so it is the only moment
  // at which a baseline means anything.
  //
  // The sweep runs first and once per process — its clock is a dispatch, never
  // a timer: a background process that deletes run state is a background
  // process nobody can audit.
  try {
    extraJournalSweep(claudeDir);
  } catch (_) {}
  const attempt = extraJournalNextAttempt(claudeDir, slice.task_id);
  const fidelity = EXTRA_JOURNAL_FIDELITY[prof.engine] || "none";
  // WHICH RUN THIS BELONGED TO — read from the trace pointer on disk, exactly
  // as `appendExtraSpend` already reads it, and never handed in by a caller.
  // The journal lives outside {run_dir} on purpose (a crashed session is the
  // moment nobody remembers the slug), but the stall DEMOTION counts
  // consecutive stalls WITHIN one run, so the run has to be on the record at
  // the moment of dispatch or the count is a guess later. `null` is the honest
  // answer when no run is open, and an attempt with `run: null` is never
  // counted into any run's clock — it is counted as SKIPPED and named.
  const jrun = extraCurrentRun(claudeDir);
  const journal = extraJournalHeader(claudeDir, {
    v: 1,
    task_id: slice.task_id || null,
    attempt,
    run: jrun ? jrun.slug : null,
    lane: jrun ? jrun.lane : null,
    // Non-null only on a resume. It is what lets a return be attributed to the
    // attempt it continued rather than read as a fresh first try.
    resumed_from: slice.resumed_from || null,
    slice_path: path.resolve(taskFile),
    slice_sha256: sha256(sliceRaw),
    profile: prof.name,
    provider: prof.provider || null,
    engine: prof.engine,
    model_requested: (route && route.model) || null,
    band: res.band || null,
    // `slot:<slot>` rides in `band`, so the journal, the trace parser, the
    // eight-field dedupe and `extraStatsScan` are all untouched.
    slot: hasSlot ? slice.slot.trim() : null,
    score,
    role: hasSlot ? slice.slot.trim() : slice.role || "executor",
    declared_files: slice.declared_files || [],
    acceptance: Array.isArray(slice.acceptance) ? slice.acceptance : [],
    cwd: slice.cwd || null,
    started_at: new Date().toISOString(),
    // The two halves of the LIVENESS gate. A "disconnected" dispatch is not
    // provably dead — a client-side socket timeout does not stop a provider
    // streaming, and a SIGTERM'd child may still be mid-write() — so a resume is
    // gated on the pid being gone OR this lease having expired, never on "the
    // parent is not here any more".
    pid: process.pid,
    lease_expires_at: new Date(Date.now() + timeouts.wall_ms + 60000).toISOString(),
    journal_fidelity: fidelity,
    journal_fidelity_note: EXTRA_JOURNAL_FIDELITY_NOTE[fidelity] || "this engine records nothing.",
    baseline: extraBaseline(root, slice.declared_files || []),
  });

  const workDir = fs.mkdtempSync(path.join(os.tmpdir(), "orc-extra-"));
  let out;
  try {
    const cwd = slice.cwd ? path.resolve(root, slice.cwd) : root;
    if (prof.engine === "claude-shim") out = runClaudeShim({ prof, route, key: cred.value, cfg, slice, cwd, workDir, journal });
    else if (prof.engine === "api")
      out = await runApiEngine({ prof, route, key: cred.value, cfg, slice, cwd, root, workDir, timeouts, journal });
    else if (prof.engine === "cli")
      // R16 — the EFFORT a codex dispatch runs at is derived from the CLAUDE
      // AGENT this route displaced. `-m` alone does not set the compute budget
      // (model and model_reasoning_effort are two independent keys), so a
      // dispatch that named only the model would run at whatever that user's
      // config happens to say — a silent downgrade, the exact failure class the
      // `expect=<model>/<effort>` trace design exists to catch.
      out = await runCliEngine({
        prof,
        route: Object.assign({}, route, { effort: route.effort || extraEffortFromAgent(res.claude && res.claude.agent) }),
        key: cred.value,
        cfg,
        slice,
        cwd,
        root,
        workDir,
        timeouts,
        journal,
      });
    else
      out = {
        ok: false,
        outcome: "failed",
        reason: "engine-unavailable",
        retry: false,
        error: `engine "${prof.engine}" is not one of: ${EXTRA_ENGINES.join(", ")}.`,
      };
  } finally {
    // The system-prompt file is ORC's own composition, not a secret — but the
    // work dir is temporary by design and a stale one is just litter.
    try {
      fs.rmSync(workDir, { recursive: true, force: true });
    } catch (_) {}
    releaseSlot(claudeDir, timeouts.wall_ms + 60000);
  }

  const payload = Object.assign(
    {
      dispatched: true,
      task_id: slice.task_id || null,
      // NULL for a slot, and not derived from anything.
      score,
      band: res.band,
      slot: hasSlot ? slice.slot.trim() : null,
      via: res.via,
      profile: prof.name,
      provider: prof.provider,
      engine: prof.engine,
      declared_files: slice.declared_files || [],
      fallback_to: res.claude,
      // v0.56.1 — the same agent, plus WHETHER THE USER GETS A SAY. `fallback_to`
      // keeps its name, its position and its meaning; this is beside it.
      fallback: extraFallbackChoice(cfg, res.claude),
      announce: res.announce,
      // v0.53.3 — WHAT WAS ACTUALLY SENT, not what the profile declares. The
      // return used to copy `credential.source: "vault"` off the profile while
      // the request carried an environment variable, so the return was wrong
      // about its own behaviour and the one field that could have named the bug
      // confirmed the wrong story instead.
      credential: { source: cred.source, key_name: cred.key_name || null },
    },
    out
  );
  // THE POSITION, on the record. `journal` is null when it could not be written
  // — best effort by construction — and that null is the honest answer, not an
  // omission: a consumer that finds null knows there is nothing to reconcile
  // against, which is a different fact from a journal it has not looked for.
  payload.attempt = attempt;
  payload.journal = journal ? journal.header : null;
  payload.journal_fidelity = journal ? fidelity : null;
  if (slice.resumed_from) {
    payload.resumed_from = slice.resumed_from;
    payload.preexisting = slice.preexisting || [];
    payload.files_preexisting = (slice.preexisting || []).filter((x) => x && x.state !== "untouched").length;
    // A RESUME RETURN OWES `resume_state`. Absent on a slice with no
    // `resumed_from` is correct; absent on THIS one is malformed, and the lane
    // validates it (`_shared/return-validation.md` §2b). Said here so the lane
    // does not have to infer it from the presence of another field.
    payload.resume_expected = true;
  }

  // ── ATTRIBUTION ──────────────────────────────────────────────────────────
  // Whose fault was it. It is not decoration: it decides the recovery. "your
  // internet is down" means a Claude fallback would fail too, so falling back
  // burns a second failure and a second cost for nothing; "the provider is down"
  // means the fallback is exactly right. ORC could not tell those apart and did
  // the same thing either way.
  //
  // The probe runs ONLY on the three reasons that cannot be told apart without
  // it, and it is ONE unauthenticated 3-second request on a path that has
  // already failed.
  let probe = null;
  if (payload.outcome !== "done" && EXTRA_PROBE_REASONS.has(payload.reason)) {
    try {
      probe = await extraNetworkProbe(prof, readCatalog());
    } catch (_) {
      probe = null;
    }
    // RECLASSIFIED ONLY WHERE THE PROBE IS THE DISCRIMINATOR — a connection
    // that dropped, with the network also down, is a different fact and a
    // different recovery. A `timeout` keeps its word: a slow endpoint and a dead
    // link are not the same failure, and the attribution says `network` either
    // way without renaming what the engine saw.
    if (probe && probe.ran && probe.reachable === false && (payload.reason === "unreachable" || payload.reason === "stream-interrupted")) {
      payload.reason_original = payload.reason;
      payload.reason = "connection-lost-local";
      payload.retry = classifyFailure("connection-lost-local").retry;
    }
  }
  payload.network_probe = probe;
  // A credential that did NOT come from the profile's declared source is said out
  // loud on every dispatch, pass or fail. An override nobody was told about is
  // the same class of silence as work leaving Claude without an `extra:` line.
  if (cred.source === "ambient")
    payload.credential_override =
      `this dispatch authenticated with ${extraCredSourceLabel(cred)}, because the vault could not be opened here ` +
      `(no passphrase in hand and none cached). Save one with a deadline: orc extra session ${prof.name} --save --ttl 30`;
  // ATTRIBUTE THE REJECTION. The provider's message describes the secret it saw;
  // only ORC knows where that secret came from.
  if (payload.reason === "authentication_failed")
    payload.credential_hint = `the rejected credential came from ${extraCredSourceLabel(cred)}.`;
  // AFTER `credential_override`, deliberately: the credential SOURCE is evidence
  // on a rejection (v0.53.3 was a 401 caused by ORC sending a key the profile
  // never declared), and evidence that is computed before the fact exists is not
  // evidence.
  payload.ended_at = new Date().toISOString();
  payload.attribution = extraAttribution(
    { profile: prof.name, provider: prof.provider, engine: prof.engine },
    payload,
    probe
  );
  payload.trace_line = extraTraceLine(payload);
  payload.trace_extras = extraTraceExtras(payload);
  // WRITTEN HERE, BY THE HAND THAT HOLDS THE NUMBERS. The trace line above is
  // still the lane’s to relay, and it still should — but whether it does is now
  // irrelevant to whether the spend was recorded. Best effort by construction:
  // it never throws, and a record that could not be written never takes the
  // dispatch down with it.
  const logged = appendExtraSpend(claudeDir, payload);
  payload.spend_logged = !!logged;
  payload.spend_log = extraSpendPath(claudeDir);
  // CLOSED, beside the spend append and by the same hand. A header with no
  // result is what an orphan looks like on disk, so writing this is what makes
  // "this dispatch never reported back" a detectable state rather than a guess.
  extraJournalResult(journal, payload);
  const code = payload.outcome === "done" ? 0 : payload.outcome === "partial" ? 4 : 1;
  if (asJson) emitJson(payload, code);
  extraDispatchRender(payload);
  process.exit(code);
}

// ── The EXTRA trace line, composed ONCE ────────────────────────────────────
//
// The CLI assembles it and the lane copies it VERBATIM — the `orc challenge
// record` precedent (v0.49.1), for the same reason: a lane that composed its own
// wording for the same numbers would produce a second format, and `orc stats`,
// `orc extra stats` and `/orc-retro` all read this line rather than parsing a
// 20-minute trace.
//
// `tok=none` IS A REAL VALUE and the only correct one when the worker reported
// no counts. `tok=0/0/0/0` would tell /orc-budget the run was free — while
// engine api's `cw=0` is a MEASURED zero, which is the opposite fact. The two
// must never be normalised together, so they are not rendered the same.
function extraTraceLine(p) {
  // Rendered through the SAME two helpers the spend log uses. One idea of how a
  // token vector and a duration are written down, or the dedupe that joins the
  // two sources would be comparing two spellings of the same dispatch.
  const dur = extraDurStr(p.duration_ms);
  const tok = extraTokStr(p.usage);
  return (
    `EXTRA ${p.profile}/${p.model_requested || "?"} engine=${p.engine} ` +
    `task=${p.task_id || "?"} band=${p.band || "?"} tok=${tok} outcome=${p.outcome} dur=${dur}`
  );
}

// The three continuation lines, each emitted ONLY when the thing it reports
// actually happened. A `substitution` line on a clean run would be noise the
// retro then has to filter; an ABSENT one on a dirty run is the failure this
// whole field exists to prevent.
function extraTraceExtras(p) {
  const out = [];
  if (p.model_reported && p.model_requested && p.model_reported !== "unknown" && p.model_reported !== p.model_requested)
    out.push(`EXTRA substitution task=${p.task_id || "?"} :: requested=${p.model_requested} reported=${p.model_reported}`);
  if (p.reroute && Array.isArray(p.served_by) && p.served_by.length)
    out.push(`EXTRA reroute task=${p.task_id || "?"} :: ${p.served_by.join(",")}`);
  // v0.54.0 — A RESUME IS VISIBLE OR IT IS NOT MEASURABLE. `/orc-retro` cannot
  // learn which providers ignore a resume preamble, and `orc extra stats` cannot
  // count a resume, unless the run says one happened.
  if (p.resumed_from)
    out.push(
      `EXTRA resume task=${p.task_id || "?"} attempt=${p.attempt || "?"} :: from=${p.resumed_from.reason || "?"} ` +
        `attribution=${p.resumed_from.attribution || "none"} target=${p.via || "?"} files_preexisting=${p.files_preexisting === undefined ? 0 : p.files_preexisting}`
    );
  // The fallback line is the CALLER's to emit AFTER it re-dispatches, because
  // only the caller knows whether it did. What the CLI can honestly supply is
  // the text, pre-composed, so the two wordings cannot diverge.
  //
  // v0.56.1 — under `extra_fallback_agent: ask` NOTHING HAS BEEN CHOSEN YET, so
  // the line says `pending` rather than naming the band's agent. A trace that
  // asserts an agent the user has not picked is a decision /orc-retro would
  // aggregate as one that was made.
  if (!p.ok) {
    const chosen = extraFallbackAgentOf(p);
    if (p.fallback && p.fallback.mode === "ask")
      out.push(`EXTRA fallback task=${p.task_id || "?"} :: ${p.reason} → pending (extra_fallback_agent=ask)`);
    else if (chosen) out.push(`EXTRA fallback task=${p.task_id || "?"} :: ${p.reason} → ${chosen}`);
  }
  return out;
}

// The ORPHAN line, pre-composed. It is the LANE's to emit, at preflight, after
// it has decided to report — the same ownership rule as `EXTRA fallback`, and
// for the same reason: only the lane knows whether it happened.
function extraOrphanTraceLine(row) {
  return (
    `EXTRA orphan task=${row.task_id} :: attempt=${row.attempt} lease-expired ` +
    `files_changed=${row.files_changed} state=${row.state}`
  );
}

function extraDispatchRender(p) {
  const head = `${p.profile}/${p.model_requested || "?"} · ${p.engine}`;
  if (p.outcome === "done") console.log("\n" + ui.mark.ok(`${head} — done in ${Math.round((p.duration_ms || 0) / 1000)}s`));
  else if (p.outcome === "partial") console.log("\n" + ui.mark.warn(`${head} — PARTIAL: ${p.error}`));
  else console.log("\n" + ui.mark.bad(`${head} — ${p.reason}: ${p.error}`));
  if (p.usage)
    console.log(
      ui.color.gray(
        `  tokens  in ${p.usage.input} · cache-w ${p.usage.cache_write} · cache-r ${p.usage.cache_read} · out ${p.usage.output}` +
          "   (never blended; priced from the dated provider table, never by the worker)"
      )
    );
  if (p.model_reported && p.model_requested && p.model_reported !== p.model_requested)
    console.log(
      "  " +
        ui.mark.warn(
          `the endpoint reported model "${p.model_reported}" for a request for "${p.model_requested}".`
        )
    );
  if (p.model_map && p.model_map.small_note) console.log("  " + ui.mark.warn(p.model_map.small_note));
  // Engine C only. The policy line prints even when the policy is `none` — "no
  // policy" and "a policy that did not apply" must not look the same.
  if (p.privacy) console.log(ui.color.gray(`  policy  ${p.privacy.summary}`));
  // Engine B only, and it is a WARNING rather than a grey note: "ORC refused
  // that write" and "ORC asked it not to" are different promises.
  if (p.fence && p.fence.declared_files === false) console.log("  " + ui.mark.warn("no fence — " + p.fence.note));
  if (p.usage === null && p.usage_note) console.log("  " + ui.mark.warn(p.usage_note));
  if (p.preflight_warning) {
    console.log("  " + ui.mark.warn(p.preflight_warning));
    if (p.preflight_remedy) console.log(ui.color.gray(p.preflight_remedy.split("\n").map((l) => "      " + l).join("\n")));
  }
  if (p.reroute) console.log("  " + ui.mark.warn("REROUTE — " + p.reroute_note));
  else if (p.served_by && p.served_by.length) console.log(ui.color.gray(`  served by  ${p.served_by.join(", ")}`));
  else if (p.served_by_note) console.log(ui.color.gray("  " + p.served_by_note));
  if (p.files_written)
    console.log(
      ui.color.gray(
        `  wrote  ${p.files_written.length ? p.files_written.join(", ") : "nothing"}` +
          (p.turns ? `   ·  ${p.turns}/${p.max_turns} turns` : "") +
          (p.bash_calls && p.bash_calls.length ? `  ·  ${p.bash_calls.length} shell command(s), all recorded` : "")
      )
    );
  if (p.credential_override) console.log("  " + ui.mark.warn(p.credential_override));
  if (p.credential_hint) console.log("  " + ui.mark.warn(p.credential_hint));
  if (!p.ok && p.fallback_to)
    console.log(ui.color.gray(`  fallback: ${p.fallback_to.agent} ${p.fallback_to.band}`));
  // v0.56.1 — the TIMELINE, on every engine-cli outcome. A stall budget you can
  // only see when it fires is a budget nobody can set before it does.
  if (p.timeline && p.timeline.stall_budget_ms) {
    const sec = (ms) => (ms === null || ms === undefined ? "—" : `${Math.round(ms / 1000)}s`);
    console.log(
      ui.color.gray(
        `  timeline: first byte ${sec(p.timeline.first_byte_ms)} · last progress ${sec(
          p.timeline.last_progress_ms
        )} · longest quiet gap ${sec(p.timeline.longest_gap_ms)} · stall budget ${sec(p.timeline.stall_budget_ms)}`
      )
    );
  }
  // The MENU, when the user asked to be the one who picks. Printed in full,
  // because a lane that has to go and look the options up is a lane that will
  // pick the first one.
  if (!p.ok && p.fallback && p.fallback.mode === "ask") {
    console.log("");
    console.log(ui.color.yellow("  extra_fallback_agent is `ask` — choose who picks this task up:"));
    for (const o of p.fallback.options)
      console.log(`    ${ui.color.cyan(o.agent)}${o.is_band ? ui.color.gray("  (this task's own band)") : ""}  ${ui.color.gray(o.why)}`);
    if (p.fallback.free_text) console.log(ui.color.gray(`    …or ${p.fallback.free_text}`));
  } else if (!p.ok && p.fallback && p.fallback.mode === "pinned") {
    console.log(ui.color.gray(`  ${p.fallback.note}`));
  }
  // Copy this into the phase packet verbatim. It is printed rather than only
  // returned in --json because the orchestrator reads the human output too, and
  // a line it has to retype is a line it will retype differently.
  if (p.trace_line) {
    console.log(ui.color.gray("  trace   " + p.trace_line));
    for (const x of p.trace_extras || []) console.log(ui.color.gray("          " + x));
  }
  // Say whether the durable record exists, every time. A dispatch that was NOT
  // logged is one `orc extra stats` will never see, and the only moment anyone
  // can act on that is now.
  console.log(
    p.spend_logged
      ? ui.color.gray("  logged  " + p.spend_log)
      : "  " + ui.mark.warn("NOT LOGGED — this dispatch could not be written to " + p.spend_log + "; orc extra stats will not count it.")
  );
  console.log("");
}

// ── The concurrency cap, ENFORCED rather than remembered ───────────────────
//
// `extra_max_concurrent` defaults to 1 because per-provider rate limits are
// undocumented in aggregate and a wave of three that 429s costs more in repairs
// than the parallelism saved. A cap the orchestrator is merely TOLD about is
// the remembered-not-dispatched pattern this repo has already lost to twice, so
// the bridge holds the slots itself.
//
// Slots live in one small file. A crashed dispatch must not wedge the lane
// forever, so a slot is reaped when its process is gone or its lease expired —
// and the lease is derived from the same extra_timeout_s everything else is.
const EXTRA_INFLIGHT = "extra-inflight.json";

function inflightPath(claudeDir) {
  return path.join(claudeDir, "orc", EXTRA_INFLIGHT);
}

const pidAlive = (pid) => {
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return e.code === "EPERM"; // alive, just not ours to signal
  }
};

function readSlots(claudeDir, leaseMs) {
  let slots = [];
  try {
    const j = JSON.parse(fs.readFileSync(inflightPath(claudeDir), "utf8"));
    slots = Array.isArray(j.slots) ? j.slots : [];
  } catch (_) {}
  const now = Date.now();
  return slots.filter((s) => s && s.pid && pidAlive(s.pid) && now - (s.at || 0) < leaseMs);
}

function takeSlot(claudeDir, cap, leaseMs, label) {
  const live = readSlots(claudeDir, leaseMs);
  if (live.length >= cap) return { ok: false, live: live.length, cap };
  const mine = { pid: process.pid, at: Date.now(), task: label || null };
  try {
    fs.mkdirSync(path.dirname(inflightPath(claudeDir)), { recursive: true });
    fs.writeFileSync(inflightPath(claudeDir), JSON.stringify({ slots: live.concat(mine) }, null, 2) + "\n");
  } catch (_) {
    // A slot we cannot record is a slot we cannot enforce — but refusing to
    // dispatch because a bookkeeping file is unwritable would be the cure
    // being worse than the disease. Proceed, unmetered, rather than stop.
    return { ok: true, unmetered: true };
  }
  return { ok: true, unmetered: false };
}

function releaseSlot(claudeDir, leaseMs) {
  try {
    const live = readSlots(claudeDir, leaseMs).filter((s) => s.pid !== process.pid);
    fs.writeFileSync(inflightPath(claudeDir), JSON.stringify({ slots: live }, null, 2) + "\n");
  } catch (_) {}
}

// ── The conformance matrix ─────────────────────────────────────────────────
//
// `tool_fidelity` is NOT a boolean, and that is the whole point of it. The
// difference between "DeepSeek works" and "DeepSeek works if you set two
// environment variables, and here they are" is the difference between a
// feature and a support thread. Each dimension is `true | false | unknown`,
// and `unknown` is an honest value that must never be rendered as either of
// the others.
//
// Anthropic publishes the gateway protocol and its failure taxonomy, so this
// is a CONFORMANCE RUN against a documented contract — not an exploratory
// spike. The mitigations are known in advance; what is measured is which of
// them this particular endpoint actually needs.
const EXTRA_FIDELITY_DIMENSIONS = [
  ["models_endpoint", "serves GET /v1/models — the free half of the connection gate"],
  ["streams", "produces --output-format stream-json, which is what classifies a failure"],
  ["tool_multi_turn", "a tool_use → tool_result round trip survives the shim (the known weak spot)"],
  ["cache_read_seen", "honours cache_control — a shim that ignores it makes every turn look costlier than it is"],
  ["adaptive_ok", "tolerates Claude Code's adaptive `thinking` field without a 400"],
  ["betas_ok", "tolerates the pre-release beta body fields without a 400"],
  ["structured_output_ok", "returns a schema-validated structured_output (prose parsing stays the floor either way)"],
];

const CONFORM_TASK = [
  "Reply with exactly the word: CONFORM",
  "Do not create, edit or delete any file. Do not run any command.",
].join("\n");

function extraConform(claudeDir, name) {
  const asJson = wantsJson();
  const deep = flag("--deep") === true;
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  if (!prof) {
    const known = ledger ? ledger.profiles.map((x) => x.name) : [];
    if (asJson) emitJson({ ok: false, reason: "unknown-profile", profile: name || null, known }, 2);
    console.error(`❌ unknown profile "${name || ""}".`);
    process.exit(2);
  }
  if (prof.engine !== "claude-shim") {
    const msg = `conformance measures the /anthropic shim surface, and "${name}" is on engine ${prof.engine}. Only claude-shim has a shim to measure.`;
    if (asJson) emitJson({ ok: false, reason: "not-applicable", engine: prof.engine, error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }
  const cfg = resolvedConfig(claudeDir);
  const cred = extraCredentialValue(claudeDir, prof, { ambientKey: process.env.ORC_EXTRA_KEY || null });
  if (!cred.ok) {
    if (asJson) emitJson(Object.assign({ ok: false, profile: name }, cred), 1);
    console.error("❌ " + cred.error);
    process.exit(1);
  }

  // A model to speak to. `models_seen` first, else whatever the route rows
  // already point at — and if neither exists, say so instead of inventing one.
  const routed = ledger.routes.filter((r) => r.profile === name);
  const model = (prof.models_seen || [])[0] || (routed[0] && routed[0].model) || null;
  if (!model) {
    const msg = `no model id to test with. Run \`orc extra ping ${name}\` (or route a band) so ORC has one from the provider rather than a guess.`;
    if (asJson) emitJson({ ok: false, reason: "no-model", error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  }

  const fid = {};
  for (const [k] of EXTRA_FIDELITY_DIMENSIONS) fid[k] = "unknown";
  fid.models_endpoint = prof.verify_method === "models";

  const runs = [];
  const oneRun = (label, over) => {
    const workDir = fs.mkdtempSync(path.join(os.tmpdir(), "orc-conform-"));
    try {
      const out = runClaudeShim({
        prof,
        route: Object.assign({ model, small_model: routed[0] && routed[0].small_model, max_turns: 2 }, over || {}),
        key: cred.value,
        cfg,
        slice: {
          prompt: CONFORM_TASK,
          standing_rules: "You are being probed for protocol conformance. Answer in one word.",
          // Read only: a conformance run must never be able to change the tree.
          allowed_tools: ["Read", "Glob", "Grep"],
          permission_mode: "default",
        },
        cwd: repoRootOf(claudeDir),
        workDir,
        envOverride: over && over.envOverride,
      });
      runs.push(Object.assign({ label }, summariseRun(out)));
      return out;
    } finally {
      try {
        fs.rmSync(workDir, { recursive: true, force: true });
      } catch (_) {}
    }
  };

  // Run 1 — the mitigated run. This is the configuration a real dispatch uses,
  // so its result is the one that decides whether this profile is usable.
  const base = oneRun("mitigated");
  fid.streams = base.format === "stream-json";
  if (base.ok || base.outcome === "partial") {
    fid.tool_multi_turn = base.tool_uses > 0 ? base.tool_results > 0 : "unknown";
    fid.cache_read_seen = base.usage ? base.usage.cache_read > 0 : "unknown";
  }

  // Runs 2 and 3 — only with --deep, because each one costs another call and
  // neither changes whether the profile WORKS. They change what ORC has to
  // send: an endpoint that tolerates the fields does not need the flags, and
  // knowing that is worth a fraction of a cent when you are debugging a 400.
  if (deep && (base.ok || base.outcome === "partial")) {
    const adaptive = oneRun("adaptive", { envOverride: { CLAUDE_CODE_DISABLE_ADAPTIVE_THINKING: "0" } });
    fid.adaptive_ok = !!adaptive.ok;
    const betas = oneRun("betas", { envOverride: { CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS: "0" } });
    fid.betas_ok = !!betas.ok;
    // structured_output travels in the `output_config` body field behind a beta
    // header — exactly what DISABLE_EXPERIMENTAL_BETAS suppresses and what a
    // weak shim 400s on. So it can only be true where betas are, and prose
    // parsing stays the floor regardless.
    fid.structured_output_ok = betas.ok ? "unknown" : false;
  }

  prof.tool_fidelity = { measured_at: new Date().toISOString(), model, deep, dimensions: fid };
  extraHistory(ledger, "conform", { profile: name, deep, ok: !!base.ok });
  writeExtra(claudeDir, ledger);

  // Every FALSE maps to something the caller can act on — a fallback reason, a
  // flag to keep, or a cost note. A matrix that only said "false" would be a
  // measurement nobody could use.
  const consequences = [];
  if (fid.streams === false)
    consequences.push({ dimension: "streams", effect: "failures cannot be classified from api_retry events, so ORC's retry budget is the only one left", fallback_reason: "malformed-return" });
  if (fid.tool_multi_turn === false)
    consequences.push({ dimension: "tool_multi_turn", effect: "this shim mangles tool blocks — engine `api` is the way to use this provider", fallback_reason: "invalid_request" });
  if (fid.cache_read_seen === false)
    consequences.push({ dimension: "cache_read_seen", effect: "cache reads are not honoured, so every turn costs full input price. This is a MEASUREMENT, not missing data", fallback_reason: null });
  if (fid.adaptive_ok === false)
    consequences.push({ dimension: "adaptive_ok", effect: "keep CLAUDE_CODE_DISABLE_ADAPTIVE_THINKING=1 — without it this endpoint 400s", fallback_reason: "invalid_request" });
  if (fid.betas_ok === false)
    consequences.push({ dimension: "betas_ok", effect: "keep CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS=1 — without it this endpoint 400s", fallback_reason: "invalid_request" });

  const payload = {
    ok: !!base.ok,
    profile: name,
    engine: "claude-shim",
    model,
    deep,
    usable: !!base.ok || base.outcome === "partial",
    dimensions: fid,
    legend: Object.fromEntries(EXTRA_FIDELITY_DIMENSIONS),
    consequences,
    runs,
    // The asymmetry worth stating wherever this is read: engine claude-shim
    // does not COMPOSE the request body, so it cannot carry a provider-routing
    // or data-retention policy. Engine `api` can. That is the first honest
    // reason to choose the engine with more moving parts.
    privacy_note:
      "engine claude-shim cannot enforce a data-retention or provider-routing policy — it does not compose the request body. Engine `api` does. Some traffic (the fast-mode availability check, the WebFetch domain safety check) still reaches Anthropic regardless of the base URL.",
    failure: base.ok ? null : { reason: base.reason, error: base.error, retry: base.retry },
  };
  if (asJson) emitJson(payload, base.ok ? 0 : 1);
  extraConformRender(payload);
  process.exit(base.ok ? 0 : 1);
}

const summariseRun = (o) => ({
  ok: !!o.ok,
  outcome: o.outcome,
  format: o.format || null,
  reason: o.reason || null,
  duration_ms: o.duration_ms || null,
  usage: o.usage || null,
});

function extraConformRender(p) {
  console.log(ui.header(`ORC · extra conform — ${p.profile} (${p.model})`));
  console.log("");
  const mark = (v) => (v === true ? ui.color.green("yes") : v === false ? ui.color.red("NO") : ui.color.gray("unknown"));
  console.log(ui.kv(EXTRA_FIDELITY_DIMENSIONS.map(([k, why]) => [k, mark(p.dimensions[k]), why])));
  if (!p.deep)
    console.log(
      "\n  " +
        ui.color.gray(
          "adaptive_ok / betas_ok / structured_output_ok read `unknown` because measuring them\n" +
            "  costs two more calls and changes what ORC SENDS, not whether this works. `--deep` measures them."
        )
    );
  if (p.consequences.length) {
    console.log("\n  What each NO costs you:");
    for (const c of p.consequences) console.log(`    ${ui.glyph.bullet} ${c.dimension} — ${c.effect}`);
  }
  if (!p.ok) console.log("\n  " + ui.mark.bad(`${p.failure.reason}: ${p.failure.error}`));
  else console.log("\n  " + ui.mark.ok("usable."));
  console.log("\n  " + ui.color.gray(p.privacy_note) + "\n");
}

// ── orc extra privacy — the ONE enforceable privacy control ────────────────
//
// F6. A policy nobody can set is decorative, so this is the setter, and it is
// deliberately narrow: five fields, all of them an aggregator's own documented
// body fields, and none of them invented by ORC.
//
// It REFUSES BY NAME on engine claude-shim rather than storing a policy that
// would never be sent. That asymmetry is the first honest reason to choose the
// engine with more moving parts, and hiding it would make engine A look safer
// than it is.
//
// It also refuses on a provider whose catalog row does not advertise
// `provider_routing`: an unknown body field is a 400 mid-wave on any endpoint
// that validates strictly, and a privacy control that breaks the run is not a
// privacy control.
function extraPrivacy(claudeDir, name) {
  const asJson = wantsJson();
  const ledger = readExtra(claudeDir);
  const prof = extraProfile(ledger, name);
  const fail = (code, reason, msg, extra) => {
    if (asJson) emitJson(Object.assign({ ok: false, reason, error: msg }, extra || {}), code);
    console.error("❌ " + msg);
    process.exit(code);
  };
  if (!prof) {
    const known = ledger ? ledger.profiles.map((x) => x.name) : [];
    fail(2, "unknown-profile", `unknown profile "${name || ""}"${known.length ? ` — known: ${known.join(", ")}` : " — none configured yet"}`, { known });
  }
  if (prof.engine !== "api")
    fail(
      1,
      "not-applicable",
      `a routing policy is a REQUEST BODY field, and "${name}" is on engine ${prof.engine}, which does not compose one. ` +
        `ANTHROPIC_CUSTOM_HEADERS adds headers, not body fields, so engine claude-shim cannot enforce this and ORC will not store a policy it would silently drop.\n` +
        "   Engine `api` is the way to enforce it.",
      { engine: prof.engine }
    );
  const row = catalogRow(readCatalog(), prof.provider);
  if (!row || row.provider_routing !== true)
    fail(
      1,
      "provider-unsupported",
      `provider "${prof.provider}" does not advertise a provider-routing block. Sending one is an unknown body field, which is a 400 in the middle of a wave on any endpoint that validates strictly — so this is refused rather than stored.`,
      { provider: prof.provider }
    );

  const onOff = (f) => {
    const v = flag(f);
    if (v === undefined) return undefined;
    if (v === "on" || v === true) return true;
    if (v === "off") return false;
    fail(1, "bad-value", `${f} takes on | off (got "${v}").`);
  };
  const cleared = args.includes("--clear");
  const pol = cleared ? {} : Object.assign({}, prof.privacy || {});
  const zdr = onOff("--zdr");
  if (zdr !== undefined) pol.zdr = zdr;
  const rp = onOff("--require-parameters");
  if (rp !== undefined) pol.require_parameters = rp;
  const af = onOff("--allow-fallbacks");
  if (af !== undefined) pol.allow_fallbacks = af;
  const dc = flag("--data-collection");
  if (dc !== undefined) {
    if (dc !== "deny" && dc !== "allow") fail(1, "bad-value", `--data-collection takes deny | allow (got "${dc}").`);
    pol.data_collection = dc;
  }
  const only = flag("--only");
  if (only !== undefined) {
    const list = String(only)
      .split(",")
      .map((x) => x.trim())
      .filter(Boolean);
    if (!list.length) fail(1, "bad-value", "--only takes a comma-separated list of provider slugs.");
    pol.only = list;
  }
  const touched = cleared || zdr !== undefined || rp !== undefined || af !== undefined || dc !== undefined || only !== undefined;

  if (touched) {
    prof.privacy = Object.keys(pol).length ? pol : null;
    extraHistory(ledger, "privacy", { profile: prof.name, privacy: prof.privacy });
    writeExtra(claudeDir, ledger);
  }
  const eff = apiProviderPolicy(prof);
  if (asJson)
    emitJson(
      {
        ok: true,
        profile: prof.name,
        provider: prof.provider,
        engine: prof.engine,
        changed: touched,
        privacy: prof.privacy || null,
        block: eff.block,
        summary: eff.summary,
        enforced_by: "engine api composes the request body, so this is sent on every dispatch and is the only privacy control ORC can enforce rather than hope for",
        still_leaves_the_machine:
          "the prompt, the slice and every file the worker reads or writes. A routing policy decides WHO serves the request, not WHETHER it is sent.",
      },
      0
    );
  console.log(`\n${ui.color.cyan(prof.name)} — routing policy${touched ? " updated" : ""}`);
  console.log(ui.kv([["policy", eff.summary], ["sent as", eff.block ? "body.provider on every dispatch" : "nothing"]]));
  console.log(
    "\n" +
      ui.box([
        "This decides WHO serves the request. It does not decide whether it is",
        "sent: the prompt, the slice and every file the worker reads still leave",
        "this machine.",
      ]) +
      "\n"
  );
}

// ══ THE FOREIGN SPEND LOG — written by the CLI, never remembered ═══════════
//
// `extraTraceLine` composes the `EXTRA …` line and the lane is supposed to copy
// it VERBATIM into the phase packet, which the trace writer then writes. That is
// a RELAY, and a relay through a model is the remembered-not-dispatched pattern
// this repo has already lost to twice (the v0.32.0 narration lesson). It lost to
// it a third time here. Two graded runs, both real foreign dispatches:
//
//   · one reshaped the line — `EXTRA Codex/gpt-5.4-mini :: engine=cli …`, with
//     the trace's own `verb … :: tail` separator inserted, which the parser did
//     not accept. A logged dispatch that reads as zero.
//   · one dropped the line entirely and folded the token vector into a free-form
//     `VERIFY …` sentence. A dispatch that cost real money and left NO parsable
//     record at all.
//
// Both surfaced identically: `orc extra stats` said "0 dispatches from 2
// traces", `orc extra rates` had nothing to price, and the Spending tab read
// `0 tasks sent`. A cost report that reads zero when money was spent is worse
// than no report, because a zero gets believed.
//
// So the bridge writes it down ITSELF, at the moment it holds the numbers, on
// the same principle as `RESUME.md` in v0.49.5: the fact is recorded by the hand
// that computed it. One JSON object per line, appended, never rewritten.
//
// The trace line is NOT retired — it is the human-readable narrative, it is what
// `/orc-retro` reads, and it is what a run's own file has to show. It is now the
// SECOND source rather than the only one, and the two are DEDUPED on the same
// eight fields the line itself carries, so a lane that relays correctly is
// counted exactly once.
const EXTRA_SPEND_LOG = "extra-spend.jsonl";

function extraSpendPath(claudeDir) {
  return path.join(claudeDir, "orc", EXTRA_SPEND_LOG);
}

// `tok=none` IS A REAL VALUE — see extraTraceLine. Both renderers live here so
// the spend log and the trace line can never disagree about the same numbers.
const extraTokStr = (u) => (u ? `${u.input}/${u.cache_write}/${u.cache_read}/${u.output}` : "none");
const extraDurStr = (ms) => {
  const secs = Math.max(0, Math.round((ms || 0) / 1000));
  return `${Math.floor(secs / 60)}m${String(secs % 60).padStart(2, "0")}s`;
};

// The dedupe identity, and it is deliberately the EXACT field set the trace line
// carries: anything the line cannot express cannot be used to tell two rows
// apart, or a correctly-relayed dispatch would be counted twice.
const extraRowKey = (r) =>
  [r.profile, r.model, r.engine, r.task, r.band, extraTokStr(r.usage), r.outcome, r.dur].join("|");

// Which run this dispatch belonged to. Read from the trace pointer, best effort:
// an unattributed row is still a real cost, so a missing pointer must never
// discard the record.
function extraCurrentRun(claudeDir) {
  try {
    const dir = resolveLogDir(claudeDir);
    const cur = fs.readFileSync(path.join(dir, ".current"), "utf8").trim();
    if (!cur) return null;
    const m = TRACE_NAME.exec(cur);
    return { trace: cur, slug: m ? m[2] : null, lane: m ? m[1] : null };
  } catch (_) {
    return null;
  }
}

// Best effort, ALWAYS. A spend record that could not be written must never take
// the dispatch down with it — the work was done and the caller needs its answer.
function appendExtraSpend(claudeDir, p) {
  try {
    const run = extraCurrentRun(claudeDir);
    const now = new Date();
    const rec = {
      v: 1,
      ts: now.toISOString(),
      // LOCAL date, because `--since` filters trace FILENAMES, whose DDMMYY
      // stamp is local. Two date bases in one report would silently drop rows
      // near midnight.
      date: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`,
      run: run ? run.slug : null,
      lane: run ? run.lane : null,
      trace: run ? run.trace : null,
      profile: p.profile,
      provider: p.provider || null,
      model: p.model_requested || "?",
      model_reported: p.model_reported || null,
      engine: p.engine,
      task: p.task_id || "?",
      band: p.band || "?",
      score: typeof p.score === "number" ? p.score : null,
      usage: p.usage || null,
      outcome: p.outcome,
      duration_ms: p.duration_ms || 0,
      dur: extraDurStr(p.duration_ms),
      reason: p.reason || null,
      served_by: Array.isArray(p.served_by) && p.served_by.length ? p.served_by : null,
      reroute: !!p.reroute,
      // The line the lane is supposed to relay, stored beside the numbers it
      // came from. A trace that never received it can still be reconciled.
      trace_line: p.trace_line || null,
      // The FALLBACK TARGET, not the fallback itself: only the caller knows
      // whether it re-dispatched, so this records who it would have been.
      fallback_to: !p.ok && p.fallback_to && p.fallback_to.agent ? p.fallback_to.agent : null,
      // v0.54.0 — A RECOVERED VECTOR IS A FLOOR AND SAYS SO. `orc extra
      // reconcile` writes the journal's running vector for a dispatch whose
      // parent was killed before it reached this function. MEASURED IS NOT
      // UNKNOWN and UNKNOWN IS NOT ZERO: `complete: false` is what stops a
      // renderer summing it into a total that reads as measured.
      recovered: !!p.recovered,
      complete: !p.recovered,
      attribution: (p.attribution && p.attribution.verdict) || null,
    };
    fs.mkdirSync(path.dirname(extraSpendPath(claudeDir)), { recursive: true });
    fs.appendFileSync(extraSpendPath(claudeDir), JSON.stringify(rec) + "\n");
    return rec;
  } catch (_) {
    return null;
  }
}

// Read it back. An unparseable line is SKIPPED and COUNTED, never fatal: this is
// an append-only log written by concurrent dispatches, so one torn line must not
// cost the report every row after it.
function readExtraSpend(claudeDir, cutoff) {
  const file = extraSpendPath(claudeDir);
  let text = "";
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (_) {
    return { file, rows: [], entries: 0, unreadable: 0 };
  }
  const rows = [];
  let unreadable = 0;
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    let r;
    try {
      r = JSON.parse(line);
    } catch (_) {
      unreadable++;
      continue;
    }
    if (!r || !r.profile || !r.outcome) {
      unreadable++;
      continue;
    }
    const date = r.date || String(r.ts || "").slice(0, 10);
    if (cutoff && date < cutoff) continue;
    rows.push({
      source: "spend-log",
      run: r.trace || r.run || null,
      date,
      profile: r.profile,
      provider: r.provider || null,
      model: r.model || "?",
      engine: r.engine || "?",
      task: r.task || "?",
      band: r.band || "?",
      usage: r.usage || null,
      outcome: r.outcome,
      dur: r.dur || extraDurStr(r.duration_ms),
      model_reported: r.model_reported || null,
      served_by: r.served_by || null,
      reroute: !!r.reroute,
      fallback_to: r.fallback_to || null,
    });
  }
  return { file, rows, entries: rows.length, unreadable };
}

// ══ orc extra stats / rates — THE FLYWHEEL ══════════════════════════════════
//
// The question this exists to answer, and it is the only one that matters about
// the whole feature: **is the cheap model actually cheaper once you count the
// repairs?** A run that costs a tenth as much and then needs two fix cycles, a
// reviewer P0 and a re-dispatch to Claude was not cheaper. Nothing else in ORC
// can see that, because nothing else joins the foreign dispatch to what
// happened next.
//
// It reads the `EXTRA` lines out of the trace files. Unlike `orc stats`, which
// reads only the tail of each file, this SCANS THEM WHOLE — a foreign dispatch
// is per task, so there is no one summary line to read, and inventing one would
// mean the orchestrator remembering a running total across a wave, which is the
// remembered-not-dispatched pattern this repo has already lost to twice. A full
// scan of an on-demand report is the cheaper mistake.

// `EXTRA ds/deepseek-v4 engine=api task=T3 band=[0,30) tok=1/2/3/4 outcome=done dur=0m41s`
//
// The ` :: ` is OPTIONAL, and accepting it is a real fix rather than a
// courtesy. Every other verb in a trace is written `VERB … :: tail`, so a trace
// writer handed this line reaches for that separator by reflex — one graded run
// wrote `EXTRA Codex/gpt-5.4-mini :: engine=cli …` and the whole run reported as
// zero foreign dispatches. A line that is faithful about the numbers and off by
// two characters in its punctuation is a line that must still parse.
const EXTRA_LINE_RE = /\bEXTRA\s+(\S+?)\/(\S+)\s+(?:::\s+)?engine=(\S+)\s+task=(\S+)\s+band=(\S+)\s+tok=(\S+)\s+outcome=(\S+)\s+dur=(\S+)/;
const EXTRA_SUB_RE = /\bEXTRA\s+substitution\s+task=(\S+)\s*::\s*requested=(\S+)\s+reported=(\S+)/;
const EXTRA_REROUTE_RE = /\bEXTRA\s+reroute\s+task=(\S+)\s*::\s*(\S+)/;
const EXTRA_FALLBACK_RE = /\bEXTRA\s+fallback\s+task=(\S+)\s*::\s*(\S+)\s+→\s+(\S+)/;

function parseExtraTok(tok) {
  // `none` is a REAL value — the worker reported no counts. It must not become
  // a zero vector, or the report says a run with unknown cost was free.
  if (tok === "none") return null;
  const p = String(tok).split("/").map(Number);
  if (p.length !== 4 || p.some((n) => !Number.isFinite(n))) return null;
  return { input: p[0], cache_write: p[1], cache_read: p[2], output: p[3] };
}

// A rate for a NON-Claude model. Never a family fallback: `rateFor`'s
// substring guess is right for `claude-opus-*` and would be nonsense here.
function foreignRate(table, provider, model) {
  const block = table && table.providers && table.providers[provider];
  const m = block && block.models && block.models[model];
  if (m && ["input", "cache_write", "cache_read", "output"].every((k) => typeof m[k] === "number")) return m;
  return null;
}

// A dispatch return the LANE saved to disk. Not a third opinion — it is the
// bridge's OWN `--json` payload, written verbatim by whoever ran it, so reading
// it back is reading the CLI's own arithmetic rather than a narrative about it.
// This is what makes the two dispatches that predate the spend log recoverable
// at all: both had a correct `trace_line` sitting in the run folder while the
// trace, the stats report and the Spending tab all read zero.
//
// The shape check is deliberately strict: `dispatched: true` AND a `trace_line`
// this parser accepts. Anything else in a run folder is ignored, so this can
// never turn some other JSON into a cost figure.
function readExtraReturns(claudeDir) {
  const rows = [];
  let files = 0;
  let root;
  try {
    root = resolveRunDir(claudeDir);
  } catch (_) {
    return { rows, files };
  }
  let slugs = [];
  try {
    slugs = fs.readdirSync(root, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name);
  } catch (_) {
    return { rows, files };
  }
  for (const slug of slugs) {
    let names = [];
    try {
      names = fs.readdirSync(path.join(root, slug)).filter((f) => f.endsWith(".json"));
    } catch (_) {
      continue;
    }
    for (const name of names) {
      const full = path.join(root, slug, name);
      let j;
      try {
        if (fs.statSync(full).size > 2_000_000) continue;
        const text = fs.readFileSync(full, "utf8");
        // Cheap pre-filter, the same shape as the traces' `indexOf("EXTRA ")`.
        // A run folder holds slices, checkpoints and worktree snapshots, and
        // parsing every one of them to find the two that are dispatch returns
        // is the cost this avoids.
        if (text.indexOf('"trace_line"') === -1) continue;
        j = JSON.parse(text);
      } catch (_) {
        continue;
      }
      if (!j || j.dispatched !== true || typeof j.trace_line !== "string") continue;
      if (!EXTRA_LINE_RE.test(j.trace_line)) continue;
      files++;
      rows.push({
        source: "run-return",
        // The RUN FOLDER names it, which is a fact on disk. There is no date in
        // the payload and none is invented from an mtime — see below for what
        // that costs a `--since` query.
        run: slug + "/" + name,
        date: null,
        profile: j.profile,
        provider: j.provider || null,
        model: j.model_requested || "?",
        engine: j.engine || "?",
        task: j.task_id || "?",
        band: j.band || "?",
        usage: j.usage || null,
        outcome: j.outcome,
        dur: extraDurStr(j.duration_ms),
        model_reported: j.model_reported || null,
        served_by: Array.isArray(j.served_by) && j.served_by.length ? j.served_by : null,
        reroute: !!j.reroute,
        fallback_to: !j.ok && j.fallback_to && j.fallback_to.agent ? j.fallback_to.agent : null,
      });
    }
  }
  return { rows, files };
}

function extraStatsScan(claudeDir) {
  const dir = resolveLogDir(claudeDir);
  // Same convention as `orc stats`: --since filters on the FILENAME date,
  // before any file is opened.
  const sinceArg = flag("--since");
  const cutoff = typeof sinceArg === "string" && sinceArg ? sinceArg : null;
  let names = [];
  try {
    names = fs.readdirSync(dir).filter((f) => f.endsWith(".txt"));
  } catch (_) {}

  // SOURCE 1 — the spend log, which is the one the CLI wrote itself. It is read
  // FIRST so that a dispatch is counted whether or not the lane relayed its
  // trace line, and so that its own richer fields (provider, reported model,
  // serving providers) win over what a one-line regex can recover.
  const spend = readExtraSpend(claudeDir, cutoff);
  const rows = spend.rows.slice();
  const subs = [];
  const reroutes = [];
  const fallbacks = [];
  const seen = new Set(rows.map(extraRowKey));
  for (const r of spend.rows) {
    if (r.model_reported && r.model_reported !== "unknown" && r.model_reported !== r.model)
      subs.push({ run: r.run, task: r.task, requested: r.model, reported: r.model_reported, source: "spend-log" });
    if (r.reroute && r.served_by && r.served_by.length)
      reroutes.push({ run: r.run, task: r.task, providers: r.served_by, source: "spend-log" });
    if (r.fallback_to)
      fallbacks.push({ run: r.run, task: r.task, reason: r.outcome, agent: r.fallback_to, source: "spend-log" });
  }

  // SOURCE 2 — the traces. Still read, for three reasons: they cover every
  // dispatch made before this log existed, they are the only place an `EXTRA
  // fallback` line lands (the CALLER emits that, after it re-dispatches — the
  // bridge cannot know it happened), and a run whose lane relayed correctly
  // should reconcile rather than silently disagree.
  let filesRead = 0;
  let recovered = 0;
  for (const name of names) {
    const m = TRACE_NAME.exec(name);
    const g = m ? null : TRACE_GENERIC.exec(name);
    if (!m && !g) continue;
    const stamp = traceDateIso(m ? m[3] : g[1]);
    if (cutoff && stamp < cutoff) continue;
    let text = "";
    try {
      text = fs.readFileSync(path.join(dir, name), "utf8");
    } catch (_) {
      continue;
    }
    // Cheap pre-filter: most traces have no foreign dispatch at all, and
    // splitting a 20-minute trace into lines to find that out is the cost this
    // avoids on every file but the few that matter.
    if (text.indexOf("EXTRA ") === -1) continue;
    filesRead++;
    for (const line of text.split(/\r?\n/)) {
      const d = EXTRA_LINE_RE.exec(line);
      if (d) {
        const row = {
          source: "trace",
          run: name,
          date: stamp,
          profile: d[1],
          model: d[2],
          engine: d[3],
          task: d[4],
          band: d[5],
          usage: parseExtraTok(d[6]),
          outcome: d[7],
          dur: d[8],
        };
        // DEDUPE on the eight fields the line itself carries. A lane that
        // relayed faithfully must be counted ONCE — double-counting a correct
        // relay would punish exactly the behaviour the contract asks for.
        const key = extraRowKey(row);
        if (seen.has(key)) continue;
        seen.add(key);
        rows.push(row);
        recovered++;
        continue;
      }
      const su = EXTRA_SUB_RE.exec(line);
      if (su) {
        subs.push({ run: name, task: su[1], requested: su[2], reported: su[3], source: "trace" });
        continue;
      }
      const rr = EXTRA_REROUTE_RE.exec(line);
      if (rr) {
        reroutes.push({ run: name, task: rr[1], providers: rr[2].split(","), source: "trace" });
        continue;
      }
      const fb = EXTRA_FALLBACK_RE.exec(line);
      if (fb) fallbacks.push({ run: name, task: fb[1], reason: fb[2], agent: fb[3], source: "trace" });
    }
  }
  // SOURCE 3 — the dispatch returns the lane saved into its own run folder.
  // Pure backfill: it only ever ADDS a dispatch the other two sources did not
  // already have, and it is how a run made before the spend log existed becomes
  // visible instead of staying a permanent zero.
  const ret = readExtraReturns(claudeDir);
  let backfilled = 0;
  let undatedSkipped = 0;
  for (const r of ret.rows) {
    const key = extraRowKey(r);
    if (seen.has(key)) continue;
    // A saved return carries no date, and NONE IS INVENTED — an mtime is when a
    // file was touched, not when a model was billed (the /orc-pact UNCHECKABLE
    // rule). Under `--since` these rows cannot be placed, so they are excluded
    // and COUNTED rather than quietly included or quietly dropped.
    if (cutoff) {
      undatedSkipped++;
      continue;
    }
    seen.add(key);
    rows.push(r);
    backfilled++;
    if (r.model_reported && r.model_reported !== "unknown" && r.model_reported !== r.model)
      subs.push({ run: r.run, task: r.task, requested: r.model, reported: r.model_reported, source: "run-return" });
    if (r.reroute && r.served_by && r.served_by.length)
      reroutes.push({ run: r.run, task: r.task, providers: r.served_by, source: "run-return" });
  }

  rows.sort((a, b) => String(a.date || "").localeCompare(String(b.date || "")));
  return {
    dir,
    rows,
    subs,
    reroutes,
    fallbacks,
    files_scanned: filesRead,
    since: cutoff,
    // WHERE EACH NUMBER CAME FROM, always printed. "the bridge logged it" and
    // "only a trace mentions it" are different facts about how much the report
    // can be trusted, and a reader who cannot tell them apart cannot tell a
    // relay that broke from a lane that never ran.
    spend_log: spend.file,
    sources: {
      spend_log: spend.rows.length,
      traces_only: recovered,
      run_returns: backfilled,
      run_returns_undated_skipped: undatedSkipped,
      unreadable_spend_lines: spend.unreadable,
    },
  };
}

function extraStats(claudeDir) {
  const asJson = wantsJson();
  const scan = extraStatsScan(claudeDir);
  const table = readPricing(claudeDir);
  const ledger = readExtra(claudeDir);
  const providerOf = (profile) => {
    const p = ledger && extraProfile(ledger, profile);
    return p ? p.provider : null;
  };

  // Grouped BY PROFILE AND BAND, which is the pair a routing decision is made
  // in — a per-provider total cannot tell you the [0,30) row was fine and the
  // [30,70) row was a false economy.
  const groups = new Map();
  let priced = 0;
  let unpriced = 0;
  const missingRates = new Map();
  for (const r of scan.rows) {
    const key = `${r.profile}|${r.band}`;
    if (!groups.has(key))
      groups.set(key, {
        profile: r.profile,
        provider: providerOf(r.profile),
        band: r.band,
        engines: {},
        models: {},
        dispatches: 0,
        outcomes: { done: 0, partial: 0, failed: 0, fallback: 0 },
        usage: { input: 0, cache_write: 0, cache_read: 0, output: 0 },
        // The count that keeps the vector honest: a total assembled from six of
        // ten dispatches is not this band's cost, and saying so is the only way
        // a reader can tell.
        usage_reported: 0,
        usage_missing: 0,
        usd: null,
      });
    const g = groups.get(key);
    g.dispatches++;
    g.engines[r.engine] = (g.engines[r.engine] || 0) + 1;
    g.models[r.model] = (g.models[r.model] || 0) + 1;
    if (g.outcomes[r.outcome] === undefined) g.outcomes[r.outcome] = 0;
    g.outcomes[r.outcome]++;
    if (r.usage) {
      g.usage = extraVectorAdd(g.usage, r.usage);
      g.usage_reported++;
      const rate = foreignRate(table, g.provider, r.model);
      if (rate) {
        const usd =
          (r.usage.input * rate.input +
            r.usage.cache_write * rate.cache_write +
            r.usage.cache_read * rate.cache_read +
            r.usage.output * rate.output) /
          1e6;
        g.usd = (g.usd || 0) + usd;
        priced++;
      } else {
        unpriced++;
        const k = `${g.provider || "?"}/${r.model}`;
        missingRates.set(k, (missingRates.get(k) || 0) + 1);
      }
    } else g.usage_missing++;
  }

  const rows = [...groups.values()].sort((a, b) => b.dispatches - a.dispatches);
  const total = scan.rows.length;
  const payload = {
    log_dir: scan.dir,
    since: scan.since,
    files_scanned: scan.files_scanned,
    dispatches: total,
    // `--json is not a summary` (v0.49.1): the human branch below prints where
    // every row came from, so the JSON carries it too.
    spend_log: scan.spend_log,
    sources: scan.sources,
    bands: rows,
    // The three things that are ONLY visible here, and each is a different
    // question. A substitution is "you did not get the model you asked for". A
    // reroute is "you got the model and a different company served it". A
    // fallback is "it did not work and Claude finished the job".
    substitutions: scan.subs,
    reroutes: scan.reroutes,
    fallbacks: scan.fallbacks,
    // v0.54.0 — RELIABILITY, beside cost. A provider that drops one dispatch in
    // three is a fact that belongs where the user chooses a profile, not in
    // folklore. Below the sample floor there is NO rate: a percentage computed
    // from three dispatches is noise with a percent sign on it.
    reliability: extraReliability(claudeDir, scan),
    // v1.0.0 W5 — HOW OFTEN THIS PROFILE GETS DROPPED MID-RUN. Reliability
    // counts dispatches; this counts RUNS, and they are different questions: a
    // profile can fail one dispatch in ten and still stall twice in a row in
    // every run that uses it.
    demotions: extraDemotionHistory(claudeDir, resolvedConfig(claudeDir)),
    price_table: table ? { as_of: table.as_of, age_days: table._age_days, stale: table._stale, path: table._path } : null,
    priced_dispatches: priced,
    unpriced_dispatches: unpriced,
    // NOT a warning ABOUT the user — every models map ships empty on purpose,
    // because a wrong price gets believed. This is the pointer to the fix.
    missing_rates: [...missingRates.entries()].map(([pair, n]) => ({ pair, dispatches: n })),
    hint: total
      ? "`orc extra rates` prints the JSON to paste for every provider/model pair with no rate."
      : "no foreign dispatch has been recorded yet. `orc extra route set <band> <profile>/<model>` and run a lane.",
  };
  if (asJson) emitJson(payload, total ? 0 : 1);

  console.log(ui.header(`ORC · extra stats — ${scan.dir}`));
  if (!total) {
    console.log("\n  " + payload.hint + "\n");
    process.exit(1);
  }
  console.log(
    ui.color.gray(
      `\n  ${plural(total, "foreign dispatch", "foreign dispatches")}` +
        (scan.since ? ` since ${scan.since}` : "") +
        `\n  ${scan.sources.spend_log} from the spend log · ${scan.sources.traces_only} from ${plural(
          scan.files_scanned,
          "trace"
        )} · ${scan.sources.run_returns} backfilled from saved dispatch returns` +
        "\n"
    )
  );
  // A torn line is named rather than absorbed. This log is appended to by
  // concurrent dispatches, so one is possible — and a report quietly short by
  // three rows is the failure this whole file exists to stop.
  if (scan.sources.run_returns_undated_skipped)
    console.log(
      "  " +
        ui.mark.warn(
          `${scan.sources.run_returns_undated_skipped} saved dispatch return(s) carry no date and are excluded by --since. Drop --since to include them.`
        ) +
        "\n"
    );
  if (payload.demotions.profiles.some((g) => g.runs_demoted))
    for (const g of payload.demotions.profiles) {
      if (!g.runs_demoted) continue;
      console.log(
        "  " +
          ui.mark.warn(
            `${g.profile} was DEMOTED in ${g.runs_demoted} of ${g.runs_seen} run(s) that used it` +
              (g.demote_rate === null
                ? ` (no rate below ${payload.demotions.rate_floor} runs)`
                : ` — ${Math.round(g.demote_rate * 100)}%`)
          ) +
          ui.color.gray(
            `   consecutive-stall ${g.reasons["consecutive-stall"]} · stale ${g.reasons["stale-live-attempt"]} · by hand ${g.reasons.manual}`
          )
      );
    }
  if (payload.demotions.runs_unattributed)
    console.log(
      ui.color.gray(
        `  ${payload.demotions.runs_unattributed} journal attempt(s) carry no run and are in no run's demotion history.`
      )
    );
  if (scan.sources.unreadable_spend_lines)
    console.log(
      "  " +
        ui.mark.warn(
          `${scan.sources.unreadable_spend_lines} unreadable line(s) in ${scan.spend_log} were skipped — those dispatches are NOT counted below.`
        ) +
        "\n"
    );
  for (const g of rows) {
    const oc = Object.entries(g.outcomes)
      .filter(([, n]) => n)
      .map(([k, n]) => `${k}:${n}`)
      .join(" ");
    console.log(
      `  ${ui.color.cyan((g.profile + " " + g.band).padEnd(26))} ${String(g.dispatches).padStart(4)}  ${oc}` +
        `   ${ui.color.gray(Object.keys(g.engines).join("+"))}`
    );
    const u = g.usage;
    const tokLine =
      g.usage_reported === g.dispatches
        ? `in ${kTok(u.input)} · cache-w ${kTok(u.cache_write)} · cache-r ${kTok(u.cache_read)} · out ${kTok(u.output)}`
        : // The honest form. Averaging a missing vector into the total would
          // make an unknown cost look like a small one.
          `in ${kTok(u.input)} · cache-w ${kTok(u.cache_write)} · cache-r ${kTok(u.cache_read)} · out ${kTok(u.output)}   ` +
          ui.mark.warn(`from ${g.usage_reported}/${g.dispatches} dispatches — ${g.usage_missing} reported no counts`);
    console.log("      " + ui.color.gray(tokLine));
    console.log(
      "      " +
        (g.usd === null
          ? ui.color.gray(`usd —  (no rate for ${g.provider || "?"} in the price table; a figure ORC did not price is never printed)`)
          : ui.color.gray(`usd ${g.usd < 0.01 ? "<0.01" : g.usd.toFixed(2)}`))
    );
  }
  const say = (label, arr, fmt) => {
    if (!arr.length) return;
    console.log("\n  " + ui.mark.warn(`${label}: ${arr.length}`));
    for (const x of arr.slice(0, 8)) console.log("    " + ui.color.gray(fmt(x)));
    if (arr.length > 8) console.log(ui.color.gray(`    … ${arr.length - 8} more`));
  };
  say("SUBSTITUTION — the endpoint answered with a different model", scan.subs, (x) => `${x.task}  requested ${x.requested} → reported ${x.reported}`);
  say("REROUTE — the model id held and the serving provider changed", scan.reroutes, (x) => `${x.task}  ${x.providers.join(" → ")}`);
  say("FALLBACK — the foreign dispatch failed and Claude finished it", scan.fallbacks, (x) => `${x.task}  ${x.reason} → ${x.agent}`);

  // RELIABILITY. Sample-floor restraint first, then the counts — and
  // `unattributed` is printed including when it is zero.
  const rel = payload.reliability;
  if (rel.profiles.length) {
    console.log("\n  " + ui.color.bold("reliability"));
    for (const g of rel.profiles) {
      console.log(
        `    ${ui.color.cyan(g.profile.padEnd(16))} ${g.dispatches_total} dispatch(es) · ${g.failed} failed · ${g.resumed} resumed · ${g.orphaned} orphaned` +
          (g.sample_too_small ? ui.color.gray(`   sample too small (floor ${rel.sample_floor})`) : `   failure rate ${Math.round(g.failure_rate * 100)}%`)
      );
      const a = g.attribution;
      console.log(
        ui.color.gray(
          `      attribution: provider ${a.provider} · network ${a.network} · local ${a.local} · worker ${a.worker} · orc ${a.orc} · unattributed ${g.unattributed}`
        )
      );
      if (g.mean_time_to_failure_ms !== null)
        console.log(ui.color.gray(`      mean time to failure ${extraDurStr(g.mean_time_to_failure_ms)}`));
    }
    if (rel.unreadable_journals || rel.journals_without_result)
      console.log(
        "    " +
          ui.mark.warn(
            `${rel.unreadable_journals} unreadable journal header(s) · ${rel.journals_without_result} attempt(s) with no result — named rather than absorbed.`
          )
      );
  }
  if (payload.missing_rates.length) {
    console.log(
      "\n  " +
        ui.mark.warn(
          `${plural(payload.missing_rates.length, "provider/model pair has", "provider/model pairs have")} no rate, so ${payload.unpriced_dispatches} of ${total} dispatches are unpriced.`
        )
    );
    console.log(ui.color.gray("     orc extra rates    prints the JSON to paste"));
  }
  console.log("");
}

// ── orc extra rates ────────────────────────────────────────────────────────
// Every provider/model pair the traces have actually USED, and whether the
// price table has a rate for it. This is the paste-the-JSON command, and it
// exists because `bin/pricing.json` ships every `models` map EMPTY on purpose:
// several of these vendors price by peak window or by tier, one sells a
// subscription rather than tokens, and one is a passthrough with a surcharge.
// A shipped figure that is wrong by 2x is worse than none, because a wrong
// figure gets believed.
function extraRates(claudeDir) {
  const asJson = wantsJson();
  const scan = extraStatsScan(claudeDir);
  const table = readPricing(claudeDir);
  const ledger = readExtra(claudeDir);
  const providerOf = (profile) => {
    const p = ledger && extraProfile(ledger, profile);
    return p ? p.provider : null;
  };
  const pairs = new Map();
  for (const r of scan.rows) {
    const provider = providerOf(r.profile) || "custom";
    const key = provider + "/" + r.model;
    if (!pairs.has(key))
      pairs.set(key, { provider, model: r.model, dispatches: 0, rate: foreignRate(table, provider, r.model) });
    pairs.get(key).dispatches++;
  }
  const rows = [...pairs.values()].sort((a, b) => b.dispatches - a.dispatches);
  const missing = rows.filter((r) => !r.rate);
  const skeleton = {};
  for (const r of missing) {
    skeleton[r.provider] = skeleton[r.provider] || { models: {} };
    skeleton[r.provider].models[r.model] = { input: 0, cache_write: 0, cache_read: 0, output: 0 };
  }
  const payload = {
    price_table: table ? { as_of: table.as_of, age_days: table._age_days, stale: table._stale, path: table._path } : null,
    pairs: rows,
    missing: missing.map((r) => r.provider + "/" + r.model),
    paste: Object.keys(skeleton).length ? { providers: skeleton } : null,
    where: "point `orc config set budget_price_table <path>` at your own copy rather than editing the shipped file, so `orc update` never overwrites your rates",
    caveats: rows
      .map((r) => {
        const b = table && table.providers && table.providers[r.provider];
        return b && b.caveat ? { provider: r.provider, caveat: b.caveat } : null;
      })
      .filter(Boolean)
      .filter((v, i, a) => a.findIndex((x) => x.provider === v.provider) === i),
  };
  if (asJson) emitJson(payload, missing.length ? 1 : 0);

  console.log(ui.header("ORC · extra rates"));
  if (!rows.length) {
    console.log("\n  No foreign dispatch has been traced yet, so there is nothing to price.\n");
    process.exit(0);
  }
  console.log("");
  for (const r of rows)
    console.log(
      `  ${ui.color.cyan((r.provider + "/" + r.model).padEnd(40))} ${String(r.dispatches).padStart(4)} dispatches  ` +
        (r.rate ? ui.mark.ok("rate present") : ui.mark.warn("NO RATE — usd will read —"))
    );
  for (const c of payload.caveats) console.log("\n  " + ui.mark.warn(`${c.provider}: ${c.caveat}`));
  if (payload.paste) {
    console.log("\n  Paste into your price table:\n");
    console.log(
      JSON.stringify(payload.paste, null, 2)
        .split("\n")
        .map((l) => "    " + l)
        .join("\n")
    );
    console.log("\n  " + ui.color.gray(payload.where));
  }
  console.log("");
  process.exit(missing.length ? 1 : 0);
}

function extraUsage() {
  return (
    "Usage: orc extra providers [--json]              the shipped, dated catalog\n" +
    "       orc extra add <profile> --provider <id> --engine <api|claude-shim|cli>\n" +
    "                               [--env-key NAME | --key-stdin | --tool-auth] [--region <id>]\n" +
    "                               [--base-url URL] [--anthropic-base-url URL]\n" +
    "                               [--cli <bin>] [--cli-agent <name>]\n" +
    "                               [--cli-attach http://localhost:4096] [--cli-args \"…\"]\n" +
    "       orc extra list [--json]                   profiles + state, NEVER a secret\n" +
    "       orc extra show <profile> [--json]\n" +
    '       orc extra remove <profile> --reason "<why>"\n' +
    "\n" +
    "       orc extra tools [--json] [--provider <id>]\n" +
    "                               the LOCAL TOOLS in the catalog, computed fresh:\n" +
    "                               absent · outdated · unauthenticated · ready\n" +
    "                               0 at least one is ready · 1 none is\n" +
    "       orc extra install <provider> [--manager <name>] [--dry-run] [--json]\n" +
    "                               opens YOUR terminal and runs the install there — visible,\n" +
    "                               never elevated, and the command is printed either way\n" +
    "       orc extra keyhelp <profile> [--json]\n" +
    "                               which of three credential routes applies:\n" +
    "                               env · stdin-login · interactive-login\n" +
    "\n" +
    "       orc extra ping <profile> [--deep] [--live] [--model <id>] [--json]\n" +
    "                               [--key-stdin | --passphrase-stdin]\n" +
    "                               the connection gate.  0 verified · 1 unreachable · 2 unknown profile\n" +
    "                               --key-stdin        paste a NEW key (line 1 the key, optional line 2\n" +
    "                                                  the passphrase that stores it after a green test)\n" +
    "                               --passphrase-stdin re-test a STORED key: the passphrase decrypts it\n" +
    "                                                  into memory for the probe and nothing else\n" +
    "                               --live             force the PAID rung: a real message to a real\n" +
    "                                                  model, with the round trip, the reply and the\n" +
    "                                                  four token counts. A CLI ping is NOT cheap\n" +
    "       orc extra models <profile> [--json] [--refresh] [--test <id>]\n" +
    "                               cached from the last ping; never invented.  --refresh re-reads\n" +
    "                               the live list; --test <id> proves ONE model actually answers,\n" +
    "                               because a LISTED model can still be dead upstream\n" +
    "       orc extra unlock <profile>                prove the passphrase (the key is never printed)\n" +
    "       orc extra rekey <profile>                 change the passphrase (needs the old one)\n" +
    "\n" +
    "       orc extra route [--json]                  the band table AND the Claude fall-through\n" +
    "       orc extra route set <from>-<to> <profile>/<model>\n" +
    "                               [--small-model <cheap-id>] [--max-turns N]\n" +
    "       orc extra route rm <from>-<to>\n" +
    "\n" +
    "       orc extra role [--json]                   the six POSITIONS - the non-scored half.\n" +
    "                               A slot with no row keeps its slot and reads as its pinned\n" +
    "                               Claude agent.  0 = at least one routes / 1 = none do\n" +
    "       orc extra role set <slot> <profile>/<model>\n" +
    "                               [--small-model <cheap-id>] [--max-turns N]\n" +
    "       orc extra role rm <slot>\n" +
    "       orc extra role show <slot> [--json]\n" +
    "       orc extra resolve <score> [--role <r>] [--risk N] [--json]\n" +
    "       orc extra resolve --slot <slot> [--risk N] [--json]\n" +
    "                               THE resolver.  0 = extra · 1 = claude\n" +
    "       orc extra conform <profile> [--deep] [--json]\n" +
    "                               measure the /anthropic shim: streams · tool round trip ·\n" +
    "                               cache_control · the beta fields.  0 usable · 1 not\n" +
    "       orc extra dispatch --task <slice.json> [--json]\n" +
    "                               THE BRIDGE. 0 done · 1 failed · 2 bad slice ·\n" +
    "                               3 not routed / capped · 4 partial\n" +
    "                               Writes every dispatch to .claude/orc/extra-spend.jsonl\n" +
    "                               itself, so a cost report never depends on a run\n" +
    "                               remembering to narrate what it spent.\n" +
    "       orc extra reconcile <task_id> [--attempt N] [--json]\n" +
    "                               THE POSITION a dead dispatch left on disk, free:\n" +
    "                               the baseline vs the worktree now, the last recorded\n" +
    "                               action, and WHOSE FAULT it was with the evidence.\n" +
    "                               0 resumable · 1 nothing-to-resume · 2 no journal ·\n" +
    "                               3 complete · 4 in-flight (REFUSED)\n" +
    "       orc extra resume-slice <task_id> --out <file> [--attempt N] [--json]\n" +
    "                               composes the CONTINUATION slice — the original slice\n" +
    "                               plus a preamble naming what is already on disk. It\n" +
    "                               never widens declared_files, never moves acceptance[]\n" +
    "                               and never moves the score.  0 written · 1 REFUSED\n" +
    "                               (not-resumable · in-flight · reverted-file ·\n" +
    "                               slice-drifted · resume-cap · resume-disabled) · 2 no journal\n" +
    "       orc extra journal [list | show <task_id> [--attempt N] [--body] | prune [--dry-run]]\n" +
    "                               what was journalled, and which dispatches never\n" +
    "                               reported back.  prune names EVERY directory before\n" +
    "                               it deletes one, and only ever a journal whose every\n" +
    "                               attempt closed `done` 30+ days ago\n" +
    "       orc extra stats [--since YYYY-MM-DD] [--json]\n" +
    "                               per profile per band: outcomes, substitutions, reroutes,\n" +
    "                               fallbacks, tokens, usd.  Merges the spend log, the EXTRA\n" +
    "                               trace lines and saved dispatch returns, deduped, and\n" +
    "                               always says how many came from each.\n" +
    "       orc extra rates [--json]                  which provider/model pairs have a price, and\n" +
    "                               the JSON to paste for the ones that do not.  0 all priced · 1 gaps\n" +
    "       orc extra session [<profile>] [--save --ttl <days> | --forget | --list | --sweep]\n" +
    "                               the saved passphrase and its DEADLINE. The passphrase\n" +
    "                               travels on STDIN; --passphrase <value> is refused by name.\n" +
    "       orc extra lanes [--json]                  WHICH LANE each band governs. A\n" +
    "                               fixed-executor lane shows both edges of its\n" +
    "                               pinned agent's band and whether they agreed.\n" +
    "       orc extra health <profile> [--model <id>] [--json]\n" +
    "                               DOES THIS MODEL STALL. Runs the live probe through the\n" +
    "                               SAME watchdog a dispatch uses and reports the timeline:\n" +
    "                               first byte, longest quiet gap, and whether it answered,\n" +
    "                               stalled or ran out of wall clock. Engine `cli` only.\n" +
    "                               0 answered - 1 stalled or failed - 2 unknown profile\n" +
    "       orc extra preflight [--json]              the P0 gate before wave 1.\n" +
    "                               0 ok · 1 STOP (an expired or missing passphrase on a\n" +
    "                               vaulted profile a route row names)\n" +
    "       orc extra demotion [<run-slug>] [--json]\n" +
    "                               HAS THIS RUN LEFT ITS FOREIGN PROVIDER. Computed from\n" +
    "                               the journal on every read, never stored as a verdict:\n" +
    "                               2 consecutive `stalled` dispatches on one profile, or a\n" +
    "                               live attempt quiet for extra_demote_stale_min minutes,\n" +
    "                               drop that profile to the BOTTOM of the ladder for the\n" +
    "                               rest of the run.  0 armed · 1 demoted · 2 unknown run\n" +
    "       orc extra promote <run-slug> --reason \"<why>\"\n" +
    "                               route foreign again in this run. Never automatic — two\n" +
    "                               stalls is evidence, and a timer that re-arms a provider\n" +
    "                               spends money on the evidence it already has.\n" +
    "                               0 promoted · 1 nothing was demoted · 2 unknown run\n" +
    "       orc extra demote <run-slug> --reason \"<why>\"\n" +
    "                               the manual half: keep this run on Claude without waiting\n" +
    "                               for two stalls.  0 demoted · 2 unknown run\n" +
    "       orc extra doctor [--json]                 0 clean · 1 findings"
  );
}

// ── orc extra session / preflight (v0.52.0) ───────────────
//
// The lifecycle the passphrase never had. Before this, a vaulted key needed
// ORC_EXTRA_KEY in the process environment or nothing, so a green, verified,
// routed profile answered `locked` at dispatch and the run announced a Claude
// fallback. That is safe and it is also a deadline you can miss without ever
// choosing to miss it.

// A DATE, never "in 27 days". A date is a thing a person can plan around.
function extraSessionDate(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  return d.toISOString().slice(0, 10);
}

function extraSessionRow(claudeDir, prof) {
  const st = extraSessionStateSwept(claudeDir, prof.name);
  const src = (prof.credential && prof.credential.source) || null;
  return {
    profile: prof.name,
    credential_source: src,
    // A profile that holds no vaulted key has no passphrase to cache, and that
    // is NOT a gap. `needs_passphrase: false` is why there is deliberately no
    // doctor finding for "you have not cached one".
    needs_passphrase: src === "vault",
    state: src === "vault" ? st.state : "ABSENT",
    days_left: st.days_left,
    expires_at: st.expires_at,
    expires_on: extraSessionDate(st.expires_at),
    ttl_days: st.ttl_days,
    created_at: st.created_at || null,
    last_used_at: st.last_used_at || null,
  };
}

function extraSessionCmd(claudeDir, name) {
  const asJson = wantsJson();
  const fail = (reason, msg) => {
    if (asJson) emitJson({ ok: false, reason, error: msg }, 1);
    console.error("❌ " + msg);
    process.exit(1);
  };
  const ledger = readExtra(claudeDir);
  const profiles = (ledger && ledger.profiles) || [];
  extraSessionSweep(claudeDir);
  const cfg = resolvedConfig(claudeDir);

  // A VALUE is refused BY NAME, with the same wording `--key <value>` uses.
  // stdin only, and that is why there is no "just pass it in a script" path.
  if (typeof flag("--passphrase") === "string")
    fail(
      "passphrase-in-argv",
      "`--passphrase <value>` does not exist on purpose: argv is world-readable in a process list and lands in shell history.\n" +
        "   The passphrase travels on STDIN: orc extra session <profile> --save --ttl <days>"
    );

  if (args.includes("--sweep")) {
    const dropped = extraSessionSweep(claudeDir);
    if (asJson) emitJson({ ok: true, swept: dropped }, 0);
    console.log(dropped.length ? `Removed ${plural(dropped.length, "expired passphrase")}: ${dropped.join(", ")}` : "Nothing had expired.");
    return;
  }

  if (args.includes("--list") || !name) {
    const rows = profiles.map((x) => extraSessionRow(claudeDir, x));
    if (asJson)
      emitJson(
        {
          ok: true,
          file: extraPaths(claudeDir).session,
          states: EXTRA_SESSION_STATES,
          ttl_options: EXTRA_TTL_DAYS,
          default_ttl_days: extraSessionTtl(cfg),
          honesty: EXTRA_SESSION_HONESTY,
          sessions: rows,
        },
        0
      );
    if (!rows.length) {
      console.log("No connections configured, so there is no passphrase to save.");
      return;
    }
    console.log(ui.header("ORC · extra — saved passphrases"));
    console.log("");
    console.log(
      ui.kv(
        rows.map((r) => [
          r.profile,
          !r.needs_passphrase
            ? ui.color.gray("no passphrase needed (" + (r.credential_source || "none") + ")")
            : r.state === "ACTIVE"
              ? ui.color.green(`saved until ${r.expires_on} (${r.days_left}d)`)
              : r.state === "EXPIRING"
                ? ui.color.yellow(`saved until ${r.expires_on} (${r.days_left}d left)`)
                : ui.color.red("not saved"),
        ])
      )
    );
    console.log(ui.color.gray("\n  " + EXTRA_SESSION_HONESTY + "\n"));
    return;
  }

  const prof = extraProfile(ledger, name);
  if (!prof) {
    const known = profiles.map((x) => x.name);
    const hint = `unknown profile "${name}"${known.length ? ` - known: ${known.join(", ")}` : ""}`;
    if (asJson) emitJson({ ok: false, reason: "unknown-profile", profile: name, known, hint }, 2);
    console.error("❌ " + hint);
    process.exit(2);
  }

  if (args.includes("--forget")) {
    const r = extraSessionForget(claudeDir, prof.name);
    const lf = readExtra(claudeDir);
    if (lf) writeExtra(claudeDir, extraHistory(lf, "session-forget", { profile: prof.name }));
    if (asJson) emitJson({ ok: true, profile: prof.name, removed: r.removed }, 0);
    console.log(r.removed ? `Forgot the saved passphrase for "${prof.name}".` : `Nothing was saved for "${prof.name}".`);
    return;
  }

  if (args.includes("--save")) {
    if ((prof.credential || {}).source !== "vault") {
      const hint = `"${prof.name}" does not use the vault (${(prof.credential || {}).source || "no credential"}), so there is no passphrase to save.`;
      if (asJson) emitJson({ ok: false, reason: "not-vaulted", profile: prof.name, hint }, 1);
      console.error("❌ " + hint);
      process.exit(1);
    }
    const ttlArg = flag("--ttl");
    const ttl = ttlArg === undefined ? extraSessionTtl(cfg) : Number(ttlArg);
    if (EXTRA_TTL_DAYS.indexOf(ttl) === -1)
      fail("bad-ttl", `--ttl must be one of: ${EXTRA_TTL_DAYS.join(" | ")}. There is no 0 and no "forever" - "forever" is the option that makes every other one pointless.`);
    const pass = (readStdinLines()[0] || "").trim() || promptSecret("passphrase: ");
    if (!pass) fail("no-passphrase", "nothing arrived on stdin. The passphrase travels on stdin and never in argv.");
    // TEST BEFORE STORE, the vault's own rule: a passphrase that does not open
    // the vault is a passphrase that will fail at wave 1 instead of here.
    const got = extraVaultGet(claudeDir, (prof.credential || {}).key_name || prof.name, pass, cfg.extra_vault_max_attempts);
    if (!got.ok) {
      if (asJson) emitJson({ ok: false, reason: got.reason, profile: prof.name, error: got.error, attempts_used: got.attempts_used || null }, 1);
      console.error("❌ " + (got.error || got.reason));
      process.exit(1);
    }
    const put = extraSessionPut(claudeDir, prof.name, pass, ttl);
    if (!put.ok) {
      if (asJson) emitJson({ ok: false, reason: put.reason, error: put.error }, 1);
      console.error("❌ " + (put.error || put.reason));
      process.exit(1);
    }
    ensureExtraGitignore(extraPaths(claudeDir).root);
    const ls = readExtra(claudeDir);
    if (ls) writeExtra(claudeDir, extraHistory(ls, "session-save", { profile: prof.name, ttl_days: ttl, expires_at: put.expires_at }));
    const row = extraSessionRow(claudeDir, prof);
    if (asJson) emitJson({ ok: true, profile: prof.name, honesty: EXTRA_SESSION_HONESTY, session: row }, 0);
    console.log(`Saved until ${row.expires_on}.`);
    console.log(ui.color.gray("  " + EXTRA_SESSION_HONESTY));
    return;
  }

  const row = extraSessionRow(claudeDir, prof);
  if (asJson)
    emitJson(
      { ok: true, profile: prof.name, honesty: EXTRA_SESSION_HONESTY, ttl_options: EXTRA_TTL_DAYS, default_ttl_days: extraSessionTtl(cfg), session: row },
      0
    );
  console.log(ui.header(`ORC · extra — ${prof.name}`));
  console.log("");
  console.log(
    ui.kv([
      ["credential", row.credential_source || "none"],
      ["passphrase", row.needs_passphrase ? row.state : "not needed"],
      ["saved until", row.expires_on || "-"],
      ["days left", row.days_left === null ? "-" : String(row.days_left)],
      ["last used", row.last_used_at ? row.last_used_at.slice(0, 10) : "-"],
    ])
  );
  console.log(ui.color.gray("\n  " + EXTRA_SESSION_HONESTY + "\n"));
}

// THE P0 GATE. It runs before wave 1, and an EXPIRED or ABSENT passphrase on a
// vaulted profile a route row names is a STOP - never a silent Claude
// fallback. `extra_on_failure` does NOT apply: that key is about an endpoint
// that failed, and letting `fallback` cover an expired credential would defeat
// the gate. A deadline you set 30 days ago deserves a stop, not a substitution.
//
// exit 0 ok (with or without warnings) * 1 stop
function extraPreflight(claudeDir) {
  const asJson = wantsJson();
  // The sweep runs FIRST and its answer is remembered, which is what lets the
  // rows below tell "expired today" from "never saved". Both STOP; only the
  // first one disconnects.
  extraSessionSweep(claudeDir);
  const ledger = readExtra(claudeDir);
  const cfg = resolvedConfig(claudeDir);
  const enabled = isTrue(cfg.extra_enabled);
  const routes = (ledger && ledger.routes) || [];
  // v0.55.0 - THE SLOT ROWS WALK HERE TOO. A slot row that would stop wave 1
  // and does not is the whole v0.52.0 deadline gate leaking through a new door:
  // same stop, same wording, same "the credential goes, the profile is stamped
  // expired, the rows survive" behaviour.
  const slots = (ledger && ledger.slots) || [];
  const named = new Set([...routes.map((r) => r.profile), ...slots.map((r) => r.profile)]);
  const profiles = ((ledger && ledger.profiles) || []).filter((x) => named.has(x.name));

  const rows = [];
  for (const prof of profiles) {
    const row = extraSessionRow(claudeDir, prof);
    const src = row.credential_source;
    if (src !== "vault") {
      rows.push(Object.assign(row, { verdict: "ok", why: "no passphrase is involved at all." }));
      continue;
    }
    if (row.state === "ACTIVE") {
      rows.push(Object.assign(row, { verdict: "ok", why: `saved until ${row.expires_on}.` }));
      continue;
    }
    if (row.state === "EXPIRING") {
      rows.push(Object.assign(row, { verdict: "warn", why: `saved until ${row.expires_on} - ${row.days_left} day(s) left.` }));
      continue;
    }
    rows.push(
      Object.assign(row, {
        verdict: "stop",
        why:
          row.state === "EXPIRED"
            ? "the saved passphrase reached its deadline. Connect again to route work here."
            : "no passphrase is saved for this vaulted connection, so nothing can open it.",
        next: `orc extra ping ${prof.name} --passphrase-stdin   (or reconnect in orc ui > Extra)`,
      })
    );
  }

  // ── ORPHANED DISPATCHES — READ-ONLY, and it does NOT change the exit code ──
  //
  // An orphan is a FINDING, not a stop. It REPORTS; it never resumes. Silently
  // continuing a third party's half-finished write into somebody's repository is
  // the same class of act as routing off Claude without saying so, and it gets
  // the same treatment: the user is told, and the user decides.
  const orphans = [];
  for (const r of extraJournalListRows(claudeDir).rows) {
    if (!r.orphan) continue;
    const v = extraReconcileCompute(claudeDir, r.task_id, r.attempt);
    const changed = v.ok ? v.files.filter((f) => f.state !== "untouched").length : 0;
    const row = {
      task_id: r.task_id,
      attempt: r.attempt,
      profile: r.profile,
      provider: r.provider,
      engine: r.engine,
      model_requested: r.model_requested,
      started_at: r.started_at,
      declared_files: r.declared_files.length,
      files_changed: changed,
      state: v.ok ? v.state : "no-journal",
      journal_fidelity: r.journal_fidelity,
      next: `orc extra reconcile ${r.task_id}`,
    };
    row.trace_line = extraOrphanTraceLine(row);
    orphans.push(row);
  }

  // ── THE DEMOTION — REPORTED, AND IT DOES NOT MOVE THE EXIT CODE ──────────
  //
  // The `extra-orphan-dispatch` precedent (v0.54.0), for the same reason: a
  // demotion is a FINDING, not a stop. The run is fine — it is going to run on
  // Claude, which is a correct answer — and stopping wave 1 over a routing
  // decision the user can reverse in one command would be a gate nobody asked
  // for. What it must never be is SILENT.
  let demotion = null;
  try {
    demotion = extraDemotionCached(claudeDir, cfg);
  } catch (_) {}
  const demoted = demotion && demotion.demoted ? demotion : null;

  const stops = rows.filter((r) => r.verdict === "stop");
  // Expiry DISCONNECTS: the vault record goes and the profile is stamped, so it
  // can never route again. The ROUTE ROWS SURVIVE (Decision 4) - the bands and
  // the model cache are work you did, and re-connecting should be one modal
  // rather than rebuilding the routing table.
  if (stops.length) {
    const l = readExtra(claudeDir);
    for (const st of stops) {
      if (!l) break;
      const prof = extraProfile(l, st.profile);
      if (!prof || st.state !== "EXPIRED") continue;
      const v = readVault(claudeDir);
      if (v.records[(prof.credential || {}).key_name || prof.name]) {
        delete v.records[(prof.credential || {}).key_name || prof.name];
        writeVault(claudeDir, v);
      }
      if (prof.credential) prof.credential.present = false;
      prof.verified_at = null;
      prof.expired_at = new Date().toISOString();
      extraHistory(l, "session-expired", { profile: prof.name });
    }
    if (l) writeExtra(claudeDir, l);
  }

  const code = stops.length ? 1 : 0;
  if (asJson)
    emitJson(
      {
        ok: !stops.length,
        extra_enabled: enabled,
        honesty: EXTRA_SESSION_HONESTY,
        // `extra_on_failure` is named here so nobody reads the stop as
        // something that key could have covered.
        on_failure_note:
          "extra_on_failure covers an endpoint that FAILED. An expired credential is a deadline you set, and it stops the run instead.",
        profiles: rows,
        stops: stops.map((x) => x.profile),
        warnings: rows.filter((r) => r.verdict === "warn").map((x) => x.profile),
        // Reported, never acted on — and never a stop. The exit code above is
        // unchanged.
        // Reported, never a stop — and the exit code above is unchanged.
        demotion: demoted
          ? {
              run: demoted.run,
              demoted_profiles: demoted.demoted_profiles,
              reasons: demoted.reasons,
              ladder: demoted.ladder,
              announce: demoted.announce,
              trace_line: demoted.trace_line,
              promote: `orc extra promote ${demoted.run} --reason "<why>"`,
            }
          : null,
        demotion_note:
          "a demotion is a FINDING, not a stop: the run continues on Claude. It is never promoted back on its own, and nothing was written to your config.",
        orphans,
        orphan_note:
          "a foreign dispatch that never reported back. It is REPORTED here and never resumed: continuing a third party's half-finished write without asking is the same class of act as routing off Claude without saying so.",
        trace_extras: orphans.map((o) => o.trace_line),
      },
      code
    );
  if (demoted) {
    console.log("  " + ui.mark.warn(demoted.announce));
    console.log("");
  }
  if (orphans.length) {
    console.log(
      "  " +
        ui.mark.warn(
          `${orphans.length} foreign ${orphans.length === 1 ? "dispatch" : "dispatches"} from an earlier run never reported back`
        )
    );
    for (const o of orphans) {
      console.log(
        `    ${o.task_id} · ${o.profile}/${o.model_requested || "?"} · started ${String(o.started_at || "?").slice(11, 16)} · ` +
          `${o.declared_files} declared file(s), ${o.files_changed} changed on disk`
      );
      console.log("    " + ui.color.bold(o.next) + ui.color.gray(`   →   ${o.state}`));
    }
    console.log("");
  }
  if (!rows.length) {
    console.log("No routed connection needs a passphrase.");
    return;
  }
  for (const r of rows) {
    const mark = r.verdict === "ok" ? ui.mark.ok("ok") : r.verdict === "warn" ? ui.mark.warn("expiring") : ui.mark.bad("STOP");
    console.log(`  ${ui.color.cyan(r.profile)}  ${mark}  ${r.why}`);
    if (r.next) console.log("      " + ui.color.bold(r.next));
  }
  console.log("");
  console.log(ui.color.gray("  " + EXTRA_SESSION_HONESTY));
  if (code) process.exit(1);
}

async function extra() {
  if (flag("--global")) {
    console.error(
      "❌ orc extra is project-scoped — a route table is this repo's. Run it from the project (or with --dir <path>)."
    );
    process.exit(1);
  }
  const claudeDir = resolveClaudeDir();
  const pos = positionals(); // ["extra", <sub?>, <arg?>, …]
  // v0.52.0 — THE SWEEP, and this is the only clock it has. A passphrase past
  // its deadline is removed when an `orc extra` command runs and at the P0 gate,
  // never on a timer: a background process that deletes credentials is a
  // background process nobody can audit.
  try {
    extraSessionSweep(claudeDir);
  } catch (_) {}
  switch (pos[1]) {
    case "providers":
      extraProvidersCmd();
      break;
    case "add":
      extraAdd(claudeDir, pos[2]);
      break;
    case undefined:
    case "list":
      extraList(claudeDir);
      break;
    case "show":
      extraShow(claudeDir, pos[2]);
      break;
    case "remove":
      extraRemove(claudeDir, pos[2]);
      break;
    case "ping":
      await extraPing(claudeDir, pos[2]);
      break;
    case "models":
      await extraModels(claudeDir, pos[2]);
      break;
    // v0.51.0 — the three commands that make a LOCAL TOOL a first-class
    // connection: what is installed, running the install in the user's own
    // terminal, and which of three credential routes this profile is on.
    case "tools":
      extraTools(claudeDir);
      break;
    case "install":
      extraInstallCmd(claudeDir, pos[2]);
      break;
    case "keyhelp":
      extraKeyhelp(claudeDir, pos[2]);
      break;
    case "unlock":
      extraUnlock(claudeDir, pos[2]);
      break;
    // v0.52.0 - the passphrase LIFECYCLE, and the gate that reads it.
    case "session":
      extraSessionCmd(claudeDir, pos[2]);
      break;
    case "preflight":
      extraPreflight(claudeDir);
      break;
    // v0.56.1 - the stall clock, measurable BEFORE a wave depends on it.
    case "health":
      await extraHealth(claudeDir, pos[2]);
      break;
    case "route":
      if (pos[2] === "set") extraRouteSet(claudeDir, pos[3], pos[4]);
      else if (pos[2] === "rm") extraRouteRm(claudeDir, pos[3]);
      else if (pos[2] === undefined || pos[2] === "list") extraRouteList(claudeDir);
      else {
        console.error(`Unknown: orc extra route ${pos[2]}\n` + extraUsage());
        process.exit(1);
      }
      break;
    // v0.55.0 - THE POSITIONS. A score is what a band needs, and four lanes do
    // not have one; this is where their slots are held.
    case "role":
      if (pos[2] === "set") extraRoleSet(claudeDir, pos[3], pos[4]);
      else if (pos[2] === "rm") extraRoleRm(claudeDir, pos[3]);
      else if (pos[2] === "show") extraRoleShow(claudeDir, pos[3]);
      else if (pos[2] === undefined || pos[2] === "list") extraRoleList(claudeDir);
      else {
        console.error(`Unknown: orc extra role ${pos[2]}\n` + extraUsage());
        process.exit(1);
      }
      break;
    case "resolve":
      extraResolveCmd(claudeDir, pos[2]);
      break;
    // v0.52.0 — WHICH LANE a band governs. The correct behaviour was already
    // implemented and the reasoning already written down; none of it was
    // rendered anywhere.
    case "lanes":
      extraLanes(claudeDir);
      break;
    case "privacy":
      extraPrivacy(claudeDir, pos[2]);
      break;
    case "stats":
      extraStats(claudeDir);
      break;
    case "rates":
      extraRates(claudeDir);
      break;
    case "conform":
      extraConform(claudeDir, pos[2]);
      break;
    case "dispatch":
      await extraDispatch(claudeDir);
      break;
    // v0.54.0 — the two READS that turn a dead dispatch into a position. Both
    // are zero-token and deterministic; neither writes anything but a prune the
    // user asked for by name.
    case "reconcile":
      extraReconcileCmd(claudeDir, pos[2]);
      break;
    case "resume-slice":
      extraResumeSlice(claudeDir, pos[2]);
      break;
    case "journal":
      extraJournalCmd(claudeDir, pos[2], pos[3]);
      break;
    // v1.0.0 W5 — the stall demotion. A READ whose exit code is the answer, and
    // two WRITES that each require a reason.
    case "demotion":
      extraDemotionCmd(claudeDir, pos[2]);
      break;
    case "promote":
      extraDemoteCmd(claudeDir, pos[2], "promote");
      break;
    case "demote":
      extraDemoteCmd(claudeDir, pos[2], "demote");
      break;
    case "doctor":
      extraDoctor(claudeDir);
      break;
    default:
      console.error(`Unknown: orc extra ${pos[1]}\n` + extraUsage());
      process.exit(1);
  }
}

// ── orc doctor (B6) — installed-side drift detector ────────────────────────
// Read-only health report over a target .claude/ (respects --global / --dir).
// `orc doctor --fix` = update + prune + settings re-merge (install overwrite).
// `orc doctor --json` renders the SAME findings as one JSON object on stdout —
// nothing else, no banner, no colour, no nudge — for a script or a CI step. The
// EXIT CODE is identical either way (0 healthy / 1 issues found): the flag
// changes the rendering only, never the semantics.
function doctor() {
  const claudeDir = resolveClaudeDir();
  const asJson = flag("--json") === true;
  if (flag("--fix") === true) {
    // A mutation and a machine-readable read-only report are two different
    // commands. Refusing beats silently handing a script the human output.
    if (asJson) {
      console.error("❌ orc doctor --json is read-only — drop --fix (or run the two separately).");
      process.exit(1);
    }
    console.log(`Applying fixes to ${claudeDir} (update + prune + settings re-merge)…\n`);
    install({ overwrite: true, forcePrune: true });
    console.log("\nRe-run `orc doctor` to confirm a clean report.");
    return;
  }

  const say = asJson ? () => {} : (s) => console.log(s);
  say(ui.color.bold(`orc doctor`) + ` — ${claudeDir}\n`);
  const problems = [];
  const findings = [];
  const ok = (s) => say("  " + ui.mark.ok(s));
  // id: stable machine key. fixable: would `orc doctor --fix` address it?
  const warn = (id, s, extra) => {
    say("  " + ui.mark.warn(s));
    problems.push(s);
    findings.push(Object.assign({ id, severity: "warn", message: s, fixable: false }, extra || {}));
  };

  // 1) payload version vs this CLI's version
  const cliVersion = currentVersion();
  let installedVersion = null;
  if (!fs.existsSync(path.join(claudeDir, "hooks"))) {
    warn("no-payload", "no ORC payload here (hooks/ missing) — run `orc init`.", { fixable: true });
  } else {
    const payloadV = (installedVersion = installedPayloadVersion(claudeDir));
    const cliV = cliVersion;
    if (payloadV === cliV) ok(`payload version ${payloadV} matches this CLI`);
    else
      warn("version-skew", `payload version ${payloadV} != CLI ${cliV} — run \`orc update\``, {
        fixable: true,
        installed_version: payloadV,
        package_version: cliV,
      });
  }

  // 1b) GLOBAL install skew (C5). Claude Code resolves a skill by NAME, and a
  // stale ~/.claude copy can win over this project's — so a report of "payload
  // matches" is worthless if the file that actually loads is three versions
  // old. Warn, never delete: a global install is not this project's to prune.
  const globalDir = path.join(os.homedir(), ".claude");
  const globalInfo = { present: false, version: null, shadows: false };
  if (path.resolve(globalDir) !== path.resolve(claudeDir)) {
    if (!fs.existsSync(path.join(globalDir, "hooks"))) {
      ok("no global ORC install (~/.claude) — nothing can shadow this one");
    } else {
      const globalV = installedPayloadVersion(globalDir);
      const localV = installedPayloadVersion(claudeDir);
      globalInfo.present = true;
      globalInfo.version = globalV;
      if (globalV !== localV) {
        globalInfo.shadows = true;
        warn(
          "global-skew",
          `GLOBAL install ~/.claude is ${globalV} but this project is ${localV} — ` +
            "the global copy can win skill resolution; run `orc update --global`",
          { global_version: globalV, local_version: localV }
        );
      } else ok(`global install ~/.claude matches (${globalV})`);
      // Agent files the global install still carries that this payload no
      // longer ships: a dispatch by a retired name resolves there instead of
      // failing loudly — the exact silent downgrade a rename must prevent.
      try {
        const shipped = new Set(shippedFootprint());
        const shadows = fs
          .readdirSync(path.join(globalDir, "agents"))
          .filter((f) => /^orc-.*\.md$/i.test(f) && !shipped.has("agents/" + f));
        if (shadows.length) {
          globalInfo.shadows = true;
          // `--prune` is NOT optional here, and saying `orc update --global`
          // alone made this finding permanent. These names were retired BEFORE
          // the manifest now on disk was written, so no manifest ever claimed
          // them: the auto-prune (which only deletes what a previous manifest
          // proves ORC owned) can never reach them, and a plain update just
          // re-reports them forever. The candidate sweep that DOES catch them
          // is gated on --prune by design — it is deleting files nothing proves
          // are ours.
          warn(
            "global-retired-agents",
            `${shadows.length} retired agent name(s) still live in ~/.claude/agents: ` +
              shadows.slice(0, 5).join(", ") + (shadows.length > 5 ? " …" : "") +
              " — run `orc update --global --prune` (--prune is required: no manifest claims these, " +
              "so a plain update only reports them; never deleted from here)",
            { paths: shadows.map((f) => "agents/" + f), fix_command: "orc update --global --prune" }
          );
        } else ok("no retired agent names shadowing from ~/.claude/agents");
      } catch (_) {}
    }
  }

  // 2) manifest vs the shipped footprint (orphans + missing files)
  const footprint = shippedFootprint();
  const current = new Set(footprint);
  const manifest = readManifest(claudeDir);
  const trunc = (a) => a.slice(0, 5).join(", ") + (a.length > 5 ? " …" : "");
  const missing = footprint.filter((f) => !fs.existsSync(path.join(claudeDir, f)));
  if (!manifest) {
    const cand = detectPreManifestOrphans(claudeDir, current);
    if (cand.length)
      warn(
        "orphan-candidates",
        `${cand.length} possible orphan(s), no install manifest: ${trunc(cand)} — \`orc update --prune\``,
        { fixable: true, paths: cand }
      );
    else ok("no install manifest yet; no ORC-named orphans detected");
  } else {
    const orphans = manifest.files.filter(
      (f) => !current.has(f) && isPrunable(f) && fs.existsSync(path.join(claudeDir, f))
    );
    if (orphans.length)
      warn("orphan", `${orphans.length} orphan(s) from a prior payload: ${trunc(orphans)} — \`orc update\``, {
        fixable: true,
        paths: orphans,
      });
    else ok("no orphaned files from prior payloads");
  }
  if (missing.length)
    warn("missing-files", `${missing.length} shipped file(s) missing on disk: ${trunc(missing)} — \`orc update\``, {
      fixable: true,
      paths: missing,
    });
  else ok("all shipped files present on disk");

  // 3) settings.json wiring
  let settings = null;
  try {
    settings = JSON.parse(fs.readFileSync(path.join(claudeDir, "settings.json"), "utf8"));
  } catch (_) {}
  if (!settings) {
    warn("settings-missing", "settings.json missing or unparseable — run `orc update` to re-merge the guards.", {
      fixable: true,
    });
  } else {
    const hooks = settings.hooks || {};
    const hasCmd = (arr, needle) =>
      (arr || []).some((e) => (e.hooks || []).some((h) => typeof h.command === "string" && h.command.includes(needle)));
    if (hasCmd(hooks.PreToolUse, "orc-effort-guard")) ok("effort guard wired (PreToolUse)");
    else warn("effort-guard-unwired", "effort guard NOT wired — /orc won't be effort-gated; run `orc update`", { fixable: true });
    const traceEntry = (hooks.PreToolUse || []).find((e) =>
      (e.hooks || []).some((h) => typeof h.command === "string" && h.command.includes("orc-trace"))
    );
    if (!traceEntry)
      warn("trace-hook-unwired", "trace hook NOT wired on PreToolUse — SPAWN lines lost; run `orc update`", { fixable: true });
    else if (!/Task/.test(traceEntry.matcher || "") || !/Agent/.test(traceEntry.matcher || ""))
      warn(
        "trace-hook-matcher",
        'trace PreToolUse matcher is "' + (traceEntry.matcher || "") + '" — needs "Task|Agent"; run `orc update`',
        { fixable: true }
      );
    else ok('trace hook wired with a Task|Agent matcher');
    if (hasCmd(hooks.SubagentStop, "orc-trace")) ok("trace RETURN wired (SubagentStop)");
    else warn("trace-return-unwired", "trace RETURN hook NOT wired (SubagentStop) — run `orc update`", { fixable: true });
    if (settings.statusLine && typeof settings.statusLine.command === "string") {
      if (settings.statusLine.command.includes("orc-statusline")) ok("statusline is ORC's model warning");
      else ok("statusline present (yours — ORC left it untouched)");
    } else
      warn("statusline-missing", "no statusLine — the non-Opus/high model warning won't show; run `orc update`", {
        fixable: true,
      });
  }

  // 4) dangling trace .current pointer
  const logRel = readOverride(claudeDir).map.log_dir || ".claude/orc/logs";
  const logDir = path.isAbsolute(logRel) ? logRel : path.join(claudeDir, "..", logRel);
  const curFile = path.join(logDir, ".current");
  try {
    if (fs.existsSync(curFile)) {
      const cur = fs.readFileSync(curFile, "utf8").trim();
      if (cur && !fs.existsSync(path.join(logDir, cur)))
        warn(
          "trace-pointer-dangling",
          `trace .current points to a missing file "${cur}" (a fresh run rotates past it — harmless)`,
          { trace_current: cur }
        );
      else ok("trace pointer resolves (or no active run)");
    } else ok("no trace pointer yet (no run recorded)");
  } catch (_) {}

  // 5) stale DIY lock (only meaningful once configured)
  const dstat = diyStatus(claudeDir);
  if (dstat.state === "UNCONFIGURED") ok("orc-diy not configured (fine — /orc-diy stays gated)");
  else if (dstat.state === "STALE") warn("diy-stale", `orc-diy flow STALE: ${dstat.reason}`, { reason: dstat.reason });
  else ok(`orc-diy flow READY (${dstat.reason})`);

  // 5b) the wiki (v0.49.1). Exactly TWO findings, and the restraint is the
  // design: a doctor that warns about normal states teaches people to ignore
  // doctor. Both route to the Knowledge panel via FINDING_ROUTE — a caution
  // routes to the panel that can CLEAR it, and `orc wiki sync` is a button
  // there.
  try {
    const ws = wikiState(claudeDir);
    if (ws.state === "none") ok("no wiki (fine — nothing consults one)");
    else if (["unregistered", "drifted", "corrupt"].includes(ws.state))
      warn(
        "wiki-unregistered",
        `wiki is ${ws.state.toUpperCase()} — nothing can read it until it is registered. ` +
          "Fix: `orc wiki sync` (FREE, instant, derived from the docs, no re-scan)",
        { state: ws.state, fix_command: "orc wiki sync" }
      );
    else {
      const wpaths = wikiPaths(claudeDir);
      const f = computeWikiFreshness(wpaths.root, ws.meta, wikiFreshnessEdges(claudeDir));
      // STALE only, and NEVER on AGING. Aging is a normal state that every
      // living repo passes through, and a doctor that warns about it is a
      // doctor people learn to skip.
      if (f.tier === "STALE") {
        const plan = wikiPlanRows(claudeDir);
        const pending = plan && !plan.error ? plan.rows.length : 0;
        if (pending)
          warn(
            "wiki-debt",
            `wiki is STALE with ${plural(pending, "doc")} pending a refresh` +
              (f.reasons[0] ? ` (${f.reasons[0]})` : "") +
              " — `orc wiki plan` ranks them; `/orc-wiki refresh --top 2` is the cheapest real dent",
            { tier: f.tier, pending, fix_command: "/orc-wiki refresh --top 2" }
          );
        else ok(`wiki STALE but nothing pending a refresh (${plural(ws.docs, "doc")})`);
      } else ok(`wiki ${f.tier} (${plural(ws.docs, "doc")}${f.distance === null ? "" : ", " + f.distance + "c on the worst doc"})`);
    }
  } catch (_) {}

  // 5c) THE LANE CONFIG CONTRACT, ON DISK (v1.0.0 W16). `bin/verify-contracts.js`
  // asserts this both ways in the SOURCE tree; this is the same assertion
  // against the payload that is actually INSTALLED, which is the only copy a
  // run ever reads. It fires when the two halves of an install are out of step
  // — a CLI that knows a lane reads keys sitting on a spine from before that
  // lane had the contract — and that is precisely the state in which a lane
  // falls back to merging `.claude/orc.config.yaml` itself and gets a shadowed
  // key wrong, silently.
  //
  // Both directions, because an empty answer is an ANSWER (v0.43.0): a spine
  // that names the contract while the CLI says the lane reads nothing is drift
  // in the other direction, and it promises an answer the CLI would refuse.
  // `version-skew` may well fire alongside this — it says the numbers differ,
  // this says what a run would get wrong because of it. FIXABLE: `orc update`
  // re-copies the payload, which is what `orc doctor --fix` does.
  try {
    const skillsDir = path.join(claudeDir, "skills");
    if (fs.existsSync(skillsDir)) {
      const drifted = [];
      for (const l of LANES) {
        const spine = path.join(skillsDir, l.lane, "SKILL.md");
        // A spine that is not on disk at all belongs to `missing-files`, which
        // already names it. Reporting it twice is a doctor being loud.
        if (!fs.existsSync(spine)) continue;
        const text = fs.readFileSync(spine, "utf8");
        const keys = CONFIG_META.filter((m) => (m.lanes || []).includes(l.lane)).map((m) => m.key);
        const names = text.includes(`orc lane config ${l.lane} --json`);
        if (keys.length && !names)
          drifted.push({
            lane: l.lane,
            keys: keys.length,
            direction: "spine-behind",
            why: `reads ${plural(keys.length, "key")} but the installed spine does not name \`orc lane config ${l.lane} --json\``,
          });
        else if (!keys.length && text.includes("orc lane config"))
          drifted.push({
            lane: l.lane,
            keys: 0,
            direction: "spine-ahead",
            why: "reads no config key, but the installed spine still carries a config contract",
          });
      }
      if (drifted.length)
        warn(
          "lane-keys-drifted",
          `${plural(drifted.length, "lane")} out of step with this CLI's config model: ${drifted
            .map((d) => d.lane)
            .join(", ")} — a lane with no contract resolves config itself, and gets a shadowed key wrong. Run \`orc update\``,
          { lanes: drifted, fixable: true, fix_command: "orc update" }
        );
      else ok(`lane config contract intact on all ${LANES.length} lanes`);
    }
  } catch (_) {}

  // 6) a document that drifted (v0.48.1). Routed to the Docs panel via
  // FINDING_ROUTE — a caution points at the panel that can CLEAR it, and
  // `orc doc audit` / `orc doc ship` both live there.
  try {
    const dirty = [];
    for (const s of docList(claudeDir)) {
      const res = docAuditFindings(claudeDir, s);
      const errs = res ? res.findings.filter((f) => f.level === "error").length : 0;
      const warns = res ? res.findings.length - errs : 0;
      if (res && res.findings.length) dirty.push({ slug: s, errors: errs, warnings: warns });
    }
    if (dirty.length)
      warn(
        "doc-drifted",
        `${plural(dirty.length, "document")} audit dirty: ${dirty.map((x) => x.slug).join(", ")} — \`orc doc audit <slug>\` names each finding and its fix`,
        { documents: dirty }
      );
    else if (docList(claudeDir).length) ok(`${plural(docList(claudeDir).length, "document")}, none drifted`);
  } catch (_) {}

  // 6b) The legacy global package (v0.56.0). This is not a `.claude/` problem —
  // it is a problem with the TOOL ITSELF, and it is the one finding that
  // explains why `orc upgrade` cannot fix anything else in this report. It is
  // NOT fixable by `orc doctor --fix`: that command's whole blast radius is
  // this project's .claude/, and evicting a global npm package is neither
  // project-scoped nor something to do without saying so. `orc upgrade` does it
  // (announced), so the fix command points there.
  try {
    const legacyOwner = detectLegacyBinOwner();
    if (legacyOwner)
      warn(
        "legacy-global-package",
        `${legacyOwner.name}@${legacyOwner.version} is installed globally and owns the \`orc\` ` +
          `command, but this package is now ${PKG_NAME} — npm refuses to link \`orc\` over it, ` +
          "so EVERY install source fails with the same EEXIST. Run `orc upgrade` (it removes the " +
          `old package first), or by hand: \`npm uninstall -g ${legacyOwner.name} && npm i -g ${NPM_SPEC}\``,
        {
          legacy_name: legacyOwner.name,
          legacy_version: legacyOwner.version,
          legacy_dir: legacyOwner.dir,
          package_name: PKG_NAME,
          fix_command: "orc upgrade",
        }
      );
  } catch (_) {}

  // 7) `orc extra` (v0.50.0). ONE line here, carrying the COUNT and the
  // command that itemises it — the restraint is deliberate and the same call
  // the two wiki findings made: a doctor that recites eleven finding ids for a
  // subsystem most repos never arm is a doctor people learn to scroll past.
  // Each id still gets its own FINDING_ROUTE row, because a caution routes to
  // the panel that can CLEAR it.
  try {
    const ex = extraDoctorFindings(claudeDir);
    if (ex.length)
      warn(
        "extra-findings",
        `orc extra has ${plural(ex.length, "finding")} (${[...new Set(ex.map((f) => f.id))].join(", ")}) — \`orc extra doctor\` names each one`,
        { count: ex.length, ids: [...new Set(ex.map((f) => f.id))], extra_findings: ex }
      );
    else if (readExtra(claudeDir)) ok("orc extra: profiles and routes clean");
  } catch (_) {}

  if (asJson) {
    // Exactly one object, then the same exit code the human path would use.
    process.stdout.write(
      JSON.stringify(
        {
          ok: problems.length === 0,
          claude_dir: claudeDir,
          installed_version: installedVersion,
          package_version: cliVersion,
          global_install: globalInfo,
          findings,
          fixable: findings.some((f) => f.fixable),
        },
        null,
        2
      ) + "\n"
    );
    process.exit(problems.length ? 1 : 0);
  }

  console.log("");
  if (problems.length) {
    console.log(
      "  " + ui.mark.warn(ui.color.bold(`${problems.length} issue(s) found.`)) +
        " Fix automatically with:  orc doctor --fix"
    );
    process.exit(1);
  }
  console.log("  " + ui.color.green("✅ ORC install looks healthy."));
}

// ---------------------------------------------------------------------------
// Version + update check. Current version = this package's package.json. Latest
// = the raw package.json on the install source's default branch (that's what
// `orc upgrade` would pull). Cached 24h in ~/.orc-update-check.json, fail-silent
// offline, opt out with ORC_NO_UPDATE_CHECK=1.
// ---------------------------------------------------------------------------

const UPDATE_URL =
  process.env.ORC_VERSION_URL ||
  "https://raw.githubusercontent.com/azure-id/orc/main/package.json";
// The changelog lives in CHANGELOG.md next to that package.json, on the same
// branch `orc upgrade` installs from — so "what would I get" is answered by the
// same source as "is there something newer", never by a second one that could
// describe a different release. (It lived in the README until the README was
// compacted; the README now carries only the newest entry and links here, so
// reading the README would answer with one entry no matter how far behind you
// are.)
const CHANGELOG_URL =
  process.env.ORC_CHANGELOG_URL ||
  "https://raw.githubusercontent.com/azure-id/orc/main/CHANGELOG.md";
const CACHE_FILE = path.join(os.homedir(), ".orc-update-check.json");
const CHECK_TTL_MS = 24 * 60 * 60 * 1000;

// The version check and the install are two different URLs on (normally) the
// same branch, and only the install one was ever printed. That gap is what makes
// "it says up to date and it is not" undiagnosable: a maintainer reads
// `source: …/heads/main.tar.gz`, concludes the check read main, and never learns
// that the release they cut is still sitting on an unmerged branch. So say which
// ref the NUMBER came from, on every surface that reports the number.
// `orc changelog --json` has always carried its own `source`; this is that field's
// missing twin, not a new idea.
function checkSourceLabel(url) {
  const m = String(url).match(
    /^https:\/\/raw\.githubusercontent\.com\/([^/]+)\/([^/]+)\/([^/]+)\//
  );
  return m ? `${m[1]}/${m[2]}@${m[3]}` : String(url);
}

function currentVersion() {
  try {
    return require(path.join(PKG_ROOT, "package.json")).version || "0.0.0";
  } catch (_) {
    return "0.0.0";
  }
}

function parseSemver(v) {
  const m = String(v).trim().replace(/^v/, "").match(/^(\d+)\.(\d+)\.(\d+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
}
function semverGt(a, b) {
  const x = parseSemver(a);
  const y = parseSemver(b);
  if (!x || !y) return false;
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] > y[i];
  return false;
}

// Zero-dep HTTPS GET → parsed JSON (or null). Bounded timeout, one redirect hop.
function httpsGetJson(url, timeoutMs) {
  return new Promise((resolve) => {
    let settled = false;
    const done = (v) => {
      if (!settled) {
        settled = true;
        resolve(v);
      }
    };
    try {
      const https = require("https");
      const req = https.get(
        url,
        { headers: { "User-Agent": "orc-cli" } },
        (res) => {
          if (
            res.statusCode >= 300 &&
            res.statusCode < 400 &&
            res.headers.location
          ) {
            res.resume();
            httpsGetJson(res.headers.location, timeoutMs).then(done);
            return;
          }
          if (res.statusCode !== 200) {
            res.resume();
            return done(null);
          }
          let data = "";
          res.on("data", (c) => (data += c));
          res.on("end", () => {
            try {
              done(JSON.parse(data));
            } catch (_) {
              done(null);
            }
          });
        }
      );
      req.on("error", () => done(null));
      req.setTimeout(timeoutMs, () => {
        req.destroy();
        done(null);
      });
    } catch (_) {
      done(null);
    }
  });
}

function readCache() {
  try {
    return JSON.parse(fs.readFileSync(CACHE_FILE, "utf8"));
  } catch (_) {
    return null;
  }
}
function writeCache(obj) {
  try {
    fs.writeFileSync(CACHE_FILE, JSON.stringify(obj));
  } catch (_) {}
}

const updateCheckDisabled = () =>
  process.env.ORC_NO_UPDATE_CHECK === "1" || process.env.CI === "true";

// Latest version, honoring the 24h cache. force=true ignores the TTL.
async function getLatestVersion({ force }) {
  const cache = readCache();
  const fresh = cache && Date.now() - (cache.checkedAt || 0) < CHECK_TTL_MS;
  if (!force && fresh) return cache.latest || null;
  const pkg = await httpsGetJson(UPDATE_URL, 2000);
  const latest = pkg && pkg.version ? pkg.version : cache ? cache.latest : null;
  // Preserve any remembered last_good_spec — writeCache overwrites the whole file.
  writeCache({ ...(cache || {}), checkedAt: Date.now(), latest });
  return latest;
}

// One-line nudge appended to normal commands. Uses the cache (refreshing at most
// once/24h). Never throws, never blocks meaningfully when offline.
async function maybeNudge() {
  if (updateCheckDisabled()) return;
  try {
    const latest = await getLatestVersion({ force: false });
    const cur = currentVersion();
    if (latest && semverGt(latest, cur)) {
      console.log(
        `\n⬆  orc ${latest} is available (you have ${cur}). Run \`orc upgrade\` to update.`
      );
    }
  } catch (_) {}
}

// `orc version` — always live-checks (bounded), so users can force a check.
async function version() {
  const cur = currentVersion();
  if (wantsJson()) {
    const latest = updateCheckDisabled() ? null : await getLatestVersion({ force: true });
    return emitJson({
      version: cur,
      latest,
      update_available: !!(latest && semverGt(latest, cur)),
      // What `orc upgrade` would actually install — the resolved source matters
      // more than the version number when approving a network mutation.
      install_spec: process.env.ORC_INSTALL_SPEC || readLastGoodSpec() || TARBALL_SPEC,
      // Where `latest` was read FROM. Not the same URL as install_spec, and the
      // only thing that distinguishes "you are current" from "the release never
      // reached the ref this reads".
      checked_source: UPDATE_URL,
      checked_ref: checkSourceLabel(UPDATE_URL),
      check_disabled: updateCheckDisabled(),
    });
  }
  console.log(`orc ${cur}`);
  if (updateCheckDisabled()) return;
  const latest = await getLatestVersion({ force: true });
  const from = checkSourceLabel(UPDATE_URL);
  if (!latest) {
    console.log(`(couldn't check for updates — offline or ${from} unreachable)`);
  } else if (semverGt(latest, cur)) {
    console.log(`⬆  newer version available: ${latest} — run \`orc upgrade\``);
  } else {
    console.log(`✓ up to date (${from} is at ${latest})`);
  }
}

// ---------------------------------------------------------------------------
// orc changelog — "what would I actually get if I upgraded".
//
// A version number is not a reason to upgrade. This fetches CHANGELOG.md from
// the same branch `orc upgrade` installs from and returns the entries NEWER than
// what is installed, so the answer and the payload can never describe different
// releases.
//
// Parsing is deliberately forgiving: the changelog is prose a human maintains,
// and a heading that does not match must degrade to "no entries", never to a
// crash or a wrong entry. Anything unparsed is simply not reported.
// ---------------------------------------------------------------------------

// Zero-dep HTTPS GET → text (or null). Same bounded, redirect-following,
// fail-silent shape as httpsGetJson — this one just does not parse.
function httpsGetText(url, timeoutMs) {
  return new Promise((resolve) => {
    let settled = false;
    const done = (v) => {
      if (!settled) {
        settled = true;
        resolve(v);
      }
    };
    try {
      const https = require("https");
      const req = https.get(url, { headers: { "User-Agent": "orc-cli" } }, (res) => {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          res.resume();
          httpsGetText(res.headers.location, timeoutMs).then(done);
          return;
        }
        if (res.statusCode !== 200) {
          res.resume();
          return done(null);
        }
        let data = "";
        res.on("data", (c) => (data += c));
        res.on("end", () => done(data));
      });
      req.on("error", () => done(null));
      req.setTimeout(timeoutMs, () => {
        req.destroy();
        done(null);
      });
    } catch (_) {
      done(null);
    }
  });
}

// Split CHANGELOG.md into entries (a `## Changelog` heading, if present, marks
// where they start — otherwise the whole document is the changelog, which is
// what CHANGELOG.md itself is). The shape this reads is the one this repo's own
// CHANGELOG.md uses and the changelog rule in CLAUDE.md mandates:
// `### v<semver> — <title> _(<date>)_`, newest first.
function parseChangelog(md) {
  if (!md) return [];
  const start = md.search(/^##\s+Changelog\s*$/m);
  const body = start === -1 ? md : md.slice(start);
  const out = [];
  // Headings only — `###` exactly, so a `####` inside an entry stays body text.
  const re = /^###\s+v(\d+\.\d+\.\d+)\s*(?:[—-]\s*)?([^\n]*?)\s*$/gm;
  const hits = [];
  let m;
  while ((m = re.exec(body))) hits.push({ version: m[1], rest: m[2] || "", at: m.index, end: re.lastIndex });
  for (let i = 0; i < hits.length; i++) {
    const h = hits[i];
    const next = hits[i + 1];
    // `_(2026-08-08)_` is the date convention; a missing one is not an error.
    const dateM = h.rest.match(/_\((\d{4}-\d{2}-\d{2})\)_/);
    out.push({
      version: h.version,
      title: h.rest.replace(/_\(\d{4}-\d{2}-\d{2}\)_/, "").trim(),
      date: dateM ? dateM[1] : null,
      // An entry ends at the next `###` — OR at the next `##`, whichever comes
      // first. A level-2 heading is a DOCUMENT section (`## Earlier releases`),
      // never part of a release, and without this cut the newest entry's body
      // carried that heading and the rule above it into the upgrade modal.
      body: body
        .slice(h.end, next ? next.at : undefined)
        .split(/\n##(?!#)\s/)[0]
        .replace(/\s*\n-{3,}\s*$/, "")
        .trim(),
    });
  }
  return out;
}

async function changelog() {
  const cur = currentVersion();
  const disabled = updateCheckDisabled();
  const md = disabled ? null : await httpsGetText(CHANGELOG_URL, 4000);
  const all = parseChangelog(md);
  // Only what you do not already have. An "upgrade" that lists the release you
  // are running is noise, and reads as though the check is broken.
  const newer = all.filter((e) => semverGt(e.version, cur));

  if (wantsJson()) {
    return emitJson({
      version: cur,
      latest: all.length ? all[0].version : null,
      update_available: !!(all.length && semverGt(all[0].version, cur)),
      entries: newer,
      source: CHANGELOG_URL,
      // Told apart on purpose: opted out, unreachable, and "nothing new" are
      // three different answers and the UI renders each differently.
      check_disabled: disabled,
      fetched: md !== null,
    });
  }

  if (disabled) return console.log("Update checks are disabled (ORC_NO_UPDATE_CHECK).");
  if (md === null) return console.log("(couldn't fetch the changelog — offline or source unreachable)");
  if (!newer.length) return console.log(`orc ${cur} — up to date. Nothing newer in the changelog.`);
  console.log(`orc ${cur} → ${newer[0].version}\n`);
  for (const e of newer) {
    console.log(`### v${e.version}${e.date ? "  (" + e.date + ")" : ""}`);
    if (e.title) console.log("  " + e.title);
    console.log("");
  }
  console.log("Run `orc upgrade` to install.");
}

// ── orc onboarding (D.2) — the "never need the GitHub README" walkthrough ────
function renderOnboardingSection(s) {
  console.log(ui.header(s.title));
  for (const line of s.lines) {
    // style a leading command token / slash command in cyan for scannability
    console.log("  " + line.replace(/(\/orc[\w-]*|orc [a-z][\w -]*?)(?=\s{2,}|$)/, (m) => ui.color.cyan(m)));
  }
}

function onboarding() {
  const pos = positionals(); // ["onboarding", <topic?>]
  const topic = pos[1];

  if (topic) {
    const s = ONBOARDING.find((x) => x.id === topic || x.id.startsWith(topic));
    if (!s) {
      console.error(
        `Unknown onboarding topic: ${topic}\n` +
          "Topics: " + ONBOARDING.map((x) => x.id).join(", ")
      );
      process.exit(1);
    }
    renderOnboardingSection(s);
    console.log("");
    return;
  }

  // Non-TTY (a model/agent, a pipe): print everything in one shot.
  if (!process.stdin.isTTY) {
    console.log(ui.color.bold("\norc onboarding — the full ORC walkthrough\n"));
    for (const s of ONBOARDING) renderOnboardingSection(s);
    console.log("\n" + ui.color.gray("Jump to one topic later with: orc onboarding <topic>"));
    return;
  }

  // TTY: a numbered section menu.
  const readline = require("readline");
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  const ask = (q) => new Promise((res) => rl.question(q, res));
  (async () => {
    for (;;) {
      console.log(ui.header("orc onboarding — pick a topic"));
      ONBOARDING.forEach((s, i) =>
        console.log(`  ${String(i + 1).padStart(2)}) ${s.title}`)
      );
      console.log("   a) show all      q) quit");
      const choice = (await ask("\n> ")).trim().toLowerCase();
      if (choice === "" || choice === "q") break;
      if (choice === "a") {
        for (const s of ONBOARDING) renderOnboardingSection(s);
        continue;
      }
      const s = ONBOARDING[Number(choice) - 1];
      if (!s) {
        console.log("  ? not a valid choice");
        continue;
      }
      renderOnboardingSection(s);
    }
    rl.close();
    console.log("done.");
  })();
}

// ── orc ui (v0.43.0) — the local web control panel ─────────────────────────
// A browser panel for everything in ORC that is NOT ai: settings, install
// health, run history, knowledge state, usage stats and the mock examples runs
// leave behind. It never runs a lane, never spawns `claude`, never calls the
// Anthropic API — that boundary is the whole design, and everything it shows or
// writes is deterministic output from THIS CLI (the server shells out to it).
//
// PROJECT-SCOPED, and deliberately so: one repo, one server, one settings file,
// exactly like `orc diy` / `orc crosslink` / `orc wiki` / `orc pattern`. There
// is no --global. `--dir` still points at ONE other project; it does not make
// the panel span several.
const UI_DEFAULT_PORT = 9921;

function uiCmd() {
  if (flag("--global")) {
    console.error(
      "❌ orc ui is project-scoped — one repo, one server, one settings file.\n" +
        "   Config does not merge: ~/.claude and <project>/.claude are two independent\n" +
        "   files, so editing both from one panel would be genuinely ambiguous.\n" +
        "   Run it from the project (or with --dir <path>). `orc doctor` reports a\n" +
        "   global install that can win skill resolution."
    );
    process.exit(1);
  }
  const claudeDir = resolveClaudeDir();
  const webui = require("./webui/serve.js");

  if (flag("--stop") === true) process.exit(webui.stop(claudeDir));

  const fixtures = flag("--fixtures") === true;
  const portRaw = flag("--port");
  const explicitPort = typeof portRaw === "string";
  const port = explicitPort ? Number(portRaw) : UI_DEFAULT_PORT;
  if (explicitPort && (!Number.isInteger(port) || port < 1 || port > 65535)) {
    console.error(`❌ --port must be a number between 1 and 65535 (got "${portRaw}").`);
    process.exit(1);
  }
  const idleRaw = flag("--idle");
  const idleMinutes = typeof idleRaw === "string" ? Number(idleRaw) : webui.DEFAULT_IDLE_MIN;
  if (!Number.isFinite(idleMinutes) || idleMinutes < 0) {
    console.error(`❌ --idle must be minutes >= 0 (0 disables the timeout).`);
    process.exit(1);
  }

  // Fixture mode needs no project at all — that is half its point.
  if (!fixtures && !fs.existsSync(path.join(claudeDir, "hooks")))
    console.error(
      "  ⚠ no ORC payload here yet (run `orc init`). The panel will open, but most\n" +
        "    of it will read empty. `orc ui --fixtures` shows it with canned data."
    );

  webui
    .serve({
      claudeDir,
      projectRoot: repoRootOf(claudeDir),
      port,
      explicitPort,
      open: flag("--no-open") !== true,
      idleMinutes,
      fixtures,
      version: currentVersion(),
    })
    .then((code) => {
      if (typeof code === "number") process.exit(code);
    })
    .catch((e) => {
      console.error("❌ orc ui failed to start: " + (e && e.message));
      process.exit(1);
    });
}

function help() {
  console.log(`orc — install the ORC Claude Code skill constellation

New? Run \`orc onboarding\` for the full walkthrough (no GitHub README needed).

Usage:
  orc init [--global | --dir <path>]      copy skills + commands (skips existing)
  orc update [--global | --dir <path>]    overwrite existing orc files (local copy only)
                                          [--prune]  also delete ORC-named orphans from a
                                                     pre-manifest install (renamed/removed files)
  orc upgrade [--global | --dir <path>]   fetch the LATEST package, then apply it
                                          [--from <spec>]  (default order: last-good,
                                          then the tarball, then ${GITHUB_SPEC})
  orc config [--global | --dir <path>]    view/change settings (interactive menu)
    orc config list                       print effective config (default vs override)
    orc config set <key> <value>          validate + write one setting
    orc config reset [key]                revert one key (or all) to defaults
    orc config path                       print the override file location
    orc config profile [<name>]           apply a coherent bundle over the existing keys
                                          (solo-fast, balanced, paranoid, token-lean);
                                          no name = list them with what each is for
    orc config recommend                  read-only: probe this repo (tests? CI? size?
                                          wiki? monorepo?) and suggest ONE profile, with
                                          the reasons it decided from
  orc lane list                           every lane, its command, and how many keys it reads
    orc lane config <lane>                ONE resolver for that lane: effective values, the
                                          family ranks with their state, announce[], stops[],
                                          the fixed roles, and what it does NOT read
                                          (exit 0 in every state; 2 unknown lane)

  orc diy [--dir <path>]                  compose your own flow — INTERACTIVE menu (project-scoped; no --global)
    orc diy init [--preset <name>]        create the flow config (presets: lean, paranoid, solo-fast)
    orc diy set <key> <value>             change one flow key (requires recompile)
    orc diy show | validate | status      inspect the flow + gate state
    orc diy compile                       build the runnable flow for /orc-diy
    orc diy reset                         delete the flow (back to UNCONFIGURED)
  orc crosslink [--dir <path>]            compose cross-repo wiki links — INTERACTIVE (project-scoped; no --global)
    orc crosslink list | status           inspect the graph + per-repo freshness (read-only)
    orc crosslink remove <name>           drop a linked repo and its edges
  orc wiki [--dir <path>]                 registration state of the wiki (project-scoped; no --global)
    orc wiki status [--json]              registration state + COMPUTED freshness tier — a doc is
                                          stale only when its OWN covered files changed; edges from
                                          config wiki_fresh_max / wiki_aging_max
    orc wiki sync [--check]               rebuild wiki-meta.json + INDEX.md from the docs on disk
                                          (instant, no re-scan — this is the repair for an
                                           unregistered wiki, e.g. a scan stopped at a pause)
    orc wiki impact                       commit-scoped delta probe — per registered doc
                                          CLEAN | TOUCHED (n) | STRUCTURAL vs scan_commit
                                          (exit 0 clean / 1 can't compute / 2 delta / 3 full)
    orc wiki plan [--json]                RANKED, priced work list: what to refresh, in what
                                          order, for how much. STRUCTURAL first, then use×delta,
                                          zero-use docs last with a retire hint. Free repairs are
                                          always listed BEFORE anything that costs money
                                          (exit 0 nothing / 1 all light / 2 a deep scan / 3 n/a)
    orc wiki debt [--json]                one line: docs pending, tokens, \$, oldest debt
                                          (exit 0 no debt / 1 debt exists / 3 no wiki)
    orc wiki usage [--rebuild] [--json]   which docs runs actually put into a slice, from the
                                          trace corpus — the input to plan's ranking
  orc pact [--dir <path>]                 the invariant ledger — the promises this project makes,
                                          and which ones are in doubt right now
    orc pact status [--json]              HOLDING | DRIFTED | UNCHECKABLE | BROKEN, all COMPUTED
                                          (exit 0 all holding / 1 any drifted / 2 any broken /
                                           3 no ledger). UNCHECKABLE never raises the code
    orc pact check [<id>]                 run the cheap checks and re-anchor what passes
    orc pact sync                         re-render the derived PACT.md from the ledger
  orc boundary [--dir <path>]             execute · escalate · refuse, per AREA
    orc boundary status [<path>] [--json] (exit 0 all EXECUTE / 1 any ESCALATE / 2 any REFUSE /
                                          3 no card or a stale card). A REFUSE always names what
                                          would make it a yes
  orc handoff [--dir <path>]              what a non-developer can safely change
    orc handoff surfaces [--json]         the graded map: 🟢 a check will catch a mistake ·
                                          🟡 the check is manual · 🔴 ORC will not touch it
    orc handoff set <id> <key> <value>    change one value on a GREEN/AMBER surface. Prints the
                                          undo command BEFORE the write; never stages, never commits
  orc budget [--dir <path>]               what a run costs, in the unit YOU are billed in
    orc budget forecast <plan> [--as …]   tokens (in/cache-w/cache-r/out) · usd · quota · context
                                          risk, per band, as a RANGE with a sample count
                                          (exit 0 / 1 a low-confidence band / 2 context risk /
                                           3 no history). [--naive] = price table only
    orc budget actual <run-slug>          what the run really cost, vs the rate model
    orc budget rates [--json]             what the corpus says per band, in tokens
    orc budget calibrate                  rebuild the model from traces + local transcripts
  orc aftermath [--dir <path>]            did the thing we shipped hold up (read-only, no telemetry)
    orc aftermath status [--since Nd]     churn · a deleted test · a revert · a broken promise
                                          (exit 0 clean / 1 churn / 2 a revert / 3 too shallow).
                                          Churn is a SIGNAL, never a verdict
  orc extra [--dir <path>]                dispatch ORC's WORKERS to non-Claude agents — DeepSeek,
                                          GLM, Kimi, MiniMax, Qwen, MiMo, a local Ollama, or any
                                          endpoint you can name. The orchestrator stays Claude;
                                          what changes is who executes a slice. Nothing happens
                                          until \`extra_enabled\` is true (project-scoped; no --global)
    orc extra providers [--json]          the shipped, DATED catalog. Providers, never models —
                                          a shipped model list is wrong within a quarter
    orc extra add <name> --provider <id> --engine <api|claude-shim|cli>
                                          [--env-key NAME | --key-stdin] [--region <id>]
                                          [--base-url URL] [--anthropic-base-url URL]
                                          An env-var NAME is the recommended credential; a pasted
                                          key goes to an encrypted vault. \`--key <value>\` is
                                          refused — argv is world-readable
    orc extra list | show <name> [--json] profiles + state, NEVER a secret
    orc extra remove <name> --reason "…"  a reason is required; it names the routes it drops
    orc extra ping <name> [--deep] [--model <id>] [--key-stdin] [--json]
                                          THE CONNECTION GATE. Cheapest rung first, and the
                                          profile records WHICH rung answered
                                          (exit 0 verified / 1 unreachable / 2 unknown profile)
    orc extra models <name> [--json]      cached from the last ping; never invented
    orc extra unlock | rekey <name>       the vault. The key is never printed, and ten wrong
                                          passphrases delete it on purpose
    orc extra route [--json]              the band table AND the Claude fall-through — a gap is
                                          not a hole, it is Claude, and it keeps its slot
    orc extra route set <from>-<to> <profile>/<model> [--max-turns N]
    orc extra route rm <from>-<to>
    orc extra role [--json]               the six POSITIONS - the non-scored half of routing,
                                          for the lanes that pin an agent instead of scoring a
                                          task (exit 0 any routes / 1 none)
    orc extra role set <slot> <profile>/<model> [--small-model <id>] [--max-turns N]
    orc extra role rm | show <slot>
    orc extra resolve <score> [--role <r>] [--risk N] [--json]
    orc extra resolve --slot <slot> [--risk N] [--json]
                                          THE resolver — the ONLY thing that decides whether a
                                          task goes foreign (exit 0 extra / 1 claude). It always
                                          says WHY. A score resolves a BAND; --slot resolves a
                                          POSITION; both together is refused by name
    orc extra doctor [--json]             (exit 0 clean / 1 findings)
  orc challenge [--dir <path>]            grade a FINISHED artifact against a goal you stated —
                                          ORC judges, you fix, ORC re-judges, and it never fixes
                                          what it judged (project-scoped; no --global)
    orc challenge list [--json]           every cycle + its COMPUTED state
                                          (exit 0 all passed / 1 any in-flight / 3 no cycles)
    orc challenge status <slug> [--json]  one cycle (exit 0 passed / 1 open blocking findings /
                                          2 a P0 is open / 3 unknown slug)
    orc challenge show <slug> [--iteration N]   full detail incl. every finding
    orc challenge diff <slug>             resolve the expected revision, then per-finding
                                          touched/untouched (exit 0 unchanged / 1 changed /
                                          2 MISSING-REVISION / 3 unknown). A HINT for you —
                                          never an input to the judge, which always re-reads
    orc challenge expect <slug> [--set <path>]  where the next revision is expected; --set
                                          records a deviation instead of ORC guessing one
    orc challenge lint <path> [--template <p>]  deterministic prose + structure lint, ZERO model
                                          tokens (exit 0 clean / 1 findings / 2 unreadable).
                                          Useful with no cycle and no model at all
    orc challenge outline <path>          the heading tree
    orc challenge record <slug> --iteration N --from <json>
                                          THE GATE: rejects coverage < 100%, an unknown carry id,
                                          an ignored rebuttal and a silent dimension; drops a
                                          finding with no \`serves\`; and COMPUTES pass/fail
    orc challenge accept <slug> <id> "reason"   accept a known gap — it stops blocking and stays
                                          visible forever with your reason
    orc challenge rebut <slug> <id> "reason"    the judge is wrong; the next verdict must answer it
    orc challenge template|goals <slug> [--set <path> --reason "…"]
                                          print the frozen yardstick, or re-freeze it (a recorded
                                          event; prior iterations keep their stamp)
    orc challenge report <slug>           re-derive CHALLENGE.md (+ the final report on a pass)
    orc challenge init <slug> --artifact <p> --kind <k> --goal … --audience … --done-means …
                                          [--out-of-scope …] [--context-ref …]
                                          (--template <p> | --no-template) [--dimensions D1,D2,…]
                                          [--revision in-place|new-file|directory --revision-pattern …]
                                          --goal/--audience/--done-means have NO default: ORC never
                                          guesses what "good" means here
  orc doc [--dir <path>]                  write a long document — PRD · TSD · collaboration
                                          agreement · report · workflow — as portable Markdown
                                          (project-scoped; no --global). The orchestrator never
                                          reads the document body; it reads the map below
    orc doc list [--json]                 every document + its \`Where it stands:\` line
    orc doc status <slug> [--json]        one document (exit 0 complete / 1 in progress /
                                          2 unknown slug). A prefix is enough for <slug>
    orc doc show <slug> [--json]          full state: outline, sections, cycles, extracts
      … --section <id>                    ONE section's text, on an explicit request — the only
                                          command that returns any of the document's prose
    orc doc map <slug> [--json]           THE SECTION MAP — heading, absolute line range, hash and
                                          computed state per section. Derived on every read and
                                          NEVER stored: a stored line number is a wrong line number
                                          one edit later
    orc doc parts <slug> [--json]         THE SECTION FILES — one row per section (and per stored
                                          sub-part), with its computed state. Works BEFORE a single
                                          compile has ever run, because the files ARE the progress
      … --confirm <id,id>                 record a VALIDATED RETURN's hash. Until then a file on
                                          disk is \`unconfirmed\`: a wave killed by a usage limit
                                          leaves exactly that, and it is re-written, never shipped
    orc doc compile <slug> [--partial]    sections/ → document.md. ZERO model tokens, on demand.
                                          --partial writes what exists and NAMES what is missing;
                                          nothing is ever stubbed into the deliverable
      … --strip-annotations               remove ORC's own markers, on your explicit request only
    orc doc split <slug>                  document.md → sections/ (also free). Recovers a document
                                          a human reshaped by hand
      … --section <id> --by-heading       store ONE big section as sub-parts, cut on its own
                                          \`###\` headings. Invisible to the reader and to the map
    orc doc migrate <slug> [--clean]      v1 → v2. Lazy, idempotent, non-destructive: document.md
                                          is never deleted, and an unparseable one is REFUSED
    orc doc mode <slug> [--set partial|all]
                                          how much of the document is bought at once. \`partial\`
                                          writes ONE wave and stops so you can redirect
    orc doc plan <slug> --role write|check|edit [--only <ids>]
                                          the batching: never splits a section, never exceeds
                                          doc_max_parallel (hard cap 2) or the per-agent line
                                          budget (exit 0 work to do / 1 nothing to do). ONE FILE
                                          PER SECTION — never one file for a two-section slice
    orc doc outline <slug> [--set <path>] the agreed section list; --set adopts another file's
                                          headings (a structure is never guessed out of prose) and
                                          RENAMES the files on disk in the same step
    orc doc extract <slug> --section <id> alias. In v2 the section file IS the extract, so nothing
                                          is copied — it prints the path and records the hash
    orc doc splice <slug>                 alias → compile. A v1-era pending part is drained first,
                                          hash-guarded (exit 1 = a section changed on disk and
                                          nothing was overwritten)
    orc doc assemble <slug>               alias → compile
    orc doc lint <slug|path> [--target <t>]
                                          the FREE check: portability rules from a real product
                                          limit, plus readability signals (exit 0 clean /
                                          1 findings / 2 unreadable). Zero model tokens
      … --section <id>                    lint ONE section file and report PART-LOCAL line
                                          numbers — the lines the writer actually opens
    orc doc resume-file <slug> [--json]   write RESUME.md now - the plain-English hand-back with
                                          the one line to paste into a new session. It is also
                                          rewritten automatically on every state change
    orc doc rules [--json]                the PROJECT's own house rules — a PLAIN TEXT config at
                                          .claude/orc/doc-house-rules.md with three headings,
                                          P0/P1/P2, and as much text under each as you want. They
                                          govern what a document SAYS and how it READS, and can
                                          never change how this lane RUNS
                                          (exit 0 = rules exist / 1 = none yet)
      orc doc rules set --priority P0|P1|P2 --text "…"
                                          replace ONE block. Multi-line is fine — that is the point
      orc doc rules add --priority P0 --text "…"
                                          append to a block instead of replacing it
      orc doc rules clear --priority P0   empty ONE block
      orc doc rules set-all --text "…"    replace the WHOLE file (what orc ui writes)
      orc doc rules <slug> [--json]       the text FROZEN into one document, and every block that
                                          moved since (exit 1 = the ledger drifted)
      orc doc rules <slug> --sync         re-freeze deliberately; NAMES the sections that predate
                                          the change and re-writes nothing
      orc doc rules --set-file <path> | --reset
    orc doc forecast <slug> [--json]      the run map, BEFORE the first paid wave: waves, agents,
                                          stops, and a token range with a sample count. No history
                                          → it refuses rather than invent (exit 0 / 1 low
                                          confidence / 3 no history)  [--naive] [--as tokens|usd|quota|all]
    orc doc cost <slug> [--json]          what this document actually cost, joined across EVERY
                                          session it spanned — per role and per section. A section
                                          nothing joins reads — , never 0 (exit 0 joined /
                                          1 partly / 3 no trace)
    orc doc templates [--json]            the five base templates + their section lists
    orc doc targets [--json]              where a Markdown file can actually go, and what to watch
    orc doc init <slug> --type <t> [--template <p>] [--title …] [--language …]
                                          [--target <t>] [--length short|standard|thorough]
                                          a SUPPLIED --template is a P0 CAGE by default: a heading
                                          it never had is a lint error and \`parts --confirm\`
                                          refuses it. --template-soft opts out
  orc export [--dir <path>]               compile the wiki + patterns + PACT.md + boundary cards
                                          into a portable AGENTS.md — derived, fingerprinted
                                          [--target agents-md|skill|both]
                                          [--check]  fail when the export is stale (exit 1)
    orc export import                     read an existing AGENTS.md/.cursorrules as EVIDENCE and
                                          propose ORC config + pact seeds (never applies anything)
  orc pattern [--dir <path>]              cached code-patterns (project-scoped; no --global)
    orc pattern status [<lang>]           whether a cached pattern exists — the deterministic
                                          existence probe every knowledge-gated lane runs first
                                          (exit 1 when <lang> absent; no arg lists all cached)
  orc gotcha [--dir <path>]               repair memory — what this project already got wrong
                                          (project-scoped; no --global)
    orc gotcha status | list              whether any live entry exists — the deterministic probe
                                          (exit 0 = entries, 1 = none); list also prints them
    orc gotcha prune                      archive the low-value tail (fewest hits, then oldest)
                                          down to gotchas_max → gotchas-archive.md; never deletes
  orc mock [--dir <path>]                 mocked runnable examples left by a green verify
                                          (project-scoped; no --global) — read-only, never runs one
    orc mock list [--json]                every mock-examples/<slug>/, newest first
    orc mock show <slug> [--json]         EXAMPLE.md + the file tree for one example
  orc mock-run                            MOCKED RUNS — a written walkthrough per lane: what you
                                          type, what ORC prints, what lands on disk. Ships with
                                          the package, so it needs no project (a different thing
                                          from orc mock above)
    orc mock-run list [--json]            every walkthrough, grouped in reading order
    orc mock-run show <slug> [--json]     read one (also: orc mock-run <slug>)
  orc pr [--dir <path>]                   stacked pull requests (project-scoped; no --global)
    orc pr stack template [<slug>]        write a fill-in stack-plan skeleton to
                                          stacked-pr/<slug>/stack-plan.md — fill it in and start
                                          straight at /orc-pr-driver (no planner run needed)
    orc pr stack status [<slug>]          is a stack plan READY? (exit 0 ready /
                                          1 absent-or-unfilled) — the probe the driver runs first
                                          (aliases: orc pr-stack-template, orc pr-stack-status)
  orc resume [<n>|<slug>]                 runs waiting for you — numbered list, pick one, and it
                                          prints (and copies) the paste-into-a-fresh-session prompt
                                          (exit 0 = something is waiting, 1 = nothing is)
                                          [--no-clipboard]  print only, never touch the clipboard
  orc run list [--all|--limit <n>]        every run, newest first, with status
                                          waiting | closed | done | empty  [--json]
    orc run show <slug|n>                 one run: state-of-play, resume prompt, checkpoint
    orc run close <slug|n>                you are finished with a run that never reached FINISH:
      --reason "<why>"                    moves RESUME.md aside (never deletes it) and records why,
                                          so it stops counting as waiting  [--json]
    orc run reopen <slug|n>               put it back — it is waiting again  [--json]
  orc stats [--since YYYY-MM-DD] [--json] how much you actually use each lane and agent, counted
                                          from the trace filenames — no model, instant, free
  orc wait                                the deterministic half of /orc-wait — a wait costs zero
                                          tokens, because a detached command does it, not a model
    orc wait lanes [--json]               which lanes support a wait, what each one checkpoints,
                                          and where its safe point is
    orc wait plan <spec> [--json]         turn 30 · 90m · 2h · until 18:41 · reset into hops
      [--hop <min>] [--max-hops <n>]      (exit 0 planned / 1 unparsable / 2 no usage reading)
  orc onboarding [<topic>]                guided walkthrough (menu on a TTY; prints all when piped)
                                          topics: overview, install, first-run, lanes,
                                          config, knowledge, upgrade, troubleshooting
  orc where [--global | --dir <path>]     show target paths
  orc doctor [--global | --dir <path>]    read-only health report: version skew, orphaned/missing
                                          payload files, settings.json wiring, trace pointer, diy lock
    orc doctor --fix                      apply the fixes (= update + prune + settings re-merge)
    orc doctor --json                     the same findings as ONE JSON object on stdout (no banner,
                                          no colour) — same exit code as the human report (0/1)
  orc ui [--dir <path>]                   local web control panel for everything in ORC that is
                                          NOT ai — settings, health, runs, knowledge, stats, mock
                                          examples. Binds 127.0.0.1:${UI_DEFAULT_PORT} and opens a browser.
                                          It never runs a lane and never calls a model.
                                          [--port <n>]   pick the port (no auto-walk when explicit)
                                          [--no-open]    print the URL instead of opening it
                                          [--idle <min>] shut down after N idle minutes (0 = never)
                                          [--fixtures]   canned data, no project needed
                                          [--stop]       stop this project's server (exit 0 stopped
                                                         / 1 nothing was running)
  orc version                             print installed version + check for a newer one
  orc changelog                           what you would GET by upgrading (entries newer than yours)
  orc --help

Machine-readable output:
  --json is accepted by config list | config profile | config recommend | where |
  version | changelog | doctor | wiki status | wiki impact | wiki plan | wiki debt |
  wiki usage | pattern status | gotcha list | crosslink list | crosslink status |
  crosslink kinds | diy show | diy status | run list | run show | stats |
  pr stack status | mock list | mock show | mock-run list | mock-run show |
  pact status | pact check |
  boundary status | handoff surfaces | handoff set | budget forecast |
  budget actual | budget rates | aftermath status | export [--check] | export import |
  challenge list | challenge status | challenge show | challenge diff | challenge expect |
  challenge lint | challenge outline | challenge record | challenge report |
  doc list | doc status | doc show | doc map | doc plan | doc outline | doc lint |
  doc templates | doc targets |
  extra providers | extra list | extra show | extra ping | extra models |
  extra route | extra resolve | extra doctor.
  It prints ONE object to stdout and keeps the command's normal exit code.

Targets:
  (default)      ./.claude            current project
  --global       ~/.claude            all projects
  --dir <path>   <path>/.claude       a specific project

update vs upgrade:
  update   re-copies the templates already installed in this package (offline).
  upgrade  refreshes the package from the source first (network), THEN copies —
           this is what actually pulls a new version. Your .claude/orc.config.yaml
           overrides survive either way.

Skills installed: ${listSkillNames().join(", ")}`);
}

// ── `orc wait` (v1.1.0 W1) ──────────────────────────────────────────────────
// The deterministic half of `/orc-wait`. The skill never does this arithmetic
// itself: a pipeline the model recomputes is a pipeline that drifts (the
// `orc doc next` / Flow-stepper rule). Canonical prose is
// `templates/skills/_shared/wait.md`, and WAIT_LANE_SHAPES below is the
// machine-readable copy of its `## Which lanes support a wait` table — a golden
// test compares the two IN BOTH DIRECTIONS, the EXTRA_LANE_SHAPES precedent.
//
// `checkpoint: "none"` is an ANSWER, not a gap: a single-dispatch lane has
// nothing to checkpoint, so all three modes collapse to the same plain wait
// there and this table says so rather than omitting the row.
const WAIT_LANE_SHAPES = [
  { lane: "/orc", checkpoint: "full", safe_point: "wave or phase edge" },
  { lane: "/orc-ultra", checkpoint: "full", safe_point: "wave or judge gate" },
  { lane: "/orc-mini", checkpoint: "full", safe_point: "after the executor returns" },
  { lane: "/orc-fast", checkpoint: "full", safe_point: "after the executor returns" },
  { lane: "/orc-diy", checkpoint: "full", safe_point: "compiled phase edge" },
  { lane: "/orc-doc", checkpoint: "full", safe_point: "wave edge" },
  { lane: "/orc-wiki", checkpoint: "full", safe_point: "scan-task boundary" },
  { lane: "/orc-analyze", checkpoint: "full", safe_point: "after the analyst returns" },
  { lane: "/orc-poly", checkpoint: "docset", safe_point: "after a per-repo plan is written" },
  { lane: "/orc-quick", checkpoint: "entry", safe_point: "after an entry closes" },
  { lane: "/orc-challenge", checkpoint: "cycle", safe_point: "after a cycle records" },
  { lane: "/orc-brainstorm", checkpoint: "snapshot", safe_point: "phase edge" },
  { lane: "/orc-grill", checkpoint: "snapshot", safe_point: "round edge" },
  { lane: "/orc-learn", checkpoint: "none", safe_point: "single dispatch" },
  { lane: "/orc-plan", checkpoint: "none", safe_point: "single dispatch" },
  { lane: "/orc-verify", checkpoint: "none", safe_point: "single dispatch" },
  { lane: "/orc-pattern", checkpoint: "none", safe_point: "single dispatch" },
  { lane: "/orc-claude", checkpoint: "none", safe_point: "single dispatch" },
  { lane: "/orc-explain", checkpoint: "none", safe_point: "read-only, seconds long" },
  { lane: "/orc-route", checkpoint: "none", safe_point: "read-only, seconds long" },
  { lane: "/orc-boundary", checkpoint: "none", safe_point: "read-only, seconds long" },
  { lane: "/orc-budget", checkpoint: "none", safe_point: "read-only, seconds long" },
  { lane: "/orc-aftermath", checkpoint: "none", safe_point: "read-only, seconds long" },
  { lane: "/orc-export", checkpoint: "none", safe_point: "read-only, seconds long" },
  { lane: "/orc-retro", checkpoint: "none", safe_point: "read-only, seconds long" },
  { lane: "/orc-pact", checkpoint: "none", safe_point: "read-only, seconds long" },
];
const WAIT_MODES = ["safe", "soft", "hard"];
const WAIT_CHECKPOINTS = ["full", "docset", "entry", "cycle", "snapshot", "none"];
const WAIT_HOP_DEFAULT_MIN = 30;
const WAIT_MAX_HOPS_DEFAULT = 5;
// The same freshness window the effort guard already uses for the session-model
// bridge. A reading older than this is `unknown`, and unknown never blocks.
const WAIT_BRIDGE_MAX_AGE_MS = 30 * 60 * 1000;

// The reader half of the statusline usage bridge. The WRITER lands in W4; until
// then every caller correctly reports `unknown`, which is the honest answer and
// never a stop. Unknown is not zero.
function readUsageBridge(claudeDir, now) {
  const t = typeof now === "number" ? now : Date.now();
  const file = path.join(claudeDir, "orc", "usage.json");
  try {
    const j = JSON.parse(fs.readFileSync(file, "utf8"));
    if (!j || typeof j.written_at !== "number") return null;
    if (t - j.written_at > WAIT_BRIDGE_MAX_AGE_MS) return null;
    return j;
  } catch (_) {
    return null;
  }
}

// `30` `90m` `2h` `2h30m` `until 18:41` `reset` → minutes.
// Returns { ok, kind, minutes, ... } or { ok:false, reason }.
function waitParseSpec(spec, now) {
  const t = typeof now === "number" ? now : Date.now();
  const s = String(spec == null ? "" : spec).trim().toLowerCase().replace(/\s+/g, " ");
  if (!s) return { ok: false, reason: "empty", hint: "say how long. Example: orc wait plan 30" };
  if (s === "reset") return { ok: true, kind: "reset", minutes: null };
  let m = /^until (\d{1,2}):(\d{2})$/.exec(s);
  if (m) {
    const hh = Number(m[1]);
    const mm = Number(m[2]);
    if (hh > 23 || mm > 59)
      return { ok: false, reason: "bad-time", hint: `${m[1]}:${m[2]} is not a time of day` };
    const d = new Date(t);
    const target = new Date(d.getFullYear(), d.getMonth(), d.getDate(), hh, mm, 0, 0);
    // A time already past today means the next one — never a negative wait.
    if (target.getTime() <= t) target.setDate(target.getDate() + 1);
    return {
      ok: true,
      kind: "until",
      minutes: Math.max(1, Math.round((target.getTime() - t) / 60000)),
      until: target.toISOString(),
    };
  }
  m = /^(\d+) ?h(?: ?(\d+) ?m?)?$/.exec(s);
  if (m) {
    const mins = Number(m[1]) * 60 + Number(m[2] || 0);
    return mins > 0
      ? { ok: true, kind: "duration", minutes: mins }
      : { ok: false, reason: "zero", hint: "a wait of zero is not a wait" };
  }
  m = /^(\d+) ?m$/.exec(s) || /^(\d+)$/.exec(s);
  if (m) {
    const mins = Number(m[1]);
    return mins > 0
      ? { ok: true, kind: "duration", minutes: mins }
      : { ok: false, reason: "zero", hint: "a wait of zero is not a wait" };
  }
  return {
    ok: false,
    reason: "unparsable",
    hint: "use 30 · 90m · 2h · 2h30m · until 18:41 · reset",
  };
}

// The LAST hop is the remainder, never a full hop. A wait that overshoots its
// own reset time has waited for nothing.
function waitHops(totalMinutes, hopMinutes, maxHops) {
  const hop = Math.max(1, Number(hopMinutes) || WAIT_HOP_DEFAULT_MIN);
  const cap = Math.max(1, Number(maxHops) || WAIT_MAX_HOPS_DEFAULT);
  const hops = [];
  let left = Math.max(0, Math.round(Number(totalMinutes) || 0));
  while (left > 0 && hops.length < cap) {
    const h = Math.min(hop, left);
    hops.push(h);
    left -= h;
  }
  return { hops, uncovered_minutes: left, truncated: left > 0 };
}

function waitPlanCmd(claudeDir) {
  const asJson = wantsJson();
  const pos = positionals().slice(2);
  const spec = pos.join(" ");
  const now = Date.now();
  const cfg = resolvedConfig(claudeDir);
  const hopMin = Number(flag("--hop")) || Number(cfg.wait_hop_minutes) || WAIT_HOP_DEFAULT_MIN;
  const maxHops = Number(flag("--max-hops")) || Number(cfg.wait_max_hops) || WAIT_MAX_HOPS_DEFAULT;

  const parsed = waitParseSpec(spec, now);
  if (!parsed.ok) {
    if (asJson) emitJson({ ok: false, reason: parsed.reason, spec, hint: parsed.hint }, 1);
    console.error(ui.mark.err(`I cannot read "${spec}" as a wait.`));
    console.error("  " + parsed.hint);
    process.exit(1);
  }

  let minutes = parsed.minutes;
  let source = parsed.kind;
  let reading = null;
  if (parsed.kind === "reset") {
    reading = readUsageBridge(claudeDir, now);
    const resets = reading && reading.five_hour && reading.five_hour.resets_at;
    const at = resets == null ? NaN : Number(resets) < 1e12 ? Number(resets) * 1000 : Number(resets);
    if (!Number.isFinite(at) || at <= now) {
      const why = reading
        ? "the reading has no usable reset time"
        : "there is no reading in the last 30 minutes";
      if (asJson)
        emitJson(
          { ok: false, reason: "no-reading", spec, hint: `${why}. Type a time instead. Example: orc wait plan 45` },
          2
        );
      console.error(ui.mark.err("I cannot read the reset time."));
      console.error("  " + why + ".");
      console.error("  Type a time instead. Example: " + ui.color.cyan("orc wait plan 45"));
      process.exit(2);
    }
    minutes = Math.max(1, Math.round((at - now) / 60000));
    source = "reset";
  }

  const h = waitHops(minutes, hopMin, maxHops);
  const endsAt = new Date(now + minutes * 60000);
  const out = {
    ok: true,
    spec,
    source,
    minutes,
    hop_minutes: hopMin,
    max_hops: maxHops,
    hops: h.hops,
    hop_count: h.hops.length,
    uncovered_minutes: h.uncovered_minutes,
    truncated: h.truncated,
    ends_at: endsAt.toISOString(),
    // A wait longer than the prompt cache TTL re-reads the whole context on the
    // next turn, at full input price. The caller must be able to say so.
    crosses_cache_ttl: minutes > 60,
    modes: WAIT_MODES,
    note: "A detached command does the waiting. No model runs, and no tokens are spent.",
  };
  if (asJson) emitJson(out, 0);

  console.log(ui.header("ORC · wait — the plan"));
  console.log("");
  console.log(`  ${ui.color.cyan("length")}    ${minutes} min  (from ${source})`);
  console.log(`  ${ui.color.cyan("ends at")}   ${endsAt.toTimeString().slice(0, 5)}`);
  console.log(`  ${ui.color.cyan("hops")}      ${h.hops.join(" + ")}  (${h.hops.length} of ${maxHops} max)`);
  if (h.truncated)
    console.log(
      ui.mark.warn(`  ${h.uncovered_minutes} min are NOT covered — wait_max_hops is ${maxHops}.`)
    );
  if (out.crosses_cache_ttl)
    console.log(
      ui.color.gray(
        "  Longer than one hour: the prompt cache expires, so the next turn re-reads\n" +
          "  your whole context at full input price. A fresh session is cheaper."
      )
    );
  console.log(ui.color.gray("\n  " + out.note + "\n"));
}

function waitLanesCmd() {
  const asJson = wantsJson();
  const lanes = WAIT_LANE_SHAPES.map((row) => {
    const plain = row.checkpoint === "none";
    return {
      lane: row.lane,
      checkpoint: row.checkpoint,
      safe_point: row.safe_point,
      // On a lane with nothing to checkpoint the three modes ARE the same
      // thing. Saying so is the point; pretending to a distinction is not.
      modes: WAIT_MODES,
      modes_differ: !plain,
      detail: plain
        ? "nothing to checkpoint — one dispatch, or a read. safe, soft and hard behave identically here."
        : `soft forces the ${row.checkpoint} checkpoint before it stops; hard writes RESUME.md only and can lose an in-flight return.`,
    };
  });
  if (asJson)
    emitJson(
      {
        ok: true,
        modes: WAIT_MODES,
        checkpoints: WAIT_CHECKPOINTS,
        lanes,
        note: "A lane not in this list does not support a wait.",
      },
      0
    );

  console.log(ui.header("ORC · wait — which lanes support a wait, and what they save"));
  console.log("");
  for (const l of lanes) {
    // Pad the PLAIN text, then colour it — an ANSI escape has width 0 on screen
    // and width 5+ to padEnd, so colouring first mis-aligns every row.
    const cp = l.checkpoint.padEnd(9);
    const mark = l.modes_differ ? ui.color.cyan(cp) : ui.color.gray(cp);
    console.log(`  ${ui.color.cyan(l.lane.padEnd(17))} ${mark}  ${l.safe_point}`);
    console.log("      " + ui.color.gray(l.detail));
  }
  console.log(ui.color.gray("\n  A lane not listed here does not support a wait.\n"));
}

// ── `orc usage check` (v1.1.0 W4) ───────────────────────────────────────────
// THE one reader of the statusline's usage bridge. No skill reads that file, so
// the threshold and the freshness rule exist in exactly one place.
//
// Exit codes are the contract, and the third one carries the whole design:
//   0 ok       — enough quota. Continue.
//   1 low      — at or below usage_stop_pct on the WORST window.
//   2 unknown  — no reading, or one older than the freshness window.
//
// UNKNOWN IS NOT LOW, and it never stops a run. An absent number is an absent
// number: older Claude Code, no headers, or simply no statusline render since
// the last dispatch. A gate that blocks on a missing reading is a gate people
// switch off.
function usageResetMs(v) {
  if (v == null) return NaN;
  const n = Number(v);
  if (Number.isFinite(n)) return n < 1e12 ? n * 1000 : n;
  const p = Date.parse(String(v));
  return Number.isFinite(p) ? p : NaN;
}

// ── `orc usage report` — where the window went (v1.2.0) ─────────────────────
//
// `orc usage check` answers "is there room". This answers the question a user
// actually asks mid-run: "how much has THIS session eaten, and what ate it".
//
// THE HONEST PART, and it decides the whole shape of this command. Claude Code
// records NO token usage for a dispatched subagent — `isSidechain` is never set
// and no sidechain message carries a usage block, in any transcript on disk. So
// a per-executor TOKEN figure cannot be measured, and inventing one would be
// the same class of bug as a fake validator. What IS measured, exactly, is WALL
// TIME, from the trace hook's own SPAWN/RETURN lines. Foreign workers are the
// one exception: `orc extra` records real four-kind vectors, so those rows
// carry tokens and say so. Every other row reports `tokens: null` plus the
// reason — never 0. Unknown is not zero.
const USAGE_TOP_N = 5;

// "12m43s" | "1m7s" | "45s" → seconds. Anything else → null, never 0.
function usageDurSeconds(s) {
  if (!s) return null;
  const m = /^(?:(\d+)m)?(\d+)s$/.exec(String(s).trim());
  if (!m) return null;
  return (m[1] ? Number(m[1]) * 60 : 0) + Number(m[2]);
}

// Per-agent wall time for the run the trace pointer names. Returns null when
// there is no open run — an absent trace is an absent measurement, not zero.
function usageRunConsumers(claudeDir) {
  const dir = resolveLogDir(claudeDir);
  let cur = null;
  try {
    cur = fs.readFileSync(path.join(dir, ".current"), "utf8").trim();
  } catch (_) {}
  if (!cur) return null;
  let text = "";
  try {
    text = fs.readFileSync(path.join(dir, cur), "utf8");
  } catch (_) {
    return null;
  }
  const nameMatch = TRACE_NAME.exec(cur);
  const by = new Map();
  const bump = (agent, secs, running) => {
    const k = agent || "(unnamed)";
    const r = by.get(k) || { agent: k, dispatches: 0, wall_seconds: 0, running: 0, unmeasured: 0 };
    r.dispatches += 1;
    if (running) r.running += 1;
    if (secs == null) r.unmeasured += 1;
    else r.wall_seconds += secs;
    by.set(k, r);
  };
  for (const line of text.split("\n")) {
    // Only the hook's own skeleton lines. `~agent :: unattributed` is a
    // bookkeeping artefact of >=2 in flight and is never a dispatch.
    const r = /\] hook\s+RETURN ~?([^\s:]+) :: /.exec(line);
    if (!r) continue;
    if (r[1] === "agent") continue;
    const d = /\bdur=(\S+)/.exec(line);
    bump(r[1], usageDurSeconds(d && d[1]), false);
  }
  // Anything still open is real spend happening RIGHT NOW — the exact case the
  // v1.2.0 in-flight guard exists for, and the one a user most wants to see.
  let pending = [];
  try {
    const raw = JSON.parse(fs.readFileSync(path.join(dir, cur + ".pending.json"), "utf8"));
    if (Array.isArray(raw)) pending = raw;
  } catch (_) {}
  const now = Date.now();
  for (const p of pending) {
    const secs = typeof p.ts === "number" ? Math.round((now - p.ts) / 1000) : null;
    bump(p.agent, secs, true);
  }
  return {
    trace: cur,
    lane: nameMatch ? nameMatch[1] : null,
    slug: nameMatch ? nameMatch[2] : null,
    agents: [...by.values()],
    in_flight: pending.length,
  };
}

// Foreign dispatches DO carry measured tokens. Same file the spend report reads.
function usageForeignSpend(claudeDir) {
  const f = path.join(claudeDir, "orc", "extra-spend.jsonl");
  let lines = [];
  try {
    lines = fs.readFileSync(f, "utf8").split("\n").filter(Boolean);
  } catch (_) {
    return { rows: [], unreadable: 0 };
  }
  const rows = [];
  let unreadable = 0;
  for (const l of lines) {
    try {
      rows.push(JSON.parse(l));
    } catch (_) {
      unreadable += 1;
    }
  }
  return { rows, unreadable };
}

function usageReportCmd(claudeDir) {
  const asJson = wantsJson();
  const now = Date.now();
  const cfg = resolvedConfig(claudeDir);
  const stopPct = Math.min(50, Math.max(1, Number(cfg.usage_stop_pct) || 10));

  // Read the bridge RAW here rather than through readUsageBridge: a stale
  // reading is still worth SHOWING, with its age, where a gate would rightly
  // discard it. The state word still comes from freshness — age is displayed,
  // never ignored.
  let raw = null;
  try {
    raw = JSON.parse(fs.readFileSync(path.join(claudeDir, "orc", "usage.json"), "utf8"));
  } catch (_) {}
  const ageMin =
    raw && typeof raw.written_at === "number" ? Math.round((now - raw.written_at) / 60000) : null;
  const stale = ageMin == null ? true : now - raw.written_at > WAIT_BRIDGE_MAX_AGE_MS;

  const view = (o, label) => {
    if (!o || typeof o.used_percentage !== "number") return null;
    const used = Math.round(o.used_percentage);
    const at = usageResetMs(o.resets_at);
    return {
      window: label,
      used_percentage: used,
      remaining_percentage: Math.max(0, 100 - used),
      resets_at: Number.isFinite(at) ? new Date(at).toISOString() : null,
      resets_in_minutes: Number.isFinite(at) && at > now ? Math.round((at - now) / 60000) : null,
      low: 100 - used <= stopPct,
    };
  };
  const fh = raw ? view(raw.five_hour, "5h") : null;
  const sd = raw ? view(raw.seven_day, "wk") : null;

  // Session consumption — the ledger the statusline keeps.
  let led = null;
  try {
    led = JSON.parse(fs.readFileSync(path.join(claudeDir, "orc", "usage-session.json"), "utf8"));
  } catch (_) {}
  const consumed = (w) =>
    !w
      ? null
      : {
          baseline_percentage: w.baseline,
          now_percentage: w.last,
          consumed_percentage: Math.max(0, w.accumulated + Math.max(0, w.last - w.baseline)),
          window_resets: w.resets,
        };
  const session = !led
    ? null
    : {
        session_id: led.session_id || null,
        started_at: led.started_at ? new Date(led.started_at).toISOString() : null,
        running_minutes: led.started_at ? Math.round((now - led.started_at) / 60000) : null,
        five_hour: consumed(led.five_hour),
        seven_day: consumed(led.seven_day),
        still_counting: true,
        // Never overclaim. The window is per ACCOUNT: a second Claude Code
        // window, a cloud session, or anyone else on the same key moves it too.
        caveat:
          "this is how far the window moved while this session ran — other sessions on the same account share it",
      };

  const run = usageRunConsumers(claudeDir);
  const foreign = usageForeignSpend(claudeDir);

  // Rank by measured wall time. A row with nothing measured keeps its slot.
  const top = [];
  if (run) {
    const sorted = run.agents.slice().sort((a, b) => b.wall_seconds - a.wall_seconds);
    for (const a of sorted.slice(0, USAGE_TOP_N))
      top.push({
        agent: a.agent,
        dispatches: a.dispatches,
        running: a.running,
        wall_seconds: a.wall_seconds,
        unmeasured_dispatches: a.unmeasured,
        tokens: null,
        tokens_source: "unavailable",
      });
  }
  for (const r of foreign.rows.slice(-USAGE_TOP_N)) {
    top.push({
      agent: "extra:" + (r.profile || "?") + "/" + (r.model || "?"),
      dispatches: 1,
      running: 0,
      wall_seconds: usageDurSeconds(r.dur),
      unmeasured_dispatches: 0,
      tokens: r.usage || null,
      tokens_source: r.usage ? "measured" : "not reported by the worker",
    });
  }

  const windows = [fh, sd].filter(Boolean);
  const state = !windows.length || stale ? "unknown" : windows.some((w) => w.low) ? "low" : "ok";
  const code = state === "low" ? 1 : state === "unknown" ? 2 : 0;
  const out = {
    ok: true,
    state,
    five_hour: fh,
    seven_day: sd,
    context_used_percentage:
      raw && typeof raw.context_used_percentage === "number" ? raw.context_used_percentage : null,
    reading_age_minutes: ageMin,
    reading_stale: stale,
    stop_pct: stopPct,
    gate: String(cfg.usage_gate || "off"),
    session,
    run: run
      ? {
          trace: run.trace,
          lane: run.lane,
          slug: run.slug,
          dispatches: run.agents.reduce((n, a) => n + a.dispatches, 0),
          in_flight: run.in_flight,
          wall_seconds: run.agents.reduce((n, a) => n + a.wall_seconds, 0),
        }
      : null,
    top,
    foreign_spend_rows: foreign.rows.length,
    unreadable_spend_lines: foreign.unreadable,
    // Say it on every emission. A reader who does not know this reads a
    // wall-time ranking as a token ranking.
    tokens_note:
      "Claude Code records no token usage for a dispatched subagent, so a Claude agent's tokens are null and never 0. Rows are ranked by MEASURED WALL TIME. Only `orc extra` foreign workers report real token vectors.",
  };
  if (asJson) emitJson(out, code);

  console.log(ui.header("ORC · usage"));
  console.log("");
  const pctLine = (w) =>
    !w
      ? ui.color.gray("      —  (no reading)")
      : "      " +
        String(w.used_percentage).padStart(3) +
        "% used · " +
        w.remaining_percentage +
        "% left" +
        (w.resets_in_minutes != null ? " · resets in " + w.resets_in_minutes + "m" : "") +
        (w.low ? "  " + ui.color.yellow("LOW") : "");
  console.log("  5 hours");
  console.log(pctLine(fh));
  console.log("  7 days");
  console.log(pctLine(sd));
  if (out.context_used_percentage != null)
    console.log("  context   " + out.context_used_percentage + "% of the window");
  if (stale)
    console.log(
      ui.color.gray(
        "  reading   " +
          (ageMin == null ? "none" : ageMin + "m old") +
          " — treated as unknown, and a run is never stopped on it"
      )
    );
  console.log("");
  if (session && session.five_hour) {
    const c = session.five_hour;
    console.log(
      "  " +
        ui.color.bold(
          "This session has consumed " +
            c.consumed_percentage +
            "% of the 5-hour window and is still counting"
        )
    );
    console.log(
      ui.color.gray(
        "      " +
          c.baseline_percentage +
          "% → " +
          c.now_percentage +
          "%" +
          (c.window_resets ? " across " + c.window_resets + " window reset(s)" : "") +
          (session.running_minutes != null ? " · " + session.running_minutes + "m in session" : "")
      )
    );
    console.log(ui.color.gray("      " + session.caveat));
  } else {
    console.log(ui.color.gray("  session consumption: no reading yet (the statusline writes it)"));
  }
  console.log("");
  if (top.length) {
    console.log("  " + ui.color.bold("Top " + USAGE_TOP_N + " by measured wall time"));
    for (const t of top.slice(0, USAGE_TOP_N)) {
      const secs = t.wall_seconds;
      const w =
        secs == null
          ? "—"
          : Math.floor(secs / 60) + "m" + String(secs % 60).padStart(2, "0") + "s";
      const tok = t.tokens ? "tokens measured" : ui.color.gray("tokens —");
      console.log(
        "      " +
          w.padStart(8) +
          "  " +
          t.agent +
          "  " +
          ui.color.gray("x" + t.dispatches) +
          (t.running ? "  " + ui.color.yellow(t.running + " RUNNING") : "") +
          "  " +
          tok
      );
    }
    console.log(
      ui.color.gray("      wall time, not tokens — Claude Code does not record a subagent's tokens")
    );
  } else {
    console.log(ui.color.gray("  no dispatches in the open run (or no run is open)"));
  }
  process.exit(code);
}

function usageCheckCmd(claudeDir) {
  const asJson = wantsJson();
  const now = Date.now();
  const cfg = resolvedConfig(claudeDir);
  const stopPct = Math.min(50, Math.max(1, Number(cfg.usage_stop_pct) || 10));
  const gate = String(cfg.usage_gate || "off");
  const j = readUsageBridge(claudeDir, now);

  const view = (o, label) => {
    if (!o || typeof o.used_percentage !== "number") return null;
    const used = Math.round(o.used_percentage);
    const at = usageResetMs(o.resets_at);
    const mins = Number.isFinite(at) && at > now ? Math.round((at - now) / 60000) : null;
    return {
      window: label,
      used_percentage: used,
      remaining_percentage: Math.max(0, 100 - used),
      resets_at: Number.isFinite(at) ? new Date(at).toISOString() : null,
      resets_in_minutes: mins,
      low: 100 - used <= stopPct,
    };
  };

  if (!j) {
    const out = {
      ok: true,
      state: "unknown",
      reason: "no reading in the last 30 minutes",
      five_hour: null,
      seven_day: null,
      context: null,
      stop_pct: stopPct,
      gate,
      // Say what unknown MEANS, every time. Silence here is what makes a user
      // believe the gate is watching when it is not.
      note: "unknown is not low — a run is never stopped on a missing reading. Claude Code before v2.1.80 sends no usage headers.",
    };
    if (asJson) emitJson(out, 2);
    console.log(ui.color.gray("usage: unknown (no reading in the last 30 minutes) · a run is never stopped on this"));
    process.exit(2);
  }

  const fh = view(j.five_hour, "5h");
  const sd = view(j.seven_day, "wk");
  const windows = [fh, sd].filter(Boolean);
  if (!windows.length) {
    const out = { ok: true, state: "unknown", reason: "the reading carries no window", stop_pct: stopPct, gate };
    if (asJson) emitJson(out, 2);
    console.log(ui.color.gray("usage: unknown (the reading carries no window)"));
    process.exit(2);
  }

  // THE WORST WINDOW DECIDES. A 7-day window at 96% with a 5-hour window at 20%
  // is not a green light: the run continues and dies twenty minutes later.
  const worst = windows.reduce((a, b) => (a.remaining_percentage <= b.remaining_percentage ? a : b));
  const low = windows.some((w) => w.low);
  const out = {
    ok: true,
    state: low ? "low" : "ok",
    five_hour: fh,
    seven_day: sd,
    worst: worst.window,
    context: typeof j.context_used_percentage === "number" ? j.context_used_percentage : null,
    stop_pct: stopPct,
    gate,
    reading_age_minutes: Math.round((now - j.written_at) / 60000),
    note: "read BEFORE a wave; the wave then spends tokens, so this is a reading and not a promise.",
  };
  if (asJson) emitJson(out, low ? 1 : 0);

  const fmt = (w) =>
    w ? `${w.window} ${w.used_percentage}%${w.resets_in_minutes != null ? ` (${w.resets_in_minutes}m)` : ""}` : null;
  const line = [fmt(fh), fmt(sd)].filter(Boolean).join(" · ");
  console.log((low ? ui.mark.warn("usage: " + line) : ui.color.gray("usage: " + line)) +
    ui.color.gray(` · gate at ${stopPct}% left · ${gate}`));
  process.exit(low ? 1 : 0);
}

// ── the wait's run state (v1.1.0 W2) ────────────────────────────────────────
// ONE file, ONE writer — this CLI. The skill never writes it, so it can never
// be behind the disk: the v0.49.5 hand-back lesson, and the fifth time this
// repo has applied it (v0.32.0 narration · v0.53.2 spend log · v0.54.0 journal
// · v1.0.0 W5 demotion).
//
// It lives BESIDE RESUME.md in {run_dir}/{slug}/, so it is deleted with the run
// and can never outlive the decision it records.
const WAIT_STATE_FILE = "wait.json";

function waitStatePath(claudeDir, slug) {
  return path.join(resolveRunDir(claudeDir), slug, WAIT_STATE_FILE);
}

function readWaitState(claudeDir, slug) {
  try {
    const j = JSON.parse(fs.readFileSync(waitStatePath(claudeDir, slug), "utf8"));
    return j && typeof j === "object" ? j : null;
  } catch (_) {
    return null;
  }
}

function writeWaitState(claudeDir, slug, patch) {
  const file = waitStatePath(claudeDir, slug);
  const cur = readWaitState(claudeDir, slug) || { v: 1, slug };
  const next = { ...cur, ...patch, v: 1, slug };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(next, null, 2) + "\n");
  return next;
}

// The run this command is about. An explicit slug always wins; otherwise the
// trace pointer names the run in flight. NEVER guess from "the newest folder" —
// a wrong run is worse than no run, because the block would silently protect
// something the user is not looking at.
function waitResolveRun(claudeDir, slug) {
  if (slug) {
    const dir = path.join(resolveRunDir(claudeDir), slug);
    return fs.existsSync(dir) ? { slug, dir } : null;
  }
  const cur = extraCurrentRun(claudeDir);
  if (!cur || !cur.slug) return null;
  const dir = path.join(resolveRunDir(claudeDir), cur.slug);
  return fs.existsSync(dir) ? { slug: cur.slug, dir } : null;
}

// CLI-COMPOSED AND CLI-WRITTEN. A wait that leaves no line cannot be counted,
// and a block that leaves no line hides that a run continued through a gate on
// the user's authority. Best effort ALWAYS: a trace that cannot be written must
// never take the command down with it.
function waitTraceLine(claudeDir, verb, tail) {
  try {
    const cur = extraCurrentRun(claudeDir);
    if (!cur || !cur.trace) return null;
    const dir = resolveLogDir(claudeDir);
    const d = new Date();
    const p = (n, w) => String(n).padStart(w || 2, "0");
    const stamp =
      `${p(d.getDate())}${p(d.getMonth() + 1)}${p(d.getFullYear() % 100)} ` +
      `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}.${p(d.getMilliseconds(), 3)}`;
    const line = `[${stamp}] ${"cli".padEnd(8)} ${verb}${tail ? ` :: ${tail}` : ""}\n`;
    fs.appendFileSync(path.join(dir, cur.trace), line);
    return line.trimEnd();
  } catch (_) {
    return null;
  }
}

function waitBlockCmd(claudeDir, unblock) {
  const asJson = wantsJson();
  const slug = positionals()[2];
  const reason = typeof flag("--reason") === "string" ? String(flag("--reason")).trim() : "";
  const run = waitResolveRun(claudeDir, slug);

  if (!run) {
    const hint = slug
      ? `no run named "${slug}" under ${resolveRunDir(claudeDir)}`
      : "no run is in flight, and no slug was given";
    if (asJson) emitJson({ ok: false, reason: "no-run", slug: slug || null, hint }, 2);
    console.error(ui.mark.err("I cannot find the run this is about."));
    console.error("  " + hint + ".");
    process.exit(2);
  }

  if (unblock) {
    const cur = readWaitState(claudeDir, run.slug);
    if (!cur || !cur.blocked_at) {
      if (asJson) emitJson({ ok: false, reason: "not-blocked", slug: run.slug }, 1);
      console.error(ui.mark.warn(`${run.slug} is not blocked.`));
      process.exit(1);
    }
    const st = writeWaitState(claudeDir, run.slug, {
      blocked_at: null,
      block_reason: null,
      unblocked_at: new Date().toISOString(),
    });
    const trace = waitTraceLine(claudeDir, "WAIT", "unblock");
    if (asJson) emitJson({ ok: true, slug: run.slug, blocked: false, trace_line: trace }, 0);
    console.log(ui.mark.ok(`${run.slug}: the gate is live again.`));
    return;
  }

  // THE REASON IS REQUIRED. A recorded reason is what makes the risk
  // demonstrably the user's — the same rule the run-close and doc-ship writers
  // already follow. Refuse BY NAME rather than storing an empty string.
  if (!reason) {
    if (asJson)
      emitJson(
        {
          ok: false,
          reason: "no-reason",
          slug: run.slug,
          hint: 'a block records why you accepted the risk. Pass --reason "<why>".',
        },
        1
      );
    console.error(ui.mark.err("A block needs a reason."));
    console.error('  orc wait block ' + run.slug + ' --reason "window resets in 5m, task needs 10"');
    process.exit(1);
  }

  const st = writeWaitState(claudeDir, run.slug, {
    blocked_at: new Date().toISOString(),
    block_reason: reason,
    unblocked_at: null,
  });
  const trace = waitTraceLine(claudeDir, "WAIT", `block reason="${reason}" by=user`);
  if (asJson)
    emitJson(
      { ok: true, slug: run.slug, blocked: true, blocked_at: st.blocked_at, reason, trace_line: trace },
      0
    );
  console.log(ui.mark.warn(`${run.slug}: computed waits are blocked for the rest of this run.`));
  console.log("  reason  " + reason);
  console.log(
    ui.color.gray(
      "  The risk is yours: if the window empties mid-wave, the wave stops in the\n" +
        "  middle. A typed `/orc-wait` still waits. `orc wait unblock` restores the gate."
    )
  );
}

function waitCancelCmd(claudeDir) {
  const asJson = wantsJson();
  const run = waitResolveRun(claudeDir, positionals()[2]);
  if (!run) {
    if (asJson) emitJson({ ok: false, reason: "no-run", hint: "no run is in flight" }, 1);
    console.error(ui.mark.warn("No run is in flight, so there is no wait to cancel."));
    process.exit(1);
  }
  const cur = readWaitState(claudeDir, run.slug);
  if (!cur || !cur.wait_started_at || cur.wait_ended_at) {
    if (asJson) emitJson({ ok: false, reason: "no-wait", slug: run.slug }, 1);
    console.error(ui.mark.warn(`${run.slug} has no wait running.`));
    process.exit(1);
  }
  writeWaitState(claudeDir, run.slug, { cancel_requested_at: new Date().toISOString() });
  if (asJson) emitJson({ ok: true, slug: run.slug, cancelled: true }, 0);
  console.log(ui.mark.ok(`${run.slug}: the wait stops at the next hop.`));
  console.log(ui.color.gray("  The hand-back is already on disk, so nothing is lost either way."));
}

function waitStatusCmd(claudeDir) {
  const asJson = wantsJson();
  const run = waitResolveRun(claudeDir, positionals()[2]);
  if (!run) {
    // An empty result is an ANSWER, so it still returns its object.
    if (asJson)
      emitJson({ ok: true, run: null, waiting: false, blocked: false, note: "no run is in flight" }, 1);
    console.log(ui.color.gray("No run is in flight."));
    process.exit(1);
  }
  const st = readWaitState(claudeDir, run.slug) || {};
  const blocked = !!st.blocked_at;
  const waiting = !!st.wait_started_at && !st.wait_ended_at;
  const ageMin = blocked ? Math.round((Date.now() - Date.parse(st.blocked_at)) / 60000) : null;
  const out = {
    ok: true,
    run: run.slug,
    waiting,
    mode: st.mode || null,
    hop: st.hop || null,
    hops_done: st.hops_done || 0,
    hops_planned: st.hops_planned || null,
    ends_at: st.ends_at || null,
    cancel_requested: !!st.cancel_requested_at,
    blocked,
    block_reason: blocked ? st.block_reason : null,
    blocked_at: st.blocked_at || null,
    // The AGE is what keeps an old block from applying invisibly — there is no
    // auto-expiry, because ORC does not decide a user's reason stopped being true.
    block_age_minutes: ageMin,
  };
  if (asJson) emitJson(out, 0);

  console.log(ui.header("ORC · wait — " + run.slug));
  console.log("");
  console.log(
    `  ${ui.color.cyan("wait")}      ` +
      (waiting
        ? `${st.mode || "?"} · hop ${out.hops_done} of ${out.hops_planned || "?"} · ends ${out.ends_at || "?"}`
        : ui.color.gray("none"))
  );
  console.log(
    `  ${ui.color.cyan("block")}     ` +
      (blocked ? ui.mark.warn(`${ageMin}m ago — "${st.block_reason}"`) : ui.color.gray("not blocked"))
  );
  if (out.cancel_requested) console.log(ui.color.gray("  a cancel is pending — the wait ends at the next hop"));
  console.log("");
}

function waitCmd() {
  const claudeDir = resolveClaudeDir();
  const sub = positionals()[1];
  switch (sub) {
    case "lanes":
      return waitLanesCmd();
    case "plan":
      return waitPlanCmd(claudeDir);
    case "status":
      return waitStatusCmd(claudeDir);
    case "block":
      return waitBlockCmd(claudeDir, false);
    case "unblock":
      return waitBlockCmd(claudeDir, true);
    case "cancel":
      return waitCancelCmd(claudeDir);
    default:
      console.error(`usage: orc wait lanes [--json]
       orc wait plan <30|90m|2h|until 18:41|reset> [--hop <min>] [--max-hops <n>] [--json]
       orc wait status [<slug>] [--json]
       orc wait block <slug> --reason "<why>" [--json]
       orc wait unblock [<slug>] [--json]
       orc wait cancel [<slug>] [--json]`);
      process.exit(1);
  }
}

// ── the `--json` crash envelope (v0.49.2) ───────────────────────────────────
// A read asked for JSON must answer in JSON or not at all. Before this, an
// unexpected throw inside any `--json` route printed a Node stack to stderr and
// NOTHING parseable to stdout, so `orc ui` had a bare 500 with no reason in it —
// which is exactly what the user saw when one corrupt challenge ledger crashed
// the panel. This is the general fix: every `--json` route inherits it, and the
// human path is untouched (a stack is the right answer at a terminal).
function jsonCrash(err) {
  const msg = String((err && err.stack) || err || "unknown error");
  emitJson(
    {
      ok: false,
      reason: "crashed",
      command: [cmd, ...args.slice(1)].filter(Boolean).join(" "),
      error: msg.split("\n")[0],
      stack: msg,
      hint: "this is a bug in orc — the command threw before it could answer. Re-run without --json to see the full stack.",
    },
    70
  );
}

(async () => {
  switch (cmd) {
    case "init":
      install({ overwrite: false });
      await maybeNudge();
      break;
    case "update":
      install({ overwrite: true });
      await maybeNudge();
      break;
    case "upgrade":
      upgrade(); // already fetching the latest — no nudge
      break;
    case "config":
      config();
      break;
    // v1.0.0 W3 — ONE resolver per lane, so a spine never re-derives a
    // precedence the CLI already computed.
    case "lane":
      lane();
      break;
    case "diy":
      diy();
      break;
    case "crosslink":
      crosslink();
      break;
    case "wiki":
      wiki();
      break;
    case "pattern":
      pattern();
      break;
    case "gotcha":
      gotcha();
      break;
    case "mock":
      mock();
      break;
    // Package content, not project state — hence a separate command from `mock`
    // above, which reads mock-examples/ inside the user's repo.
    case "mock-run":
    case "mockrun":
      mockRun();
      break;
    // v0.46.0 — the six new lanes' deterministic halves. Every one is a READ
    // with an exit-code contract (plus the two sanctioned writes: `pact check`
    // re-anchors what passes, `handoff set` edits one graded surface).
    case "pact":
      pact();
      break;
    case "boundary":
      boundary();
      break;
    case "handoff":
      handoff();
      break;
    case "budget":
      budget();
      break;
    case "aftermath":
      aftermath();
      break;
    case "export":
      exportCmd();
      break;
    // v0.47.0 — the lane that refuses to produce. Every subcommand is a READ
    // with an exit-code contract except `init`, `record`, `accept`, `rebut`,
    // `template`, `goals` and `report`, which are the ledger's only writers.
    case "challenge":
      challenge();
      break;
    // v0.48.0 — the lane that writes the long document. Every subcommand is a
    // READ with an exit-code contract except `init`, `outline --set`, `extract`,
    // `splice` and `assemble`, which are doc.json's only writers.
    case "doc":
      doc();
      break;
    // v0.50.0 — dispatch ORC's workers to non-Claude agents. Every subcommand
    // is a READ with an exit-code contract except `add`, `remove` and the
    // route writers, which are extra.json's only writers.
    case "extra":
      await extra();
      break;
    // v1.1.0 W1 — the deterministic half of `/orc-wait`. The skill asks; it
    // never computes hops or the lane table itself.
    case "wait":
      waitCmd();
      break;
    // v1.1.0 W4 — the ONE reader of the statusline's usage bridge.
    case "usage":
      if (positionals()[1] === "check") usageCheckCmd(resolveClaudeDir());
      else if (positionals()[1] === "report") usageReportCmd(resolveClaudeDir());
      else {
        console.error("usage: orc usage check|report [--json]");
        process.exit(1);
      }
      break;
    case "ui":
      uiCmd();
      break;
    case "pr":
    case "pr-stack-template":
    case "pr-stack-status":
      pr(cmd);
      break;
    case "resume":
      resume();
      break;
    case "run":
      runCmd();
      break;
    case "stats":
      stats();
      break;
    case "where":
      where();
      await maybeNudge();
      break;
    case "onboarding":
      onboarding();
      break;
    case "doctor":
      doctor();
      break;
    case "version":
    case "--version":
    case "-v":
      await version();
      break;
    case "changelog":
      await changelog();
      break;
    case "--help":
    case "-h":
    case "help":
    case undefined:
      help();
      await maybeNudge();
      break;
    default:
      console.error(`Unknown command: ${cmd}\n`);
      help();
      process.exit(1);
  }
})().catch((err) => {
  if (wantsJson()) jsonCrash(err);
  throw err;
});
